CREATE TABLE public.ablage_bereiche (
  bereich text NOT NULL,
  name text NOT NULL,
  server_ordner text NOT NULL,
  extern_ordner text
);

CREATE TABLE public.ablage_einstellung (
  id smallint DEFAULT 1 NOT NULL,
  art text DEFAULT 'server'::text NOT NULL,
  name text DEFAULT 'Server'::text NOT NULL,
  adresse text,
  geaendert_am timestamp with time zone DEFAULT now() NOT NULL,
  benutzer text,
  credential_id text,
  geprueft_am timestamp with time zone,
  geaendert_von text,
  verbunden_am timestamp with time zone
);

CREATE TABLE public.ally_app_symbol (
  id smallint DEFAULT 1 NOT NULL,
  png bytea NOT NULL,
  breite integer NOT NULL,
  hoehe integer NOT NULL,
  groesse integer NOT NULL,
  pruefsumme text NOT NULL,
  geaendert_von text,
  geaendert_am timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.ally_assistent_verlauf (
  id bigint DEFAULT nextval('ally_assistent_verlauf_id_seq'::regclass) NOT NULL,
  person text NOT NULL,
  event_id text NOT NULL,
  frage text NOT NULL,
  antwort text,
  erstellt_am timestamp with time zone DEFAULT now() NOT NULL,
  beantwortet_am timestamp with time zone
);

CREATE TABLE public.ally_benachrichtigung_arten (
  schluessel text NOT NULL,
  name text NOT NULL,
  beschreibung text DEFAULT ''::text NOT NULL,
  seite text,
  standard_glocke boolean DEFAULT true NOT NULL,
  sortierung integer DEFAULT 100 NOT NULL
);

CREATE TABLE public.ally_benachrichtigung_schalter (
  person text NOT NULL,
  art text NOT NULL,
  glocke boolean NOT NULL,
  geaendert_am timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.ally_benachrichtigungen (
  id bigint DEFAULT nextval('ally_benachrichtigungen_id_seq'::regclass) NOT NULL,
  person text,
  talent_id integer,
  art text NOT NULL,
  titel text NOT NULL,
  text text DEFAULT ''::text NOT NULL,
  ziel jsonb,
  ref text,
  quelle text,
  chat boolean DEFAULT false NOT NULL,
  erstellt_am timestamp with time zone DEFAULT now() NOT NULL,
  gelesen_am timestamp with time zone
);

CREATE TABLE public.ally_cd (
  unternehmen_id integer NOT NULL,
  schrift text NOT NULL,
  farbe_dunkel text NOT NULL,
  farbe_text_auf_dunkel text NOT NULL,
  farbe_akzent text NOT NULL,
  farbe_akzent_dunkel text NOT NULL,
  farbe_hell text NOT NULL,
  farbe_grau text NOT NULL,
  farbe_warnung text NOT NULL,
  geaendert_am timestamp with time zone DEFAULT now() NOT NULL,
  stile text[] DEFAULT ARRAY['dunkel'::text, 'hell'::text, 'akzent'::text] NOT NULL,
  deko_punkte boolean DEFAULT true NOT NULL,
  deko_boegen boolean DEFAULT true NOT NULL,
  deko_icon boolean DEFAULT true NOT NULL,
  icons_an boolean DEFAULT true NOT NULL,
  icons_aus text[] DEFAULT '{}'::text[] NOT NULL
);

CREATE TABLE public.ally_cd_dateien (
