CREATE OR REPLACE FUNCTION public.ablage_adresse_fehler(p_adresse text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  m text[];
  host text;
  port int;
BEGIN
  m := regexp_match(coalesce(p_adresse, ''), '^(https?)://([a-z0-9.-]+)(?::([0-9]{1,5}))?$');
  IF m IS NULL THEN
    RETURN 'Die Adresse muss so aussehen: https://name.de oder https://name.de:5006 (ohne Ordner dahinter).';
  END IF;
  host := m[2];
  port := coalesce(m[3]::int, 0);
  IF port > 65535 THEN
    RETURN 'Die Portnummer in der Adresse ist ungültig.';
  END IF;
  IF adresse_gesperrt(host) THEN
    RETURN 'Diese Adresse ist nicht erlaubt.';
  END IF;
  IF m[1] = 'http' AND host !~ '^(10\.[0-9]+\.[0-9]+\.[0-9]+|192\.168\.[0-9]+\.[0-9]+)$' THEN
    RETURN 'Außerhalb des eigenen Netzes nur mit https. Sonst ginge das Passwort unverschlüsselt durchs Internet.';
  END IF;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.ablage_ordner_fehler(p_ordner text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN coalesce(p_ordner, '') = '' THEN 'Bitte einen Ordner angeben.'
    WHEN length(p_ordner) > 500 THEN 'Der Ordnerpfad ist zu lang.'
    WHEN p_ordner !~ '^/' THEN 'Der Ordner muss mit / beginnen, zum Beispiel /Dokumente.'
    WHEN p_ordner ~ '[[:cntrl:]\\*?{}]' OR p_ordner ~ '(^|/)\.\.?(/|$)' OR p_ordner ~ '//' THEN 'Der Ordnerpfad ist ungültig.'
  END
$function$
;

CREATE OR REPLACE FUNCTION public.ablage_web_abschliessen(p_token text, p_aktion text, p_vorher jsonb, p_api jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  v jsonb := coalesce(p_vorher, '{}'::jsonb);
  api jsonb := coalesce(p_api, '{}'::jsonb);
  m text;
  ok boolean := false;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen OR NOT ally_hat_recht(s.matrix_user_id, 'admin') OR NOT plattform_modul_an('speicherort') OR (v->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  IF p_aktion = 'server' THEN
    UPDATE ablage_einstellung SET art = 'server', geaendert_am = now(), geaendert_von = s.matrix_user_id WHERE id = 1;
    ok := true;
    m := 'Neue Dateien legt ' || produkt_name() || ' ab jetzt auf dem Server ab. Vorhandene Dateien bleiben am bisherigen Speicherort.';
  ELSIF p_aktion = 'speichern' THEN
    IF (api->>'pruefung_ok') IS DISTINCT FROM 'true' THEN
      m := coalesce(nullif(api->>'pruefung_text', ''), 'Die Prüfung ist fehlgeschlagen.') || ' Es wurde nichts geändert.';
    -- Ohne neues Passwort (pw_gespeichert) werden die Zugangsdaten nicht neu gesetzt (17.10.2026)
    ELSIF (api->>'patch_status') IS DISTINCT FROM '200' AND (v->>'pw_gespeichert') IS DISTINCT FROM 'true' THEN
      m := 'Die Prüfung war erfolgreich, aber die Zugangsdaten konnten nicht gespeichert werden (' || coalesce(nullif(api->>'patch_meldung', ''), 'Status ' || coalesce(api->>'patch_status', 'unbekannt')) || '). Es wurde nichts geändert.';
    ELSE
      UPDATE ablage_einstellung SET art = 'webdav', name = v->>'name', adresse = v->>'adresse', benutzer = v->>'benutzer',
        geprueft_am = now(), geaendert_am = now(), geaendert_von = s.matrix_user_id, verbunden_am = now() WHERE id = 1;
      UPDATE ablage_bereiche b SET extern_ordner = o->>'ordner'
        FROM jsonb_array_elements(coalesce(v->'ordner', '[]'::jsonb)) o WHERE b.bereich = o->>'bereich';
      ok := true;
      m := 'Speicherort „' || (v->>'name') || '“ gespeichert. Lesen, Schreiben und Löschen haben geklappt. Neue Dateien legt ' || produkt_name() || ' ab jetzt dort ab. Vorhandene Dateien bleiben am bisherigen Ort.'
        || CASE WHEN (v->'ordner'->1->>'pruefen') = 'true' THEN ' Verbuchte Belege kommen in ' || (v->'ordner'->1->>'ordner') || '.' ELSE '' END
        || CASE WHEN (api->>'rest') = 'true' THEN ' Hinweis: Eine Prüfdatei (.ally-pruefung) konnte nicht entfernt werden, du kannst sie löschen.' ELSE '' END;
    END IF;
  ELSIF p_aktion = 'verbinden' THEN
    -- Migration 89: Schritt 1 abgeschlossen – nur Verbindung gemerkt, art bleibt (Server); umgestellt wird erst mit dem gewählten Ordner („speichern“)
    IF (api->>'anmeldung_ok') IS DISTINCT FROM 'true' THEN
      m := coalesce(nullif(api->>'anmeldung_text', ''), 'Die Verbindung ließ sich nicht prüfen.') || ' Es wurde nichts geändert.';
    ELSIF (api->>'patch_status') IS DISTINCT FROM '200' THEN
      m := 'Die Anmeldung hat geklappt, aber die Zugangsdaten konnten nicht gespeichert werden (' || coalesce(nullif(api->>'patch_meldung', ''), 'Status ' || coalesce(api->>'patch_status', 'unbekannt')) || '). Es wurde nichts geändert.';
    ELSE
      UPDATE ablage_einstellung SET name = v->>'name', adresse = v->>'adresse', benutzer = v->>'benutzer', verbunden_am = now(), geaendert_am = now(), geaendert_von = s.matrix_user_id
      WHERE id = 1 AND art IS DISTINCT FROM 'webdav';
      ok := true;
      m := 'Verbindung zu „' || (v->>'name') || '“ steht. Wähle jetzt den Ordner für die Dateien von ' || produkt_name() || '. Bis dahin landen neue Dateien weiter auf dem Server.';
    END IF;
  ELSIF p_aktion = 'belege_ordner' THEN
    IF (api->>'ablegen_ok') = 'true' THEN
      ok := true;
      m := 'Ordner für verbuchte Belege gespeichert: ' || (v->>'ordner_belege') || '. ' || produkt_name() || ' hat ihn mit einer Prüfdatei geprüft.'
        || CASE WHEN (api->>'rest') = 'true' THEN ' Hinweis: Die Prüfdatei (.ally-pruefung) konnte nicht entfernt werden, du kannst sie löschen.' ELSE '' END;
    ELSE
      UPDATE ablage_bereiche SET extern_ordner = v->>'alt' WHERE bereich = 'buchhaltung';
      m := 'Der Ordner ' || (v->>'ordner_belege') || ' ließ sich nicht nutzen (' || coalesce(nullif(rtrim(api->>'fehler', '.'), ''), 'keine Antwort') || '). Es bleibt beim bisherigen Ordner.';
    END IF;
  ELSE
    m := 'Unbekannte Aktion.';
  END IF;
  UPDATE ally_web_sitzungen SET flash = m, flash_art = CASE WHEN ok THEN 'ok' ELSE 'fehler' END WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', ok, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ablage_web_seite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  e record;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN NULL;
  END IF;
  SELECT * INTO e FROM ablage_einstellung WHERE id = 1;
  RETURN jsonb_build_object(
    'gebucht', plattform_modul_an('speicherort'),
    'darf', ally_hat_recht(s.matrix_user_id, 'admin'),
    'aktiv', (ablage_ziel()->>'art') = 'webdav',
    'art', coalesce(e.art, 'server'),
    'name', e.name,
    'adresse', e.adresse,
    'benutzer', e.benutzer,
    'geprueft_am', to_char(e.geprueft_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI'),
    'geaendert_am', to_char(e.geaendert_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI'),
    'zugang_da', e.credential_id IS NOT NULL,
    -- Migration 89: Verbindung geprüft (Schritt 1) bzw. eigener Speicherort in Betrieb; nur dann zeigt der Ordner-Browser den Speicher
    'verbunden', coalesce(e.credential_id IS NOT NULL AND e.adresse IS NOT NULL AND (e.art = 'webdav' OR e.verbunden_am IS NOT NULL), false),
    'verbunden_am', to_char(e.verbunden_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI'),
    'belege', plattform_modul_an('belege'),
    'ordner_ally', (SELECT extern_ordner FROM ablage_bereiche WHERE bereich = 'ally'),
    'ordner_buchhaltung', (SELECT extern_ordner FROM ablage_bereiche WHERE bereich = 'buchhaltung'),
    'buchhaltung_standard', (SELECT extern_ordner FROM ablage_bereiche WHERE bereich = 'ally') || '/Buchhaltung',
    'offene_belege', (SELECT count(*) FROM beleg_verarbeitung WHERE processing_status IN ('neu', 'klaerung_offen')),
    'offene_themen', (SELECT count(*) FROM marketing_themen WHERE status IN ('in_arbeit', 'entwurf')));
END $function$
;

CREATE OR REPLACE FUNCTION public.ablage_web_vorbereiten(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  e record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  adresse text := lower(btrim(coalesce(d->>'adresse', ''), ' /'));
  name text := btrim(coalesce(d->>'name', ''));
  benutzer text := btrim(coalesce(d->>'benutzer', ''));
  o_ally text := rtrim(btrim(coalesce(d->>'ordner', '')), '/');
  o_beleg text := rtrim(btrim(coalesce(d->>'ordner_belege', '')), '/');
  belege boolean := plattform_modul_an('belege');
  akt_ally text := (SELECT extern_ordner FROM ablage_bereiche WHERE bereich = 'ally');
  akt_buch text := (SELECT extern_ordner FROM ablage_bereiche WHERE bereich = 'buchhaltung');
  buch jsonb;
  fehler text;
  -- Leeres Passwort (17.10.2026): gespeichertes Passwort nutzen, wenn der Benutzer gleich bleibt (nur wenn ALLY 11 pw_gespeichert schickt)
  pw_leer boolean := coalesce((d->>'passwort_laenge')::int, 0) = 0;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  SELECT * INTO e FROM ablage_einstellung WHERE id = 1;
  IF NOT plattform_modul_an('speicherort') THEN
    fehler := 'Das Paket Eigener Speicherort ist nicht gebucht.';
  ELSIF NOT ally_hat_recht(s.matrix_user_id, 'admin') THEN
    fehler := 'Den Speicherort richten Admins ein.';
  ELSIF p_aktion = 'server' THEN
    IF coalesce(e.art, 'server') = 'server' THEN
      fehler := 'Die Dateien liegen schon auf dem Server.';
    END IF;
  ELSIF p_aktion = 'belege_ordner' THEN
    IF NOT belege THEN
      fehler := 'Das Paket Belege ist nicht gebucht.';
    ELSIF coalesce(e.art, 'server') <> 'webdav' THEN
      fehler := 'Die Belege liegen auf dem Server. Einen eigenen Ordner gibt es nur mit eigenem Speicherort.';
    ELSE
      fehler := coalesce('Ordner: ' || ablage_ordner_fehler(o_beleg),
        CASE WHEN o_beleg = akt_ally THEN 'Bitte einen anderen Ordner als den ' || produkt_name() || '-Ordner wählen.' END);
    END IF;
  ELSIF p_aktion = 'verbinden' THEN
    -- Migration 89 (Stefan 22.10.2026, Regel „Speicherorte und Ordner nie als Freitext“): Schritt 1 „Verbindung prüfen“ (ALLY 11 meldet sich nur an, setzt die Zugangsdaten
    -- und merkt name/adresse/benutzer), Schritt 2 Ordner im Ordner-Browser wählen, erst dann wird umgestellt („speichern“). Nie, solange der eigene Speicherort genutzt
    -- wird: dieselben Zugangsdaten nutzt der laufende Speicherort.
    IF coalesce(e.art, 'server') = 'webdav' THEN
      fehler := 'Solange neue Dateien im eigenen Speicherort landen, lässt sich keine andere Verbindung einrichten. Dafür zuerst „Wieder auf dem Server ablegen“ wählen.';
    ELSIF e.credential_id IS NULL THEN
      fehler := 'Für den Speicherort sind in n8n keine Zugangsdaten eingerichtet. Bitte die ' || produkt_name() || '-Betreuung fragen.';
    ELSIF name = '' OR length(name) > 60 THEN
      fehler := 'Bitte eine Bezeichnung mit höchstens 60 Zeichen angeben, zum Beispiel NAS.';
    ELSE
      fehler := coalesce(ablage_adresse_fehler(adresse),
        CASE WHEN benutzer = '' OR length(benutzer) > 200 OR benutzer ~ '[[:cntrl:]:]' THEN 'Bitte den Anmeldenamen angeben (ohne Doppelpunkt).' END,
        CASE WHEN pw_leer THEN 'Bitte das Passwort angeben.' WHEN (d->>'passwort_laenge')::int > 500 THEN 'Das Passwort ist zu lang.' END);
    END IF;
  ELSIF p_aktion <> 'speichern' THEN
    fehler := 'Unbekannte Aktion.';
  ELSIF e.credential_id IS NULL THEN
    fehler := 'Für den Speicherort sind in n8n keine Zugangsdaten eingerichtet. Bitte die ' || produkt_name() || '-Betreuung fragen.';
  ELSIF name = '' OR length(name) > 60 THEN
    fehler := 'Bitte eine Bezeichnung mit höchstens 60 Zeichen angeben, zum Beispiel NAS.';
  ELSE
    fehler := coalesce(ablage_adresse_fehler(adresse),
      CASE WHEN benutzer = '' OR length(benutzer) > 200 OR benutzer ~ '[[:cntrl:]:]' THEN 'Bitte den Anmeldenamen angeben (ohne Doppelpunkt).' END,
      CASE WHEN pw_leer THEN
          CASE WHEN d->>'pw_gespeichert' = '1' AND e.benutzer IS NOT NULL AND e.benutzer = benutzer AND e.adresse IS NOT NULL AND e.adresse = adresse THEN NULL
               WHEN d->>'pw_gespeichert' = '1' AND e.benutzer IS NOT NULL THEN 'Bitte das Passwort angeben. Für eine andere Adresse oder einen anderen Anmeldenamen braucht ' || produkt_name() || ' ein neues Passwort.'
               ELSE 'Bitte das Passwort angeben.' END
        WHEN (d->>'passwort_laenge')::int > 500 THEN 'Das Passwort ist zu lang.' END,
      'Ordner: ' || ablage_ordner_fehler(o_ally));
  END IF;
  IF fehler IS NOT NULL THEN
    UPDATE ally_web_sitzungen SET flash = fehler, flash_art = 'fehler' WHERE token_hash = s.token_hash;
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', fehler);
  END IF;
  IF p_aktion = 'belege_ordner' THEN
    UPDATE ablage_bereiche SET extern_ordner = o_beleg WHERE bereich = 'buchhaltung';
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'aktion', p_aktion, 'ordner_belege', o_beleg, 'alt', akt_buch);
  END IF;
  IF p_aktion = 'speichern' THEN
    -- Eigener Belege-Ordner bleibt nur bei gleicher Adresse; sonst Unterordner "Buchhaltung" im Ally-Ordner (wird angelegt, wenn Belege gebucht sind)
    buch := CASE WHEN e.art = 'webdav' AND e.adresse = adresse AND akt_buch IS NOT NULL AND akt_buch IS DISTINCT FROM akt_ally || '/Buchhaltung'
      THEN jsonb_build_object('bereich', 'buchhaltung', 'name', 'Belege', 'ordner', akt_buch, 'anlegen', false, 'pruefen', belege)
      ELSE jsonb_build_object('bereich', 'buchhaltung', 'name', 'Belege', 'ordner', o_ally || '/Buchhaltung', 'anlegen', belege, 'pruefen', belege) END;
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'aktion', p_aktion, 'credential_id', e.credential_id,
    'name', name, 'adresse', adresse, 'benutzer', benutzer, 'pw_gespeichert', p_aktion = 'speichern' AND pw_leer,
    'ordner', CASE WHEN p_aktion = 'speichern' THEN
      jsonb_build_array(jsonb_build_object('bereich', 'ally', 'name', '' || produkt_name() || '', 'ordner', o_ally, 'anlegen', false, 'pruefen', true), buch) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ablage_ziel()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object(
    'art', CASE WHEN extern THEN 'webdav' ELSE 'server' END,
    'name', CASE WHEN extern THEN e.name ELSE 'Server' END,
    'adresse', CASE WHEN extern THEN e.adresse END,
    'bereiche', coalesce((SELECT jsonb_object_agg(b.bereich, jsonb_build_object('name', b.name, 'server', b.server_ordner, 'extern', b.extern_ordner)) FROM ablage_bereiche b), '{}'::jsonb))
  FROM (SELECT 1) x
  LEFT JOIN ablage_einstellung e ON e.id = 1
  CROSS JOIN LATERAL (SELECT coalesce(e.art = 'webdav' AND e.adresse IS NOT NULL AND plattform_modul_an('speicherort'), false) AS extern) y
$function$
;

CREATE OR REPLACE FUNCTION public.adresse_gesperrt(p_host text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
-- Host, den Ally nicht ansprechen darf: der eigene Server (localhost, Docker-Netz, Hostinger-Adressen),
-- Namen ohne Punkt (Docker-Dienste) und IP-Adressen in Sonderschreibweise (Stefan 17.10.2026)
DECLARE
  h text := lower(btrim(coalesce(p_host, ''), ' .'));
  letzte text;
  o int[];
BEGIN
  IF h = '' OR h !~ '\.' OR h = 'localhost' OR h ~ '\.(localhost|internal|local|arpa)$' OR h ~ '(^|\.)hstgr\.cloud$' THEN
    RETURN true;
  END IF;
  letzte := regexp_replace(h, '^.*\.', '');
  IF letzte ~ '^(0x[0-9a-f]*|[0-9]+)$' THEN
    -- sieht aus wie eine IP-Adresse: nur die übliche Schreibweise a.b.c.d (ohne führende Nullen) ist erlaubt
    IF h !~ '^(0|[1-9][0-9]{0,2})(\.(0|[1-9][0-9]{0,2})){3}$' THEN
      RETURN true;
    END IF;
    o := string_to_array(h, '.')::int[];
    IF o[1] > 255 OR o[2] > 255 OR o[3] > 255 OR o[4] > 255 THEN RETURN true; END IF;
    IF o[1] IN (0, 127) OR o[1] >= 224 OR (o[1] = 169 AND o[2] = 254) OR (o[1] = 172 AND o[2] BETWEEN 16 AND 31) THEN
      RETURN true;
    END IF;
  END IF;
  RETURN false;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_aktualisieren_schutz()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Migration 188: „Updates einspielen“ haben fest nur Admin und Superadmin (wie ally_rechte_schutz: Abbruch mit check_violation).
  IF NEW.recht COLLATE "C" = 'ally_aktualisieren' THEN
    RAISE EXCEPTION USING ERRCODE = 'check_violation',
      MESSAGE = 'Das Recht „Updates einspielen“ haben fest nur Admin und Superadmin. Es lässt sich nicht an Rollen oder Personen vergeben.';
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_app_symbol_info()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Angaben zum App-Symbol für Einstellungen › Unternehmen und Design (ALLY 23; Stefan 20.10.2026, Migration 60, BA4b), ohne die Bilddaten.
  SELECT coalesce((SELECT jsonb_build_object('eigen', true, 'breite', a.breite, 'hoehe', a.hoehe, 'groesse', a.groesse,
      'am', to_char(a.geaendert_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI')) FROM ally_app_symbol a WHERE a.id = 1),
    jsonb_build_object('eigen', false))
$function$
;

CREATE OR REPLACE FUNCTION public.ally_app_symbol_pruefen(p_png bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  n integer := coalesce(length(p_png), 0);
  pos integer := 8;
  len bigint;
  typ text;
  b bigint := NULL; h bigint := NULL; ft integer := NULL;
  k integer := 0;
BEGIN
  -- Prüft ein hochgeladenes App-Symbol (Stefan 20.10.2026, Migration 60, BA4b): PNG, höchstens 2 MB, quadratisch, 512 bis 4096 Pixel,
  -- ohne Transparenz (Farbtyp Grau, RGB oder Palette, kein tRNS-Block). Liest nur die Blöcke bis zu den Bilddaten.
  IF n = 0 THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Bitte eine PNG-Datei wählen.'); END IF;
  IF n > 2097152 THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Die Datei ist größer als 2 MB.'); END IF;
  IF n < 45 OR substring(p_png FROM 1 FOR 8) <> '\x89504e470d0a1a0a'::bytea THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das ist keine PNG-Datei. Bitte ein Bild im Format PNG wählen.');
  END IF;
  LOOP
    k := k + 1;
    IF k > 10000 OR pos + 12 > n THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Die PNG-Datei ist unvollständig oder beschädigt.'); END IF;
    len := (get_byte(p_png, pos)::bigint << 24) + (get_byte(p_png, pos + 1) << 16) + (get_byte(p_png, pos + 2) << 8) + get_byte(p_png, pos + 3);
    typ := encode(substring(p_png FROM pos + 5 FOR 4), 'hex');
    IF pos + 12 + len > n THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Die PNG-Datei ist unvollständig oder beschädigt.'); END IF;
    IF k = 1 AND (typ <> '49484452' OR len <> 13) THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Die PNG-Datei ist unvollständig oder beschädigt.'); END IF;
    IF typ = '49484452' THEN
      b := (get_byte(p_png, pos + 8)::bigint << 24) + (get_byte(p_png, pos + 9) << 16) + (get_byte(p_png, pos + 10) << 8) + get_byte(p_png, pos + 11);
      h := (get_byte(p_png, pos + 12)::bigint << 24) + (get_byte(p_png, pos + 13) << 16) + (get_byte(p_png, pos + 14) << 8) + get_byte(p_png, pos + 15);
      ft := get_byte(p_png, pos + 17);
    ELSIF typ = '74524e53' THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Das Bild enthält Transparenz. Bitte ein PNG ohne transparente Flächen wählen.');
    ELSIF typ = '49444154' THEN
      EXIT;
    ELSIF typ = '49454e44' THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Die PNG-Datei ist unvollständig oder beschädigt.');
    END IF;
    pos := pos + 12 + len::integer;
  END LOOP;
  IF ft IN (4, 6) THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Das Bild enthält Transparenz. Bitte ein PNG ohne transparente Flächen wählen.'); END IF;
  IF ft IS NULL OR ft NOT IN (0, 2, 3) THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Die PNG-Datei ist unvollständig oder beschädigt.'); END IF;
  IF b <> h THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Symbol muss quadratisch sein (dieses Bild hat ' || b || ' × ' || h || ' Pixel).');
  END IF;
  IF b < 512 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Symbol muss mindestens 512 × 512 Pixel groß sein (dieses Bild hat ' || b || ' × ' || h || ' Pixel).');
  END IF;
  IF b > 4096 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Symbol darf höchstens 4096 × 4096 Pixel groß sein (dieses Bild hat ' || b || ' × ' || h || ' Pixel).');
  END IF;
  RETURN jsonb_build_object('ok', true, 'breite', b, 'hoehe', h);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_app_symbol_web()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Eigenes App-Symbol für ALLY 20 (GET app/symbol und app/manifest, öffentlich wie das Symbol selbst; Stefan 20.10.2026, Migration 60, BA4b):
  -- PNG als Base64 ohne Zeilenumbrüche. Ohne eigenes Symbol NULL, dann nutzt ALLY 20 die Bildmarke aus dem Corporate Design.
  SELECT jsonb_build_object('png_b64', translate(encode(a.png, 'base64'), E'\n', ''), 'breite', a.breite, 'hoehe', a.hoehe, 'v', left(a.pruefsumme, 12))
  FROM ally_app_symbol a WHERE a.id = 1
$function$
;

CREATE OR REPLACE FUNCTION public.ally_assistent_antwort(p_event_id text, p_sender text, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n integer;
BEGIN
  IF coalesce(p_event_id, '') !~ '^web-[0-9a-f]{24}$' THEN RETURN jsonb_build_object('ok', true, 'uebersprungen', true); END IF;
  UPDATE ally_assistent_verlauf SET antwort = left(ally_ergebnis_text(p_text, NULL), 20000), beantwortet_am = now()
  WHERE event_id = p_event_id AND person = p_sender AND beantwortet_am IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN jsonb_build_object('ok', n = 1);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'fehler', left(SQLERRM, 200));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_assistent_ui(p_token text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN s.person IS NULL THEN '[]'::jsonb ELSE coalesce((
    SELECT jsonb_agg(jsonb_build_object('id', v.id, 'frage', v.frage, 'antwort', v.antwort, 'zeit', arbeit_zeit(v.erstellt_am), 'beantwortet', arbeit_zeit(v.beantwortet_am),
      'wartet', v.antwort IS NULL AND v.erstellt_am > now() - interval '10 minutes') ORDER BY v.id DESC)
    FROM (SELECT * FROM ally_assistent_verlauf x WHERE x.person = s.person ORDER BY x.id DESC LIMIT 20) v), '[]'::jsonb) END
  FROM (SELECT 1) x LEFT JOIN LATERAL (SELECT * FROM ally_ui_sitzung(p_token) y WHERE NOT y.muss_pw_setzen) s ON true
$function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigen(p_person text, p_art text, p_titel text, p_text text, p_ziel jsonb, p_ref text, p_quelle text, p_chat boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a record;
  an boolean;
  t text; x text; r text;
  z jsonb;
  neu_id bigint;
BEGIN
  -- Benachrichtigung für eine Person anlegen (BA4). Unbekannte Art -> "mitteilung". Glocke für diese Art aus -> nichts anlegen.
  -- Doppelschutz über ref (gleiche Person, Art, ref): dann wird die vorhandene Benachrichtigung genannt. Ziel geprüft, sonst Seite der Art.
  IF p_person IS NULL OR NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = p_person AND p.aktiv) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'empfaenger_unbekannt');
  END IF;
  -- Testdaten (Migration 79): Test-Personen nie per Chat; echte Personen bekommen keine Meldung zu Test-Talents oder Test-Kampagnen
  IF ally_person_ist_testdaten(p_person) THEN
    p_chat := false;
  ELSIF ally_testdaten_ziel(p_ziel) THEN
    RETURN jsonb_build_object('ok', true, 'glocke', false, 'testdaten', true);
  END IF;
  SELECT * INTO a FROM ally_benachrichtigung_arten x WHERE x.schluessel = coalesce(p_art, 'mitteilung');
  IF NOT FOUND THEN
    SELECT * INTO a FROM ally_benachrichtigung_arten x WHERE x.schluessel = 'mitteilung';
  END IF;
  SELECT s.glocke INTO an FROM ally_benachrichtigung_schalter s WHERE s.person = p_person AND s.art = a.schluessel;
  IF NOT coalesce(an, a.standard_glocke) THEN
    RETURN jsonb_build_object('ok', true, 'glocke', false, 'art', a.schluessel);
  END IF;
  t := btrim(regexp_replace(coalesce(p_titel, ''), '\s+', ' ', 'g'));
  IF t = '' THEN t := a.name; END IF;
  IF length(t) > 120 THEN t := left(t, 119) || '…'; END IF;
  x := btrim(coalesce(p_text, ''));
  IF length(x) > 4000 THEN x := left(x, 3999) || '…'; END IF;
  r := nullif(left(btrim(coalesce(p_ref, '')), 200), '');
  z := coalesce(ally_ui_ziel_pruefen(p_ziel), CASE WHEN a.seite IS NOT NULL THEN jsonb_build_object('seite', a.seite) END);
  INSERT INTO ally_benachrichtigungen (person, art, titel, text, ziel, ref, quelle, chat)
  VALUES (p_person, a.schluessel, t, x, z, r, nullif(left(btrim(coalesce(p_quelle, '')), 80), ''), coalesce(p_chat, false))
  ON CONFLICT (person, art, ref) WHERE ref IS NOT NULL AND person IS NOT NULL DO NOTHING
  RETURNING id INTO neu_id;
  IF neu_id IS NULL THEN
    SELECT b.id INTO neu_id FROM ally_benachrichtigungen b WHERE b.person = p_person AND b.art = a.schluessel AND b.ref = r;
    RETURN jsonb_build_object('ok', true, 'glocke', true, 'neu', false, 'id', neu_id, 'art', a.schluessel);
  END IF;
  RETURN jsonb_build_object('ok', true, 'glocke', true, 'neu', true, 'id', neu_id, 'art', a.schluessel);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigung_aus_chat(p_nachricht text, p_art text, p_ref text, p_titel text, p_ziel text, p_quelle text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n jsonb; z jsonb := NULL;
  art text := nullif(btrim(coalesce(p_art, '')), '');
  wer text[];
  tl record;
  titel text; rest text;
BEGIN
  -- Benachrichtigung zu einer Chat-Nachricht (SYS 4, SYS 7 und Abläufe, die den Listener-Bot direkt aufrufen). p_nachricht = derselbe JSON-Text,
  -- den der Ablauf an den Bot schickt ({ user_id | room_id, text, html }). Empfänger: user_id oder der Direktraum einer Person (room_id).
  -- Wirft nie einen Fehler (der Chat-Versand darf daran nicht scheitern); Ergebnis nur zur Nachverfolgung. Art "keine" = keine Benachrichtigung.
  IF art = 'keine' THEN RETURN jsonb_build_object('ok', true, 'uebersprungen', true); END IF;
  n := CASE WHEN coalesce(btrim(p_nachricht), '') = '' THEN '{}'::jsonb ELSE p_nachricht::jsonb END;
  IF jsonb_typeof(n) <> 'object' THEN RETURN jsonb_build_object('ok', false, 'grund', 'nachricht_ungueltig'); END IF;
  IF coalesce(btrim(p_ziel), '') <> '' THEN
    BEGIN
      z := p_ziel::jsonb;
    EXCEPTION WHEN OTHERS THEN
      z := NULL;
    END;
  END IF;
  IF coalesce(n->>'user_id', '') <> '' THEN
    wer := ARRAY(SELECT p.matrix_user_id FROM ally_personen p WHERE p.matrix_user_id = n->>'user_id' AND p.aktiv);
  ELSIF coalesce(n->>'room_id', '') <> '' THEN
    wer := ARRAY(SELECT DISTINCT p.matrix_user_id FROM matrix_direct_rooms r JOIN ally_personen p ON p.matrix_user_id = r.matrix_user_id AND p.aktiv
                 WHERE r.room_id = n->>'room_id');
  END IF;
  IF coalesce(cardinality(wer), 0) <> 1 THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'empfaenger_unbekannt');
  END IF;
  -- BA10 (Migration 69): vollständiges Ergebnis für die Oberfläche merken (unabhängig von der Glocke); ein Fehler dabei verhindert die Benachrichtigung nicht
  IF art IN ('morgen_briefing', 'kundenueberblick', 'talents_wochen_briefing') THEN
    BEGIN
      -- Migration 177 (B10b, Briefings): bei Briefings als Quelle die Kennung des Laufs (woche:JJJJ-WW bzw. woche:JJJJ-WW#<Nummer>), für Name und Zahl der Empfänger in der Kachel
      PERFORM ally_ergebnis_merken(wer[1], art, p_titel, n->>'text', n->>'html', CASE WHEN art = 'talents_wochen_briefing' AND coalesce(p_ref, '') ~ '^woche:' THEN p_ref ELSE p_quelle END);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  SELECT * INTO tl FROM ally_benachrichtigung_teile(n->>'text', n->>'html');
  IF tl.titel IS NULL OR tl.titel = '' THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'leer');
  END IF;
  IF coalesce(btrim(p_titel), '') <> '' THEN
    titel := p_titel; rest := btrim(tl.titel || ' ' || coalesce(tl.rest, ''));
  ELSIF coalesce(tl.rest, '') = '' THEN
    titel := NULL; rest := tl.titel;
  ELSE
    titel := tl.titel; rest := tl.rest;
  END IF;
  RETURN ally_benachrichtigen(wer[1], coalesce(art, 'mitteilung'), titel, rest, z, p_ref, p_quelle, true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'grund', 'fehler', 'fehler', left(SQLERRM, 200));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigung_schalter_web(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
BEGIN
  -- Daten für Einstellungen › Mein Konto › Benachrichtigungen: je Art, ob sie in der Glocke erscheint (Aktion benachrichtigung_schalter)
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false); END IF;
  RETURN jsonb_build_object('ok', true, 'arten', (SELECT coalesce(jsonb_agg(jsonb_build_object('art', a.schluessel, 'name', a.name, 'beschreibung', a.beschreibung,
      'glocke', coalesce(sch.glocke, a.standard_glocke)) ORDER BY a.sortierung, a.schluessel), '[]'::jsonb)
    FROM ally_benachrichtigung_arten a LEFT JOIN ally_benachrichtigung_schalter sch ON sch.person = s.person AND sch.art = a.schluessel));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigung_teile(p_text text, p_html text, OUT titel text, OUT rest text)
 RETURNS record
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  t text := p_text;
  zeilen text[];
BEGIN
  -- Chat-Nachricht in Titel (erste Zeile) und Rest (übrige Zeilen in einer Zeile) teilen. Ohne Text: aus dem HTML (Tags entfernt).
  -- Fett-Marken (** und __) und Überschrift-/Zitatzeichen am Zeilenanfang fallen weg.
  IF coalesce(btrim(t), '') = '' THEN
    t := regexp_replace(coalesce(p_html, ''), '<br\s*/?>|</p>|</li>|</h[1-6]>|</div>', E'\n', 'gi');
    t := regexp_replace(t, '<[^>]*>', '', 'g');
    t := replace(replace(replace(replace(replace(t, '&lt;', '<'), '&gt;', '>'), '&quot;', '"'), '&#39;', ''''), '&amp;', '&');
  END IF;
  t := replace(replace(t, '**', ''), '__', '');
  zeilen := ARRAY(SELECT btrim(regexp_replace(s.x, '^\s*[#>]+\s*', '')) FROM regexp_split_to_table(t, E'\r?\n') WITH ORDINALITY s(x, n)
                  WHERE btrim(regexp_replace(s.x, '^\s*[#>]+\s*', '')) <> '' ORDER BY s.n);
  IF coalesce(cardinality(zeilen), 0) = 0 THEN
    titel := NULL; rest := '';
    RETURN;
  END IF;
  titel := btrim(regexp_replace(zeilen[1], '\s*:\s*$', ''));
  rest := btrim(regexp_replace(array_to_string(zeilen[2:], ' '), '\s+', ' ', 'g'));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigung_zeit(p_zeit timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Zeitangabe für Glocke und Liste (Berliner Zeit wie in der übrigen Oberfläche)
  SELECT CASE
    WHEN p_zeit IS NULL THEN ''
    WHEN now() - p_zeit < interval '1 minute' THEN 'gerade eben'
    WHEN now() - p_zeit < interval '60 minutes' THEN 'vor ' || floor(extract(epoch FROM now() - p_zeit) / 60)::integer || ' Min.'
    WHEN (p_zeit AT TIME ZONE 'Europe/Berlin')::date = (now() AT TIME ZONE 'Europe/Berlin')::date THEN 'heute, ' || to_char(p_zeit AT TIME ZONE 'Europe/Berlin', 'HH24:MI')
    WHEN (p_zeit AT TIME ZONE 'Europe/Berlin')::date = (now() AT TIME ZONE 'Europe/Berlin')::date - 1 THEN 'gestern, ' || to_char(p_zeit AT TIME ZONE 'Europe/Berlin', 'HH24:MI')
    WHEN extract(year FROM p_zeit AT TIME ZONE 'Europe/Berlin') = extract(year FROM now() AT TIME ZONE 'Europe/Berlin') THEN to_char(p_zeit AT TIME ZONE 'Europe/Berlin', 'DD.MM., HH24:MI')
    ELSE to_char(p_zeit AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY') END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigung_ziel(p_id bigint, p_ziel jsonb, p_person text, p_rolle text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Ziel eines Eintrags in Glocke und Liste: die Stelle (wenn für die Person freigegeben), sonst die Seite Benachrichtigungen; immer mit bn = id
  -- (der Aufruf markiert die Benachrichtigung als gelesen, siehe ally_ui_eingang).
  SELECT CASE WHEN q.z IS NOT NULL AND ally_ui_funktion_erlaubt(p_person, p_rolle, q.z->>'seite')
    THEN q.z || jsonb_build_object('parameter', coalesce(q.z->'parameter', '{}'::jsonb) || jsonb_build_object('bn', p_id))
    ELSE jsonb_build_object('seite', 'benachrichtigungen', 'parameter', jsonb_build_object('bn', p_id)) END
  FROM (SELECT ally_ui_ziel_pruefen(p_ziel) AS z) q
$function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigungen_aufraeumen(p_tage integer)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  n integer;
BEGIN
  -- Gelesene Benachrichtigungen nach p_tage Tagen entfernen (mindestens 30). Für den täglichen Aufräum-Ablauf vorgesehen, noch nicht eingebunden.
  DELETE FROM ally_benachrichtigungen b WHERE b.gelesen_am IS NOT NULL AND b.erstellt_am < now() - make_interval(days => greatest(30, coalesce(p_tage, 90)));
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigungen_glocke(p_person text, p_rolle text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Glocke im Kopf: Zahl der ungelesenen und die letzten 10 Benachrichtigungen der Person (gelesene grau)
  SELECT jsonb_build_object(
    'ungelesen', (SELECT count(*) FROM ally_benachrichtigungen b WHERE b.person = p_person AND b.gelesen_am IS NULL),
    'eintraege', coalesce((SELECT jsonb_agg(jsonb_build_object('titel', x.titel,
        'text', CASE WHEN length(x.text) > 140 THEN left(x.text, 139) || '…' ELSE x.text END,
        'zeit', ally_benachrichtigung_zeit(x.erstellt_am), 'ungelesen', x.gelesen_am IS NULL,
        'ziel', ally_benachrichtigung_ziel(x.id, x.ziel, p_person, p_rolle)) ORDER BY x.erstellt_am DESC, x.id DESC)
      FROM (SELECT b.* FROM ally_benachrichtigungen b WHERE b.person = p_person ORDER BY b.erstellt_am DESC, b.id DESC LIMIT 10) x), '[]'::jsonb))
$function$
;

CREATE OR REPLACE FUNCTION public.ally_benachrichtigungen_web(p_token text, p_parameter jsonb, p_seite integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
  pa jsonb := CASE WHEN jsonb_typeof(p_parameter) = 'object' THEN p_parameter ELSE '{}'::jsonb END;
  fa text; nur boolean;
  so jsonb; sp text; ri text;
  ges integer; sn integer;
  zeilen jsonb;
  heute date := (now() AT TIME ZONE 'Europe/Berlin')::date;
BEGIN
  -- Seite "Benachrichtigungen" (ALLY 34): eigene Benachrichtigungen, Filter Art und Status (alle/ungelesen), Sortierung je Person
  -- (Zustand benachrichtigungen.alle: zeit, art, titel), 20 je Seite, Kennzahlen. Nur lesen.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen OR NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'benachrichtigungen') THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  fa := CASE WHEN EXISTS (SELECT 1 FROM ally_benachrichtigung_arten x WHERE x.schluessel = pa->>'art') THEN pa->>'art' END;
  nur := coalesce(pa->>'status', '') = 'ungelesen';
  SELECT z.wert->'sortierung' INTO so FROM ally_ui_zustand z WHERE z.person = s.person AND z.schluessel = 'benachrichtigungen.alle';
  sp := CASE WHEN so->>'spalte' IN ('zeit', 'art', 'titel') THEN so->>'spalte' ELSE 'zeit' END;
  ri := CASE WHEN so->>'spalte' = sp AND so->>'richtung' IN ('auf', 'ab') THEN so->>'richtung' WHEN sp = 'zeit' THEN 'ab' ELSE 'auf' END;
  SELECT count(*) INTO ges FROM ally_benachrichtigungen b WHERE b.person = s.person AND (fa IS NULL OR b.art = fa) AND (NOT nur OR b.gelesen_am IS NULL);
  sn := greatest(1, least(coalesce(p_seite, 1), greatest(1, ceil(ges / 20.0)::integer)));
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'art', x.art, 'art_name', x.art_name, 'titel', x.titel, 'text', x.text,
           'zeit', ally_benachrichtigung_zeit(x.erstellt_am), 'ungelesen', x.gelesen_am IS NULL,
           'ziel', ally_benachrichtigung_ziel(x.id, x.ziel, s.person, s.rolle)) ORDER BY x.rn), '[]'::jsonb)
    INTO zeilen
  FROM (SELECT b.*, a.name AS art_name,
          row_number() OVER (ORDER BY
            CASE WHEN sp = 'art' AND ri = 'auf' THEN a.name END ASC, CASE WHEN sp = 'art' AND ri = 'ab' THEN a.name END DESC,
            CASE WHEN sp = 'titel' AND ri = 'auf' THEN lower(b.titel) END ASC, CASE WHEN sp = 'titel' AND ri = 'ab' THEN lower(b.titel) END DESC,
            CASE WHEN sp = 'zeit' AND ri = 'auf' THEN b.erstellt_am END ASC, b.erstellt_am DESC, b.id DESC) AS rn
        FROM ally_benachrichtigungen b JOIN ally_benachrichtigung_arten a ON a.schluessel = b.art
        WHERE b.person = s.person AND (fa IS NULL OR b.art = fa) AND (NOT nur OR b.gelesen_am IS NULL)) x
  WHERE x.rn > (sn - 1) * 20 AND x.rn <= sn * 20;
  RETURN jsonb_build_object('ok', true,
    'ungelesen', (SELECT count(*) FROM ally_benachrichtigungen b WHERE b.person = s.person AND b.gelesen_am IS NULL),
    'heute', (SELECT count(*) FROM ally_benachrichtigungen b WHERE b.person = s.person AND (b.erstellt_am AT TIME ZONE 'Europe/Berlin')::date = heute),
    'woche', (SELECT count(*) FROM ally_benachrichtigungen b WHERE b.person = s.person AND b.erstellt_am > now() - interval '7 days'),
    'alle', (SELECT count(*) FROM ally_benachrichtigungen b WHERE b.person = s.person),
    'gesamt', ges, 'seite', sn, 'je_seite', 20,
    'sortierung', jsonb_build_object('spalte', sp, 'richtung', ri),
    'filter', jsonb_build_object('art', coalesce(fa, ''), 'status', CASE WHEN nur THEN 'ungelesen' ELSE 'alle' END),
    'arten', (SELECT coalesce(jsonb_agg(jsonb_build_object('wert', x.schluessel, 'text', x.name) ORDER BY x.sortierung, x.schluessel), '[]'::jsonb)
              FROM ally_benachrichtigung_arten x),
    'zeilen', zeilen);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_cd_logo_mail(p_mit_daten boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  d ally_cd_dateien%ROWTYPE; b bytea; w integer; h integer;
BEGIN
  -- Migration 192 (Entscheidung Stefan 01.11.2026: Logo als Bild unter fester Adresse): nur das Logo für dunkle Flächen der eigenen Firma, nur als PNG
  -- (SVG zeigen die meisten Mailprogramme nicht an; dann NULL und die Mail zeigt den Firmennamen). Breite und Höhe aus dem PNG-Kopf. v = Kennung der Fassung
  -- (nur zum Neuladen nach einem Wechsel, ohne Rückschluss auf andere Dateien). Daten nur mit p_mit_daten (öffentliche Bildadresse, ALLY 16 „Logo“).
  SELECT x.* INTO d FROM ally_cd_dateien x
  WHERE x.art = 'logo_fuer_dunkel' AND x.mime = 'image/png'
    AND x.unternehmen_id = (SELECT f.unternehmen_id FROM ally_firma f ORDER BY f.id LIMIT 1);
  IF d.unternehmen_id IS NULL THEN RETURN NULL; END IF;
  BEGIN
    b := decode(left(d.daten, 32), 'base64');
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
  IF length(b) < 24 OR substring(b FROM 1 FOR 8) <> '\x89504e470d0a1a0a'::bytea OR substring(b FROM 13 FOR 4) <> '\x49484452'::bytea THEN RETURN NULL; END IF;
  w := (get_byte(b, 16) << 24) | (get_byte(b, 17) << 16) | (get_byte(b, 18) << 8) | get_byte(b, 19);
  h := (get_byte(b, 20) << 24) | (get_byte(b, 21) << 16) | (get_byte(b, 22) << 8) | get_byte(b, 23);
  IF w NOT BETWEEN 1 AND 10000 OR h NOT BETWEEN 1 AND 10000 THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('breite', w, 'hoehe', h, 'v', left(md5(d.groesse::text || '|' || d.geaendert_am::text || '|' || left(d.daten, 64)), 12))
    || CASE WHEN p_mit_daten THEN jsonb_build_object('mime', 'image/png', 'daten', d.daten) ELSE '{}'::jsonb END;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_auftrag_ergebnis(p_auftrag_id bigint, p_ok boolean, p_fehler text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a record;
  code text := split_part(coalesce(p_fehler, ''), ':', 1);
  m text;
BEGIN
  -- ALLY 18, letzter Schritt (Stefan 19.10.2026, Migration 56): Ergebnis eines Auftrags speichern. anlegen -> ally_person_anlegen_abschliessen.
  -- BA9 (Migration 68): Aufträge für Talents (ref_art talent): anlegen -> talent_chat_anlegen_abschliessen; nach erfolgreichem Deaktivieren
  -- wird der Chat-Benutzer beim Talent-Zugang entfernt, wenn der Ally-Chat aus ist (die Kennung bleibt gesperrt). Personen unverändert.
  SELECT * INTO a FROM ally_chat_auftraege WHERE id = p_auftrag_id;
  IF NOT FOUND OR a.status <> 'in_arbeit' THEN
    RETURN jsonb_build_object('ok', false, 'auftrag_id', p_auftrag_id, 'fehler', 'nicht_in_arbeit', 'meldung', 'Der Auftrag ist nicht (mehr) in Arbeit.');
  END IF;
  IF a.art = 'anlegen' AND a.ref_art = 'talent' THEN
    RETURN talent_chat_anlegen_abschliessen(p_auftrag_id, p_ok, p_fehler);
  END IF;
  IF a.art = 'anlegen' THEN
    RETURN ally_person_anlegen_abschliessen(p_auftrag_id, p_ok, p_fehler);
  END IF;
  PERFORM 1 FROM ally_chat_auftraege WHERE id = a.id FOR UPDATE;
  IF coalesce(p_ok, false) THEN
    IF a.art = 'deaktivieren' THEN
      UPDATE ally_chat_kennungen SET deaktiviert_am = coalesce(deaktiviert_am, now()) WHERE matrix_user_id = a.matrix_user_id;
      m := 'Chat-Konto ' || a.matrix_user_id || ' deaktiviert. Die Kennung wird nicht neu vergeben.';
      IF a.ref_art = 'talent' THEN
        UPDATE talent_zugaenge z SET matrix_user_id = NULL, geaendert_am = now() WHERE z.matrix_user_id = a.matrix_user_id
          AND NOT coalesce((SELECT c.chat_an FROM talent_chat c WHERE c.talent_id = z.talent_id), false);
        -- BA10 (Migration 69): nach Sperren des Zugangs (talent_chat_ui_aktion tz_sperren)
        m := CASE WHEN EXISTS (SELECT 1 FROM talent_zugaenge z WHERE z.talent_id = a.ref_id AND NOT z.aktiv) THEN 'Zugang gesperrt, Ally-Chat ausgeschaltet. ' ELSE 'Ally-Chat ausgeschaltet. ' END || m;
      END IF;
    ELSE
      m := 'Chat-Passwort gespeichert. Anmeldung im Chat mit ' || a.matrix_user_id || ' und diesem Passwort.';
    END IF;
    UPDATE ally_chat_auftraege SET status = 'erledigt', fehler = NULL, meldung = m, erledigt_am = now() WHERE id = a.id;
    RETURN jsonb_build_object('ok', true, 'auftrag_id', a.id, 'art', a.art, 'kennung', a.kennung, 'matrix_user_id', a.matrix_user_id, 'meldung', m);
  END IF;
  IF code NOT IN ('zugang', 'zeitueberschreitung', 'verbindung', 'unklar', 'fehlt', 'deaktiviert', 'passwort', 'einstellung', 'fremder_server') THEN
    code := 'server';
  END IF;
  m := CASE WHEN a.art = 'deaktivieren' THEN 'Chat-Konto nicht deaktiviert. ' ELSE 'Chat-Passwort nicht gespeichert. ' END || ally_chat_fehler_text(code);
  UPDATE ally_chat_auftraege SET status = 'fehler', fehler = left(coalesce(nullif(p_fehler, ''), code), 200), meldung = m, erledigt_am = now() WHERE id = a.id;
  RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'art', a.art, 'kennung', a.kennung, 'fehler', code, 'meldung', m);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_auftrag_holen(p_auftrag_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a record;
  ein jsonb := ally_chat_einrichtung();
  kand text[];
BEGIN
  -- ALLY 18, Schritt 1 (Stefan 19.10.2026, Migration 56): Auftrag übernehmen (offen -> in_arbeit). Ein Auftrag "in_arbeit" ohne Ergebnis
  -- wird nach 10 Minuten wieder übernommen. Passwort-Aufträge gelten 15 Minuten. Liefert für "anlegen" bis zu 5 freie Kennungen.
  SELECT * INTO a FROM ally_chat_auftraege WHERE id = p_auftrag_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'auftrag_id', p_auftrag_id, 'fehler', 'unbekannt', 'meldung', 'Unbekannter Auftrag.');
  END IF;
  IF NOT (a.status = 'offen' OR (a.status = 'in_arbeit' AND a.gestartet_am < now() - interval '10 minutes')) THEN
    RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'art', a.art, 'fehler', 'nicht_offen', 'meldung', 'Der Auftrag ist schon bearbeitet (' || a.status || ').');
  END IF;
  IF a.art = 'passwort' AND a.erstellt_am < now() - interval '15 minutes' THEN
    UPDATE ally_chat_auftraege SET status = 'abgelaufen', erledigt_am = now(), meldung = 'Abgelaufen. Bitte das Chat-Passwort erneut festlegen.' WHERE id = a.id;
    RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'art', a.art, 'fehler', 'abgelaufen', 'meldung', 'Abgelaufen. Bitte das Chat-Passwort erneut festlegen.');
  END IF;
  IF NOT (ein->>'ok')::boolean THEN
    UPDATE ally_chat_auftraege SET status = 'fehler', fehler = 'einstellung', meldung = ally_chat_fehler_text('einstellung'), erledigt_am = now() WHERE id = a.id;
    RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'art', a.art, 'fehler', 'einstellung', 'meldung', ally_chat_fehler_text('einstellung'));
  END IF;
  IF substring(a.matrix_user_id FROM '^@[^:]+:(.*)$') IS DISTINCT FROM ein->>'server_name' THEN
    UPDATE ally_chat_auftraege SET status = 'fehler', fehler = 'fremder_server', meldung = ally_chat_fehler_text('fremder_server'), erledigt_am = now() WHERE id = a.id;
    RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'art', a.art, 'fehler', 'fremder_server', 'meldung', ally_chat_fehler_text('fremder_server'));
  END IF;
  IF a.art = 'anlegen' THEN
    kand := ally_chat_kennungen_frei(a.anzeigename, 5, a.id);
    IF cardinality(kand) = 0 THEN
      UPDATE ally_chat_auftraege SET status = 'fehler', fehler = 'belegt', meldung = ally_chat_fehler_text('belegt'), erledigt_am = now() WHERE id = a.id;
      RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'art', a.art, 'fehler', 'belegt', 'meldung', ally_chat_fehler_text('belegt'));
    END IF;
  END IF;
  UPDATE ally_chat_auftraege SET status = 'in_arbeit', versuche = versuche + 1, gestartet_am = now(), fehler = NULL, meldung = NULL WHERE id = a.id;
  RETURN jsonb_build_object('ok', true, 'auftrag_id', a.id, 'art', a.art, 'kennung', a.kennung, 'matrix_user_id', a.matrix_user_id,
    'anzeigename', a.anzeigename, 'adresse', ein->>'adresse', 'server_name', ein->>'server_name', 'kandidaten', to_jsonb(coalesce(kand, '{}')));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_auftrag_kennung_festlegen(p_auftrag_id bigint, p_kennung text, p_belegt jsonb DEFAULT '[]'::jsonb, p_fehler text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a record;
  ein jsonb := ally_chat_einrichtung();
  kn text := lower(btrim(coalesce(p_kennung, '')));
BEGIN
  -- ALLY 18, Schritt 2 bei "anlegen" (Stefan 19.10.2026, Migration 56): auf dem Chat-Server belegte Kennungen dauerhaft sperren (art fremd)
  -- und die erste freie Kennung für den Auftrag festlegen. Ohne Kennung: Fehler aus der Prüfung zurückgeben.
  SELECT * INTO a FROM ally_chat_auftraege WHERE id = p_auftrag_id FOR UPDATE;
  IF NOT FOUND OR a.art <> 'anlegen' OR a.status <> 'in_arbeit' THEN
    RETURN jsonb_build_object('ok', false, 'auftrag_id', p_auftrag_id, 'fehler', 'nicht_in_arbeit');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('ally_chat_kennung'));
  INSERT INTO ally_chat_kennungen (kennung, matrix_user_id, art)
  SELECT x, '@' || x || ':' || (ein->>'server_name'), 'fremd'
  FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_belegt) = 'array' THEN p_belegt ELSE '[]'::jsonb END) AS x
  WHERE x ~ '^[a-z0-9._=/+-]{1,200}$'
  ON CONFLICT DO NOTHING;
  IF kn = '' THEN
    RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'fehler', coalesce(nullif(p_fehler, ''), 'belegt'));
  END IF;
  IF NOT (kn = ANY (ally_chat_kennungen_frei(a.anzeigename, 5, a.id))) THEN
    RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'fehler', 'belegt');
  END IF;
  UPDATE ally_chat_auftraege SET kennung = kn, matrix_user_id = '@' || kn || ':' || (ein->>'server_name') WHERE id = a.id;
  RETURN jsonb_build_object('ok', true, 'auftrag_id', a.id, 'art', a.art, 'kennung', kn, 'matrix_user_id', '@' || kn || ':' || (ein->>'server_name'),
    'anzeigename', a.anzeigename, 'adresse', ein->>'adresse');
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_einrichtung()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Einstellungen für den Chat-Server (Stefan 19.10.2026, Migration 56): chat_server_name (Teil hinter dem Doppelpunkt) und chat_admin_adresse (interne Adresse der Admin-API)
  SELECT jsonb_build_object('server_name', lower(btrim(ally_einstellung('chat_server_name'))), 'adresse', rtrim(btrim(ally_einstellung('chat_admin_adresse')), '/'),
    'ok', lower(btrim(ally_einstellung('chat_server_name'))) ~ '^[a-z0-9.-]+(:[0-9]{1,5})?$'
      AND rtrim(btrim(ally_einstellung('chat_admin_adresse')), '/') ~ '^https?://[a-z0-9.-]+(:[0-9]{1,5})?$')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_fehler_text(p_fehler text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Verständlicher Text zu einem Fehlercode aus ALLY 18 (Stefan 19.10.2026, Migration 56); Code vor dem Doppelpunkt, dahinter ggf. HTTP-Status.
  SELECT CASE split_part(coalesce(p_fehler, ''), ':', 1)
    WHEN 'zugang' THEN 'Der Chat-Server hat den Admin-Zugang abgelehnt. Bitte den Zugang zum Chat-Server in n8n prüfen.'
    WHEN 'zeitueberschreitung' THEN 'Der Chat-Server hat nicht rechtzeitig geantwortet. Bitte später erneut versuchen.'
    WHEN 'verbindung' THEN 'Der Chat-Server ist nicht erreichbar. Bitte später erneut versuchen.'
    WHEN 'belegt' THEN 'Es war keine freie Chat-Kennung zu finden (5 Versuche). Bitte erneut versuchen.'
    WHEN 'vorhanden' THEN 'Diese Chat-Kennung gibt es auf dem Chat-Server schon. Sie wird nicht mehr vergeben. Bitte erneut versuchen.'
    WHEN 'unklar' THEN 'Der Chat-Server hat nicht eindeutig geantwortet. Die Chat-Kennung wird vorsichtshalber nicht mehr vergeben. Bitte erneut versuchen.'
    WHEN 'ungueltig' THEN 'Der Chat-Server lehnt die Chat-Kennung ab.'
    WHEN 'fehlt' THEN 'Dieses Chat-Konto gibt es auf dem Chat-Server nicht.'
    WHEN 'deaktiviert' THEN 'Dieses Chat-Konto ist deaktiviert.'
    WHEN 'passwort' THEN 'Das Chat-Passwort wurde nicht angenommen. Bitte mindestens 10 Zeichen verwenden.'
    WHEN 'doppelt' THEN 'Diese Person gibt es inzwischen schon.'
    WHEN 'einstellung' THEN 'Der Chat-Server ist noch nicht eingerichtet (Einstellungen chat_server_name und chat_admin_adresse).'
    WHEN 'fremder_server' THEN 'Dieses Chat-Konto gehört nicht zum eingerichteten Chat-Server.'
    ELSE 'Der Chat-Server meldet einen Fehler. Bitte später erneut versuchen.' END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_initialen(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Initialen für die Chat-Kennung (Stefan 19.10.2026, Migration 56): erstes Zeichen des ersten und des letzten Namensteils,
  -- ohne Nachname die ersten zwei Zeichen des Vornamens; Umlaute und Akzente umgeschrieben (ä -> a), nur a-z; ohne Buchstaben "nn".
  WITH w AS (
    SELECT array_remove(ARRAY(SELECT regexp_replace(x, '[^a-z]', '', 'g')
      FROM unnest(regexp_split_to_array(translate(lower(btrim(coalesce(p_name, ''))), 'äöüàáâãåāăąçćčďèéêëēėęěğìíîïīįñńňòóôõōőŕřśšşťùúûůūűųýÿźżžßæœøłđðþı', 'aouaaaaaaaacccdeeeeeeeegiiiiiinnnoooooorrssstuuuuuuuyyzzzsaoolddti'), '[[:space:],]+')) AS x), '') AS teile)
  SELECT CASE
    WHEN cardinality(teile) >= 2 THEN left(teile[1], 1) || left(teile[cardinality(teile)], 1)
    WHEN cardinality(teile) = 1 THEN rpad(left(teile[1], 2), 2, 'x')
    ELSE 'nn' END
  FROM w
$function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_kennung_vorschlag(p_name text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Vorschlag für die Chat-Kennung einer neuen Person (Stefan 19.10.2026, Migration 56), z. B. "sb0001". Geprüft wird beim Chat-Server erst in ALLY 18.
  SELECT (ally_chat_kennungen_frei(p_name, 1))[1]
$function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_kennungen_frei(p_name text, p_anzahl integer DEFAULT 1, p_auftrag_id bigint DEFAULT NULL::bigint)
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
  -- Freie Chat-Kennungen für einen Namen (Entscheidung E3, Stefan 19.10.2026): Initialen + 4 Ziffern ab 0001 (sb0001, sb0002 …), ab 10000 fünfstellig.
  -- Frei = weder im Verzeichnis ally_chat_kennungen (auch deaktivierte und fremde) noch als Kennung einer Person noch in einem offenen Anlege-Auftrag
  -- (der Auftrag p_auftrag_id selbst zählt nicht). Kleinste freie Nummer zuerst.
  WITH v AS (SELECT ally_chat_initialen(p_name) AS ini),
  belegt AS (
    SELECT k.kennung AS k FROM ally_chat_kennungen k, v WHERE k.kennung LIKE v.ini || '%'
    UNION SELECT substring(p.matrix_user_id FROM '^@([^:]+):') FROM ally_personen p
    UNION SELECT a.kennung FROM ally_chat_auftraege a
      WHERE a.art = 'anlegen' AND a.status IN ('offen', 'in_arbeit') AND a.id IS DISTINCT FROM p_auftrag_id)
  SELECT coalesce((SELECT array_agg(y.k ORDER BY y.n) FROM (
      SELECT x.n, x.k FROM (SELECT n, v.ini || CASE WHEN n < 10000 THEN lpad(n::text, 4, '0') ELSE n::text END AS k FROM v, generate_series(1, 99999) AS n) x
      WHERE NOT EXISTS (SELECT 1 FROM belegt b WHERE b.k = x.k)
      ORDER BY x.n LIMIT greatest(coalesce(p_anzahl, 1), 1)) y), '{}')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_chat_passwort_auftrag(p_sitzung text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  kn record;
  ein jsonb := ally_chat_einrichtung();
  aid bigint;
BEGIN
  -- Chat-Passwort festlegen (Stefan 19.10.2026, Migration 56): nur für den eigenen Chat-Benutzer, nur aus der eigenen Sitzung.
  -- Das Passwort selbst geht direkt an ALLY 18 und wird nie gespeichert. Höchstens 5 Aufträge je Stunde.
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_sitzung);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND, 'fehler', 'Bitte neu anmelden.');
  END IF;
  IF NOT (ein->>'ok')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'fehler', ally_chat_fehler_text('einstellung'));
  END IF;
  SELECT * INTO kn FROM ally_chat_kennungen k WHERE k.matrix_user_id = s.matrix_user_id AND k.art = 'person';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Für dich ist noch kein Chat-Konto eingerichtet.');
  ELSIF kn.deaktiviert_am IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', ally_chat_fehler_text('deaktiviert'));
  ELSIF substring(kn.matrix_user_id FROM '^@[^:]+:(.*)$') <> ein->>'server_name' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', ally_chat_fehler_text('fremder_server'));
  END IF;
  IF (SELECT count(*) FROM ally_chat_auftraege a WHERE a.art = 'passwort' AND a.matrix_user_id = kn.matrix_user_id AND a.erstellt_am > now() - interval '1 hour') >= 5 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Bitte etwas warten, bevor du das Chat-Passwort erneut änderst.');
  END IF;
  UPDATE ally_chat_auftraege SET status = 'abgelaufen', erledigt_am = now(), meldung = 'Durch einen neueren Auftrag ersetzt.'
  WHERE art = 'passwort' AND matrix_user_id = kn.matrix_user_id AND status = 'offen';
  INSERT INTO ally_chat_auftraege (art, kennung, matrix_user_id, anzeigename, ref_art, ref_id, erstellt_von)
  VALUES ('passwort', kn.kennung, kn.matrix_user_id, s.anzeigename, 'person', kn.ref_id, s.matrix_user_id)
  RETURNING id INTO aid;
  RETURN jsonb_build_object('ok', true, 'auftrag_id', aid, 'matrix_user_id', kn.matrix_user_id);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_darf_aktualisieren(p_person text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 188 (Konzept E.4, Entscheidung Stefan 31.10.: nur Admin und Superadmin, fest): Recht „Updates einspielen“ und Admin oder Superadmin;
  -- Test-Personen nie (kein Update aus Testdaten heraus). Das Recht selbst lässt sich nicht an Rollen oder Personen vergeben (ally_aktualisieren_schutz).
  SELECT coalesce(ally_hat_recht(p_person, 'ally_aktualisieren'), false)
     AND (coalesce(ally_hat_recht(p_person, 'admin'), false) OR coalesce(ally_hat_recht(p_person, 'superadmin'), false))
     AND NOT coalesce(ally_person_ist_testdaten(p_person), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_datei_auftrag(p_token text, p_art text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record; e record; b record; bereich text; pfad text; name text; zurueck text;
  nid bigint := CASE WHEN coalesce(p_id, '') ~ '^[0-9]{1,12}$' THEN p_id::bigint END;
BEGIN
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false, 'zurueck', ''); END IF;
  IF p_art = 'er' THEN
    SELECT * INTO e FROM ally_ergebnisse x WHERE x.id = nid AND x.person = s.person AND x.datei IS NOT NULL;
    zurueck := CASE e.art WHEN 'kundenueberblick' THEN '?seite=kundenueberblick#a-ergebnisse' ELSE '' END;
    IF e.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'zurueck', '', 'meldung', 'Diese Datei gibt es nicht (mehr).'); END IF;
    IF e.art = 'kundenueberblick' AND NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'kundenueberblick') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'zurueck', '', 'meldung', 'Diese Datei ist für dich nicht freigeschaltet.');
    END IF;
    bereich := e.datei->>'bereich'; pfad := e.datei->>'pfad'; name := e.datei->>'name';
  ELSIF p_art IN ('kl', 'be') THEN
    zurueck := '?seite=belege' || CASE WHEN p_art = 'be' THEN '#a-fehler' ELSE '#a-fragen' END;
    IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'belege') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'zurueck', '', 'meldung', 'Belege sind für dich nicht freigeschaltet.');
    END IF;
    IF p_art = 'kl' THEN
      SELECT bv.* INTO b FROM klaerungsfaelle kf JOIN beleg_verarbeitung bv ON bv.id = kf.beleg_verarbeitung_id WHERE kf.id = nid AND kf.status = 'offen';
    ELSE
      SELECT bv.* INTO b FROM beleg_verarbeitung bv WHERE bv.id = nid AND bv.processing_status = 'fehler';
    END IF;
    IF b.id IS NULL OR coalesce(b.datei_pfad, '') = '' THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'zurueck', zurueck, 'meldung', 'Zu diesem Beleg ist keine Datei hinterlegt.');
    END IF;
    bereich := coalesce(nullif(b.datei_bereich, ''), 'ally'); pfad := b.datei_pfad; name := regexp_replace(b.datei_pfad, '^.*/', '');
  ELSE
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'zurueck', '', 'meldung', 'Unbekannte Datei.');
  END IF;
  IF bereich NOT IN ('ally', 'buchhaltung') OR pfad IS NULL OR pfad = '' OR length(pfad) > 1000 OR left(pfad, 1) = '/' OR pfad ~ '(^|/)\.\.?(/|$)'
     OR pfad ~ '[\x01-\x1f\x7f*?{}\\]' OR pfad ~ '//' THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'zurueck', zurueck, 'meldung', 'Der Ablageort der Datei ist ungültig.');
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'auftrag', jsonb_build_object('aktion', 'holen', 'bereich', bereich, 'pfad', pfad),
    'name', left(coalesce(nullif(name, ''), 'datei'), 200), 'zurueck', zurueck);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_einstellung(p_schluessel text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((SELECT wert FROM ally_einstellungen WHERE schluessel = p_schluessel), '')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_einstellung_setzen(p_schluessel text, p_wert text, p_von text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
AS $function$
  INSERT INTO ally_einstellungen (schluessel, wert, geaendert_am, geaendert_von) VALUES (p_schluessel, p_wert, now(), p_von)
  ON CONFLICT (schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von
$function$
;

CREATE OR REPLACE FUNCTION public.ally_einzelrecht_uebernehmen(p_user text, p_recht text, p_von text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  z ally_rechte%ROWTYPE; e record; n integer := 0; m integer;
BEGIN
  -- Migration 167 (Bauplan B6, F13): ein einzeln vergebenes Recht der alten Oberfläche als eigenes Recht (plus) der Person, so wie es bisher wirkte
  -- (ally_recht_roh bis 166): „Talents ansehen“ für zugeordnete Talents, „Talents und Kampagnen verwalten“ für alle und dazu „Talents ansehen“ für alle,
  -- Rechte mit Reichweite sonst für alle, Rechte ohne Reichweite ohne Angabe. Nur Rechte mit je_person (andere wirkten nie einzeln), nie admin/superadmin,
  -- nie für Talents. Ein minus bleibt stehen (es nahm das Recht schon bisher), ein vorhandenes plus behält die größere Reichweite.
  -- Liefert die Zahl der neuen oder erweiterten Einträge.
  SELECT * INTO z FROM ally_rechte x WHERE x.schluessel = p_recht AND x.je_person AND x.schluessel NOT IN ('admin', 'superadmin');
  IF NOT FOUND OR ally_person_ist_talent(p_user) OR NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = p_user) THEN RETURN 0; END IF;
  FOR e IN SELECT p_recht AS k, CASE WHEN p_recht = 'talents_ansehen' THEN 'zugeordnet' WHEN z.reichweite THEN 'alle' END AS rw
           UNION ALL SELECT 'talents_ansehen', 'alle' WHERE p_recht = 'talents_verwalten' LOOP
    INSERT INTO ally_person_rechte (person, recht, wirkung, reichweite, geaendert_von) VALUES (p_user, e.k, 'plus', e.rw, p_von)
    ON CONFLICT (person, recht) DO UPDATE SET reichweite = EXCLUDED.reichweite, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von
    WHERE ally_person_rechte.wirkung = 'plus' AND ally_person_rechte.reichweite IS NOT NULL AND ally_recht_stufe(EXCLUDED.reichweite) > ally_recht_stufe(ally_person_rechte.reichweite);
    GET DIAGNOSTICS m = ROW_COUNT;
    n := n + m;
  END LOOP;
  RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_entschluesseln(p_wert bytea)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  k text;
BEGIN
  IF p_wert IS NULL THEN
    RETURN NULL;
  END IF;
  k := ally_schluessel();
  BEGIN
    RETURN pgp_sym_decrypt(p_wert, k);
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Entschlüsselung fehlgeschlagen. Der Schlüssel passt nicht zu den gespeicherten Daten.';
  END;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ergebnis_merken(p_person text, p_art text, p_titel text, p_text text, p_html text, p_quelle text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
  t text; z text[]; titel text; datei jsonb := NULL; m text[]; pfad text; vorn text; i integer; neu bigint;
BEGIN
  IF p_art IS NULL OR p_art NOT IN ('morgen_briefing', 'kundenueberblick', 'talents_wochen_briefing') THEN RETURN NULL; END IF;
  IF p_person IS NULL OR NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = p_person) THEN RETURN NULL; END IF;
  t := ally_ergebnis_text(p_text, p_html);
  IF t = '' THEN RETURN NULL; END IF;
  z := regexp_split_to_array(t, E'\n');
  IF p_art = 'kundenueberblick' THEN
    vorn := ltrim(coalesce(dokumente_ordner(), '') || '/Kundenüberblick', '/') || '/';
    FOR i IN REVERSE coalesce(array_length(z, 1), 0)..1 LOOP
      m := regexp_match(z[i], '^PDF \(([^)]{0,100})\): (.+)$');
      IF m IS NOT NULL THEN
        pfad := btrim(m[2]);
        IF left(pfad, length(vorn)) = vorn AND pfad ~* '\.pdf$' AND length(pfad) <= 1000 AND pfad !~ '(^|/)\.\.?(/|$)' AND pfad !~ '[\x01-\x1f\x7f*?{}\\]' AND pfad !~ '//' THEN
          datei := jsonb_build_object('bereich', 'ally', 'pfad', pfad, 'name', regexp_replace(pfad, '^.*/', ''), 'ort', nullif(btrim(m[1]), ''));
        END IF;
        z := z[1:i - 1] || z[i + 1:];
        EXIT;
      END IF;
    END LOOP;
  END IF;
  titel := btrim(regexp_replace(coalesce(z[1], ''), '\s*:\s*$', ''));
  IF p_art = 'morgen_briefing' OR titel = '' OR length(titel) > 200 THEN
    titel := coalesce(nullif(btrim(coalesce(p_titel, '')), ''), (SELECT a.name FROM ally_benachrichtigung_arten a WHERE a.schluessel = p_art), 'Ergebnis');
  ELSE
    z := z[2:];
  END IF;
  t := btrim(array_to_string(z, E'\n'), E' \n\t');
  INSERT INTO ally_ergebnisse (person, art, titel, text, datei, quelle)
  VALUES (p_person, p_art, left(titel, 200), left(t, 20000), datei, nullif(left(btrim(coalesce(p_quelle, '')), 80), ''))
  RETURNING id INTO neu;
  DELETE FROM ally_ergebnisse e WHERE e.person = p_person AND e.art = p_art
    AND e.id NOT IN (SELECT x.id FROM ally_ergebnisse x WHERE x.person = p_person AND x.art = p_art ORDER BY x.erstellt_am DESC, x.id DESC LIMIT 20);
  RETURN neu;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ergebnis_text(p_text text, p_html text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  t text := coalesce(p_text, '');
BEGIN
  IF btrim(t) = '' THEN
    t := regexp_replace(coalesce(p_html, ''), '<br\s*/?>', E'\n', 'gi');
    t := regexp_replace(t, '</p>|</li>|</h[1-6]>|</div>|</ul>', E'\n\n', 'gi');
    t := regexp_replace(t, '<[^>]*>', '', 'g');
    t := replace(replace(replace(replace(replace(replace(t, '&nbsp;', ' '), '&lt;', '<'), '&gt;', '>'), '&quot;', '"'), '&#39;', ''''), '&amp;', '&');
  END IF;
  t := replace(replace(replace(t, E'\r\n', E'\n'), E'\r', E'\n'), '**', '');
  t := regexp_replace(t, '[ \t]+\n', E'\n', 'g');
  t := regexp_replace(t, '\n{3,}', E'\n\n', 'g');
  RETURN btrim(t, E' \n\t');
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ergebnisse_ui(p_token text, p_art text, p_anzahl integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN s.person IS NULL THEN jsonb_build_object('ok', false) ELSE jsonb_build_object('ok', true, 'liste', coalesce((
    SELECT jsonb_agg(jsonb_build_object('id', e.id, 'titel', e.titel, 'text', e.text, 'zeit', arbeit_zeit(e.erstellt_am), 'quelle', e.quelle,
      'datei', e.datei IS NOT NULL, 'datei_name', e.datei->>'name', 'datei_ort', e.datei->>'ort') ORDER BY e.erstellt_am DESC, e.id DESC)
    FROM (SELECT * FROM ally_ergebnisse x WHERE x.person = s.person AND x.art = p_art ORDER BY x.erstellt_am DESC, x.id DESC
          LIMIT least(greatest(coalesce(p_anzahl, 5), 1), 20)) e), '[]'::jsonb)) END
  FROM (SELECT 1) x LEFT JOIN LATERAL (SELECT * FROM ally_ui_sitzung(p_token) y WHERE NOT y.muss_pw_setzen) s ON true
$function$
;

CREATE OR REPLACE FUNCTION public.ally_fassung_aktuell()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 188 (Konzept C.1): eingespielte Fassung dieser Installation = zuletzt eingespielte Zeile in ally_fassung (NULL ohne Eintrag).
  SELECT f.nummer FROM ally_fassung f ORDER BY f.eingespielt_am DESC, f.nummer COLLATE "C" DESC LIMIT 1
$function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_einstellungen_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  k text := CASE WHEN TG_OP = 'DELETE' THEN OLD.schluessel ELSE NEW.schluessel END;
  e text; i text;
BEGIN
  SELECT x.einstellung, CASE WHEN k = ANY (x.schluessel) THEN '' ELSE substr(k, length(x.praefix) + 1) END INTO e, i
  FROM ally_fix_einstellungen x WHERE x.quelle = 'einstellung' AND (k = ANY (x.schluessel) OR (x.praefix IS NOT NULL AND left(k, length(x.praefix)) = x.praefix))
  ORDER BY x.sortierung LIMIT 1;
  IF e IS NOT NULL THEN
    PERFORM ally_fix_pruefen(e, i, CASE TG_OP
      WHEN 'INSERT' THEN NOT EXISTS (SELECT 1 FROM ally_einstellungen a WHERE a.schluessel = NEW.schluessel)   -- bei ON CONFLICT prüft der UPDATE-Trigger den Wert
      WHEN 'UPDATE' THEN OLD.wert IS DISTINCT FROM NEW.wert OR OLD.schluessel IS DISTINCT FROM NEW.schluessel
      ELSE true END);
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_handelnd()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT nullif(current_setting('ally.handelnd', true), '')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_meldung(p_token text, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM ally_web_meldung(p_token, p_text, 'fehler', NULL);
  RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', p_text);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_person_geschuetzt(p_person text, p_handelnd text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT p_handelnd IS NOT NULL AND NOT coalesce(ally_hat_recht(p_handelnd, 'superadmin'), false) AND ally_fixiert('admin_recht', p_person)
    AND EXISTS (SELECT 1 FROM ally_nutzer_rechte x WHERE x.matrix_user_id = p_person AND x.recht = 'admin')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_pruefen(p_einstellung text, p_eintrag text, p_geaendert boolean)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  h text := ally_fix_handelnd();
  w jsonb;
  x text;
BEGIN
  IF h IS NULL THEN RETURN; END IF;   -- System (ohne Sitzung): nie blockiert, nie fixiert
  IF coalesce(ally_hat_recht(h, 'superadmin'), false) THEN
    -- Superadmin: gewählt im Häkchen „Fixiert“ (ally_fix_wunsch) -> so; sonst ein geänderter Wert -> fixiert; sonst bleibt der Zustand
    w := nullif(current_setting('ally.fix_wunsch', true), '')::jsonb;
    x := w->>(p_einstellung || '|' || coalesce(p_eintrag, ''));
    IF x IS NOT NULL THEN PERFORM ally_fix_setzen(p_einstellung, p_eintrag, x::boolean, h);
    ELSIF p_geaendert THEN PERFORM ally_fix_setzen(p_einstellung, p_eintrag, true, h); END IF;
    RETURN;
  END IF;
  IF p_geaendert AND ally_fixiert(p_einstellung, p_eintrag) THEN
    -- eigener Fehlercode AT002 (Muster AT001): Aktionen ohne eigene Vorprüfung fangen ihn ab und zeigen den Text als Meldung (ally_fix_meldung)
    RAISE EXCEPTION USING ERRCODE = 'AT002',
      MESSAGE = 'Diese Einstellung ist fixiert: ' || coalesce((SELECT e.name FROM ally_fix_einstellungen e WHERE e.einstellung = p_einstellung), p_einstellung) || '.';
  END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_rechte_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.recht = 'admin' THEN
    PERFORM ally_fix_pruefen('admin_recht', OLD.matrix_user_id, TG_OP = 'DELETE' OR NEW.recht IS DISTINCT FROM 'admin' OR NEW.matrix_user_id IS DISTINCT FROM OLD.matrix_user_id);
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.recht = 'admin' THEN
    PERFORM ally_fix_pruefen('admin_recht', NEW.matrix_user_id, NOT EXISTS (SELECT 1 FROM ally_nutzer_rechte x WHERE x.matrix_user_id = NEW.matrix_user_id AND x.recht = 'admin'));
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_schalter_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM ally_fix_pruefen('funktion', NEW.schluessel, NOT NEW.an AND NOT EXISTS (SELECT 1 FROM ally_ui_funktion_schalter x WHERE x.schluessel = NEW.schluessel));
  ELSIF TG_OP = 'UPDATE' THEN
    PERFORM ally_fix_pruefen('funktion', NEW.schluessel, OLD.an IS DISTINCT FROM NEW.an OR OLD.schluessel IS DISTINCT FROM NEW.schluessel);
    IF OLD.schluessel IS DISTINCT FROM NEW.schluessel THEN PERFORM ally_fix_pruefen('funktion', OLD.schluessel, true); END IF;
  ELSE
    PERFORM ally_fix_pruefen('funktion', OLD.schluessel, NOT OLD.an);
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_setzen(p_einstellung text, p_eintrag text, p_fixiert boolean, p_von text)
 RETURNS void
 LANGUAGE sql
AS $function$
  INSERT INTO ally_fixierung (einstellung, eintrag, fixiert, geaendert_am, geaendert_von) VALUES (p_einstellung, coalesce(p_eintrag, ''), p_fixiert, now(), p_von)
  ON CONFLICT (einstellung, eintrag) DO UPDATE SET fixiert = EXCLUDED.fixiert, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von
$function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE s record;
BEGIN
  SELECT * INTO s FROM ally_ui_sitzung(p_token) x WHERE NOT x.muss_pw_setzen;
  IF NOT FOUND OR NOT coalesce(ally_hat_recht(s.person, 'admin'), false) THEN RETURN jsonb_build_object('ok', false); END IF;
  RETURN jsonb_build_object('ok', true, 'sa', coalesce(ally_hat_recht(s.person, 'superadmin'), false),
    'budget_frei', coalesce((SELECT v.ki_schluessel FROM plattform_vertrag v WHERE v.id = 1), '') = 'kunde',
    'fixiert', coalesce((SELECT jsonb_object_agg(y.einstellung, y.e) FROM (SELECT x.einstellung, jsonb_agg(x.eintrag ORDER BY x.eintrag) AS e FROM ally_fixierung x
        WHERE ally_fixiert(x.einstellung, x.eintrag) GROUP BY x.einstellung) y), '{}'::jsonb),
    'karte', coalesce((SELECT jsonb_agg(jsonb_build_object('einstellung', e.einstellung, 'name', e.name, 'formulare', to_jsonb(e.formulare), 'felder', to_jsonb(e.felder),
        'eintrag_aus', e.eintrag_aus, 'aktion', e.aktion) ORDER BY e.sortierung) FROM ally_fix_einstellungen e), '[]'::jsonb));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_vertrag_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM ally_fix_pruefen('ki_budget', '', (OLD.ki_budget_eur, OLD.budget_modus, OLD.warn_prozent, OLD.spar_prozent) IS DISTINCT FROM (NEW.ki_budget_eur, NEW.budget_modus, NEW.warn_prozent, NEW.spar_prozent));
  PERFORM ally_fix_pruefen('ki_zugang', '', OLD.ki_schluessel IS DISTINCT FROM NEW.ki_schluessel);
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_fix_wunsch(p_daten jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  h text := ally_fix_handelnd();
  e text; i text; f boolean; w jsonb;
BEGIN
  IF jsonb_typeof(p_daten) <> 'object' OR NOT (p_daten ? '_fx_e') OR h IS NULL OR NOT coalesce(ally_hat_recht(h, 'superadmin'), false) THEN RETURN; END IF;
  e := btrim(coalesce(p_daten->>'_fx_e', '')); i := btrim(coalesce(p_daten->>'_fx_i', ''));
  IF NOT EXISTS (SELECT 1 FROM ally_fix_einstellungen x WHERE x.einstellung = e) OR length(i) > 200 THEN RETURN; END IF;
  f := lower(coalesce(p_daten->>'_fixiert', '')) IN ('1', 'true', 'an', 'ja', 'on');
  w := coalesce(nullif(current_setting('ally.fix_wunsch', true), '')::jsonb, '{}'::jsonb) || jsonb_build_object(e || '|' || i, f);
  PERFORM set_config('ally.fix_wunsch', w::text, true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_fixiert(p_einstellung text, p_eintrag text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((SELECT x.fixiert FROM ally_fixierung x WHERE x.einstellung = p_einstellung AND x.eintrag = coalesce(p_eintrag, '')), false)
    AND NOT (p_einstellung = 'ki_budget' AND coalesce((SELECT v.ki_schluessel FROM plattform_vertrag v WHERE v.id = 1), '') = 'kunde')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_funktion_an(p_user text, p_schluessel text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Testdaten (Migration 79): Test-Personen bekommen keine Funktion mit Chat, Mail oder Briefing
  SELECT NOT ally_person_ist_testdaten(p_user) AND coalesce((SELECT f.modul IS NULL OR plattform_modul_an(f.modul) FROM ally_funktionen f WHERE f.schluessel = p_schluessel), true)
     AND coalesce(
       (SELECT aktiv FROM ally_nutzer_funktionen WHERE matrix_user_id = p_user AND schluessel = p_schluessel),
       (SELECT aktiv FROM ally_funktionen WHERE schluessel = p_schluessel),
       false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_geheim(p_schluessel text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((SELECT ally_entschluesseln(g.wert) FROM ally_geheimnisse g WHERE g.schluessel = p_schluessel), '')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_geheim_setzen(p_schluessel text, p_wert text, p_von text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF coalesce(p_schluessel, '') !~ '^[a-z0-9_]{1,60}$' THEN
    RAISE EXCEPTION 'Ungültiger Name für ein Geheimnis.';
  END IF;
  IF p_wert IS NULL OR btrim(p_wert) = '' THEN
    DELETE FROM ally_geheimnisse WHERE schluessel = p_schluessel;
  ELSE
    INSERT INTO ally_geheimnisse (schluessel, wert, geaendert_am, geaendert_von) VALUES (p_schluessel, ally_verschluesseln(p_wert), now(), p_von)
    ON CONFLICT (schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von;
  END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_geheim_vorhanden(p_schluessel text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM ally_geheimnisse g WHERE g.schluessel = p_schluessel)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_hat_recht(p_user text, p_recht text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Hat die Person das Recht (Migration 64, Stefan 20.10.2026)? Über Rolle und Reichweite (ally_recht_reichweite), nicht über Rollennamen.
  -- „talents_verwalten“ behält die bisherige Bedeutung „Talents verwalten für alle Talents“ (nur Reichweite „alle“ zählt);
  -- „nur zugeordnete“ prüfen talents_planung_management und talents_ui_rechte.
  -- Migration 156 (Prüfbericht M155 N1): 'selbst' (nur die eigenen Daten eines Talents) zählt nur bei Rechten mit nur_selbst; sonst nur 'zugeordnet' oder 'alle'.
  SELECT CASE WHEN p_recht = 'talents_verwalten' THEN coalesce(q.r = 'alle', false)
              ELSE coalesce(q.r IN ('alle', 'zugeordnet') OR (q.r = 'selbst' AND EXISTS (SELECT 1 FROM ally_rechte z WHERE z.schluessel = p_recht AND z.nur_selbst)), false) END
  FROM (SELECT ally_recht_reichweite(p_user, p_recht) AS r) q
$function$
;

CREATE OR REPLACE FUNCTION public.ally_html(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT replace(replace(replace(replace(replace(coalesce(p, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;'), '''', '&#39;')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_aufgabe(p_id bigint, p_mit_talent boolean)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Ein Eintrag aus talent_aufgaben als VEVENT (Termin mit Beginn/Ende, Aufgabe/Review/Erinnerung zum Fälligkeitszeitpunkt). UID aus ics_uid, SEQUENCE aus ics_sequenz.
  SELECT ally_ics_ereignis(a.ics_uid || '@' || ally_ics_domain(), a.ics_sequenz, coalesce(a.beginn, a.faellig_am), CASE WHEN a.art = 'termin' THEN a.ende END, a.ganztags,
      (coalesce(a.beginn, a.faellig_am) AT TIME ZONE 'Europe/Berlin')::date, (coalesce(a.ende, a.beginn, a.faellig_am) AT TIME ZONE 'Europe/Berlin')::date,
      CASE WHEN a.status = 'erledigt' THEN 'Erledigt: ' ELSE '' END
        || CASE a.art WHEN 'termin' THEN '' WHEN 'review' THEN 'Review: ' WHEN 'erinnerung' THEN 'Erinnerung: ' ELSE 'Aufgabe: ' END || a.titel
        || CASE WHEN p_mit_talent THEN ' (' || coalesce(talent_listenname(a.talent_id), 'Talent') || ')' ELSE '' END,
      concat_ws(E'\n', nullif(btrim(a.text), ''),
        (SELECT 'Kampagne: ' || k.marke || ' – ' || k.name FROM talent_kampagnen k WHERE k.id = a.kampagne_id),
        (SELECT 'Deliverable: ' || talents_planung_deliverable_name(d.format, d.anzahl, d.titel) FROM talent_deliverables d WHERE d.id = a.deliverable_id)),
      a.ort, a.status = 'abgesagt', now())
  FROM talent_aufgaben a WHERE a.id = p_id AND coalesce(a.beginn, a.faellig_am) IS NOT NULL
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_datei(p_ereignisse text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Kalenderdatei als Mail-Anhang (ein Termin zum Übernehmen, METHOD:PUBLISH, ohne Kalendername)
  SELECT ally_ics_zeile('BEGIN:VCALENDAR') || ally_ics_zeile('VERSION:2.0')
    || ally_ics_zeile('PRODID:-//' || regexp_replace(produkt_name(), '[^A-Za-z0-9 ._-]', '', 'g') || '//Kalender//DE')
    || ally_ics_zeile('CALSCALE:GREGORIAN') || ally_ics_zeile('METHOD:PUBLISH') || coalesce(p_ereignisse, '') || ally_ics_zeile('END:VCALENDAR')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_deliverable(p_id bigint, p_was text, p_mit_talent boolean)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Deadline bzw. geplante Veröffentlichung eines Deliverables als ganztägiger Eintrag. Keine Honorare.
  SELECT ally_ics_ereignis('deliverable-' || d.id || '-' || p_was || '@' || ally_ics_domain(), 0, NULL, NULL, true,
      CASE WHEN p_was = 'deadline' THEN d.deadline ELSE d.veroeffentlichen_am END, NULL,
      CASE WHEN p_was = 'deadline' THEN 'Deadline: ' ELSE 'Veröffentlichung: ' END || talents_planung_deliverable_name(d.format, d.anzahl, d.titel)
        || ' (' || k.marke || ' – ' || k.name || CASE WHEN p_mit_talent THEN ', ' || coalesce(talent_listenname(d.talent_id), 'Talent') ELSE '' END || ')',
      concat_ws(E'\n', 'Plattform: ' || talents_planung_plattform_text(d.plattform), 'Stand: ' || talents_planung_status_text(d.status)),
      NULL, false, now())
  FROM talent_deliverables d JOIN talent_kampagnen k ON k.id = d.kampagne_id
  WHERE d.id = p_id AND (p_was = 'deadline' OR d.veroeffentlichen_am IS NOT NULL)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_domain()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Teil hinter dem @ der UID: Host der öffentlichen Adresse (Einstellung n8n_oeffentlich), sonst ein neutraler Wert
  SELECT coalesce(substring(lower(coalesce(ally_einstellung('n8n_oeffentlich'), '')) FROM '^https://([a-z0-9.-]{3,253})'), 'ally.invalid')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_ereignis(p_uid text, p_sequenz integer, p_beginn timestamp with time zone, p_ende timestamp with time zone, p_ganztags boolean, p_tag_beginn date, p_tag_ende date, p_titel text, p_text text, p_ort text, p_abgesagt boolean, p_stamp timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Ein VEVENT. Mit Uhrzeit: Beginn/Ende in UTC (ohne Ende 30 Minuten). Ganztägig: Tage (DTEND ist der Tag nach dem letzten Tag).
  SELECT ally_ics_zeile('BEGIN:VEVENT') || ally_ics_zeile('UID:' || p_uid) || ally_ics_zeile('DTSTAMP:' || ally_ics_utc(p_stamp))
    || ally_ics_zeile('SEQUENCE:' || greatest(coalesce(p_sequenz, 0), 0))
    || CASE WHEN p_ganztags OR p_beginn IS NULL
         THEN ally_ics_zeile('DTSTART;VALUE=DATE:' || to_char(p_tag_beginn, 'YYYYMMDD')) || ally_ics_zeile('DTEND;VALUE=DATE:' || to_char(greatest(coalesce(p_tag_ende, p_tag_beginn), p_tag_beginn) + 1, 'YYYYMMDD'))
         ELSE ally_ics_zeile('DTSTART:' || ally_ics_utc(p_beginn)) || ally_ics_zeile('DTEND:' || ally_ics_utc(CASE WHEN p_ende IS NOT NULL AND p_ende > p_beginn THEN p_ende ELSE p_beginn + interval '30 minutes' END)) END
    || ally_ics_zeile('SUMMARY:' || ally_ics_text(left(p_titel, 250)))
    || CASE WHEN nullif(btrim(coalesce(p_text, '')), '') IS NOT NULL THEN ally_ics_zeile('DESCRIPTION:' || ally_ics_text(left(p_text, 3000))) ELSE '' END
    || CASE WHEN nullif(btrim(coalesce(p_ort, '')), '') IS NOT NULL THEN ally_ics_zeile('LOCATION:' || ally_ics_text(left(p_ort, 200))) ELSE '' END
    || ally_ics_zeile('STATUS:' || CASE WHEN p_abgesagt THEN 'CANCELLED' ELSE 'CONFIRMED' END)
    || ally_ics_zeile('TRANSP:' || CASE WHEN p_ganztags OR p_beginn IS NULL THEN 'TRANSPARENT' ELSE 'OPAQUE' END)
    || ally_ics_zeile('END:VEVENT')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_kalender(p_name text, p_ereignisse text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Rahmen eines Kalenders (RFC 5545): Name, Produkt aus den Einstellungen, Abruf-Empfehlung stündlich
  SELECT ally_ics_zeile('BEGIN:VCALENDAR') || ally_ics_zeile('VERSION:2.0')
    || ally_ics_zeile('PRODID:-//' || regexp_replace(produkt_name(), '[^A-Za-z0-9 ._-]', '', 'g') || '//Kalender//DE')
    || ally_ics_zeile('CALSCALE:GREGORIAN') || ally_ics_zeile('METHOD:PUBLISH')
    || ally_ics_zeile('X-WR-CALNAME:' || ally_ics_text(left(p_name, 120))) || ally_ics_zeile('X-WR-TIMEZONE:Europe/Berlin')
    || ally_ics_zeile('REFRESH-INTERVAL;VALUE=DURATION:PT1H') || ally_ics_zeile('X-PUBLISHED-TTL:PT1H')
    || coalesce(p_ereignisse, '') || ally_ics_zeile('END:VCALENDAR')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Text für iCalendar (RFC 5545, 3.3.11): Backslash, Semikolon, Komma und Zeilenumbruch maskieren, Steuerzeichen entfernen
  SELECT replace(replace(replace(replace(regexp_replace(replace(replace(coalesce(p, ''), E'\r\n', E'\n'), E'\r', E'\n'), '[\x01-\x09\x0b-\x1f\x7f]', ' ', 'g'),
    '\', '\\'), ';', '\;'), ',', '\,'), E'\n', '\n')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_utc(p timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT to_char(p AT TIME ZONE 'UTC', 'YYYYMMDD"T"HH24MISS"Z"')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ics_zeile(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  aus text := ''; teil text := ''; z text; n integer := 0; grenze integer := 75;
BEGIN
  -- Eine Inhaltszeile mit CRLF, gefaltet nach höchstens 75 Oktetten (RFC 5545, 3.1); Fortsetzungszeilen beginnen mit einem Leerzeichen.
  -- Gezählt wird in UTF-8-Oktetten, ein Zeichen wird nie geteilt.
  FOR z IN SELECT x FROM regexp_split_to_table(coalesce(p, ''), '') x LOOP
    IF n + octet_length(z) > grenze THEN
      aus := aus || teil || E'\r\n ';
      teil := ''; n := 0; grenze := 74;
    END IF;
    teil := teil || z; n := n + octet_length(z);
  END LOOP;
  RETURN aus || teil || E'\r\n';
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_kalender_abo_adresse(p_token text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Abo-Adresse: öffentliche Adresse der Oberfläche (n8n_oeffentlich, kein fester Wert) + /kalender?t=<Code>; NULL ohne eingerichtete Adresse
  SELECT CASE WHEN talent_ui_adresse() IS NOT NULL AND coalesce(p_token, '') ~ '^[0-9a-f]{64}$' THEN talent_ui_adresse() || '/kalender?t=' || p_token END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_kalender_abo_neu(p_person text, p_talent_id integer, p_von text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  tok text;
BEGIN
  -- Neue Abo-Adresse (die bisherige gilt danach nicht mehr). Genau einer von Person oder Talent.
  -- Testdaten (Migration 79): kein Kalender-Abo für Testdaten
  IF ally_person_ist_testdaten(p_person) OR talents_ist_testdaten(p_talent_id) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Für Testdaten gibt es kein Kalender-Abo.');
  END IF;
  IF (p_person IS NULL) = (p_talent_id IS NULL) THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Kalender.'); END IF;
  IF NOT ally_verschluesselung_bereit() OR talent_ui_adresse() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Abo-Adresse kann gerade nicht erstellt werden (Verschlüsselung oder öffentliche Adresse nicht eingerichtet).');
  END IF;
  UPDATE ally_kalender_abos SET widerrufen_am = now(), widerrufen_von = p_von
  WHERE widerrufen_am IS NULL AND (person = p_person OR talent_id = p_talent_id);
  tok := encode(gen_random_bytes(32), 'hex');
  INSERT INTO ally_kalender_abos (token_hash, token_verschluesselt, person, talent_id, erstellt_von) VALUES (ally_web_hash(tok), ally_verschluesseln(tok), p_person, p_talent_id, p_von);
  RETURN jsonb_build_object('ok', true, 'adresse', ally_kalender_abo_adresse(tok));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_kalender_abo_stand(p_person text, p_talent_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  a ally_kalender_abos%ROWTYPE; tok text := NULL;
BEGIN
  -- Stand des Kalender-Abos (aktive Adresse zum Kopieren, seit, letzter Abruf). Die Adresse nur für die Person bzw. das Talent selbst (Aufrufer prüft).
  SELECT * INTO a FROM ally_kalender_abos x WHERE x.widerrufen_am IS NULL AND (x.person = p_person OR x.talent_id = p_talent_id) ORDER BY x.id DESC LIMIT 1;
  IF a.id IS NULL THEN RETURN jsonb_build_object('aktiv', false, 'moeglich', ally_verschluesselung_bereit() AND talent_ui_adresse() IS NOT NULL); END IF;
  BEGIN
    tok := ally_entschluesseln(a.token_verschluesselt);
  EXCEPTION WHEN OTHERS THEN
    tok := NULL;
  END;
  RETURN jsonb_build_object('aktiv', true, 'moeglich', true, 'adresse', ally_kalender_abo_adresse(tok), 'seit', talents_zeit(a.erstellt_am),
    'letzter_abruf', CASE WHEN a.letzter_abruf IS NOT NULL THEN talents_zeit(a.letzter_abruf) END, 'abrufe', a.abrufe);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_kalender_abo_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
BEGIN
  -- Mein Kalender (ALLY 23, Person): eigenes Kalender-Abo und Stand der Google-Verbindung (vorbereitet)
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false); END IF;
  RETURN jsonb_build_object('ok', true, 'abo', ally_kalender_abo_stand(s.person, NULL),
    'google', jsonb_build_object('bereit', coalesce(ally_einstellung('google_kalender_bereit'), 'nein') = 'ja',
      'verbunden', EXISTS (SELECT 1 FROM ally_kalender_verbindungen v WHERE v.person = s.person AND v.schluessel IS NOT NULL),
      'admin', coalesce(ally_hat_recht(s.person, 'admin'), false)));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_kalender_ics(p_token text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  a ally_kalender_abos%ROWTYPE; sicht jsonb; ev text := ''; name text; firma text; d_von date := talents_heute() - 60; d_bis date := talents_heute() + 400; n integer := 0; rec record;
BEGIN
  -- Kalender-Abo (ALLY 19, GET app/kalender?t=<Code>): NULL = unbekannt, widerrufen oder nicht mehr berechtigt (Antwort 404).
  -- Talent: nur eigene Einträge mit Kanal „Kalender des Talents“ (Termine/Erinnerungen bei „Termine“ sichtbar, Aufgaben/Reviews bei „Aufgaben“ sichtbar)
  -- und Deadlines eigener, für das Talent sichtbarer Deliverables. Person: Aufgaben, Termine und Deadlines der Talents, für die sie zuständig ist,
  -- und der Kampagnen, für die sie zuständig ist (nur Talents, die sie sehen darf). Keine Honorare, Budgets oder Notizen. Zeitraum 60 Tage zurück bis 400 Tage voraus.
  IF coalesce(p_token, '') !~ '^[0-9a-f]{64}$' THEN RETURN NULL; END IF;
  SELECT * INTO a FROM ally_kalender_abos x WHERE x.token_hash = ally_web_hash(p_token) AND x.widerrufen_am IS NULL;
  IF NOT FOUND THEN RETURN NULL; END IF;
  firma := coalesce(nullif(btrim(coalesce(eigenes_unternehmen()->>'name', '')), ''), produkt_name());
  IF a.talent_id IS NOT NULL THEN
    IF NOT plattform_modul_an('talents') OR NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = a.talent_id AND t.status = 'aktiv')
       OR NOT EXISTS (SELECT 1 FROM talent_zugaenge z WHERE z.talent_id = a.talent_id AND z.aktiv) THEN
      RETURN NULL;
    END IF;
    sicht := talent_bereich_sicht(a.talent_id);
    name := firma || ' – Termine und Deadlines';
    FOR rec IN SELECT t.id FROM talent_aufgaben t
             WHERE t.talent_id = a.talent_id AND 'kalender' = ANY (t.kanaele) AND coalesce(t.beginn, t.faellig_am) IS NOT NULL
               AND (coalesce(t.beginn, t.faellig_am) AT TIME ZONE 'Europe/Berlin')::date BETWEEN d_von AND d_bis
               AND ((t.art IN ('termin', 'erinnerung') AND (sicht->>'termine')::boolean) OR (t.art IN ('aufgabe', 'review') AND (sicht->>'aufgaben')::boolean))
             ORDER BY coalesce(t.beginn, t.faellig_am), t.id LIMIT 600 LOOP
      ev := ev || coalesce(ally_ics_aufgabe(rec.id, false), ''); n := n + 1;
    END LOOP;
    IF (sicht->>'aufgaben')::boolean THEN
      FOR rec IN SELECT d.id, w.was FROM talent_deliverables d JOIN talent_kampagnen k ON k.id = d.kampagne_id AND k.abgebrochen_am IS NULL
               CROSS JOIN (VALUES ('deadline'), ('veroeffentlichung')) AS w(was)
               WHERE d.talent_id = a.talent_id AND d.sichtbar_fuer_talent
                 AND (CASE WHEN w.was = 'deadline' THEN d.deadline ELSE d.veroeffentlichen_am END) BETWEEN d_von AND d_bis
               ORDER BY d.deadline, d.id, w.was LIMIT 400 LOOP
        ev := ev || coalesce(ally_ics_deliverable(rec.id, rec.was, false), ''); n := n + 1;
      END LOOP;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = a.person AND p.aktiv AND p.zugang_aktiv) THEN RETURN NULL; END IF;
    name := produkt_name() || ' – meine Termine und Deadlines';
    IF plattform_modul_an('talents') THEN
      FOR rec IN SELECT t.id FROM talent_aufgaben t JOIN talents tt ON tt.id = t.talent_id AND tt.status = 'aktiv'
               WHERE EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.talent_id AND tp.matrix_user_id = a.person)
                 AND coalesce(t.beginn, t.faellig_am) IS NOT NULL AND (coalesce(t.beginn, t.faellig_am) AT TIME ZONE 'Europe/Berlin')::date BETWEEN d_von AND d_bis
               ORDER BY coalesce(t.beginn, t.faellig_am), t.id LIMIT 600 LOOP
        ev := ev || coalesce(ally_ics_aufgabe(rec.id, true), ''); n := n + 1;
      END LOOP;
      FOR rec IN SELECT DISTINCT d.id, w.was, d.deadline FROM talent_deliverables d JOIN talent_kampagnen k ON k.id = d.kampagne_id AND k.abgebrochen_am IS NULL
               JOIN talents tt ON tt.id = d.talent_id AND tt.status = 'aktiv'
               CROSS JOIN (VALUES ('deadline'), ('veroeffentlichung')) AS w(was)
               WHERE (EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = d.talent_id AND tp.matrix_user_id = a.person)
                      OR (k.zustaendig = a.person AND coalesce(talent_sichtbar(a.person, d.talent_id), false)))
                 AND (CASE WHEN w.was = 'deadline' THEN d.deadline ELSE d.veroeffentlichen_am END) BETWEEN d_von AND d_bis
               ORDER BY d.deadline, d.id, w.was LIMIT 400 LOOP
        ev := ev || coalesce(ally_ics_deliverable(rec.id, rec.was, true), ''); n := n + 1;
      END LOOP;
    END IF;
  END IF;
  UPDATE ally_kalender_abos SET letzter_abruf = now(), abrufe = abrufe + 1 WHERE id = a.id;
  RETURN ally_ics_kalender(name, ev);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ki_budget_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE s record; v plattform_vertrag%ROWTYPE;
BEGIN
  SELECT * INTO s FROM ally_ui_sitzung(p_token) x WHERE NOT x.muss_pw_setzen;
  IF NOT FOUND OR NOT coalesce(ally_hat_recht(s.person, 'admin'), false) THEN RETURN jsonb_build_object('ok', false); END IF;
  SELECT * INTO v FROM plattform_vertrag WHERE id = 1;
  RETURN jsonb_build_object('ok', true, 'ki_budget_eur', v.ki_budget_eur, 'budget_modus', v.budget_modus, 'warn_prozent', v.warn_prozent, 'spar_prozent', v.spar_prozent,
    'eigener_schluessel', v.ki_schluessel = 'kunde',
    'budget_modi', jsonb_build_array(
      jsonb_build_object('wert', 'sperre', 'name', 'Sperren, wenn das Budget erreicht ist'),
      jsonb_build_object('wert', 'nachberechnen', 'name', 'Weiterlaufen lassen, Mehrverbrauch wird nachberechnet')));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_luecken_ui_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  s record; e jsonb; r jsonb; fehler text := NULL; m text := NULL; weiter text := NULL; aus jsonb := NULL;
  typ text; groesse bigint; name text; endung text; kennung text;
BEGIN
  IF p_aktion IS NULL OR p_aktion NOT IN ('fragen', 'wochen_briefing_jetzt', 'be_hochladen') THEN RETURN NULL; END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF p_aktion = 'fragen' THEN
    r := ally_ui_aktion(p_token, p_csrf, p_aktion, d, p_zustand);
    IF r->>'weiter' = 'arbeit' AND coalesce(r->'r'->>'event_id', '') ~ '^web-[0-9a-f]{24}$' AND NOT s.muss_pw_setzen THEN
      INSERT INTO ally_assistent_verlauf (person, event_id, frage) VALUES (s.person, r->'r'->>'event_id', left(coalesce(r->'r'->>'text', ''), 2000))
      ON CONFLICT (event_id) DO NOTHING;
    END IF;
    RETURN r;
  END IF;
  IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN
    PERFORM ally_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ungueltig', true);
  END IF;
  IF s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'muss_pw_setzen', true); END IF;
  IF jsonb_typeof(p_zustand->'z') = 'array' THEN
    FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
      IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN
        PERFORM ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen'));
      END IF;
    END LOOP;
  END IF;

  IF p_aktion = 'wochen_briefing_jetzt' THEN
    IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'talents') THEN
      fehler := 'Talents sind für dich nicht freigeschaltet.';
    -- Migration 177 (B10b, Briefings): alle Briefings, die die Person bekommt
    ELSIF NOT EXISTS (SELECT 1 FROM talents_briefings b CROSS JOIN LATERAL talents_briefing_empfaenger(b.id) x
                      WHERE b.art = 'manager' AND b.geloescht_am IS NULL AND x.user_id = s.person) THEN
      fehler := 'Für dich gibt es keine KI-Analyse, deshalb erstellt Ally keine. KI-Analysen gehen an ihre Empfänger mit eingeschalteten KI-Analysen (Einstellungen › Benachrichtigungen).';
    ELSIF EXISTS (SELECT 1 FROM ally_nutzer_einstellungen x WHERE x.matrix_user_id = s.person AND x.schluessel = 'web_start_wochen_briefing' AND x.geaendert_am > now() - interval '3 minutes') THEN
      fehler := 'Gerade erstellt Ally schon KI-Analysen für dich. Bitte einen Moment warten und die Seite neu laden.';
    ELSE
      INSERT INTO ally_nutzer_einstellungen (matrix_user_id, schluessel, wert, geaendert_am) VALUES (s.person, 'web_start_wochen_briefing', 'ja', now())
      ON CONFLICT (matrix_user_id, schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
      weiter := 'start'; aus := jsonb_build_object('was', 'wochen_briefing', 'nutzer', s.person);
      m := 'Deine KI-Analysen werden erstellt.';
    END IF;

  ELSIF p_aktion = 'be_hochladen' THEN
    typ := lower(btrim(coalesce(d->>'datei_typ', '')));
    groesse := CASE WHEN coalesce(d->>'datei_groesse', '') ~ '^[0-9]{1,12}$' THEN (d->>'datei_groesse')::bigint ELSE 0 END;
    name := left(regexp_replace(btrim(coalesce(d->>'datei_name', '')), '[\x00-\x1f\x7f]', ' ', 'g'), 120);
    endung := CASE WHEN typ IN ('application/xml', 'text/xml') THEN 'xml' ELSE 'pdf' END;
    IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'belege') THEN
      fehler := 'Belege sind für dich nicht freigeschaltet.';
    ELSIF groesse <= 0 THEN
      fehler := 'Bitte eine Datei auswählen.';
    ELSIF typ NOT IN ('application/pdf', 'application/xml', 'text/xml', 'image/jpeg', 'image/png', 'image/webp') THEN
      fehler := 'Diese Datei kann nicht als Beleg verarbeitet werden. Bitte als PDF, E-Rechnung (XML) oder Foto (JPG, PNG, WEBP) hochladen.';
    ELSIF groesse > 10485760 THEN
      fehler := 'Die Datei ist größer als 10 MB.';
    ELSIF (SELECT count(*) FROM beleg_verarbeitung x WHERE x.source_mailbox = 'ally-web' AND x.sender = s.person AND x.created_at > localtimestamp - interval '1 hour') >= 30 THEN
      fehler := 'Es sind schon viele Belege in der letzten Stunde hochgeladen worden. Bitte etwas warten.';
    ELSE
      kennung := 'web-' || encode(gen_random_bytes(12), 'hex');
      weiter := 'beleg';
      aus := jsonb_build_object('pfad', 'Belegerfassung/Belege-Staging/' || to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD_HH24-MI-SS') || '_ally-web_' || encode(gen_random_bytes(3), 'hex') || '.' || endung,
        'kennung', kennung, 'name', coalesce(nullif(name, ''), 'Beleg'), 'typ', typ, 'bild', typ LIKE 'image/%');
    END IF;
  END IF;

  IF coalesce(fehler, m) IS NOT NULL THEN
    PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  END IF;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'fertig', false, 'weiter', CASE WHEN fehler IS NULL THEN weiter END,
    'r', CASE WHEN fehler IS NULL AND weiter IS NOT NULL THEN aus END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_mail_cd_html(p_titel text, p_bloecke jsonb, p_fuss text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c ally_cd%ROWTYPE; dunkel text; hell text; schrift text; firma text; logo jsonb := ally_mail_logo(); b jsonb; inhalt text := ''; kopf text; lk text;
BEGIN
  -- Migration 192 (Konzept Einladungsmail, Teil 3): Rahmen einer Mail im Corporate Design wie ally_systemnachricht_inhalt (Box 560 px, Kopfleiste in Dunkel,
  -- Schrift aus dem CD mit Rückfall Arial). Kopf: Logo als Bild (ally_mail_logo, nur PNG) mit dem Firmennamen als alt, sonst der Firmenname als Text.
  -- Blöcke: absatz (Text; Zeilenumbrüche bleiben), knopf (Text und Link; darunter der Link als Text, ohne Link nur der Hinweis „[Einladungslink]“),
  -- html (fertiges HTML, z. B. Signatur des Postfachs). Texte laufen durch ally_html. ally_systemnachricht_inhalt bleibt in diesem Schritt unverändert.
  SELECT x.* INTO c FROM ally_cd x WHERE x.unternehmen_id = (SELECT f.unternehmen_id FROM ally_firma f ORDER BY f.id LIMIT 1);
  dunkel := CASE WHEN coalesce(c.farbe_dunkel, '') ~ '^#[0-9A-Fa-f]{6}$' THEN c.farbe_dunkel ELSE '#1F2933' END;
  hell := CASE WHEN coalesce(c.farbe_text_auf_dunkel, '') ~ '^#[0-9A-Fa-f]{6}$' THEN c.farbe_text_auf_dunkel ELSE '#FFFFFF' END;
  schrift := CASE WHEN coalesce(c.schrift, '') ~ '^[A-Za-z0-9 ]{1,60}$' THEN '''' || c.schrift || ''',' ELSE '' END;
  firma := coalesce(nullif(btrim(coalesce(eigenes_unternehmen()->>'name', '')), ''), produkt_name());
  kopf := CASE WHEN logo IS NOT NULL
    THEN '<div style="background:' || dunkel || ';padding:12px 20px"><img src="' || ally_html(logo->>'url') || '" width="' || (logo->>'breite') || '" height="' || (logo->>'hoehe')
      || '" alt="' || ally_html(firma) || '" style="display:block;border:0;width:' || (logo->>'breite') || 'px;height:' || (logo->>'hoehe') || 'px;max-width:100%;color:' || hell
      || ';font-size:14px;line-height:18px;font-weight:700"></div>'
    ELSE '<div style="background:' || dunkel || ';color:' || hell || ';padding:14px 20px;font-size:18px;font-weight:700">' || ally_html(firma) || '</div>' END;
  FOR b IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_bloecke) = 'array' THEN p_bloecke ELSE '[]'::jsonb END) x LOOP
    IF b->>'art' = 'absatz' AND btrim(coalesce(b->>'text', '')) <> '' THEN
      inhalt := inhalt || '<p style="margin:0 0 14px">' || replace(ally_html(b->>'text'), E'\n', '<br>') || '</p>';
    ELSIF b->>'art' = 'knopf' THEN
      lk := btrim(coalesce(b->>'link', ''));
      inhalt := inhalt || '<p style="margin:18px 0">' || CASE WHEN lk ~ '^https://' THEN '<a href="' || ally_html(lk) || '" ' ELSE '<span ' END
        || 'style="display:inline-block;background:' || dunkel || ';color:' || hell || ';text-decoration:none;padding:12px 18px;border-radius:8px;font-weight:600">'
        || ally_html(coalesce(b->>'text', '')) || CASE WHEN lk ~ '^https://' THEN '</a>' ELSE '</span>' END || '</p>'
        || '<p style="margin:0 0 14px;font-size:13px;color:#5B6470;word-break:break-all">Falls der Knopf nicht funktioniert, diesen Link öffnen:<br>'
        || ally_html(CASE WHEN lk ~ '^https://' THEN lk ELSE '[Einladungslink]' END) || '</p>';
    ELSIF b->>'art' = 'html' AND btrim(coalesce(b->>'html', '')) <> '' THEN
      inhalt := inhalt || '<div style="margin:18px 0 0">' || (b->>'html') || '</div>';
    END IF;
  END LOOP;
  RETURN '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' || ally_html(p_titel) || '</title></head>'
    || '<body style="margin:0;padding:24px 12px;background:#F4F5F7;font-family:' || schrift || 'Arial,Helvetica,sans-serif;color:#1F2933">'
    || '<div style="max-width:560px;margin:0 auto;background:#FFFFFF;border:1px solid #E1E4E8;border-radius:10px;overflow:hidden">' || kopf
    || '<div style="padding:20px;font-size:15px;line-height:1.5">' || inhalt || '</div></div>'
    || CASE WHEN btrim(coalesce(p_fuss, '')) <> '' THEN '<p style="max-width:560px;margin:12px auto 0;font-size:12px;color:#5B6470">' || ally_html(p_fuss) || '</p>' ELSE '' END
    || '</body></html>';
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_mail_gueltig(p text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Mailadresse für Systemnachrichten: einfache Form, kleingeschrieben, ohne Zeichen, die Kopfzeilen einer Mail verändern könnten
  SELECT coalesce(p, '') = lower(btrim(coalesce(p, ''))) AND length(coalesce(p, '')) <= 254
     AND coalesce(p, '') ~ '^[^[:space:]@<>",;:()\\]{1,200}@[^[:space:]@<>",;:()\\]{1,200}\.[^[:space:]@.<>",;:()\\]{1,63}$'
     -- Testdaten (Migration 79): an .invalid geht nie eine Mail (reservierte Domain)
     AND coalesce(p, '') !~ '[.]invalid$'
$function$
;

CREATE OR REPLACE FUNCTION public.ally_mail_logo()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  l jsonb := ally_cd_logo_mail(false); basis text := rtrim(btrim(coalesce(ally_einstellung('n8n_oeffentlich'), '')), '/'); w numeric; h numeric; bw integer; bh integer;
BEGIN
  -- Migration 192: Logo der Mail im Kopf (feste Adresse auf dem n8n-Host, öffentlicher Pfad web/ wie die Einladung; ALLY 16 „Logo“). Höhe 36 px, höchstens 220 px breit.
  -- NULL ohne PNG-Logo oder ohne öffentliche Adresse: dann steht der Firmenname im Kopf.
  IF l IS NULL OR basis !~ '^https://[A-Za-z0-9.-]{3,253}(:[0-9]{1,5})?(/[A-Za-z0-9._~-]+)*$' THEN RETURN NULL; END IF;
  w := (l->>'breite')::numeric; h := (l->>'hoehe')::numeric;
  bh := 36; bw := greatest(1, round(w * 36 / h)::integer);
  IF bw > 220 THEN bw := 220; bh := greatest(1, round(h * 220 / w)::integer); END IF;
  RETURN jsonb_build_object('url', basis || '/webhook/web/cd-logo?v=' || (l->>'v'), 'breite', bw, 'hoehe', bh);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_nutzer_rechte_rolle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Trigger (Stefan 19.10.2026, Migration 56): Rolle an direkt geänderte Rechte angleichen
  IF TG_OP IN ('UPDATE', 'DELETE') THEN PERFORM ally_person_rolle_abgleichen(OLD.matrix_user_id); END IF;
  IF TG_OP IN ('UPDATE', 'INSERT') THEN PERFORM ally_person_rolle_abgleichen(NEW.matrix_user_id); END IF;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_nutzer_token(p_user text, p_name text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN p_name IN ('linkedin_token', 'instagram_token') AND p_user IS NOT NULL
    THEN coalesce(nullif(ally_geheim(ally_nutzer_token_schluessel(p_user, p_name)), ''), NULL, '') ELSE '' END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_nutzer_token_schluessel(p_user text, p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT p_name || '__' || md5(coalesce(p_user, ''))
$function$
;

CREATE OR REPLACE FUNCTION public.ally_nutzer_token_setzen(p_user text, p_name text, p_wert text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF p_name IS NULL OR p_name NOT IN ('linkedin_token', 'instagram_token') OR coalesce(p_user, '') = '' THEN RAISE EXCEPTION 'Unbekanntes Zugangstoken.'; END IF;
  PERFORM ally_geheim_setzen(ally_nutzer_token_schluessel(p_user, p_name), p_wert, p_user);
  DELETE FROM ally_nutzer_einstellungen WHERE matrix_user_id = p_user AND schluessel = p_name;
  RETURN true;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_nutzer_token_vorhanden(p_user text, p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT p_name IN ('linkedin_token', 'instagram_token') AND p_user IS NOT NULL
    AND (ally_geheim_vorhanden(ally_nutzer_token_schluessel(p_user, p_name)) OR NULL IS NOT NULL)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_nutzer_wert(p_user text, p_schluessel text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(
    (SELECT wert FROM ally_nutzer_einstellungen WHERE matrix_user_id = p_user AND schluessel = p_schluessel),
    (SELECT wert FROM ally_einstellungen WHERE schluessel = p_schluessel))
$function$
;

CREATE OR REPLACE FUNCTION public.ally_oberflaeche_adresse()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 74 (BA11, Stefan 21.10.2026): eigene Adresse der Oberfläche (Einstellung oberflaeche_adresse, z. B. https://ally.firma.de, ohne Pfad und Port).
  -- Nur ein gültiger Wert zählt, sonst NULL (dann gilt die bisherige Adresse unter /webhook/app). Muss zur Server-Einrichtung (traefik) passen.
  SELECT CASE WHEN lower(btrim(ally_einstellung('oberflaeche_adresse'))) ~ '^https://[a-z0-9.-]{3,253}$' THEN lower(btrim(ally_einstellung('oberflaeche_adresse'))) END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_oberflaeche_intern()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 74 (BA11): bisherige Adresse der Oberfläche auf dem n8n-Host (n8n_oeffentlich + /webhook/app, Formel bis Migration 73 in talent_ui_adresse); NULL, wenn nicht eingerichtet.
  -- Für Wege, die auf dem n8n-Host laufen (Rückweg nach „Verbinden“ aus ALLY 16), unabhängig von der eigenen Adresse der Oberfläche.
  SELECT CASE WHEN rtrim(btrim(ally_einstellung('n8n_oeffentlich')), '/') ~ '^https://[A-Za-z0-9.-]{3,253}(:[0-9]{1,5})?(/[A-Za-z0-9._~-]+)*$'
              THEN rtrim(btrim(ally_einstellung('n8n_oeffentlich')), '/') || '/webhook/app' END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_oberflaeche_web_daten(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
BEGIN
  -- Migration 74 (BA11): Anzeige für Einstellungen › Superadmin › Adressen (ALLY 23). Nur Superadmin, sonst NULL. Keine Geheimnisse.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen OR NOT ally_hat_recht(s.person, 'superadmin') THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('ok', true,
    'adresse', btrim(ally_einstellung('oberflaeche_adresse')),
    'gueltig', ally_oberflaeche_adresse() IS NOT NULL,
    'aktuell', talent_ui_adresse(),
    'bisher', ally_oberflaeche_intern(),
    'n8n', rtrim(btrim(ally_einstellung('n8n_oeffentlich')), '/'),
    'geaendert', (SELECT to_char(e.geaendert_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI') || coalesce(' · ' || nullif(e.geaendert_von, ''), '')
                  FROM ally_einstellungen e WHERE e.schluessel = 'oberflaeche_adresse' AND coalesce(e.geaendert_von, '') <> ''));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_oberflaeche_webhook()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 74 (BA11): Grundlage für Links in die Abläufe der bisherigen Oberfläche (ALLY 8, 9, 12, 15; .../webhook). Gleicher Host wie die Oberfläche, weil das
  -- Cookie ally_sitzung (ALLY 20 „Link weiterleiten“) nur für den Host der Antwort gilt: mit eigener Adresse <adresse>/webhook, sonst wie bis Migration 73
  -- (bisherige Adresse ohne /app, leer ohne eingerichtete Adresse).
  SELECT CASE WHEN ally_oberflaeche_adresse() IS NOT NULL THEN ally_oberflaeche_adresse() || '/webhook'
              ELSE regexp_replace(coalesce(ally_oberflaeche_intern(), ''), '/app$', '') END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_person_anlegen_abschliessen(p_auftrag_id bigint, p_ok boolean, p_fehler text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a record;
  em text;
  pid integer;
  code text := split_part(coalesce(p_fehler, ''), ':', 1);
  m text;
BEGIN
  -- Person anlegen, Schritt 2 (Stefan 19.10.2026, Migration 56): nach ALLY 18. ok -> Person mit matrix_user_id, Rolle, Funktionen, Talents, Postfächern;
  -- sonst Reservierung freigeben (Auftrag "fehler") und Grund melden. Ist offen, ob der Chat-Benutzer entstanden ist, wird die Kennung gesperrt.
  SELECT * INTO a FROM ally_chat_auftraege WHERE id = p_auftrag_id FOR UPDATE;
  IF NOT FOUND OR a.art <> 'anlegen' OR a.status NOT IN ('offen', 'in_arbeit') THEN
    RETURN jsonb_build_object('ok', false, 'auftrag_id', p_auftrag_id, 'fehler', 'nicht_in_arbeit', 'meldung', 'Der Auftrag ist nicht (mehr) offen.');
  END IF;
  IF coalesce(p_ok, false) AND EXISTS (SELECT 1 FROM ally_personen WHERE matrix_user_id = a.matrix_user_id) THEN
    p_ok := false; code := 'doppelt';
  END IF;
  IF NOT coalesce(p_ok, false) THEN
    IF code NOT IN ('zugang', 'zeitueberschreitung', 'verbindung', 'belegt', 'vorhanden', 'unklar', 'ungueltig', 'doppelt', 'einstellung', 'fremder_server') THEN
      code := 'server';
    END IF;
    IF code IN ('vorhanden', 'unklar', 'doppelt') THEN
      INSERT INTO ally_chat_kennungen (kennung, matrix_user_id, art) VALUES (a.kennung, a.matrix_user_id, 'fremd') ON CONFLICT DO NOTHING;
    END IF;
    m := a.anzeigename || ' wurde nicht angelegt. ' || ally_chat_fehler_text(code);
    UPDATE ally_chat_auftraege SET status = 'fehler', fehler = left(coalesce(nullif(p_fehler, ''), code), 200), meldung = m, erledigt_am = now() WHERE id = a.id;
    RETURN jsonb_build_object('ok', false, 'auftrag_id', a.id, 'art', a.art, 'kennung', a.kennung, 'fehler', code, 'meldung', m);
  END IF;

  em := a.daten->>'email';
  IF em IS NOT NULL AND EXISTS (SELECT 1 FROM ally_personen WHERE email = em) THEN
    em := NULL;
  END IF;
  INSERT INTO ally_personen (matrix_user_id, name, email, aktiv, rolle) VALUES (a.matrix_user_id, a.anzeigename, em, true, a.daten->>'rolle')
  RETURNING id INTO pid;
  INSERT INTO ally_chat_kennungen (kennung, matrix_user_id, art, ref_id) VALUES (a.kennung, a.matrix_user_id, 'person', pid)
  ON CONFLICT (kennung) DO UPDATE SET art = 'person', ref_id = EXCLUDED.ref_id WHERE ally_chat_kennungen.matrix_user_id = EXCLUDED.matrix_user_id;
  PERFORM ally_person_rolle_anwenden(a.matrix_user_id, a.daten->>'rolle',
    ARRAY(SELECT x FROM jsonb_array_elements_text(coalesce(a.daten->'funktionen', '[]'::jsonb)) AS x));
  INSERT INTO talent_personen (talent_id, matrix_user_id)
  SELECT x::integer, a.matrix_user_id FROM jsonb_array_elements_text(coalesce(a.daten->'talents', '[]'::jsonb)) AS x
  WHERE EXISTS (SELECT 1 FROM talents t WHERE t.id = x::integer) ON CONFLICT DO NOTHING;
  -- Migration 90: keine Zuständigkeit je Postfach mehr (gemeinsame Postfächer sieht, wer das Recht aus der Rolle hat; persönliche nur die Person selbst)
  m := a.anzeigename || ' angelegt. Chat-Konto: ' || a.matrix_user_id || '. Jetzt einen Zugang mit Startcode erzeugen.'
    || CASE WHEN em IS NULL AND a.daten->>'email' IS NOT NULL THEN ' Die E-Mail-Adresse gehört inzwischen zu einer anderen Person, bitte eine andere eintragen.' ELSE '' END;
  UPDATE ally_chat_auftraege SET status = 'erledigt', fehler = NULL, meldung = m, ref_id = pid, daten = '{}'::jsonb, erledigt_am = now() WHERE id = a.id;
  RETURN jsonb_build_object('ok', true, 'auftrag_id', a.id, 'art', a.art, 'kennung', a.kennung, 'matrix_user_id', a.matrix_user_id, 'person_id', pid, 'meldung', m);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_person_ausnahme_setzen(p_person text, p_recht text, p_an boolean, p_von text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  rolle boolean; tid integer;
BEGIN
  -- Migration 162 (Bauplan B5a, F6): Ausnahme je Person zur Rolle. Ohne Änderung bleiben Eintrag und Änderungsangaben, wie sie sind.
  -- Migration 166 (Bauplan B5d, Prüfbericht M162 N3): eigene Berechtigungsprüfung; Team-Personen über ally_person_eigene_rechte_setzen.
  IF NOT ally_person_ist_talent(p_person) THEN
    RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Eigene Rechte einer Team-Person setzt ein Admin im Person-Fenster.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM ally_rechte z WHERE z.schluessel = p_recht AND z.nur_selbst) THEN
    RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Ein Talent bekommt nur Rechte aus der Gruppe „Talent-Bereich“.';
  END IF;
  SELECT p.talent_id INTO tid FROM ally_personen p WHERE p.matrix_user_id = p_person;
  IF p_von IS NULL OR NOT coalesce(talent_zugang_darf(p_von, tid), false) THEN
    RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', MESSAGE = 'Das darf, wer für dieses Talent das Recht „Talent-Zugang und Talent-Bereich einstellen“ hat.';
  END IF;
  rolle := EXISTS (SELECT 1 FROM ally_personen p JOIN ally_rollen ro ON ro.schluessel = p.rolle AND ro.art IN ('eigen', 'talent') AND ro.archiviert_am IS NULL
                   JOIN ally_rollen_rechte rr ON rr.rolle = ro.schluessel AND rr.recht = p_recht
                   WHERE p.matrix_user_id = p_person);
  IF p_an = rolle THEN
    DELETE FROM ally_person_rechte r WHERE r.person = p_person AND r.recht = p_recht;
  ELSE
    INSERT INTO ally_person_rechte (person, recht, wirkung, reichweite, geaendert_von)
    VALUES (p_person, p_recht, CASE WHEN p_an THEN 'plus' ELSE 'minus' END, NULL, p_von)
    ON CONFLICT (person, recht) DO UPDATE SET wirkung = EXCLUDED.wirkung, reichweite = EXCLUDED.reichweite, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von
    WHERE (ally_person_rechte.wirkung, ally_person_rechte.reichweite) IS DISTINCT FROM (EXCLUDED.wirkung, EXCLUDED.reichweite);
  END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_person_deaktivieren(p_sitzung text, p_person text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  u text;
  ziel text := btrim(coalesce(p_person, ''));
  p record;
  kn record;
  ein jsonb := ally_chat_einrichtung();
  aid bigint;
  m text;
BEGIN
  -- Person deaktivieren (Stefan 19.10.2026, Migration 56): kein Chat mit dem Assistenten, keine Anmeldung; Rechte und Zuständigkeiten bleiben.
  -- Der Chat-Benutzer wird per Auftrag (ALLY 18) deaktiviert; die Kennung bleibt gesperrt.
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_sitzung);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND, 'fehler', 'Bitte neu anmelden.');
  END IF;
  u := s.matrix_user_id;
  IF NOT ally_hat_recht(u, 'admin') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Personen verwalten nur Admins.');
  END IF;
  SELECT * INTO p FROM ally_personen WHERE matrix_user_id = ziel;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte Person.');
  ELSIF ally_person_ist_talent(ziel) THEN  -- Migration 158 (Bauplan B3a): Talent-Personen ändert man im Talent-Profil.
    RETURN jsonb_build_object('ok', false, 'fehler', 'Den Zugang eines Talents änderst du im Talent-Profil.');
  ELSIF ziel = u THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Du kannst dich nicht selbst deaktivieren.');
  ELSIF ally_person_superadmin(ziel) AND NOT ally_hat_recht(u, 'superadmin') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Person ist Superadmin. Änderungen an ihr nehmen nur Superadmins vor.');
  -- Migration 172 (B8b, Fixieren): ist das Admin-Recht der Person fixiert, deaktiviert sie nur ein Superadmin
  ELSIF ally_fix_person_geschuetzt(ziel, u) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Admin-Recht von ' || p.name || ' ist fixiert. Deaktivieren kann sie nur ein Superadmin.');
  END IF;
  UPDATE ally_personen SET aktiv = false, geaendert_am = now() WHERE matrix_user_id = ziel AND aktiv;
  DELETE FROM ally_web_sitzungen WHERE matrix_user_id = ziel;
  m := p.name || ' deaktiviert: keine Anmeldung und kein Chat mit ' || produkt_name() || ' mehr. Rechte und Zuordnungen als Manager/in bleiben gespeichert.';
  SELECT * INTO kn FROM ally_chat_kennungen k WHERE k.matrix_user_id = ziel;
  IF FOUND AND kn.deaktiviert_am IS NULL AND (ein->>'ok')::boolean AND substring(ziel FROM '^@[^:]+:(.*)$') = ein->>'server_name' THEN
    SELECT a.id INTO aid FROM ally_chat_auftraege a WHERE a.art = 'deaktivieren' AND a.matrix_user_id = ziel AND a.status IN ('offen', 'in_arbeit') LIMIT 1;
    IF aid IS NULL THEN
      INSERT INTO ally_chat_auftraege (art, kennung, matrix_user_id, anzeigename, ref_art, ref_id, erstellt_von)
      VALUES ('deaktivieren', kn.kennung, ziel, p.name, 'person', p.id, u) RETURNING id INTO aid;
    END IF;
    m := m || ' Das Chat-Konto wird deaktiviert.';
  ELSIF FOUND AND kn.deaktiviert_am IS NULL AND (ein->>'ok')::boolean THEN
    m := m || ' Das Chat-Konto liegt nicht auf dem eingerichteten Chat-Server und bleibt bestehen.';
  END IF;
  RETURN jsonb_build_object('ok', true, 'auftrag_id', aid, 'meldung', m);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_person_eigene_rechte_setzen(p_sitzung text, p_person text, p_rechte jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; ziel text := btrim(coalesce(p_person, '')); nm text; ro text; pr jsonb; basis jsonb; ein jsonb; k text; soll text; b text; n integer := 0; z ally_rechte%ROWTYPE;
BEGIN
  -- Migration 166 (Bauplan B5d, Stefan G4): Zusätzlich zur Rolle eigene Rechte je Person (gilt für Team-Personen; Talents im Talent-Profil).
  -- Eingabe {recht: 'ja' | 'zugeordnet' | 'alle'} für alle gewählten Rechte des Katalogs (ally_person_rechte_katalog); nicht genannte = „Kein Recht“.
  -- Je Recht: wie die Rolle (Basis: Rolle und alte Einzelrechte) = kein Eintrag; „Kein Recht“ = minus; mehr als die Rolle = plus mit Reichweite.
  -- Weniger Reichweite als die Rolle geht nicht (minus nimmt das Recht ganz). Unveränderte Einträge behalten ihre Änderungsangaben.
  SELECT * INTO s FROM ally_ui_sitzung(p_sitzung);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Bitte neu anmelden.'); END IF;
  IF NOT ally_hat_recht(s.person, 'admin') THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Rechte vergibt eine Person mit der Rolle Admin.'); END IF;
  SELECT p.name, p.rolle INTO nm, ro FROM ally_personen p WHERE p.matrix_user_id = ziel AND p.aktiv;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte oder deaktivierte Person.'); END IF;
  -- Migration 167 (Bauplan B6): Prüfbericht M166 N6: auch eine Person mit einer Rolle der Art talent gilt hier als Talent.
  IF ally_person_ist_talent(ziel) OR ally_rolle_ist_talent(ro) THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Den Zugang und die Rolle eines Talents änderst du im Talent-Profil.'); END IF;
  IF ally_person_superadmin(ziel) AND NOT ally_hat_recht(s.person, 'superadmin') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Person ist Superadmin. Änderungen an ihr nehmen nur Superadmins vor.');
  END IF;
  IF ro = 'admin' OR EXISTS (SELECT 1 FROM ally_nutzer_rechte n WHERE n.matrix_user_id = ziel AND n.recht IN ('admin', 'superadmin')) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Eine Person mit der Rolle Admin hat alle Rechte. Eigene Rechte gibt es bei den anderen Rollen.');
  END IF;
  -- Migration 167 (Bauplan B6): Prüfbericht M166 N2: eine fehlende oder kaputte Angabe abgelehnt (ein leeres Objekt heißt weiter „alles Kein Recht“).
  IF jsonb_typeof(p_rechte) IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Rechte konnten nicht gelesen werden. Bitte die Seite neu laden.');
  END IF;
  ein := p_rechte;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(ein) e(k) WHERE NOT e.k IN (SELECT ally_person_rechte_katalog())) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'In der Auswahl ist ein unbekanntes Recht. Bitte die Seite neu laden.');
  END IF;
  -- Prüfen und vereinheitlichen wie bei Rollen (R1: Talent-Rechte bringen „Talents ansehen“ mit; R2: nie weiter als „Talents ansehen“)
  pr := ally_rolle_rechte_pruefen(ein);
  IF NOT coalesce((pr->>'ok')::boolean, false) THEN RETURN jsonb_build_object('ok', false, 'fehler', replace(pr->>'fehler', 'wenn die Rolle auch', 'wenn die Person auch')); END IF;
  basis := ally_person_rechte_basis(ziel);
  FOR k IN SELECT ally_person_rechte_katalog() LOOP
    soll := CASE WHEN (pr->'rechte') ? k THEN coalesce(pr->'rechte'->>k, 'alle') END;
    b := basis->>k;
    -- R1 ergänzt „Talents ansehen“; fehlt es in der Eingabe und hat die Basis es nicht, entsteht dafür kein eigener Eintrag
    IF k = 'talents_ansehen' AND NOT ein ? k AND b IS NULL THEN soll := NULL; END IF;
    IF soll IS NOT NULL AND b IS NOT NULL AND ally_recht_stufe(soll) < ally_recht_stufe(b) THEN
      -- Migration 167 (Bauplan B6): Prüfbericht M166 N1: „Kein Recht“ bei „Talents ansehen“, ein anderes Talent-Recht bleibt (R1 ergänzt Ansehen)
      IF k = 'talents_ansehen' AND NOT ein ? k THEN
        RETURN jsonb_build_object('ok', false, 'fehler', '„Talents ansehen“ gehört zu den übrigen Talent-Rechten und lässt sich nur zusammen mit ihnen wegnehmen.');
      END IF;
      SELECT * INTO z FROM ally_rechte x WHERE x.schluessel = k;
      RETURN jsonb_build_object('ok', false, 'fehler', 'Bei „' || coalesce(z.katalog_name, z.name) || '“ gibt die Rolle schon alle Talents. Weniger geht nur mit „Kein Recht“.');
    END IF;
  END LOOP;
  FOR k IN SELECT ally_person_rechte_katalog() LOOP
    soll := CASE WHEN (pr->'rechte') ? k THEN coalesce(pr->'rechte'->>k, 'alle') END;
    b := basis->>k;
    IF k = 'talents_ansehen' AND NOT ein ? k AND b IS NULL THEN soll := NULL; END IF;
    SELECT * INTO z FROM ally_rechte x WHERE x.schluessel = k;
    IF soll IS NOT DISTINCT FROM b THEN
      DELETE FROM ally_person_rechte r WHERE r.person = ziel AND r.recht = k;
    ELSE
      INSERT INTO ally_person_rechte (person, recht, wirkung, reichweite, geaendert_von)
      VALUES (ziel, k, CASE WHEN soll IS NULL THEN 'minus' ELSE 'plus' END, CASE WHEN soll IS NOT NULL AND z.reichweite THEN soll END, s.person)
      ON CONFLICT (person, recht) DO UPDATE SET wirkung = EXCLUDED.wirkung, reichweite = EXCLUDED.reichweite, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von
      WHERE (ally_person_rechte.wirkung, ally_person_rechte.reichweite) IS DISTINCT FROM (EXCLUDED.wirkung, EXCLUDED.reichweite);
      n := n + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'meldung', 'Rechte von ' || nm || ' gespeichert.'
    || CASE WHEN n = 0 THEN ' Sie entsprechen der Rolle.' WHEN n = 1 THEN ' 1 Recht weicht von der Rolle ab.' ELSE ' ' || n || ' Rechte weichen von der Rolle ab.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_person_ist_talent(p_user text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 158 (Bauplan B3a): Talent-Personen haben die Rolle der Art talent (die Rolle „Talent“) und eine talent_id. Sie erscheinen nicht als Team-Person.
  SELECT EXISTS (SELECT 1 FROM ally_personen p JOIN ally_rollen r ON r.schluessel = p.rolle AND r.art = 'talent'
                 WHERE p.matrix_user_id = p_user AND p.talent_id IS NOT NULL)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_person_ist_testdaten(p_person text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 79: ist die Person eine Test-Person? (NULL oder unbekannt: nein)
  SELECT coalesce((SELECT p.testdaten FROM ally_personen p WHERE p.matrix_user_id = p_person), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_person_rechte_basis(p_user text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 166 (Bauplan B5d, G4): {recht: 'alle' | 'zugeordnet' | 'selbst'}; ally_recht_roh = diese Basis, dazu plus (Maximum), minus nimmt das Recht ganz.
  -- Migration 167 (Bauplan B6): ohne einzeln vergebene Rechte der alten Oberfläche (F13); die Basis ist die Rolle.
  SELECT coalesce(jsonb_object_agg(x.recht, x.r), '{}'::jsonb) FROM (
    SELECT q.recht, CASE WHEN max(ally_recht_stufe(q.r)) = 2 THEN 'alle' WHEN max(ally_recht_stufe(q.r)) = 1 THEN 'zugeordnet' WHEN bool_or(q.r = 'selbst') THEN 'selbst' END AS r
    FROM (
      SELECT rr.recht, coalesce(rr.reichweite, 'alle') AS r
      FROM ally_personen p
      JOIN ally_rollen ro ON ro.schluessel = p.rolle AND ro.art IN ('eigen', 'talent') AND ro.archiviert_am IS NULL
      JOIN ally_rollen_rechte rr ON rr.rolle = ro.schluessel
      WHERE p.matrix_user_id = p_user AND p.aktiv
    ) q GROUP BY q.recht) x
  WHERE x.r IS NOT NULL
$function$
;

CREATE OR REPLACE FUNCTION public.ally_person_rechte_katalog()
 RETURNS SETOF text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 166 (Bauplan B5d, G4).
  SELECT z.schluessel FROM ally_rechte z
  WHERE z.katalog_gruppe IS NOT NULL AND z.schluessel NOT IN ('admin', 'superadmin') AND NOT z.nur_selbst AND (z.modul IS NULL OR plattform_modul_an(z.modul))
    AND (ally_postfach_platz_recht(z.schluessel) IS NULL OR ally_postfach_platz_adresse(ally_postfach_platz_recht(z.schluessel)) IS NOT NULL)
    AND (z.schluessel <> 'speicherort_eigen' OR coalesce((ally_speicherort_eigen()->>'eingerichtet')::boolean, false))  -- Migration 167 (Bauplan B6): T3, nur mit eingebundenem eigenem Speicherort
$function$
;

CREATE OR REPLACE FUNCTION public.ally_person_rolle_abgleichen(p_user text)
 RETURNS void
 LANGUAGE sql
AS $function$
  -- Rolle folgt dem Admin-Recht, wenn es direkt gesetzt wird (alte Oberfläche „Personen und Rechte“, Migration 64): admin/superadmin -> Rolle Admin;
  -- wer das Admin-Recht verliert, ist danach ohne Rolle (der Admin wählt eine neue). Andere Rollen bleiben.
  UPDATE ally_personen p SET rolle = x.neu
  FROM (SELECT CASE WHEN EXISTS (SELECT 1 FROM ally_nutzer_rechte r WHERE r.matrix_user_id = p_user AND r.recht IN ('admin', 'superadmin')) THEN 'admin'
                    WHEN q.rolle = 'admin' THEN NULL ELSE q.rolle END AS neu
        FROM ally_personen q WHERE q.matrix_user_id = p_user) x
  WHERE p.matrix_user_id = p_user AND p.rolle IS DISTINCT FROM x.neu
$function$
;

CREATE OR REPLACE FUNCTION public.ally_person_rolle_anwenden(p_user text, p_rolle text, p_funktionen text[])
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  ro text := nullif(btrim(coalesce(p_rolle, '')), '');
BEGIN
  -- Rolle einer Person setzen (Migration 64): Admin oder eine aktive, vom Admin angelegte Rolle; unbekannt oder archiviert = ohne Rolle.
  -- Die Rechte kommen aus der Rolle (ally_rollen_rechte), sie werden nicht je Person gespeichert. Nur das Recht „admin“ wird für die alte Oberfläche
  -- mitgeführt. Einzeln freigegebene Rechte (p_funktionen, nur Rechte der alten Oberfläche, ohne admin/superadmin) kommen dazu; vorhandene bleiben.
  IF ro IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_rollen r WHERE r.schluessel = ro AND r.fuer_personen AND (r.art = 'admin' OR (r.art = 'eigen' AND r.archiviert_am IS NULL))) THEN
    ro := NULL;
  END IF;
  IF ally_person_superadmin(p_user) THEN ro := 'admin'; END IF;
  UPDATE ally_personen SET rolle = ro, geaendert_am = now() WHERE matrix_user_id = p_user AND rolle IS DISTINCT FROM ro;
  IF ro = 'admin' THEN
    INSERT INTO ally_nutzer_rechte (matrix_user_id, recht) VALUES (p_user, 'admin') ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM ally_nutzer_rechte WHERE matrix_user_id = p_user AND recht = 'admin';
  END IF;
  -- Migration 167 (Bauplan B6): F13, einzeln freigegebene Rechte als eigene Rechte (plus) der Person, nicht mehr in ally_nutzer_rechte
  PERFORM ally_einzelrecht_uebernehmen(p_user, x, 'anlegen') FROM unnest(coalesce(p_funktionen, '{}')) AS x WHERE x NOT IN ('admin', 'superadmin');
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_person_rolle_setzen(p_sitzung text, p_person text, p_rolle text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  u text;
  ziel text := btrim(coalesce(p_person, ''));
  ro text := nullif(lower(btrim(coalesce(p_rolle, ''))), '');
  nm text;
BEGIN
  -- Rolle einer Person ändern (Migration 64): Admin oder eine aktive, vom Admin angelegte Rolle; leer = ohne Rolle. Nur Admins.
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_sitzung);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND, 'fehler', 'Bitte neu anmelden.');
  END IF;
  u := s.matrix_user_id;
  IF NOT ally_hat_recht(u, 'admin') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Rollen vergibt eine Person mit der Rolle Admin.');
  END IF;
  SELECT name INTO nm FROM ally_personen WHERE matrix_user_id = ziel AND aktiv;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte oder deaktivierte Person.');
  ELSIF ally_person_ist_talent(ziel) THEN  -- Migration 158 (Bauplan B3a): Talent-Personen ändert man im Talent-Profil.
    -- Migration 163 (Bauplan B5b): Rolle des Talents im Talent-Profil (F7).
    RETURN jsonb_build_object('ok', false, 'fehler', 'Den Zugang und die Rolle eines Talents änderst du im Talent-Profil.');
  ELSIF ro IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_rollen r WHERE r.schluessel = ro AND r.fuer_personen AND (r.art = 'admin' OR (r.art = 'eigen' AND r.archiviert_am IS NULL))) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Rolle gibt es nicht oder sie ist archiviert. Bitte eine andere wählen.');
  ELSIF ally_person_superadmin(ziel) AND NOT ally_hat_recht(u, 'superadmin') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Person ist Superadmin. Änderungen an ihr nehmen nur Superadmins vor.');
  ELSIF ally_person_superadmin(ziel) AND ro IS DISTINCT FROM 'admin' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Superadmins haben immer die Rolle Admin.');
  ELSIF ziel = u AND ro IS DISTINCT FROM 'admin' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Du kannst dir die Rolle Admin nicht selbst entziehen.');
  END IF;
  PERFORM ally_person_rolle_anwenden(ziel, ro, '{}');
  -- Migration 167 (Bauplan B6): Prüfbericht M166 N3: eigene Rechte bleiben beim Wechsel der Rolle stehen (bei der Rolle Admin ohne Wirkung)
  RETURN jsonb_build_object('ok', true, 'meldung', 'Rolle von ' || nm || ': ' || coalesce((SELECT name FROM ally_rollen WHERE schluessel = ro), 'ohne Rolle') || '.'
    || CASE WHEN ro IS DISTINCT FROM 'admin' AND EXISTS (SELECT 1 FROM ally_person_rechte r WHERE r.person = ziel) THEN ' Eigene Rechte gelten weiter.' ELSE '' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_person_superadmin(p_user text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM ally_nutzer_rechte r WHERE r.matrix_user_id = p_user AND r.recht = 'superadmin')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_person_talents_setzen(p_sitzung text, p_person text, p_talents jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  u text;
  ziel text := btrim(coalesce(p_person, ''));
  name_z text;
  ta integer[];
  los text;
BEGIN
  -- Zuständigkeit einer Person für Talents setzen (Stefan 20.10.2026, Migration 59, BA5): danach ist die Person für genau die übergebenen Talents
  -- zuständig. Nur Admin oder Recht „Talents und Kampagnen verwalten“ für alle Talents. Jedes Talent behält mindestens eine zuständige Person (wie talents_web_aktion).
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_sitzung);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND, 'fehler', 'Bitte neu anmelden.');
  END IF;
  u := s.matrix_user_id;
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  IF NOT (ally_hat_recht(u, 'admin') OR ally_hat_recht(u, 'talents_verwalten')) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Dafür fehlt dir das Recht „Talents und Kampagnen verwalten“ für alle Talents.');
  END IF;
  SELECT name INTO name_z FROM ally_personen WHERE matrix_user_id = ziel AND aktiv;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte oder deaktivierte Person.');
  END IF;
  IF ally_person_ist_talent(ziel) THEN  -- Migration 158 (Bauplan B3a): Talent-Personen sind nie Manager/in.
    RETURN jsonb_build_object('ok', false, 'fehler', 'Den Zugang eines Talents änderst du im Talent-Profil.');
  END IF;
  IF ally_person_superadmin(ziel) AND NOT ally_hat_recht(u, 'superadmin') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Person ist Superadmin. Änderungen an ihr nehmen nur Superadmins vor.');
  END IF;
  IF coalesce(jsonb_typeof(p_talents), 'null') NOT IN ('array', 'null') OR jsonb_array_length(coalesce(p_talents, '[]'::jsonb)) > 500 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Angaben konnten nicht verarbeitet werden. Bitte die Seite neu laden.');
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(p_talents, '[]'::jsonb)) AS x WHERE (x #>> '{}') !~ '^[0-9]{1,9}$') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekanntes Talent.');
  END IF;
  ta := ARRAY(SELECT DISTINCT (x #>> '{}')::integer FROM jsonb_array_elements(coalesce(p_talents, '[]'::jsonb)) AS x);
  IF EXISTS (SELECT 1 FROM unnest(ta) AS x WHERE NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = x)) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekanntes Talent.');
  END IF;
  SELECT string_agg(coalesce(t.kuenstlername, t.name, 'Talent ' || t.id), ', ' ORDER BY t.id) INTO los
  FROM talent_personen tp JOIN talents t ON t.id = tp.talent_id
  WHERE tp.matrix_user_id = ziel AND NOT (tp.talent_id = ANY (ta))
    AND NOT EXISTS (SELECT 1 FROM talent_personen o WHERE o.talent_id = tp.talent_id AND o.matrix_user_id <> ziel);
  IF los IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Ohne ' || name_z || ' gäbe es für ' || left(los, 300)
      || ' keinen Manager und keine Managerin mehr. Bitte zuerst einen anderen Manager oder eine andere Managerin eintragen.');
  END IF;
  -- Migration 81: Test-Personen sind nur für Test-Talents zuständig
  IF ally_person_ist_testdaten(ziel) AND EXISTS (SELECT 1 FROM talents t WHERE t.id = ANY (ta) AND NOT t.testdaten) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', name_z || ' gehört zu den Testdaten und kann nur Manager oder Managerin von Test-Talents sein.');
  END IF;
  DELETE FROM talent_personen WHERE matrix_user_id = ziel AND NOT (talent_id = ANY (ta));
  INSERT INTO talent_personen (talent_id, matrix_user_id) SELECT x, ziel FROM unnest(ta) AS x ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('ok', true, 'meldung', 'Zuordnung als Manager/in von ' || name_z || ' gespeichert: '
    || CASE WHEN cardinality(ta) = 0 THEN 'keine Talents' WHEN cardinality(ta) = 1 THEN '1 Talent' ELSE cardinality(ta) || ' Talents' END || '.');
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_person_vormerken(p_sitzung text, p_name text, p_email text, p_rolle text, p_funktionen jsonb DEFAULT '[]'::jsonb, p_talents jsonb DEFAULT '[]'::jsonb, p_postfaecher jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  u text;
  k text := left(btrim(coalesce(p_name, '')), 120);
  em text := lower(btrim(coalesce(p_email, '')));
  ro text := lower(btrim(coalesce(p_rolle, '')));
  fu text[];
  ta integer[];
  pf text[];
  ein jsonb := ally_chat_einrichtung();
  kenn text;
  aid bigint;
  doppelt boolean := false;
BEGIN
  -- Person anlegen, Schritt 1 (Stefan 19.10.2026, Migration 56): prüfen, Chat-Kennung reservieren, Auftrag für ALLY 18 anlegen.
  -- Schritt 2: ALLY 18 legt den Chat-Benutzer an, danach ally_person_anlegen_abschliessen.
  -- Migration 64: Rolle = Admin, eine aktive vom Admin angelegte Rolle oder leer (ohne Rolle); Funktionen nur Rechte, die es je Person gibt (je_person).
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_sitzung);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND, 'fehler', 'Bitte neu anmelden.');
  END IF;
  u := s.matrix_user_id;
  IF NOT ally_hat_recht(u, 'admin') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Personen lädt eine Person mit der Rolle Admin ein.');
  END IF;
  IF k = '' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Bitte einen Namen angeben.');
  END IF;
  IF em !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Bitte eine gültige E-Mail-Adresse angeben. Damit meldet sich die Person an.');
  END IF;
  IF ro <> '' AND NOT EXISTS (SELECT 1 FROM ally_rollen r WHERE r.schluessel = ro AND r.fuer_personen AND (r.art = 'admin' OR (r.art = 'eigen' AND r.archiviert_am IS NULL))) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Rolle gibt es nicht oder sie ist archiviert. Bitte eine andere wählen.');
  END IF;
  IF coalesce(jsonb_typeof(p_funktionen), 'null') NOT IN ('array', 'null') OR coalesce(jsonb_typeof(p_talents), 'null') NOT IN ('array', 'null')
     OR coalesce(jsonb_typeof(p_postfaecher), 'null') NOT IN ('array', 'null') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Angaben konnten nicht verarbeitet werden. Bitte die Seite neu laden.');
  END IF;
  fu := ARRAY(SELECT DISTINCT x FROM jsonb_array_elements_text(coalesce(p_funktionen, '[]'::jsonb)) AS x);
  IF EXISTS (SELECT 1 FROM unnest(fu) AS x WHERE x IN ('admin', 'superadmin')
             OR NOT EXISTS (SELECT 1 FROM ally_rechte r WHERE r.schluessel = x AND r.je_person AND (r.modul IS NULL OR plattform_modul_an(r.modul)))) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte Funktion. Admin wird über die Rolle vergeben.');
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(p_talents, '[]'::jsonb)) AS x WHERE (x #>> '{}') !~ '^[0-9]{1,9}$') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekanntes Talent.');
  END IF;
  ta := ARRAY(SELECT DISTINCT (x #>> '{}')::integer FROM jsonb_array_elements(coalesce(p_talents, '[]'::jsonb)) AS x);
  IF EXISTS (SELECT 1 FROM unnest(ta) AS x WHERE NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = x)) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekanntes Talent.');
  END IF;
  pf := ARRAY(SELECT DISTINCT lower(btrim(x)) FROM jsonb_array_elements_text(coalesce(p_postfaecher, '[]'::jsonb)) AS x);
  IF EXISTS (SELECT 1 FROM unnest(pf) AS x WHERE NOT EXISTS (SELECT 1 FROM ally_postfaecher p WHERE p.adresse = x)) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekanntes Postfach.');
  END IF;
  IF NOT (ein->>'ok')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'fehler', ally_chat_fehler_text('einstellung'));
  END IF;

  -- Ab hier nacheinander (zwei Admins gleichzeitig bekommen nicht dieselbe Kennung)
  PERFORM pg_advisory_xact_lock(hashtext('ally_chat_kennung'));
  IF EXISTS (SELECT 1 FROM ally_personen WHERE email = em)
     OR EXISTS (SELECT 1 FROM ally_chat_auftraege a WHERE a.art = 'anlegen' AND a.status IN ('offen', 'in_arbeit') AND a.daten->>'email' = em) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese E-Mail-Adresse gehört schon zu einer anderen Person.');
  END IF;
  -- Zugänge für Talents (BA7): E-Mail-Adresse eindeutig über Team und Talents, sobald es die Tabelle gibt
  IF to_regclass('public.talent_zugaenge') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM talent_zugaenge WHERE lower(email) = $1)' INTO doppelt USING em;
    IF doppelt THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Diese E-Mail-Adresse gehört schon zu einem Talent-Zugang.');
    END IF;
  END IF;

  kenn := ally_chat_kennung_vorschlag(k);
  IF kenn IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', ally_chat_fehler_text('belegt'));
  END IF;
  INSERT INTO ally_chat_auftraege (art, kennung, matrix_user_id, anzeigename, ref_art, daten, erstellt_von)
  VALUES ('anlegen', kenn, '@' || kenn || ':' || (ein->>'server_name'), k, 'person',
          jsonb_build_object('email', em, 'rolle', nullif(ro, ''), 'funktionen', to_jsonb(fu), 'talents', to_jsonb(ta), 'postfaecher', to_jsonb(pf)), u)
  RETURNING id INTO aid;
  RETURN jsonb_build_object('ok', true, 'auftrag_id', aid, 'kennung', kenn, 'matrix_user_id', '@' || kenn || ':' || (ein->>'server_name'),
    'meldung', k || ' wird angelegt. Das Chat-Konto wird gerade eingerichtet.');
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_personen_kennung_merken()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Trigger (Stefan 19.10.2026, Migration 56): jede neue Person (auch aus der alten Oberfläche mit Feld Chat-Adresse) kommt ins Kennungs-Verzeichnis
  INSERT INTO ally_chat_kennungen (kennung, matrix_user_id, art, ref_id)
  SELECT substring(NEW.matrix_user_id FROM '^@([^:]+):'), NEW.matrix_user_id, 'person', NEW.id
  WHERE NEW.matrix_user_id ~ '^@[a-z0-9._=/+-]+:[^[:space:]]+$'
  ON CONFLICT DO NOTHING;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_personen_sitzungen_weg()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Migration 161 (Prüfung M160): Sitzungen einer gelöschten Person enden mit ihr (auch die Talent-Person, die mit ihrem Talent-Zugang wegfällt).
  DELETE FROM ally_web_sitzungen s WHERE s.matrix_user_id = OLD.matrix_user_id;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_postfach_absender_darf(p_user text, p_postfach text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 90: Als Absender wählen (zum Beispiel Verkaufsberichte): gemeinsame Postfächer wie bisher, persönliche nur von der Person, der sie gehören.
  SELECT coalesce((SELECT p.art = 'gemeinsam' OR p.eigentuemer = p_user FROM ally_postfaecher p WHERE p.adresse = lower(btrim(p_postfach))), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_postfach_aktiv(p_postfach text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((SELECT aktiv FROM ally_postfaecher WHERE adresse = lower(trim(p_postfach))), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_postfach_platz_adresse(p_platz integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 90: Adresse des gemeinsamen Postfachs auf dem Platz (NULL: frei oder persönlich)
  SELECT p.adresse FROM postfach_plaetze pl JOIN ally_postfaecher p ON p.adresse = pl.adresse AND p.art = 'gemeinsam' WHERE pl.platz = p_platz
$function$
;

CREATE OR REPLACE FUNCTION public.ally_postfach_platz_recht(p_recht text)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 173 (Schritt P, P3): Nummer zum Recht für jede Postfach-Nummer (eingerichtete und freie Plätze, eigene Nummern)
  SELECT CASE WHEN p_recht LIKE 'postfach\_%' THEN coalesce(
    (SELECT p.platz FROM postfach_plaetze p WHERE ally_postfach_recht(p.platz) = p_recht ORDER BY p.platz LIMIT 1),
    (SELECT g FROM generate_series(1, 10) g WHERE ally_postfach_recht(g) = p_recht)) END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_postfach_recht(p_platz integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 90: Recht „gemeinsames Postfach auf Platz n sehen“ (Schlüssel ohne Ziffern, wie alle Rechte)
  -- Migration 173 (Schritt P, P3): für jede Postfach-Nummer, Zahlwort ohne Ziffern (1–10 wie bisher: eins … zehn)
  SELECT CASE WHEN p_platz >= 1 THEN 'postfach_' || zahlwort(p_platz) END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_postfach_verwalten_darf(p_user text, p_postfach text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 90: Postfach einstellen (Zugang, Versand, Signatur, Einordnung, Unternehmen, Entfernen):
  --   persönlich nur die Person, der es gehört; gemeinsam mit dem Recht „Gemeinsame Postfächer verwalten“.
  SELECT coalesce((
    SELECT CASE WHEN p.art = 'persoenlich'
                THEN p.eigentuemer = p_user AND EXISTS (SELECT 1 FROM ally_personen x WHERE x.matrix_user_id = p_user AND x.aktiv) AND NOT ally_person_ist_testdaten(p_user)
                ELSE coalesce(ally_hat_recht(p_user, 'postfaecher'), false) END
    FROM ally_postfaecher p WHERE p.adresse = lower(btrim(p_postfach))), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_postfach_zustaendig(p_user text, p_postfach text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 90: Wer sieht das Postfach (Mails, Entwürfe, Einordnung, Hinweise, Briefing)?
  --   persönlich: nur die Person, der es gehört (aktiv);
  --   gemeinsam: wer das Recht postfach_<platz> hat (Rolle oder einzeln; Admins haben es immer). Ohne Platz (entfernt): nur Admins.
  SELECT coalesce((
    SELECT CASE WHEN p.art = 'persoenlich'
                THEN p.eigentuemer = p_user AND EXISTS (SELECT 1 FROM ally_personen x WHERE x.matrix_user_id = p_user AND x.aktiv)
                WHEN pl.platz IS NULL THEN ally_hat_recht(p_user, 'admin')
                ELSE ally_hat_recht(p_user, ally_postfach_recht(pl.platz)) END
    FROM ally_postfaecher p LEFT JOIN postfach_plaetze pl ON pl.adresse = p.adresse
    WHERE p.adresse = lower(btrim(p_postfach))), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_profil_ui(p_token text, p_code text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN s.person IS NULL THEN jsonb_build_object('ok', false) ELSE jsonb_build_object('ok', true,
    'email', p.email,
    'versand_aktiv', ally_systemnachricht_aktiv() AND talent_ui_adresse() IS NOT NULL,
    'offen', (SELECT jsonb_build_object('neue_email', e.neue_email, 'bis', to_char(e.gueltig_bis AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI'),
        'versand', (SELECT n.status FROM ally_systemnachrichten n WHERE n.art = 'email_aendern' AND n.person = s.person ORDER BY n.id DESC LIMIT 1))
      FROM ally_email_aenderungen e WHERE e.person = s.person AND e.status = 'offen' AND e.gueltig_bis > now() ORDER BY e.id DESC LIMIT 1),
    'bestaetigen', CASE WHEN coalesce(p_code, '') ~ '^[0-9a-f]{64}$' THEN (
      SELECT CASE WHEN e.id IS NULL OR e.person <> s.person THEN jsonb_build_object('gueltig', false, 'grund', 'fremd')
                  WHEN e.status <> 'offen' OR e.gueltig_bis <= now() THEN jsonb_build_object('gueltig', false, 'grund', 'abgelaufen')
                  ELSE jsonb_build_object('gueltig', true, 'neue_email', e.neue_email) END
      FROM (SELECT 1) z LEFT JOIN ally_email_aenderungen e ON e.code_hash = ally_web_hash(p_code)) END) END
  FROM (SELECT 1) x
  LEFT JOIN LATERAL (SELECT * FROM ally_ui_sitzung(p_token) y WHERE NOT y.muss_pw_setzen) s ON true
  LEFT JOIN ally_personen p ON p.matrix_user_id = s.person
$function$
;

CREATE OR REPLACE FUNCTION public.ally_recht_name(p_recht text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 90: Anzeigename eines Rechts; bei „gemeinsames Postfach auf Platz n“ die Adresse
  SELECT CASE WHEN ally_postfach_platz_recht(z.schluessel) IS NOT NULL
              THEN coalesce('Postfach ' || ally_postfach_platz_adresse(ally_postfach_platz_recht(z.schluessel)), 'Gemeinsames Postfach (Platz ' || ally_postfach_platz_recht(z.schluessel) || ', frei)')
              -- Migration 167 (Bauplan B6): T3, „Ordner freigeben: <Bezeichnung des Speicherorts>“
              WHEN z.schluessel = 'speicherort_eigen' THEN coalesce(z.katalog_name, z.name) || coalesce(': ' || nullif(btrim(ally_speicherort_eigen()->>'name'), ''), '')
              ELSE coalesce(z.katalog_name, z.name) END
  FROM ally_rechte z WHERE z.schluessel = p_recht
$function$
;

CREATE OR REPLACE FUNCTION public.ally_recht_reichweite(p_user text, p_recht text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  bekannt boolean; modul text; nur_selbst boolean; minus_ansehen boolean; r text; a text; v text;
BEGIN
  -- Reichweite eines Rechts für eine Person (Migration 64, Stefan 20.10.2026): 'alle', 'zugeordnet' oder NULL (kein Recht).
  -- Nur aktive Personen; Rechte nicht gebuchter Pakete gelten für niemanden. Superadmin hat alles, Admin alles außer „superadmin“. Admin ist, wer das Recht „admin“
  -- hat (die Rolle Admin setzt es immer mit, ally_person_rolle_anwenden; wie bisher).
  -- Sonst das Maximum aus der Rolle (nicht archiviert) und einzeln vergebenen Rechten (ally_recht_roh). Rechte ohne Reichweite liefern 'alle'.
  -- Talent-Rechte: Wer „Talents und Kampagnen verwalten“, „Honorare und Budgets sehen“ oder „Talent-Bereich einstellen“ hat, sieht auch die Talents (R1);
  -- diese Rechte reichen nie weiter als „Talents ansehen“ (R2). Migration 66: „Talents ansehen“ für alle geht auch ohne Verwalten-Recht (Regel R3 entfällt);
  -- Ansehen allein erlaubt keine Änderungen (talent_verwaltbar).
  -- Migration 156 (Prüfbericht M155 N1/N2): Reichweite 'selbst' gilt nur bei Rechten für die eigenen Daten eines Talents (ally_rechte.nur_selbst) und nur als 'selbst';
  -- bei allen anderen Rechten zählt sie nicht. Ein minus auf „Talents ansehen“ nimmt auch die übrigen Talent-Rechte (R2: nie weiter als Ansehen), nach Admin,
  -- vor R1/R2 und vor der Testdaten-Klammer. Die Testdaten-Klammer macht nur aus 'zugeordnet'/'alle' ein 'zugeordnet'.
  IF p_user IS NULL OR p_recht IS NULL THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = p_user AND p.aktiv) THEN RETURN NULL; END IF;
  minus_ansehen := p_recht IN ('talents_ansehen', 'talents_verwalten', 'talents_betraege', 'talents_bereich')
    AND EXISTS (SELECT 1 FROM ally_person_rechte m WHERE m.person = p_user AND m.recht = 'talents_ansehen' AND m.wirkung = 'minus');
  -- Migration 81 (Testdaten): Test-Personen bekommen nur die Talent-Rechte und höchstens „zugeordnet“ – auch wenn ihre Rolle „alle“ sagt oder ihnen jemand
  -- Admin, Superadmin oder andere Rechte gibt. Zugeordnet werden können sie nur Test-Talents und Test-Kampagnen (Trigger ally_testdaten_trennung).
  IF ally_person_ist_testdaten(p_user) THEN
    -- Migration 161 (Bauplan B4b): Rechte für die eigenen Daten eines Talents (nur_selbst) gelten für Test-Talents wie für echte: nur 'selbst', Paket gebucht.
    IF EXISTS (SELECT 1 FROM ally_rechte x WHERE x.schluessel = p_recht AND x.nur_selbst AND (x.modul IS NULL OR plattform_modul_an(x.modul))) THEN
      RETURN CASE WHEN ally_recht_roh(p_user, p_recht) IS NOT NULL THEN 'selbst' END;
    END IF;
    IF p_recht NOT IN ('talents_ansehen', 'talents_verwalten', 'talents_betraege', 'talents_bereich') OR NOT plattform_modul_an('talents') OR minus_ansehen THEN RETURN NULL; END IF;
    IF p_recht = 'talents_ansehen' THEN
      RETURN CASE WHEN (SELECT max(ally_recht_stufe(ally_recht_roh(p_user, k))) FROM unnest(ARRAY['talents_ansehen', 'talents_verwalten', 'talents_betraege', 'talents_bereich']) AS k) >= 1 THEN 'zugeordnet' END;
    END IF;
    RETURN CASE WHEN ally_recht_roh(p_user, p_recht) IN ('zugeordnet', 'alle') THEN 'zugeordnet' END;
  END IF;
  SELECT x.modul, x.nur_selbst INTO modul, nur_selbst FROM ally_rechte x WHERE x.schluessel = p_recht;
  bekannt := FOUND;
  IF modul IS NOT NULL AND NOT plattform_modul_an(modul) THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM ally_nutzer_rechte n WHERE n.matrix_user_id = p_user AND n.recht = 'superadmin') THEN RETURN 'alle'; END IF;
  IF p_recht = 'superadmin' THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM ally_nutzer_rechte n WHERE n.matrix_user_id = p_user AND n.recht = 'admin') THEN RETURN 'alle'; END IF;
  IF p_recht = 'admin' OR NOT bekannt THEN RETURN NULL; END IF;
  IF minus_ansehen THEN RETURN NULL; END IF;
  IF p_recht IN ('talents_ansehen', 'talents_verwalten', 'talents_betraege', 'talents_bereich') THEN
    SELECT CASE max(ally_recht_stufe(ally_recht_roh(p_user, k))) WHEN 2 THEN 'alle' WHEN 1 THEN 'zugeordnet' END INTO a
    FROM unnest(ARRAY['talents_ansehen', 'talents_verwalten', 'talents_betraege', 'talents_bereich']) AS k;
    IF p_recht = 'talents_ansehen' THEN RETURN a; END IF;
    r := nullif(ally_recht_roh(p_user, p_recht), 'selbst');
    IF r = 'alle' AND a IS DISTINCT FROM 'alle' THEN r := 'zugeordnet'; END IF;
    RETURN r;
  END IF;
  r := ally_recht_roh(p_user, p_recht);
  IF nur_selbst THEN RETURN CASE WHEN r IS NOT NULL THEN 'selbst' END; END IF;
  RETURN nullif(r, 'selbst');
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_recht_roh(p_user text, p_recht text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Reichweite eines Rechts aus der Rolle der Person (nicht archiviert) und aus einzeln vergebenen Rechten der alten Oberfläche (Migration 64).
  -- Ohne Admin/Superadmin, ohne Paketprüfung und ohne die Regeln der Talent-Rechte (das macht ally_recht_reichweite).
  -- Einzeln vergeben: „Talents verwalten“ wirkt wie bisher für alle Talents (und sehen alle), „Talents ansehen“ nur für zugeordnete; sonst ohne Reichweite.
  -- Migration 155 (G4): eigene Rechte je Account aus ally_person_rechte – plus zählt wie ein Recht der Rolle (ohne Reichweite = alle), minus nimmt das Recht weg
  -- (auch wenn die Rolle es hat). Reichweite 'selbst' (nur eigene Daten eines Talents) gilt nur, wenn keine Quelle 'zugeordnet' oder 'alle' liefert.
  -- Rollen der Art 'talent' zählen wie eigene Rollen.
  -- Migration 167 (Bauplan B6): einzeln vergebene Rechte der alten Oberfläche (ally_nutzer_rechte) zählen nicht mehr (F13); sie stehen als eigene Rechte (plus)
  -- in ally_person_rechte (ally_einzelrecht_uebernehmen). In ally_nutzer_rechte bleiben nur admin und superadmin.
  SELECT CASE WHEN EXISTS (SELECT 1 FROM ally_person_rechte m WHERE m.person = p_user AND m.recht = p_recht AND m.wirkung = 'minus') THEN NULL
              WHEN max(ally_recht_stufe(x.r)) = 2 THEN 'alle'
              WHEN max(ally_recht_stufe(x.r)) = 1 THEN 'zugeordnet'
              WHEN bool_or(x.r = 'selbst') THEN 'selbst' END
  FROM (
    SELECT coalesce(rr.reichweite, 'alle') AS r
    FROM ally_personen p
    JOIN ally_rollen ro ON ro.schluessel = p.rolle AND ro.art IN ('eigen', 'talent') AND ro.archiviert_am IS NULL
    JOIN ally_rollen_rechte rr ON rr.rolle = ro.schluessel AND rr.recht = p_recht
    WHERE p.matrix_user_id = p_user AND p.aktiv
    UNION ALL
    SELECT coalesce(pr.reichweite, 'alle')
    FROM ally_person_rechte pr JOIN ally_personen p ON p.matrix_user_id = pr.person AND p.aktiv
    WHERE pr.person = p_user AND pr.recht = p_recht AND pr.wirkung = 'plus'
  ) x
$function$
;

CREATE OR REPLACE FUNCTION public.ally_recht_stufe(p_reichweite text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Rangfolge der Reichweiten (Migration 64): kein Recht 0, zugeordnete 1, alle 2
  SELECT CASE p_reichweite WHEN 'alle' THEN 2 WHEN 'zugeordnet' THEN 1 ELSE 0 END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_rechte_schutz()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Migration 168 (Bauplan B7, N3 aus der Prüfung M158): Rollen, eigene Rechte und Seiten hängen am Schlüssel; nur_selbst bestimmt die Reichweite.
  IF NEW.schluessel IS DISTINCT FROM OLD.schluessel OR NEW.nur_selbst IS DISTINCT FROM OLD.nur_selbst THEN
    RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Schlüssel und Reichweite eines Rechts ändert nur eine Migration.';
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_reichweite_passt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  ns boolean; rw boolean; nm text;
BEGIN
  -- Migration 156 (Prüfbericht M155 N3, M156 N3; Absicherung in den Tabellen ally_rollen_rechte und ally_person_rechte): die Reichweite passt zum Recht im Katalog.
  -- Rechte für die eigenen Daten eines Talents (nur_selbst): nur 'selbst' (ohne Angabe wird 'selbst' gesetzt). Rechte mit Reichweite (ally_rechte.reichweite):
  -- 'zugeordnet' oder 'alle', ohne Angabe = alle (wie ally_recht_roh). Rechte ohne Reichweite: ohne Angabe. minus-Einträge haben keine Reichweite (CHECK aus 155).
  IF TG_TABLE_NAME = 'ally_person_rechte' THEN
    IF NEW.wirkung = 'minus' THEN RETURN NEW; END IF;
  END IF;
  SELECT coalesce(z.nur_selbst, false), coalesce(z.reichweite, false), coalesce(z.katalog_name, z.name) INTO ns, rw, nm FROM ally_rechte z WHERE z.schluessel = NEW.recht;
  IF NOT FOUND THEN RETURN NEW; END IF;  -- unbekanntes Recht: lehnt der Fremdschlüssel ab
  IF ns THEN
    IF NEW.reichweite IS NULL THEN
      NEW.reichweite := 'selbst';
    ELSIF NEW.reichweite <> 'selbst' THEN
      RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = '„' || nm || '“ gilt nur für die eigenen Daten eines Talents.';
    END IF;
  ELSIF rw THEN
    IF NEW.reichweite = 'selbst' THEN
      RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = '„' || nm || '“ gilt für zugeordnete oder alle, nicht nur für die eigenen Daten eines Talents.';
    END IF;
  ELSIF NEW.reichweite IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = '„' || nm || '“ hat keine Reichweite.';
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_reichweite_text(p_recht text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 101: Bezeichnung der eingeschränkten Reichweite eines Rechts. Talent-Rechte: „zugeordnete“ (Talents), Verkaufsberichte: „eigene“ (selbst angelegt).
  SELECT CASE WHEN p_recht IN ('verkaufsberichte', 'briefings') THEN 'eigene' ELSE 'zugeordnete' END  -- Migration 177: Briefings „eigene“
$function$
;

CREATE OR REPLACE FUNCTION public.ally_rolle_auf_standard(p_rolle text, p_person text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  ro ally_rollen%ROWTYPE; n integer;
BEGIN
  -- Migration 156 (G2): Rechte einer Vorlage auf den Standard zurücksetzen – ally_rollen_rechte wird genau ally_rollen.standard ({recht: reichweite|null}).
  -- Name und Beschreibung bleiben. Liefert die Zahl der Rechte danach, NULL ohne Rolle oder ohne Standard.
  -- admin und superadmin kommen nie über einen Standard in eine Rolle; stehen sie in der Rolle, fallen sie beim Zurücksetzen weg (Prüfbericht M156).
  SELECT * INTO ro FROM ally_rollen x WHERE x.schluessel = p_rolle FOR UPDATE;
  IF NOT FOUND OR ro.standard IS NULL OR jsonb_typeof(ro.standard) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
  DELETE FROM ally_rollen_rechte rr WHERE rr.rolle = ro.schluessel AND (NOT ro.standard ? rr.recht OR rr.recht IN ('admin', 'superadmin'));
  INSERT INTO ally_rollen_rechte (rolle, recht, reichweite, geaendert_von)
  SELECT ro.schluessel, e.key, e.value #>> '{}', p_person FROM jsonb_each(ro.standard) e JOIN ally_rechte z ON z.schluessel = e.key
  WHERE e.key NOT IN ('admin', 'superadmin')
  ON CONFLICT (rolle, recht) DO UPDATE SET reichweite = EXCLUDED.reichweite, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von
  WHERE ally_rollen_rechte.reichweite IS DISTINCT FROM EXCLUDED.reichweite;
  UPDATE ally_rollen SET geaendert_am = now(), geaendert_von = p_person WHERE schluessel = ro.schluessel;
  SELECT count(*) INTO n FROM ally_rollen_rechte rr WHERE rr.rolle = ro.schluessel;
  RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_rolle_ist_talent(p_rolle text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 165 (Bauplan B5c): Ist die Rolle eine Rolle der Art talent (Rolle für Talents)? Leer oder unbekannt = nein.
  SELECT EXISTS (SELECT 1 FROM ally_rollen r WHERE r.schluessel = p_rolle AND r.art = 'talent')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_rolle_papierkorb(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; ro ally_rollen%ROWTYPE;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  liste text[]; m text := NULL; fehler text := NULL; n integer := 0; bleibt text[] := '{}';
BEGIN
  -- Migration 129: Papierkorb der Rollen (archivierte Rollen). Endgültig löschen nur ohne zugeordnete Personen (auch deaktivierte). Nur Admins.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT ally_hat_recht(s.person, 'admin') THEN
    fehler := 'Rollen verwaltet eine Person mit der Rolle Admin.';
  ELSIF p_aktion = 'ro_endgueltig' THEN
    SELECT * INTO ro FROM ally_rollen x WHERE x.schluessel = lower(btrim(coalesce(d->>'schluessel', ''))) AND x.art IN ('eigen', 'talent') FOR UPDATE;  -- Migration 165 (Bauplan B5c): auch Rollen für Talents
    IF NOT FOUND OR ro.archiviert_am IS NULL THEN
      fehler := 'Diese Rolle liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.';
    ELSE
      SELECT count(*) INTO n FROM ally_personen p WHERE p.rolle = ro.schluessel;
      IF n > 0 THEN
        fehler := 'Die Rolle „' || ro.name || '“ ist noch ' || n || CASE WHEN n = 1 THEN ' Person' ELSE ' Personen' END
          || ' zugeordnet (auch deaktivierte zählen). Bitte zuerst eine andere Rolle geben, dann endgültig löschen.';
      ELSE
        DELETE FROM ally_rollen WHERE schluessel = ro.schluessel;
        m := 'Rolle „' || ro.name || '“ endgültig gelöscht.';
      END IF;
    END IF;
  ELSIF p_aktion = 'ro_papierkorb_leeren' THEN
    IF coalesce(d->>'liste', '') !~ '^[a-z0-9_]{1,40}(,[a-z0-9_]{1,40})*$' OR cardinality(string_to_array(d->>'liste', ',')) > 1000 THEN
      fehler := 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.';
    ELSE
      liste := string_to_array(d->>'liste', ',');
      SELECT coalesce(array_agg(ro2.name ORDER BY lower(ro2.name)), '{}') INTO bleibt FROM ally_rollen ro2
       WHERE ro2.schluessel = ANY (liste) AND ro2.art IN ('eigen', 'talent') AND ro2.archiviert_am IS NOT NULL AND EXISTS (SELECT 1 FROM ally_personen p WHERE p.rolle = ro2.schluessel);
      DELETE FROM ally_rollen ro2 WHERE ro2.schluessel = ANY (liste) AND ro2.art IN ('eigen', 'talent') AND ro2.archiviert_am IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.rolle = ro2.schluessel);
      GET DIAGNOSTICS n = ROW_COUNT;
      m := CASE WHEN n = 0 THEN 'Keine Rolle gelöscht.' WHEN n = 1 THEN '1 Rolle endgültig gelöscht.' ELSE n || ' Rollen endgültig gelöscht.' END
        || CASE WHEN cardinality(bleibt) > 0 THEN ' Im Papierkorb bleiben, weil ihnen noch Personen zugeordnet sind: ' || array_to_string(bleibt, ', ') || '.' ELSE '' END;
    END IF;
  ELSE
    fehler := 'Diese Aktion gibt es nicht.';
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_rolle_rechte_pruefen(p_rechte jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  e record; x ally_rechte%ROWTYPE; w text; erg jsonb := '{}'::jsonb; a text; m text;
BEGIN
  -- Rechte einer Rolle prüfen und vereinheitlichen (Migration 64). Eingabe {recht: 'ja' | 'zugeordnet' | 'alle' | ''}; nur Rechte des Katalogs
  -- (gebuchte Pakete), nie admin/superadmin. Ausgabe {ok, rechte: {recht: reichweite oder null}} oder {ok: false, fehler}.
  -- Regeln: R1 Talent-Rechte bringen „Talents ansehen“ mit; R2 sie reichen nicht weiter als „Talents ansehen“.
  -- Migration 66: Regel R3 entfällt („alle Talents ansehen“ geht auch ohne „Talents und Kampagnen verwalten: alle“; Ansehen allein erlaubt keine Änderungen).
  IF jsonb_typeof(p_rechte) IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Rechte konnten nicht gelesen werden. Bitte die Seite neu laden.');
  END IF;
  FOR e IN SELECT key AS k, value AS v FROM jsonb_each(p_rechte) LOOP
    w := CASE WHEN jsonb_typeof(e.v) = 'string' THEN e.v #>> '{}' ELSE '' END;
    CONTINUE WHEN w IN ('', 'nein');
    SELECT * INTO x FROM ally_rechte z WHERE z.schluessel = e.k AND z.katalog_gruppe IS NOT NULL AND z.schluessel NOT IN ('admin', 'superadmin');
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekanntes Recht. Bitte die Seite neu laden.');
    END IF;
    -- Migration 90: Häkchen nur für belegte gemeinsame Postfächer
    IF ally_postfach_platz_recht(e.k) IS NOT NULL AND ally_postfach_platz_adresse(ally_postfach_platz_recht(e.k)) IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Ein gewähltes Postfach gibt es nicht mehr. Bitte die Seite neu laden.');
    END IF;
    -- Migration 167 (Bauplan B6): T3, „Ordner freigeben“ nur mit eingebundenem eigenem Speicherort
    IF e.k = 'speicherort_eigen' AND NOT coalesce((ally_speicherort_eigen()->>'eingerichtet')::boolean, false) THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Es ist kein eigener Speicherort eingebunden. Bitte die Seite neu laden.');
    END IF;
    -- Migration 156: Rechte für die eigenen Daten eines Talents (nur_selbst) gelten mit Reichweite 'selbst' (ein Häkchen)
    IF x.nur_selbst THEN
      IF w NOT IN ('ja', '1', 'selbst') THEN
        RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte Angabe bei „' || coalesce(x.katalog_name, x.name) || '“.');
      END IF;
      erg := erg || jsonb_build_object(e.k, 'selbst');
      CONTINUE;
    END IF;
    -- Migration 102: heutige Rollenverwaltung schickt für „Verkaufsberichte“ ein Häkchen (ja/1) = alle
    IF x.reichweite AND x.schluessel = 'verkaufsberichte' AND w IN ('ja', '1') THEN w := 'alle'; END IF;
    IF x.reichweite THEN
      IF w NOT IN ('zugeordnet', 'alle') THEN
        RETURN jsonb_build_object('ok', false, 'fehler', 'Bitte für „' || coalesce(x.katalog_name, x.name) || '“ wählen: nur ' || ally_reichweite_text(x.schluessel) || ' oder alle.');
      END IF;
      erg := erg || jsonb_build_object(e.k, w);
    ELSE
      IF w NOT IN ('ja', 'zugeordnet', 'alle', '1') THEN
        RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte Angabe bei „' || coalesce(x.katalog_name, x.name) || '“.');
      END IF;
      erg := erg || jsonb_build_object(e.k, NULL);
    END IF;
  END LOOP;
  -- R1
  SELECT CASE max(ally_recht_stufe(erg->>k)) WHEN 2 THEN 'alle' WHEN 1 THEN 'zugeordnet' END INTO a
  FROM unnest(ARRAY['talents_verwalten', 'talents_betraege', 'talents_bereich']) AS k WHERE erg ? k;
  IF a IS NOT NULL AND NOT erg ? 'talents_ansehen' THEN
    erg := erg || jsonb_build_object('talents_ansehen', a);
  END IF;
  -- R2
  IF EXISTS (SELECT 1 FROM unnest(ARRAY['talents_verwalten', 'talents_betraege', 'talents_bereich']) AS k
             WHERE erg ? k AND ally_recht_stufe(erg->>k) > ally_recht_stufe(erg->>'talents_ansehen')) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Talent-Rechte für alle Talents gehen nur, wenn die Rolle auch alle Talents ansehen darf.');
  END IF;
  RETURN jsonb_build_object('ok', true, 'rechte', erg);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_rolle_text(p_rolle text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Kurzfassung der Rechte einer Rolle (Migration 64), z. B. „Talents ansehen (zugeordnete), Kalender“
  SELECT CASE WHEN ro.art = 'admin' THEN 'Alle Rechte in der Organisation'
    ELSE coalesce((SELECT string_agg(ally_recht_name(z.schluessel) || CASE rr.reichweite WHEN 'alle' THEN ' (alle)' WHEN 'zugeordnet' THEN ' (' || ally_reichweite_text(z.schluessel) || ')' ELSE '' END,
                                     ', ' ORDER BY z.katalog_sortierung, z.schluessel)
                   FROM ally_rollen_rechte rr JOIN ally_rechte z ON z.schluessel = rr.recht
                   WHERE rr.rolle = ro.schluessel AND (z.modul IS NULL OR plattform_modul_an(z.modul))), 'Keine Rechte') END
  FROM ally_rollen ro WHERE ro.schluessel = p_rolle
$function$
;

CREATE OR REPLACE FUNCTION public.ally_rolle_ui_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  ro ally_rollen%ROWTYPE;
  k text := lower(btrim(coalesce(d->>'schluessel', '')));
  nm text := btrim(regexp_replace(coalesce(d->>'name', ''), '\s+', ' ', 'g'));
  be text := btrim(coalesce(d->>'beschreibung', ''));
  pr jsonb; m text := NULL; fehler text := NULL; n integer;
  art_neu text := CASE WHEN d->>'art' = 'talent' THEN 'talent' ELSE 'eigen' END;
BEGIN
  -- Rollen verwalten (ALLY 23, Migration 64, ro_*): ro_neu (name, beschreibung, rechte), ro_speichern (schluessel, name, beschreibung, rechte),
  -- ro_archivieren (schluessel; nur ohne aktive Personen), ro_aktivieren (schluessel). Nur Admins. Rollen werden nie gelöscht. Admin ist fest.
  -- Rechte gebuchter Pakete ersetzt das Formular; Rechte nicht gebuchter Pakete bleiben in der Rolle gespeichert. Meldung setzt die Funktion selbst.
  -- Migration 156 (G2): Vorlagen der Pakete (vorlage gesetzt, auch die Rolle Talent) lassen sich ändern (ro_speichern) und auf den Standard zurücksetzen
  -- (ro_standard), aber nicht in den Papierkorb legen. Umbenennen lassen sie sich alle gleich, die Rolle Talent auch wieder zurück auf „Talent“ (Prüfbericht M156 M2);
  -- neue oder andere Rollen bekommen den Namen Talent nie.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT ally_hat_recht(s.person, 'admin') THEN
    fehler := 'Rollen verwaltet eine Person mit der Rolle Admin.';
  ELSIF p_aktion NOT IN ('ro_neu', 'ro_speichern', 'ro_archivieren', 'ro_aktivieren', 'ro_standard') THEN
    fehler := 'Diese Aktion gibt es nicht.';
  -- Migration 165 (Bauplan B5c): ro_neu mit art talent legt eine Rolle für Talents an (nur mit dem Paket Talents).
  ELSIF p_aktion = 'ro_neu' AND art_neu = 'talent' AND NOT plattform_modul_an('talents') THEN
    fehler := 'Rollen für Talents gibt es nur mit dem Paket Talents.';
  ELSE
    IF p_aktion <> 'ro_neu' THEN
      SELECT * INTO ro FROM ally_rollen x WHERE x.schluessel = k FOR UPDATE;
      IF NOT FOUND OR ro.art NOT IN ('eigen', 'talent') THEN
        fehler := CASE WHEN FOUND AND ro.art = 'admin' THEN 'Die Rolle Admin ist fest und lässt sich nicht ändern.' ELSE 'Diese Rolle gibt es nicht. Bitte die Seite neu laden.' END;
      -- Migration 165 (Bauplan B5c): nur Vorlagen (auch die Rolle Talent) bleiben immer; weitere Rollen für Talents lassen sich in den Papierkorb legen.
      ELSIF ro.vorlage IS NOT NULL AND p_aktion IN ('ro_archivieren', 'ro_aktivieren') THEN
        fehler := 'Vorlagen bleiben immer erhalten. Du kannst sie ändern und auf den Standard zurücksetzen.';
      ELSIF p_aktion = 'ro_standard' AND ro.standard IS NULL THEN
        fehler := 'Für diese Rolle gibt es keinen Standard.';
      -- Migration 163 (Bauplan B5b): Ally-Chat ist eine Erlaubnis (Stefan G12); der Standard darf sie Talents mit eingeschaltetem Chat nicht wegnehmen.
      ELSIF p_aktion = 'ro_standard' AND ro.art = 'talent' AND NOT ro.standard ? 'talent_chat' AND EXISTS (SELECT 1 FROM ally_personen p JOIN talent_chat c ON c.talent_id = p.talent_id AND c.chat_an WHERE p.rolle = ro.schluessel AND p.talent_id IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM ally_person_rechte x WHERE x.person = p.matrix_user_id AND x.recht = 'talent_chat' AND x.wirkung = 'plus')) THEN
        fehler := 'Bei Talents mit dieser Rolle ist der Ally-Chat eingeschaltet. Bitte ihn dort zuerst ausschalten.';
      END IF;
    END IF;
    IF fehler IS NULL AND p_aktion IN ('ro_neu', 'ro_speichern') THEN
      IF nm = '' OR length(nm) > 40 THEN
        fehler := 'Bitte einen Namen mit höchstens 40 Zeichen angeben.';
      ELSIF lower(nm) IN ('admin', 'superadmin', 'talent', 'ohne rolle') AND lower(nm) IS DISTINCT FROM lower(btrim(ro.name))
        AND NOT (coalesce(ro.vorlage, '') = 'talent' AND lower(nm) = 'talent') THEN
        fehler := 'Diesen Namen gibt es schon fest. Bitte einen anderen wählen.';
      ELSIF EXISTS (SELECT 1 FROM ally_rollen x WHERE lower(btrim(x.name)) = lower(nm) AND x.schluessel IS DISTINCT FROM ro.schluessel) THEN
        fehler := 'Eine Rolle mit diesem Namen gibt es schon (auch Rollen im Papierkorb zählen).';
      ELSIF length(be) > 300 THEN
        fehler := 'Die Beschreibung ist zu lang (höchstens 300 Zeichen).';
      ELSE
        pr := ally_rolle_rechte_pruefen(CASE WHEN jsonb_typeof(d->'rechte') = 'object' THEN d->'rechte' ELSE '{}'::jsonb END);
        IF NOT coalesce((pr->>'ok')::boolean, false) THEN fehler := pr->>'fehler';
        -- Migration 158 (Bauplan B3a): die Rolle Talent bekommt nur Rechte aus der Gruppe „Talent-Bereich“ (nur_selbst; Prüfbericht M156).
        ELSIF coalesce(ro.art, art_neu) = 'talent' AND EXISTS (SELECT 1 FROM jsonb_object_keys(pr->'rechte') AS rk(recht) JOIN ally_rechte z ON z.schluessel = rk.recht WHERE NOT z.nur_selbst) THEN
          fehler := 'Eine Rolle für Talents bekommt nur Rechte aus der Gruppe „Talent-Bereich“.';
        -- Migration 162 (Bauplan B5a): „Eigenes Profil“ bleibt in Rollen der Art talent immer an (Prüfbericht M161 N1).
        ELSIF coalesce(ro.art, art_neu) = 'talent' AND plattform_modul_an('talents') AND NOT (pr->'rechte') ? 'talent_profil' THEN
          fehler := 'In einer Rolle für Talents bleibt „Eigenes Profil“ immer an. Ohne dieses Recht sähe kein Talent sein Profil.';
        -- Migration 163 (Bauplan B5b): Ally-Chat ist eine Erlaubnis (Stefan G12); nicht wegnehmen, solange Talents mit dieser Rolle den Chat an haben.
        ELSIF ro.art = 'talent' AND plattform_modul_an('talents') AND NOT (pr->'rechte') ? 'talent_chat' AND EXISTS (SELECT 1 FROM ally_personen p JOIN talent_chat c ON c.talent_id = p.talent_id AND c.chat_an WHERE p.rolle = ro.schluessel AND p.talent_id IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM ally_person_rechte x WHERE x.person = p.matrix_user_id AND x.recht = 'talent_chat' AND x.wirkung = 'plus')) THEN
          fehler := 'Bei Talents mit dieser Rolle ist der Ally-Chat eingeschaltet. Bitte ihn dort zuerst ausschalten.';
        END IF;
      END IF;
    END IF;
    IF fehler IS NULL THEN
      IF p_aktion = 'ro_neu' THEN
        LOOP
          k := 'r' || nextval('ally_rollen_nr');
          EXIT WHEN NOT EXISTS (SELECT 1 FROM ally_rollen x WHERE x.schluessel = k);
        END LOOP;
        INSERT INTO ally_rollen (schluessel, name, beschreibung, sortierung, rechte, fuer_personen, art, erstellt_von, geaendert_von)
        VALUES (k, nm, be, CASE WHEN art_neu = 'talent' THEN 1000 ELSE 100 END, '{}', art_neu <> 'talent', art_neu, s.person, s.person);
        INSERT INTO ally_rollen_rechte (rolle, recht, reichweite, geaendert_von)
        SELECT k, e.key, e.value #>> '{}', s.person FROM jsonb_each(pr->'rechte') e;
        m := 'Rolle „' || nm || '“ angelegt. ' || CASE WHEN art_neu = 'talent' THEN 'Talents bekommen sie beim Einladen oder im Talent-Profil.'
          ELSE 'Personen bekommen sie unter Team und Rollen › Personen.' END;
      ELSIF p_aktion = 'ro_speichern' THEN
        UPDATE ally_rollen SET name = nm, beschreibung = be, geaendert_am = now(), geaendert_von = s.person WHERE schluessel = ro.schluessel;
        DELETE FROM ally_rollen_rechte rr USING ally_rechte z
        WHERE rr.rolle = ro.schluessel AND z.schluessel = rr.recht AND (z.modul IS NULL OR plattform_modul_an(z.modul)) AND NOT (pr->'rechte') ? rr.recht
          -- Migration 167 (Bauplan B6): T3, ohne eingebundenen Speicherort steht „Ordner freigeben“ nicht im Formular und bleibt erhalten
          AND (rr.recht <> 'speicherort_eigen' OR coalesce((ally_speicherort_eigen()->>'eingerichtet')::boolean, false));
        INSERT INTO ally_rollen_rechte (rolle, recht, reichweite, geaendert_von)
        SELECT ro.schluessel, e.key, e.value #>> '{}', s.person FROM jsonb_each(pr->'rechte') e
        ON CONFLICT (rolle, recht) DO UPDATE SET reichweite = EXCLUDED.reichweite, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von
        WHERE ally_rollen_rechte.reichweite IS DISTINCT FROM EXCLUDED.reichweite;
        SELECT count(*) INTO n FROM ally_personen p WHERE p.rolle = ro.schluessel AND p.aktiv;
        m := 'Rolle „' || nm || '“ gespeichert.' || CASE WHEN n > 0 THEN ' Gilt sofort für ' || n || CASE WHEN n = 1 THEN ' Person.' ELSE ' Personen.' END ELSE '' END;
      ELSIF p_aktion = 'ro_standard' THEN
        PERFORM ally_rolle_auf_standard(ro.schluessel, s.person);
        SELECT count(*) INTO n FROM ally_personen p WHERE p.rolle = ro.schluessel AND p.aktiv;
        m := 'Rolle „' || ro.name || '“ auf den Standard zurückgesetzt.' || CASE WHEN n > 0 THEN ' Gilt sofort für ' || n || CASE WHEN n = 1 THEN ' Person.' ELSE ' Personen.' END ELSE '' END;
      ELSIF p_aktion = 'ro_archivieren' THEN
        -- Migration 165 (Bauplan B5c): bei Rollen für Talents zählen auch inaktive Personen (Prüfbericht M165 N1).
        SELECT count(*) INTO n FROM ally_personen p WHERE p.rolle = ro.schluessel AND (p.aktiv OR ro.art = 'talent');
        IF ro.archiviert_am IS NOT NULL THEN
          fehler := 'Die Rolle liegt schon im Papierkorb.';
        ELSIF n > 0 THEN
          fehler := 'Die Rolle „' || ro.name || '“ haben noch ' || n || CASE WHEN n = 1 THEN ' Person' ELSE ' Personen' END || '. Bitte zuerst eine andere Rolle zuweisen.';
        ELSE
          UPDATE ally_rollen SET archiviert_am = now(), archiviert_von = s.person, geaendert_am = now(), geaendert_von = s.person WHERE schluessel = ro.schluessel;
          m := 'Rolle „' || ro.name || '“ liegt jetzt im Papierkorb. Sie lässt sich nicht mehr zuweisen und gibt keine Rechte mehr. Im Papierkorb kannst du sie wiederherstellen oder endgültig löschen.';
        END IF;
      ELSE
        IF ro.archiviert_am IS NULL THEN
          fehler := 'Die Rolle liegt nicht im Papierkorb.';
        ELSE
          UPDATE ally_rollen SET archiviert_am = NULL, archiviert_von = NULL, geaendert_am = now(), geaendert_von = s.person WHERE schluessel = ro.schluessel;
          m := 'Rolle „' || ro.name || '“ wiederhergestellt.';
        END IF;
      END IF;
    END IF;
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'schluessel', CASE WHEN fehler IS NULL THEN k END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_rollen_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
BEGIN
  -- Einstellungen › Team und Rollen (ALLY 23, Migration 64): Rollen (Admin fest, die übrigen legt der Admin an), Rechte-Katalog der gebuchten Pakete,
  -- wirksame Rechte je Person. Nur für Admins.
  -- Migration 156 (G2): auch die Rolle Talent (Art talent); je Rolle Paket, Vorlage, ob es einen Standard gibt und ob die Rechte ihm entsprechen;
  -- im Katalog je Recht nur_selbst (Recht gilt nur für die eigenen Daten eines Talents).
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND); END IF;
  IF NOT ally_hat_recht(s.person, 'admin') THEN RETURN jsonb_build_object('ok', true, 'darf', false); END IF;
  RETURN jsonb_build_object('ok', true, 'darf', true,
    'rollen', (SELECT coalesce(jsonb_agg(jsonb_build_object('schluessel', ro.schluessel, 'name', ro.name, 'beschreibung', ro.beschreibung, 'art', ro.art,
        'paket', ro.paket, 'vorlage', ro.vorlage, 'standard', ro.standard IS NOT NULL,
        'wie_standard', CASE WHEN ro.standard IS NOT NULL THEN coalesce((SELECT jsonb_object_agg(rr.recht, rr.reichweite) FROM ally_rollen_rechte rr WHERE rr.rolle = ro.schluessel), '{}'::jsonb) = ro.standard END,
        'archiviert', ro.archiviert_am IS NOT NULL, 'archiviert_am', CASE WHEN ro.archiviert_am IS NOT NULL THEN talents_datum(ro.archiviert_am) END,
        'kurz', ally_rolle_text(ro.schluessel),
        'personen', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.matrix_user_id, 'name', p.name, 'aktiv', p.aktiv) ORDER BY p.aktiv DESC, lower(p.name)), '[]'::jsonb)
                     FROM ally_personen p WHERE p.rolle = ro.schluessel),
        'rechte', (SELECT coalesce(jsonb_object_agg(rr.recht, coalesce(rr.reichweite, 'ja')), '{}'::jsonb) FROM ally_rollen_rechte rr WHERE rr.rolle = ro.schluessel))
      ORDER BY ro.art <> 'admin', ro.archiviert_am IS NOT NULL, lower(ro.name)), '[]'::jsonb)
      FROM ally_rollen ro WHERE ro.art IN ('admin', 'eigen', 'talent')),
    'katalog', (SELECT coalesce(jsonb_agg(jsonb_build_object('gruppe', g.gruppe, 'rechte', g.rechte) ORDER BY g.o), '[]'::jsonb) FROM (
        SELECT z.katalog_gruppe AS gruppe, min(z.katalog_sortierung) AS o,
          jsonb_agg(jsonb_build_object('schluessel', z.schluessel,
            -- Migration 90: Gruppe „Gemeinsame Postfächer“ = ein Häkchen je belegtem gemeinsamem Platz, beschriftet mit der Adresse
            -- Migration 167 (Bauplan B6): „Ordner freigeben: <Bezeichnung des Speicherorts>“ (T3)
            'name', coalesce(ally_postfach_platz_adresse(ally_postfach_platz_recht(z.schluessel)), CASE WHEN z.schluessel = 'speicherort_eigen' THEN ally_recht_name(z.schluessel) END,
              coalesce(z.katalog_name, z.name)),
            'text', CASE WHEN ally_postfach_platz_recht(z.schluessel) IS NOT NULL THEN coalesce((SELECT nullif(btrim(p.name), '') FROM ally_postfaecher p
              WHERE p.adresse = ally_postfach_platz_adresse(ally_postfach_platz_recht(z.schluessel)) AND lower(btrim(p.name)) <> p.adresse), '') ELSE coalesce(z.katalog_text, '') END,
            'reichweite', z.reichweite AND z.schluessel <> 'verkaufsberichte', 'nur_selbst', z.nur_selbst, 'reichweite_text', CASE WHEN z.reichweite THEN ally_reichweite_text(z.schluessel) END)
            ORDER BY z.katalog_sortierung, z.schluessel) AS rechte
        FROM ally_rechte z WHERE z.katalog_gruppe IS NOT NULL AND z.schluessel NOT IN ('admin', 'superadmin') AND (z.modul IS NULL OR plattform_modul_an(z.modul))
          AND (ally_postfach_platz_recht(z.schluessel) IS NULL OR ally_postfach_platz_adresse(ally_postfach_platz_recht(z.schluessel)) IS NOT NULL)
          AND (z.schluessel <> 'speicherort_eigen' OR coalesce((ally_speicherort_eigen()->>'eingerichtet')::boolean, false))  -- Migration 167 (Bauplan B6): T3, nur mit eingebundenem eigenem Speicherort
        GROUP BY z.katalog_gruppe) g),
    'personen', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.matrix_user_id,
        'rolle_archiviert', EXISTS (SELECT 1 FROM ally_rollen ro WHERE ro.schluessel = p.rolle AND ro.archiviert_am IS NOT NULL),
        'wirksam', CASE WHEN p.aktiv AND ally_hat_recht(p.matrix_user_id, 'admin') THEN '[]'::jsonb ELSE
          (SELECT coalesce(jsonb_agg(ally_recht_name(z.schluessel) || CASE WHEN z.reichweite THEN ' (' || CASE ally_recht_reichweite(p.matrix_user_id, z.schluessel) WHEN 'alle' THEN 'alle' ELSE ally_reichweite_text(z.schluessel) END || ')' ELSE '' END
                    ORDER BY z.katalog_sortierung, z.schluessel), '[]'::jsonb)
           FROM ally_rechte z WHERE z.katalog_gruppe IS NOT NULL AND z.schluessel NOT IN ('admin', 'superadmin') AND ally_recht_reichweite(p.matrix_user_id, z.schluessel) IS NOT NULL) END,
        'speicherort', ally_speicherort_darf(p.matrix_user_id, 'eigen'),
        -- Migration 166 (Bauplan B5d): je Team-Person die Rechte wie gerechnet (ally_recht_roh) und ohne eigene Rechte (Basis) für „Eigene Rechte“ im Person-Fenster;
        -- nicht für Talents (Talent-Profil) und nicht für Admins (haben alle Rechte), wie ally_person_eigene_rechte_setzen
        -- Migration 167 (Bauplan B6): Prüfbericht M166 N6: nicht bei einer Rolle der Art talent
        'rechte', CASE WHEN NOT ally_person_ist_talent(p.matrix_user_id) AND NOT ally_rolle_ist_talent(p.rolle) AND coalesce(p.rolle, '') <> 'admin'
            AND NOT EXISTS (SELECT 1 FROM ally_nutzer_rechte n WHERE n.matrix_user_id = p.matrix_user_id AND n.recht IN ('admin', 'superadmin'))
          THEN (SELECT coalesce(jsonb_object_agg(k.k, k.r) FILTER (WHERE k.r IS NOT NULL), '{}'::jsonb)
          FROM (SELECT x.k, ally_recht_roh(p.matrix_user_id, x.k) AS r FROM ally_person_rechte_katalog() AS x(k)) k) END,
        'basis', CASE WHEN NOT ally_person_ist_talent(p.matrix_user_id) AND NOT ally_rolle_ist_talent(p.rolle) AND coalesce(p.rolle, '') <> 'admin'
            AND NOT EXISTS (SELECT 1 FROM ally_nutzer_rechte n WHERE n.matrix_user_id = p.matrix_user_id AND n.recht IN ('admin', 'superadmin'))
          THEN ally_person_rechte_basis(p.matrix_user_id) END) ORDER BY p.id), '[]'::jsonb)
      FROM ally_personen p));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_schluessel()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  k text := ally_schluessel_roh();
BEGIN
  IF k IS NULL OR length(k) < 32 THEN
    RAISE EXCEPTION 'Verschlüsselung ist nicht eingerichtet.';
  END IF;
  RETURN k;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_schluessel_roh()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(nullif(current_setting('ally.schluessel', true), ''),
    (SELECT nullif(substr(x.e, 17), '') FROM pg_db_role_setting s CROSS JOIN LATERAL unnest(s.setconfig) AS x(e)
     WHERE s.setrole = 0 AND s.setdatabase = (SELECT d.oid FROM pg_database d WHERE d.datname = current_database())
       AND x.e LIKE 'ally.schluessel=%'
     LIMIT 1))
$function$
;

CREATE OR REPLACE FUNCTION public.ally_speicherort_darf(p_user text, p_speicherort text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Darf die Person Ordner im Speicherort verwalten und für Talents freigeben (Migration 64)? Nur der eigene (externe) Speicherort, nie die Server-Ablage.
  -- Admin immer; sonst ein nicht entzogenes Recht für die Person oder für ihre (nicht archivierte) Rolle. Nur aktive Personen.
  SELECT p_speicherort = 'eigen' AND coalesce((ally_speicherort_eigen()->>'bereit')::boolean, false)
     AND EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = p_user AND p.aktiv)
     -- Migration 167 (Bauplan B6): T3, Katalogrecht „Ordner freigeben“ (Rolle oder eigene Rechte); Admins haben es immer
     AND coalesce(ally_hat_recht(p_user, 'speicherort_eigen'), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_speicherort_eigen()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Der eingebundene eigene Speicherort (Migration 64): bereit = Paket gebucht, WebDAV eingerichtet und geprüft. Ohne Zugangsdaten und Adresse.
  SELECT jsonb_build_object('bereit', coalesce(e.art = 'webdav' AND e.adresse IS NOT NULL AND e.geprueft_am IS NOT NULL AND plattform_modul_an('speicherort'), false),
    'eingerichtet', coalesce(e.art = 'webdav' AND e.adresse IS NOT NULL, false), 'paket', plattform_modul_an('speicherort'),
    'name', CASE WHEN e.art = 'webdav' THEN e.name END, 'art', CASE WHEN e.art = 'webdav' THEN 'WebDAV' END,
    'geprueft', CASE WHEN e.geprueft_am IS NOT NULL THEN talents_datum(e.geprueft_am) END,
    'inhalte_ordner', coalesce(nullif(btrim(ally_einstellung('inhalte_ordner')), ''), 'Inhalte'))
  FROM (SELECT 1) x LEFT JOIN ablage_einstellung e ON e.id = 1
$function$
;

CREATE OR REPLACE FUNCTION public.ally_speicherort_ui_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  z text := btrim(coalesce(d->>'ziel', '')); art text; wer text; nm text; x ally_speicherort_rechte%ROWTYPE;
  m text := NULL; fehler text := NULL;
BEGIN
  -- Rechte am eigenen Speicherort (ALLY 23, Migration 64, sp_*): sp_recht_neu (ziel = 'rolle:<schlüssel>' oder 'person:<Chat-Benutzer>'),
  -- sp_recht_entziehen (id; nur entzogen_am wird gesetzt). Nur Admins. Admins brauchen kein eigenes Recht. Meldung setzt die Funktion selbst.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT ally_hat_recht(s.person, 'admin') THEN
    fehler := 'Rechte an Speicherorten vergibt eine Person mit der Rolle Admin.';
  -- Migration 167 (Bauplan B6): T3, das Recht steht jetzt im Katalog (Rollen, eigene Rechte); die alte Tabelle wird nicht mehr beschrieben
  ELSIF p_aktion IN ('sp_recht_neu', 'sp_recht_entziehen') THEN
    fehler := 'Wer Ordner teilen darf, steht jetzt in den Rollen (Recht „Ordner teilen“) und bei einzelnen Personen unter „Eigene Rechte“.';
  ELSIF p_aktion = 'sp_recht_neu' THEN
    art := split_part(z, ':', 1); wer := substr(z, length(art) + 2);
    IF NOT coalesce((ally_speicherort_eigen()->>'eingerichtet')::boolean, false) THEN
      fehler := 'Es ist noch kein eigener Speicherort eingebunden.';
    ELSIF art = 'rolle' THEN
      SELECT ro.name INTO nm FROM ally_rollen ro WHERE ro.schluessel = wer AND ro.art = 'eigen' AND ro.archiviert_am IS NULL;
      IF nm IS NULL THEN fehler := 'Diese Rolle gibt es nicht oder sie ist archiviert.'; END IF;
    ELSIF art = 'person' THEN
      SELECT p.name INTO nm FROM ally_personen p WHERE p.matrix_user_id = wer AND p.aktiv;
      IF nm IS NULL THEN fehler := 'Diese Person gibt es nicht oder sie ist deaktiviert.';
      ELSIF ally_person_ist_talent(wer) THEN fehler := 'Den Zugang eines Talents änderst du im Talent-Profil.';  -- Migration 158 (Bauplan B3a): Talent-Personen ändert man im Talent-Profil.
      ELSIF ally_hat_recht(wer, 'admin') THEN fehler := nm || ' hat die Rolle Admin und darf das ohnehin.'; END IF;
    ELSE
      fehler := 'Bitte eine Rolle oder eine Person wählen.';
    END IF;
    IF fehler IS NULL THEN
      IF EXISTS (SELECT 1 FROM ally_speicherort_rechte r WHERE r.speicherort = 'eigen' AND r.entzogen_am IS NULL
                 AND (art = 'rolle' AND r.rolle = wer OR art = 'person' AND r.person = wer)) THEN
        fehler := nm || ' hat dieses Recht schon.';
      ELSE
        INSERT INTO ally_speicherort_rechte (speicherort, rolle, person, erteilt_von)
        VALUES ('eigen', CASE WHEN art = 'rolle' THEN wer END, CASE WHEN art = 'person' THEN wer END, s.person);
        m := CASE WHEN art = 'rolle' THEN 'Rolle „' || nm || '“' ELSE nm END || ' darf jetzt Ordner im Speicherort verwalten und mit Talents teilen.';
      END IF;
    END IF;
  ELSIF p_aktion = 'sp_recht_entziehen' THEN
    SELECT * INTO x FROM ally_speicherort_rechte r WHERE r.id = CASE WHEN coalesce(d->>'id', '') ~ '^[0-9]{1,12}$' THEN (d->>'id')::bigint END AND r.entzogen_am IS NULL FOR UPDATE;
    IF NOT FOUND THEN
      fehler := 'Dieses Recht gibt es nicht (mehr). Bitte die Seite neu laden.';
    ELSE
      UPDATE ally_speicherort_rechte SET entzogen_am = now(), entzogen_von = s.person WHERE id = x.id;
      m := 'Recht am Speicherort entzogen. Bereits geteilte Ordner bleiben geteilt; Inhalte werden nicht gelöscht.';
    END IF;
  ELSE
    fehler := 'Diese Aktion gibt es nicht.';
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_speicherorte_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
DECLARE
  s record; e jsonb := ally_speicherort_eigen();
BEGIN
  -- Einstellungen › Organisation › Speicherorte (ALLY 23, Migration 64): eingebundene Speicherorte und wer Ordner im eigenen Speicherort verwalten
  -- und für Talents freigeben darf. Nur für Admins. Der Admin legt keine Ordner fest.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND); END IF;
  IF NOT ally_hat_recht(s.person, 'admin') THEN RETURN jsonb_build_object('ok', true, 'darf', false); END IF;
  RETURN jsonb_build_object('ok', true, 'darf', true, 'eigen', e,
    -- Migration 167 (Bauplan B6): „Wer Ordner freigeben darf“ entfällt (T3), das Recht steht im Katalog der Rollen und eigenen Rechte
    'freigaben', (SELECT count(*) FROM talent_ordner o WHERE o.beendet_am IS NULL));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_start_details(p_token text, p_teile text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
  c jsonb;
  u text;
  heute date := talents_heute();
  ks integer[];
  r jsonb := '{}'::jsonb;
BEGIN
  -- Migration 140 (Stefan 24.10.2026, 09:29–09:31): Inhalt der Überblick-Kacheln, nur lesend, nur angefragte und erlaubte Teile
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN NULL;
  END IF;
  p_teile := coalesce(p_teile, '{}'::text[]);

  IF 'talents' = ANY (p_teile) AND ally_ui_funktion_erlaubt(s.person, s.rolle, 'talents') THEN
    c := talents_ansicht_start(p_token);
    IF coalesce((c->>'ok')::boolean, false) THEN
      u := c->>'u';
      ks := ARRAY(SELECT k.id FROM talent_kanaele k JOIN talents t ON t.id = k.talent_id
                  WHERE t.status = 'aktiv' AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u)));
      r := r || jsonb_build_object(
        -- je Plattform wie talents_kachel: verbunden (auch die bald ablaufenden), davon läuft bald ab (unter 7 Tagen), abgelaufen
        'plattformen', (SELECT coalesce(jsonb_agg(jsonb_build_object('plattform', x.plattform, 'name', talents_plattform_name(x.plattform),
                           'verbunden', x.v, 'bald', x.b, 'abgelaufen', x.a) ORDER BY array_position(talents_plattformen(), x.plattform)), '[]'::jsonb)
                        FROM (SELECT k.plattform, count(*) FILTER (WHERE k.status = 'verbunden') AS v,
                                     count(*) FILTER (WHERE k.status = 'verbunden' AND k.gueltig_bis IS NOT NULL AND k.gueltig_bis < now() + interval '7 days') AS b,
                                     count(*) FILTER (WHERE k.status = 'abgelaufen') AS a
                              FROM talent_kanaele k WHERE k.id = ANY (ks) GROUP BY k.plattform
                              HAVING count(*) FILTER (WHERE k.status IN ('verbunden', 'abgelaufen')) > 0) x),
        -- 8 Blöcke zu 7 Tagen bis gestern (Block 1 = heute-7 … heute-1), Summen wie talents_zahlen ohne manuelle Werte
        'wochen', (SELECT jsonb_agg(jsonb_build_object('von', to_char(heute - 7 * g, 'YYYY-MM-DD'), 'bis', to_char(heute - 7 * g + 6, 'YYYY-MM-DD'),
                         'reichweite', w.r, 'interaktionen', w.i, 'tage', coalesce(w.t, 0)) ORDER BY g DESC)
                   FROM generate_series(1, 8) g
                   LEFT JOIN (SELECT ((heute - 1 - kt.tag) / 7) + 1 AS blk, sum(talents_zahl(kt.werte->'reach')) AS r, sum(talents_interaktionen(kt.werte)) AS i,
                                     count(DISTINCT kt.tag) FILTER (WHERE talents_zahl(kt.werte->'reach') IS NOT NULL OR talents_interaktionen(kt.werte) IS NOT NULL) AS t
                              FROM talent_kanal_tage kt WHERE kt.kanal_id = ANY (ks) AND kt.tag BETWEEN heute - 56 AND heute - 1 GROUP BY 1) w ON w.blk = g));
    END IF;
  END IF;

  IF 'belege' = ANY (p_teile) AND plattform_modul_an('belege') AND ally_ui_funktion_erlaubt(s.person, s.rolle, 'belege') THEN
    r := r || jsonb_build_object('belege', (SELECT coalesce(jsonb_agg(jsonb_build_object('wer', x.wer, 'betreff', x.betreff, 'datum', x.datum) ORDER BY x.o), '[]'::jsonb)
      FROM (SELECT row_number() OVER (ORDER BY coalesce(b.email_date, b.created_at) DESC NULLS LAST, b.id DESC) AS o,
                   left(coalesce(nullif(btrim(b.creditor_name_extrahiert), ''), nullif(btrim(b.sender), ''), 'Unbekannt'), 120) AS wer,
                   left(coalesce(b.subject, ''), 160) AS betreff, to_char(coalesce(b.email_date, b.created_at), 'DD.MM.YYYY') AS datum
            FROM beleg_verarbeitung b WHERE b.processing_status = 'neu'
            ORDER BY coalesce(b.email_date, b.created_at) DESC NULLS LAST, b.id DESC LIMIT 3) x));
  END IF;

  IF 'mails' = ANY (p_teile) AND plattform_modul_an('mail_entwuerfe') AND ally_ui_funktion_erlaubt(s.person, s.rolle, 'mail-assistent') THEN
    r := r || jsonb_build_object('vorschlaege', (SELECT coalesce(jsonb_agg(jsonb_build_object('wer', x.wer, 'betreff', x.betreff, 'datum', x.datum) ORDER BY x.o), '[]'::jsonb)
      FROM (SELECT row_number() OVER (ORDER BY m.erstellt_am DESC, m.id DESC) AS o,
                   left(coalesce(nullif(btrim(m.absender_name), ''), nullif(btrim(m.absender), ''), 'Unbekannt'), 120) AS wer,
                   left(coalesce(m.betreff, ''), 160) AS betreff, to_char(m.erstellt_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY') AS datum
            FROM mail_rueckfragen m WHERE m.status = 'offen' AND m.art = 'antwort' AND m.erstellt_am > now() - interval '14 days'
              AND ally_postfach_zustaendig(s.person, m.postfach)
            ORDER BY m.erstellt_am DESC, m.id DESC LIMIT 3) x));
  END IF;

  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_startseite_auswahl(p_person text)
 RETURNS TABLE(schluessel text, name text, gruppe text)
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 169 (Startseite): wählbare Seiten = Funktionen der Leiste (art funktion), im Register an, Schalter nicht aus, Paket aktiviert
  -- (Funktionen ohne Paket gehören zum Basispaket). Mit p_person nur die Seiten, die diese Person sehen darf (ally_ui_funktion_erlaubt).
  SELECT f.schluessel, ally_ui_name(f.name), g.name
  FROM ally_ui_funktionen f
  LEFT JOIN ally_ui_gruppen g ON g.schluessel = f.gruppe
  LEFT JOIN ally_ui_funktion_schalter sch ON sch.schluessel = f.schluessel
  WHERE f.art = 'funktion' AND f.an AND coalesce(sch.an, true) AND (f.modul IS NULL OR plattform_modul_an(f.modul))
    AND (p_person IS NULL OR ally_ui_funktion_erlaubt(p_person, '', f.schluessel))
  ORDER BY coalesce(g.sortierung, 0), f.sortierung, f.schluessel
$function$
;

CREATE OR REPLACE FUNCTION public.ally_startseite_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
  vg text;
  meine text;
  start_name text := (SELECT ally_ui_name(f.name) FROM ally_ui_funktionen f WHERE f.schluessel = 'start');
BEGIN
  -- Migration 169 (Startseite): Daten für die Einstellungen. vorgabe/optionen nur für den Superadmin (alle Seiten aktivierter Pakete);
  -- meine/meine_optionen für die eigene Wahl (nur Seiten, die die Person sehen darf); gilt = Seite, die die Person jetzt als Startseite sieht.
  SELECT * INTO s FROM ally_ui_sitzung(p_token) x WHERE NOT x.muss_pw_setzen;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false); END IF;
  IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'start') THEN RETURN jsonb_build_object('ok', true, 'moeglich', false); END IF;
  vg := nullif(ally_einstellung('startseite_vorgabe'), '');
  SELECT x.seite INTO meine FROM ally_person_startseite x WHERE x.person = s.person;
  RETURN jsonb_build_object('ok', true, 'moeglich', true, 'start_name', start_name,
    'gilt', ally_startseite_ziel(s.person),
    'gilt_name', coalesce((SELECT ally_ui_name(f.name) FROM ally_ui_funktionen f WHERE f.schluessel = ally_startseite_ziel(s.person)), start_name),
    'meine', meine,
    'meine_optionen', coalesce((SELECT jsonb_agg(jsonb_build_object('wert', a.schluessel, 'text', a.name, 'gruppe', a.gruppe)) FROM ally_startseite_auswahl(s.person) a), '[]'::jsonb),
    'vorgabe_name', (SELECT a.name FROM ally_startseite_auswahl(NULL) a WHERE a.schluessel = vg),
    -- Auswahl für die eigene Wahl (Mein Konto › Startseite und „Startseite anordnen“, Stefan 29.10. 07:49 „a und c“): leer = wie für alle, 'start' = normale Startseite
    'meine_auswahl', jsonb_build_array(jsonb_build_object('wert', '', 'text', 'Wie für alle (' || coalesce((SELECT a.name FROM ally_startseite_auswahl(s.person) a WHERE a.schluessel = vg), start_name) || ')'),
        jsonb_build_object('wert', 'start', 'text', start_name))
      || coalesce((SELECT jsonb_agg(jsonb_build_object('wert', a.schluessel, 'text', coalesce(a.gruppe || ' › ', '') || a.name)) FROM ally_startseite_auswahl(s.person) a), '[]'::jsonb),
    'meine_info', 'Welche Seite du nach der Anmeldung siehst. Gilt nur für dich. „Wie für alle“ folgt der Vorgabe der Firma. Seiten, die du nicht sehen darfst, stehen nicht zur Wahl.')
    -- Migration 172 (B8b, Fixieren): die Startseite für alle stellen Admins ein (vorher nur Superadmins)
    || CASE WHEN coalesce(ally_hat_recht(s.person, 'admin'), false) THEN jsonb_build_object('superadmin', coalesce(ally_hat_recht(s.person, 'superadmin'), false), 'vorgabe_darf', true, 'vorgabe', vg,
      'optionen', coalesce((SELECT jsonb_agg(jsonb_build_object('wert', a.schluessel, 'text', a.name, 'gruppe', a.gruppe)) FROM ally_startseite_auswahl(NULL) a), '[]'::jsonb),
      'vorgabe_geaendert', (SELECT to_char(e.geaendert_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI') FROM ally_einstellungen e WHERE e.schluessel = 'startseite_vorgabe'))
    ELSE '{}'::jsonb END;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_startseite_ui_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  w text := btrim(coalesce(d->>'seite', ''));
  e jsonb;
  nein jsonb := '{"ok": false, "angemeldet": true}'::jsonb;
  ja jsonb := '{"ok": true, "angemeldet": true}'::jsonb;
BEGIN
  -- Migration 169 (Startseite): st_vorgabe (Superadmin, Startseite für alle; leer = keine Vorgabe) und st_meine (eigene Wahl; leer = wie für alle,
  -- 'start' = normale Startseite). NULL bei allen anderen Aktionen (ALLY 20 „Aktion ausführen“ fragt diese Funktion zuerst).
  IF coalesce(p_aktion, '') NOT IN ('st_vorgabe', 'st_meine') THEN RETURN NULL; END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN RETURN '{"ok": false, "angemeldet": false}'::jsonb; END IF;
  IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN
    RETURN coalesce(ally_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler', NULL), '{}'::jsonb) || '{"ok": false, "angemeldet": true, "ungueltig": true}'::jsonb;
  END IF;
  IF s.muss_pw_setzen THEN RETURN '{"ok": false, "angemeldet": true, "muss_pw_setzen": true}'::jsonb; END IF;
  -- Migration 172 (B8b, Fixieren): Häkchen „Fixiert“ des Superadmins (_fx_e, _fx_i, _fixiert) gilt für diese Aktion
  PERFORM ally_fix_wunsch(p_daten);
  IF jsonb_typeof(p_zustand->'z') = 'array' THEN
    FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
      IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN
        PERFORM ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen'));
      END IF;
    END LOOP;
  END IF;

  IF p_aktion = 'st_vorgabe' THEN
    -- Migration 172 (B8b, Fixieren): Admins (vorher nur Superadmins), außer die Startseite für alle ist fixiert
    IF NOT coalesce(ally_hat_recht(s.person, 'admin'), false) THEN
      PERFORM ally_web_meldung(p_token, 'Das dürfen nur Admins.', 'fehler', NULL); RETURN nein;
    END IF;
    IF NOT coalesce(ally_hat_recht(s.person, 'superadmin'), false) AND ally_fixiert('startseite_vorgabe', '') THEN
      PERFORM ally_web_meldung(p_token, 'Die Startseite für alle ist fixiert.', 'fehler', NULL); RETURN nein;
    END IF;
    IF w = '' THEN
      DELETE FROM ally_einstellungen WHERE schluessel = 'startseite_vorgabe';
      PERFORM ally_web_meldung(p_token, 'Gespeichert. Alle sehen die normale Startseite, sofern sie keine eigene gewählt haben.', 'ok', NULL); RETURN ja;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ally_startseite_auswahl(NULL) a WHERE a.schluessel = w) THEN
      PERFORM ally_web_meldung(p_token, 'Diese Seite lässt sich nicht als Startseite wählen.', 'fehler', NULL); RETURN nein;
    END IF;
    PERFORM ally_einstellung_setzen('startseite_vorgabe', w, s.person);
    PERFORM ally_web_meldung(p_token, 'Gespeichert. „' || (SELECT a.name FROM ally_startseite_auswahl(NULL) a WHERE a.schluessel = w) || '“ ist die Startseite für alle, die keine eigene gewählt haben.', 'ok', NULL);
    RETURN ja;
  END IF;

  -- st_meine
  IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'start') THEN
    PERFORM ally_web_meldung(p_token, 'Die Startseite lässt sich für dich nicht einstellen.', 'fehler', NULL); RETURN nein;
  END IF;
  IF w = '' THEN
    DELETE FROM ally_person_startseite WHERE person = s.person;
  ELSIF w = 'start' OR EXISTS (SELECT 1 FROM ally_startseite_auswahl(s.person) a WHERE a.schluessel = w) THEN
    INSERT INTO ally_person_startseite (person, seite, geaendert_am, geaendert_von) VALUES (s.person, w, now(), s.person)
    ON CONFLICT (person) DO UPDATE SET seite = EXCLUDED.seite, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von;
  ELSE
    PERFORM ally_web_meldung(p_token, 'Diese Seite lässt sich nicht als Startseite wählen.', 'fehler', NULL); RETURN nein;
  END IF;
  PERFORM ally_web_meldung(p_token, 'Gespeichert. Deine Startseite: „' || coalesce((SELECT ally_ui_name(f.name) FROM ally_ui_funktionen f WHERE f.schluessel = ally_startseite_ziel(s.person)), '') || '“.', 'ok', NULL);
  RETURN ja;
  -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung, die Änderungen dieser Aktion sind zurückgenommen
EXCEPTION WHEN SQLSTATE 'AT002' THEN
  RETURN ally_fix_meldung(p_token, SQLERRM);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_startseite_ziel(p_person text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 169 (Startseite): welche Seite die Person als Startseite sieht. Zuerst die eigene Wahl, dann die Vorgabe für alle, sonst 'start'.
  -- Eine Wahl gilt nur, solange die Seite wählbar ist und die Person sie sehen darf. Wer die normale Startseite nicht hat (Talents), bekommt 'start'
  -- (dort gilt weiter das Startziel aus Migration 161).
  SELECT CASE WHEN NOT ally_ui_funktion_erlaubt(p_person, '', 'start') THEN 'start' ELSE coalesce(
    (SELECT x.seite FROM ally_person_startseite x WHERE x.person = p_person
       AND (x.seite = 'start' OR EXISTS (SELECT 1 FROM ally_startseite_auswahl(p_person) a WHERE a.schluessel = x.seite))),
    (SELECT e.wert FROM ally_einstellungen e WHERE e.schluessel = 'startseite_vorgabe'
       AND EXISTS (SELECT 1 FROM ally_startseite_auswahl(p_person) a WHERE a.schluessel = e.wert)),
    'start') END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_superadmin_erlaubt(p_user text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 168 (Bauplan B7, G1): steht die Person in der Liste superadmin_personen?
  SELECT coalesce(p_user, '') <> '' AND EXISTS (SELECT 1 FROM unnest(string_to_array(ally_einstellung('superadmin_personen'), ',')) AS x(id) WHERE btrim(x.id) = p_user)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_superadmin_liste_schutz()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Migration 168 (Bauplan B7, G1): auf ally_nutzer_rechte das Recht Superadmin nur für Personen aus der Liste superadmin_personen. Eine bestehende
  -- Zeile bleibt unberührt. Test-Personen verwirft ally_testdaten_trennung wie bisher still. Auf ally_einstellungen: die Liste selbst ändert nur eine Migration.
  IF TG_TABLE_NAME = 'ally_einstellungen' THEN
    IF TG_OP <> 'INSERT' THEN
      IF OLD.schluessel = 'superadmin_personen' THEN
        RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Wer Superadmin sein darf, legt eine Migration fest. Hier lässt sich das nicht ändern.';
      END IF;
    END IF;
    IF TG_OP <> 'DELETE' THEN
      IF NEW.schluessel = 'superadmin_personen' THEN
        RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Wer Superadmin sein darf, legt eine Migration fest. Hier lässt sich das nicht ändern.';
      END IF;
      RETURN NEW;
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.recht = 'superadmin' AND NOT ally_superadmin_erlaubt(NEW.matrix_user_id) AND NOT coalesce(ally_person_ist_testdaten(NEW.matrix_user_id), false) THEN
    IF TG_OP = 'INSERT' THEN
      IF NOT EXISTS (SELECT 1 FROM ally_nutzer_rechte x WHERE x.matrix_user_id = NEW.matrix_user_id AND x.recht = 'superadmin') THEN
        RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Das Recht Superadmin lässt sich hier nicht vergeben.';
      END IF;
    ELSIF OLD.recht IS DISTINCT FROM NEW.recht OR OLD.matrix_user_id IS DISTINCT FROM NEW.matrix_user_id THEN
      RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Das Recht Superadmin lässt sich hier nicht vergeben.';
    END IF;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_superadmin_schutz()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.recht = 'superadmin'
     AND (TG_OP = 'DELETE' OR NEW.recht IS DISTINCT FROM 'superadmin' OR NEW.matrix_user_id IS DISTINCT FROM OLD.matrix_user_id)
     AND NOT EXISTS (SELECT 1 FROM ally_nutzer_rechte r WHERE r.recht = 'superadmin' AND r.matrix_user_id <> OLD.matrix_user_id) THEN
    RAISE EXCEPTION 'Der letzte Superadmin kann nicht entfernt werden. Bitte zuerst einer anderen Person das Recht Superadmin geben.';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_absender_abschliessen(p_token text, p_ergebnis jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; e jsonb := CASE WHEN jsonb_typeof(p_ergebnis) = 'object' THEN p_ergebnis ELSE '{}'::jsonb END; modus text; ok boolean; meld text; txt text; art text := 'ok'; adr text;
BEGIN
  -- Ergebnis von ALLY 39 (Zugangsdaten „Systemnachrichten – Versand (SMTP)“ gesetzt/geprüft/geleert) eintragen; nur mit Admin-Sitzung (ALLY 20 „Versand-Ergebnis“).
  -- Eingerichtet (und damit aktiv) nur nach erfolgreicher Prüfung der Verbindung.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen OR NOT coalesce(ally_hat_recht(s.person, 'admin'), false) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND); END IF;
  modus := coalesce(e->>'modus', '');
  ok := coalesce(e->>'test_status', '') = 'OK' AND (modus <> 'speichern' OR coalesce(e->>'patch_status', '') = '200');
  meld := left(btrim(regexp_replace(coalesce(nullif(e->>'patch_meldung', ''), nullif(e->>'test_meldung', ''), nullif(e->>'fehler', ''), ''), '\s+', ' ', 'g')), 250);
  IF modus IN ('speichern', 'pruefen') THEN
    UPDATE ally_systemnachricht_absender SET eingerichtet = ok, geprueft_am = now(), pruef_ergebnis = CASE WHEN ok THEN 'ok' ELSE coalesce(nullif(meld, ''), 'keine Antwort') END
    WHERE id RETURNING adresse INTO adr;
    IF adr IS NULL THEN
      txt := 'Es ist kein Absender-Postfach eingestellt.'; art := 'fehler';
    ELSIF modus = 'speichern' AND coalesce(e->>'patch_status', '') <> '200' THEN
      txt := 'Die Zugangsdaten konnten nicht gespeichert werden: ' || coalesce(nullif(meld, ''), 'unbekannter Fehler') || '. Es wird nichts versendet.'; art := 'fehler';
    ELSIF ok THEN
      txt := CASE WHEN modus = 'speichern' THEN 'Absender-Postfach ' || adr || ' gespeichert und geprüft: Die Verbindung klappt. Systemnachrichten gehen ab jetzt per Mail raus.'
                  ELSE 'Verbindung für ' || adr || ' geprüft: Sie klappt.' END;
    ELSE
      txt := CASE WHEN modus = 'speichern' THEN 'Absender-Postfach ' || adr || ' gespeichert, aber die Prüfung ist fehlgeschlagen: ' ELSE 'Verbindung für ' || adr || ' geprüft: Sie klappt nicht: ' END
        || coalesce(nullif(meld, ''), 'keine Antwort') || '. Bitte Server, Port, Anmeldename und Passwort prüfen. Bis dahin wird nichts versendet.';
      art := 'fehler';
    END IF;
  ELSIF modus = 'leeren' THEN
    txt := 'Absender-Postfach entfernt. Es werden keine Systemnachrichten mehr per Mail versendet; Links stehen wieder zum Kopieren bereit.'
      || CASE WHEN coalesce(e->>'patch_status', '') <> '200' THEN ' Die gespeicherten Zugangsdaten konnten nicht geleert werden (' || coalesce(nullif(meld, ''), 'unbekannter Fehler') || ').' ELSE '' END;
  ELSE
    txt := 'Das Ergebnis der Prüfung ist unbekannt. Bitte noch einmal versuchen.'; art := 'fehler';
  END IF;
  PERFORM ally_web_meldung(p_token, txt, art, NULL);
  RETURN jsonb_build_object('ok', art = 'ok', 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_absender_stand()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  a ally_systemnachricht_absender%ROWTYPE; adr text; cred text; cred_ok boolean; aus boolean;
BEGIN
  -- Stand des Absender-Postfachs für Systemnachrichten (BA8). aktiv = eingestellt, Verbindung geprüft, Zugang für den Versand vorhanden und
  -- (bei einem Postfach-Platz) die Adresse des Platzes unverändert. Sonst wird nichts versendet und Links stehen zum Kopieren bereit (wie bisher).
  cred := btrim(coalesce(ally_einstellung('systemnachrichten_credential_id'), ''));
  cred_ok := cred ~ '^[A-Za-z0-9]{8,40}$';
  SELECT * INTO a FROM ally_systemnachricht_absender x WHERE x.id;
  IF NOT FOUND THEN RETURN jsonb_build_object('vorhanden', false, 'aktiv', false, 'credential_bereit', cred_ok); END IF;
  adr := CASE WHEN a.art = 'platz' THEN (SELECT lower(btrim(p.adresse)) FROM postfach_plaetze p WHERE p.platz = a.platz) ELSE a.adresse END;
  -- Migration 88 (Stefan 22.10.2026, 16:56): ist für das Postfach mit dieser Adresse „Versand erlauben“ ausgeschaltet, sendet Ally auch keine Systemnachrichten darüber
  aus := EXISTS (SELECT 1 FROM postfach_plaetze p WHERE lower(p.adresse) = lower(a.adresse) AND p.versand_erlaubt IS FALSE);
  RETURN jsonb_build_object('vorhanden', true, 'art', a.art, 'platz', a.platz, 'adresse', a.adresse, 'platz_adresse', CASE WHEN a.art = 'platz' THEN adr END,
    'name', a.name, 'smtp_host', a.smtp_host, 'smtp_port', a.smtp_port, 'smtp_benutzer', a.smtp_benutzer, 'eingerichtet', a.eingerichtet,
    'geprueft', CASE WHEN a.geprueft_am IS NOT NULL THEN talents_zeit(a.geprueft_am) END, 'pruef_ergebnis', a.pruef_ergebnis,
    'credential_bereit', cred_ok, 'credential_id', CASE WHEN cred_ok THEN cred END,
    'platz_geaendert', a.art = 'platz' AND adr IS DISTINCT FROM a.adresse, 'versand_aus', aus,
    'aktiv', a.eingerichtet AND cred_ok AND ally_mail_gueltig(a.adresse) AND (a.art = 'eigen' OR adr = a.adresse) AND NOT aus);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_absender_web(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record; st jsonb;
BEGIN
  -- Einstellungen › Postfächer › Absender für Systemnachrichten (ALLY 23, nur Admin): Stand, Auswahl der eingebundenen Postfächer, Zahlen, letzte 20 Nachrichten
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen OR NOT coalesce(ally_hat_recht(s.person, 'admin'), false) THEN RETURN jsonb_build_object('ok', false); END IF;
  st := ally_systemnachricht_absender_stand();
  RETURN jsonb_build_object('ok', true, 'stand', st - 'credential_id',
    'ki_hinweis', coalesce(ally_einstellung('ki_hinweis_system'), 'aus') = 'an',  -- Migration 96
    'plaetze', (SELECT coalesce(jsonb_agg(jsonb_build_object('platz', p.platz, 'adresse', lower(btrim(p.adresse))) ORDER BY p.platz), '[]'::jsonb)
                FROM postfach_plaetze p WHERE nullif(btrim(coalesce(p.adresse, '')), '') IS NOT NULL AND p.versand_erlaubt IS NOT FALSE
                  AND NOT EXISTS (SELECT 1 FROM ally_postfaecher f WHERE f.adresse = lower(btrim(p.adresse)) AND f.art = 'persoenlich')),  -- Migration 90: nur gemeinsame  -- Migration 88: ausgeschaltete nicht anbieten
    'vorschlag_name', coalesce(nullif(btrim(coalesce(eigenes_unternehmen()->>'name', '')), ''), produkt_name()),
    'zahlen', (SELECT jsonb_build_object('wartet', count(*) FILTER (WHERE x.status IN ('wartet', 'in_arbeit')),
        'gesendet_24h', count(*) FILTER (WHERE x.status = 'gesendet' AND x.erledigt_am > now() - interval '24 hours'),
        'fehler_7t', count(*) FILTER (WHERE x.status IN ('fehler', 'unklar') AND x.erledigt_am > now() - interval '7 days'),
        'nicht_gesendet_7t', count(*) FILTER (WHERE x.status = 'verfallen' AND x.erledigt_am > now() - interval '7 days'))
      FROM ally_systemnachrichten x),
    'letzte', (SELECT coalesce(jsonb_agg(jsonb_build_object('zeit', talents_zeit(coalesce(q.erledigt_am, q.in_arbeit_seit, q.erstellt_am)), 'art', ally_systemnachricht_art_text(q.art),
        'an', coalesce(q.an, ''), 'betreff', coalesce(q.betreff, ''), 'status', q.status,
        'status_text', CASE q.status WHEN 'wartet' THEN 'wartet' WHEN 'in_arbeit' THEN 'wird gesendet' WHEN 'gesendet' THEN 'gesendet' WHEN 'fehler' THEN 'Fehler'
                                     WHEN 'verfallen' THEN 'nicht gesendet' ELSE 'unklar' END, 'grund', coalesce(q.grund, '')) ORDER BY q.id DESC), '[]'::jsonb)
      FROM (SELECT * FROM ally_systemnachrichten x ORDER BY x.id DESC LIMIT 20) q));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_aktiv()
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((ally_systemnachricht_absender_stand()->>'aktiv')::boolean, false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_art_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'zugang_talent' THEN 'Zugangslink (Talent)' WHEN 'zugang_person' THEN 'Zugangslink (Person)' WHEN 'passwort' THEN 'Passwort vergessen'
    WHEN 'aufgabe' THEN 'Termin, Aufgabe oder Erinnerung' WHEN 'test' THEN 'Testnachricht' WHEN 'email_aendern' THEN 'E-Mail-Adresse bestätigen' WHEN 'einladung' THEN 'Einladung (Talent)' ELSE coalesce(p, '') END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_ergebnis(p_id bigint, p_ok boolean, p_meldung text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  q ally_systemnachrichten%ROWTYPE; adm text;
BEGIN
  -- Ergebnis eines Versands (SYS 9): nur für Nachrichten „in_arbeit“; danach kein zweiter Versand. Geheimcode wird gelöscht. Aufgabe: Mail gesendet bzw. nicht gesendet.
  -- Fehler: Benachrichtigung an die Admins (höchstens eine je Tag).
  UPDATE ally_systemnachrichten SET status = CASE WHEN p_ok THEN 'gesendet' ELSE 'fehler' END, erledigt_am = now(), geheim = NULL,
    grund = CASE WHEN p_ok THEN NULL ELSE left(coalesce(nullif(btrim(regexp_replace(coalesce(p_meldung, ''), '\s+', ' ', 'g')), ''), 'unbekannter Fehler'), 300) END
  WHERE id = p_id AND status = 'in_arbeit' RETURNING * INTO q;
  IF q.id IS NULL THEN RETURN jsonb_build_object('ok', false); END IF;
  IF q.art = 'aufgabe' THEN
    UPDATE talent_aufgaben SET mail_status = CASE WHEN p_ok THEN 'gesendet' ELSE 'fehler' END WHERE id = q.aufgabe_id AND ics_sequenz = q.aufgabe_sequenz AND mail_status = 'offen';
  END IF;
  IF NOT p_ok AND q.art = 'einladung' THEN PERFORM talent_einladung_fehler_melden('system', q.id); END IF;   -- Migration 192: einladende Person
  IF NOT p_ok THEN
    FOR adm IN SELECT y.matrix_user_id FROM ally_personen y WHERE y.aktiv AND coalesce(ally_hat_recht(y.matrix_user_id, 'admin'), false) ORDER BY y.id LOOP
      PERFORM ally_benachrichtigen(adm, 'systemnachrichten', 'Systemnachricht nicht versendet',
        'Mindestens eine Mail konnte nicht versendet werden (' || ally_systemnachricht_art_text(q.art) || '): ' || q.grund,
        jsonb_build_object('seite', 'einstellungen', 'parameter', jsonb_build_object('bereich', 'postfaecher'), 'anker', 'a-systemnachrichten'),
        'systemnachrichten:' || to_char(now() AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD'), 'SYS 9', false);
    END LOOP;
  END IF;
  RETURN jsonb_build_object('ok', true, 'status', q.status);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_inhalt(p_id bigint, p_tok text, p_stand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  q ally_systemnachrichten%ROWTYPE; a talent_aufgaben%ROWTYPE; cd jsonb; f jsonb; m jsonb;   -- Migration 192: m
  basis text := talent_ui_adresse(); produkt text := produkt_name(); firma text; absender text := coalesce(p_stand->>'name', ''); adr text := coalesce(p_stand->>'adresse', '');
  name text; betreff text; vor text[] := '{}'; details text[] := '{}'; nach text[] := '{}'; knopf text; link text; ics text; bis timestamptz;
  dunkel text; hell text; schrift text; txt text; html text; mit_bereich boolean;
  ki boolean := coalesce(ally_einstellung('ki_hinweis_system'), 'aus') = 'an';  -- Migration 96: KI-Hinweis (Einstellung, Standard aus)
BEGIN
  -- Inhalt einer Systemnachricht (BA8): Betreff, Text, HTML im Corporate Design (Farben aus cd_daten), bei Terminen eine .ics-Datei. Neutral und genderneutral,
  -- Absendername aus den Einstellungen, nie im Namen einer Person. Links mit Geheimcode nur hier (aus dem entschlüsselten Code); NULL = nicht (mehr) sendbar.
  SELECT * INTO q FROM ally_systemnachrichten x WHERE x.id = p_id;
  IF q.id IS NULL OR absender = '' THEN RETURN NULL; END IF;
  -- Migration 192: Einladung zum Verbinden der Accounts (talent_einladung_mail, Systemweg: CD mit Logo, Knopf „Accounts verbinden“, Textteil, Fußzeile)
  IF q.art = 'einladung' THEN
    m := talent_einladung_mail(q.einladung_id, 'system', q.erstellt_von, NULL, true);
    IF NOT coalesce((m->>'ok')::boolean, false) THEN RETURN NULL; END IF;
    RETURN jsonb_build_object('betreff', m->>'betreff', 'text', m->>'text', 'html', m->>'html', 'ics', NULL, 'ics_name', NULL);
  END IF;
  firma := coalesce(nullif(btrim(coalesce(eigenes_unternehmen()->>'name', '')), ''), produkt);
  name := CASE WHEN q.person IS NOT NULL THEN (SELECT y.name FROM ally_personen y WHERE y.matrix_user_id = q.person)
               ELSE coalesce(talent_anzeigename(q.talent_id), talent_listenname(q.talent_id)) END;
  IF q.art = 'email_aendern' THEN
    -- Migration 70: Bestätigung im Profil der neuen Oberfläche (nur mit der eigenen Anmeldung)
    IF basis IS NULL OR coalesce(p_tok, '') !~ '^[0-9a-f]{64}$' THEN RETURN NULL; END IF;
    link := basis || '?seite=einstellungen&bereich=profil&em=' || p_tok;
  ELSIF q.art IN ('zugang_talent', 'zugang_person', 'passwort') THEN
    IF basis IS NULL OR coalesce(p_tok, '') !~ '^[0-9a-f]{64}$' THEN RETURN NULL; END IF;
    link := basis || '?seite=passwort-neu&code=' || p_tok;
  END IF;
  IF q.art = 'test' THEN
    betreff := 'Testnachricht von ' || produkt;
    vor := ARRAY['diese Testnachricht zeigt, dass ' || produkt || ' Systemnachrichten über das Absender-Postfach ' || adr || ' versenden kann. Du musst nichts weiter tun.'];
  ELSIF q.art = 'zugang_talent' THEN
    SELECT z.einladung_bis INTO bis FROM talent_zugaenge z WHERE z.talent_id = q.talent_id;
    betreff := 'Dein Zugang bei ' || firma;
    vor := ARRAY['für dich ist ein eigener Bereich bei ' || firma || ' eingerichtet. Dort siehst du deine Aufgaben, Termine und Kampagnen und verbindest deine Accounts selbst.',
                 'Über den folgenden Link legst du dein Passwort fest. Der Link gilt bis ' || coalesce(talents_zeit(bis), '–') || ' und nur einmal.'];
    nach := ARRAY['Danach meldest du dich mit dieser E-Mail-Adresse und deinem Passwort hier an: ' || basis];
    knopf := 'Passwort festlegen';
  ELSIF q.art = 'zugang_person' THEN
    betreff := 'Dein Zugang zu ' || produkt;
    vor := ARRAY['für dich ist ein Zugang zu ' || produkt || ' bei ' || firma || ' eingerichtet.',
                 'Über den folgenden Link legst du dein Passwort fest. Der Link gilt sieben Tage und nur einmal.'];
    nach := ARRAY['Danach meldest du dich mit dieser E-Mail-Adresse und deinem Passwort hier an: ' || basis];
    knopf := 'Passwort festlegen';
  ELSIF q.art = 'email_aendern' THEN
    betreff := 'Neue E-Mail-Adresse für ' || produkt || ' bestätigen';
    vor := ARRAY['jemand, vermutlich du, möchte diese E-Mail-Adresse für die Anmeldung bei ' || produkt || ' verwenden. Über den folgenden Link bestätigst du das; '
      || 'dafür meldest du dich wie bisher an. Der Link gilt 24 Stunden und nur einmal.'];
    nach := ARRAY['Wenn du das nicht angefordert hast, kannst du diese Mail ignorieren. Es ändert sich dann nichts.'];
    knopf := 'E-Mail-Adresse bestätigen';
  ELSIF q.art = 'passwort' THEN
    betreff := 'Neues Passwort für ' || produkt;
    vor := ARRAY['jemand, vermutlich du, möchte ein neues Passwort für ' || produkt || ' festlegen. Über den folgenden Link geht das. Der Link gilt eine Stunde und nur einmal.'];
    nach := ARRAY['Wenn du das nicht angefordert hast, kannst du diese Mail ignorieren. Dein bisheriges Passwort bleibt dann gültig.'];
    knopf := 'Neues Passwort festlegen';
  ELSIF q.art = 'aufgabe' THEN
    SELECT * INTO a FROM talent_aufgaben x WHERE x.id = q.aufgabe_id;
    IF a.id IS NULL THEN RETURN NULL; END IF;
    mit_bereich := basis IS NOT NULL AND EXISTS (SELECT 1 FROM talent_zugaenge z WHERE z.talent_id = a.talent_id AND z.aktiv AND z.pw_hash IS NOT NULL);
    betreff := CASE WHEN a.status = 'abgesagt' THEN talents_planung_art_text(a.art) || ' abgesagt: '
                    WHEN a.art = 'erinnerung' THEN 'Erinnerung: '
                    WHEN a.art = 'termin' THEN CASE WHEN q.aufgabe_sequenz > 0 THEN 'Termin geändert: ' ELSE 'Neuer Termin: ' END
                    WHEN a.art = 'review' THEN CASE WHEN q.aufgabe_sequenz > 0 THEN 'Review geändert: ' ELSE 'Review zu Content: ' END
                    ELSE CASE WHEN q.aufgabe_sequenz > 0 THEN 'Aufgabe geändert: ' ELSE 'Neue Aufgabe: ' END END || a.titel;
    vor := ARRAY[CASE WHEN a.status = 'abgesagt' THEN 'dieser Eintrag ist abgesagt:' WHEN a.art = 'erinnerung' THEN 'eine Erinnerung von ' || firma || ':'
                      WHEN q.aufgabe_sequenz > 0 THEN 'ein Eintrag für dich wurde geändert:' ELSE 'es gibt einen neuen Eintrag für dich:' END];
    details := array_remove(ARRAY['Was: ' || a.titel,
      CASE WHEN coalesce(a.beginn, a.faellig_am) IS NOT NULL THEN CASE WHEN a.art IN ('aufgabe', 'review') THEN 'Bis: ' ELSE 'Wann: ' END
        || talents_planung_zeit_text(coalesce(a.beginn, a.faellig_am), a.ganztags)
        || CASE WHEN a.art = 'termin' AND a.ende IS NOT NULL THEN ' bis ' || talents_planung_zeit_text(a.ende, a.ganztags) ELSE '' END END,
      CASE WHEN a.ort IS NOT NULL THEN 'Ort: ' || a.ort END,
      (SELECT 'Kampagne: ' || k.marke || ' – ' || k.name FROM talent_kampagnen k WHERE k.id = a.kampagne_id),
      (SELECT 'Deliverable: ' || talents_planung_deliverable_name(d.format, d.anzahl, d.titel) FROM talent_deliverables d WHERE d.id = a.deliverable_id)], NULL);
    nach := array_remove(ARRAY[nullif(btrim(a.text), ''),
      CASE WHEN a.art = 'termin' AND a.status <> 'abgesagt' THEN 'Im Anhang steht der Termin als Kalenderdatei (.ics) zum Übernehmen in deinen Kalender.' END,
      CASE WHEN mit_bereich THEN 'Mehr dazu in deinem Bereich: ' || basis END], NULL);
    IF a.art = 'termin' THEN
      ics := ally_ics_datei(ally_ics_aufgabe(a.id, false));
    END IF;
  ELSE
    RETURN NULL;
  END IF;
  -- Text
  txt := 'Hallo' || coalesce(' ' || nullif(btrim(name), ''), '') || ',' || E'\n\n' || array_to_string(vor, E'\n\n')
    || CASE WHEN cardinality(details) > 0 THEN E'\n\n' || array_to_string(details, E'\n') ELSE '' END
    || CASE WHEN link IS NOT NULL THEN E'\n\n' || link ELSE '' END
    || CASE WHEN cardinality(nach) > 0 THEN E'\n\n' || array_to_string(nach, E'\n\n') ELSE '' END
    || E'\n\nViele Grüße\n' || absender || CASE WHEN ki THEN E'\n\nErstellt mit KI-Unterstützung.' ELSE '' END || E'\n\n--\nDiese Nachricht wurde automatisch versendet.';
  -- HTML im Corporate Design (Farben und Schrift aus cd_daten, sonst neutral)
  cd := cd_daten(NULL); f := coalesce(cd->'farben', '{}'::jsonb);
  dunkel := CASE WHEN coalesce(f->>'farbe_dunkel', '') ~ '^#[0-9A-Fa-f]{6}$' THEN f->>'farbe_dunkel' ELSE '#1F2933' END;
  hell := CASE WHEN coalesce(f->>'farbe_text_auf_dunkel', '') ~ '^#[0-9A-Fa-f]{6}$' THEN f->>'farbe_text_auf_dunkel' ELSE '#FFFFFF' END;
  schrift := CASE WHEN coalesce(cd->>'schrift', '') ~ '^[A-Za-z0-9 ]{1,60}$' THEN '''' || (cd->>'schrift') || ''',' ELSE '' END;
  html := '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' || ally_html(betreff) || '</title></head>'
    || '<body style="margin:0;padding:24px 12px;background:#F4F5F7;font-family:' || schrift || 'Arial,Helvetica,sans-serif;color:#1F2933">'
    || '<div style="max-width:560px;margin:0 auto;background:#FFFFFF;border:1px solid #E1E4E8;border-radius:10px;overflow:hidden">'
    || '<div style="background:' || dunkel || ';color:' || hell || ';padding:14px 20px;font-size:18px;font-weight:700">' || ally_html(firma) || '</div>'
    || '<div style="padding:20px;font-size:15px;line-height:1.5">'
    || '<p style="margin:0 0 14px">Hallo' || coalesce(' ' || ally_html(nullif(btrim(name), '')), '') || ',</p>'
    || coalesce((SELECT string_agg('<p style="margin:0 0 14px">' || replace(ally_html(x), E'\n', '<br>') || '</p>', '' ORDER BY o) FROM unnest(vor) WITH ORDINALITY AS u(x, o)), '')
    || CASE WHEN cardinality(details) > 0 THEN '<p style="margin:0 0 14px">' || array_to_string(ARRAY(SELECT ally_html(x) FROM unnest(details) x), '<br>') || '</p>' ELSE '' END
    || CASE WHEN link IS NOT NULL THEN '<p style="margin:18px 0"><a href="' || ally_html(link) || '" style="display:inline-block;background:' || dunkel || ';color:' || hell
         || ';text-decoration:none;padding:12px 18px;border-radius:8px;font-weight:600">' || ally_html(knopf) || '</a></p>'
         || '<p style="margin:0 0 14px;font-size:13px;color:#5B6470;word-break:break-all">Falls der Knopf nicht funktioniert, diesen Link öffnen:<br>' || ally_html(link) || '</p>' ELSE '' END
    || coalesce((SELECT string_agg('<p style="margin:0 0 14px">' || replace(ally_html(x), E'\n', '<br>') || '</p>', '' ORDER BY o) FROM unnest(nach) WITH ORDINALITY AS u(x, o)), '')
    || '<p style="margin:18px 0 0">Viele Grüße<br>' || ally_html(absender) || '</p>'
    || CASE WHEN ki THEN '<p style="margin:14px 0 0">Erstellt mit KI-Unterstützung.</p>' ELSE '' END || '</div></div>'
    || '<p style="max-width:560px;margin:12px auto 0;font-size:12px;color:#5B6470">Diese Nachricht wurde automatisch versendet.</p></body></html>';
  RETURN jsonb_build_object('betreff', left(regexp_replace(betreff, '[\r\n\t]+', ' ', 'g'), 200), 'text', txt, 'html', html, 'ics', ics,
    'ics_name', CASE WHEN ics IS NOT NULL THEN 'termin.ics' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_testdaten_schutz()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Migration 168 (Bauplan B7): keine Systemnachrichten an Testdaten (Talent oder Person mit Testdaten-Kennzeichen).
  IF NEW.status IN ('wartet', 'in_arbeit') AND ((NEW.talent_id IS NOT NULL AND coalesce(talents_ist_testdaten(NEW.talent_id), false))
     OR (NEW.person IS NOT NULL AND coalesce(ally_person_ist_testdaten(NEW.person), false))) THEN
    NEW.status := 'verfallen';
    NEW.geheim := NULL;
    NEW.erledigt_am := now();
    NEW.grund := 'Testdaten lösen keine Mails aus.';
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_ui_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  adm boolean; m text := NULL; fehler text := NULL; r jsonb := NULL; weiter text := NULL;
  q text; pl integer; adr text; nm text; host text; port integer; ben text; cred text; tok text; p ally_personen%ROWTYPE; n integer; x jsonb;
BEGIN
  -- Aktionen der Oberfläche (über ally_ui_aktion, BA8): Absender-Postfach für Systemnachrichten (sy_*, nur Admin) und eigenes Kalender-Abo (ka_*).
  -- sy_absender_speichern/pruefen/entfernen: weiter = versand -> ALLY 20 ruft ALLY 39 (Zugangsdaten „Systemnachrichten – Versand (SMTP)“ setzen, prüfen, leeren);
  -- das Ergebnis trägt ally_systemnachricht_absender_abschliessen ein. Das Passwort kommt nie in die Datenbank (hier nur seine Länge).
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  adm := coalesce(ally_hat_recht(s.person, 'admin'), false);
  cred := btrim(coalesce(ally_einstellung('systemnachrichten_credential_id'), ''));
  IF p_aktion LIKE 'sy\_%' AND NOT adm THEN
    fehler := 'Das darf eine Person mit der Rolle Admin.';

  ELSIF p_aktion = 'sy_absender_speichern' THEN
    q := btrim(coalesce(d->>'quelle', ''));
    pl := CASE WHEN q ~ '^platz:[1-9][0-9]{0,8}$' THEN substr(q, 7)::integer END;  -- Migration 173 (Schritt P, P3): Postfach-Nummer ohne Grenze
    adr := CASE WHEN pl IS NOT NULL THEN (SELECT lower(btrim(y.adresse)) FROM postfach_plaetze y WHERE y.platz = pl) ELSE lower(btrim(coalesce(d->>'adresse', ''))) END;
    nm := btrim(regexp_replace(coalesce(d->>'name', ''), '\s+', ' ', 'g'));
    host := lower(btrim(coalesce(d->>'smtp_host', '')));
    port := CASE WHEN coalesce(d->>'smtp_port', '') IN ('465', '587') THEN (d->>'smtp_port')::integer END;
    ben := btrim(coalesce(d->>'smtp_benutzer', ''));
    IF cred !~ '^[A-Za-z0-9]{8,40}$' THEN
      fehler := 'Der Versand ist in dieser Installation noch nicht eingerichtet (Zugangsdaten für den Versand fehlen).';
    ELSIF q <> 'eigen' AND pl IS NULL THEN
      fehler := 'Bitte ein Postfach wählen.';
    ELSIF pl IS NOT NULL AND adr IS NULL THEN
      fehler := 'Dieses Postfach ist nicht eingerichtet.';
    -- Migration 90: Systemnachrichten nur über gemeinsame Postfächer
    ELSIF pl IS NOT NULL AND (SELECT x.art FROM ally_postfaecher x WHERE x.adresse = adr) = 'persoenlich' THEN
      fehler := 'Für Systemnachrichten geht nur ein gemeinsames Postfach.';
    ELSIF NOT ally_mail_gueltig(adr) THEN
      fehler := 'Bitte die Mailadresse des Postfachs angeben.';
    ELSIF nm = '' OR length(nm) > 80 OR nm ~ '[<>"\\,;:()]' THEN
      fehler := 'Bitte einen Absendernamen angeben (höchstens 80 Zeichen, ohne < > " , ; : ( )).';
    ELSIF EXISTS (SELECT 1 FROM ally_personen y WHERE lower(btrim(y.name)) = lower(nm)) THEN
      fehler := 'Als Absendername bitte den Namen der Organisation verwenden, nicht den Namen einer Person.';
    ELSIF length(host) > 253 OR host !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' THEN
      fehler := 'Bitte den Postausgangsserver (SMTP) angeben, z. B. smtp.beispiel.de.';
    ELSIF adresse_gesperrt(host) THEN
      fehler := 'Dieser Server ist nicht erlaubt.';
    ELSIF port IS NULL THEN
      fehler := 'Bitte Port 465 (SSL/TLS) oder 587 (STARTTLS) wählen.';
    ELSIF ben = '' OR length(ben) > 200 OR ben ~ '[\r\n\t]' THEN
      fehler := 'Bitte den Anmeldenamen angeben (meist die Mailadresse).';
    ELSIF coalesce(d->>'passwort_laenge', '0') !~ '^[0-9]{1,4}$' OR (d->>'passwort_laenge')::integer < 1 THEN
      fehler := 'Bitte das Passwort des Postfachs angeben.';
    ELSE
      INSERT INTO ally_systemnachricht_absender (id, art, platz, adresse, name, smtp_host, smtp_port, smtp_benutzer, eingerichtet, geprueft_am, pruef_ergebnis, geaendert_am, geaendert_von)
      VALUES (true, CASE WHEN pl IS NULL THEN 'eigen' ELSE 'platz' END, pl, adr, nm, host, port, ben, false, NULL, NULL, now(), s.person)
      ON CONFLICT (id) DO UPDATE SET art = EXCLUDED.art, platz = EXCLUDED.platz, adresse = EXCLUDED.adresse, name = EXCLUDED.name, smtp_host = EXCLUDED.smtp_host,
        smtp_port = EXCLUDED.smtp_port, smtp_benutzer = EXCLUDED.smtp_benutzer, eingerichtet = false, geprueft_am = NULL, pruef_ergebnis = NULL,
        geaendert_am = now(), geaendert_von = s.person;
      weiter := 'versand';
      r := jsonb_build_object('modus', 'speichern', 'credential_id', cred, 'host', host, 'port', port, 'secure', port = 465, 'benutzer', ben);
    END IF;

  ELSIF p_aktion = 'sy_absender_pruefen' THEN
    IF NOT EXISTS (SELECT 1 FROM ally_systemnachricht_absender) THEN
      fehler := 'Es ist noch kein Absender-Postfach eingestellt.';
    ELSIF cred !~ '^[A-Za-z0-9]{8,40}$' THEN
      fehler := 'Der Versand ist in dieser Installation noch nicht eingerichtet (Zugangsdaten für den Versand fehlen).';
    ELSE
      weiter := 'versand';
      r := jsonb_build_object('modus', 'pruefen', 'credential_id', cred);
    END IF;

  ELSIF p_aktion = 'sy_absender_entfernen' THEN
    DELETE FROM ally_systemnachricht_absender;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n = 0 THEN
      fehler := 'Es ist kein Absender-Postfach eingestellt.';
    ELSIF cred ~ '^[A-Za-z0-9]{8,40}$' THEN
      weiter := 'versand';
      r := jsonb_build_object('modus', 'leeren', 'credential_id', cred);
    ELSE
      m := 'Absender-Postfach entfernt. Es werden keine Systemnachrichten mehr per Mail versendet; Links stehen wieder zum Kopieren bereit.';
    END IF;

  ELSIF p_aktion = 'sy_testnachricht' THEN
    SELECT * INTO p FROM ally_personen y WHERE y.matrix_user_id = s.person;
    IF NOT ally_systemnachricht_aktiv() THEN
      fehler := 'Erst ein Absender-Postfach einstellen und die Verbindung prüfen.';
    ELSIF NOT ally_mail_gueltig(lower(btrim(coalesce(p.email, '')))) THEN
      fehler := 'Für dich ist keine gültige E-Mail-Adresse hinterlegt.';
    ELSIF (SELECT count(*) FROM ally_systemnachrichten y WHERE y.art = 'test' AND y.erstellt_am > now() - interval '1 hour') >= 3 THEN
      fehler := 'Höchstens drei Testnachrichten je Stunde. Bitte später noch einmal versuchen.';
    ELSE
      INSERT INTO ally_systemnachrichten (art, ref, person, gueltig_bis, erstellt_von)
      VALUES ('test', 'test:' || p.id || ':' || encode(gen_random_bytes(8), 'hex'), s.person, now() + interval '1 hour', s.person);
      m := 'Testnachricht an ' || lower(btrim(p.email)) || ' vorgemerkt. Sie geht in etwa einer Minute raus; der Stand steht in der Liste „Letzte Systemnachrichten“.';
    END IF;

  ELSIF p_aktion = 'sy_person_zugang' THEN
    SELECT * INTO p FROM ally_personen y WHERE y.matrix_user_id = coalesce(d->>'id', '') FOR UPDATE;
    IF NOT ally_systemnachricht_aktiv() THEN
      fehler := 'Es ist kein Absender-Postfach eingestellt. Bitte den Startcode nutzen.';
    ELSIF NOT ally_verschluesselung_bereit() OR talent_ui_adresse() IS NULL THEN
      fehler := 'Der Zugangslink kann gerade nicht erstellt werden (Verschlüsselung oder öffentliche Adresse nicht eingerichtet).';
    ELSIF p.id IS NULL OR NOT p.aktiv THEN
      fehler := 'Unbekannte Person.';
    ELSIF ally_person_ist_talent(p.matrix_user_id) THEN  -- Migration 158 (Bauplan B3a): Talent-Personen ändert man im Talent-Profil.
      fehler := 'Den Zugang eines Talents änderst du im Talent-Profil.';
    -- Migration 168 (Bauplan B7): Testdaten lösen keine Mails aus
    ELSIF coalesce(ally_person_ist_testdaten(p.matrix_user_id), false) THEN
      fehler := 'Testdaten lösen keine Mails aus. Bitte den Startcode nutzen.';
    ELSIF NOT p.zugang_aktiv THEN
      fehler := 'Der Zugang dieser Person ist gesperrt. Bitte ihn zuerst freischalten.';
    ELSIF NOT ally_mail_gueltig(lower(btrim(coalesce(p.email, '')))) THEN
      fehler := 'Bitte zuerst eine gültige E-Mail-Adresse für ' || p.name || ' eintragen.';
    ELSIF ally_person_superadmin(p.matrix_user_id) AND NOT coalesce(ally_hat_recht(s.person, 'superadmin'), false) THEN
      fehler := 'Diese Person ändert nur eine Person mit Superadmin-Recht.';
    ELSIF p.ruecksetz_bis IS NOT NULL AND p.ruecksetz_bis > now() + interval '6 days 23 hours' THEN
      fehler := 'Der Zugangslink wurde gerade erst gesendet. Bitte in einer Stunde noch einmal versuchen.';
    ELSE
      tok := encode(gen_random_bytes(32), 'hex');
      UPDATE ally_personen SET ruecksetz_hash = ally_web_hash(tok), ruecksetz_bis = now() + interval '7 days', geaendert_am = now() WHERE id = p.id;
      INSERT INTO ally_systemnachrichten (art, ref, person, geheim, gueltig_bis, erstellt_von)
      VALUES ('zugang_person', 'zugang_person:' || p.id || ':' || left(ally_web_hash(tok), 16), p.matrix_user_id, ally_verschluesseln(tok), now() + interval '1 day', s.person);
      m := 'Zugangslink für ' || p.name || ' an ' || lower(btrim(p.email)) || ' vorgemerkt (gültig 7 Tage, nur einmal). Die Mail geht in etwa einer Minute raus.';
    END IF;

  ELSIF p_aktion = 'ka_abo_neu' THEN
    x := ally_kalender_abo_neu(s.person, NULL, s.person);
    IF coalesce((x->>'ok')::boolean, false) THEN
      m := 'Abo-Adresse erstellt. Eine bisherige Adresse gilt nicht mehr; bitte in der Kalender-App die neue Adresse eintragen.';
    ELSE
      fehler := coalesce(x->>'fehler', 'Die Abo-Adresse konnte nicht erstellt werden.');
    END IF;

  ELSIF p_aktion = 'ka_abo_widerrufen' THEN
    UPDATE ally_kalender_abos SET widerrufen_am = now(), widerrufen_von = s.person WHERE person = s.person AND widerrufen_am IS NULL;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n = 0 THEN fehler := 'Es gibt kein Kalender-Abo.'; ELSE m := 'Kalender-Abo beendet. Die Adresse gilt nicht mehr.'; END IF;

  ELSE
    fehler := 'Diese Aktion gibt es hier nicht.';
  END IF;
  IF coalesce(fehler, m) IS NOT NULL THEN
    PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  END IF;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'weiter', CASE WHEN fehler IS NULL THEN weiter END, 'r', CASE WHEN fehler IS NULL THEN r END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachricht_vergessen(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
DECLARE
  v text := lower(btrim(coalesce(p_email, ''))); r jsonb; z talent_zugaenge%ROWTYPE; tok text; p ally_personen%ROWTYPE;
BEGIN
  -- „Passwort vergessen“ der neuen Anmeldeseite (BA8), für Personen und Talents. Antwort immer gleich (verrät nicht, ob es die Adresse gibt).
  -- Nur mit eingestelltem Absender-Postfach; sonst gilt der bisherige Weg (Link „Passwort vergessen?“ der bisherigen Oberfläche).
  -- Personen: wie ally_web_vergessen (Link 1 Stunde, höchstens einer je 10 Minuten). Talents: neuer Zugangslink 1 Stunde (nur mit festgelegtem Passwort).
  IF v = '' OR length(v) > 254 OR NOT ally_systemnachricht_aktiv() OR NOT ally_verschluesselung_bereit() OR talent_ui_adresse() IS NULL THEN
    PERFORM pg_sleep(0.2);
    RETURN jsonb_build_object('ok', true);
  END IF;
  IF (SELECT count(*) FROM ally_systemnachrichten x WHERE x.art = 'passwort' AND x.erstellt_am > now() - interval '1 hour') >= 20 THEN
    RETURN jsonb_build_object('ok', true);
  END IF;
  -- Migration 158 (Bauplan B3a): Talent-Personen nehmen weiter den Talent-Weg (neuer Zugangslink über talent_zugaenge).
  SELECT * INTO p FROM ally_personen x WHERE x.email = v AND NOT ally_person_ist_talent(x.matrix_user_id);
  IF p.id IS NOT NULL THEN
    r := ally_web_vergessen(v);
    IF coalesce((r->>'senden')::boolean, false) AND coalesce(r->>'code', '') ~ '^[0-9a-f]{64}$' THEN
      INSERT INTO ally_systemnachrichten (art, ref, person, geheim, gueltig_bis, erstellt_von)
      VALUES ('passwort', 'passwort:p' || p.id || ':' || left(ally_web_hash(r->>'code'), 16), p.matrix_user_id, ally_verschluesseln(r->>'code'), now() + interval '50 minutes', 'vergessen')
      ON CONFLICT (ref) DO NOTHING;
    END IF;
    RETURN jsonb_build_object('ok', true);
  END IF;
  -- Migration 159 (Bauplan B3b): E-Mail, Passwort und „Zugang aktiv“ kommen aus der Talent-Person; der neue Zugangslink bleibt am Zugang.
  SELECT x.* INTO z FROM ally_personen tp JOIN talents t ON t.id = tp.talent_id AND t.status = 'aktiv' JOIN talent_zugaenge x ON x.talent_id = tp.talent_id
  WHERE tp.email = v AND ally_rolle_ist_talent(tp.rolle) AND tp.talent_id IS NOT NULL AND tp.zugang_aktiv AND tp.pw_hash IS NOT NULL AND plattform_modul_an('talents') FOR UPDATE OF x;
  IF z.id IS NULL OR EXISTS (SELECT 1 FROM ally_systemnachrichten x WHERE x.art = 'passwort' AND x.talent_id = z.talent_id AND x.erstellt_am > now() - interval '10 minutes') THEN
    PERFORM pg_sleep(0.3);
    RETURN jsonb_build_object('ok', true);
  END IF;
  tok := encode(gen_random_bytes(32), 'hex');
  UPDATE talent_zugaenge SET einladung_hash = ally_web_hash(tok), einladung_verschluesselt = NULL, einladung_bis = now() + interval '1 hour',
    geaendert_am = now(), geaendert_von = 'vergessen' WHERE id = z.id;
  INSERT INTO ally_systemnachrichten (art, ref, talent_id, geheim, gueltig_bis, erstellt_von)
  VALUES ('passwort', 'passwort:t' || z.id || ':' || left(ally_web_hash(tok), 16), z.talent_id, ally_verschluesseln(tok), now() + interval '50 minutes', 'vergessen');
  RETURN jsonb_build_object('ok', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachrichten_holen(p_jetzt timestamp with time zone DEFAULT now(), p_max integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  st jsonb; vb jsonb; q ally_systemnachrichten%ROWTYPE; v_an text; v_tok text; v_grund text; inh jsonb; res jsonb := '[]'::jsonb; frei integer; n_h integer;
BEGIN
  -- Versand der Systemnachrichten (SYS 9, jede Minute): Vormerkungen pflegen, dann höchstens p_max (bis 20) wartende Nachrichten übernehmen („in_arbeit“).
  -- Nur mit aktivem Absender-Postfach. Empfänger nur aus der Datenbank. Drosselung: höchstens 60 je Stunde insgesamt, 5 je Stunde und 20 je Tag an dieselbe Adresse
  -- (darüber bleibt die Nachricht wartend, bis sie verfällt). Links nur, solange sie noch gelten; Aufgaben nur in der aktuellen Fassung.
  vb := ally_systemnachrichten_vorbereiten(p_jetzt);
  -- Datensparsamkeit: nach 90 Tagen Empfänger und Betreff entfernen (die Zeile bleibt als Nachweis)
  UPDATE ally_systemnachrichten SET an = NULL, betreff = NULL WHERE erledigt_am < p_jetzt - interval '90 days' AND (an IS NOT NULL OR betreff IS NOT NULL);
  st := ally_systemnachricht_absender_stand();
  IF NOT coalesce((st->>'aktiv')::boolean, false) THEN
    RETURN jsonb_build_object('aktiv', false, 'vorbereitet', vb, 'nachrichten', '[]'::jsonb);
  END IF;
  SELECT count(*) INTO n_h FROM ally_systemnachrichten x WHERE x.in_arbeit_seit > p_jetzt - interval '1 hour';
  frei := least(greatest(coalesce(p_max, 10), 0), 20, 60 - n_h);
  FOR q IN SELECT x.* FROM ally_systemnachrichten x WHERE x.status = 'wartet' AND x.gueltig_bis >= p_jetzt ORDER BY x.id LIMIT 100 FOR UPDATE SKIP LOCKED LOOP
    EXIT WHEN frei <= 0;
    v_grund := NULL; v_an := NULL; v_tok := NULL;
    IF q.art = 'email_aendern' THEN
      -- Migration 70: Bestätigungslink an die NEUE Adresse (nur solange die Änderung offen ist)
      SELECT lower(btrim(e.neue_email)) INTO v_an FROM ally_email_aenderungen e JOIN ally_personen y ON y.matrix_user_id = e.person AND y.aktiv AND y.zugang_aktiv
      WHERE e.person = q.person AND e.status = 'offen' AND e.gueltig_bis > p_jetzt ORDER BY e.id DESC LIMIT 1;
    ELSIF q.person IS NOT NULL THEN
      SELECT lower(btrim(y.email)) INTO v_an FROM ally_personen y WHERE y.matrix_user_id = q.person AND y.aktiv AND (q.art = 'test' OR y.zugang_aktiv);
    ELSIF q.art = 'einladung' THEN   -- Migration 192: Einladung an die E-Mail des Talents (nicht talent_zugaenge), nur aktiv und ohne Testdaten
      SELECT lower(btrim(t.email)) INTO v_an FROM talents t WHERE t.id = q.talent_id AND t.status = 'aktiv' AND NOT coalesce(t.testdaten, false);
    ELSIF q.art = 'aufgabe' THEN
      SELECT coalesce((SELECT z.email FROM talent_zugaenge z WHERE z.talent_id = t.id AND z.aktiv), lower(btrim(t.email))) INTO v_an
      FROM talents t WHERE t.id = q.talent_id AND t.status = 'aktiv';
    ELSE
      SELECT z.email INTO v_an FROM talent_zugaenge z JOIN talents t ON t.id = z.talent_id AND t.status = 'aktiv' WHERE z.talent_id = q.talent_id AND z.aktiv;
    END IF;
    IF NOT ally_mail_gueltig(v_an) THEN
      v_grund := 'Keine gültige E-Mail-Adresse hinterlegt.';
    ELSIF q.art IN ('zugang_talent', 'zugang_person', 'passwort', 'email_aendern') THEN
      BEGIN
        v_tok := ally_entschluesseln(q.geheim);
      EXCEPTION WHEN OTHERS THEN
        v_tok := NULL;
      END;
      IF coalesce(v_tok, '') !~ '^[0-9a-f]{64}$' THEN
        v_grund := 'Der Link ist nicht lesbar.';
      ELSIF q.art = 'email_aendern' AND NOT EXISTS (SELECT 1 FROM ally_email_aenderungen e WHERE e.person = q.person AND e.code_hash = ally_web_hash(v_tok)
          AND e.status = 'offen' AND e.gueltig_bis > p_jetzt) THEN
        v_grund := 'Der Link gilt nicht mehr (inzwischen ersetzt, verworfen oder benutzt).';
      ELSIF q.art <> 'email_aendern' AND q.person IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_personen y WHERE y.matrix_user_id = q.person AND y.ruecksetz_hash = ally_web_hash(v_tok) AND y.ruecksetz_bis > p_jetzt) THEN
        v_grund := 'Der Link gilt nicht mehr (inzwischen ersetzt oder benutzt).';
      ELSIF q.talent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talent_zugaenge z WHERE z.talent_id = q.talent_id AND z.einladung_hash = ally_web_hash(v_tok) AND z.einladung_bis > p_jetzt) THEN
        v_grund := 'Der Link gilt nicht mehr (inzwischen ersetzt oder benutzt).';
      END IF;
    ELSIF q.art = 'einladung' AND talent_einladung_versandfehler(q.einladung_id, q.talent_id, q.erstellt_von) IS NOT NULL THEN   -- Migration 192
      v_grund := talent_einladung_versandfehler(q.einladung_id, q.talent_id, q.erstellt_von);
    ELSIF q.art = 'aufgabe' AND NOT EXISTS (SELECT 1 FROM talent_aufgaben t WHERE t.id = q.aufgabe_id AND t.ics_sequenz = q.aufgabe_sequenz AND t.mail_status = 'offen' AND 'mail' = ANY (t.kanaele)) THEN
      v_grund := 'Inzwischen geändert; es gilt die neuere Fassung.';
    END IF;
    IF v_grund IS NULL THEN
      -- Drosselung je Adresse
      IF (SELECT count(*) FROM ally_systemnachrichten x WHERE x.an = v_an AND x.in_arbeit_seit > p_jetzt - interval '1 hour') >= 5
         OR (SELECT count(*) FROM ally_systemnachrichten x WHERE x.an = v_an AND x.in_arbeit_seit > p_jetzt - interval '1 day') >= 20 THEN
        CONTINUE;
      END IF;
      inh := ally_systemnachricht_inhalt(q.id, v_tok, st);
      IF inh IS NULL THEN v_grund := CASE WHEN q.art = 'einladung' THEN coalesce(talent_einladung_mail(q.einladung_id, 'system', q.erstellt_von, NULL, true)->>'fehler', 'Der Inhalt ist nicht verfügbar.')
                                          ELSE 'Der Inhalt ist nicht verfügbar.' END; END IF;   -- Migration 192
    END IF;
    IF v_grund IS NOT NULL THEN
      UPDATE ally_systemnachrichten SET status = 'verfallen', grund = v_grund, geheim = NULL, erledigt_am = p_jetzt WHERE id = q.id;
      IF q.art = 'einladung' THEN PERFORM talent_einladung_fehler_melden('system', q.id); END IF;   -- Migration 192
      IF q.art = 'aufgabe' THEN
        UPDATE talent_aufgaben SET mail_status = 'fehler' WHERE id = q.aufgabe_id AND ics_sequenz = q.aufgabe_sequenz AND mail_status = 'offen';
      END IF;
      CONTINUE;
    END IF;
    UPDATE ally_systemnachrichten SET status = 'in_arbeit', in_arbeit_seit = p_jetzt, versuche = versuche + 1, an = v_an, betreff = inh->>'betreff',
      absender = CASE WHEN q.art = 'einladung' THEN lower(btrim(st->>'adresse')) ELSE absender END WHERE id = q.id;   -- Migration 192: Absender im Protokoll
    res := res || jsonb_build_array(jsonb_build_object('id', q.id, 'an', v_an) || inh);
    frei := frei - 1;
  END LOOP;
  RETURN jsonb_build_object('aktiv', true, 'credential_id', st->>'credential_id', 'von_adresse', st->>'adresse', 'von_name', st->>'name', 'vorbereitet', vb, 'nachrichten', res);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_systemnachrichten_vorbereiten(p_jetzt timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  aktiv boolean := ally_systemnachricht_aktiv(); a record; n_neu integer := 0; n_alt integer := 0; n_ab integer := 0; gb timestamptz; v_grund text;
  v_ein bigint[];   -- Migration 192
BEGIN
  -- Vormerkungen pflegen (BA8, Aufruf aus ally_systemnachrichten_holen, SYS 9 jede Minute):
  -- 1. Wartende, deren Gültigkeit abgelaufen ist -> „nicht gesendet“ (Aufgabe: Mail nicht gesendet). 2. Nicht bestätigte Versuche nach 15 Minuten -> „unklar“,
  -- nie ein zweiter Versand. 3. Aufgaben/Termine/Erinnerungen mit Kanal Mail und Vormerkung „offen“ (Migration 61) -> eine Nachricht je Fassung (ics_sequenz);
  -- Erinnerungen erst, wenn sie fällig sind. Vormerkungen älter als ein Tag, vorbei oder ohne Absender-Postfach werden nicht mehr gesendet.
  -- Migration 192: Einladungen, die gleich verfallen oder unklar werden, für die Benachrichtigung der einladenden Person merken
  SELECT array_agg(x.id) INTO v_ein FROM (SELECT y.id FROM ally_systemnachrichten y WHERE y.art = 'einladung'
    AND ((y.status = 'wartet' AND y.gueltig_bis < p_jetzt) OR (y.status = 'in_arbeit' AND y.in_arbeit_seit < p_jetzt - interval '15 minutes')) FOR UPDATE) x;
  WITH v AS (UPDATE ally_systemnachrichten SET status = 'verfallen', geheim = NULL, erledigt_am = p_jetzt,
               grund = CASE WHEN aktiv THEN 'Nicht rechtzeitig versendet (Drosselung oder Fehler beim Versand).' ELSE 'Kein Absender-Postfach eingestellt.' END
             WHERE status = 'wartet' AND gueltig_bis < p_jetzt RETURNING aufgabe_id, aufgabe_sequenz)
  UPDATE talent_aufgaben t SET mail_status = 'fehler' FROM v WHERE t.id = v.aufgabe_id AND t.ics_sequenz = v.aufgabe_sequenz AND t.mail_status = 'offen';
  WITH v AS (UPDATE ally_systemnachrichten SET status = 'unklar', geheim = NULL, erledigt_am = p_jetzt,
               grund = 'Der Versand wurde nicht bestätigt. Die Mail wird nicht noch einmal gesendet.'
             WHERE status = 'in_arbeit' AND in_arbeit_seit < p_jetzt - interval '15 minutes' RETURNING aufgabe_id, aufgabe_sequenz)
  UPDATE talent_aufgaben t SET mail_status = 'fehler' FROM v WHERE t.id = v.aufgabe_id AND t.ics_sequenz = v.aufgabe_sequenz AND t.mail_status = 'offen';
  PERFORM talent_einladung_fehler_melden('system', x) FROM unnest(coalesce(v_ein, '{}'::bigint[])) x;   -- Migration 192
  FOR a IN SELECT t.id, t.talent_id, t.art, t.status, t.ics_sequenz, t.faellig_am, t.beginn, t.ende, t.geaendert_am, tt.status AS t_status
           FROM talent_aufgaben t JOIN talents tt ON tt.id = t.talent_id
           WHERE t.mail_status = 'offen' AND 'mail' = ANY (t.kanaele)
             AND NOT EXISTS (SELECT 1 FROM ally_systemnachrichten q WHERE q.ref = 'aufgabe:' || t.id || ':' || t.ics_sequenz)
           ORDER BY t.id LIMIT 200 LOOP
    IF a.art = 'erinnerung' AND a.status = 'offen' AND a.t_status = 'aktiv' AND a.faellig_am > p_jetzt THEN
      n_ab := n_ab + 1;
      CONTINUE;
    END IF;
    gb := CASE WHEN a.art = 'erinnerung' AND a.status = 'offen' THEN greatest(a.faellig_am, a.geaendert_am) ELSE a.geaendert_am END + interval '1 day';
    v_grund := CASE WHEN a.t_status <> 'aktiv' THEN 'Das Talent liegt im Papierkorb.'
                    WHEN a.art = 'termin' AND a.status <> 'abgesagt' AND coalesce(a.ende, a.beginn) < p_jetzt THEN 'Der Termin ist vorbei.'
                    WHEN a.art = 'erinnerung' AND a.status = 'erledigt' THEN 'Die Erinnerung ist schon erledigt.'
                    WHEN gb < p_jetzt THEN CASE WHEN aktiv THEN 'Die Vormerkung ist älter als ein Tag.' ELSE 'Kein Absender-Postfach eingestellt.' END END;
    IF v_grund IS NOT NULL THEN
      INSERT INTO ally_systemnachrichten (art, ref, talent_id, aufgabe_id, aufgabe_sequenz, status, grund, gueltig_bis, erledigt_am, erstellt_von)
      VALUES ('aufgabe', 'aufgabe:' || a.id || ':' || a.ics_sequenz, a.talent_id, a.id, a.ics_sequenz, 'verfallen', v_grund, p_jetzt, p_jetzt, 'vormerkung')
      ON CONFLICT (ref) DO NOTHING;
      UPDATE talent_aufgaben SET mail_status = 'fehler' WHERE id = a.id AND ics_sequenz = a.ics_sequenz AND mail_status = 'offen';
      n_alt := n_alt + 1;
    ELSIF aktiv THEN
      INSERT INTO ally_systemnachrichten (art, ref, talent_id, aufgabe_id, aufgabe_sequenz, gueltig_bis, erstellt_von)
      VALUES ('aufgabe', 'aufgabe:' || a.id || ':' || a.ics_sequenz, a.talent_id, a.id, a.ics_sequenz, gb, 'vormerkung')
      ON CONFLICT (ref) DO NOTHING;
      n_neu := n_neu + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('neu', n_neu, 'nicht_gesendet', n_alt, 'noch_nicht_faellig', n_ab);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_bild(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 79: neutrales Platzhalter-Bild (SVG als data-Adresse) für Beiträge der Testdaten; keine fremde Bildquelle, keine Personen.
  WITH f AS (SELECT (ARRAY['#C9D6C3','#E8D9C5','#C7D3E3','#E3C9CF','#D9D2E9','#CFE3DF','#EADFC0','#D6D6D6'])[1 + floor(ally_testdaten_zufall(p || 'a') * 8)::integer] AS hg,
                    (ARRAY['#5E7A55','#9A6B3F','#4B6584','#9C4F5E','#6D5A99','#3F7F74','#8C7A2E','#555555'])[1 + floor(ally_testdaten_zufall(p || 'b') * 8)::integer] AS vg,
                    40 + floor(ally_testdaten_zufall(p || 'c') * 320)::integer AS x, 40 + floor(ally_testdaten_zufall(p || 'd') * 260)::integer AS y,
                    30 + floor(ally_testdaten_zufall(p || 'e') * 90)::integer AS r, floor(ally_testdaten_zufall(p || 'f') * 3)::integer AS form)
  SELECT 'data:image/svg+xml;base64,' || replace(encode(convert_to(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" width="400" height="400"><rect width="400" height="400" fill="' || f.hg || '"/>'
    || CASE f.form WHEN 0 THEN '<circle cx="' || f.x || '" cy="' || f.y || '" r="' || f.r || '" fill="' || f.vg || '" fill-opacity="0.75"/>'
                   WHEN 1 THEN '<rect x="' || greatest(f.x - f.r, 10) || '" y="' || greatest(f.y - f.r, 10) || '" width="' || (2 * f.r) || '" height="' || (2 * f.r) || '" rx="18" fill="' || f.vg || '" fill-opacity="0.75"/>'
                   ELSE '<path d="M' || greatest(f.x - f.r, 10) || ' ' || (f.y + f.r) || ' L' || f.x || ' ' || greatest(f.y - f.r, 10) || ' L' || least(f.x + f.r, 390) || ' ' || (f.y + f.r) || ' Z" fill="' || f.vg || '" fill-opacity="0.75"/>' END
    || '<rect x="0" y="352" width="400" height="48" fill="#FFFFFF" fill-opacity="0.7"/><text x="200" y="384" font-family="Arial, sans-serif" font-size="22" text-anchor="middle" fill="#333333">Testbild</text></svg>',
    'UTF8'), 'base64'), E'\n', '')
  FROM f
$function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_entfernen(p_von text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  tp text[]; tt integer[]; n jsonb := '{}'::jsonb; c integer; behalten text[];
BEGIN
  -- Migration 79: alle markierten Testdaten vollständig entfernen. Reihenfolge: Berichte, Kampagnen, Talents (mit allem, was per Fremdschlüssel daran hängt),
  -- Personen (ebenso), Einträge ohne Fremdschlüssel (Sitzungen, Rechte, Einstellungen, Chat-Kennungen), Rollen. Echte Daten bleiben unberührt.
  PERFORM pg_advisory_xact_lock(hashtext('ally_testdaten'));
  tp := ARRAY(SELECT p.matrix_user_id FROM ally_personen p WHERE p.testdaten);
  tt := ARRAY(SELECT t.id FROM talents t WHERE t.testdaten);
  DELETE FROM talent_berichte b WHERE b.testdaten OR (cardinality(b.talent_ids) > 0 AND b.talent_ids <@ tt);
  GET DIAGNOSTICS c = ROW_COUNT; n := n || jsonb_build_object('berichte', c);
  DELETE FROM talent_kampagnen k WHERE k.testdaten;
  GET DIAGNOSTICS c = ROW_COUNT; n := n || jsonb_build_object('kampagnen', c);
  DELETE FROM talent_kampagnen_papierkorb pk WHERE pk.testdaten;  -- Migration 131 (Zählung unverändert)
  DELETE FROM talents t WHERE t.testdaten;
  GET DIAGNOSTICS c = ROW_COUNT; n := n || jsonb_build_object('talents', c);
  DELETE FROM talent_profil_papierkorb x WHERE x.testdaten;  -- Migration 130 (Zählung unverändert)
  -- Migration 81: Tabellen ohne Fremdschlüssel – nur Zeilen der Test-Personen bzw. Test-Talents (echte Zeilen nie)
  DELETE FROM ki_verbrauch x WHERE x.matrix_user_id = ANY (tp);
  GET DIAGNOSTICS c = ROW_COUNT; n := n || jsonb_build_object('ki_verbrauch', c);
  DELETE FROM marketing_posts x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM marketing_themen x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM marketing_papierkorb x WHERE x.matrix_user_id = ANY (tp);  -- Migration 133
  DELETE FROM marketing_pk_loeschauftraege x WHERE x.matrix_user_id = ANY (tp);  -- Migration 133
  DELETE FROM matrix_direct_rooms x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM ally_chat_auftraege x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM ally_gesendete_nachrichten x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM talent_importe x WHERE x.erstellt_von = ANY (tp);
  DELETE FROM talent_ki_anfragen x WHERE x.erstellt_von = ANY (tp) OR (cardinality(x.talent_ids) > 0 AND x.talent_ids <@ tt);
  DELETE FROM talent_widerrufe x WHERE x.talent_id = ANY (tt);
  DELETE FROM talent_loesch_dateien x WHERE x.talent_id = ANY (tt);
  DELETE FROM ally_web_sitzungen x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM ally_nutzer_rechte x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM ally_nutzer_funktionen x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM ally_nutzer_einstellungen x WHERE x.matrix_user_id = ANY (tp);
  -- Migration 90: ally_nutzer_postfaecher ist eine berechnete Sicht (Test-Personen sehen nie ein Postfach)
  DELETE FROM ally_chat_kennungen x WHERE x.matrix_user_id = ANY (tp);
  DELETE FROM ally_personen p WHERE p.testdaten;
  GET DIAGNOSTICS c = ROW_COUNT; n := n || jsonb_build_object('personen', c);
  -- Test-Rollen: nur entfernen, wenn keine echte Person sie inzwischen hat; sonst bleibt die Rolle als normale Rolle erhalten
  behalten := ARRAY(SELECT r.schluessel FROM ally_rollen r WHERE r.testdaten AND EXISTS (SELECT 1 FROM ally_personen p WHERE p.rolle = r.schluessel));
  UPDATE ally_rollen SET testdaten = false WHERE schluessel = ANY (behalten);
  DELETE FROM ally_rollen r WHERE r.testdaten;
  GET DIAGNOSTICS c = ROW_COUNT; n := n || jsonb_build_object('rollen', c, 'rollen_behalten', cardinality(behalten));
  DELETE FROM ally_ui_zustand z WHERE z.schluessel = 'testdaten.ausblenden';
  UPDATE ally_testdaten_stand SET aktiv = false, entfernt_am = now(), entfernt_von = p_von, anzahl = '{}'::jsonb WHERE id = 1;
  RETURN jsonb_build_object('ok', true, 'entfernt', n);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_erzeugen(p_groesse integer, p_von text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n integer := p_groesse;
  heute date := talents_heute();
  vornamen text[] := ARRAY['Alex','Robin','Kim','Sam','Charlie','Jona','Luca','Mika','Toni','Juli','Nico','Pat','Chris','Jules','Andrea','Sascha','Kai','Lou','Elia','Maxi',
                     'Noa','Ronja','Lia','Ben','Emma','Finn','Mila','Paul','Lina','Theo'];
  nachnamen text[] := ARRAY['Beispiel','Muster','Probe','Vorlage','Sonnenfeld','Bergmann','Waldner','Fischer','Lindner','Kramer','Seidel','Brand','Vogt','Roth','Albrecht',
                     'Kuhn','Hartmann','Busch','Engel','Winter'];
  themen text[] := ARRAY['Fitness','Reisen','Kochen','Mode','Technik','Familie','Nachhaltigkeit','Musik','Gaming','Beauty','Sport','Outdoor','Kunst','Finanzen','Wohnen'];
  plattf text[] := ARRAY['instagram','tiktok','youtube','facebook','threads','pinterest'];
  STAEDTE text[] := ARRAY['Berlin','Hamburg','München','Köln','Frankfurt am Main','Stuttgart','Düsseldorf','Leipzig','Dortmund','Essen','Bremen','Dresden',
                          'Hannover','Nürnberg','Wien','Zürich'];
  PERS text[] := ARRAY['@testdaten-person-1:testdaten.invalid','@testdaten-person-2:testdaten.invalid','@testdaten-person-3:testdaten.invalid',
                       '@testdaten-person-4:testdaten.invalid','@testdaten-person-5:testdaten.invalid'];
  i integer; j integer; d integer; tid integer; kid integer; bid bigint; kampid integer;
  vn text; nn text; handle text; anz integer; pl text; st text; f numeric; r double precision; reach numeric; v numeric; fol numeric;
  verb timestamptz; gb timestamptz; aktiv_t boolean; einbruch boolean; luecke boolean; tage integer; art text; part text; erst timestamptz;
  marke text; kv date; kb date; abbr timestamptz; tids integer[]; c_t integer := 0; c_k integer := 0; c_tage integer := 0; c_b integer := 0; c_kamp integer := 0;
  tok text; st_rec record;
BEGIN
  -- Migration 79: frische Testdaten nach festem Muster (deterministisch, Zahlen relativ zu heute). Vorhandene Testdaten werden vorher entfernt.
  -- Keine Zugangsschlüssel (Kanäle haben keinen Schlüssel und werden daher nie abgerufen), Adressen unter .invalid (dort kommt nie eine Mail an),
  -- Chat-Benutzer unter testdaten.invalid (gehören zu keinem Chat-Server), Bilder als Platzhalter-SVG.
  IF n IS NULL OR n NOT IN (10, 50, 100) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Bitte 10, 50 oder 100 Talents wählen.');
  END IF;
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Testdaten gibt es für das Paket Talents. Es ist nicht gebucht.');
  END IF;
  PERFORM set_config('statement_timeout', '180s', true);
  PERFORM ally_testdaten_entfernen(p_von);
  IF EXISTS (SELECT 1 FROM ally_rollen x WHERE lower(x.name) IN ('test: leitung', 'test: management', 'test: ansehen') OR x.schluessel IN ('testdaten_leitung', 'testdaten_management', 'testdaten_ansehen')) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Eine Rolle mit dem Namen „Test: Leitung“, „Test: Management“ oder „Test: Ansehen“ gibt es schon. Bitte umbenennen, dann noch einmal einschalten.');
  END IF;

  -- Rollen nach dem freien Rollenmodell
  INSERT INTO ally_rollen (schluessel, name, beschreibung, sortierung, rechte, fuer_personen, art, erstellt_von, geaendert_von, testdaten) VALUES
    ('testdaten_leitung', 'Test: Leitung', 'Testdaten: sieht und verwaltet alle Talents und Kampagnen, mit Honoraren und Budgets.', 900, '{}', true, 'eigen', p_von, p_von, true),
    ('testdaten_management', 'Test: Management', 'Testdaten: verwaltet die zugeordneten Talents und Kampagnen.', 901, '{}', true, 'eigen', p_von, p_von, true),
    ('testdaten_ansehen', 'Test: Ansehen', 'Testdaten: sieht alle Talents, ändert nichts.', 902, '{}', true, 'eigen', p_von, p_von, true);
  INSERT INTO ally_rollen_rechte (rolle, recht, reichweite, geaendert_von) VALUES
    ('testdaten_leitung', 'talents_ansehen', 'alle', p_von), ('testdaten_leitung', 'talents_verwalten', 'alle', p_von),
    ('testdaten_leitung', 'talents_betraege', 'alle', p_von), ('testdaten_leitung', 'talents_bereich', 'alle', p_von),
    ('testdaten_management', 'talents_ansehen', 'zugeordnet', p_von), ('testdaten_management', 'talents_verwalten', 'zugeordnet', p_von),
    ('testdaten_management', 'talents_betraege', 'zugeordnet', p_von), ('testdaten_management', 'talents_bereich', 'zugeordnet', p_von),
    ('testdaten_ansehen', 'talents_ansehen', 'alle', p_von);

  -- Migration 168 (Bauplan B7): 5 Personen, ohne Manager-Login (die Adresse manager@testdaten.invalid bleibt die von Person 1)
  INSERT INTO ally_personen (matrix_user_id, name, email, aktiv, zugang_aktiv, rolle, testdaten) VALUES
    (PERS[1], 'Alex Beispiel', 'manager@testdaten.invalid', true, true, 'testdaten_management', true),
    (PERS[2], 'Robin Muster', 'person2@testdaten.invalid', true, true, 'testdaten_management', true),
    (PERS[3], 'Kim Vorlage', 'person3@testdaten.invalid', true, true, 'testdaten_leitung', true),
    (PERS[4], 'Sam Probe', 'person4@testdaten.invalid', true, true, 'testdaten_ansehen', true),
    (PERS[5], 'Jona Sonnenfeld', 'person5@testdaten.invalid', true, true, 'testdaten_management', true);

  -- Talents
  FOR i IN 1..n LOOP
    vn := vornamen[1 + ((i * 7) % array_length(vornamen, 1))];
    nn := nachnamen[1 + ((i * 11) % array_length(nachnamen, 1))];
    handle := lower(translate(vn || '.' || nn, 'ÄÖÜäöüß', 'AOUaous')) || CASE WHEN i > 30 THEN (i::text) ELSE '' END;
    aktiv_t := i % 23 <> 0;
    INSERT INTO talents (name, kuenstlername, email, notiz, status, erstellt_am, erstellt_von, geaendert_am, geaendert_von, archiviert_am, testdaten)
    VALUES (vn || ' ' || nn, handle, 'talent' || i || '@testdaten.invalid',
      'Testdaten. Themen: ' || themen[1 + ((i * 3) % array_length(themen, 1))] || ', ' || themen[1 + ((i * 5 + 2) % array_length(themen, 1))] || '.',
      CASE WHEN aktiv_t THEN 'aktiv' ELSE 'archiviert' END, now() - make_interval(days => 60 + (i * 13) % 300), p_von, now(), p_von,
      CASE WHEN aktiv_t THEN NULL ELSE now() - interval '10 days' END, true)
    RETURNING id INTO tid;
    tids := tids || tid;
    c_t := c_t + 1;
    -- Zuständig: abwechselnd Person 1, 2, 5; jedes siebte Talent zusätzlich Person 3
    INSERT INTO talent_personen (talent_id, matrix_user_id) VALUES (tid, PERS[(ARRAY[1, 2, 5])[1 + (i % 3)]]);
    IF i % 7 = 0 THEN INSERT INTO talent_personen (talent_id, matrix_user_id) VALUES (tid, PERS[3]) ON CONFLICT DO NOTHING; END IF;
    IF i = 1 THEN
      -- Migration 168 (Bauplan B7): kein Talent-Login mehr (ein Zugang nur auf dem normalen Weg im Talent-Profil). Talent-Bereich des ersten
      -- Talents mit Briefing; Dateien und Upload aus (kein Speicherort bei Testdaten)
      INSERT INTO talent_bereich (talent_id, briefing, briefing_am, briefing_von, zeige_dateien, zeige_upload, geaendert_von)
      VALUES (tid, 'Willkommen im Talent-Bereich der Testdaten. Hier stehen Briefing, Aufgaben, Termine und Zahlen.', now(), p_von, false, false, p_von);
    END IF;

    -- Kanäle: 0 bis 6 je Talent
    anz := CASE WHEN i % 17 = 0 THEN 0 ELSE 1 + floor(ally_testdaten_zufall('kanaele' || i) * 6)::integer END;
    FOR j IN 1..anz LOOP
      pl := plattf[1 + ((i + j - 2) % 6)];
      r := ally_testdaten_zufall('status' || i || pl);
      st := CASE WHEN NOT aktiv_t THEN 'getrennt' WHEN r < 0.06 THEN 'abgelaufen' WHEN r < 0.10 THEN 'getrennt' WHEN r < 0.14 THEN 'offen' ELSE 'verbunden' END;
      verb := now() - make_interval(days => 70 + floor(ally_testdaten_zufall('verb' || i || pl) * 300)::integer);
      gb := CASE WHEN st = 'abgelaufen' THEN now() - make_interval(days => 3 + (i % 20))
                 WHEN st = 'verbunden' AND r > 0.94 THEN now() + make_interval(days => 2 + (i % 10))
                 WHEN st = 'verbunden' THEN now() + make_interval(days => 25 + (i % 35)) END;
      INSERT INTO talent_kanaele (talent_id, plattform, status, anmeldeweg, extern_id, extern_name, verbunden_am, gueltig_bis, geprueft_am, letzter_abruf, letzter_fehler)
      VALUES (tid, pl, st, CASE WHEN pl = 'instagram' THEN CASE WHEN i % 2 = 0 THEN 'facebook' ELSE 'instagram' END ELSE pl END,
        CASE WHEN st = 'offen' THEN NULL ELSE 'testdaten-' || i || '-' || pl END, CASE WHEN st = 'offen' THEN NULL ELSE '@' || handle END,
        CASE WHEN st = 'offen' THEN NULL ELSE verb END, gb, CASE WHEN st = 'offen' THEN NULL ELSE now() - interval '1 day' END,
        CASE WHEN st IN ('verbunden') THEN CASE WHEN ally_testdaten_zufall('alt' || i || pl) < 0.05 THEN now() - interval '4 days' ELSE now() - interval '2 hours' END
             WHEN st IN ('abgelaufen', 'getrennt') THEN coalesce(gb, now() - interval '20 days') END,
        CASE WHEN st = 'verbunden' AND ally_testdaten_zufall('fehler' || i || pl) < 0.05 THEN 'Testdaten: Beispiel für einen Fehler beim Abruf.' END)
      RETURNING id INTO kid;
      c_k := c_k + 1;
      CONTINUE WHEN st = 'offen';
      -- Tageszahlen der letzten 56 Tage (bei abgelaufenen/getrennten nur bis zum Ende)
      fol := round(exp(ln(800) + ally_testdaten_zufall('fol' || i || pl) * (ln(250000) - ln(800))));
      f := 0.02 + ally_testdaten_zufall('quote' || i || pl) * 0.12;
      einbruch := i % 13 = 0;
      luecke := i % 11 = 0;
      tage := CASE WHEN st IN ('abgelaufen', 'getrennt') THEN greatest(0, 56 - greatest(0, (heute - talents_tag(coalesce(gb, now() - interval '20 days')))::integer)) ELSE 56 END;
      FOR d IN REVERSE 56..1 LOOP
        CONTINUE WHEN 56 - d >= tage;
        CONTINUE WHEN luecke AND d IN (9, 10, 23);
        reach := round(fol * f * (0.6 + ally_testdaten_zufall('r' || kid || 'd' || d) * 0.8) * CASE WHEN extract(isodow FROM heute - d) IN (6, 7) THEN 1.25 ELSE 1 END
                 * CASE WHEN einbruch AND d <= 7 THEN 0.3 ELSE 1 END);
        v := round(reach * (1.3 + ally_testdaten_zufall('v' || kid || 'd' || d) * 0.8));
        INSERT INTO talent_kanal_tage (kanal_id, tag, werte, abgerufen_am)
        VALUES (kid, heute - d, jsonb_build_object('reach', reach, 'views', v, 'likes', round(reach * 0.045), 'comments', round(reach * 0.006),
          'total_interactions', round(reach * 0.055), 'followers_count', round(fol * (1 - d * 0.0015))), (heute - d + 1)::timestamptz + interval '3 hours');
        c_tage := c_tage + 1;
      END LOOP;
      -- Beiträge: 6 bis 18 in den letzten 56 Tagen
      FOR j IN 1..(6 + floor(ally_testdaten_zufall('beitraege' || kid) * 13)::integer) LOOP
        d := 1 + floor(ally_testdaten_zufall('tag' || kid || '-' || j) * 55)::integer;
        CONTINUE WHEN 56 - d >= tage;
        r := ally_testdaten_zufall('art' || kid || '-' || j);
        art := CASE WHEN pl IN ('tiktok', 'youtube') THEN 'VIDEO' WHEN pl IN ('threads', 'pinterest') THEN 'IMAGE'
                    WHEN r < 0.35 THEN 'IMAGE' WHEN r < 0.70 THEN 'VIDEO' WHEN r < 0.85 THEN 'CAROUSEL_ALBUM' ELSE 'IMAGE' END;
        part := CASE WHEN pl = 'instagram' AND r >= 0.85 THEN 'STORY' WHEN pl = 'instagram' AND art = 'VIDEO' THEN 'REELS' WHEN pl = 'instagram' THEN 'FEED' END;
        erst := (heute - d)::timestamptz + make_interval(hours => 8 + floor(ally_testdaten_zufall('h' || kid || '-' || j) * 12)::integer);
        reach := round(fol * f * (1.5 + ally_testdaten_zufall('br' || kid || '-' || j) * 3));
        INSERT INTO talent_beitraege (kanal_id, extern_id, art, produkt_art, erstellt, link, vorschau_url, text_inhalt, werte, aktualisiert_am, abgeschlossen, erfasst_am)
        VALUES (kid, 'testdaten-' || kid || '-' || j, art, part, erst, NULL, ally_testdaten_bild(kid || '-' || j),
          'Testbeitrag ' || j || ' zum Thema ' || themen[1 + ((i + j) % array_length(themen, 1))] || '. #testdaten'
            || CASE WHEN (i + j) % 4 = 0 THEN ' #beispielmarke' || chr(97 + (i % 6)) ELSE '' END,
          jsonb_build_object('reach', reach, 'views', round(reach * 1.7), 'likes', round(reach * 0.06), 'comments', round(reach * 0.008),
            'saved', round(reach * 0.01), 'shares', round(reach * 0.005), 'total_interactions', round(reach * 0.083)),
          now() - interval '2 hours', d > 14, erst)
        RETURNING id INTO bid;
        c_b := c_b + 1;
        IF d <= 14 THEN
          INSERT INTO talent_beitrag_tage (beitrag_id, tag, werte, abgerufen_am)
          SELECT bid, heute - x, jsonb_build_object('reach', round(reach * (1 - x::numeric / (d + 1))), 'views', round(reach * 1.7 * (1 - x::numeric / (d + 1)))),
                 (heute - x)::timestamptz + interval '3 hours'
          FROM generate_series(0, least(d - 1, 6)) x ON CONFLICT DO NOTHING;
        END IF;
      END LOOP;
      -- Zielgruppe (Stand heute)
      IF pl IN ('instagram', 'tiktok', 'youtube') AND st = 'verbunden' THEN
        r := ally_testdaten_zufall('zg' || kid);
        INSERT INTO talent_zielgruppen (kanal_id, stand, art, werte) VALUES
          (kid, heute, 'follower_demographics:gender', jsonb_build_object('F', round(40 + r * 30), 'M', round(60 - r * 30 - 3), 'U', 3)),
          (kid, heute, 'follower_demographics:age', jsonb_build_object('13-17', round(4 + r * 6), '18-24', round(20 + r * 15), '25-34', round(30 - r * 5), '35-44', 18, '45-54', 9, '55-64', 4, '65+', 2)),
          (kid, heute, 'follower_demographics:country', jsonb_build_object('DE', round(70 + r * 15), 'AT', 8, 'CH', 6, 'NL', 2, 'IT', 1)),
          (kid, heute, 'follower_demographics:city', (SELECT jsonb_object_agg(s.x, round(fol * 0.08 / s.n)) FROM unnest(STAEDTE) WITH ORDINALITY s(x, n)))
        ON CONFLICT DO NOTHING;
      END IF;
    END LOOP;

    -- Manuelle Daten (jedes neunte Talent), teils überschneidend mit den automatisch geladenen Zahlen (dann Hinweis „doppelte Daten“)
    IF i % 9 = 0 AND aktiv_t THEN
      INSERT INTO talent_manuell_werte (talent_id, plattform, konto, bereich, kennzahl, wert, von, bis, quelle, quelle_text, bestaetigt_von)
      VALUES (tid, 'instagram', '@' || handle, 'konto', 'reach', 1000 + i * 37, heute - 7, heute - 1, 'hand', 'Testdaten: von Hand eingetragen', PERS[1]);
    END IF;

    -- Migration 145: offene, unbestätigte manuelle Daten („bitte prüfen“) für wenige Talents (jedes zwölfte ab dem fünften), ohne Datei, ohne KI
    IF i % 12 = 5 AND aktiv_t THEN
      PERFORM ally_testdaten_vorschlag(tid, i, '@' || handle, PERS[1]);
    END IF;

    -- Einladung (jedes achte Talent), nur wenn die Verschlüsselung eingerichtet ist
    IF i % 8 = 0 AND aktiv_t AND ally_verschluesselung_bereit() THEN
      tok := encode(gen_random_bytes(32), 'hex');
      INSERT INTO talent_einladungen (talent_id, token_hash, token_verschluesselt, gueltig_bis, erstellt_von)
      VALUES (tid, ally_web_hash(tok), ally_verschluesseln(tok), now() + interval '6 days', PERS[1]);
    END IF;

    -- Talent-Reports (jedes zehnte Talent): fertig ohne Datei, einer mit Fehler
    IF i % 10 = 0 THEN
      INSERT INTO talent_berichte (art, titel, talent_ids, von, bis, status, quelle, erstellt_von, erstellt_am, fertig_am, fehler, testdaten)
      VALUES ('monat', 'Monatsbericht ' || to_char(date_trunc('month', heute) - interval '1 month', 'MM/YYYY') || ' – ' || vn || ' ' || nn, ARRAY[tid],
        (date_trunc('month', heute) - interval '1 month')::date, (date_trunc('month', heute) - interval '1 day')::date,
        CASE WHEN i % 30 = 0 THEN 'fehler' ELSE 'fertig' END, 'oberflaeche', PERS[1], now() - interval '3 days',
        CASE WHEN i % 30 = 0 THEN NULL ELSE now() - interval '3 days' END, CASE WHEN i % 30 = 0 THEN 'Testdaten: Beispiel für einen Fehler.' END, true);
    END IF;
  END LOOP;

  -- Kampagnen: n/5 (mindestens 3) in verschiedenen Zuständen
  FOR j IN 1..greatest(3, n / 5) LOOP
    marke := 'Beispielmarke ' || chr(64 + 1 + ((j - 1) % 26));
    kv := CASE j % 4 WHEN 0 THEN heute - 50 WHEN 1 THEN heute - 10 WHEN 2 THEN heute + 12 ELSE heute - 25 END;
    kb := kv + (20 + (j * 3) % 25);
    abbr := CASE WHEN j % 7 = 0 THEN now() - interval '2 days' END;
    INSERT INTO talent_kampagnen (marke, name, von, bis, hashtags, schlagwoerter, erstellt_von, geaendert_von, zustaendig, budget_cent, ziel_reichweite,
      ziel_interaktionsrate, briefing_ziel, kernbotschaft, werbekennzeichnung, erinnerungen_an, abgebrochen_am, testdaten)
    VALUES (marke, (ARRAY['Produktstart', 'Sommeraktion', 'Herbstkampagne', 'Markenbotschaft', 'Gewinnspiel', 'Wintersortiment'])[1 + (j % 6)], kv, kb,
      ARRAY['#beispielmarke' || chr(97 + ((j - 1) % 6))], ARRAY['testdaten'], p_von, p_von, PERS[(ARRAY[1, 2, 3, 5])[1 + (j % 4)]],
      (150000 + j * 47500)::bigint, (50000 + j * 12000)::bigint, 3.5, 'Testdaten: Reichweite für ' || marke || ' aufbauen.',
      'Testdaten: Kernbotschaft der Kampagne.', 'Anzeige', false, abbr, true)
    RETURNING id INTO kampid;
    c_kamp := c_kamp + 1;
    INSERT INTO talent_kampagne_talents (kampagne_id, talent_id)
    SELECT kampid, t FROM unnest(tids) WITH ORDINALITY u(t, o)
    WHERE (o + j) % greatest(3, n / 6) = 0 AND talents_ist_testdaten(t) AND EXISTS (SELECT 1 FROM talents x WHERE x.id = t AND x.status = 'aktiv')
    ON CONFLICT DO NOTHING;
    -- bestätigte Beiträge aus dem Zeitraum (passender Hashtag)
    INSERT INTO talent_kampagne_beitraege (kampagne_id, beitrag_id, status, quelle, grund)
    SELECT kampid, b.id, CASE WHEN b.id % 3 = 0 THEN 'vorschlag' ELSE 'bestaetigt' END, CASE WHEN b.id % 3 = 0 THEN 'automatisch' ELSE 'manuell' END, 'Testdaten'
    FROM talent_kampagne_talents kt JOIN talent_kanaele c ON c.talent_id = kt.talent_id JOIN talent_beitraege b ON b.kanal_id = c.id
    WHERE kt.kampagne_id = kampid AND talents_tag(b.erstellt) BETWEEN kv AND kb AND b.text_inhalt LIKE '%#beispielmarke%'
    ON CONFLICT DO NOTHING;
  END LOOP;

  UPDATE ally_testdaten_stand SET aktiv = true, groesse = n, erzeugt_am = now(), erzeugt_von = p_von,
    anzahl = jsonb_build_object('talents', c_t, 'kanaele', c_k, 'tageswerte', c_tage, 'beitraege', c_b, 'kampagnen', c_kamp, 'personen', 5)
  WHERE id = 1;
  RETURN jsonb_build_object('ok', true, 'talents', c_t, 'kanaele', c_k, 'tageswerte', c_tage, 'beitraege', c_b, 'kampagnen', c_kamp, 'personen', 5);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_info()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
  -- Migration 168 (Bauplan B7): ohne die Test-Logins (manager, talent).
  -- Migration 79: Stand der Testdaten (für die Seite Administration › Testdaten)
  SELECT jsonb_build_object('aktiv', s.aktiv, 'groesse', s.groesse, 'erzeugt_am', CASE WHEN s.erzeugt_am IS NOT NULL THEN talents_zeit(s.erzeugt_am) END,
    'entfernt_am', CASE WHEN s.entfernt_am IS NOT NULL THEN talents_zeit(s.entfernt_am) END, 'anzahl', s.anzahl,
    'talents', (SELECT count(*) FROM talents t WHERE t.testdaten), 'personen', (SELECT count(*) FROM ally_personen p WHERE p.testdaten AND NOT ally_rolle_ist_talent(p.rolle)),
    'kampagnen', (SELECT count(*) FROM talent_kampagnen k WHERE k.testdaten),
    'paket', plattform_modul_an('talents'))
  FROM ally_testdaten_stand s WHERE s.id = 1
$function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_kennung(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record; aus boolean;
BEGIN
  -- Migration 79: welche Talents, Kampagnen und Personen sind Testdaten (für den Hinweis „Testdaten“ und den Filter „Testdaten ausblenden“ je Person).
  -- Leer, solange es keine Testdaten gibt. Gilt für Sitzungen der Oberfläche.
  IF NOT EXISTS (SELECT 1 FROM talents t WHERE t.testdaten) AND NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.testdaten) THEN
    RETURN jsonb_build_object('aktiv', false);
  END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('aktiv', false); END IF;
  SELECT coalesce((z.wert->>'aus')::boolean, false) INTO aus FROM ally_ui_zustand z WHERE z.person = s.person AND z.schluessel = 'testdaten.ausblenden';
  RETURN jsonb_build_object('aktiv', true, 'ausblenden', coalesce(aus, false) AND NOT ally_person_ist_testdaten(s.person),
    'selbst_test', ally_person_ist_testdaten(s.person),
    'talents', coalesce((SELECT jsonb_agg(t.id ORDER BY t.id) FROM talents t WHERE t.testdaten), '[]'::jsonb),
    'kampagnen', coalesce((SELECT jsonb_agg(k.id ORDER BY k.id) FROM talent_kampagnen k WHERE k.testdaten), '[]'::jsonb),
    'personen', coalesce((SELECT jsonb_agg(p.matrix_user_id ORDER BY p.id) FROM ally_personen p WHERE p.testdaten), '[]'::jsonb));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_trennung()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Migration 81 (Testdaten): Test-Personen werden nur Test-Talents und Test-Kampagnen zugeordnet; Test-Talents und echte Talents stehen nie in derselben Kampagne;
  -- was eine Test-Person anlegt (Talent, Kampagne, Bericht), ist selbst Testdaten; Test-Personen bekommen nie Admin oder Superadmin (still verworfen).
  -- Ablehnungen mit SQLSTATE AT001 und verständlichem Text.
  IF TG_TABLE_NAME = 'talent_personen' THEN
    IF ally_person_ist_testdaten(NEW.matrix_user_id) AND NOT talents_ist_testdaten(NEW.talent_id) THEN
      RAISE EXCEPTION USING ERRCODE = 'AT001', MESSAGE = 'Test-Personen können nur Manager oder Managerinnen von Test-Talents sein.';
    END IF;
  ELSIF TG_TABLE_NAME = 'talent_kampagne_talents' THEN
    IF talents_ist_testdaten(NEW.talent_id) IS DISTINCT FROM talents_kampagne_ist_testdaten(NEW.kampagne_id) THEN
      RAISE EXCEPTION USING ERRCODE = 'AT001', MESSAGE = 'Test-Talents und echte Talents lassen sich nicht in derselben Kampagne zusammenfassen.';
    END IF;
  ELSIF TG_TABLE_NAME = 'talent_kampagnen' THEN
    IF TG_OP = 'INSERT' AND ally_person_ist_testdaten(NEW.erstellt_von) THEN NEW.testdaten := true; END IF;
    IF NEW.zustaendig IS NOT NULL AND NOT coalesce(NEW.testdaten, false) AND ally_person_ist_testdaten(NEW.zustaendig) THEN
      RAISE EXCEPTION USING ERRCODE = 'AT001', MESSAGE = 'Test-Personen können nur Manager oder Managerinnen von Test-Kampagnen sein.';
    END IF;
  ELSIF TG_TABLE_NAME IN ('talents', 'talent_berichte') THEN
    IF ally_person_ist_testdaten(NEW.erstellt_von) THEN NEW.testdaten := true; END IF;
  ELSIF TG_TABLE_NAME = 'ally_nutzer_rechte' THEN
    IF NEW.recht IN ('admin', 'superadmin') AND ally_person_ist_testdaten(NEW.matrix_user_id) THEN RETURN NULL; END IF;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
BEGIN
  -- Migration 79: Daten der Seite Administration › Testdaten (nur Superadmin; sonst nichts)
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen OR NOT coalesce(ally_hat_recht(s.person, 'superadmin'), false) THEN RETURN NULL; END IF;
  RETURN ally_testdaten_info();
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_ui_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  m text := NULL; fehler text := NULL; r jsonb; pw text := coalesce(d->>'neu', ''); n integer; tid integer;
BEGIN
  -- Migration 79: Aktionen der Testdaten (td_*). td_ein (groesse 10|50|100), td_aus (td_passwort gab es bis vor Migration 168)
  -- nur Superadmin; td_ausblenden (aus 1|0) für jede Person (eigener Filter). Setzt die Meldung selbst.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF p_aktion = 'td_ausblenden' THEN
    PERFORM ally_ui_zustand_merken(s.person, 'testdaten.ausblenden', jsonb_build_object('aus', d->>'aus' = '1'));
    m := CASE WHEN d->>'aus' = '1' THEN 'Testdaten sind für dich ausgeblendet.' ELSE 'Testdaten sind für dich wieder sichtbar.' END;
  ELSIF NOT coalesce(ally_hat_recht(s.person, 'superadmin'), false) THEN
    fehler := 'Diese Aktion gibt es nicht.';
  ELSIF p_aktion = 'td_ein' THEN
    n := CASE WHEN coalesce(d->>'groesse', '') ~ '^[0-9]{1,3}$' THEN (d->>'groesse')::integer END;
    r := ally_testdaten_erzeugen(n, s.person);
    IF coalesce((r->>'ok')::boolean, false) THEN
      m := 'Testdaten eingeschaltet: ' || (r->>'talents') || ' Talents, ' || (r->>'kanaele') || ' Kanäle, ' || (r->>'beitraege') || ' Beiträge, '
        || (r->>'kampagnen') || ' Kampagnen und 5 Personen.';
    ELSE
      fehler := coalesce(r->>'fehler', 'Die Testdaten konnten nicht erzeugt werden.');
    END IF;
  ELSIF p_aktion = 'td_aus' THEN
    r := ally_testdaten_entfernen(s.person);
    m := 'Testdaten ausgeschaltet und vollständig entfernt.';
  -- Migration 168 (Bauplan B7): td_passwort entfällt (keine Test-Logins mehr)
  ELSE
    fehler := 'Diese Aktion gibt es nicht.';
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL);
  -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung, die Änderungen dieser Aktion sind zurückgenommen
EXCEPTION WHEN SQLSTATE 'AT002' THEN
  RETURN ally_fix_meldung(p_token, SQLERRM);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_vorschlag(p_tid integer, p_nr integer, p_konto text, p_von text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
  heute date := talents_heute();
  roh jsonb;
  liste jsonb := '[]'::jsonb;
  w jsonb;
  hin jsonb;
  nr integer := 0;
  v_id bigint;
BEGIN
  -- Migration 145: ein offener Vorschlag „Zahlen aus Screenshots“ für ein Test-Talent, so wie TALENTS Zahlen auslesen ihn anlegt (Zustand offen, Werte über
  -- talents_manuell_wert_lesen), aber ohne Datei im Speicher, ohne KI, ohne Abruf, ohne Mail und ohne Chat. Nur für Talents mit testdaten = true.
  -- Bestätigen oder Verwerfen läuft über talents_manuell_web_aktion (nur Datenbank); Meldungen dazu gehen nur an Test-Personen (ally_benachrichtigen, Migration 79).
  IF NOT talents_ist_testdaten(p_tid) THEN
    RAISE EXCEPTION 'Migration 145: Talent % gehört nicht zu den Testdaten', p_tid;
  END IF;
  roh := jsonb_build_array(
    jsonb_build_object('plattform', 'instagram', 'konto', p_konto, 'bereich', 'konto', 'kennzahl', 'follower', 'wert', 2000 + p_nr * 41, 'stand', to_char(heute - 2, 'YYYY-MM-DD')),
    jsonb_build_object('plattform', 'instagram', 'konto', p_konto, 'bereich', 'konto', 'kennzahl', 'reichweite', 'wert', 600 + p_nr * 23,
                       'von', to_char(heute - 9, 'YYYY-MM-DD'), 'bis', to_char(heute - 3, 'YYYY-MM-DD')))
    -- jedes zweite: ein Wert ohne Zeitraum (wie beim Auslesen, wenn der Screenshot keinen Zeitraum zeigt)
    || CASE WHEN (p_nr / 12) % 2 = 1 THEN jsonb_build_array(jsonb_build_object('plattform', 'instagram', 'konto', p_konto, 'bereich', 'konto', 'kennzahl', 'interaktionen', 'wert', 40 + p_nr))
            ELSE '[]'::jsonb END;
  FOR w IN SELECT talents_manuell_wert_lesen(e, row_number() OVER ()::integer, 'instagram') FROM jsonb_array_elements(roh) e LOOP
    CONTINUE WHEN w IS NULL;
    nr := nr + 1;
    liste := liste || jsonb_build_array(w || jsonb_build_object('nr', nr));
  END LOOP;
  hin := jsonb_build_array('Testdaten: Werte zum Prüfen, ohne Datei.');
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(liste) e WHERE jsonb_array_length(e->'fehlt') > 0) THEN
    hin := hin || to_jsonb('Bei einigen Werten fehlt der Zeitraum. Bitte vor dem Bestätigen ergänzen.'::text);
  END IF;
  INSERT INTO talent_manuell_vorschlaege (talent_id, quelle, quelle_text, datei_pfad, datei_name, datei_typ, status, werte, hinweise, erstellt_von, erstellt_am)
  VALUES (p_tid, 'hochladen', 'Testdaten: Screenshot zum Prüfen (ohne Datei)', NULL, NULL, NULL, 'offen', liste, hin, p_von, now() - interval '1 hour')
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_ziel(p_ziel jsonb)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 79: zeigt das Ziel einer Benachrichtigung auf ein Test-Talent oder eine Test-Kampagne?
  SELECT CASE WHEN jsonb_typeof(p_ziel) <> 'object' OR jsonb_typeof(p_ziel->'parameter') <> 'object' THEN false
    ELSE (coalesce(p_ziel->>'seite', '') LIKE 'talent%' AND coalesce(p_ziel->'parameter'->>'id', '') ~ '^[0-9]{1,9}$'
            AND talents_ist_testdaten((p_ziel->'parameter'->>'id')::integer))
      OR (coalesce(p_ziel->'parameter'->>'kampagne', '') ~ '^[0-9]{1,9}$' AND talents_kampagne_ist_testdaten((p_ziel->'parameter'->>'kampagne')::integer))
      OR (coalesce(p_ziel->'parameter'->>'talent', '') ~ '^[0-9]{1,9}$' AND talents_ist_testdaten((p_ziel->'parameter'->>'talent')::integer)) END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_testdaten_zufall(p text)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 79: feste Zufallszahl 0 … <1 aus einem Text (gleiches Muster bei jedem Erzeugen)
  SELECT ('x' || substr(md5(p), 1, 8))::bit(32)::bigint / 4294967296.0
$function$
;

CREATE OR REPLACE FUNCTION public.ally_token(p_name text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN p_name IN ('instagram_token', 'linkedin_seite_token') THEN coalesce(nullif(ally_geheim(p_name), ''), NULL, '') ELSE '' END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_token_setzen(p_name text, p_wert text, p_von text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF p_name IS NULL OR p_name NOT IN ('instagram_token', 'linkedin_seite_token') THEN RAISE EXCEPTION 'Unbekanntes Zugangstoken.'; END IF;
  PERFORM ally_geheim_setzen(p_name, p_wert, p_von);
  DELETE FROM ally_einstellungen WHERE schluessel = p_name;
  RETURN true;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_token_vorhanden(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT p_name IN ('instagram_token', 'linkedin_seite_token') AND (ally_geheim_vorhanden(p_name) OR NULL IS NOT NULL)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  e jsonb;
  erlaubt text[];
  reihe text[]; sichtbar text[]; aus text[];
  alt jsonb;
  rf text;
  wer text; wohin text; i integer; j integer; tmp text;
  fertig boolean;
  m text := NULL; fehler text := NULL;
  anz integer;
  r jsonb := NULL; weiter text := NULL; selbst boolean := false;
  png bytea; pr jsonb;
  gr text[]; gi integer; gj integer;
  ub_erlaubt text[]; ub_reihe text[]; ub_aus text[]; ub_sicht text[];
BEGIN
  -- Aktion der neuen Oberfläche (POST app/aktion, BA3): Sitzung und Schutzwert prüfen, mitgeschickte Zustände (_z) speichern, Aktion ausführen,
  -- Meldung für die nächste Seite setzen. Anmeldung und Passwort laufen über ally_ui_anmeldung_aktion (ALLY 36).
  -- BA4: benachrichtigungen_gelesen (alle eigenen als gelesen), benachrichtigung_schalter (Glocke je Art ein/aus, nur eigene).
  -- BA5 (Migration 59): Aktionen der übertragenen Seiten gehen an die vorhandenen Datenbank-Aktionen (wie ALLY 8, ALLY 13 und TALENTS Web).
  -- "weiter" sagt ALLY 20, welcher Ablauf folgt: chat = ALLY 18, start = Start-Abläufe, bericht = Talent-Report,
  -- monatsbericht = BERICHT 2, arbeit = ALLY 37 (Arbeitsbereiche). "r" enthält dafür die Angaben (ohne Passwörter).
  -- BA4b (Migration 60): app_symbol (eigenes App-Symbol als PNG, geprüft mit ally_app_symbol_pruefen) und app_symbol_entfernen, nur Admin.
  -- BA6 (Migration 61): Kampagnen (tk_*) und Kampagnenplanung (kp_*: Deliverables, Freigaben, Erinnerungen, Aufgaben und Termine) über talents_planung_ui_aktion;
  -- Talents (tl_*) über talents_ui_talent_aktion (Management legt die eigenen Talents selbst an und verwaltet sie, Stefan 20.10.2026).
  -- BA7 (Migration 62): Zugang und Talent-Bereich eines Talents (tz_*) über talent_zugang_ui_aktion (Admin oder zuständige Person aus dem Management).
  -- Talent-Sitzungen kennt diese Funktion nicht (sie stehen in talent_web_sitzungen); dafür gilt talent_ui_aktion.
  -- BA8 (Migration 63): Absender-Postfach für Systemnachrichten, Testnachricht, Zugangslink per Mail (sy_*) und eigenes Kalender-Abo (ka_*) über
  -- ally_systemnachricht_ui_aktion; weiter = versand -> ALLY 39 (Zugangsdaten für den Versand setzen, prüfen, leeren).
  -- Migration 64: Rollen (ro_*, ally_rolle_ui_aktion), Rechte am Speicherort (sp_*, ally_speicherort_ui_aktion), für Talents freigegebene Ordner
  -- (to_*, talent_ordner_ui_aktion); alle prüfen die Rechte selbst und setzen die Meldung selbst.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN
    PERFORM ally_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ungueltig', true);
  END IF;
  IF p_aktion = 'abmelden' THEN
    RETURN ally_web_aktion(p_token, 'abmelden', '{}'::jsonb);
  END IF;
  IF s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'muss_pw_setzen', true); END IF;
  -- Migration 172 (B8b, Fixieren): Häkchen „Fixiert“ des Superadmins (_fx_e, _fx_i, _fixiert) gilt für diese Aktion
  PERFORM ally_fix_wunsch(p_daten);
  IF jsonb_typeof(p_zustand->'z') = 'array' THEN
    FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
      IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN
        PERFORM ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen'));
      END IF;
    END LOOP;
  END IF;

  IF p_aktion = 'start_ansicht' THEN
    IF d->>'ansicht' IN ('kacheln', 'liste') THEN
      PERFORM ally_ui_zustand_merken(s.person, 'start.anordnung', jsonb_build_object('ansicht', d->>'ansicht'));
    ELSE
      fehler := 'Diese Ansicht gibt es nicht.';
    END IF;

  ELSIF p_aktion = 'start_anordnen' THEN
    erlaubt := ARRAY(SELECT x.schluessel FROM ally_ui_funktionen x WHERE x.art = 'funktion' AND ally_ui_funktion_erlaubt(s.person, s.rolle, x.schluessel)
                     ORDER BY x.sortierung, x.schluessel);
    SELECT z.wert INTO alt FROM ally_ui_zustand z WHERE z.person = s.person AND z.schluessel = 'start.anordnung';
    alt := coalesce(alt, '{}'::jsonb);
    IF jsonb_typeof(d->'reihe') = 'array' THEN
      reihe := ARRAY(SELECT r.x FROM (SELECT x, min(n) AS n FROM jsonb_array_elements_text(d->'reihe') WITH ORDINALITY t(x, n) WHERE x = ANY (erlaubt) GROUP BY x) r ORDER BY r.n);
      sichtbar := ARRAY(SELECT x FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(d->'sichtbar') = 'array' THEN d->'sichtbar' ELSE '[]'::jsonb END) x WHERE x = ANY (erlaubt));
    ELSE
      reihe := ARRAY(SELECT x FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(alt->'reihe') = 'array' THEN alt->'reihe' ELSE '[]'::jsonb END) x WHERE x = ANY (erlaubt));
      sichtbar := NULL;
    END IF;
    reihe := reihe || ARRAY(SELECT x FROM unnest(erlaubt) x WHERE NOT x = ANY (reihe));
    rf := CASE WHEN d->>'reihenfolge' IN ('eigene', 'az', 'za') THEN d->>'reihenfolge' WHEN alt->>'reihenfolge' IN ('eigene', 'az', 'za') THEN alt->>'reihenfolge' ELSE 'eigene' END;
    IF coalesce(d->>'schieben', '') ~ '^[a-z0-9-]{1,40}:(hoch|runter)$' THEN
      wer := split_part(d->>'schieben', ':', 1); wohin := split_part(d->>'schieben', ':', 2);
      i := array_position(reihe, wer);
      IF i IS NOT NULL THEN
        -- Nachbar in derselben Gruppe suchen (Ziehen und Pfeile wirken nur innerhalb einer Gruppe)
        j := NULL;
        IF wohin = 'hoch' THEN
          FOR n IN REVERSE i - 1 .. 1 LOOP
            IF ally_ui_kachel_gruppe(s.person, reihe[n]) IS NOT DISTINCT FROM ally_ui_kachel_gruppe(s.person, wer) THEN j := n; EXIT; END IF;
          END LOOP;
        ELSE
          FOR n IN i + 1 .. coalesce(array_length(reihe, 1), 0) LOOP
            IF ally_ui_kachel_gruppe(s.person, reihe[n]) IS NOT DISTINCT FROM ally_ui_kachel_gruppe(s.person, wer) THEN j := n; EXIT; END IF;
          END LOOP;
        END IF;
        IF j IS NOT NULL THEN tmp := reihe[i]; reihe[i] := reihe[j]; reihe[j] := tmp; END IF;
      END IF;
      rf := 'eigene';
    END IF;
    IF sichtbar IS NULL THEN
      aus := ARRAY(SELECT x FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(alt->'ausgeblendet') = 'array' THEN alt->'ausgeblendet' ELSE '[]'::jsonb END) x WHERE x = ANY (erlaubt));
    ELSE
      aus := ARRAY(SELECT x FROM unnest(reihe) x WHERE NOT x = ANY (sichtbar));
    END IF;
    -- Migration 76 (Stefan 21.10.2026, Runde 2): Reihenfolge der Gruppen (Pfeile je Gruppe im Anordnen-Modus), gilt nur für die eigene Startseite
    gr := ally_ui_start_gruppen(s.person, s.rolle, CASE WHEN jsonb_typeof(d->'gruppen') = 'array' THEN d->'gruppen' ELSE alt->'gruppen' END);
    IF coalesce(d->>'gruppe_schieben', '') ~ '^[a-z0-9-]{1,40}:(hoch|runter)$' THEN
      gi := array_position(gr, split_part(d->>'gruppe_schieben', ':', 1));
      gj := CASE WHEN split_part(d->>'gruppe_schieben', ':', 2) = 'hoch' THEN gi - 1 ELSE gi + 1 END;
      IF gi IS NOT NULL AND gj BETWEEN 1 AND coalesce(array_length(gr, 1), 0) THEN tmp := gr[gi]; gr[gi] := gr[gj]; gr[gj] := tmp; END IF;
    END IF;
    gr := ARRAY(SELECT x FROM unnest(gr) x WHERE x ~ '^[a-z0-9-]{1,40}$');
    -- Migration 78 (Stefan 21.10.2026, 19:47): Bausteine des Überblicks – Auswahl (ub_sichtbar), Reihenfolge (ub_reihe) und Pfeile (ub_schieben), nur erlaubte Bausteine
    ub_erlaubt := ARRAY(SELECT ub->>'schluessel' FROM jsonb_array_elements(ally_ui_ueberblick(s.person, s.rolle, alt)) ub);
    IF jsonb_typeof(d->'ub_reihe') = 'array' THEN
      ub_reihe := ARRAY(SELECT r.x FROM (SELECT x, min(n) AS n FROM jsonb_array_elements_text(d->'ub_reihe') WITH ORDINALITY t(x, n) WHERE x = ANY (ub_erlaubt) GROUP BY x) r ORDER BY r.n);
      ub_sicht := ARRAY(SELECT x FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(d->'ub_sichtbar') = 'array' THEN d->'ub_sichtbar' ELSE '[]'::jsonb END) x WHERE x = ANY (ub_erlaubt));
    ELSE
      ub_reihe := ub_erlaubt;
      ub_sicht := NULL;
    END IF;
    ub_reihe := ub_reihe || ARRAY(SELECT x FROM unnest(ub_erlaubt) x WHERE NOT x = ANY (ub_reihe));
    IF coalesce(d->>'ub_schieben', '') ~ '^[a-z0-9-]{1,40}:(hoch|runter)$' THEN
      gi := array_position(ub_reihe, split_part(d->>'ub_schieben', ':', 1));
      gj := CASE WHEN split_part(d->>'ub_schieben', ':', 2) = 'hoch' THEN gi - 1 ELSE gi + 1 END;
      IF gi IS NOT NULL AND gj BETWEEN 1 AND coalesce(array_length(ub_reihe, 1), 0) THEN tmp := ub_reihe[gi]; ub_reihe[gi] := ub_reihe[gj]; ub_reihe[gj] := tmp; END IF;
    END IF;
    IF ub_sicht IS NULL THEN
      ub_aus := ARRAY(SELECT ub->>'schluessel' FROM jsonb_array_elements(ally_ui_ueberblick(s.person, s.rolle, alt)) ub WHERE (ub->>'an')::boolean IS FALSE);
    ELSE
      ub_aus := ARRAY(SELECT x FROM unnest(ub_reihe) x WHERE NOT x = ANY (ub_sicht));
    END IF;
    fertig := coalesce(d->>'fertig', '') = '1';
    IF NOT ally_ui_zustand_merken(s.person, 'start.anordnung', jsonb_build_object('reihe', to_jsonb(reihe), 'ausgeblendet', to_jsonb(aus), 'reihenfolge', rf, 'gruppen', to_jsonb(gr), 'ub_reihe', to_jsonb(ub_reihe), 'ub_aus', to_jsonb(ub_aus))) THEN
      fehler := 'Die Anordnung konnte nicht gespeichert werden.';
    ELSIF fertig THEN
      m := 'Die Startseite ist gespeichert.';
    END IF;

  ELSIF p_aktion = 'ki_kopf_sichtbar' THEN
    IF NOT ally_hat_recht(s.person, 'admin') THEN
      fehler := 'Das dürfen nur Admins.';
    ELSIF d->>'wert' NOT IN ('alle', 'admins') OR d->>'wert' IS NULL THEN
      fehler := 'Bitte „alle“ oder „nur Admins“ wählen.';
    ELSE
      PERFORM ally_einstellung_setzen('ki_kopf_sichtbar', d->>'wert', s.person);
      m := CASE WHEN d->>'wert' = 'alle' THEN 'Der KI-Verbrauch steht jetzt für alle im Kopf.' ELSE 'Der KI-Verbrauch steht jetzt nur für Admins im Kopf.' END;
    END IF;

  ELSIF p_aktion = 'fx_setzen' THEN
    -- Migration 172 (B8b, Fixieren): der Superadmin fixiert eine Einstellung (Eintrag) oder gibt sie frei
    IF NOT coalesce(ally_hat_recht(s.person, 'superadmin'), false) THEN
      fehler := 'Das dürfen nur Superadmins.';
    ELSIF NOT EXISTS (SELECT 1 FROM ally_fix_einstellungen x WHERE x.einstellung = d->>'einstellung') OR length(coalesce(d->>'eintrag', '')) > 200 OR coalesce(d->>'fixiert', '') NOT IN ('1', '0') THEN
      fehler := 'Diese Einstellung gibt es nicht.';
    ELSE
      PERFORM ally_fix_setzen(d->>'einstellung', coalesce(d->>'eintrag', ''), d->>'fixiert' = '1', s.person);
      m := (SELECT x.name FROM ally_fix_einstellungen x WHERE x.einstellung = d->>'einstellung') || CASE WHEN d->>'fixiert' = '1' THEN ': fixiert.' ELSE ': frei.' END;
    END IF;

  ELSIF p_aktion = 'paket_funktion' THEN
    -- Migration 172 (B8b, Fixieren): Funktionen gebuchter Pakete schalten Admins (Superadmins alle Funktionen), außer die Funktion ist fixiert
    IF NOT coalesce(ally_hat_recht(s.person, 'admin'), false) THEN
      fehler := 'Das dürfen nur Admins.';
    ELSIF NOT EXISTS (SELECT 1 FROM ally_ui_funktionen x WHERE x.schluessel = d->>'schluessel' AND x.art = 'funktion') OR d->>'an' NOT IN ('1', '0') OR d->>'an' IS NULL THEN
      fehler := 'Diese Funktion gibt es nicht.';
    ELSIF NOT ally_hat_recht(s.person, 'superadmin') AND NOT EXISTS (SELECT 1 FROM ally_ui_funktionen x WHERE x.schluessel = d->>'schluessel' AND (x.modul IS NULL OR plattform_modul_an(x.modul))) THEN
      fehler := 'Das Paket dieser Funktion ist nicht gebucht.';
    ELSIF NOT ally_hat_recht(s.person, 'superadmin') AND ally_fixiert('funktion', d->>'schluessel') THEN
      fehler := 'Diese Funktion ist fixiert.';
    ELSE
      INSERT INTO ally_ui_funktion_schalter (schluessel, an, geaendert_am, geaendert_von) VALUES (d->>'schluessel', d->>'an' = '1', now(), s.person)
      ON CONFLICT (schluessel) DO UPDATE SET an = EXCLUDED.an, geaendert_am = now(), geaendert_von = EXCLUDED.geaendert_von;
      m := ally_ui_name((SELECT x.name FROM ally_ui_funktionen x WHERE x.schluessel = d->>'schluessel')) || CASE WHEN d->>'an' = '1' THEN ' ist eingeschaltet.' ELSE ' ist ausgeschaltet.' END;
    END IF;

  ELSIF p_aktion = 'benachrichtigungen_gelesen' THEN
    IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'benachrichtigungen') THEN
      fehler := 'Das ist für dich nicht freigeschaltet.';
    ELSE
      UPDATE ally_benachrichtigungen b SET gelesen_am = now() WHERE b.person = s.person AND b.gelesen_am IS NULL;
      GET DIAGNOSTICS anz = ROW_COUNT;
      m := CASE WHEN anz = 0 THEN 'Es gibt keine ungelesenen Benachrichtigungen.' WHEN anz = 1 THEN '1 Benachrichtigung ist als gelesen markiert.'
                ELSE anz || ' Benachrichtigungen sind als gelesen markiert.' END;
    END IF;

  ELSIF p_aktion = 'benachrichtigung_schalter' THEN
    IF NOT EXISTS (SELECT 1 FROM ally_benachrichtigung_arten x WHERE x.schluessel = d->>'art') OR coalesce(d->>'glocke', '') NOT IN ('1', '0') THEN
      fehler := 'Diese Art von Benachrichtigung gibt es nicht.';
    ELSE
      INSERT INTO ally_benachrichtigung_schalter (person, art, glocke, geaendert_am) VALUES (s.person, d->>'art', d->>'glocke' = '1', now())
      ON CONFLICT (person, art) DO UPDATE SET glocke = EXCLUDED.glocke, geaendert_am = now();
      m := (SELECT x.name FROM ally_benachrichtigung_arten x WHERE x.schluessel = d->>'art')
           || CASE WHEN d->>'glocke' = '1' THEN ': erscheint in der Glocke.' ELSE ': erscheint nicht mehr in der Glocke.' END;
    END IF;

  ELSIF p_aktion IN ('profil', 'postfach', 'regel_neu', 'regel_loeschen', 'regel_wiederherstellen', 'regel_endgueltig', 'regel_papierkorb_leeren', 'person_daten', 'person_rechte', 'person_zugang', 'person_sperren', 'person_freigeben',
                     'person_ally', 'unternehmen', 'unternehmen_loeschen', 'cd', 'paket_fuer_mich', 'ki_hinweis') THEN
    -- BA5: Einstellungen wie in ALLY 8 über ally_web_aktion (prüft Rechte und Werte, setzt die Meldung selbst). Profil: nur der Name, E-Mail-Adresse
    -- und Passwort ändern sich hier nicht. person_ally nur zum Wieder-Aktivieren; deaktiviert wird über person_deaktivieren (sperrt auch den Chat-Benutzer).
    IF p_aktion = 'person_ally' AND coalesce(d->>'aktiv', '') <> '1' THEN
      fehler := 'Deaktivieren geht über „Person deaktivieren“.';
    ELSE
      IF p_aktion = 'profil' THEN
        d := jsonb_build_object('name', coalesce(d->>'name', ''), 'email', coalesce((SELECT p.email FROM ally_personen p WHERE p.matrix_user_id = s.person), ''));
      END IF;
      r := ally_web_aktion(p_token, p_aktion, d);
      selbst := true;
    END IF;

  ELSIF p_aktion IN ('sa_vertrag', 'sa_module') THEN
    r := superadmin_web_aktion(p_token, substr(p_aktion, 4), d);
    selbst := true;

  ELSIF p_aktion = 'ki_modelle' THEN
    r := ki_web_aktion(p_token, 'ki_modelle', d);
    selbst := true;

  ELSIF p_aktion IN ('tl_liste_hinzu', 'tl_liste_entfernen') THEN
    -- Migration 147 (Stefan 24.10.2026, Konzept D): eigene Liste „Meine Talents“ (prüft die Sichtbarkeit und setzt die Meldung selbst)
    r := talents_liste_aktion(p_token, substr(p_aktion, 4), d);
    selbst := true;

  ELSIF p_aktion IN ('tl_talent_neu', 'tl_talent_bearbeiten', 'tl_einladung_neu', 'tl_kanal_trennen', 'tl_talent_archivieren', 'tl_talent_reaktivieren',
                     'tl_talent_loeschen', 'tl_einstellungen', 'tl_links_erneuern', 'tl_papierkorb_leeren') THEN
    r := talents_ui_talent_aktion(p_token, substr(p_aktion, 4), d);
    selbst := true;

  ELSIF p_aktion IN ('tp_papierkorb_wiederherstellen', 'tp_papierkorb_endgueltig', 'tp_papierkorb_leeren') THEN
    -- Migration 130: Papierkorb des Talent-Profils (setzt die Meldung selbst)
    r := talents_profil_papierkorb(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion IN ('tn_neu', 'tn_bearbeiten', 'tn_loeschen') THEN
    r := talents_notiz_aktion(p_token, 'notiz_' || substr(p_aktion, 4), d);
    selbst := true;

  ELSIF p_aktion IN ('ti_import_pruefen', 'ti_import_anlegen', 'ti_import_verwerfen') THEN
    -- Import einer Tabelle in zwei Schritten wie ALLY 8: prüfen (Vorschau im Sitzungs-Ergebnis), dann anlegen oder verwerfen
    r := talents_import_aktion(p_token, substr(p_aktion, 4), CASE WHEN p_aktion = 'ti_import_pruefen' THEN jsonb_build_object('csv', coalesce(d->>'csv', ''))
           ELSE jsonb_build_object('import_id', coalesce(d->>'import_id', '')) END);
    selbst := true;

  ELSIF p_aktion IN ('tr_vorlage_wiederherstellen', 'tr_vorlage_endgueltig', 'tr_vorlage_papierkorb_leeren') THEN
    -- Migration 132: Papierkorb der Vorlagen (setzt die Meldung selbst)
    r := talents_vorlage_papierkorb(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion IN ('tr_bericht', 'tr_vorlage_erstellen', 'tr_vorlage_loeschen') THEN
    -- Talent-Reports: ein Formular mit zwei Knöpfen (modus = erstellen oder vorlage_speichern); erstellt wird im Ablauf „TALENTS Bericht erzeugen“.
    r := talents_berichte_web_aktion(p_token, CASE p_aktion WHEN 'tr_vorlage_erstellen' THEN 'vorlage_erstellen' WHEN 'tr_vorlage_loeschen' THEN 'vorlage_loeschen'
           ELSE CASE WHEN d->>'modus' = 'vorlage_speichern' THEN 'vorlage_speichern' ELSE 'erstellen' END END, d - 'modus');
    selbst := true;
    IF r->>'weiter' = 'bericht' THEN weiter := 'bericht'; END IF;

  ELSIF p_aktion = 'person_vormerken' THEN
    r := ally_person_vormerken(p_token, d->>'name', d->>'email', d->>'rolle',
           CASE WHEN jsonb_typeof(d->'funktionen') = 'array' THEN d->'funktionen' ELSE '[]'::jsonb END,
           CASE WHEN jsonb_typeof(d->'talents') = 'array' THEN d->'talents' ELSE '[]'::jsonb END,
           CASE WHEN jsonb_typeof(d->'postfaecher') = 'array' THEN d->'postfaecher' ELSE '[]'::jsonb END);
    IF coalesce((r->>'ok')::boolean, false) THEN
      m := r->>'meldung'; weiter := 'chat';
    ELSE
      fehler := coalesce(r->>'fehler', 'Die Person konnte nicht eingeladen werden.');
    END IF;

  ELSIF p_aktion = 'person_rolle' THEN
    r := ally_person_rolle_setzen(p_token, d->>'person', d->>'rolle');
    IF coalesce((r->>'ok')::boolean, false) THEN m := r->>'meldung'; ELSE fehler := coalesce(r->>'fehler', 'Die Rolle konnte nicht gespeichert werden.'); END IF;

  -- Migration 166 (Bauplan B5d): eigene Rechte einer Team-Person (Person-Fenster, Stefan G4); prüft ally_person_eigene_rechte_setzen.
  ELSIF p_aktion = 'person_eigene_rechte' THEN
    r := ally_person_eigene_rechte_setzen(p_token, d->>'person', d->'rechte');  -- Migration 167 (Bauplan B6): M166 N2, die Angabe prüft die Funktion
    IF coalesce((r->>'ok')::boolean, false) THEN m := r->>'meldung'; ELSE fehler := coalesce(r->>'fehler', 'Die Rechte konnten nicht gespeichert werden.'); END IF;

  ELSIF p_aktion = 'person_talents' THEN
    r := ally_person_talents_setzen(p_token, d->>'person', CASE WHEN jsonb_typeof(d->'talents') = 'array' THEN d->'talents' ELSE '[]'::jsonb END);
    IF coalesce((r->>'ok')::boolean, false) THEN m := r->>'meldung'; ELSE fehler := coalesce(r->>'fehler', 'Die Zuordnung als Manager/in konnte nicht gespeichert werden.'); END IF;

  ELSIF p_aktion = 'person_deaktivieren' THEN
    r := ally_person_deaktivieren(p_token, d->>'person');
    IF coalesce((r->>'ok')::boolean, false) THEN
      m := r->>'meldung';
      IF coalesce(r->>'auftrag_id', '') ~ '^[0-9]{1,18}$' THEN weiter := 'chat'; END IF;
    ELSE
      fehler := coalesce(r->>'fehler', 'Die Person konnte nicht deaktiviert werden.');
    END IF;

  ELSIF p_aktion = 'chat_passwort' THEN
    -- Das Passwort kommt nie in die Datenbank: ALLY 20 gibt es nur an ALLY 18 weiter (Auftrag gilt 15 Minuten).
    r := ally_chat_passwort_auftrag(p_token);
    IF coalesce((r->>'ok')::boolean, false) THEN
      m := 'Das Chat-Passwort wird gesetzt.'; weiter := 'chat';
    ELSE
      fehler := coalesce(r->>'fehler', 'Das Chat-Passwort konnte nicht gesetzt werden.');
    END IF;

  ELSIF p_aktion = 'start' THEN
    IF coalesce(d->>'was', '') NOT IN ('belege', 'abgleich', 'themen', 'briefing', 'kundenueberblick') THEN
      fehler := 'Das lässt sich hier nicht starten.';
    ELSE
      r := ally_web_start(p_token, d->>'was', d);
      selbst := true;
      IF coalesce((r->>'ok')::boolean, false) THEN weiter := 'start'; END IF;
    END IF;

  ELSIF p_aktion = 'monatsbericht' THEN
    r := ally_web_recht_pruefen(p_token, 'monatsbericht');
    IF NOT coalesce((r->>'ok')::boolean, false) THEN
      selbst := true;
    ELSIF coalesce(d->>'projekt_id', '') !~ '^[0-9]{1,12}$' THEN
      PERFORM ally_web_meldung(p_token, 'Bericht nicht erstellt: Bitte Kundschaft und Projekt wählen.', 'fehler',
        jsonb_build_object('art', 'monatsbericht', 'ok', false, 'label', left(coalesce(d->>'projekt_label', ''), 200), 'grund', 'Es wurde kein Projekt übermittelt.'));
      selbst := true;
      r := jsonb_build_object('ok', false);
    ELSIF coalesce(d->>'monat', '') !~ '^(20[0-9]{2}-(0[1-9]|1[0-2]))?$' THEN
      fehler := 'Bitte einen Monat wählen.';
    ELSE
      weiter := 'monatsbericht';
      r := jsonb_build_object('ok', true, 'projekt_id', d->>'projekt_id', 'monat', coalesce(d->>'monat', ''),
        'aufgaben_dl', CASE WHEN d->>'aufgaben_dl' = 'ja' THEN 'ja' ELSE '' END, 'label', left(coalesce(d->>'projekt_label', ''), 200));
    END IF;

  ELSIF p_aktion IN ('beitrag', 'freigeben', 'verwerfen', 'posten', 'stornieren', 'loeschen', 'klaerung', 'entwurf', 'ablehnen', 'neue_mail',
                     'termin_neu', 'termin_aendern', 'termin_loeschen', 'systemmails', 'fragen', 'kalender_einstellen') THEN
    -- Arbeitsbereiche wie in ALLY 13: arbeit_web_aktion prüft und setzt die Meldung. Mit „weiter“ folgt der Ablauf in ALLY 37,
    -- dessen Abschluss (arbeit_web_abschluss) die Meldung setzt.
    r := arbeit_web_aktion(p_token, p_aktion, d);
    selbst := true;
    IF coalesce(r->>'weiter', '') <> '' THEN
      weiter := 'arbeit';
      r := r || jsonb_build_object('produkt_name', coalesce(produkt_name(), ''));
    END IF;

  ELSIF p_aktion IN ('mk_papierkorb_wiederherstellen', 'mk_papierkorb_endgueltig', 'mk_papierkorb_leeren', 'mk_papierkorb_entfernen') THEN
    -- Migration 133: Papierkorb Marketing (setzt die Meldung selbst; endgültig mit Ordner: weiter = ALLY 37, marketing_pk_abschliessen setzt die Meldung)
    r := marketing_papierkorb(p_token, p_aktion, d);
    selbst := true;
    IF coalesce(r->>'weiter', '') <> '' THEN
      weiter := 'arbeit';
    END IF;

  ELSIF p_aktion IN ('app_symbol', 'app_symbol_entfernen') THEN
    -- Eigenes App-Symbol (Einstellungen › Unternehmen und Design). ALLY 20 liest die Datei als Base64 (Feld png_b64, höchstens 2 MB + 1 Byte).
    IF NOT ally_hat_recht(s.person, 'admin') THEN
      fehler := 'Das App-Symbol ändert eine Person mit der Rolle Admin.';
    ELSIF p_aktion = 'app_symbol_entfernen' THEN
      DELETE FROM ally_app_symbol x WHERE x.id = 1;
      GET DIAGNOSTICS anz = ROW_COUNT;
      m := CASE WHEN anz = 0 THEN 'Es ist kein eigenes App-Symbol hinterlegt.'
                ELSE 'Das eigene App-Symbol ist entfernt. Es gilt wieder die Bildmarke aus dem Corporate Design.' END;
    ELSIF length(coalesce(d->>'png_b64', '')) > 2796300 THEN
      fehler := 'Die Datei ist größer als 2 MB.';
    ELSE
      BEGIN
        png := decode(coalesce(d->>'png_b64', ''), 'base64');
      EXCEPTION WHEN others THEN
        png := NULL;
      END;
      IF png IS NULL THEN
        fehler := 'Die Datei konnte nicht gelesen werden. Bitte noch einmal hochladen.';
      ELSE
        pr := ally_app_symbol_pruefen(png);
        IF NOT coalesce((pr->>'ok')::boolean, false) THEN
          fehler := coalesce(pr->>'fehler', 'Die Datei ist kein gültiges App-Symbol.');
        ELSE
          INSERT INTO ally_app_symbol (id, png, breite, hoehe, groesse, pruefsumme, geaendert_von, geaendert_am)
          VALUES (1, png, (pr->>'breite')::integer, (pr->>'hoehe')::integer, length(png), md5(png), s.person, now())
          ON CONFLICT (id) DO UPDATE SET png = EXCLUDED.png, breite = EXCLUDED.breite, hoehe = EXCLUDED.hoehe, groesse = EXCLUDED.groesse,
            pruefsumme = EXCLUDED.pruefsumme, geaendert_von = EXCLUDED.geaendert_von, geaendert_am = EXCLUDED.geaendert_am;
          m := 'Das App-Symbol ist gespeichert (' || (pr->>'breite') || ' × ' || (pr->>'hoehe') || ' Pixel).';
        END IF;
      END IF;
    END IF;

  ELSIF p_aktion ~ '^(sy|ka)_[a-z_]{1,40}$' THEN
    -- BA8: prüft die Rechte und setzt die Meldung selbst
    r := ally_systemnachricht_ui_aktion(p_token, p_aktion, d);
    selbst := true;
    IF r->>'weiter' = 'versand' THEN weiter := 'versand'; r := r->'r'; END IF;

  ELSIF p_aktion IN ('ro_endgueltig', 'ro_papierkorb_leeren') THEN
    -- Migration 129: Papierkorb der Rollen (setzt die Meldung selbst)
    r := ally_rolle_papierkorb(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion IN ('unternehmen_wiederherstellen', 'unternehmen_endgueltig', 'unternehmen_papierkorb_leeren') THEN
    -- Migration 129: Papierkorb der Unternehmen (setzt die Meldung selbst)
    r := ally_unternehmen_papierkorb(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion IN ('kp_regel_wiederherstellen', 'kp_regel_endgueltig', 'kp_regel_papierkorb_leeren') THEN
    -- Migration 129: Papierkorb der Standard-Erinnerungen (setzt die Meldung selbst)
    r := talents_regel_papierkorb(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion ~ '^ro_[a-z_]{1,40}$' THEN
    r := ally_rolle_ui_aktion(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion ~ '^sp_[a-z_]{1,40}$' THEN
    r := ally_speicherort_ui_aktion(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion ~ '^to_[a-z_]{1,40}$' THEN
    r := talent_ordner_ui_aktion(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion ~ '^tz_[a-z_]{1,40}$' THEN
    -- BA7: prüft das Recht je Talent und setzt die Meldung selbst
    r := talent_zugang_ui_aktion(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion IN ('kp_papierkorb_wiederherstellen', 'kp_papierkorb_endgueltig', 'kp_papierkorb_leeren') THEN
    -- Migration 131: Papierkorb der Kampagnen (setzt die Meldung selbst)
    r := talents_kampagnen_papierkorb(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion ~ '^(tk|kp)_[a-z_]{1,40}$' THEN
    -- BA6: prüft Rechte je Kampagne und Talent und setzt die Meldung selbst
    r := talents_planung_ui_aktion(p_token, p_aktion, d);
    selbst := true;

  ELSIF p_aktion ~ '^td_[a-z_]{1,30}$' THEN
    -- Testdaten (Migration 79): Schalter und Logins nur Superadmin, Ausblenden für jede Person; setzt die Meldung selbst
    r := ally_testdaten_ui_aktion(p_token, p_aktion, d);
    selbst := true;

  ELSE
    fehler := 'Diese Aktion ist in der neuen Oberfläche noch nicht verfügbar.';
  END IF;

  IF NOT selbst AND coalesce(fehler, m) IS NOT NULL THEN
    PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  END IF;
  RETURN jsonb_build_object('ok', fehler IS NULL AND coalesce((r->>'ok')::boolean, true), 'angemeldet', true, 'fertig', coalesce(fertig, false),
    'weiter', weiter, 'r', CASE WHEN weiter IS NOT NULL THEN r END);
  -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung, die Änderungen dieser Aktion sind zurückgenommen
EXCEPTION WHEN SQLSTATE 'AT002' THEN
  RETURN ally_fix_meldung(p_token, SQLERRM);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_anmeldung(p_code text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Daten der Anmeldeseite (ALLY 36): Produktname, Name des Unternehmens, Prüfung eines Links "Neues Passwort".
  -- Probebetrieb: "Passwort vergessen" läuft über die bisherige Oberfläche (Adresse aus talents_basis(), kein fester Wert), bis Systemnachrichten über das Absender-Postfach gehen.
  -- BA7 (Migration 62): Ist der Code kein Link einer Person, wird er als Zugangslink eines Talents geprüft (einladung = true).
  -- BA8 (Migration 63): vergessen_mail = Absender-Postfach eingestellt -> „Passwort vergessen“ auf dieser Seite (Mail mit Link); sonst wie bisher vergessen_adresse.
  -- Link eines Talents, das schon ein Passwort hat (aus „Passwort vergessen“): einladung = false (Ansicht „Neues Passwort“).
  SELECT jsonb_build_object('produkt', produkt_name(), 'firma', coalesce(eigenes_unternehmen() ->> 'name', ''),
    'vergessen_adresse', CASE WHEN talents_basis() ~ '^https://[a-z0-9.-]+(:[0-9]+)?/[A-Za-z0-9/_-]*/einladung$'
                              THEN regexp_replace(talents_basis(), '/einladung$', '') || '?ansicht=vergessen' END,
    'vergessen_mail', ally_systemnachricht_aktiv(),
    'code', CASE WHEN coalesce(p_code, '') ~ '^[0-9a-f]{64}$' THEN CASE WHEN (ally_web_code_pruefen(p_code)->>'gueltig')::boolean THEN ally_web_code_pruefen(p_code)
                                                                        ELSE talent_zugang_code_pruefen(p_code)
                                                                          || CASE WHEN EXISTS (SELECT 1 FROM talent_zugaenge z WHERE z.einladung_hash = ally_web_hash(p_code) AND z.pw_hash IS NOT NULL)
                                                                                  THEN '{"einladung": false}'::jsonb ELSE '{}'::jsonb END END END)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_anmeldung_aktion(p_aktion text, p_daten jsonb, p_token text, p_csrf text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  s record;
  r jsonb;
  v text := lower(btrim(coalesce(d->>'benutzer', '')));
BEGIN
  -- Anmeldung für alle (K14, ALLY 36): gleiche Prüfungen und Sitzungen wie ALLY 8. Passwörter kommen nur als SHA-256-Prüfsummen aus dem Browser.
  -- BA7 (Migration 62): eine Anmeldung für alle. Die E-Mail-Adresse gibt es nur einmal über Personen und Talents; gefunden wird zuerst eine Person
  -- (wie bisher, ally_web_login), sonst ein Talent-Zugang (talent_web_login, eigene Sitzung). Zugangslinks von Talents laufen über passwort_neu.
  IF p_aktion = 'anmelden' THEN
    -- Migration 158 (Bauplan B3a): Talents haben eine Person (Rolle „Talent“) und melden sich über sie an (talent_person_login; Sitzung bis B4 als Talent-Sitzung).
    IF v <> '' AND EXISTS (SELECT 1 FROM ally_personen p WHERE p.email = v AND ally_rolle_ist_talent(p.rolle) AND p.talent_id IS NOT NULL) THEN
      RETURN talent_person_login(v, d->>'h');
    END IF;
    -- Migration 159 (Bauplan B3b): Der Weg talent_web_login (Talent-Zugang ohne Person) entfällt; jeder Zugang hat eine Person.
    RETURN ally_web_login(d->>'benutzer', d->>'ha', d->>'h', d->>'hc');
  ELSIF p_aktion = 'passwort_neu' THEN
    r := ally_web_passwort_neu(jsonb_build_object('code', d->>'code', 'neu', d->>'neu', 'wiederholung', d->>'wiederholung', 'laenge', d->>'laenge'));
    IF r->>'code' = 'link' THEN
      r := talent_zugang_passwort_neu(jsonb_build_object('code', d->>'code', 'neu', d->>'neu', 'wiederholung', d->>'wiederholung', 'laenge', d->>'laenge'));
    END IF;
    RETURN r;
  ELSIF p_aktion = 'vergessen' THEN
    -- BA8 (Migration 63): Passwort vergessen für Personen und Talents; Antwort immer gleich, Mail nur mit eingestelltem Absender-Postfach
    RETURN ally_systemnachricht_vergessen(d->>'email');
  ELSIF p_aktion = 'passwort_setzen' THEN
    SELECT * INTO s FROM ally_ui_sitzung(p_token);
    IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
    IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ungueltig', true); END IF;
    RETURN ally_web_aktion(p_token, 'passwort_setzen', jsonb_build_object('neu', d->>'neu', 'wiederholung', d->>'wiederholung', 'laenge', d->>'laenge'));
  END IF;
  RETURN jsonb_build_object('ok', false, 'ungueltig', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_csrf(p_token_hash text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Schutzwert gegen fremde Formulare: aus dem (geheimen) Sitzungs-Hash abgeleitet, je Sitzung fest, nie gleich dem Cookie
  SELECT CASE WHEN coalesce(p_token_hash, '') ~ '^[0-9a-f]{64}$' THEN encode(digest('ally-ui-csrf:' || p_token_hash, 'sha256'), 'hex') END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_eingang(p_token text, p_seite text, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  e jsonb;
  so jsonb := p_zustand->'s';
  seite text := CASE WHEN coalesce(p_seite, '') ~ '^[a-z0-9-]{1,40}$' THEN p_seite ELSE 'start' END;
BEGIN
  -- Seitenaufruf (GET): zuerst die mitgeschickten Zustände der eigenen Ansicht speichern (z = auf/zu, s = Sortierung einer Tabelle,
  -- b = geöffnete Benachrichtigung als gelesen markieren, nur eigene), dann der Rahmen.
  -- Ungültige Schlüssel oder Werte werden still übergangen (nur die eigene Ansicht betroffen).
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF FOUND AND NOT s.muss_pw_setzen THEN
    IF jsonb_typeof(p_zustand->'z') = 'array' THEN
      FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
        IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN
          PERFORM ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen'));
        END IF;
      END LOOP;
    END IF;
    IF jsonb_typeof(so) = 'object' AND coalesce(so->>'tabelle', '') ~ '^[a-z0-9-]{1,40}$' THEN
      PERFORM ally_ui_zustand_merken(s.person, seite || '.' || (so->>'tabelle'),
        jsonb_build_object('sortierung', jsonb_build_object('spalte', so->>'spalte', 'richtung', so->>'richtung')));
    END IF;
    IF coalesce(p_zustand->>'b', '') ~ '^[0-9]{1,18}$' THEN
      UPDATE ally_benachrichtigungen b SET gelesen_am = now() WHERE b.id = (p_zustand->>'b')::bigint AND b.person = s.person AND b.gelesen_am IS NULL;
    END IF;
  END IF;
  RETURN ally_ui_rahmen(p_token, seite);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_funktion_erlaubt(p_person text, p_rolle text, p_schluessel text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Darf die Person diese Seite sehen (Migration 64)? Register an, Schalter (Pakete) nicht aus, Paket gebucht, dann das Recht der Seite (ally_hat_recht), nie der Rollenname.
  -- Migration 161 (Bauplan B4b, F9): nur noch das Recht entscheidet; die Spalte rollen und p_rolle werden nicht mehr ausgewertet (p_rolle bleibt für die Aufrufer).
  -- Seiten ohne eigenes Recht (Startseite, Einstellungen, Benachrichtigungen, KI-Verbrauch) gelten für alle Personen außer Personen mit einer Rolle der Art talent.
  -- Seiten nur für Admins haben das Recht „admin“. Rechte für die eigenen Daten eines Talents (nur_selbst, z. B. „Eigenes Profil“) öffnen eine Seite nur für
  -- Talent-Personen (Rolle der Art talent und talent_id); Admins haben solche Rechte zwar im Katalog, aber kein eigenes Profil.
  -- KI-Verbrauch zusätzlich nur für Admins oder für alle, wenn ki_kopf_sichtbar = 'alle' (S3.4).
  SELECT coalesce((
    SELECT f.an AND coalesce(sch.an, true) AND (f.modul IS NULL OR plattform_modul_an(f.modul))
       AND CASE WHEN f.recht IS NULL THEN NOT EXISTS (SELECT 1 FROM ally_personen p JOIN ally_rollen r ON r.schluessel = p.rolle AND r.art = 'talent'
                                                       WHERE p.matrix_user_id = p_person)
                WHEN coalesce(x.nur_selbst, false) THEN ally_person_ist_talent(p_person) AND ally_hat_recht(p_person, f.recht)
                ELSE ally_hat_recht(p_person, f.recht) END
       AND (f.schluessel <> 'ki-verbrauch' OR coalesce(ally_hat_recht(p_person, 'admin'), false) OR ally_einstellung('ki_kopf_sichtbar') = 'alle')
    FROM ally_ui_funktionen f LEFT JOIN ally_ui_funktion_schalter sch ON sch.schluessel = f.schluessel
    LEFT JOIN ally_rechte x ON x.schluessel = f.recht
    WHERE f.schluessel = p_schluessel), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_kachel_gruppe(p_person text, p_schluessel text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Gruppe einer Kachel auf der Startseite der Person: erste eigene Gruppe, die sie enthält, sonst die Standardgruppe
  SELECT coalesce((SELECT g.gruppe FROM ally_ui_eigene_gruppen g WHERE g.person = p_person AND p_schluessel = ANY (g.funktionen) ORDER BY g.sortierung, g.gruppe LIMIT 1),
                  (SELECT f.gruppe FROM ally_ui_funktionen f WHERE f.schluessel = p_schluessel))
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_konto_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  s record; e jsonb; p ally_personen%ROWTYPE; ae ally_email_aenderungen%ROWTYPE;
  r jsonb := NULL; fehler text := NULL; m text := NULL; selbst boolean := false;
  pw text; alt text; em text; code text; tok text;
BEGIN
  IF p_aktion IS NULL OR p_aktion NOT IN ('profil_passwort', 'profil_email', 'profil_email_bestaetigen', 'profil_email_verwerfen',
      'cd_datei', 'cd_datei_loeschen', 'hintergrund_loeschen', 'cd_gestaltung',
      'sa_ki', 'sa_produkt', 'sa_person_admin', 'sa_person_superadmin', 'sa_modell_freigabe') THEN
    RETURN NULL;
  END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN
    PERFORM ally_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ungueltig', true);
  END IF;
  IF s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'muss_pw_setzen', true); END IF;
  IF jsonb_typeof(p_zustand->'z') = 'array' THEN
    FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
      IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN
        PERFORM ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen'));
      END IF;
    END LOOP;
  END IF;

  IF p_aktion = 'profil_passwort' THEN
    SELECT * INTO p FROM ally_personen x WHERE x.matrix_user_id = s.person FOR UPDATE;
    pw := coalesce(d->>'neu', ''); alt := coalesce(d->>'alt', '');
    IF alt !~ '^[0-9a-f]{64}$' OR p.pw_hash IS NULL OR p.pw_hash IS DISTINCT FROM crypt(alt, p.pw_hash) THEN
      PERFORM pg_sleep(0.3);
      fehler := 'Das bisherige Passwort stimmt nicht.';
    ELSIF pw !~ '^[0-9a-f]{64}$' THEN
      fehler := 'Bitte ein neues Passwort eingeben.';
    ELSIF coalesce(d->>'laenge', '') !~ '^[0-9]{1,4}$' OR (d->>'laenge')::integer < 10 THEN
      fehler := 'Das neue Passwort muss mindestens 10 Zeichen lang sein.';
    ELSIF pw <> coalesce(d->>'wiederholung', '') THEN
      fehler := 'Die beiden neuen Passwörter stimmen nicht überein.';
    ELSIF pw = alt THEN
      fehler := 'Das neue Passwort ist dasselbe wie das bisherige.';
    ELSE
      UPDATE ally_personen SET pw_hash = crypt(pw, gen_salt('bf', 12)), pw_alt_name = NULL, benutzername = NULL, geaendert_am = now()
      WHERE matrix_user_id = s.person;
      DELETE FROM ally_web_sitzungen WHERE matrix_user_id = s.person AND token_hash <> s.token_hash;
      m := 'Passwort geändert. Es gilt ab sofort, andere Anmeldungen wurden beendet.';
    END IF;

  ELSIF p_aktion = 'profil_email' THEN
    SELECT * INTO p FROM ally_personen x WHERE x.matrix_user_id = s.person FOR UPDATE;
    em := lower(btrim(coalesce(d->>'email', ''))); alt := coalesce(d->>'alt', '');
    IF NOT ally_systemnachricht_aktiv() OR talent_ui_adresse() IS NULL OR NOT ally_verschluesselung_bereit() THEN
      fehler := 'Die E-Mail-Adresse lässt sich erst ändern, wenn ein Absender-Postfach für Systemnachrichten eingerichtet ist (Einstellungen › Gemeinsame Postfächer, nur Admin). '
        || 'Ally schickt dann einen Bestätigungslink an die neue Adresse. Die E-Mail-Adresse bleibt unverändert.';
    ELSIF NOT ally_mail_gueltig(em) OR em !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' THEN
      fehler := 'Bitte eine gültige E-Mail-Adresse angeben.';
    ELSIF em = lower(coalesce(p.email, '')) THEN
      fehler := 'Das ist schon deine E-Mail-Adresse.';
    ELSIF alt !~ '^[0-9a-f]{64}$' OR p.pw_hash IS NULL OR p.pw_hash IS DISTINCT FROM crypt(alt, p.pw_hash) THEN
      PERFORM pg_sleep(0.3);
      fehler := 'Das bisherige Passwort stimmt nicht.';
    ELSIF EXISTS (SELECT 1 FROM ally_personen x WHERE x.matrix_user_id <> s.person AND (lower(x.email) = em OR lower(x.benutzername) = em))
       OR EXISTS (SELECT 1 FROM ally_chat_auftraege a WHERE a.art = 'anlegen' AND a.status IN ('offen', 'in_arbeit') AND lower(a.daten->>'email') = em)
       OR EXISTS (SELECT 1 FROM talent_zugaenge z WHERE z.email = em) THEN
      fehler := 'Diese E-Mail-Adresse wird schon für eine andere Anmeldung verwendet.';
    ELSIF (SELECT count(*) FROM ally_email_aenderungen x WHERE x.person = s.person AND x.erstellt_am > now() - interval '1 hour') >= 3 THEN
      fehler := 'In der letzten Stunde wurden schon mehrere Bestätigungslinks verschickt. Bitte etwas später erneut versuchen.';
    ELSE
      UPDATE ally_email_aenderungen SET status = 'ersetzt', erledigt_am = now() WHERE person = s.person AND status = 'offen';
      tok := encode(gen_random_bytes(32), 'hex');
      INSERT INTO ally_email_aenderungen (person, neue_email, code_hash, gueltig_bis) VALUES (s.person, em, ally_web_hash(tok), now() + interval '24 hours');
      INSERT INTO ally_systemnachrichten (art, ref, person, geheim, gueltig_bis, erstellt_von)
      VALUES ('email_aendern', 'email:p' || p.id || ':' || left(ally_web_hash(tok), 16), s.person, ally_verschluesseln(tok), now() + interval '23 hours', 'profil');
      m := 'Bestätigungslink an ' || em || ' unterwegs. Die neue Adresse gilt erst nach dem Bestätigen (Link 24 Stunden gültig); bis dahin bleibt die bisherige Anmeldung.';
    END IF;

  ELSIF p_aktion = 'profil_email_bestaetigen' THEN
    code := coalesce(d->>'code', '');
    IF code ~ '^[0-9a-f]{64}$' THEN
      SELECT * INTO ae FROM ally_email_aenderungen x WHERE x.code_hash = ally_web_hash(code) FOR UPDATE;
    END IF;
    IF ae.id IS NULL OR ae.person <> s.person THEN
      fehler := 'Dieser Bestätigungslink gehört nicht zu deiner Anmeldung. Die E-Mail-Adresse bleibt unverändert.';
    ELSIF ae.status <> 'offen' OR ae.gueltig_bis <= now() THEN
      fehler := 'Der Bestätigungslink ist abgelaufen oder wurde schon benutzt. Bitte die Änderung im Profil neu anfordern.';
    ELSIF EXISTS (SELECT 1 FROM ally_personen x WHERE x.matrix_user_id <> s.person AND (lower(x.email) = ae.neue_email OR lower(x.benutzername) = ae.neue_email))
       OR EXISTS (SELECT 1 FROM talent_zugaenge z WHERE z.email = ae.neue_email) THEN
      fehler := 'Diese E-Mail-Adresse wird inzwischen für eine andere Anmeldung verwendet. Die E-Mail-Adresse bleibt unverändert.';
    ELSE
      UPDATE ally_personen SET email = ae.neue_email, benutzername = CASE WHEN pw_alt_name IS NULL THEN NULL ELSE benutzername END, geaendert_am = now()
      WHERE matrix_user_id = s.person;
      UPDATE ally_email_aenderungen SET status = 'bestaetigt', erledigt_am = now() WHERE id = ae.id;
      m := 'E-Mail-Adresse geändert. Die Anmeldung gilt ab sofort mit ' || ae.neue_email || '.';
    END IF;

  ELSIF p_aktion = 'profil_email_verwerfen' THEN
    UPDATE ally_email_aenderungen SET status = 'verworfen', erledigt_am = now() WHERE person = s.person AND status = 'offen';
    IF FOUND THEN m := 'Änderung der E-Mail-Adresse verworfen. Der Bestätigungslink gilt nicht mehr.';
    ELSE fehler := 'Es gibt keine offene Änderung der E-Mail-Adresse.'; END IF;

  ELSIF p_aktion = 'cd_datei' THEN
    -- wie ALLY 10 (Seite Unternehmen bzw. Marketing): prüft Recht, Paket, Typ und Größe und setzt die Meldung selbst
    r := CASE WHEN d->>'art' = 'hintergrund' THEN ally_web_hintergrund(p_token, d) ELSE ally_web_cd_datei(p_token, d) END;
    selbst := true;

  ELSIF p_aktion IN ('cd_datei_loeschen', 'hintergrund_loeschen', 'cd_gestaltung') THEN
    r := ally_web_aktion(p_token, p_aktion, d);
    selbst := true;

  ELSE
    -- sa_*: wie ALLY 8 (nur Superadmin, prüft superadmin_web_aktion)
    r := superadmin_web_aktion(p_token, substr(p_aktion, 4), d);
    selbst := true;
  END IF;

  IF r IS NOT NULL AND r->>'angemeldet' = 'false' THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT selbst AND coalesce(fehler, m) IS NOT NULL THEN
    PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  END IF;
  RETURN jsonb_build_object('ok', fehler IS NULL AND coalesce((r->>'ok')::boolean, true), 'angemeldet', true, 'fertig', false, 'weiter', NULL, 'r', NULL);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_meldung(p_token text, p_text text, p_art text, p_ergebnis jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  r jsonb;
BEGIN
  -- Meldung für die nächste Seite (ALLY 20 „Ergebnis speichern“, BA9): Personen wie bisher (ally_web_meldung), Talent-Sitzungen über talent_web_meldung
  -- (z. B. Ergebnis von ALLY 18 beim Chat-Passwort eines Talents). Ohne Sitzung NULL.
  r := ally_web_meldung(p_token, p_text, p_art, p_ergebnis);
  IF r IS NOT NULL THEN RETURN r; END IF;
  IF EXISTS (SELECT 1 FROM talent_web_sitzung(p_token)) THEN
    PERFORM talent_web_meldung(p_token, left(coalesce(p_text, ''), 500), p_art);
    RETURN jsonb_build_object('ok', p_art = 'ok', 'angemeldet', true);
  END IF;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_name(p_name text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Name einer Funktion; {produkt} = Produktname aus den Einstellungen (kein fester Name im Register)
  SELECT replace(coalesce(p_name, ''), '{produkt}', produkt_name())
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_oberflaeche_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  s record; e jsonb; neu text; alt text; fehler text := NULL; m text := NULL;
BEGIN
  -- Migration 74 (BA11, Stefan 21.10.2026): sa_oberflaeche_adresse (Einstellungen › Superadmin › Adressen) setzt bzw. leert die Einstellung oberflaeche_adresse.
  -- NULL bei allen anderen Aktionen und ohne Personen-Sitzung (ALLY 20 „Aktion ausführen“, Kette coalesce). Sitzung, Schutzwert und Passwort-Pflicht wie ally_ui_konto_aktion.
  -- Erlaubt: https://<host> ohne Pfad, Port und Abfrage (Kleinbuchstaben; ein Schrägstrich am Ende wird entfernt), leer = bisherige Adresse unter /webhook/app.
  IF p_aktion IS DISTINCT FROM 'sa_oberflaeche_adresse' THEN RETURN NULL; END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN
    PERFORM ally_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ungueltig', true);
  END IF;
  IF s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'muss_pw_setzen', true); END IF;
  IF jsonb_typeof(p_zustand->'z') = 'array' THEN
    FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
      IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN
        PERFORM ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen'));
      END IF;
    END LOOP;
  END IF;

  neu := regexp_replace(lower(btrim(coalesce(d->>'adresse', ''))), '/$', '');
  alt := btrim(ally_einstellung('oberflaeche_adresse'));
  IF NOT ally_hat_recht(s.person, 'superadmin') THEN
    fehler := 'Das dürfen nur Superadmins.';
  ELSIF neu <> '' AND (neu !~ '^https://[a-z0-9.-]{3,253}$' OR neu !~ '^https://[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$') THEN
    fehler := 'Bitte die Adresse in der Form https://ally.firma.de angeben (ohne Pfad, ohne Port), oder das Feld leeren.';
  ELSIF neu = coalesce(alt, '') THEN
    m := 'Adresse der Oberfläche unverändert.';
  ELSE
    PERFORM ally_einstellung_setzen('oberflaeche_adresse', neu, s.person);
    m := CASE WHEN neu = '' THEN 'Adresse der Oberfläche geleert. Links und Mails nutzen wieder die bisherige Adresse.'
              ELSE 'Adresse der Oberfläche gespeichert: ' || neu || '. Neue Zugangslinks, Abo-Adressen und Mails nutzen ab jetzt diese Adresse.' END;
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'fertig', false, 'weiter', NULL, 'r', NULL);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_rahmen(p_token text, p_seite text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  fl text; fa text;
  seite text := CASE WHEN coalesce(p_seite, '') ~ '^[a-z0-9-]{1,40}$' THEN p_seite ELSE 'start' END;
  f record;
  erlaubt boolean := false;
  st jsonb; wert text; budget text;
  n_ohne int := 0; teil boolean := false;   -- Migration 189
  ki jsonb := NULL;
  leiste jsonb := NULL;
  zustand jsonb;
  startziel text;
BEGIN
  -- Rahmen einer Seite der neuen Oberfläche (BA3, Glocke BA4): Sitzung, Person, Kopf (KI, Glocke mit den letzten 10 Benachrichtigungen, Zahnrad), linke Leiste gefiltert nach Paket, Recht und Rolle,
  -- Zustände der Person für diese Seite und die Leiste, Ziel-Unterablauf der Seite, Meldung nach einer Aktion (wird dabei gelesen und gelöscht).
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('angemeldet', false, 'produkt', produkt_name());
  END IF;
  SELECT x.flash, x.flash_art INTO fl, fa FROM ally_web_sitzungen x WHERE x.token_hash = s.token_hash FOR UPDATE;
  UPDATE ally_web_sitzungen x SET letzte_nutzung = now(), flash = NULL, flash_art = NULL WHERE x.token_hash = s.token_hash;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('angemeldet', true, 'muss_pw_setzen', true, 'produkt', produkt_name(), 'csrf', ally_ui_csrf(s.token_hash),
      'person', jsonb_build_object('name', s.name, 'email', s.email),
      'hinweis', CASE WHEN fl IS NOT NULL THEN jsonb_build_object('text', fl, 'ton', CASE WHEN fa = 'ok' THEN 'ok' ELSE 'warn' END) END);
  END IF;
  -- Migration 161 (Bauplan B4b): Startziel (G6) – wer die Startseite nicht hat und als einzige Seite das eigene Profil (talent-bereich), landet dort.
  IF seite = 'start' THEN
    IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'start') AND ally_ui_funktion_erlaubt(s.person, s.rolle, 'talent-bereich')
       AND NOT EXISTS (SELECT 1 FROM ally_ui_funktionen x WHERE x.schluessel NOT IN ('start', 'talent-bereich') AND ally_ui_funktion_erlaubt(s.person, s.rolle, x.schluessel)) THEN
      seite := 'talent-bereich';
    -- Migration 169 (Startseite): gilt für die Person eine andere Startseite (eigene Wahl oder Vorgabe für alle), steht sie als startziel im Rahmen.
    -- Der Inhalt bleibt die Startseite; die Web-App wechselt beim Aufruf ohne Parameter zur Seite startziel. Ohne Einstellung fehlt der Eintrag.
    ELSE
      startziel := nullif(ally_startseite_ziel(s.person), 'start');
    END IF;
  END IF;
  SELECT * INTO f FROM ally_ui_funktionen x WHERE x.schluessel = seite;
  IF FOUND THEN erlaubt := ally_ui_funktion_erlaubt(s.person, s.rolle, seite); END IF;
  IF ally_ui_funktion_erlaubt(s.person, s.rolle, 'ki-verbrauch') THEN
    st := ki_monat_stand();
    wert := CASE WHEN st->>'verbrauch_eur' IS NOT NULL THEN round((st->>'verbrauch_eur')::numeric)::text || ' €'
                 ELSE round(coalesce((st->>'verbrauch_usd')::numeric, 0))::text || ' US-$' END;
    budget := CASE WHEN st->>'verbrauch_eur' IS NOT NULL AND st->>'budget_eur' IS NOT NULL THEN round((st->>'budget_eur')::numeric)::text || ' €' END;
    -- Migration 189 (Plan 51): nur Buchungen ohne Preis → „unbekannt“ statt 0 €; mit bekannten zusammen: Betrag wie bisher und sichtbarer Zusatz im Text
    -- („· dazu N Aufrufe ohne Preis“ wie die Kostenzeile, kurz „KI ab 37 €“), ausführlich in der Beschreibung (title, Vorlesen)
    n_ohne := coalesce((st->>'ohne_preis')::int, 0);
    IF n_ohne > 0 AND n_ohne >= coalesce((st->>'aufrufe')::int, 0) THEN wert := 'unbekannt'; ELSE teil := n_ohne > 0; END IF;
    ki := jsonb_build_object('sichtbar', true,
      'text', 'KI ' || wert || coalesce(' / ' || budget, '') || CASE WHEN teil THEN ' · dazu ' || n_ohne::text || CASE WHEN n_ohne = 1 THEN ' Aufruf' ELSE ' Aufrufe' END || ' ohne Preis' ELSE '' END,
      'text_kurz', 'KI ' || CASE WHEN teil THEN 'ab ' ELSE '' END || wert,   -- Nachprüfung 189 N-S1: am Handy kurz „KI ab 37 €“ (mindestens so viel)
      'label', 'KI-Verbrauch in diesem Monat: ' || wert || coalesce(' von ' || budget, '')
        || CASE WHEN n_ohne > 0 THEN ' · ' || CASE WHEN wert = 'unbekannt' THEN '' ELSE 'dazu ' END || n_ohne::text || CASE WHEN n_ohne = 1 THEN ' Aufruf' ELSE ' Aufrufe' END
          || ' ohne Preis (Kosten unbekannt)' ELSE '' END,
      'unbekannt', n_ohne, 'ziel', jsonb_build_object('seite', 'ki-verbrauch'));
  END IF;
  -- Migration 161 (Bauplan B4b): Leiste für jede Person nach Recht (nicht mehr nach der Rolle); die Startseite steht nur darin, wenn sie erlaubt ist;
  -- ohne Startseite und ohne Seite in einer Gruppe gibt es keine Leiste.
  BEGIN
    SELECT jsonb_build_object('art', 'funktionen',
             'start', CASE WHEN ally_ui_funktion_erlaubt(s.person, s.rolle, 'start') THEN
               jsonb_build_object('text', (SELECT x.name FROM ally_ui_funktionen x WHERE x.schluessel = 'start'), 'ziel', jsonb_build_object('seite', 'start')) END,
             'gruppen', coalesce(jsonb_agg(jsonb_build_object('id', g.schluessel, 'name', g.name, 'eintraege', e.eintraege) ORDER BY g.sortierung, g.schluessel), '[]'::jsonb))
      INTO leiste
    FROM ally_ui_gruppen g
    CROSS JOIN LATERAL (SELECT jsonb_agg(jsonb_build_object('schluessel', x.schluessel, 'name', ally_ui_name(x.name), 'ziel', jsonb_build_object('seite', x.schluessel))
                          ORDER BY x.sortierung, x.schluessel) AS eintraege
                        FROM ally_ui_funktionen x WHERE x.gruppe = g.schluessel AND x.art = 'funktion' AND ally_ui_funktion_erlaubt(s.person, s.rolle, x.schluessel)) e
    WHERE e.eintraege IS NOT NULL;
    IF leiste->'start' = 'null'::jsonb AND leiste->'gruppen' = '[]'::jsonb THEN leiste := NULL; END IF;
  END;
  SELECT coalesce(jsonb_object_agg(z.schluessel, z.wert), '{}'::jsonb) INTO zustand FROM ally_ui_zustand z
  WHERE z.person = s.person AND (z.schluessel LIKE 'leiste.%' OR split_part(z.schluessel, '.', 1) = seite);
  RETURN jsonb_build_object('angemeldet', true, 'muss_pw_setzen', false, 'produkt', produkt_name(), 'csrf', ally_ui_csrf(s.token_hash),
    'texte', ally_ui_texte(),
    'person', jsonb_build_object('name', s.name, 'email', s.email, 'rolle', s.rolle, 'rolle_text', coalesce((SELECT r.name FROM ally_rollen r WHERE r.schluessel = s.rolle), nullif(s.rolle, ''), 'Ohne Rolle')),
    'kopf', jsonb_build_object('ki', ki,
       'glocke', CASE WHEN ally_ui_funktion_erlaubt(s.person, s.rolle, 'benachrichtigungen') THEN ally_benachrichtigungen_glocke(s.person, s.rolle)
         || jsonb_build_object('ziel_alle', jsonb_build_object('seite', 'benachrichtigungen'), 'gelesen_aktion', 'benachrichtigungen_gelesen') END,
       'zahnrad', CASE WHEN ally_ui_funktion_erlaubt(s.person, s.rolle, 'einstellungen') THEN jsonb_build_object('ziel', jsonb_build_object('seite', 'einstellungen')) END),
    'profil_ziel', CASE WHEN ally_ui_funktion_erlaubt(s.person, s.rolle, 'einstellungen') THEN jsonb_build_object('seite', 'einstellungen', 'parameter', jsonb_build_object('bereich', 'profil')) END,
    'leiste', leiste,
    'zustand', zustand,
    'funktion', jsonb_build_object('schluessel', seite, 'erlaubt', erlaubt, 'workflow_id', CASE WHEN erlaubt THEN f.workflow_id END,
       'art', CASE WHEN erlaubt THEN f.art END, 'name', CASE WHEN erlaubt THEN ally_ui_name(f.name) END, 'beschreibung', CASE WHEN erlaubt THEN f.beschreibung END,
       'einstellungen_ziel', CASE WHEN erlaubt THEN f.einstellungen_ziel END, 'leiste_aktiv', CASE WHEN erlaubt THEN f.leiste_aktiv END),
    'hinweis', CASE WHEN fl IS NOT NULL THEN jsonb_build_object('text', fl, 'ton', CASE WHEN fa = 'ok' THEN 'ok' ELSE 'warn' END) END)
    || CASE WHEN startziel IS NOT NULL THEN jsonb_build_object('startziel', startziel) ELSE '{}'::jsonb END;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_sitzung(p_token text)
 RETURNS TABLE(token_hash text, person text, name text, email text, rolle text, muss_pw_setzen boolean)
 LANGUAGE sql
 STABLE
AS $function$
  -- Sitzung der neuen Oberfläche = dieselbe Sitzung wie in ALLY 8 (ally_web_sitzungen), dazu der Schlüssel der Rolle der Person ('' = ohne Rolle, Migration 64)
  SELECT s.token_hash, s.matrix_user_id, s.anzeigename, s.email, coalesce(p.rolle, ''), s.muss_pw_setzen
  FROM ally_web_sitzung_pruefen(p_token) s JOIN ally_personen p ON p.matrix_user_id = s.matrix_user_id
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_start_gruppen(p_person text, p_rolle text, p_gespeichert jsonb)
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 76 (Stefan 21.10.2026, Runde 2): Reihenfolge der Gruppen auf der Startseite der Person. Zuerst die gespeicherte Reihenfolge (start.anordnung, Feld gruppen),
  -- danach die übrigen Gruppen wie bisher (eigene Gruppen zuerst, dann Standardgruppen nach Sortierung). Nur Gruppen mit mindestens einer erlaubten Kachel.
  WITH g AS (
    SELECT DISTINCT ally_ui_kachel_gruppe(p_person, x.schluessel) AS id FROM ally_ui_funktionen x
    WHERE x.art = 'funktion' AND ally_ui_funktion_erlaubt(p_person, p_rolle, x.schluessel)
  ), gr AS (
    SELECT eg.gruppe AS id, 0 AS art, eg.sortierung FROM ally_ui_eigene_gruppen eg WHERE eg.person = p_person
    UNION ALL SELECT sg.schluessel, 1, sg.sortierung FROM ally_ui_gruppen sg
  ), gs AS (
    SELECT t.x AS id, t.n FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_gespeichert) = 'array' THEN p_gespeichert ELSE '[]'::jsonb END) WITH ORDINALITY t(x, n)
  ), w AS (
    SELECT DISTINCT ON (gr.id) gr.id, gr.art, gr.sortierung FROM gr WHERE gr.id IN (SELECT g.id FROM g) ORDER BY gr.id, gr.art
  )
  SELECT coalesce(array_agg(w.id ORDER BY (SELECT min(gs.n) FROM gs WHERE gs.id = w.id) NULLS LAST, w.art, w.sortierung, w.id), '{}'::text[]) FROM w
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_startseite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
  cfg jsonb;
  reihe text[];
  aus text[];
  gruppen jsonb;
  greihe text[];
BEGIN
  -- Startseite je Person (S1.2, S2, K9): Kacheln der erlaubten Funktionen in eigenen Gruppen (zuerst) und Standardgruppen,
  -- Reihenfolge aus "start.anordnung" (reihe), ausgeblendete Kacheln, Ansicht Kacheln/Liste, Reihenfolge eigene/az/za.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false); END IF;
  SELECT z.wert INTO cfg FROM ally_ui_zustand z WHERE z.person = s.person AND z.schluessel = 'start.anordnung';
  cfg := coalesce(cfg, '{}'::jsonb);
  reihe := ARRAY(SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(cfg->'reihe') = 'array' THEN cfg->'reihe' ELSE '[]'::jsonb END));
  aus := ARRAY(SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(cfg->'ausgeblendet') = 'array' THEN cfg->'ausgeblendet' ELSE '[]'::jsonb END));
  -- Migration 76 (Stefan 21.10.2026, Runde 2): Reihenfolge der Gruppen je Person (start.anordnung, Feld gruppen), sonst wie bisher
  greihe := ally_ui_start_gruppen(s.person, s.rolle, cfg->'gruppen');
  WITH f AS (
    SELECT x.*, ally_ui_kachel_gruppe(s.person, x.schluessel) AS g, array_position(reihe, x.schluessel) AS pos
    FROM ally_ui_funktionen x WHERE x.art = 'funktion' AND ally_ui_funktion_erlaubt(s.person, s.rolle, x.schluessel)
  ), gr AS (
    SELECT eg.gruppe AS id, eg.name, 0 AS art, eg.sortierung FROM ally_ui_eigene_gruppen eg WHERE eg.person = s.person
    UNION ALL SELECT sg.schluessel, sg.name, 1, sg.sortierung FROM ally_ui_gruppen sg
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', gr.id, 'name', gr.name, 'kacheln', k.kacheln) ORDER BY array_position(greihe, gr.id) NULLS LAST, gr.art, gr.sortierung, gr.id), '[]'::jsonb) INTO gruppen
  FROM gr CROSS JOIN LATERAL (
    SELECT jsonb_agg(jsonb_build_object('schluessel', f.schluessel, 'name', ally_ui_name(f.name), 'beschreibung', f.beschreibung, 'symbol', f.symbol,
             'einstellungen_ziel', f.einstellungen_ziel, 'ausgeblendet', f.schluessel = ANY (aus)) ORDER BY coalesce(f.pos, 1000), f.sortierung, f.schluessel) AS kacheln
    FROM f WHERE f.g = gr.id) k
  WHERE k.kacheln IS NOT NULL;
  RETURN jsonb_build_object('ok', true, 'name', s.name, 'vorname', split_part(btrim(s.name), ' ', 1),
    'ansicht', CASE WHEN cfg->>'ansicht' = 'liste' THEN 'liste' ELSE 'kacheln' END,
    'reihenfolge', CASE WHEN cfg->>'reihenfolge' IN ('az', 'za') THEN cfg->>'reihenfolge' ELSE 'eigene' END,
    'einstellungen', ally_ui_funktion_erlaubt(s.person, s.rolle, 'einstellungen'),
    -- Migration 78 (Stefan 21.10.2026, 19:47): Bausteine des Blocks „Überblick“ (nur erlaubte, in der Reihenfolge der Person, an/aus)
    'ueberblick', ally_ui_ueberblick(s.person, s.rolle, cfg),
    'gruppen', gruppen);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_texte()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Sichtbare Texte des Rahmens und des Baukastens (ALLY 21), genderneutral (Stefan 19.10.2026, BA3). Platzhalter in geschweiften Klammern.
  -- BA4b (Migration 60): „Alle als gelesen markieren“ statt „Alle gelesen“; hinweis/hinweis_zu für das i-Symbol (Beschriftung für Screenreader).
  SELECT jsonb_build_object(
    'zum_inhalt', 'Zum Inhalt springen', 'menue', 'Menü mit allen Funktionen', 'navigation', 'Funktionen', 'navigation_einstellungen', 'Einstellungen',
    'benachrichtigungen', 'Benachrichtigungen', 'benachrichtigungen_ungelesen', 'Benachrichtigungen, {n} ungelesen', 'keine_benachrichtigungen', 'Keine neuen Benachrichtigungen.',
    'alle_gelesen', 'Alle als gelesen markieren', 'alle_benachrichtigungen', 'Alle Benachrichtigungen', 'einstellungen', 'Einstellungen', 'einstellungen_fuer', 'Einstellungen für {name}',
    'brotkrumen', 'Brotkrumen', 'aktionen', 'Aktionen', 'ueberblick', 'Überblick', 'schliessen', 'Schließen', 'seiten', 'Seiten', 'zeilen_von', '{von}–{bis} von {gesamt}',
    'zurueck', 'Zurück', 'weiter', 'Weiter', 'anwenden', 'Anwenden', 'fehler_baustein', 'Dieser Teil der Seite kann nicht angezeigt werden (Baustein „{typ}“).',
    'ansicht', 'Ansicht', 'kacheln', 'Kacheln', 'liste', 'Liste', 'anordnen', 'Anordnen', 'fertig', 'Fertig', 'reihenfolge', 'Reihenfolge',
    'reihenfolge_eigene', 'Eigene', 'reihenfolge_az', 'A–Z', 'reihenfolge_za', 'Z–A',
    'anordnen_hinweis', 'Kacheln an eine andere Stelle ziehen oder mit den Pfeilen verschieben. Ein- und Ausblenden gilt nur für dich.',
    'sichtbar', 'Sichtbar', 'nach_oben', '{name} nach vorn', 'nach_unten', '{name} nach hinten', 'symbol', 'Symbol', 'spalte_funktion', 'Funktion', 'spalte_stand', 'Stand',
    'spalte_gruppe', 'Gruppe', 'hinweis', 'Hinweis', 'hinweis_zu', 'Hinweis zu {name}',
    'startseite', 'Startseite', 'abmelden', 'Abmelden', 'mein_profil', 'Mein Profil',
    'seite_fehlt_titel', 'Seite nicht gefunden', 'seite_fehlt_text', 'Diese Seite gibt es nicht oder sie ist für dich nicht freigeschaltet.',
    'seite_fehler_titel', 'Seite nicht verfügbar', 'seite_fehler_text', 'Diese Seite konnte gerade nicht geladen werden. Bitte später noch einmal versuchen.') || jsonb_build_object(
    -- Migration 76 (Stefan 21.10.2026, Runde 2): Zahnrad „Startseite anordnen“, Gruppen verschieben, externe Links, Säulengrafik mit Tagen, Signatur zu groß
    'startseite_anordnen', 'Startseite anordnen', 'gruppe_nach_oben', 'Gruppe {name} nach vorn', 'gruppe_nach_unten', 'Gruppe {name} nach hinten',
    'anordnen_hinweis', 'Gruppen mit den Pfeilen verschieben, Kacheln ziehen oder mit den Pfeilen verschieben. Ein- und Ausblenden gilt nur für dich.',
    'neuer_tab', 'öffnet in einem neuen Tab', 'aktuelle_seite_darin', 'enthält die aktuelle Seite',
    'hoechster_wert', 'Höchster Wert', 'am_datum', 'am {datum}', 'keine_zahlen', 'keine Zahlen', 'tage_ohne_zahlen', '{n} Tage ohne Zahlen', 'tag_ohne_zahlen', '1 Tag ohne Zahlen',
    'sig_zu_gross', 'Die Signatur ist zu groß zum Speichern ({n} Zeichen, höchstens 20.000). Eingebettete Bilder bitte über „Bild“ als Link zur Bilddatei einfügen.',
    -- Migration 77 (Stefan 21.10.2026, 14:18/14:19): eigene Seite für lange Inhalte (Alle anzeigen) und Verbindungen eines Talents im Fenster „Einstellungen“
    'alle_anzeigen', 'Alle anzeigen ({n})', 'zurueck_zu', 'Zurück zu {name}', 'verbindungen', 'Verbindungen',
    -- Migration 78 (Stefan 21.10.2026, 19:47): Auswahl der Bausteine im Überblick (Startseite anordnen)
    'ueberblick_auswahl_hinweis', 'Wähle, was oben im Überblick steht, und verschiebe es mit den Pfeilen. Angeboten wird nur, was gebucht ist und was du sehen darfst. Gilt nur für dich.',
    'ub_nach_oben', '{name} nach oben', 'ub_nach_unten', '{name} nach unten')
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_ueberblick(p_person text, p_rolle text, p_cfg jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 78 (Stefan 21.10.2026, 19:47/19:48): Bausteine des Überblicks für diese Person, in ihrer Reihenfolge (start.anordnung, Feld ub_reihe; neue Bausteine hinten),
  -- an = nicht ausgeblendet (Feld ub_aus). Ohne gespeicherte Auswahl sind alle erlaubten Bausteine an. Nur erlaubte Bausteine (Paket gebucht und Recht).
  -- gruppe = Name der Standardgruppe der Funktion (nur für die Auswahl beim Anordnen).
  WITH k AS (
    SELECT e->>'schluessel' AS schluessel, e->>'name' AS name, e->>'funktion' AS funktion, e->>'art' AS art, (e->>'sortierung')::int AS sortierung
    FROM jsonb_array_elements(ally_ui_ueberblick_katalog()) e
  ), r AS (
    SELECT t.x, t.n FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_cfg->'ub_reihe') = 'array' THEN p_cfg->'ub_reihe' ELSE '[]'::jsonb END) WITH ORDINALITY t(x, n)
  ), a AS (
    SELECT t.x FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_cfg->'ub_aus') = 'array' THEN p_cfg->'ub_aus' ELSE '[]'::jsonb END) t(x)
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object('schluessel', k.schluessel, 'name', k.name, 'art', k.art, 'funktion', k.funktion,
           'gruppe', coalesce((SELECT g.name FROM ally_ui_funktionen f JOIN ally_ui_gruppen g ON g.schluessel = f.gruppe WHERE f.schluessel = k.funktion), ''),
           'an', NOT EXISTS (SELECT 1 FROM a WHERE a.x = k.schluessel))
         ORDER BY (SELECT min(r.n) FROM r WHERE r.x = k.schluessel) NULLS LAST, k.sortierung), '[]'::jsonb)
  FROM k WHERE ally_ui_funktion_erlaubt(p_person, p_rolle, k.funktion)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_ueberblick_katalog()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 78 (Stefan 21.10.2026, 19:47/19:48): Bausteine für den Block „Überblick“ oben auf der Startseite. Jeder Baustein gehört zu einer Funktion;
  -- angeboten wird er nur, wenn die Person diese Funktion sehen darf (Paket gebucht, Schalter an, Recht – ally_ui_funktion_erlaubt).
  -- art: kennzahl = Zahlenkachel in der oberen Reihe, karte = Karte mit kurzer Liste darunter. Nur Bausteine mit vorhandener Datenquelle.
  SELECT jsonb_build_array(
    jsonb_build_object('schluessel', 'talents-kennzahlen', 'name', 'Talents in Zahlen', 'funktion', 'talents', 'art', 'kennzahl', 'sortierung', 10),
    jsonb_build_object('schluessel', 'talents-handlungsbedarf', 'name', 'Handlungsbedarf', 'funktion', 'talents', 'art', 'karte', 'sortierung', 20),
    jsonb_build_object('schluessel', 'talents-veraenderungen', 'name', 'Größte Veränderungen', 'funktion', 'talents', 'art', 'karte', 'sortierung', 30),
    jsonb_build_object('schluessel', 'talents-kampagnen', 'name', 'Laufende Kampagnen', 'funktion', 'kampagnen', 'art', 'karte', 'sortierung', 40),
    jsonb_build_object('schluessel', 'talents-neue-inhalte', 'name', 'Neue Inhalte', 'funktion', 'talents', 'art', 'karte', 'sortierung', 50),
    jsonb_build_object('schluessel', 'kampagnen-stand', 'name', 'Kampagnen', 'funktion', 'kampagnen', 'art', 'kennzahl', 'sortierung', 60),
    jsonb_build_object('schluessel', 'mails-stand', 'name', 'Antwortvorschläge', 'funktion', 'mail-assistent', 'art', 'kennzahl', 'sortierung', 70),
    jsonb_build_object('schluessel', 'belege-stand', 'name', 'Belege', 'funktion', 'belege', 'art', 'kennzahl', 'sortierung', 80),
    jsonb_build_object('schluessel', 'marketing-stand', 'name', 'Marketing-Themen', 'funktion', 'marketing', 'art', 'kennzahl', 'sortierung', 90))
$function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_verbindung_link(p_token text, p_art text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record; basis text := ally_oberflaeche_webhook(); ziel text;  -- Migration 74 (BA11): gleicher Host wie die Oberfläche (Cookie ally_sitzung gilt je Host)
BEGIN
  IF p_art IS NULL OR p_art NOT IN ('li', 'lis', 'ig', 'pf', 'ki', 'sa') THEN RETURN NULL; END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen OR basis !~ '^https://[A-Za-z0-9.-]{3,253}(:[0-9]{1,5})?(/[A-Za-z0-9._~-]+)*/webhook$' THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  ziel := basis || '/web' || CASE p_art
    WHEN 'li' THEN '/linkedin-verbinden'
    WHEN 'lis' THEN '/linkedin-verbinden?seite=1'
    WHEN 'ig' THEN '?ansicht=marketing#instagram'
    WHEN 'pf' THEN '?ansicht=einstellungen&bereich=postfaecher'
    WHEN 'ki' THEN '?ansicht=einstellungen&bereich=ki#ki-zugang'
    ELSE '?ansicht=einstellungen&bereich=superadmin' || CASE WHEN coalesce(p_id, '') ~ '^[a-z]{2,20}$' THEN '&sa=' || p_id ELSE '' END END;
  RETURN jsonb_build_object('ok', true, 'url', ziel, 'ally8', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_werkzeug_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb, p_geheim jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  g jsonb := CASE WHEN jsonb_typeof(p_geheim) = 'object' THEN p_geheim ELSE '{}'::jsonb END;
  s record; e jsonb; r jsonb := NULL; fn text; ak text; t text; csv text; name text; erg jsonb;
  KI constant text[] := ARRAY['kz_angaben_speichern', 'kz_erstellen', 'kz_ueberarbeitung_anfordern', 'kz_entwurf_speichern', 'kz_aktivieren', 'kz_verwerfen',
    'kz_ziel_speichern', 'kz_ziel_loeschen', 'wf_erstellen', 'tx_erstellen', 'tx_speichern', 'tx_loeschen', 'ma_starten', 'ms_kriterium_hinzufuegen',
    'ms_kriterium_entfernen', 'ms_suche_starten', 'ms_bewerten', 'ms_bewertung_zuruecknehmen', 'me_anlegen', 'kf_speichern', 'ab_waehlen', 'ab_dienst_speichern',
    'ab_dienst_entfernen', 'ab_ordner_zuruecksetzen'];
  SA constant text[] := ARRAY['sa_meta_app', 'sa_meta_ig', 'sa_plattform_app', 'sa_meta_rechte'];
  EIN constant text[] := ARRAY['ki_zugang', 'pk_zugang', 'pf_zugang_speichern', 'pf_zugang_pruefen', 'pf_platz_freigeben', 'li_app', 'li_trennen', 'li_seite_app', 'li_seite_trennen'];
BEGIN
  -- Migration 71 (BA10 Teil 3, Stefan 20.10.2026): letzte Aktionen der bisherigen Oberfläche (ALLY 8) in der neuen Oberfläche (ALLY 20 „Aktion ausführen“, vor ally_ui_aktion).
  -- NULL bei allen anderen Aktionen und ohne Personen-Sitzung (Talent-Sitzungen gelten nicht). Sitzung, Schutzwert (csrf) und Passwort-Pflicht wie ally_ui_aktion.
  -- 1. KI-Werkzeuge der Talents und Einstellungen der Talents wie ALLY 8 („Aktion ausführen“ dort): dieselben Datenbank-Aktionen mit denselben Daten; Rechte, Prüfung und
  --    Texte machen diese Aktionen. Meldung wie ALLY 8 (ally_web_meldung mit meldung bzw. fehler). Mit auftrag_id folgt weiter = ki (ALLY 20 startet „TALENTS KI-Aufträge“
  --    ohne Warten), mit entwurf_id weiter = mail („TALENTS Mail-Entwürfe“). Die KI läuft nur, weil die Person den Knopf gedrückt hat.
  -- 2. tb_verfolgung (Verfolgung eines Beitrags) wie ALLY 8 über talents_beitrag_verfolgung (setzt die Meldung selbst).
  -- 3. Superadmin mit Geheimnissen (Meta-App, Instagram-App, Plattform-Apps, Meta-Rechtstexte): wie ALLY 8/ALLY 16 über meta_app_web_aktion, meta_ig_app_web_aktion,
  --    plattform_app_web_aktion, meta_rueckmeldungen_web_aktion (prüfen Superadmin, setzen die Meldung selbst). Das Geheimnis kommt NICHT aus „daten“, sondern als
  --    eigener Wert p_geheim direkt aus dem Formular (ALLY 20 liest es aus dem Webhook); es wird nur weitergegeben, nie gespeichert außer verschlüsselt durch diese Aktionen.
  -- 4. Einrichtungen über die vorhandenen Abläufe (KI-Zugang ALLY 15, Papierkram ALLY 14, Postfach-Zugang ALLY 9, LinkedIn-App ALLY 12) und Instagram-Zugang
  --    (Schlüsseltausch wie ALLY 8): hier nur Sitzung und Schutzwert; Rechte prüfen die Abläufe selbst. weiter = einrichtung bzw. instagram.
  -- 5. ti_csv: Tabellen der Talents als Datei (Vorlage, Ergebnis eines Imports mit gültigen Links, neue Einladungslinks aus dem eigenen Sitzungs-Ergebnis), weiter = csv.
  IF p_aktion IS NULL OR NOT (p_aktion = ANY (KI) OR p_aktion = ANY (SA) OR p_aktion = ANY (EIN) OR p_aktion IN ('tb_verfolgung', 'instagram', 'ti_csv')) THEN RETURN NULL; END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN
    PERFORM ally_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ungueltig', true);
  END IF;
  IF s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'muss_pw_setzen', true); END IF;
  -- Migration 172 (B8b, Fixieren): Häkchen „Fixiert“ des Superadmins (_fx_e, _fx_i, _fixiert) gilt für diese Aktion
  PERFORM ally_fix_wunsch(p_daten);
  IF jsonb_typeof(p_zustand->'z') = 'array' THEN
    FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
      IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN
        PERFORM ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen'));
      END IF;
    END LOOP;
  END IF;

  IF p_aktion = ANY (KI) THEN
    fn := substr(p_aktion, 1, 2); ak := substr(p_aktion, 4);
    r := CASE fn WHEN 'kz' THEN talents_konzept_aktion(p_token, ak, d) WHEN 'wf' THEN talents_wf_aktion(p_token, ak, d) WHEN 'tx' THEN talents_texte_aktion(p_token, ak, d)
      WHEN 'ma' THEN talents_anfrage_aktion(p_token, ak, d) WHEN 'ms' THEN talents_markensuche_aktion(p_token, ak, d) WHEN 'me' THEN talents_mail_entwurf_anlegen(p_token, d)
      WHEN 'kf' THEN talents_ki_einstellungen_aktion(p_token, d) WHEN 'ab' THEN talents_ablage_web_aktion(p_token, ak, d) END;
    r := coalesce(r, jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Die Aktion konnte nicht ausgeführt werden.'));
    IF coalesce(r->>'meldung', r->>'fehler', '') <> '' THEN
      PERFORM ally_web_meldung(p_token, coalesce(r->>'meldung', r->>'fehler'), CASE WHEN (r->>'ok') = 'true' THEN 'ok' ELSE 'fehler' END, NULL);
    END IF;
    IF (r->>'ok') = 'true' AND coalesce(r->>'auftrag_id', '') ~ '^[0-9]{1,12}$' THEN
      RETURN r || jsonb_build_object('weiter', 'ki', 'r', jsonb_build_object('auftrag_id', r->>'auftrag_id'));
    ELSIF (r->>'ok') = 'true' AND coalesce(r->>'entwurf_id', '') ~ '^[0-9]{1,12}$' THEN
      RETURN r || jsonb_build_object('weiter', 'mail', 'r', jsonb_build_object('entwurf_id', r->>'entwurf_id'));
    END IF;
    RETURN r - 'weiter' - 'r';
  END IF;

  IF p_aktion = 'tb_verfolgung' THEN
    RETURN talents_beitrag_verfolgung(p_token, CASE WHEN (d->>'beitrag') ~ '^[0-9]{1,12}$' THEN (d->>'beitrag')::bigint END, d) - 'weiter' - 'r';
  END IF;

  IF p_aktion = ANY (SA) THEN
    r := CASE p_aktion
      WHEN 'sa_meta_app' THEN meta_app_web_aktion(p_token, jsonb_build_object('app_id', coalesce(d->>'app_id', ''), 'app_secret', btrim(coalesce(g->>'app_secret', ''))))
      WHEN 'sa_meta_ig' THEN meta_ig_app_web_aktion(p_token, jsonb_build_object('app_id', coalesce(d->>'app_id', ''), 'app_secret', btrim(coalesce(g->>'app_secret', ''))))
      WHEN 'sa_plattform_app' THEN plattform_app_web_aktion(p_token, (d - 'app_secret') || jsonb_build_object('app_secret', btrim(coalesce(g->>'app_secret', ''))))
      ELSE meta_rueckmeldungen_web_aktion(p_token, (d - 'ig_basis_secret') || jsonb_build_object('ig_basis_secret', btrim(coalesce(g->>'ig_basis_secret', '')))) END;
    RETURN coalesce(r, jsonb_build_object('ok', false, 'angemeldet', true)) - 'weiter' - 'r';
  END IF;

  IF p_aktion = ANY (EIN) THEN
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'weiter', 'einrichtung', 'r', jsonb_build_object(
      'ziel', CASE WHEN p_aktion = 'ki_zugang' THEN 'ki' WHEN p_aktion = 'pk_zugang' THEN 'pk' WHEN p_aktion LIKE 'pf\_%' THEN 'pf' ELSE 'li' END,
      'aktion', CASE p_aktion WHEN 'pf_zugang_speichern' THEN 'zugang_speichern' WHEN 'pf_zugang_pruefen' THEN 'zugang_pruefen' WHEN 'pf_platz_freigeben' THEN 'platz_freigeben'
        WHEN 'li_app' THEN 'linkedin_app' WHEN 'li_trennen' THEN 'linkedin_trennen' WHEN 'li_seite_app' THEN 'linkedin_seite_app' WHEN 'li_seite_trennen' THEN 'linkedin_seite_trennen' ELSE '' END));
  END IF;

  IF p_aktion = 'instagram' THEN
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'weiter', 'instagram', 'r', jsonb_build_object('aktion', 'instagram'));
  END IF;

  -- ti_csv (das Sitzungs-Ergebnis bleibt erhalten, auch wenn die Datei fehlt)
  t := coalesce(d->>'art', '');
  SELECT w.ergebnis INTO erg FROM ally_web_sitzungen w WHERE w.token_hash = s.token_hash;
  IF t = 'vorlage' THEN
    r := talents_import(p_token, NULL, '{}'::jsonb);
    IF (r->>'ok') = 'true' THEN csv := r->'vorlage'->>'csv'; name := coalesce(r->'vorlage'->>'dateiname', 'talents-vorlage.csv'); END IF;
  ELSIF t = 'import' AND coalesce(d->>'import_id', '') ~ '^[0-9]{1,9}$' THEN
    r := talents_import_csv(p_token, (d->>'import_id')::integer);
    IF (r->>'ok') = 'true' THEN csv := r->>'csv'; name := coalesce(r->>'dateiname', 'talents-import.csv'); END IF;
  ELSIF t = 'links' THEN
    IF erg->>'art' = 'links' AND coalesce(erg->>'csv', '') <> '' THEN csv := erg->>'csv'; name := coalesce(erg->>'dateiname', 'einladungslinks.csv'); END IF;
  END IF;
  IF coalesce(csv, '') = '' THEN
    PERFORM ally_web_meldung(p_token, coalesce(r->>'fehler', CASE WHEN t = 'links' THEN 'Die neuen Einladungslinks stehen nicht mehr zur Verfügung. Bitte neue Links erstellen.'
      ELSE 'Die Tabelle steht nicht zur Verfügung.' END), 'fehler', erg);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'weiter', 'csv', 'r', jsonb_build_object('csv', csv,
    'dateiname', CASE WHEN name ~ '^[A-Za-z0-9._-]{1,100}$' THEN name ELSE 'tabelle.csv' END));
  -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung, die Änderungen dieser Aktion sind zurückgenommen
EXCEPTION WHEN SQLSTATE 'AT002' THEN
  RETURN ally_fix_meldung(p_token, SQLERRM);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_ziel_pruefen(p_ziel jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  k text; v jsonb; n integer := 0;
BEGIN
  -- Ziel in der Oberfläche prüfen ({ seite, parameter, anker }, wie im Baukasten). Ungültig = NULL. Reservierte Parameter (seite, s, p, z, f, m, code, bn) sind verboten.
  IF p_ziel IS NULL OR jsonb_typeof(p_ziel) <> 'object' THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_ziel) x WHERE x NOT IN ('seite', 'parameter', 'anker')) THEN RETURN NULL; END IF;
  IF coalesce(jsonb_typeof(p_ziel->'seite'), '') <> 'string' OR (p_ziel->>'seite') !~ '^[a-z0-9-]{1,40}$' THEN RETURN NULL; END IF;
  IF p_ziel ? 'anker' AND (coalesce(jsonb_typeof(p_ziel->'anker'), '') <> 'string' OR (p_ziel->>'anker') !~ '^[a-z0-9-]{1,40}$') THEN RETURN NULL; END IF;
  IF p_ziel ? 'parameter' THEN
    IF coalesce(jsonb_typeof(p_ziel->'parameter'), '') <> 'object' THEN RETURN NULL; END IF;
    FOR k, v IN SELECT e.key, e.value FROM jsonb_each(p_ziel->'parameter') e LOOP
      n := n + 1;
      IF n > 10 OR k !~ '^[a-z0-9_]{1,30}$' OR k IN ('seite', 's', 'p', 'z', 'f', 'm', 'code', 'bn')
         OR jsonb_typeof(v) NOT IN ('string', 'number', 'boolean') OR length(v #>> '{}') > 200 THEN
        RETURN NULL;
      END IF;
    END LOOP;
  END IF;
  RETURN jsonb_strip_nulls(jsonb_build_object('seite', p_ziel->'seite', 'parameter', p_ziel->'parameter', 'anker', p_ziel->'anker'));
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_zustand_aktion(p_token text, p_csrf text, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; t record; e jsonb; n integer := 0;
BEGIN
  -- Migration 76 (Stefan 21.10.2026, Runde 2): Klappzustand sofort beim Auf- und Zuklappen speichern (POST aktion=ui_zustand aus dem Baukasten ALLY 21, über ALLY 20).
  -- Still: keine Meldung für die nächste Seite, keine Weiterleitung. Gleiche Regeln wie das Mitschicken mit _z in ally_ui_aktion bzw. talent_ui_aktion:
  -- gültige Sitzung, Schutzwert, höchstens 40 Einträge, Schlüssel und Werte prüfen ally_ui_zustand_merken bzw. talent_ui_zustand_merken.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF FOUND THEN
    IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'still', true); END IF;
    IF jsonb_typeof(p_zustand->'z') = 'array' THEN
      FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
        IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' AND ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen')) THEN n := n + 1; END IF;
      END LOOP;
    END IF;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'still', true, 'n', n);
  END IF;
  SELECT * INTO t FROM talent_web_sitzung(p_token);
  IF FOUND THEN
    IF coalesce(p_csrf, '') <> ally_ui_csrf(t.token_hash) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'still', true); END IF;
    IF jsonb_typeof(p_zustand->'z') = 'array' THEN
      FOR e IN SELECT x FROM jsonb_array_elements(p_zustand->'z') x LIMIT 40 LOOP
        IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN PERFORM talent_ui_zustand_merken(t.zugang_id, e->>'k', e->'offen'); n := n + 1; END IF;
      END LOOP;
    END IF;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'still', true, 'n', n);
  END IF;
  RETURN jsonb_build_object('ok', false, 'angemeldet', false, 'still', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_zustand_merken(p_person text, p_schluessel text, p_wert jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  k text; v jsonb; alt jsonb; neu jsonb; n integer;
BEGIN
  -- Zustand je Person speichern (nur erlaubte Schlüssel und Felder, höchstens 2 kB je Schlüssel und 300 Schlüssel je Person). false = abgelehnt, nichts geändert.
  IF p_person IS NULL OR p_schluessel IS NULL OR p_wert IS NULL OR jsonb_typeof(p_wert) <> 'object' THEN RETURN false; END IF;
  IF length(p_schluessel) > 100 OR p_schluessel !~ '^[a-z0-9-]+(\.[a-z0-9-]+){1,2}$' THEN RETURN false; END IF;
  IF split_part(p_schluessel, '.', 1) <> 'leiste' AND NOT EXISTS (SELECT 1 FROM ally_ui_funktionen f WHERE f.schluessel = split_part(p_schluessel, '.', 1)) THEN
    RETURN false;
  END IF;
  FOR k, v IN SELECT e.key, e.value FROM jsonb_each(p_wert) e LOOP
    IF k = 'offen' THEN
      IF jsonb_typeof(v) <> 'boolean' THEN RETURN false; END IF;
    ELSIF k = 'sortierung' THEN
      IF jsonb_typeof(v) <> 'object' OR (SELECT count(*) FROM jsonb_object_keys(v)) <> 2 OR coalesce(v->>'spalte', '') !~ '^[a-z0-9_]{1,40}$'
         OR coalesce(v->>'richtung', '') NOT IN ('auf', 'ab') THEN RETURN false; END IF;
    ELSIF k = 'ansicht' THEN
      IF v NOT IN ('"kacheln"'::jsonb, '"liste"'::jsonb) THEN RETURN false; END IF;
    ELSIF k = 'reihenfolge' THEN
      IF v NOT IN ('"eigene"'::jsonb, '"az"'::jsonb, '"za"'::jsonb) THEN RETURN false; END IF;
    -- Migration 76 (Runde 2): gruppen = Reihenfolge der Gruppen auf der Startseite, gleiche Regeln wie reihe
    -- Migration 78: ub_reihe/ub_aus = Reihenfolge und ausgeblendete Bausteine des Überblicks auf der Startseite
    ELSIF k IN ('reihe', 'ausgeblendet', 'gruppen', 'ub_reihe', 'ub_aus') THEN
      IF jsonb_typeof(v) <> 'array' OR jsonb_array_length(v) > 60
         OR EXISTS (SELECT 1 FROM jsonb_array_elements(v) x WHERE jsonb_typeof(x) <> 'string' OR (x #>> '{}') !~ '^[a-z0-9-]{1,40}$') THEN RETURN false; END IF;
    ELSE
      RETURN false;
    END IF;
  END LOOP;
  SELECT z.wert INTO alt FROM ally_ui_zustand z WHERE z.person = p_person AND z.schluessel = p_schluessel FOR UPDATE;
  neu := coalesce(alt, '{}'::jsonb) || p_wert;
  IF octet_length(neu::text) > 2048 THEN RETURN false; END IF;
  IF alt IS NULL THEN
    SELECT count(*) INTO n FROM ally_ui_zustand z WHERE z.person = p_person;
    IF n >= 300 THEN RETURN false; END IF;
    INSERT INTO ally_ui_zustand (person, schluessel, wert, geaendert_am) VALUES (p_person, p_schluessel, neu, now())
    ON CONFLICT (person, schluessel) DO UPDATE SET wert = ally_ui_zustand.wert || EXCLUDED.wert, geaendert_am = now();
  ELSIF neu IS DISTINCT FROM alt THEN
    UPDATE ally_ui_zustand z SET wert = neu, geaendert_am = now() WHERE z.person = p_person AND z.schluessel = p_schluessel;
  END IF;
  RETURN true;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_ui_zustand_setzen(p_token text, p_schluessel text, p_wert jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
BEGIN
  -- Zustand der eigenen Ansicht speichern (nur mit gültiger Sitzung, nicht vor dem Festlegen des Passworts)
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN false; END IF;
  RETURN ally_ui_zustand_merken(s.person, p_schluessel, p_wert);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_unternehmen_papierkorb(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; x ally_unternehmen%ROWTYPE;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  m text := NULL; fehler text := NULL; n integer := 0; bleibt text[] := '{}';
BEGIN
  -- Migration 129: Papierkorb der Unternehmen (wiederherstellen, endgültig löschen samt Corporate Design und Hintergründen, leeren). Nur Admins.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT ally_hat_recht(s.person, 'admin') THEN
    fehler := 'Unternehmensdaten ändern Admins.';
  ELSIF p_aktion IN ('unternehmen_wiederherstellen', 'unternehmen_endgueltig') THEN
    IF coalesce(d->>'id', '') ~ '^[0-9]{1,9}$' THEN SELECT * INTO x FROM ally_unternehmen u WHERE u.id = (d->>'id')::integer FOR UPDATE; END IF;
    IF x.id IS NULL OR x.geloescht_am IS NULL THEN
      fehler := 'Dieses Unternehmen liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.';
    ELSIF p_aktion = 'unternehmen_wiederherstellen' THEN
      IF EXISTS (SELECT 1 FROM ally_unternehmen u WHERE lower(trim(u.name)) = lower(trim(x.name)) AND u.id <> x.id AND u.geloescht_am IS NULL) THEN
        fehler := 'Ein Unternehmen mit dem Namen „' || x.name || '“ gibt es inzwischen. Bitte das andere zuerst umbenennen.';
      ELSE
        UPDATE ally_unternehmen SET geloescht_am = NULL, geloescht_von = NULL, geaendert_am = now() WHERE id = x.id;
        m := 'Unternehmen ' || x.name || ' wiederhergestellt.';
      END IF;
    ELSIF EXISTS (SELECT 1 FROM ally_firma fx WHERE fx.unternehmen_id = x.id) THEN
      -- Prüfung 129 (N1): eigene Meldung statt Fehler des Fremdschlüssels
      fehler := 'Das ist dein eigenes Unternehmen. Es lässt sich nicht endgültig löschen. Bitte wiederherstellen.';
    ELSIF EXISTS (SELECT 1 FROM ally_postfaecher px WHERE px.unternehmen_id = x.id) THEN
      fehler := 'Dieses Unternehmen ist einem Postfach zugeordnet. Bitte dort zuerst ein anderes Unternehmen wählen, dann endgültig löschen.';
    ELSE
      DELETE FROM ally_unternehmen WHERE id = x.id;
      m := 'Unternehmen ' || x.name || ' endgültig gelöscht, samt Corporate Design und Hintergründen.';
    END IF;
  ELSIF p_aktion = 'unternehmen_papierkorb_leeren' THEN
    IF coalesce(d->>'ids', '') !~ '^[0-9]{1,9}(,[0-9]{1,9})*$' OR cardinality(string_to_array(d->>'ids', ',')) > 1000 THEN
      fehler := 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.';
    ELSE
      -- Prüfung 129 (N1): eigenes Unternehmen und Unternehmen mit Postfach bleiben im Papierkorb und werden genannt
      SELECT coalesce(array_agg(u.name ORDER BY lower(u.name)), '{}') INTO bleibt FROM ally_unternehmen u
       WHERE u.id = ANY (string_to_array(d->>'ids', ',')::integer[]) AND u.geloescht_am IS NOT NULL
         AND (EXISTS (SELECT 1 FROM ally_firma fx WHERE fx.unternehmen_id = u.id) OR EXISTS (SELECT 1 FROM ally_postfaecher px WHERE px.unternehmen_id = u.id));
      DELETE FROM ally_unternehmen u WHERE u.id = ANY (string_to_array(d->>'ids', ',')::integer[]) AND u.geloescht_am IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM ally_firma fx WHERE fx.unternehmen_id = u.id) AND NOT EXISTS (SELECT 1 FROM ally_postfaecher px WHERE px.unternehmen_id = u.id);
      GET DIAGNOSTICS n = ROW_COUNT;
      m := CASE WHEN n = 0 THEN 'Kein Unternehmen gelöscht.' WHEN n = 1 THEN '1 Unternehmen endgültig gelöscht.' ELSE n || ' Unternehmen endgültig gelöscht.' END
        || CASE WHEN cardinality(bleibt) > 0 THEN ' Im Papierkorb bleiben (eigenes Unternehmen oder einem Postfach zugeordnet): ' || array_to_string(bleibt, ', ') || '.' ELSE '' END;
    END IF;
  ELSE
    fehler := 'Diese Aktion gibt es nicht.';
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_update_beenden(p_lauf bigint, p_status text, p_ergebnis text, p_commit text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  u ally_updates%ROWTYPE; v_commit text := nullif(btrim(coalesce(p_commit, '')), '');
BEGIN
  -- Migration 188 (Konzept C.6/C.7): Lauf abschließen. ok trägt die neue Fassung ein (mit Commit), fehler und zurueckgenommen lassen die Fassung wie sie war.
  IF p_status IS NULL OR p_status COLLATE "C" <> ALL (ARRAY['ok', 'fehler', 'zurueckgenommen']) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Abschluss.');
  END IF;
  IF v_commit IS NOT NULL AND v_commit !~ '^[0-9a-f]{7,40}$' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Ungültiger Commit.');
  END IF;
  SELECT * INTO u FROM ally_updates x WHERE x.id = p_lauf FOR UPDATE;
  IF NOT FOUND OR u.status COLLATE "C" <> 'laeuft' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Dieser Lauf ist nicht offen.');
  END IF;
  UPDATE ally_updates SET status = p_status, ergebnis = left(p_ergebnis, 4000), beendet_am = now() WHERE id = p_lauf;
  IF p_status COLLATE "C" = 'ok' THEN
    INSERT INTO ally_fassung (nummer, git_commit, eingespielt_von) VALUES (u.zu_fassung, v_commit, u.person)
    ON CONFLICT (nummer) DO UPDATE SET git_commit = EXCLUDED.git_commit, eingespielt_am = now(), eingespielt_von = EXCLUDED.eingespielt_von;
  END IF;
  RETURN jsonb_build_object('ok', true, 'lauf', p_lauf, 'status', p_status, 'fassung', ally_fassung_aktuell());
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_update_starten(p_person text, p_zu text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_von text := ally_fassung_aktuell(); v_zu text := btrim(coalesce(p_zu, '')); v_id bigint; v_seit timestamp with time zone;
BEGIN
  -- Migration 188 (Konzept C.6/E.4): Update-Lauf beginnen. Nur wer ally_darf_aktualisieren erfüllt, nur eine neuere Fassung, höchstens ein Lauf zugleich
  -- (eindeutiger Teilindex ally_updates_ein_lauf; ein gleichzeitiger zweiter Start scheitert dort und wird hier abgefangen).
  IF NOT coalesce(ally_darf_aktualisieren(p_person), false) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Updates einspielen dürfen nur Admin und Superadmin.');
  END IF;
  IF v_zu !~ '^[0-9]{1,3}[.][0-9]{1,3}$' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte Fassung.');
  END IF;
  IF v_von IS NOT NULL AND ARRAY[split_part(v_zu, '.', 1)::integer, split_part(v_zu, '.', 2)::integer]
       <= ARRAY[split_part(v_von, '.', 1)::integer, split_part(v_von, '.', 2)::integer] THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Eingespielt ist schon Fassung ' || v_von || '. Es gehen nur neuere Fassungen.');
  END IF;
  SELECT u.gestartet_am INTO v_seit FROM ally_updates u WHERE u.status COLLATE "C" = 'laeuft' LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Es läuft schon ein Update (seit ' || to_char(v_seit AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI') || ').');
  END IF;
  BEGIN
    INSERT INTO ally_updates (von_fassung, zu_fassung, person) VALUES (v_von, v_zu, p_person) RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Es läuft schon ein Update.');
  END;
  RETURN jsonb_build_object('ok', true, 'lauf', v_id, 'von', v_von, 'zu', v_zu);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_verlaeufe_aufraeumen()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  tage integer := CASE WHEN coalesce(ally_einstellung('talent_chat_verlauf_tage'), '') ~ '^[0-9]{1,4}$' THEN greatest(7, least(3650, ally_einstellung('talent_chat_verlauf_tage')::integer)) ELSE 90 END;
  a integer; b integer; c integer;
BEGIN
  DELETE FROM talent_chat_verlauf WHERE zeit < now() - make_interval(days => tage);
  GET DIAGNOSTICS a = ROW_COUNT;
  DELETE FROM ally_assistent_verlauf WHERE erstellt_am < now() - interval '30 days';
  GET DIAGNOSTICS b = ROW_COUNT;
  DELETE FROM ally_ergebnisse WHERE erstellt_am < now() - interval '180 days';
  GET DIAGNOSTICS c = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'talent_chat_tage', tage, 'talent_chat', a, 'assistent', b, 'ergebnisse', c);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_verschluesseln(p_text text)
 RETURNS bytea
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF p_text IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN pgp_sym_encrypt(p_text, ally_schluessel(), 'cipher-algo=aes256');
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_verschluesselung_bereit()
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(length(ally_schluessel_roh()) >= 32, false)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_web_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  u text;
  m text := NULL;
  fehler text := NULL;
  k text;
  v text;
  n integer;
  code text;
  ziel text;
  pw text;
  f record;
  neue_rechte text[];
  em text;
  sa_alt boolean;
  sa_neu boolean;
  grenze text;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  u := s.matrix_user_id;

  IF p_aktion = 'abmelden' THEN
    DELETE FROM ally_web_sitzungen WHERE token_hash = s.token_hash;
    RETURN jsonb_build_object('ok', true, 'abmelden', true);
  END IF;

  -- Nach Anmeldung mit Startcode ist nur das Setzen eines Passworts erlaubt
  IF s.muss_pw_setzen AND p_aktion <> 'passwort_setzen' THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;

  IF p_aktion = 'passwort_setzen' THEN
    -- Nach der Anmeldung mit Startcode: eigenes Passwort festlegen
    pw := coalesce(d->>'neu', '');
    IF pw !~ '^[0-9a-f]{64}$' THEN
      fehler := 'Das Passwort konnte nicht verarbeitet werden. Bitte die Seite neu laden.';
    ELSIF coalesce(d->>'laenge', '0') !~ '^[0-9]+$' OR (d->>'laenge')::int < 10 THEN
      fehler := 'Das neue Passwort muss mindestens 10 Zeichen lang sein.';
    ELSIF pw <> coalesce(d->>'wiederholung', '') THEN
      fehler := 'Die beiden neuen Passwörter stimmen nicht überein.';
    ELSE
      UPDATE ally_personen SET pw_hash = crypt(pw, gen_salt('bf', 12)), pw_alt_name = NULL,
        benutzername = CASE WHEN email IS NOT NULL THEN NULL ELSE benutzername END,
        startcode_hash = NULL, startcode_bis = NULL, geaendert_am = now() WHERE matrix_user_id = u;
      DELETE FROM ally_web_sitzungen WHERE matrix_user_id = u AND token_hash <> s.token_hash;
      UPDATE ally_web_sitzungen SET muss_pw_setzen = false, ablauf = now() + interval '30 days' WHERE token_hash = s.token_hash;
      m := 'Passwort gespeichert. Ab jetzt meldest du dich mit deiner E-Mail-Adresse und diesem Passwort an.';
    END IF;

  ELSIF p_aktion = 'profil' THEN
    -- Mein Profil: Name, E-Mail-Adresse, Passwort. Bisheriges Passwort nur nötig, wenn sich E-Mail oder Passwort ändern.
    k := trim(coalesce(d->>'name', ''));
    em := lower(trim(coalesce(d->>'email', '')));
    pw := coalesce(d->>'neu', '');
    IF k = '' THEN
      fehler := 'Bitte deinen Namen angeben.';
    ELSIF em !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' THEN
      fehler := 'Bitte eine gültige E-Mail-Adresse angeben.';
    ELSIF EXISTS (SELECT 1 FROM ally_personen WHERE email = em AND matrix_user_id <> u) THEN
      fehler := 'Diese E-Mail-Adresse gehört schon zu einer anderen Person.';
    ELSIF (pw <> '' OR em IS DISTINCT FROM (SELECT email FROM ally_personen WHERE matrix_user_id = u))
          AND NOT EXISTS (SELECT 1 FROM ally_personen z WHERE z.matrix_user_id = u AND z.pw_hash IS NOT NULL AND z.pw_hash = crypt(coalesce(d->>'alt', ''), z.pw_hash)) THEN
      fehler := 'Das bisherige Passwort stimmt nicht.';
    ELSIF pw <> '' AND pw !~ '^[0-9a-f]{64}$' THEN
      fehler := 'Das Passwort konnte nicht verarbeitet werden. Bitte die Seite neu laden.';
    ELSIF pw <> '' AND (coalesce(d->>'laenge', '0') !~ '^[0-9]+$' OR (d->>'laenge')::int < 10) THEN
      fehler := 'Das neue Passwort muss mindestens 10 Zeichen lang sein.';
    ELSIF pw <> '' AND pw <> coalesce(d->>'wiederholung', '') THEN
      fehler := 'Die beiden neuen Passwörter stimmen nicht überein.';
    ELSE
      UPDATE ally_personen SET name = k, email = em,
        pw_hash = CASE WHEN pw <> '' THEN crypt(pw, gen_salt('bf', 12)) ELSE pw_hash END,
        pw_alt_name = CASE WHEN pw <> '' THEN NULL ELSE pw_alt_name END,
        benutzername = CASE WHEN pw <> '' OR pw_alt_name IS NULL THEN NULL ELSE benutzername END,
        geaendert_am = now()
      WHERE matrix_user_id = u;
      IF pw <> '' THEN
        DELETE FROM ally_web_sitzungen WHERE matrix_user_id = u AND token_hash <> s.token_hash;
      END IF;
      m := 'Profil gespeichert.' || CASE WHEN pw <> '' THEN ' Das neue Passwort gilt ab sofort, andere Anmeldungen wurden beendet.' ELSE '' END;
    END IF;

  ELSIF p_aktion = 'funktionen' THEN
    FOR f IN
      SELECT fx.schluessel FROM ally_funktionen fx
      WHERE (fx.schluessel <> 'systemfehler_meldung' OR ally_hat_recht(u, 'admin'))
         AND (fx.schluessel NOT LIKE 'mail_rueckfrage_%'
         OR EXISTS (SELECT 1 FROM ally_postfaecher p WHERE p.schalter = fx.schluessel AND ally_postfach_zustaendig(u, p.adresse)))
    LOOP
      IF d ? ('sichtbar__' || f.schluessel) THEN
        INSERT INTO ally_nutzer_funktionen (matrix_user_id, schluessel, aktiv) VALUES (u, f.schluessel, d ? ('an__' || f.schluessel))
        ON CONFLICT (matrix_user_id, schluessel) DO UPDATE SET aktiv = EXCLUDED.aktiv, geaendert_am = now()
        WHERE ally_nutzer_funktionen.aktiv IS DISTINCT FROM EXCLUDED.aktiv;
      END IF;
    END LOOP;
    m := 'Funktionen gespeichert.';

  ELSIF p_aktion = 'einstellungen' THEN
    -- Marketing-Felder sind optional: sie stehen seit 15.10.2026 auf der eigenen Seite "Marketing" (Aktion marketing)
    IF ally_web_uhrzeit(d->>'briefing_uhrzeit') IS NULL OR (d ? 'marketing_uhrzeit' AND ally_web_uhrzeit(d->>'marketing_uhrzeit') IS NULL) THEN
      fehler := 'Bitte die Uhrzeiten im Format HH:MM angeben.';
    ELSIF d ? 'marketing_tag' AND coalesce(d->>'marketing_tag', '') !~ '^[1-7]$' THEN
      fehler := 'Bitte einen Wochentag wählen.';
    ELSIF coalesce(d->>'standard_postfach', '') <> '' AND NOT ally_postfach_zustaendig(u, d->>'standard_postfach') THEN
      fehler := 'Als Standard-Postfach geht nur ein Postfach, das du siehst.';
    ELSIF trim(coalesce(d->>'absender_name', '')) = '' OR trim(coalesce(d->>'signatur_name', '')) = '' THEN
      fehler := 'Absendername und Name in der Signatur dürfen nicht leer sein.';
    ELSE
      PERFORM ally_web_wert_setzen(u, 'briefing_uhrzeit', ally_web_uhrzeit(d->>'briefing_uhrzeit'));
      IF d ? 'marketing_uhrzeit' THEN PERFORM ally_web_wert_setzen(u, 'marketing_uhrzeit', ally_web_uhrzeit(d->>'marketing_uhrzeit')); END IF;
      IF d ? 'marketing_tag' THEN PERFORM ally_web_wert_setzen(u, 'marketing_tag', d->>'marketing_tag'); END IF;
      PERFORM ally_web_wert_setzen(u, 'kalender_id', trim(coalesce(d->>'kalender_id', '')));
      PERFORM ally_web_wert_setzen(u, 'standard_postfach', lower(trim(coalesce(d->>'standard_postfach', ''))));
      IF d ? 'marketing_profil' THEN PERFORM ally_web_wert_setzen(u, 'marketing_profil', trim(coalesce(d->>'marketing_profil', ''))); END IF;
      PERFORM ally_web_wert_setzen(u, 'absender_name', trim(d->>'absender_name'));
      PERFORM ally_web_wert_setzen(u, 'signatur_name', trim(d->>'signatur_name'));
      m := 'Einstellungen gespeichert.';
    END IF;

  ELSIF p_aktion = 'postfach' THEN
    ziel := lower(trim(coalesce(d->>'adresse', '')));
    -- Migration 90: persönliche Postfächer stellt nur die Person ein, der sie gehören; gemeinsame wer „Gemeinsame Postfächer verwalten“ hat
    IF NOT EXISTS (SELECT 1 FROM ally_postfaecher WHERE adresse = ziel) THEN
      fehler := 'Unbekanntes Postfach.';
    ELSIF NOT ally_postfach_verwalten_darf(u, ziel) THEN
      fehler := CASE WHEN (SELECT x.art FROM ally_postfaecher x WHERE x.adresse = ziel) = 'persoenlich'
        THEN 'Dieses Postfach gehört einer anderen Person. Einstellen kann es nur sie.'
        ELSE 'Dafür fehlt dir das Recht „Gemeinsame Postfächer verwalten“.' END;
    ELSIF trim(coalesce(d->>'entwurf_ordner', '')) = '' THEN
      fehler := 'Bitte einen Entwurfsordner wählen.';
    ELSIF EXISTS (SELECT 1 FROM postfach_plaetze pp WHERE pp.adresse = ziel AND jsonb_typeof(pp.ordner) = 'array'
                  AND jsonb_array_length(pp.ordner) > 0 AND NOT (pp.ordner ? trim(d->>'entwurf_ordner'))) THEN
      fehler := 'Diesen Entwurfsordner gibt es im Postfach nicht. Bitte aus der Liste wählen oder die Ordner neu einlesen.';
    ELSIF d ? 'einordnung_sichtbar' AND NOT (d ? 'gemeinsam') AND EXISTS (
          SELECT 1 FROM jsonb_each_text(CASE WHEN jsonb_typeof(d->'einordnung') = 'object' THEN d->'einordnung' ELSE '{}'::jsonb END) e
          WHERE e.key IN ('kunde', 'geschaeft', 'spam', 'system_report')
            AND NOT (e.value IN ('nichts', 'hinweis') OR (e.value LIKE 'ordner:_%' AND NOT EXISTS (SELECT 1 FROM postfach_plaetze pp WHERE pp.adresse = ziel
              AND jsonb_typeof(pp.ordner) = 'array' AND jsonb_array_length(pp.ordner) > 0 AND NOT (pp.ordner ? substr(e.value, 8)))))) THEN
      fehler := 'Bei der Einordnung ist ein Ordner gewählt, den es im Postfach nicht gibt. Bitte aus der Liste wählen oder die Ordner neu einlesen.';
    ELSIF d ? 'unternehmen_sichtbar' AND coalesce(d->>'unternehmen_id', '') <> ''
          AND NOT EXISTS (SELECT 1 FROM ally_unternehmen WHERE id::text = d->>'unternehmen_id' AND geloescht_am IS NULL) THEN
      fehler := 'Unbekanntes Unternehmen.';
    ELSE
      UPDATE ally_postfaecher SET
        unternehmen_id = CASE WHEN d ? 'unternehmen_sichtbar' THEN nullif(d->>'unternehmen_id', '')::int ELSE unternehmen_id END,
        name = coalesce(nullif(trim(d->>'name'), ''), name),
        aktiv = d ? 'aktiv',
        entwurf_ordner = trim(d->>'entwurf_ordner'),
        signatur_html = nullif(trim(coalesce(d->>'signatur_html', '')), ''),
        signatur_text = nullif(trim(coalesce(d->>'signatur_text', '')), ''),
        schrift = coalesce((SELECT ms.schluessel FROM mail_schriften ms WHERE ms.schluessel = d->>'schrift'), schrift),
        angebot_bei = CASE WHEN d ? 'angebot_sichtbar' THEN ARRAY(SELECT DISTINCT x FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(d->'angebot') = 'array' THEN d->'angebot' ELSE '[]'::jsonb END) x
          WHERE x IN ('kunde', 'geschaeft', 'antwort')) ELSE angebot_bei END,
        eigene_einordnung = CASE WHEN d ? 'einordnung_sichtbar' THEN NOT (d ? 'gemeinsam') ELSE eigene_einordnung END,
        einordnung = CASE WHEN d ? 'einordnung_sichtbar' AND NOT (d ? 'gemeinsam') THEN (SELECT coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
          FROM jsonb_each_text(CASE WHEN jsonb_typeof(d->'einordnung') = 'object' THEN d->'einordnung' ELSE '{}'::jsonb END) e
          WHERE e.key IN ('kunde', 'geschaeft', 'spam', 'system_report') AND (e.value IN ('nichts', 'hinweis') OR e.value LIKE 'ordner:_%')) ELSE einordnung END,
        schrift_groesse = CASE WHEN coalesce(d->>'schrift_groesse', '') ~ '^[0-9]{1,2}$' AND (d->>'schrift_groesse')::int BETWEEN 10 AND 20 THEN (d->>'schrift_groesse')::int ELSE schrift_groesse END,
        geaendert_am = now()
      WHERE adresse = ziel;
      UPDATE postfach_plaetze SET belege_erfassen = (d ? 'belege'), geaendert_am = now()
      WHERE adresse = ziel AND d ? 'belege_sichtbar' AND belege_erfassen IS DISTINCT FROM (d ? 'belege');
      -- Migration 90: keine Zuständigen je Postfach mehr (Sichtbarkeit gemeinsamer Postfächer steht in der Rolle)
      m := 'Postfach ' || ziel || ' gespeichert' || CASE WHEN d ? 'aktiv' THEN '.' ELSE ' (pausiert).' END;
    END IF;

  ELSIF p_aktion = 'regel_neu' THEN
    -- Absender-Regel, auf Wunsch nur für ein Postfach (gleiche Funktion wie im Chat)
    v := mail_regel_speichern(u, d->>'muster', d->>'kategorie', d->>'notiz', d->>'postfach', 'web')::text;
    IF (v::jsonb->>'ok')::boolean THEN m := v::jsonb->>'meldung'; ELSE fehler := v::jsonb->>'meldung'; END IF;

  ELSIF p_aktion = 'regel_loeschen' THEN
    v := mail_regel_loeschen(u, d->>'muster', coalesce(nullif(d->>'postfach', ''), 'alle'))::text;
    IF (v::jsonb->>'ok')::boolean THEN m := v::jsonb->>'meldung'; ELSE fehler := v::jsonb->>'meldung'; END IF;

  ELSIF p_aktion IN ('regel_wiederherstellen', 'regel_endgueltig', 'regel_papierkorb_leeren') THEN
    -- Migration 128: Papierkorb der Absender-Regeln (E13)
    v := mail_regel_papierkorb(u, p_aktion, CASE WHEN p_aktion = 'regel_papierkorb_leeren' THEN d->>'ids' ELSE d->>'id' END)::text;
    IF (v::jsonb->>'ok')::boolean THEN m := v::jsonb->>'meldung'; ELSE fehler := v::jsonb->>'meldung'; END IF;

  ELSIF p_aktion = 'unternehmen' THEN
    -- Unternehmen anlegen oder ändern (nur Admins); Postfächer werden einem Unternehmen zugeordnet
    k := left(trim(coalesce(d->>'name', '')), 120);
    v := coalesce(d->>'id', '');
    IF NOT ally_hat_recht(u, 'admin') THEN
      fehler := 'Unternehmensdaten ändern Admins.';
    ELSIF k = '' THEN
      fehler := 'Bitte den Namen des Unternehmens angeben.';
    ELSIF v <> '' AND NOT EXISTS (SELECT 1 FROM ally_unternehmen WHERE id::text = v AND geloescht_am IS NULL) THEN
      fehler := 'Unbekanntes Unternehmen.';
    ELSIF EXISTS (SELECT 1 FROM ally_unternehmen WHERE lower(trim(name)) = lower(k) AND id::text <> v AND geloescht_am IS NULL) THEN
      fehler := 'Ein Unternehmen mit diesem Namen gibt es schon.';
    ELSIF EXISTS (SELECT 1 FROM ally_unternehmen WHERE lower(trim(name)) = lower(k) AND id::text <> v) THEN
      fehler := 'Ein Unternehmen mit diesem Namen liegt im Papierkorb. Bitte dort wiederherstellen oder endgültig löschen.';
    ELSIF trim(coalesce(d->>'website', '')) <> '' AND trim(d->>'website') !~* '^(https?://)?[a-z0-9.-]+[.][a-z]{2,}(/[^[:space:]]*)?$' THEN
      fehler := 'Bitte die Website als Adresse angeben, z. B. www.beispiel.de.';
    ELSIF v = '' THEN
      INSERT INTO ally_unternehmen (name, inhaber, ort, website, leistungen)
      VALUES (k, nullif(left(trim(coalesce(d->>'inhaber', '')), 120), ''), nullif(left(trim(coalesce(d->>'ort', '')), 120), ''),
              nullif(left(trim(coalesce(d->>'website', '')), 200), ''), nullif(left(trim(coalesce(d->>'leistungen', '')), 2000), ''));
      m := 'Unternehmen ' || k || ' angelegt. Jetzt bei den Postfächern zuordnen.';
    ELSE
      UPDATE ally_unternehmen SET name = k,
        inhaber = nullif(left(trim(coalesce(d->>'inhaber', '')), 120), ''), ort = nullif(left(trim(coalesce(d->>'ort', '')), 120), ''),
        website = nullif(left(trim(coalesce(d->>'website', '')), 200), ''), leistungen = nullif(left(trim(coalesce(d->>'leistungen', '')), 2000), ''),
        geaendert_am = now()
      WHERE id::text = v;
      m := 'Unternehmen ' || k || ' gespeichert.';
    END IF;

  ELSIF p_aktion = 'unternehmen_loeschen' THEN
    v := coalesce(d->>'id', '');
    IF NOT ally_hat_recht(u, 'admin') THEN
      fehler := 'Unternehmensdaten ändern Admins.';
    ELSIF NOT EXISTS (SELECT 1 FROM ally_unternehmen WHERE id::text = v AND geloescht_am IS NULL) THEN
      fehler := 'Unbekanntes Unternehmen.';
    ELSIF EXISTS (SELECT 1 FROM ally_firma firma_x WHERE firma_x.unternehmen_id::text = v) THEN
      fehler := 'Das ist dein eigenes Unternehmen. Belege, Marketing und ' || produkt_name() || ' nutzen diese Angaben, deshalb lässt es sich nicht löschen.';
    ELSIF EXISTS (SELECT 1 FROM ally_postfaecher WHERE unternehmen_id::text = v) THEN
      fehler := 'Dieses Unternehmen ist noch einem Postfach zugeordnet. Bitte dort zuerst ein anderes Unternehmen wählen.';
    ELSE
      -- Migration 129: in den Papierkorb (Corporate Design und Hintergründe bleiben bis zum endgültigen Löschen)
      UPDATE ally_unternehmen SET geloescht_am = now(), geloescht_von = u WHERE id::text = v RETURNING name INTO k;
      m := 'Unternehmen ' || k || ' liegt jetzt im Papierkorb. Dort kannst du es wiederherstellen oder endgültig löschen.';
    END IF;

  ELSIF p_aktion LIKE 'person_%' AND NOT ally_hat_recht(u, 'admin') THEN
    fehler := 'Personen und Rechte verwaltet nur eine Person mit der Rolle Admin.';

  -- Superadmin-Schutz (Stefan 18.10.2026): An einer Person mit Recht Superadmin ändert nur ein Superadmin etwas
  ELSIF p_aktion LIKE 'person_%' AND p_aktion <> 'person_neu' AND ally_person_superadmin(coalesce(d->>'id', '')) AND NOT ally_hat_recht(u, 'superadmin') THEN
    fehler := 'Diese Person ist Superadmin. Änderungen an ihr nehmen nur Superadmins vor.';

  ELSIF p_aktion = 'person_neu' THEN
    v := trim(coalesce(d->>'id', ''));
    k := trim(coalesce(d->>'name', ''));
    IF v !~ '^@[a-z0-9._=/+\-]+:[a-z0-9.\-]+\.[a-z]{2,}$' THEN
      fehler := 'Bitte die Chat-Adresse vollständig angeben, z. B. @anna:' || split_part(u, ':', 2) || '.';
    ELSIF k = '' THEN
      fehler := 'Bitte einen Namen angeben.';
    ELSIF EXISTS (SELECT 1 FROM ally_personen WHERE matrix_user_id = v) THEN
      fehler := 'Diese Person gibt es schon.';
    ELSIF coalesce(trim(d->>'email'), '') <> '' AND lower(trim(d->>'email')) !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' THEN
      fehler := 'Bitte eine gültige E-Mail-Adresse angeben.';
    ELSIF coalesce(trim(d->>'email'), '') <> '' AND EXISTS (SELECT 1 FROM ally_personen WHERE email = lower(trim(d->>'email'))) THEN
      fehler := 'Diese E-Mail-Adresse gehört schon zu einer anderen Person.';
    ELSE
      em := nullif(lower(trim(coalesce(d->>'email', ''))), '');
      INSERT INTO ally_personen (matrix_user_id, name, email, aktiv) VALUES (v, k, em, true);
      m := k || ' angelegt. Jetzt Rechte setzen und einen Zugang mit Startcode erzeugen.';
    END IF;

  ELSIF p_aktion IN ('person_zugang', 'person_sperren', 'person_freigeben', 'person_rechte', 'person_ally', 'person_daten') THEN
    ziel := coalesce(d->>'id', '');
    IF NOT EXISTS (SELECT 1 FROM ally_personen WHERE matrix_user_id = ziel) THEN
      fehler := 'Unbekannte Person.';
    -- Migration 158 (Bauplan B3a): Talent-Personen ändert man im Talent-Profil.
    ELSIF ally_person_ist_talent(ziel) THEN
      fehler := 'Den Zugang eines Talents änderst du im Talent-Profil.';

    ELSIF p_aktion = 'person_rechte' THEN
      -- Superadmin (Stefan 18.10.2026): wird getrennt behandelt; vergeben oder entziehen darf es nur ein Superadmin, sonst bleibt der bisherige Stand
      SELECT coalesce(array_agg(r.schluessel), '{}') INTO neue_rechte FROM ally_rechte r WHERE d ? ('recht__' || r.schluessel) AND (r.modul IS NULL OR plattform_modul_an(r.modul))
        AND r.schluessel = 'admin';  -- Migration 167 (Bauplan B6): F13, hier nur noch admin (superadmin getrennt); alle übrigen Rechte in der Rolle oder unter „Eigene Rechte“
      sa_alt := ally_person_superadmin(ziel);
      -- Migration 167 (Bauplan B6): Prüfung M1, ohne Kennung recht__superadmin_feld (Häkchen „Superadmin“ im Formular) bleibt der bisherige Stand
      sa_neu := CASE WHEN ally_hat_recht(u, 'superadmin') AND d ? 'recht__superadmin_feld' THEN d ? 'recht__superadmin' ELSE sa_alt END;
      IF d ? 'recht__superadmin' AND NOT sa_alt AND NOT ally_hat_recht(u, 'superadmin') THEN
        fehler := 'Das Recht Superadmin vergeben nur Superadmins.';
      -- Migration 168 (Bauplan B7): G1, Superadmin nur für Personen aus der Liste superadmin_personen
      ELSIF sa_neu AND NOT sa_alt AND NOT ally_superadmin_erlaubt(ziel) THEN
        fehler := 'Das Recht Superadmin lässt sich hier nicht vergeben.';
      ELSIF ziel = u AND NOT ('admin' = ANY (neue_rechte)) THEN
        fehler := 'Du kannst dir das Admin-Recht nicht selbst entziehen.';
      ELSIF sa_alt AND NOT sa_neu AND NOT EXISTS (SELECT 1 FROM ally_nutzer_rechte x WHERE x.recht = 'superadmin' AND x.matrix_user_id <> ziel) THEN
        fehler := 'Der letzte Superadmin kann das Recht Superadmin nicht abgeben. Bitte zuerst einer anderen Person das Recht Superadmin geben.';
      ELSE
        -- Rechte nicht gebuchter Pakete bleiben erhalten (auf der Seite nicht sichtbar)
        DELETE FROM ally_nutzer_rechte WHERE matrix_user_id = ziel AND recht = 'admin' AND NOT (recht = ANY (neue_rechte));
        INSERT INTO ally_nutzer_rechte (matrix_user_id, recht) SELECT ziel, x FROM unnest(neue_rechte) AS x ON CONFLICT DO NOTHING;
        IF sa_neu AND NOT sa_alt THEN
          INSERT INTO ally_nutzer_rechte (matrix_user_id, recht) VALUES (ziel, 'superadmin') ON CONFLICT DO NOTHING;
        ELSIF sa_alt AND NOT sa_neu THEN
          DELETE FROM ally_nutzer_rechte WHERE matrix_user_id = ziel AND recht = 'superadmin';
        END IF;
        m := 'Rechte von ' || (SELECT name FROM ally_personen WHERE matrix_user_id = ziel) || ' gespeichert.'
          || CASE WHEN EXISTS (SELECT 1 FROM jsonb_object_keys(d) AS kq(feld) WHERE kq.feld LIKE 'recht\_\_%' AND kq.feld NOT IN ('recht__admin', 'recht__superadmin', 'recht__superadmin_feld'))
             THEN ' Weitere Rechte stehen in der Rolle oder unter „Eigene Rechte“ (Einstellungen › Team und Rollen).' ELSE '' END;
      END IF;

    ELSIF p_aktion = 'person_ally' THEN
      IF ziel = u THEN
        fehler := 'Du kannst dich nicht selbst deaktivieren.';
      -- Migration 172 (B8b, Fixieren): ist das Admin-Recht der Person fixiert, deaktiviert sie nur ein Superadmin
      ELSIF d->>'aktiv' IS DISTINCT FROM '1' AND ally_fix_person_geschuetzt(ziel, u) THEN
        fehler := 'Das Admin-Recht von ' || (SELECT name FROM ally_personen WHERE matrix_user_id = ziel) || ' ist fixiert. Deaktivieren kann sie nur ein Superadmin.';
      ELSE
        UPDATE ally_personen SET aktiv = (d->>'aktiv' = '1'), geaendert_am = now() WHERE matrix_user_id = ziel;
        IF d->>'aktiv' <> '1' THEN DELETE FROM ally_web_sitzungen WHERE matrix_user_id = ziel; END IF;
        m := CASE WHEN d->>'aktiv' = '1' THEN 'Person wieder aktiv: Chat und Oberfläche sind freigeschaltet.' ELSE 'Person deaktiviert: kein Chat mit ' || produkt_name() || ' und keine Anmeldung mehr. Rechte und Zuordnungen als Manager/in bleiben gespeichert.' END;
      END IF;

    ELSIF NOT EXISTS (SELECT 1 FROM ally_nutzer WHERE matrix_user_id = ziel) THEN
      fehler := 'Die Person ist deaktiviert. Bitte zuerst wieder aktivieren.';

    ELSIF p_aktion = 'person_daten' THEN
      -- Name und E-Mail-Adresse einer Person ändern (Admin); das Passwort bleibt gültig
      k := trim(coalesce(d->>'name', ''));
      em := nullif(lower(trim(coalesce(d->>'email', ''))), '');
      IF k = '' THEN
        fehler := 'Bitte einen Namen angeben.';
      ELSIF em IS NULL AND (SELECT pw_hash IS NOT NULL OR startcode_hash IS NOT NULL FROM ally_personen WHERE matrix_user_id = ziel) THEN
        fehler := 'Wer einen Zugang hat, braucht eine E-Mail-Adresse. Damit meldet sich die Person an.';
      ELSIF em IS NOT NULL AND em !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' THEN
        fehler := 'Bitte eine gültige E-Mail-Adresse angeben.';
      ELSIF em IS NOT NULL AND EXISTS (SELECT 1 FROM ally_personen WHERE email = em AND matrix_user_id <> ziel) THEN
        fehler := 'Diese E-Mail-Adresse gehört schon zu einer anderen Person.';
      ELSE
        UPDATE ally_personen SET name = k, email = em, geaendert_am = now() WHERE matrix_user_id = ziel;
        m := 'Angaben von ' || k || ' gespeichert.';
      END IF;

    ELSIF p_aktion = 'person_zugang' THEN
      -- Startcode erzeugen: Anmeldung mit der E-Mail-Adresse der Person und dem Startcode
      em := (SELECT email FROM ally_personen WHERE matrix_user_id = ziel);
      IF em IS NULL THEN
        fehler := 'Bitte zuerst eine E-Mail-Adresse für ' || (SELECT name FROM ally_personen WHERE matrix_user_id = ziel) || ' eintragen. Damit meldet sich die Person an.';
      ELSE
        code := ally_web_startcode();
        UPDATE ally_personen SET
          pw_hash = CASE WHEN matrix_user_id = u THEN pw_hash ELSE NULL END,
          pw_alt_name = CASE WHEN matrix_user_id = u THEN pw_alt_name ELSE NULL END,
          startcode_hash = crypt(ally_web_hash('ally-code:' || replace(code, '-', '')), gen_salt('bf', 10)), startcode_bis = now() + interval '7 days',
          fehlversuche = 0, gesperrt_bis = NULL, geaendert_am = now()
        WHERE matrix_user_id = ziel;
        IF ziel <> u THEN
          DELETE FROM ally_web_sitzungen WHERE matrix_user_id = ziel;
        END IF;
        m := 'Startcode für ' || (SELECT name FROM ally_personen WHERE matrix_user_id = ziel) || ': ' || code ||
             '. Anmeldung mit ' || em || ' und diesem Startcode als Passwort. Gültig 7 Tage, nur einmal verwendbar. Er wird nur jetzt angezeigt.';
      END IF;

    ELSE
      IF ziel = u THEN
        fehler := 'Du kannst deinen eigenen Zugang nicht sperren.';
      -- Migration 172 (B8b, Fixieren): ist das Admin-Recht der Person fixiert, sperrt ihren Zugang nur ein Superadmin
      ELSIF p_aktion = 'person_sperren' AND ally_fix_person_geschuetzt(ziel, u) THEN
        fehler := 'Das Admin-Recht von ' || (SELECT name FROM ally_personen WHERE matrix_user_id = ziel) || ' ist fixiert. Den Zugang sperren kann nur ein Superadmin.';
      ELSIF NOT EXISTS (SELECT 1 FROM ally_personen WHERE matrix_user_id = ziel AND (pw_hash IS NOT NULL OR startcode_hash IS NOT NULL)) THEN
        fehler := 'Die Person hat noch keinen Zugang.';
      ELSE
        UPDATE ally_personen SET zugang_aktiv = (p_aktion = 'person_freigeben'), geaendert_am = now() WHERE matrix_user_id = ziel;
        IF p_aktion = 'person_sperren' THEN DELETE FROM ally_web_sitzungen WHERE matrix_user_id = ziel; END IF;
        m := 'Zugang zur Oberfläche ' || CASE WHEN p_aktion = 'person_sperren' THEN 'gesperrt. Der Chat mit ' || produkt_name() || ' bleibt möglich.' ELSE 'freigeschaltet.' END;
      END IF;
    END IF;

  ELSIF p_aktion = 'cd' THEN
    -- Corporate Design eines Unternehmens: Schrift und Grundfarben (nur Admins)
    v := coalesce(d->>'id', '');
    k := trim(coalesce(d->>'schrift', ''));
    IF NOT ally_hat_recht(u, 'admin') THEN
      fehler := 'Unternehmensdaten ändern Admins.';
    ELSIF NOT plattform_cd_gebraucht() THEN
      fehler := 'Das Corporate Design wird erst mit einem Paket gebraucht, das Berichte oder Grafiken erstellt.';
    ELSIF NOT EXISTS (SELECT 1 FROM ally_unternehmen WHERE id::text = v AND geloescht_am IS NULL) THEN
      fehler := 'Unbekanntes Unternehmen.';
    ELSIF k !~ '^[A-Za-z0-9 ]{1,60}$' THEN
      fehler := 'Bitte die Schrift so angeben, wie sie bei Google Fonts heißt, z. B. Raleway oder Open Sans.';
    ELSIF EXISTS (SELECT 1 FROM unnest(ARRAY['farbe_dunkel', 'farbe_text_auf_dunkel', 'farbe_akzent', 'farbe_akzent_dunkel', 'farbe_hell', 'farbe_grau', 'farbe_warnung']) AS fx(x)
                  WHERE upper(coalesce(d->>fx.x, '')) !~ '^#[0-9A-F]{6}$') THEN
      fehler := 'Bitte alle Farben im Format #RRGGBB angeben, z. B. #171D23.';
    ELSE
      INSERT INTO ally_cd (unternehmen_id, schrift, farbe_dunkel, farbe_text_auf_dunkel, farbe_akzent, farbe_akzent_dunkel, farbe_hell, farbe_grau, farbe_warnung)
      VALUES (v::int, k, upper(d->>'farbe_dunkel'), upper(d->>'farbe_text_auf_dunkel'), upper(d->>'farbe_akzent'), upper(d->>'farbe_akzent_dunkel'),
              upper(d->>'farbe_hell'), upper(d->>'farbe_grau'), upper(d->>'farbe_warnung'))
      ON CONFLICT (unternehmen_id) DO UPDATE SET schrift = EXCLUDED.schrift, farbe_dunkel = EXCLUDED.farbe_dunkel,
        farbe_text_auf_dunkel = EXCLUDED.farbe_text_auf_dunkel, farbe_akzent = EXCLUDED.farbe_akzent, farbe_akzent_dunkel = EXCLUDED.farbe_akzent_dunkel,
        farbe_hell = EXCLUDED.farbe_hell, farbe_grau = EXCLUDED.farbe_grau, farbe_warnung = EXCLUDED.farbe_warnung, geaendert_am = now();
      m := 'Corporate Design von ' || (SELECT name FROM ally_unternehmen WHERE id::text = v) || ' gespeichert.';
    END IF;

  ELSIF p_aktion = 'cd_datei_loeschen' THEN
    -- Nur das Logo für helle Flächen ist freiwillig; die anderen Dateien lassen sich nur ersetzen
    v := coalesce(d->>'id', '');
    IF NOT ally_hat_recht(u, 'admin') THEN
      fehler := 'Unternehmensdaten ändern Admins.';
    ELSIF NOT plattform_cd_gebraucht() THEN
      fehler := 'Das Corporate Design wird erst mit einem Paket gebraucht, das Berichte oder Grafiken erstellt.';
    ELSIF EXISTS (SELECT 1 FROM ally_unternehmen ux WHERE ux.id::text = v AND ux.geloescht_am IS NOT NULL) THEN
      fehler := 'Das Unternehmen liegt im Papierkorb. Seine Dateien gehen erst beim endgültigen Löschen mit.';
    ELSIF coalesce(d->>'art', '') <> 'logo_fuer_hell' THEN
      fehler := 'Diese Datei wird gebraucht. Du kannst sie durch eine neue ersetzen, aber nicht entfernen.';
    ELSE
      DELETE FROM ally_cd_dateien WHERE unternehmen_id::text = v AND art = 'logo_fuer_hell';
      GET DIAGNOSTICS n = ROW_COUNT;
      IF n = 0 THEN fehler := 'Datei nicht gefunden.'; ELSE m := 'Logo für helle Flächen entfernt.'; END IF;
    END IF;

  ELSIF p_aktion = 'marketing' THEN
    -- Seite "Marketing": Wochentag und Uhrzeit der Themenvorschläge, Marketing-Profil (gilt nur für die Person selbst)
    IF NOT plattform_modul_an('marketing') THEN
      fehler := 'Das Paket Marketing ist nicht gebucht.';
    ELSIF ally_web_uhrzeit(d->>'marketing_uhrzeit') IS NULL THEN
      fehler := 'Bitte die Uhrzeit im Format HH:MM angeben.';
    ELSIF coalesce(d->>'marketing_tag', '') !~ '^[1-7]$' THEN
      fehler := 'Bitte einen Wochentag wählen.';
    ELSE
      PERFORM ally_web_wert_setzen(u, 'marketing_tag', d->>'marketing_tag');
      PERFORM ally_web_wert_setzen(u, 'marketing_uhrzeit', ally_web_uhrzeit(d->>'marketing_uhrzeit'));
      PERFORM ally_web_wert_setzen(u, 'marketing_profil', trim(coalesce(d->>'marketing_profil', '')));
      m := 'Marketing-Einstellungen gespeichert.';
    END IF;

  ELSIF p_aktion = 'cd_gestaltung' THEN
    -- Gestaltung der Marketing-Grafiken eines Unternehmens: Folienstile, Akzente, Icons (nur Admins)
    v := coalesce(d->>'id', '');
    IF NOT ally_hat_recht(u, 'admin') THEN
      fehler := 'Unternehmensdaten ändern Admins.';
    ELSIF NOT plattform_modul_an('marketing') THEN
      fehler := 'Das Paket Marketing ist nicht gebucht.';
    ELSIF NOT EXISTS (SELECT 1 FROM ally_cd cx JOIN ally_unternehmen ux ON ux.id = cx.unternehmen_id WHERE cx.unternehmen_id::text = v AND ux.geloescht_am IS NULL) THEN
      fehler := 'Bitte zuerst Schrift und Farben für dieses Unternehmen speichern.';
    ELSIF coalesce(jsonb_typeof(d->'stile'), '') <> 'array'
          OR (NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(d->'stile') AS st(x) WHERE st.x IN ('dunkel', 'hell', 'akzent'))
              AND NOT EXISTS (SELECT 1 FROM marketing_hintergruende hx WHERE hx.unternehmen_id::text = v)) THEN
      fehler := 'Bitte mindestens einen Folienstil auswählen oder einen eigenen Hintergrund hochladen.';
    ELSE
      UPDATE ally_cd SET
        stile = ARRAY(SELECT st.x FROM unnest(ARRAY['dunkel', 'hell', 'akzent']) WITH ORDINALITY AS st(x, nr) WHERE d->'stile' ? st.x ORDER BY st.nr),
        deko_punkte = d ? 'punkte', deko_boegen = d ? 'boegen', deko_icon = d ? 'gross_icon', icons_an = d ? 'icons',
        icons_aus = CASE WHEN coalesce(jsonb_typeof(d->'icons_liste'), '') = 'array'
                         THEN ARRAY(SELECT ic.name FROM ally_icons ic WHERE NOT (d->'icons_liste' ? ic.name) ORDER BY ic.name) ELSE icons_aus END,
        geaendert_am = now()
      WHERE unternehmen_id::text = v;
      m := 'Gestaltung der Marketing-Grafiken von ' || (SELECT name FROM ally_unternehmen WHERE id::text = v) || ' gespeichert.';
    END IF;

  ELSIF p_aktion = 'hintergrund_loeschen' THEN
    -- Eigenen Hintergrund der Marketing-Grafiken entfernen (Recht „Postfächer verwalten“); ohne Hintergrund und ohne Folienstil gelten wieder alle Stile
    v := coalesce(d->>'bild', '');
    IF NOT ally_hat_recht(u, 'admin') THEN
      fehler := 'Unternehmensdaten ändern Admins.';
    ELSIF v !~ '^[0-9]{1,9}$' THEN
      fehler := 'Hintergrund nicht gefunden.';
    ELSIF EXISTS (SELECT 1 FROM marketing_hintergruende hx JOIN ally_unternehmen ux ON ux.id = hx.unternehmen_id WHERE hx.id = v::int AND ux.geloescht_am IS NOT NULL) THEN
      fehler := 'Das Unternehmen liegt im Papierkorb. Seine Dateien gehen erst beim endgültigen Löschen mit.';
    ELSE
      DELETE FROM marketing_hintergruende WHERE id = v::int RETURNING unternehmen_id::text INTO k;
      IF k IS NULL THEN
        fehler := 'Hintergrund nicht gefunden.';
      ELSE
        UPDATE ally_cd SET stile = ARRAY['dunkel', 'hell', 'akzent'], geaendert_am = now()
        WHERE unternehmen_id::text = k AND cardinality(stile) = 0 AND NOT EXISTS (SELECT 1 FROM marketing_hintergruende hx WHERE hx.unternehmen_id::text = k);
        m := 'Hintergrund entfernt.';
      END IF;
    END IF;

  ELSIF p_aktion = 'startseite' THEN
    -- Reihenfolge und Sichtbarkeit der Kacheln auf der Startseite (gilt nur für die Person selbst; "Einstellungen" bleibt immer sichtbar)
    IF coalesce(jsonb_typeof(d->'reihenfolge'), '') <> 'array' OR coalesce(jsonb_typeof(d->'aus'), '') <> 'array' THEN
      fehler := 'Die Startseite konnte nicht gespeichert werden. Bitte die Seite neu laden.';
    ELSIF jsonb_array_length(d->'reihenfolge') > 20 OR jsonb_array_length(d->'aus') > 20
          OR EXISTS (SELECT 1 FROM jsonb_array_elements(d->'reihenfolge') AS ka(x) WHERE jsonb_typeof(ka.x) <> 'string' OR ka.x #>> '{}' !~ '^[a-z_]{1,30}$')
          OR EXISTS (SELECT 1 FROM jsonb_array_elements(d->'aus') AS ka(x) WHERE jsonb_typeof(ka.x) <> 'string' OR ka.x #>> '{}' !~ '^[a-z_]{1,30}$' OR ka.x #>> '{}' = 'einstellungen') THEN
      fehler := 'Die Startseite konnte nicht gespeichert werden. Bitte die Seite neu laden.';
    ELSE
      PERFORM ally_web_wert_setzen(u, 'kacheln', jsonb_build_object('reihenfolge', d->'reihenfolge', 'aus', d->'aus')::text);
      m := 'Startseite gespeichert.';
    END IF;

  ELSIF p_aktion = 'ki_hinweis' THEN
    -- KI-Hinweis "Erstellt mit KI-Unterstützung." in Mail-Entwürfen bzw. Marketing-Texten, gilt für alle (Stefan 17.10.2026). Ändern nur Admins.
    v := coalesce(d->>'art', '');
    IF NOT ally_hat_recht(u, 'admin') THEN
      fehler := 'Den KI-Hinweis ändern Admins.';
    ELSIF v NOT IN ('mail', 'marketing', 'system') THEN  -- Migration 96: auch Systemnachrichten (ohne Paket)
      fehler := 'Unbekannte Aktion.';
    ELSIF v <> 'system' AND NOT plattform_modul_an(CASE WHEN v = 'mail' THEN 'mail_entwuerfe' ELSE 'marketing' END) THEN
      fehler := 'Dieses Paket ist nicht gebucht.';
    ELSE
      INSERT INTO ally_einstellungen (schluessel, wert, geaendert_am) VALUES ('ki_hinweis_' || v, CASE WHEN d ? 'an' THEN 'an' ELSE 'aus' END, now())
      ON CONFLICT (schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
      m := 'KI-Hinweis ' || CASE WHEN v = 'mail' THEN 'in Mail-Entwürfen ' WHEN v = 'system' THEN 'in Systemnachrichten ' ELSE 'in Marketing-Texten ' END || CASE WHEN d ? 'an' THEN 'eingeschaltet.' ELSE 'ausgeschaltet.' END;
    END IF;

  ELSIF p_aktion = 'paket_fuer_mich' THEN
    -- Seite eines Pakets, Teil "Für mich": Schalter der Funktionen dieses Pakets und persönliche Werte (gilt nur für die Person selbst).
    -- "grundpaket" steht für die Benachrichtigungen des Grundpakets (Einstellungen).
    v := coalesce(d->>'paket', '');
    IF NOT (v = 'grundpaket' OR (EXISTS (SELECT 1 FROM plattform_module WHERE schluessel = v) AND plattform_modul_an(v))) THEN
      fehler := 'Dieses Paket ist nicht gebucht.';
    ELSIF (d ? 'briefing_uhrzeit' AND ally_web_uhrzeit(d->>'briefing_uhrzeit') IS NULL) OR (d ? 'marketing_uhrzeit' AND ally_web_uhrzeit(d->>'marketing_uhrzeit') IS NULL) THEN
      fehler := 'Bitte die Uhrzeit im Format HH:MM angeben.';
    ELSIF d ? 'marketing_tag' AND coalesce(d->>'marketing_tag', '') !~ '^[1-7]$' THEN
      fehler := 'Bitte einen Wochentag wählen.';
    ELSIF coalesce(d->>'standard_postfach', '') <> '' AND NOT ally_postfach_zustaendig(u, d->>'standard_postfach') THEN
      fehler := 'Als Standard-Postfach geht nur ein Postfach, das du siehst.';
    ELSIF d ? 'marketing_anzahl' AND coalesce(d->>'marketing_anzahl', '') !~ '^[1-5]$' THEN
      fehler := 'Bitte als Anzahl der Vorschläge 1 bis 5 wählen.';
    ELSIF d ? 'marketing_ansprache' AND coalesce(d->>'marketing_ansprache', '') NOT IN ('du', 'sie') THEN
      fehler := 'Bitte als Ansprache Du oder Sie wählen.';
    ELSIF (d ? 'absender_name' AND trim(coalesce(d->>'absender_name', '')) = '') OR (d ? 'signatur_name' AND trim(coalesce(d->>'signatur_name', '')) = '') THEN
      fehler := 'Absendername und Name in der Signatur dürfen nicht leer sein.';
    ELSE
      FOR f IN
        SELECT fx.schluessel FROM ally_funktionen fx
        WHERE CASE WHEN v = 'grundpaket' THEN fx.modul IS NULL OR fx.modul IN (SELECT pm.schluessel FROM plattform_module pm WHERE pm.grundpaket) ELSE fx.modul = v END
          AND (fx.schluessel <> 'systemfehler_meldung' OR ally_hat_recht(u, 'admin'))
          AND (fx.schluessel NOT LIKE 'mail_rueckfrage_%'
           OR EXISTS (SELECT 1 FROM ally_postfaecher p WHERE p.schalter = fx.schluessel AND ally_postfach_zustaendig(u, p.adresse)))
      LOOP
        IF d ? ('sichtbar__' || f.schluessel) THEN
          INSERT INTO ally_nutzer_funktionen (matrix_user_id, schluessel, aktiv) VALUES (u, f.schluessel, d ? ('an__' || f.schluessel))
          ON CONFLICT (matrix_user_id, schluessel) DO UPDATE SET aktiv = EXCLUDED.aktiv, geaendert_am = now()
          WHERE ally_nutzer_funktionen.aktiv IS DISTINCT FROM EXCLUDED.aktiv;
        END IF;
      END LOOP;
      IF d ? 'briefing_uhrzeit' THEN PERFORM ally_web_wert_setzen(u, 'briefing_uhrzeit', ally_web_uhrzeit(d->>'briefing_uhrzeit')); END IF;
      IF d ? 'kalender_id' THEN PERFORM ally_web_wert_setzen(u, 'kalender_id', trim(coalesce(d->>'kalender_id', ''))); END IF;
      IF d ? 'standard_postfach' THEN PERFORM ally_web_wert_setzen(u, 'standard_postfach', lower(trim(coalesce(d->>'standard_postfach', '')))); END IF;
      IF d ? 'absender_name' THEN PERFORM ally_web_wert_setzen(u, 'absender_name', trim(d->>'absender_name')); END IF;
      IF d ? 'signatur_name' THEN PERFORM ally_web_wert_setzen(u, 'signatur_name', trim(d->>'signatur_name')); END IF;
      IF d ? 'marketing_tag' THEN PERFORM ally_web_wert_setzen(u, 'marketing_tag', d->>'marketing_tag'); END IF;
      IF d ? 'marketing_uhrzeit' THEN PERFORM ally_web_wert_setzen(u, 'marketing_uhrzeit', ally_web_uhrzeit(d->>'marketing_uhrzeit')); END IF;
      IF d ? 'marketing_profil' THEN PERFORM ally_web_wert_setzen(u, 'marketing_profil', trim(coalesce(d->>'marketing_profil', ''))); END IF;
      IF d ? 'marketing_anzahl' THEN PERFORM ally_web_wert_setzen(u, 'marketing_anzahl', d->>'marketing_anzahl'); END IF;
      IF d ? 'marketing_ansprache' THEN PERFORM ally_web_wert_setzen(u, 'marketing_ansprache', d->>'marketing_ansprache'); END IF;
      FOREACH k IN ARRAY ARRAY['marketing_themenfelder', 'marketing_zielgruppe', 'marketing_stil', 'marketing_nogos'] LOOP
        IF d ? k THEN PERFORM ally_web_wert_setzen(u, k, left(trim(coalesce(d->>k, '')), 2000)); END IF;
      END LOOP;
      m := CASE WHEN v = 'grundpaket' THEN 'Benachrichtigungen gespeichert.'
                ELSE 'Einstellungen für ' || (SELECT name FROM plattform_module WHERE schluessel = v) || ' gespeichert.' END;
    END IF;

  ELSE
    fehler := 'Unbekannte Aktion.';
  END IF;

  UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
  -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung, die Änderungen dieser Aktion sind zurückgenommen
EXCEPTION WHEN SQLSTATE 'AT002' THEN
  RETURN ally_fix_meldung(p_token, SQLERRM);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_arbeit(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  u text;
  heute text := to_char(now() AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD');
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN NULL;
  END IF;
  u := s.matrix_user_id;
  RETURN jsonb_build_object(
    'belege', CASE WHEN plattform_modul_an('belege') THEN jsonb_build_object(
      'neu', (SELECT count(*) FROM beleg_verarbeitung WHERE processing_status = 'neu'),
      'klaerungen', (SELECT count(*) FROM klaerungsfaelle WHERE status = 'offen'),
      'fehler', (SELECT count(*) FROM beleg_verarbeitung WHERE processing_status = 'fehler'),
      'laeuft', EXISTS (SELECT 1 FROM ally_einstellungen WHERE schluessel = 'web_start_belege' AND geaendert_am > now() - interval '10 minutes')) END,
    'abgleich', CASE WHEN plattform_modul_an('zeiterfassung') THEN jsonb_build_object(
      'zuletzt', (SELECT wert FROM ally_einstellungen WHERE schluessel = 'sync5_letzter_erfolg'),
      'alt', coalesce((SELECT geaendert_am < now() - interval '26 hours' FROM ally_einstellungen WHERE schluessel = 'sync5_letzter_erfolg'), true),
      'laeuft', EXISTS (SELECT 1 FROM ally_einstellungen WHERE schluessel = 'web_start_abgleich' AND geaendert_am > now() - interval '10 minutes')) END,
    'marketing', CASE WHEN plattform_modul_an('marketing') THEN jsonb_build_object(
      'themen', coalesce((SELECT jsonb_agg(jsonb_build_object('id', t.id, 'titel', t.titel) ORDER BY t.id DESC)
        FROM (SELECT id, titel FROM marketing_themen WHERE matrix_user_id = u AND status = 'vorschlag' ORDER BY id DESC LIMIT 20) t), '[]'::jsonb),
      'in_arbeit', (SELECT count(*) FROM marketing_themen WHERE matrix_user_id = u AND status = 'in_arbeit'),
      'entwurf', (SELECT count(*) FROM marketing_themen WHERE matrix_user_id = u AND status = 'entwurf'),
      'fertig', (SELECT count(*) FROM marketing_themen WHERE matrix_user_id = u AND status = 'fertig'),
      'geplant', (SELECT count(*) FROM marketing_posts WHERE matrix_user_id = u AND status = 'freigegeben'),
      'laeuft', EXISTS (SELECT 1 FROM ally_nutzer_einstellungen WHERE matrix_user_id = u AND schluessel = 'web_start_themen' AND geaendert_am > now() - interval '3 minutes')) END,
    'kunden', CASE WHEN plattform_modul_an('kundenueberblick') THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id', k.papierkram_id, 'name', k.name) ORDER BY lower(k.name))
      FROM (SELECT papierkram_id, split_part(last_synced_hash, '|', 1) AS name FROM sync_mapping WHERE entity_type = 'customer' AND status = 'active') k
      WHERE k.name <> ''), '[]'::jsonb) END,
    'briefing', CASE WHEN plattform_modul_an('morgen_briefing') THEN jsonb_build_object(
      'an', ally_funktion_an(u, 'morgen_briefing'),
      'uhrzeit', coalesce(ally_nutzer_wert(u, 'briefing_uhrzeit'), '05:00'),
      'heute', coalesce(ally_nutzer_wert(u, 'briefing_letzter_versand'), '') = heute,
      'laeuft', EXISTS (SELECT 1 FROM ally_nutzer_einstellungen WHERE matrix_user_id = u AND schluessel = 'web_start_briefing' AND geaendert_am > now() - interval '3 minutes')) END,
    'mails', jsonb_build_object(
      'entwuerfe', plattform_modul_an('mail_entwuerfe'),
      'angebote', CASE WHEN plattform_modul_an('mail_entwuerfe') THEN (SELECT count(*) FROM mail_rueckfragen r2 WHERE r2.status = 'offen' AND r2.art = 'antwort'
        AND r2.erstellt_am > now() - interval '14 days' AND ally_postfach_zustaendig(u, r2.postfach)) END,
      'postfaecher', (SELECT count(*) FROM ally_postfaecher p2 WHERE ally_postfach_zustaendig(u, p2.adresse))),
    'kalender', jsonb_build_object('hinterlegt', coalesce(ally_nutzer_wert(u, 'kalender_id'), '') <> ''),
    'budgets', CASE WHEN EXISTS (SELECT 1 FROM ally_firma WHERE papierkram_subdomain ~ '^[a-z0-9-]+$') THEN jsonb_build_object('papierkram', true) END,
    'systemmails', jsonb_build_object('woche', (SELECT count(*) FROM mail_klassifizierung_log l WHERE l.kategorie_key = 'system_report' AND l.created_at > now() - interval '7 days'
      AND (ally_postfach_zustaendig(u, l.postfach) OR (l.postfach IS NULL AND ally_hat_recht(u, 'admin'))))),
    'fragen', jsonb_build_object('chat', EXISTS (SELECT 1 FROM ally_berechtigungen b WHERE b.matrix_user_id = u AND b.aktiv)
      AND EXISTS (SELECT 1 FROM ally_nutzer n WHERE n.matrix_user_id = u AND coalesce(n.room_id, '') <> ''))
  );
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_cd_datei(p_token text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  v text := coalesce(d->>'id', '');
  w_art text := coalesce(d->>'art', '');
  b64 text := coalesce(d->>'b64', '');
  roh bytea;
  txt text;
  w_mime text;
  fehler text := NULL;
  m text := NULL;
  namen jsonb := '{"logo_fuer_dunkel": "Logo für dunkle Flächen", "logo_fuer_hell": "Logo für helle Flächen", "bildmarke_fuer_dunkel": "Bildmarke für dunkle Flächen", "bildmarke_fuer_hell": "Bildmarke für helle Flächen"}'::jsonb;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  IF NOT ally_hat_recht(s.matrix_user_id, 'admin') THEN
    fehler := 'Unternehmensdaten ändern Admins.';
  ELSIF NOT plattform_cd_gebraucht() THEN
    fehler := 'Das Corporate Design wird erst mit einem Paket gebraucht, das Berichte oder Grafiken erstellt.';
  ELSIF NOT EXISTS (SELECT 1 FROM ally_unternehmen WHERE id::text = v AND geloescht_am IS NULL) THEN
    fehler := 'Unbekanntes Unternehmen.';
  ELSIF NOT EXISTS (SELECT 1 FROM ally_cd WHERE unternehmen_id::text = v) THEN
    fehler := 'Bitte zuerst Schrift und Farben für dieses Unternehmen speichern.';
  ELSIF NOT namen ? w_art THEN
    fehler := 'Unbekannte Datei.';
  ELSIF b64 = '' THEN
    fehler := 'Bitte eine Datei auswählen.';
  ELSIF b64 !~ '^[A-Za-z0-9+/]+={0,2}$' THEN
    fehler := 'Die Datei konnte nicht gelesen werden.';
  ELSE
    roh := decode(b64, 'base64');
    IF length(roh) > 512000 THEN
      fehler := 'Die Datei ist zu groß. Erlaubt sind höchstens 500 KB.';
    ELSIF substring(roh FROM 1 FOR 8) = '\x89504e470d0a1a0a'::bytea THEN
      w_mime := 'image/png';
    ELSE
      BEGIN
        txt := convert_from(roh, 'UTF8');
      EXCEPTION WHEN others THEN
        txt := NULL;
      END;
      IF txt IS NULL OR txt !~* '<svg[[:space:]>]' THEN
        fehler := 'Bitte eine SVG- oder PNG-Datei hochladen.';
      ELSIF txt ~* '<script|javascript:|<foreignobject|<iframe|<embed|<object|[[:space:]"''/]on[a-z]+[[:space:]]*=' THEN
        fehler := 'Diese SVG-Datei enthält Skripte oder eingebettete Inhalte und wird deshalb nicht angenommen. Bitte die Datei ohne Skripte exportieren.';
      ELSE
        w_mime := 'image/svg+xml';
      END IF;
    END IF;
  END IF;
  IF fehler IS NULL THEN
    INSERT INTO ally_cd_dateien (unternehmen_id, art, mime, daten, dateiname, groesse)
    VALUES (v::int, w_art, w_mime, b64, coalesce(nullif(left(regexp_replace(coalesce(d->>'name', ''), '[^[:alnum:] ._()-]', '', 'g'), 120), ''), w_art), length(roh))
    ON CONFLICT (unternehmen_id, art) DO UPDATE SET mime = EXCLUDED.mime, daten = EXCLUDED.daten, dateiname = EXCLUDED.dateiname,
      groesse = EXCLUDED.groesse, geaendert_am = now();
    m := (namen->>w_art) || ' für ' || (SELECT name FROM ally_unternehmen WHERE id::text = v) || ' gespeichert.';
  END IF;
  UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_code_pruefen(p_code text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(
    (SELECT jsonb_build_object('gueltig', true, 'name', p.name, 'email', p.email) FROM ally_personen p
     WHERE coalesce(p_code, '') ~ '^[0-9a-f]{64}$' AND p.ruecksetz_hash = ally_web_hash(p_code) AND p.ruecksetz_bis > now() AND p.aktiv AND p.zugang_aktiv),
    jsonb_build_object('gueltig', false))
$function$
;

CREATE OR REPLACE FUNCTION public.ally_web_daten(p_user text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
  SELECT jsonb_build_object(
    'funktionen', coalesce((SELECT jsonb_agg(jsonb_build_object('schluessel', f.schluessel, 'name', f.name, 'beschreibung', f.beschreibung,
        'modul', f.modul, 'an', ally_funktion_an(p_user, f.schluessel)) ORDER BY f.sortierung, f.name)
      FROM ally_funktionen f
      WHERE (f.schluessel <> 'systemfehler_meldung' OR ally_hat_recht(p_user, 'admin'))
         AND (f.modul IS NULL OR plattform_modul_an(f.modul))
         AND (f.schluessel NOT LIKE 'mail_rueckfrage_%'
         OR EXISTS (SELECT 1 FROM ally_postfaecher p WHERE p.schalter = f.schluessel AND ally_postfach_zustaendig(p_user, p.adresse)))), '[]'::jsonb),
    'einstellungen', jsonb_build_object(
      'briefing_uhrzeit', coalesce(ally_nutzer_wert(p_user, 'briefing_uhrzeit'), '05:00'),
      'kalender_id', coalesce(ally_nutzer_wert(p_user, 'kalender_id'), ''),
      'standard_postfach', coalesce(ally_nutzer_wert(p_user, 'standard_postfach'), ''),
      'marketing_tag', coalesce(ally_nutzer_wert(p_user, 'marketing_tag'), '1'),
      'marketing_uhrzeit', coalesce(ally_nutzer_wert(p_user, 'marketing_uhrzeit'), '08:00'),
      'marketing_profil', coalesce(ally_nutzer_wert(p_user, 'marketing_profil'), ''),
      'marketing_anzahl', coalesce(ally_nutzer_wert(p_user, 'marketing_anzahl'), '3'),
      'marketing_ansprache', coalesce(ally_nutzer_wert(p_user, 'marketing_ansprache'), 'du'),
      'marketing_themenfelder', coalesce(ally_nutzer_wert(p_user, 'marketing_themenfelder'), ''),
      'marketing_zielgruppe', coalesce(ally_nutzer_wert(p_user, 'marketing_zielgruppe'), ''),
      'marketing_stil', coalesce(ally_nutzer_wert(p_user, 'marketing_stil'), ''),
      'marketing_nogos', coalesce(ally_nutzer_wert(p_user, 'marketing_nogos'), ''),
      'kacheln', coalesce(ally_nutzer_wert(p_user, 'kacheln'), ''),
      'absender_name', coalesce((SELECT wert FROM ally_nutzer_einstellungen WHERE matrix_user_id = p_user AND schluessel = 'absender_name'), (SELECT anzeigename FROM ally_nutzer WHERE matrix_user_id = p_user), ''),
      'signatur_name', coalesce((SELECT wert FROM ally_nutzer_einstellungen WHERE matrix_user_id = p_user AND schluessel = 'signatur_name'), (SELECT split_part(anzeigename, ' ', 1) FROM ally_nutzer WHERE matrix_user_id = p_user), '')),
    -- Migration 90: persönliche Postfächer anderer nur für Admins und nur mit Adresse, Person und Platz (keine Einstellungen, keine Inhalte)
    'postfaecher', coalesce((SELECT jsonb_agg(CASE WHEN p.art = 'persoenlich' AND p.eigentuemer IS DISTINCT FROM p_user THEN jsonb_build_object('adresse', p.adresse, 'aktiv', p.aktiv,
        'art', p.art, 'eigentuemer', p.eigentuemer, 'eigentuemer_name', (SELECT x.name FROM ally_personen x WHERE x.matrix_user_id = p.eigentuemer), 'eigen', false, 'verwalten', false,
        'zustaendig', false, 'platz', (SELECT pp.platz FROM postfach_plaetze pp WHERE pp.adresse = p.adresse))
      ELSE jsonb_build_object('adresse', p.adresse, 'name', p.name, 'aktiv', p.aktiv,
        'art', p.art, 'eigentuemer', p.eigentuemer, 'eigen', p.eigentuemer IS NOT DISTINCT FROM p_user AND p.art = 'persoenlich', 'verwalten', ally_postfach_verwalten_darf(p_user, p.adresse),
        'zustaendig', ally_postfach_zustaendig(p_user, p.adresse),
        'personen', CASE WHEN ally_postfach_verwalten_darf(p_user, p.adresse) THEN coalesce((SELECT jsonb_agg(np.matrix_user_id ORDER BY np.matrix_user_id) FROM ally_nutzer_postfaecher np WHERE np.postfach = p.adresse), '[]'::jsonb) END,
        'entwurf_ordner', CASE WHEN ally_postfach_verwalten_darf(p_user, p.adresse) THEN p.entwurf_ordner END,
        'signatur_html', CASE WHEN ally_postfach_verwalten_darf(p_user, p.adresse) THEN p.signatur_html END,
        'schrift', p.schrift, 'schrift_groesse', p.schrift_groesse,
        'angebot_bei', to_jsonb(p.angebot_bei), 'eigene_einordnung', p.eigene_einordnung,
        'einordnung', CASE WHEN ally_postfach_verwalten_darf(p_user, p.adresse) THEN p.einordnung END,
        'unternehmen_id', p.unternehmen_id, 'unternehmen', (SELECT ux.name FROM ally_unternehmen ux WHERE ux.id = p.unternehmen_id),
        'platz', (SELECT pp.platz FROM postfach_plaetze pp WHERE pp.adresse = p.adresse),
        'belege_erfassen', (SELECT pp.belege_erfassen FROM postfach_plaetze pp WHERE pp.adresse = p.adresse),
        'zugang', CASE WHEN ally_postfach_verwalten_darf(p_user, p.adresse) THEN (SELECT jsonb_build_object('host', pp.imap_host, 'port', pp.imap_port, 'benutzer', pp.imap_benutzer,
          'ssl', pp.imap_ssl, 'eingerichtet', pp.eingerichtet, 'ergebnis', pp.pruef_ergebnis,
          'geprueft', to_char(pp.letzte_pruefung AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI'),
          'ordner', pp.ordner, 'ordner_stand', to_char(pp.ordner_stand AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI')) FROM postfach_plaetze pp WHERE pp.adresse = p.adresse) END) END ORDER BY p.sortierung, p.adresse)
      FROM ally_postfaecher p WHERE p.art = 'gemeinsam' OR p.eigentuemer = p_user OR ally_hat_recht(p_user, 'admin')), '[]'::jsonb),
    'mail_schriften', (SELECT jsonb_agg(jsonb_build_object('schluessel', s.schluessel, 'name', s.name, 'stapel', s.stapel) ORDER BY s.sortierung) FROM mail_schriften s),
    'plaetze_frei', CASE WHEN ally_hat_recht(p_user, 'postfaecher') OR ally_hat_recht(p_user, 'postfaecher_eigene') THEN CASE WHEN postfach_hoechstzahl_erreicht() THEN '[]'::jsonb ELSE '[0]'::jsonb END END,  -- Migration 173 (Schritt P, P3): 0 = neues Postfach mit eigener Nummer
    -- Migration 170 (Schritt P): ab der Höchstzahl keine freien Plätze, dazu das Kennzeichen für den Hinweis
    'postfaecher_hoechstzahl_erreicht', CASE WHEN ally_hat_recht(p_user, 'postfaecher') OR ally_hat_recht(p_user, 'postfaecher_eigene') THEN postfach_hoechstzahl_erreicht() END,
    'unternehmen', CASE WHEN ally_hat_recht(p_user, 'postfaecher') OR ally_hat_recht(p_user, 'postfaecher_eigene') THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', ux.id, 'name', ux.name, 'eigen', EXISTS (SELECT 1 FROM ally_firma firma_x WHERE firma_x.unternehmen_id = ux.id), 'cd', cd_seite(ux.id),
        'inhaber', ux.inhaber, 'ort', ux.ort, 'website', ux.website, 'leistungen', ux.leistungen,
        'postfaecher', (SELECT coalesce(jsonb_agg(px.adresse ORDER BY px.adresse), '[]'::jsonb) FROM ally_postfaecher px WHERE px.unternehmen_id = ux.id AND (px.art = 'gemeinsam' OR px.eigentuemer = p_user)))
        ORDER BY lower(ux.name)), '[]'::jsonb) FROM ally_unternehmen ux WHERE ux.geloescht_am IS NULL) END,
    -- Migration 129: Papierkorb der Unternehmen (nur Admins)
    'unternehmen_papierkorb', CASE WHEN ally_hat_recht(p_user, 'admin') THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', ux.id, 'name', ux.name, 'ort', ux.ort,
        'geloescht', to_char(ux.geloescht_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI'),
        'von', coalesce((SELECT nx.anzeigename FROM ally_nutzer nx WHERE nx.matrix_user_id = ux.geloescht_von), ux.geloescht_von),
        'cd', EXISTS (SELECT 1 FROM ally_cd cx WHERE cx.unternehmen_id = ux.id),
        'dateien', (SELECT count(*) FROM ally_cd_dateien cf WHERE cf.unternehmen_id = ux.id) + (SELECT count(*) FROM marketing_hintergruende hx WHERE hx.unternehmen_id = ux.id))
        ORDER BY ux.geloescht_am DESC, ux.id DESC), '[]'::jsonb) FROM ally_unternehmen ux WHERE ux.geloescht_am IS NOT NULL) END,
    'plaetze_live', postfach_plaetze_live(),
    'paket', (SELECT paket FROM plattform_vertrag WHERE id = 1),
    'pakete', (SELECT coalesce(jsonb_agg(jsonb_build_object('schluessel', m.schluessel, 'name', m.name, 'beschreibung', m.beschreibung,
        'grundpaket', m.grundpaket, 'braucht_cd', m.braucht_cd, 'gebucht', plattform_modul_an(m.schluessel)) ORDER BY m.sortierung), '[]'::jsonb) FROM plattform_module m),
    'regeln', coalesce((SELECT jsonb_agg(jsonb_build_object('muster', r.muster, 'kategorie', r.kategorie_key, 'notiz', r.notiz, 'quelle', r.quelle,
        'postfach', r.postfach, 'datum', to_char(r.updated_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY')) ORDER BY r.muster, r.postfach NULLS FIRST)
      FROM mail_absender_regeln r), '[]'::jsonb),
    -- Migration 128: Papierkorb der Absender-Regeln (nur mit dem Recht; Regeln persönlicher Postfächer anderer Personen nicht)
    'regeln_papierkorb', CASE WHEN ally_hat_recht(p_user, 'absender_regeln') THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id', k.id, 'muster', k.muster,
        'kategorie', k.kategorie_key, 'notiz', k.notiz, 'postfach', k.postfach, 'geloescht', to_char(k.geloescht_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI'),
        'von', coalesce((SELECT nx.anzeigename FROM ally_nutzer nx WHERE nx.matrix_user_id = k.geloescht_von), k.geloescht_von)) ORDER BY k.geloescht_am DESC, k.id DESC)
      FROM mail_absender_regeln_papierkorb k
      WHERE NOT EXISTS (SELECT 1 FROM ally_postfaecher px WHERE lower(px.adresse) = lower(k.postfach) AND px.art = 'persoenlich' AND px.eigentuemer IS DISTINCT FROM p_user)), '[]'::jsonb) END,
    'mail_kategorien', (SELECT coalesce(jsonb_object_agg(k.kategorie_key, jsonb_build_object('aktion', k.aktion, 'ziel_ordner', k.ziel_ordner)), '{}'::jsonb) FROM mail_kategorien k WHERE k.aktiv),
    'rechte_liste', (SELECT jsonb_agg(jsonb_build_object('schluessel', r.schluessel, 'name', r.name, 'beschreibung', r.beschreibung) ORDER BY r.sortierung) FROM ally_rechte r WHERE r.je_person AND (r.modul IS NULL OR plattform_modul_an(r.modul)) AND ally_postfach_platz_recht(r.schluessel) IS NULL
      -- Superadmin (Stefan 18.10.2026): nur für Superadmins wählbar
      AND (r.schluessel <> 'superadmin' OR ally_hat_recht(p_user, 'superadmin'))),
    'aktive_personen', CASE WHEN ally_hat_recht(p_user, 'postfaecher') THEN
      (SELECT coalesce(jsonb_agg(jsonb_build_object('id', n.matrix_user_id, 'name', n.anzeigename) ORDER BY n.anzeigename), '[]'::jsonb) FROM ally_nutzer n) END,
    'personen', CASE WHEN ally_hat_recht(p_user, 'admin') THEN coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', p.matrix_user_id, 'name', p.name, 'email', p.email, 'ally_aktiv', p.aktiv,
        -- Migration 158 (Bauplan B3a): bei Talent-Personen gilt der Talent-Zugang (Einladungslink statt Startcode).
        'hat_zugang', p.pw_hash IS NOT NULL OR p.startcode_hash IS NOT NULL
          OR (ally_rolle_ist_talent(p.rolle) AND EXISTS (SELECT 1 FROM talent_zugaenge tz WHERE tz.talent_id = p.talent_id AND tz.einladung_hash IS NOT NULL)), 'zugang_aktiv', p.zugang_aktiv,
        'passwort_gesetzt', p.pw_hash IS NOT NULL, 'startcode_offen', (p.startcode_hash IS NOT NULL AND p.startcode_bis > now())
          OR (ally_rolle_ist_talent(p.rolle) AND EXISTS (SELECT 1 FROM talent_zugaenge tz WHERE tz.talent_id = p.talent_id AND tz.einladung_hash IS NOT NULL AND tz.einladung_bis > now())),
        'letzte_anmeldung', to_char(p.letzte_anmeldung AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI'),
        'rechte', (SELECT coalesce(jsonb_agg(r.recht), '[]'::jsonb) FROM ally_nutzer_rechte r WHERE r.matrix_user_id = p.matrix_user_id),
        -- Superadmin (Stefan 18.10.2026): Kennzeichen; geschuetzt = nur ein Superadmin darf an dieser Person etwas ändern
        'superadmin', ally_person_superadmin(p.matrix_user_id),
        -- Migration 168 (Bauplan B7): G1, Häkchen Superadmin nur für Personen aus der Liste (ein bestehendes Recht lässt sich immer abgeben)
        'superadmin_moeglich', ally_superadmin_erlaubt(p.matrix_user_id) OR ally_person_superadmin(p.matrix_user_id),
        'geschuetzt', ally_person_superadmin(p.matrix_user_id) AND NOT ally_hat_recht(p_user, 'superadmin'),
        -- Chat mit dem Assistenten eingerichtet (Direktraum vorhanden), Spalte "Chat" in Personen und Rechte (Stefan 19.10.2026)
        'chat', EXISTS (SELECT 1 FROM matrix_direct_rooms dr WHERE dr.matrix_user_id = p.matrix_user_id),
        -- Rolle und Chat-Benutzer (nur Anzeige) für Team und Rollen (Stefan 19.10.2026)
        'rolle', p.rolle, 'rolle_name', (SELECT ro.name FROM ally_rollen ro WHERE ro.schluessel = p.rolle),
        -- Migration 158 (Bauplan B3a): Talent-Personen (Rolle „Talent“) stehen in der Liste; ihr Fenster zeigt nur Angaben (talent_id), kein Chat-Konto.
        'chat_benutzer', CASE WHEN ally_rolle_ist_talent(p.rolle) THEN NULL ELSE p.matrix_user_id END, 'talent_id', CASE WHEN ally_rolle_ist_talent(p.rolle) THEN p.talent_id END,
        'chat_deaktiviert', EXISTS (SELECT 1 FROM ally_chat_kennungen ck WHERE ck.matrix_user_id = p.matrix_user_id AND ck.deaktiviert_am IS NOT NULL))
        ORDER BY p.aktiv DESC, p.name)
      FROM ally_personen p), '[]'::jsonb) END,
    'rollen', CASE WHEN ally_hat_recht(p_user, 'admin') THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('schluessel', ro.schluessel, 'name', ro.name,
        'beschreibung', ro.beschreibung, 'fuer_personen', ro.fuer_personen) ORDER BY ro.sortierung), '[]'::jsonb) FROM ally_rollen ro) END,
    -- Migration 168 (Bauplan B7): F14, die Liste der Chat-Aufträge nur für Superadmins (das Feld Chat-Konto im Person-Fenster bleibt für Admins)
    'chat_auftraege', CASE WHEN ally_hat_recht(p_user, 'superadmin') THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'art', x.art,
        'matrix_user_id', x.matrix_user_id, 'name', x.anzeigename, 'status', x.status, 'meldung', x.meldung,
        'erstellt', to_char(x.erstellt_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI')) ORDER BY x.id DESC), '[]'::jsonb)
      FROM (SELECT * FROM ally_chat_auftraege a WHERE a.art <> 'passwort' ORDER BY a.id DESC LIMIT 20) x) END,
    'ki', CASE WHEN ally_hat_recht(p_user, 'admin') THEN jsonb_build_object(
      'stand', ki_monat_stand(),
      'funktionen', ki_monat_funktionen(),
      -- (Stefan 18.10.2026) Beträge sind Kundenpreise; schluessel 'kunde' = eigener Anthropic-Schlüssel, Verbrauch nur zur Information
      'schluessel', (SELECT ki_schluessel FROM plattform_vertrag WHERE id = 1),
      'intern', CASE WHEN ally_hat_recht(p_user, 'superadmin') THEN ki_monat_intern() END,
      'paket', (SELECT paket FROM plattform_vertrag WHERE id = 1),
      'budget_modus', (SELECT budget_modus FROM plattform_vertrag WHERE id = 1),
      'seit', (SELECT to_char(min(zeit) AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY') FROM ki_verbrauch),
      'kurs', (SELECT usd_eur FROM plattform_vertrag WHERE id = 1),
      'kurs_stand', (SELECT to_char(wert::date, 'DD.MM.YYYY') FROM ally_einstellungen WHERE schluessel = 'kurs_usd_eur_stand' AND wert ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) END,
    'ki_hinweis', jsonb_build_object(
      'mail', coalesce((SELECT wert FROM ally_einstellungen WHERE schluessel = 'ki_hinweis_mail'), 'aus') = 'an',
      'marketing', coalesce((SELECT wert FROM ally_einstellungen WHERE schluessel = 'ki_hinweis_marketing'), 'aus') = 'an'),
    'instagram', CASE WHEN ally_hat_recht(p_user, 'instagram') THEN jsonb_build_object(
      'konto', nullif(ally_einstellung('instagram_username'), ''),
      'seit', nullif(ally_einstellung('instagram_token_datum'), '')) END,
    'papierkram', CASE WHEN ally_hat_recht(p_user, 'admin') THEN jsonb_build_object(
      'subdomain', (SELECT papierkram_subdomain FROM ally_firma WHERE id = 1),
      'geprueft_am', (SELECT to_char(wert::timestamptz AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI') FROM ally_einstellungen
        WHERE schluessel = 'papierkram_geprueft' AND wert ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T]')) END
  )
$function$
;

CREATE OR REPLACE FUNCTION public.ally_web_hash(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT encode(digest(p, 'sha256'), 'hex') $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_hintergrund(p_token text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  v text := coalesce(d->>'id', '');
  b64 text := coalesce(d->>'b64', '');
  w_vorschau text := coalesce(d->>'vorschau', '');
  roh bytea;
  w_mime text;
  fehler text := NULL;
  m text := NULL;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  IF NOT ally_hat_recht(s.matrix_user_id, 'admin') THEN
    fehler := 'Unternehmensdaten ändern Admins.';
  ELSIF NOT plattform_modul_an('marketing') THEN
    fehler := 'Das Paket Marketing ist nicht gebucht.';
  ELSIF NOT EXISTS (SELECT 1 FROM ally_cd cx JOIN ally_unternehmen ux ON ux.id = cx.unternehmen_id WHERE cx.unternehmen_id::text = v AND ux.geloescht_am IS NULL) THEN
    fehler := 'Bitte zuerst Schrift und Farben für dieses Unternehmen speichern.';
  ELSIF coalesce(d->>'helligkeit', '') NOT IN ('hell', 'dunkel') THEN
    fehler := 'Bitte angeben, ob das Bild hell oder dunkel ist.';
  ELSIF (SELECT count(*) FROM marketing_hintergruende WHERE unternehmen_id::text = v) >= 6 THEN
    fehler := 'Es sind höchstens 6 eigene Hintergründe möglich. Bitte zuerst einen entfernen.';
  ELSIF b64 = '' THEN
    fehler := 'Bitte eine Datei auswählen.';
  ELSIF b64 !~ '^[A-Za-z0-9+/]+={0,2}$' THEN
    fehler := 'Die Datei konnte nicht gelesen werden.';
  ELSE
    roh := decode(b64, 'base64');
    IF length(roh) > 1048576 THEN
      fehler := 'Das Bild ist zu groß. Erlaubt ist höchstens 1 MB.';
    ELSIF substring(roh FROM 1 FOR 8) = '\x89504e470d0a1a0a'::bytea THEN
      w_mime := 'image/png';
    ELSIF substring(roh FROM 1 FOR 3) = '\xffd8ff'::bytea THEN
      w_mime := 'image/jpeg';
    ELSE
      fehler := 'Bitte ein JPG- oder PNG-Bild hochladen.';
    END IF;
  END IF;
  IF fehler IS NULL THEN
    INSERT INTO marketing_hintergruende (unternehmen_id, hell, mime, daten, vorschau, dateiname, groesse)
    VALUES (v::int, d->>'helligkeit' = 'hell', w_mime, b64,
      CASE WHEN length(w_vorschau) <= 60000 AND w_vorschau ~ '^data:image/jpeg;base64,[A-Za-z0-9+/]+={0,2}$' THEN w_vorschau END,
      coalesce(nullif(left(regexp_replace(coalesce(d->>'name', ''), '[^[:alnum:] ._()-]', '', 'g'), 120), ''), 'Hintergrund'), length(roh));
    m := 'Hintergrund für ' || (SELECT name FROM ally_unternehmen WHERE id::text = v) || ' gespeichert.';
  END IF;
  UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_login(p_login text, p_hash_alt text, p_hash text, p_hash_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  z ally_personen%ROWTYPE;
  v text := lower(trim(coalesce(p_login, '')));
  per_start boolean := false;
  umstellen boolean := false;
  t text;
  fl text := NULL;
BEGIN
  -- Anmeldung mit E-Mail-Adresse; der bisherige Benutzername gilt nur noch bis zur Umstellung
  SELECT * INTO z FROM ally_personen WHERE v <> '' AND (email = v OR benutzername = v) ORDER BY (email = v) DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND OR NOT z.zugang_aktiv OR NOT z.aktiv OR NOT EXISTS (SELECT 1 FROM ally_nutzer n WHERE n.matrix_user_id = z.matrix_user_id) THEN
    PERFORM pg_sleep(0.3);
    RETURN jsonb_build_object('ok', false, 'code', 'falsch');
  END IF;
  IF z.gesperrt_bis IS NOT NULL AND z.gesperrt_bis > now() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'gesperrt');
  END IF;
  IF z.pw_hash IS NOT NULL AND z.pw_alt_name IS NULL AND coalesce(p_hash, '') ~ '^[0-9a-f]{64}$' AND z.pw_hash = crypt(p_hash, z.pw_hash) THEN
    per_start := false;
  ELSIF z.pw_hash IS NOT NULL AND z.pw_alt_name IS NOT NULL AND v = z.pw_alt_name
        AND coalesce(p_hash_alt, '') ~ '^[0-9a-f]{64}$' AND z.pw_hash = crypt(p_hash_alt, z.pw_hash) THEN
    per_start := false;
    umstellen := coalesce(p_hash, '') ~ '^[0-9a-f]{64}$';
  ELSIF z.startcode_hash IS NOT NULL AND z.startcode_bis > now()
        AND coalesce(p_hash_code, '') ~ '^[0-9a-f]{64}$' AND z.startcode_hash = crypt(p_hash_code, z.startcode_hash) THEN
    per_start := true;
  ELSE
    UPDATE ally_personen SET
      fehlversuche = CASE WHEN fehlversuche + 1 >= 5 THEN 0 ELSE fehlversuche + 1 END,
      gesperrt_bis = CASE WHEN fehlversuche + 1 >= 5 THEN now() + interval '15 minutes' ELSE gesperrt_bis END
    WHERE matrix_user_id = z.matrix_user_id;
    RETURN jsonb_build_object('ok', false, 'code', CASE WHEN z.fehlversuche + 1 >= 5 THEN 'gesperrt' ELSE 'falsch' END);
  END IF;
  IF umstellen THEN
    -- Passwort aufs neue Verfahren umstellen (der Browser hat beide Prüfsummen geschickt)
    UPDATE ally_personen SET pw_hash = crypt(p_hash, gen_salt('bf', 12)), pw_alt_name = NULL,
      benutzername = CASE WHEN email IS NOT NULL THEN NULL ELSE benutzername END, geaendert_am = now()
    WHERE matrix_user_id = z.matrix_user_id;
    fl := CASE WHEN z.email IS NOT NULL THEN 'Ab jetzt meldest du dich mit deiner E-Mail-Adresse ' || z.email || ' an. Dein Passwort bleibt gleich.'
               ELSE 'Bitte trage unter Einstellungen › Profil deine E-Mail-Adresse ein. Damit meldest du dich künftig an.' END;
  END IF;
  t := encode(gen_random_bytes(32), 'hex');
  INSERT INTO ally_web_sitzungen (token_hash, matrix_user_id, muss_pw_setzen, ablauf, flash, flash_art)
  VALUES (ally_web_hash(t), z.matrix_user_id, per_start, CASE WHEN per_start THEN now() + interval '30 minutes' ELSE now() + interval '30 days' END,
          fl, CASE WHEN fl IS NOT NULL THEN 'ok' END);
  UPDATE ally_personen SET fehlversuche = 0, gesperrt_bis = NULL, letzte_anmeldung = now() WHERE matrix_user_id = z.matrix_user_id;
  DELETE FROM ally_web_sitzungen WHERE ablauf < now();
  RETURN jsonb_build_object('ok', true, 'token', t, 'muss_pw_setzen', per_start, 'max_age', CASE WHEN per_start THEN 1800 ELSE 2592000 END,
    'ziel', CASE WHEN umstellen AND z.email IS NULL THEN 'profil' ELSE '' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_meldung(p_token text, p_text text, p_art text, p_ergebnis jsonb)
 RETURNS jsonb
 LANGUAGE sql
AS $function$
  UPDATE ally_web_sitzungen SET flash = left(coalesce(p_text, ''), 2000), flash_art = CASE WHEN p_art = 'ok' THEN 'ok' ELSE 'fehler' END, ergebnis = p_ergebnis
  WHERE token_hash = ally_web_hash(coalesce(p_token, '')) AND coalesce(p_token, '') <> ''
    AND NOT ally_person_ist_talent(matrix_user_id)  -- Migration 160 (Bauplan B4a): Sitzungen von Talent-Personen sind keine Team-Sitzungen
  RETURNING jsonb_build_object('ok', p_art = 'ok', 'angemeldet', true)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_web_passwort_neu(p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  z ally_personen%ROWTYPE;
  pw text := coalesce(d->>'neu', '');
  t text;
BEGIN
  SELECT * INTO z FROM ally_personen WHERE coalesce(d->>'code', '') ~ '^[0-9a-f]{64}$' AND ruecksetz_hash = ally_web_hash(d->>'code')
    AND ruecksetz_bis > now() AND aktiv AND zugang_aktiv FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'link');
  END IF;
  IF pw !~ '^[0-9a-f]{64}$' OR coalesce(d->>'laenge', '0') !~ '^[0-9]+$' OR (d->>'laenge')::int < 10 OR pw <> coalesce(d->>'wiederholung', '') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'passwort');
  END IF;
  UPDATE ally_personen SET pw_hash = crypt(pw, gen_salt('bf', 12)), pw_alt_name = NULL,
    benutzername = CASE WHEN email IS NOT NULL THEN NULL ELSE benutzername END,
    startcode_hash = NULL, startcode_bis = NULL, ruecksetz_hash = NULL, ruecksetz_bis = NULL,
    fehlversuche = 0, gesperrt_bis = NULL, letzte_anmeldung = now(), geaendert_am = now()
  WHERE matrix_user_id = z.matrix_user_id;
  DELETE FROM ally_web_sitzungen WHERE matrix_user_id = z.matrix_user_id OR ablauf < now();
  t := encode(gen_random_bytes(32), 'hex');
  INSERT INTO ally_web_sitzungen (token_hash, matrix_user_id, muss_pw_setzen, ablauf, flash, flash_art)
  VALUES (ally_web_hash(t), z.matrix_user_id, false, now() + interval '30 days', 'Neues Passwort gespeichert. Du bist angemeldet.', 'ok');
  RETURN jsonb_build_object('ok', true, 'token', t, 'max_age', 2592000);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_recht_pruefen(p_token text, p_recht text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  IF NOT ally_hat_recht(s.matrix_user_id, p_recht) THEN
    UPDATE ally_web_sitzungen SET flash = 'Dafür fehlt dir das Recht. Rechte vergibt eine Person mit der Rolle Admin.', flash_art = 'fehler'
    WHERE token_hash = s.token_hash;
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'nutzer', s.matrix_user_id);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_rechte(p_user text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Rechte der Person für die alte Oberfläche (ALLY 8): nur die Rechte, die es dort gibt (je_person, Migration 64)
  SELECT coalesce(jsonb_agg(r.schluessel ORDER BY r.sortierung), '[]'::jsonb)
  FROM ally_rechte r WHERE r.je_person AND ally_hat_recht(p_user, r.schluessel)
$function$
;

CREATE OR REPLACE FUNCTION public.ally_web_seite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  fl text; fa text; er jsonb;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('angemeldet', false);
  END IF;
  SELECT x.flash, x.flash_art, x.ergebnis INTO fl, fa, er FROM ally_web_sitzungen x WHERE x.token_hash = s.token_hash FOR UPDATE;
  UPDATE ally_web_sitzungen x SET letzte_nutzung = now(), flash = NULL, flash_art = NULL, ergebnis = NULL WHERE x.token_hash = s.token_hash;
  RETURN jsonb_build_object('angemeldet', true, 'muss_pw_setzen', s.muss_pw_setzen,
    'nutzer', jsonb_build_object('id', s.matrix_user_id, 'name', s.anzeigename, 'email', s.email, 'rechte', ally_web_rechte(s.matrix_user_id)),
    'hinweis', fl, 'hinweis_art', fa, 'ergebnis', er,
    'daten', CASE WHEN s.muss_pw_setzen THEN NULL ELSE ally_web_daten(s.matrix_user_id) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_sitzung_pruefen(p_token text)
 RETURNS TABLE(token_hash text, matrix_user_id text, muss_pw_setzen boolean, anzeigename text, benutzername text, email text)
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 172 (B8b, Fixieren): merkt sich für diese Transaktion, wer handelt (ally.handelnd); sonst unverändert
  SELECT s.token_hash, set_config('ally.handelnd', s.matrix_user_id, true), s.muss_pw_setzen, p.name, p.benutzername, p.email
  FROM ally_web_sitzungen s
  -- Migration 160 (Bauplan B4a): Sitzungen von Talent-Personen gelten nur als Talent-Sitzung (talent_web_sitzung), nie als Sitzung einer Team-Person.
  JOIN ally_personen p ON p.matrix_user_id = s.matrix_user_id AND p.zugang_aktiv AND p.aktiv AND NOT ally_person_ist_talent(p.matrix_user_id)
  WHERE s.token_hash = ally_web_hash(coalesce(p_token, '')) AND coalesce(p_token, '') <> '' AND s.ablauf > now()
$function$
;

CREATE OR REPLACE FUNCTION public.ally_web_start(p_token text, p_was text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  u text;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  paket text;
  fehler text := NULL;
  m text := NULL;
  thema record;
  thema_nr integer := NULL;
  kunde text := NULL;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := s.matrix_user_id;
  paket := CASE p_was WHEN 'belege' THEN 'belege' WHEN 'abgleich' THEN 'zeiterfassung' WHEN 'themen' THEN 'marketing'
    WHEN 'beitrag' THEN 'marketing' WHEN 'kundenueberblick' THEN 'kundenueberblick' WHEN 'briefing' THEN 'morgen_briefing' END;

  IF paket IS NULL THEN
    fehler := 'Unbekannte Aktion.';
  ELSIF NOT plattform_modul_an(paket) THEN
    fehler := 'Dieses Paket ist nicht gebucht.';

  ELSIF p_was = 'belege' THEN
    IF EXISTS (SELECT 1 FROM ally_einstellungen WHERE schluessel = 'web_start_belege' AND geaendert_am > now() - interval '10 minutes') THEN
      fehler := 'Die Belege werden gerade schon verbucht. Bitte in ein paar Minuten wieder schauen.';
    ELSIF NOT EXISTS (SELECT 1 FROM beleg_verarbeitung WHERE processing_status = 'neu') THEN
      fehler := 'Es gibt gerade keine neuen Belege zum Verbuchen.';
    ELSE
      INSERT INTO ally_einstellungen (schluessel, wert, geaendert_am) VALUES ('web_start_belege', u, now())
      ON CONFLICT (schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
      m := '' || produkt_name() || ' verbucht die neuen Belege jetzt. Das dauert ein bis mehrere Minuten. Klärungen kommen wie gewohnt in den Chat.';
    END IF;

  ELSIF p_was = 'abgleich' THEN
    IF EXISTS (SELECT 1 FROM ally_einstellungen WHERE schluessel = 'web_start_abgleich' AND geaendert_am > now() - interval '10 minutes') THEN
      fehler := 'Der Abgleich läuft gerade schon. Bitte in ein paar Minuten wieder schauen.';
    ELSE
      INSERT INTO ally_einstellungen (schluessel, wert, geaendert_am) VALUES ('web_start_abgleich', u, now())
      ON CONFLICT (schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
      m := 'Der Abgleich von Papierkram und timeBuzzer läuft. Das dauert etwa eine Minute, danach steht hier der neue Stand.';
    END IF;

  ELSIF p_was IN ('themen', 'briefing') AND EXISTS (SELECT 1 FROM ally_nutzer_einstellungen
      WHERE matrix_user_id = u AND schluessel = 'web_start_' || p_was AND geaendert_am > now() - interval '3 minutes') THEN
    fehler := CASE WHEN p_was = 'themen' THEN 'Die Themenvorschläge sind schon unterwegs. Sie kommen gleich in den Chat.'
                   ELSE 'Das Briefing ist schon unterwegs. Es kommt gleich in den Chat.' END;

  ELSIF p_was = 'themen' THEN
    m := '' || produkt_name() || ' erstellt neue Themenvorschläge. Sie kommen in etwa einer halben Minute in den Chat.';

  ELSIF p_was = 'briefing' THEN
    IF NOT ally_funktion_an(u, 'morgen_briefing') THEN
      fehler := 'Das Morgen-Briefing ist für dich ausgeschaltet. Du schaltest es unter Einstellungen › Morgen-Briefing ein.';
    ELSE
      m := 'Dein Briefing kommt gleich in den Chat. Das geplante Briefing kommt trotzdem zur eingestellten Uhrzeit.';
    END IF;

  ELSIF p_was = 'beitrag' THEN
    SELECT id, titel, status INTO thema FROM marketing_themen
    WHERE id::text = coalesce(d->>'thema', '') AND matrix_user_id = u;
    IF NOT FOUND THEN
      fehler := 'Bitte ein Thema auswählen.';
    ELSIF thema.status <> 'vorschlag' THEN
      fehler := 'Zu diesem Thema gibt es schon einen Beitrag oder er wird gerade erstellt.';
    ELSE
      thema_nr := thema.id;
      m := '' || produkt_name() || ' erstellt den Beitrag „' || thema.titel || '“. Der Entwurf kommt in ein bis zwei Minuten in den Chat.';
    END IF;

  ELSIF p_was = 'kundenueberblick' THEN
    SELECT split_part(last_synced_hash, '|', 1) INTO kunde FROM sync_mapping
    WHERE entity_type = 'customer' AND status = 'active' AND papierkram_id = coalesce(d->>'kunde', '');
    IF kunde IS NULL OR kunde = '' THEN
      fehler := 'Bitte die Kundschaft auswählen.';
    END IF;
  END IF;

  -- Merken, damit ein zweiter Klick keinen zweiten Lauf startet (je Person)
  IF fehler IS NULL AND p_was IN ('themen', 'briefing') THEN
    INSERT INTO ally_nutzer_einstellungen (matrix_user_id, schluessel, wert, geaendert_am) VALUES (u, 'web_start_' || p_was, 'gestartet', now())
    ON CONFLICT (matrix_user_id, schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
  END IF;

  IF fehler IS NOT NULL OR m IS NOT NULL THEN
    UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END
    WHERE token_hash = s.token_hash;
  END IF;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'was', p_was, 'nutzer', u,
    'thema_id', thema_nr, 'kunde', kunde);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_startcode()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  z constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  b bytea := gen_random_bytes(12);
  s text := '';
BEGIN
  FOR i IN 0..11 LOOP
    s := s || substr(z, (get_byte(b, i) % 32) + 1, 1);
    IF i IN (3, 7) THEN s := s || '-'; END IF;
  END LOOP;
  RETURN s;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_uhrzeit(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN trim(coalesce(p, '')) ~ '^([01]?[0-9]|2[0-3]):[0-5][0-9]$'
    THEN to_char(make_time(split_part(trim(p), ':', 1)::int, (split_part(trim(p), ':', 2)::int / 15) * 15, 0), 'HH24:MI') END
$function$
;

CREATE OR REPLACE FUNCTION public.ally_web_vergessen(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  z ally_personen%ROWTYPE;
  v text := lower(trim(coalesce(p_email, '')));
  t text;
BEGIN
  SELECT * INTO z FROM ally_personen WHERE v <> '' AND email = v AND aktiv AND zugang_aktiv
    AND (pw_hash IS NOT NULL OR startcode_hash IS NOT NULL) FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM ally_nutzer n WHERE n.matrix_user_id = z.matrix_user_id) THEN
    PERFORM pg_sleep(0.3);
    RETURN jsonb_build_object('ok', true, 'senden', false);
  END IF;
  IF z.ruecksetz_bis IS NOT NULL AND z.ruecksetz_bis > now() + interval '50 minutes' THEN
    RETURN jsonb_build_object('ok', true, 'senden', false);
  END IF;
  t := encode(gen_random_bytes(32), 'hex');
  UPDATE ally_personen SET ruecksetz_hash = ally_web_hash(t), ruecksetz_bis = now() + interval '1 hour' WHERE matrix_user_id = z.matrix_user_id;
  RETURN jsonb_build_object('ok', true, 'senden', true, 'an', z.email, 'name', z.name, 'code', t);
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_web_wert_setzen(p_user text, p_schluessel text, p_wert text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF p_wert IS NULL OR trim(p_wert) = '' THEN
    DELETE FROM ally_nutzer_einstellungen WHERE matrix_user_id = p_user AND schluessel = p_schluessel;
  ELSE
    INSERT INTO ally_nutzer_einstellungen (matrix_user_id, schluessel, wert) VALUES (p_user, p_schluessel, p_wert)
    ON CONFLICT (matrix_user_id, schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
  END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.ally_webhook_aussen()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 190 (D.1): Pfad der außen eingetragenen Adressen (Einladung, OAuth-Rückwege, Meta, LinkedIn-Rückkehr), z. B. /webhook/web
  SELECT '/webhook/' || ally_webhook_praefix_aussen()
$function$
;

CREATE OR REPLACE FUNCTION public.ally_webhook_praefix_aussen()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 190 (D.1): Vorsatz der außen eingetragenen Adressen. Standard 'web'; eine Installation, deren Adressen schon in App-Konsolen stehen,
  -- setzt die Einstellung webhook_praefix_aussen (traefik leitet die alten Adressen dort auf /webhook/web weiter). Nur Kleinbuchstaben, Ziffern, Bindestrich.
  SELECT CASE WHEN btrim(ally_einstellung('webhook_praefix_aussen')) ~ '^[a-z0-9-]{1,40}$' THEN btrim(ally_einstellung('webhook_praefix_aussen')) ELSE 'web' END
$function$
;

CREATE OR REPLACE FUNCTION public.anbieter_name()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT btrim(ally_einstellung('anbieter_name'))
$function$
;

CREATE OR REPLACE FUNCTION public.arbeit_kanal_verbunden(p_user text, p_kanal text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE p_kanal
    WHEN 'instagram_post' THEN ally_token_vorhanden('instagram_token')
    WHEN 'instagram_story' THEN ally_token_vorhanden('instagram_token')
    WHEN 'linkedin_profil' THEN coalesce(ally_nutzer_wert(p_user, 'linkedin_konto'), '') <> ''
    WHEN 'linkedin_seite' THEN ally_token_vorhanden('linkedin_seite_token')
    ELSE false END;
$function$
;

CREATE OR REPLACE FUNCTION public.arbeit_web_abschluss(p_token text, p_r jsonb, p_erg jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  r jsonb := coalesce(p_r, '{}'::jsonb);
  e jsonb := coalesce(p_erg, '{}'::jsonb);
  ok boolean := coalesce((e->>'ok')::boolean, false);
  txt text := e->>'text';
  n int := 0;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF r->>'weiter' = 'loeschen' AND ok THEN
    DELETE FROM marketing_posts WHERE thema_id = (r->>'thema')::int AND matrix_user_id = s.matrix_user_id;
    DELETE FROM marketing_themen WHERE id = (r->>'thema')::int AND matrix_user_id = s.matrix_user_id AND status <> 'in_arbeit';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n = 0 THEN ok := false; txt := 'Das Thema konnte nicht gelöscht werden (' || produkt_name() || ' arbeitet gerade daran oder es ist schon weg).'; END IF;
  END IF;
  UPDATE ally_web_sitzungen SET flash = left(coalesce(txt, CASE WHEN ok THEN 'Erledigt.' ELSE 'Das hat nicht geklappt.' END), 2000),
    flash_art = CASE WHEN ok THEN 'ok' ELSE 'fehler' END, ergebnis = CASE WHEN jsonb_typeof(e->'ergebnis') = 'object' THEN e->'ergebnis' END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', ok, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.arbeit_web_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  u text;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  fehler text := NULL;
  m text := NULL;
  weiter text := NULL;
  aus jsonb := '{}'::jsonb;
  th record;
  mr record;
  kn text;
  fm text;
  zp timestamptz;
  n int;
  kan text[];
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := s.matrix_user_id;
  aus := jsonb_build_object('nutzer', u);

  -- Marketing-Beiträge
  IF p_aktion IN ('beitrag', 'freigeben', 'verwerfen', 'posten', 'stornieren', 'loeschen') AND NOT plattform_modul_an('marketing') THEN
    fehler := 'Das Paket Marketing ist nicht gebucht.';

  ELSIF p_aktion IN ('beitrag', 'freigeben', 'verwerfen', 'posten', 'loeschen') AND coalesce(d->>'thema', '') <> '' THEN
    SELECT * INTO th FROM marketing_themen WHERE id::text = d->>'thema' AND matrix_user_id = u;
    IF NOT FOUND THEN
      fehler := 'Dieses Thema gibt es nicht oder es gehört nicht dir.';
    ELSIF th.status = 'in_arbeit' THEN
      fehler := 'Zu „' || th.titel || '“ arbeitet ' || produkt_name() || ' gerade. Bitte warten, bis der Entwurf da ist.';
    ELSIF p_aktion = 'beitrag' THEN
      SELECT coalesce(array_agg(k ORDER BY k), '{}') INTO kan FROM jsonb_array_elements_text(coalesce(d->'kanaele', '[]'::jsonb)) k
        WHERE k IN ('instagram_post', 'instagram_story', 'linkedin', 'whatsapp');
      IF th.status IN ('vorschlag', 'verworfen') AND cardinality(kan) = 0 THEN
        fehler := 'Bitte mindestens einen Kanal wählen.';
      ELSIF th.status IN ('entwurf', 'fertig') AND cardinality(kan) = 0 AND trim(coalesce(d->>'hinweise', '')) = '' AND coalesce(d->>'entfernen', '') = '' THEN
        fehler := 'Bitte schreib, was ' || produkt_name() || ' ändern soll, oder wähle einen Kanal dazu.';
      ELSE
        weiter := 'marketing2';
        aus := aus || jsonb_build_object('modus', 'entwurf', 'thema_ids', th.id::text, 'freies_thema', '',
          'kanaele', array_to_string(kan || CASE WHEN coalesce(d->>'entfernen', '') <> '' THEN ARRAY(SELECT 'entfernen: ' || e FROM unnest(string_to_array(d->>'entfernen', ',')) e WHERE e IN ('instagram_post', 'instagram_story', 'linkedin', 'whatsapp')) ELSE '{}'::text[] END, ','),
          'story_modus', CASE WHEN d->>'story_modus' IN ('wie_beitrag', 'eigen') THEN d->>'story_modus' ELSE '' END,
          'hinweise', left(trim(coalesce(d->>'hinweise', '')), 3000));
        m := CASE WHEN th.status IN ('entwurf', 'fertig') THEN '' || produkt_name() || ' überarbeitet „' || th.titel || '“.' ELSE '' || produkt_name() || ' erstellt den Beitrag „' || th.titel || '“.' END ||
             ' Das dauert ein bis zwei Minuten. Der Entwurf kommt in den Chat und steht danach hier.';
      END IF;
    ELSIF p_aktion = 'freigeben' THEN
      IF th.status <> 'entwurf' THEN
        fehler := 'Freigeben geht nur bei einem Entwurf.';
      ELSE
        weiter := 'marketing2';
        aus := aus || jsonb_build_object('modus', 'final', 'thema_ids', th.id::text, 'titel', th.titel);
      END IF;
    ELSIF p_aktion = 'verwerfen' THEN
      IF th.status = 'verworfen' THEN
        fehler := '„' || th.titel || '“ ist schon verworfen.';
      ELSE
        weiter := 'marketing2';
        aus := aus || jsonb_build_object('modus', 'verwerfen', 'thema_ids', th.id::text, 'titel', th.titel);
      END IF;
    ELSIF p_aktion = 'loeschen' THEN
      -- Migration 133: in den Papierkorb (Ordner bleibt im Speicherort bis zum endgültigen Löschen; zurück und endgültig: marketing_papierkorb)
      -- G1: Thema und Posts zuerst sperren, dann den Stand erneut prüfen (MARKETING 2 bzw. 3/4 kommen nicht mehr dazwischen; 3/4 überspringen gesperrte Posts)
      PERFORM 1 FROM marketing_themen x WHERE x.id = th.id FOR UPDATE;
      PERFORM 1 FROM marketing_posts p WHERE p.thema_id = th.id FOR UPDATE;
      IF (SELECT x.status FROM marketing_themen x WHERE x.id = th.id) = 'in_arbeit' THEN
        fehler := 'Zu „' || th.titel || '“ arbeitet ' || produkt_name() || ' gerade. Bitte warten, bis der Entwurf da ist.';
      ELSIF EXISTS (SELECT 1 FROM marketing_posts p WHERE p.thema_id = th.id AND p.status = 'in_arbeit') THEN
        fehler := 'Ein Post zu „' || th.titel || '“ wird gerade veröffentlicht. Bitte kurz warten.';
      ELSE
        SELECT count(*) INTO n FROM marketing_posts p WHERE p.thema_id = th.id AND p.status = 'freigegeben';
        PERFORM marketing_pk_legen(th.id, u);
        m := '„' || th.titel || '“ liegt jetzt im Papierkorb'
          || CASE WHEN n = 1 THEN '; 1 geplanter Post wird nicht veröffentlicht' WHEN n > 1 THEN '; ' || n || ' geplante Posts werden nicht veröffentlicht' ELSE '' END
          || '. Im Papierkorb kannst du es wiederherstellen oder endgültig löschen.';
      END IF;
    ELSIF p_aktion = 'posten' THEN
      kn := CASE WHEN d->>'kanal' IN ('linkedin_profil', 'linkedin_seite', 'instagram_post', 'instagram_story') THEN d->>'kanal' END;
      fm := CASE WHEN kn = 'instagram_story' THEN 'story'
                 WHEN kn = 'instagram_post' THEN CASE WHEN d->>'format' = 'bild' THEN 'bild' ELSE 'karussell' END
                 WHEN d->>'format' IN ('pdf', 'bild', 'text') THEN d->>'format' ELSE 'pdf' END;
      BEGIN
        zp := CASE WHEN coalesce(d->>'zeitpunkt', '') = '' THEN now() ELSE (d->>'zeitpunkt')::timestamptz END;
      EXCEPTION WHEN others THEN zp := NULL;
      END;
      IF NOT plattform_modul_an('marketing_posten') THEN
        fehler := 'Das Paket Marketing veröffentlichen ist nicht gebucht.';
      ELSIF th.status <> 'fertig' OR th.ordner IS NULL THEN
        fehler := 'Posten geht nur bei einem freigegebenen Beitrag.';
      ELSIF kn IS NULL THEN
        fehler := 'Bitte einen Kanal wählen.';
      ELSIF NOT arbeit_kanal_verbunden(u, kn) THEN
        fehler := CASE WHEN kn LIKE 'instagram%' THEN 'Instagram ist nicht verbunden.' WHEN kn = 'linkedin_seite' THEN 'Die LinkedIn-Unternehmensseite ist nicht verbunden.'
                       ELSE 'Dein LinkedIn-Profil ist nicht verbunden.' END || ' Verbinden unter Einstellungen › Marketing.';
      ELSIF zp IS NULL OR zp < now() - interval '5 minutes' THEN
        fehler := 'Bitte einen Zeitpunkt in der Zukunft wählen oder das Feld leer lassen (sofort).';
      ELSIF zp > now() + interval '180 days' THEN
        fehler := 'Bitte einen Zeitpunkt in den nächsten 180 Tagen wählen.';
      ELSE
        INSERT INTO marketing_posts (thema_id, matrix_user_id, kanal, format, geplant_fuer) VALUES (th.id, u, kn, fm, greatest(zp, now()));
        m := '„' || th.titel || '“ ist eingeplant: ' || CASE kn WHEN 'linkedin_profil' THEN 'LinkedIn-Profil' WHEN 'linkedin_seite' THEN 'LinkedIn-Unternehmensseite'
             WHEN 'instagram_post' THEN 'Instagram-Beitrag' ELSE 'Instagram-Story' END || ', ' ||
             CASE WHEN zp <= now() + interval '1 minute' THEN 'sofort (innerhalb weniger Minuten)' ELSE arbeit_zeit(zp) || ' Uhr' END || '. Das Ergebnis kommt in den Chat.';
      END IF;
    END IF;

  ELSIF p_aktion = 'beitrag' AND trim(coalesce(d->>'freies_thema', '')) <> '' THEN
    SELECT coalesce(array_agg(k ORDER BY k), '{}') INTO kan FROM jsonb_array_elements_text(coalesce(d->'kanaele', '[]'::jsonb)) k
      WHERE k IN ('instagram_post', 'instagram_story', 'linkedin', 'whatsapp');
    IF cardinality(kan) = 0 THEN
      fehler := 'Bitte mindestens einen Kanal wählen.';
    ELSIF length(trim(d->>'freies_thema')) > 500 THEN
      fehler := 'Das Thema ist zu lang (höchstens 500 Zeichen).';
    ELSE
      weiter := 'marketing2';
      aus := aus || jsonb_build_object('modus', 'entwurf', 'thema_ids', '', 'freies_thema', trim(d->>'freies_thema'), 'kanaele', array_to_string(kan, ','),
        'story_modus', CASE WHEN d->>'story_modus' IN ('wie_beitrag', 'eigen') THEN d->>'story_modus' ELSE '' END,
        'hinweise', left(trim(coalesce(d->>'hinweise', '')), 3000));
      m := '' || produkt_name() || ' erstellt den Beitrag zu deinem Thema. Das dauert ein bis zwei Minuten. Der Entwurf kommt in den Chat und steht danach hier.';
    END IF;

  ELSIF p_aktion IN ('beitrag', 'freigeben', 'verwerfen', 'posten', 'loeschen') THEN
    fehler := CASE WHEN p_aktion = 'beitrag' THEN 'Bitte ein Thema wählen oder ein eigenes Thema eintragen.' ELSE 'Bitte ein Thema wählen.' END;

  ELSIF p_aktion = 'stornieren' THEN
    UPDATE marketing_posts SET status = 'storniert', geaendert_am = now()
    WHERE id::text = coalesce(d->>'post', '') AND matrix_user_id = u AND status = 'freigegeben';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n = 0 THEN fehler := 'Dieser Post ist nicht mehr geplant (schon veröffentlicht, in Arbeit oder storniert).';
    ELSE m := 'Geplanter Post storniert.'; END IF;

  -- Belege: Klärungsfall beantworten (BELEG 2)
  ELSIF p_aktion = 'klaerung' THEN
    IF NOT plattform_modul_an('belege') THEN
      fehler := 'Das Paket Belege ist nicht gebucht.';
    ELSIF NOT EXISTS (SELECT 1 FROM klaerungsfaelle WHERE id::text = coalesce(d->>'id', '') AND status = 'offen') THEN
      fehler := 'Diese Klärung ist nicht mehr offen.';
    ELSIF trim(coalesce(d->>'antwort', '')) = '' THEN
      fehler := 'Bitte eine Antwort eintragen.';
    ELSIF length(d->>'antwort') > 2000 THEN
      fehler := 'Die Antwort ist zu lang (höchstens 2000 Zeichen).';
    ELSE
      weiter := 'beleg2';
      aus := aus || jsonb_build_object('klaerungsfall_id', (d->>'id')::int, 'antwort_text', trim(d->>'antwort'));
    END IF;

  -- Mails: Antwortentwurf, kein Entwurf, neue Mail (ALLY 6)
  ELSIF p_aktion IN ('entwurf', 'ablehnen', 'neue_mail') AND NOT plattform_modul_an('mail_entwuerfe') THEN
    fehler := 'Das Paket Mail-Entwürfe ist nicht gebucht.';

  ELSIF p_aktion IN ('entwurf', 'ablehnen') THEN
    SELECT * INTO mr FROM mail_rueckfragen WHERE id::text = coalesce(d->>'id', '') AND art = 'antwort' AND ally_postfach_zustaendig(u, postfach);
    IF NOT FOUND THEN
      fehler := 'Diese Mail gibt es nicht oder du bist für ihr Postfach nicht zuständig.';
    ELSIF NOT ally_postfach_aktiv(mr.postfach) THEN
      fehler := 'Das Postfach ' || mr.postfach || ' ist pausiert.';
    ELSIF p_aktion = 'ablehnen' THEN
      IF mr.status <> 'offen' THEN
        fehler := 'Für diese Mail gibt es kein offenes Entwurfsangebot mehr.';
      ELSE
        UPDATE mail_rueckfragen SET status = 'abgelehnt', geaendert_am = now() WHERE id = mr.id;
        m := 'Kein Entwurf zu „' || coalesce(mr.betreff, 'ohne Betreff') || '“. Das Angebot ist erledigt.';
      END IF;
    ELSIF length(coalesce(d->>'anweisung', '')) > 3000 THEN
      fehler := 'Die Anweisung ist zu lang (höchstens 3000 Zeichen).';
    ELSE
      weiter := 'ally6';
      aus := aus || jsonb_build_object('mail_id', mr.id, 'anweisung', coalesce(nullif(trim(d->>'anweisung'), ''), 'ja'), 'postfach', '', 'an', '', 'an_name', '', 'betreff', '');
    END IF;

  ELSIF p_aktion = 'neue_mail' THEN
    IF NOT ally_postfach_zustaendig(u, lower(trim(coalesce(d->>'postfach', '')))) THEN
      fehler := 'Bitte ein Postfach wählen, für das du zuständig bist.';
    ELSIF trim(coalesce(d->>'betreff', '')) = '' OR trim(coalesce(d->>'anweisung', '')) = '' THEN
      fehler := 'Bitte Betreff und Inhalt angeben.';
    ELSIF trim(coalesce(d->>'an', '')) <> '' AND trim(d->>'an') !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' THEN
      fehler := 'Die Empfängeradresse ist ungültig.';
    ELSIF length(d->>'anweisung') > 3000 OR length(d->>'betreff') > 200 THEN
      fehler := 'Betreff oder Inhalt sind zu lang.';
    ELSE
      weiter := 'ally6';
      aus := aus || jsonb_build_object('mail_id', 0, 'anweisung', trim(d->>'anweisung'), 'postfach', lower(trim(d->>'postfach')), 'an', lower(trim(coalesce(d->>'an', ''))),
        'an_name', left(trim(coalesce(d->>'an_name', '')), 120), 'betreff', trim(d->>'betreff'));
    END IF;

  -- Kalender (Google Calendar)
  ELSIF p_aktion IN ('termin_neu', 'termin_aendern', 'termin_loeschen') THEN
    IF coalesce(ally_nutzer_wert(u, 'kalender_id'), '') = '' THEN
      fehler := 'Für dich ist kein Kalender hinterlegt (Einstellungen › Mein Kalender).';
    ELSIF p_aktion <> 'termin_neu' AND coalesce(d->>'termin', '') !~ '^[A-Za-z0-9_-]{1,200}$' THEN
      fehler := 'Unbekannter Termin.';
    ELSIF p_aktion <> 'termin_loeschen' AND trim(coalesce(d->>'titel', '')) = '' THEN
      fehler := 'Bitte einen Titel angeben.';
    ELSIF p_aktion <> 'termin_loeschen' AND (coalesce(d->>'start', '') = '' OR coalesce(d->>'ende', '') = '') THEN
      fehler := 'Bitte Beginn und Ende angeben.';
    ELSIF p_aktion <> 'termin_loeschen' AND (d->>'ende') < (d->>'start') THEN
      fehler := 'Das Ende liegt vor dem Beginn.';
    ELSE
      weiter := 'kalender';
      aus := aus || jsonb_build_object('art', p_aktion, 'kalender_id', ally_nutzer_wert(u, 'kalender_id'), 'termin', coalesce(d->>'termin', ''),
        'titel', left(trim(coalesce(d->>'titel', '')), 200), 'start', coalesce(d->>'start', ''), 'ende', coalesce(d->>'ende', ''),
        'ganztaegig', CASE WHEN d->>'ganztaegig' = '1' THEN 'yes' ELSE 'no' END,
        'ort', left(trim(coalesce(d->>'ort', '')), 200), 'beschreibung', left(trim(coalesce(d->>'beschreibung', '')), 2000));
    END IF;

  -- System-Mails: Zusammenfassung (ALLY 2)
  ELSIF p_aktion = 'systemmails' THEN
    weiter := 'ally2';
    aus := aus || jsonb_build_object('tage', CASE WHEN coalesce(d->>'tage', '') ~ '^[0-9]{1,2}$' THEN LEAST(GREATEST((d->>'tage')::int, 1), 30) ELSE 7 END);

  -- Ally fragen: Frage geht wie eine Chat-Nachricht an ALLY 1, die Antwort kommt in den Chat
  ELSIF p_aktion = 'fragen' THEN
    IF trim(coalesce(d->>'text', '')) = '' THEN
      fehler := 'Bitte eine Frage eintragen.';
    ELSIF length(d->>'text') > 2000 THEN
      fehler := 'Die Frage ist zu lang (höchstens 2000 Zeichen).';
    ELSIF ally_person_ist_testdaten(u) THEN
      fehler := 'Dies ist ein Test-Zugang (Testdaten). ' || produkt_name() || ' beantwortet hier keine Fragen, damit kein KI-Verbrauch entsteht.';
    ELSIF NOT EXISTS (SELECT 1 FROM ally_berechtigungen b WHERE b.matrix_user_id = u AND b.aktiv) THEN
      fehler := 'Du bist für den Chat mit ' || produkt_name() || ' nicht freigeschaltet.';
    ELSIF NOT EXISTS (SELECT 1 FROM ally_nutzer n WHERE n.matrix_user_id = u AND coalesce(n.room_id, '') <> '') THEN
      fehler := 'Es gibt noch keinen Chat zwischen dir und ' || produkt_name() || '. Schreib ' || produkt_name() || ' einmal im Chat an.';
    ELSE
      weiter := 'fragen';
      aus := aus || jsonb_build_object('room_id', (SELECT room_id FROM ally_nutzer WHERE matrix_user_id = u), 'text', trim(d->>'text'),
        'event_id', 'web-' || encode(gen_random_bytes(12), 'hex'));
    END IF;

  -- Google-Kalender der Person (Einstellungen › Mein Profil, wenn das Morgen-Briefing nicht gebucht ist)
  ELSIF p_aktion = 'kalender_einstellen' THEN
    IF length(trim(coalesce(d->>'kalender_id', ''))) > 200 OR trim(coalesce(d->>'kalender_id', '')) ~ '[[:space:]<>"]' THEN
      fehler := 'Bitte die Kalender-ID so angeben, wie sie in Google Kalender unter „Kalender integrieren“ steht.';
    ELSE
      PERFORM ally_web_wert_setzen(u, 'kalender_id', trim(coalesce(d->>'kalender_id', '')));
      m := CASE WHEN trim(coalesce(d->>'kalender_id', '')) = '' THEN 'Kalender entfernt.' ELSE 'Kalender gespeichert.' END;
    END IF;

  ELSE
    fehler := 'Unbekannte Aktion.';
  END IF;

  -- Meldung nur setzen, wenn kein weiterer Ablauf folgt (sonst setzt arbeit_web_abschluss die Meldung) oder bei Fehler
  IF fehler IS NOT NULL OR (weiter IS NULL AND m IS NOT NULL) THEN
    UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END
    WHERE token_hash = s.token_hash;
  END IF;
  RETURN aus || jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'aktion', p_aktion, 'weiter', CASE WHEN fehler IS NULL THEN weiter END, 'meldung', m);
END $function$
;

CREATE OR REPLACE FUNCTION public.arbeit_web_download(p_token text, p_thema text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  th record;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen OR NOT plattform_modul_an('marketing') THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  SELECT * INTO th FROM marketing_themen WHERE id::text = coalesce(p_thema, '') AND matrix_user_id = s.matrix_user_id AND ordner IS NOT NULL;
  IF NOT FOUND THEN
    UPDATE ally_web_sitzungen SET flash = 'Zu diesem Thema gibt es keine Dateien.', flash_art = 'fehler' WHERE token_hash = s.token_hash;
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'thema', th.id, 'titel', th.titel, 'ordner', th.ordner);
END $function$
;

CREATE OR REPLACE FUNCTION public.arbeit_web_download_fehler(p_token text, p_text text)
 RETURNS jsonb
 LANGUAGE sql
AS $function$
  UPDATE ally_web_sitzungen SET flash = left(coalesce(p_text, 'Der Download hat nicht geklappt.'), 500), flash_art = 'fehler'
  WHERE token_hash = ally_web_hash(coalesce(p_token, '')) AND coalesce(p_token, '') <> ''
    AND NOT ally_person_ist_talent(matrix_user_id)  -- Migration 160 (Bauplan B4a): Sitzungen von Talent-Personen sind keine Team-Sitzungen
  RETURNING jsonb_build_object('ok', false);
$function$
;

CREATE OR REPLACE FUNCTION public.arbeit_web_seite(p_token text, p_ansicht text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  u text;
  d jsonb := coalesce(p, '{}'::jsonb);
  tage int := CASE WHEN coalesce(d->>'tage', '') ~ '^[0-9]{1,2}$' THEN LEAST(GREATEST((d->>'tage')::int, 1), 30) ELSE 14 END;
  q text := left(trim(coalesce(d->>'q', '')), 100);
  th record;
  r jsonb;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN
    RETURN NULL;
  END IF;
  u := s.matrix_user_id;

  IF p_ansicht = 'beitrag' THEN
    IF NOT plattform_modul_an('marketing') THEN RETURN jsonb_build_object('gebucht', false); END IF;
    r := jsonb_build_object('gebucht', true,
      'posten', plattform_modul_an('marketing_posten'),
      'verbunden', jsonb_build_object('instagram', arbeit_kanal_verbunden(u, 'instagram_post'), 'linkedin_profil', arbeit_kanal_verbunden(u, 'linkedin_profil'),
                                      'linkedin_seite', arbeit_kanal_verbunden(u, 'linkedin_seite')),
      'laeuft_themen', EXISTS (SELECT 1 FROM ally_nutzer_einstellungen WHERE matrix_user_id = u AND schluessel = 'web_start_themen' AND geaendert_am > now() - interval '3 minutes'),
      'themen', coalesce((SELECT jsonb_agg(jsonb_build_object('id', t.id, 'titel', t.titel, 'status', t.status, 'dateien', t.ordner IS NOT NULL,
          'erstellt', to_char(t.erstellt_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY'), 'geaendert', arbeit_zeit(coalesce(t.geaendert_am, t.erstellt_am)),
          'quelle', t.quelle, 'kanaele', CASE WHEN jsonb_typeof(t.paket->'kanaele') = 'array' THEN t.paket->'kanaele' ELSE '[]'::jsonb END,
          'gepostet', (SELECT count(*) FROM marketing_posts mp WHERE mp.thema_id = t.id AND mp.status = 'gepostet'),
          'geplant', (SELECT count(*) FROM marketing_posts mp WHERE mp.thema_id = t.id AND mp.status IN ('freigegeben', 'in_arbeit')),
          -- Migration 133: genau die Posts, die „Verwerfen“ storniert (MARKETING 2: Status freigegeben)
          'verwerfen_storniert', (SELECT count(*) FROM marketing_posts mp WHERE mp.thema_id = t.id AND mp.status = 'freigegeben'))
        ORDER BY CASE t.status WHEN 'in_arbeit' THEN 0 WHEN 'entwurf' THEN 1 WHEN 'vorschlag' THEN 2 WHEN 'fertig' THEN 3 ELSE 4 END, coalesce(t.geaendert_am, t.erstellt_am) DESC)
        FROM marketing_themen t WHERE t.matrix_user_id = u), '[]'::jsonb),
      'posts', coalesce((SELECT jsonb_agg(jsonb_build_object('id', x.id, 'thema_id', x.thema_id, 'titel', x.titel, 'kanal', x.kanal, 'format', x.format, 'status', x.status,
          'zeit', arbeit_zeit(x.geplant_fuer), 'url', x.post_url, 'fehler', x.fehler) ORDER BY x.geplant_fuer DESC)
        FROM (SELECT mp.*, mt.titel FROM marketing_posts mp JOIN marketing_themen mt ON mt.id = mp.thema_id WHERE mp.matrix_user_id = u ORDER BY mp.geplant_fuer DESC LIMIT 100) x), '[]'::jsonb),
      'papierkorb', marketing_pk_liste(u));  -- Migration 133
    -- Einzelnes Thema (Ansicht mit Texten, Dateien und Posts)
    IF coalesce(d->>'thema', '') ~ '^[0-9]{1,9}$' THEN
      SELECT * INTO th FROM marketing_themen WHERE id = (d->>'thema')::int AND matrix_user_id = u;
      IF FOUND THEN
        r := r || jsonb_build_object('thema', jsonb_build_object('id', th.id, 'titel', th.titel, 'status', th.status, 'aufhaenger', th.aufhaenger, 'idee', th.idee, 'quelle', th.quelle,
          'erstellt', arbeit_zeit(th.erstellt_am), 'geaendert', arbeit_zeit(th.geaendert_am), 'dateien', th.ordner IS NOT NULL,
          'verwerfen_storniert', (SELECT count(*) FROM marketing_posts mp WHERE mp.thema_id = th.id AND mp.status = 'freigegeben'),  -- Migration 133
          'kanaele', CASE WHEN jsonb_typeof(th.paket->'kanaele') = 'array' THEN th.paket->'kanaele' ELSE '[]'::jsonb END,
          'story_modus', th.paket->>'story_modus',
          'texte', CASE WHEN jsonb_typeof(th.paket) = 'object' THEN jsonb_strip_nulls(jsonb_build_object(
             'linkedin_profil', nullif(th.paket->>'linkedin_profil', ''), 'linkedin_seite', nullif(th.paket->>'linkedin_seite', ''),
             'instagram_caption', nullif(th.paket->>'instagram_caption', ''),
             'instagram_hashtags', CASE WHEN jsonb_typeof(th.paket->'instagram_hashtags') = 'array' THEN (SELECT string_agg(h, ' ') FROM jsonb_array_elements_text(th.paket->'instagram_hashtags') h) END,
             'whatsapp_status', nullif(th.paket->>'whatsapp_status', ''),
             'pruefen', CASE WHEN jsonb_typeof(th.paket->'pruefen') = 'array' AND jsonb_array_length(th.paket->'pruefen') > 0 THEN th.paket->'pruefen' END)) END),
          'extern', CASE WHEN th.ordner IS NOT NULL THEN jsonb_build_object('ordner', th.ordner) END);
      END IF;
    END IF;
    RETURN r;

  ELSIF p_ansicht = 'belege_verbuchen' THEN
    IF NOT plattform_modul_an('belege') THEN RETURN jsonb_build_object('gebucht', false); END IF;
    RETURN jsonb_build_object('gebucht', true, 'klaerungen', coalesce((SELECT jsonb_agg(jsonb_build_object('id', kf.id, 'grund', kf.grund, 'text', kf.vorschlag_text,
        'absender', bv.sender, 'betreff', bv.subject, 'lieferant', bv.creditor_name_extrahiert, 'betrag', bv.betrag, 'datum', to_char(bv.rechnungsdatum, 'DD.MM.YYYY'),
        'seit', arbeit_zeit(kf.created_at AT TIME ZONE 'UTC')) ORDER BY kf.id)
      FROM klaerungsfaelle kf JOIN beleg_verarbeitung bv ON bv.id = kf.beleg_verarbeitung_id WHERE kf.status = 'offen'), '[]'::jsonb));

  ELSIF p_ansicht = 'mails' THEN
    RETURN jsonb_build_object(
      'entwuerfe', plattform_modul_an('mail_entwuerfe'),
      'tage', tage, 'q', q, 'kategorie', coalesce(d->>'kategorie', ''), 'suche', d ? 'suche',
      'standard', coalesce(ally_nutzer_wert(u, 'standard_postfach'), ''),
      'postfaecher', coalesce((SELECT jsonb_agg(jsonb_build_object('adresse', p2.adresse, 'aktiv', p2.aktiv) ORDER BY p2.adresse)
        FROM ally_postfaecher p2 WHERE ally_postfach_zustaendig(u, p2.adresse)), '[]'::jsonb),
      'angebote', CASE WHEN plattform_modul_an('mail_entwuerfe') THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id', x.id, 'postfach', x.postfach,
          'absender', coalesce(x.absender_name || ' ', '') || '<' || coalesce(x.antwort_an, x.absender) || '>', 'betreff', x.betreff, 'zusammenfassung', x.zusammenfassung,
          'eingang', arbeit_zeit(x.erstellt_am)) ORDER BY x.erstellt_am DESC)
        FROM (SELECT * FROM mail_rueckfragen r2 WHERE r2.status = 'offen' AND r2.art = 'antwort' AND r2.erstellt_am > now() - interval '14 days'
              AND ally_postfach_zustaendig(u, r2.postfach) ORDER BY r2.erstellt_am DESC LIMIT 30) x), '[]'::jsonb) END,
      'treffer', CASE WHEN plattform_modul_an('mail_entwuerfe') AND d ? 'suche' THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id', x.id, 'postfach', x.postfach,
          'absender', coalesce(x.absender_name || ' ', '') || '<' || coalesce(x.antwort_an, x.absender) || '>', 'betreff', x.betreff, 'status', x.status,
          'eingang', arbeit_zeit(x.erstellt_am), 'auszug', left(coalesce(x.zusammenfassung, regexp_replace(coalesce(x.inhalt, ''), '\s+', ' ', 'g')), 300)) ORDER BY x.erstellt_am DESC)
        FROM (SELECT * FROM mail_rueckfragen r2 WHERE r2.art = 'antwort' AND r2.erstellt_am > now() - make_interval(days => tage)
              AND ally_postfach_zustaendig(u, r2.postfach)
              AND (q = '' OR concat_ws(' ', r2.absender, r2.absender_name, r2.antwort_an, r2.betreff, r2.inhalt) ILIKE '%' || q || '%')
              ORDER BY r2.erstellt_am DESC LIMIT 30) x), '[]'::jsonb) END,
      'log', CASE WHEN d ? 'log' THEN coalesce((SELECT jsonb_agg(jsonb_build_object('kategorie', x.kategorie_key, 'postfach', x.postfach, 'absender', x.sender, 'betreff', x.subject,
          'begruendung', x.begruendung, 'aktion', x.aktion_ausgefuehrt, 'zeit', arbeit_zeit(x.created_at)) ORDER BY x.created_at DESC)
        FROM (SELECT * FROM mail_klassifizierung_log l WHERE l.created_at > now() - make_interval(days => tage)
              AND (coalesce(d->>'kategorie', '') = '' OR l.kategorie_key = d->>'kategorie')
              AND (ally_postfach_zustaendig(u, l.postfach) OR (l.postfach IS NULL AND ally_hat_recht(u, 'admin')))
              AND (q = '' OR concat_ws(' ', l.sender, l.subject, l.begruendung, CASE l.kategorie_key WHEN 'kunde' THEN 'Kundschaft' WHEN 'geschaeft' THEN 'Geschäftlich' WHEN 'keine' THEN 'Keine Einordnung' WHEN 'spam' THEN 'Spam' WHEN 'system_report' THEN 'System-Report' END) ILIKE '%' || q || '%')
              ORDER BY l.created_at DESC LIMIT 100) x), '[]'::jsonb) END);

  ELSIF p_ansicht = 'kalender' THEN
    r := jsonb_build_object('kalender_id', coalesce(ally_nutzer_wert(u, 'kalender_id'), ''),
      'von', CASE WHEN coalesce(d->>'von', '') ~ '^20[0-9]{2}-[01][0-9]-[0-3][0-9]$' THEN d->>'von' ELSE to_char(now() AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD') END,
      'tage', CASE WHEN coalesce(d->>'tage', '') ~ '^[0-9]{1,2}$' THEN LEAST(GREATEST((d->>'tage')::int, 1), 62) ELSE 14 END,
      'q', q, 'termin', CASE WHEN coalesce(d->>'termin', '') ~ '^[A-Za-z0-9_-]{1,200}$' THEN d->>'termin' END);
    RETURN r || jsonb_build_object('extern', CASE WHEN r->>'kalender_id' <> '' THEN jsonb_build_object('kalender', jsonb_build_object(
      'kalender_id', r->>'kalender_id', 'von', r->>'von', 'tage', (r->>'tage')::int, 'q', q)) END);

  ELSIF p_ansicht = 'budgets' THEN
    RETURN jsonb_build_object('papierkram', EXISTS (SELECT 1 FROM ally_firma WHERE papierkram_subdomain ~ '^[a-z0-9-]+$'),
      'extern', CASE WHEN EXISTS (SELECT 1 FROM ally_firma WHERE papierkram_subdomain ~ '^[a-z0-9-]+$') THEN jsonb_build_object('budgets', true) END);

  ELSIF p_ansicht = 'systemmails' THEN
    RETURN jsonb_build_object('tage', tage, 'liste', coalesce((SELECT jsonb_agg(jsonb_build_object('absender', x.sender, 'betreff', x.subject, 'begruendung', x.begruendung,
        'postfach', x.postfach, 'zeit', arbeit_zeit(x.created_at)) ORDER BY x.created_at DESC)
      FROM (SELECT * FROM mail_klassifizierung_log l WHERE l.kategorie_key = 'system_report' AND l.created_at > now() - make_interval(days => tage)
            AND (ally_postfach_zustaendig(u, l.postfach) OR (l.postfach IS NULL AND ally_hat_recht(u, 'admin')))
            ORDER BY l.created_at DESC LIMIT 200) x), '[]'::jsonb));

  ELSIF p_ansicht = 'fragen' THEN
    RETURN jsonb_build_object('chat', EXISTS (SELECT 1 FROM ally_berechtigungen b WHERE b.matrix_user_id = u AND b.aktiv)
      AND EXISTS (SELECT 1 FROM ally_nutzer n WHERE n.matrix_user_id = u AND coalesce(n.room_id, '') <> ''));
  END IF;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.arbeit_zeit(p timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN p IS NULL THEN NULL ELSE to_char(p AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') END;
$function$
;

CREATE OR REPLACE FUNCTION public.beleg_web_eintragen(p_token text, p_r jsonb, p_ablage jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; pfad text := p_r->>'pfad'; kennung text := p_r->>'kennung'; name text := left(coalesce(nullif(btrim(p_r->>'name'), ''), 'Beleg'), 120); neu integer;
BEGIN
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF coalesce(pfad, '') !~ '^Belegerfassung/Belege-Staging/[0-9]{4}-[0-9]{2}-[0-9]{2}_[0-9]{2}-[0-9]{2}-[0-9]{2}_ally-web_[0-9a-f]{6}\.(pdf|xml)$'
     OR coalesce(kennung, '') !~ '^web-[0-9a-f]{24}$' THEN
    PERFORM ally_web_meldung(p_token, 'Der Beleg konnte nicht angenommen werden. Bitte erneut hochladen.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  IF coalesce((p_ablage->>'ok')::boolean, false) IS NOT TRUE THEN
    PERFORM ally_web_meldung(p_token, 'Der Beleg ' || name || ' konnte nicht abgelegt werden: ' || left(coalesce(nullif(p_ablage->>'fehler', ''), 'unbekannter Fehler'), 300), 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  INSERT INTO beleg_verarbeitung (source_mailbox, message_id, sender, subject, email_date, datei_bereich, datei_pfad, has_attachment)
  SELECT 'ally-web', kennung, s.person, left('Beleg aus der Oberfläche: ' || name, 250), now(), 'ally', pfad, true
  WHERE NOT EXISTS (SELECT 1 FROM beleg_verarbeitung x WHERE x.source_mailbox = 'ally-web' AND x.message_id = kennung)
  RETURNING id INTO neu;
  PERFORM ally_web_meldung(p_token, 'Beleg erhalten (' || name || '). Er wird beim nächsten Belege-Lauf verbucht (täglich 5 Uhr); sofort geht es mit „Jetzt verbuchen“.', 'ok', NULL);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'id', neu);
END $function$
;

CREATE OR REPLACE FUNCTION public.belege_fehler_ui(p_token text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN s.person IS NULL OR NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'belege') THEN '[]'::jsonb ELSE coalesce((
    SELECT jsonb_agg(jsonb_build_object('id', b.id, 'absender', b.sender, 'betreff', b.subject, 'lieferant', b.creditor_name_extrahiert, 'betrag', b.betrag,
      'eingang', arbeit_zeit(coalesce(b.email_date, b.created_at) AT TIME ZONE 'UTC'), 'versuche', b.fehlversuche, 'grund', left(coalesce(b.letzter_fehler, ''), 300),
      'zuletzt', arbeit_zeit(b.letzter_versuch), 'datei', coalesce(b.datei_pfad, '') <> '', 'quelle', b.source_mailbox) ORDER BY b.letzter_versuch DESC NULLS LAST, b.id DESC)
    FROM (SELECT * FROM beleg_verarbeitung x WHERE x.processing_status = 'fehler' ORDER BY x.letzter_versuch DESC NULLS LAST, x.id DESC LIMIT 200) b), '[]'::jsonb) END
  FROM (SELECT 1) x LEFT JOIN LATERAL (SELECT * FROM ally_ui_sitzung(p_token) y WHERE NOT y.muss_pw_setzen) s ON true
$function$
;

CREATE OR REPLACE FUNCTION public.cd_daten(p_unternehmen_id integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('unternehmen_id', c.unternehmen_id, 'unternehmen', (SELECT x.name FROM ally_unternehmen x WHERE x.id = c.unternehmen_id),
    'schrift', c.schrift,
    'farben', jsonb_build_object('farbe_dunkel', c.farbe_dunkel, 'farbe_text_auf_dunkel', c.farbe_text_auf_dunkel, 'farbe_akzent', c.farbe_akzent,
      'farbe_akzent_dunkel', c.farbe_akzent_dunkel, 'farbe_hell', c.farbe_hell, 'farbe_grau', c.farbe_grau, 'farbe_warnung', c.farbe_warnung),
    'dateien', coalesce((SELECT jsonb_object_agg(d.art, 'data:' || d.mime || ';base64,' || d.daten) FROM ally_cd_dateien d WHERE d.unternehmen_id = c.unternehmen_id), '{}'::jsonb),
    'gestaltung', jsonb_build_object('stile', to_jsonb(c.stile), 'punkte', c.deko_punkte, 'boegen', c.deko_boegen, 'gross_icon', c.deko_icon,
      'icons', c.icons_an, 'icons_aus', to_jsonb(c.icons_aus)),
    'icons', coalesce((SELECT jsonb_object_agg(i.name, i.svg) FROM ally_icons i), '{}'::jsonb))
  FROM ally_cd c
  WHERE c.unternehmen_id = CASE WHEN EXISTS (SELECT 1 FROM ally_cd y WHERE y.unternehmen_id = p_unternehmen_id) THEN p_unternehmen_id
                                ELSE (SELECT f.unternehmen_id FROM ally_firma f ORDER BY f.id LIMIT 1) END
$function$
;

CREATE OR REPLACE FUNCTION public.cd_hintergruende(p_unternehmen_id integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'hell', h.hell, 'src', 'data:' || h.mime || ';base64,' || h.daten) ORDER BY h.id), '[]'::jsonb)
  FROM marketing_hintergruende h
  WHERE h.unternehmen_id = CASE WHEN EXISTS (SELECT 1 FROM ally_cd y WHERE y.unternehmen_id = p_unternehmen_id) THEN p_unternehmen_id
                                ELSE (SELECT f.unternehmen_id FROM ally_firma f ORDER BY f.id LIMIT 1) END
$function$
;

CREATE OR REPLACE FUNCTION public.cd_seite(p_unternehmen_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN c.unternehmen_id IS NULL THEN jsonb_build_object('vorhanden', false)
    ELSE jsonb_build_object('vorhanden', true, 'schrift', c.schrift,
      'farben', jsonb_build_object('farbe_dunkel', c.farbe_dunkel, 'farbe_text_auf_dunkel', c.farbe_text_auf_dunkel, 'farbe_akzent', c.farbe_akzent,
        'farbe_akzent_dunkel', c.farbe_akzent_dunkel, 'farbe_hell', c.farbe_hell, 'farbe_grau', c.farbe_grau, 'farbe_warnung', c.farbe_warnung),
      'gestaltung', jsonb_build_object('stile', to_jsonb(c.stile), 'punkte', c.deko_punkte, 'boegen', c.deko_boegen, 'gross_icon', c.deko_icon,
        'icons', c.icons_an, 'icons_aus', to_jsonb(c.icons_aus)),
      'geaendert', to_char(c.geaendert_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI')) END
    || jsonb_build_object('dateien', coalesce((SELECT jsonb_object_agg(d.art, jsonb_build_object('dateiname', d.dateiname, 'groesse', d.groesse,
        'geaendert', to_char(d.geaendert_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI'), 'src', 'data:' || d.mime || ';base64,' || d.daten))
      FROM ally_cd_dateien d WHERE d.unternehmen_id = p_unternehmen_id), '{}'::jsonb))
    -- Eigene Hintergruende: nur kleine Vorschau, das Bild selbst holt MARKETING 2
    || jsonb_build_object('hintergruende', coalesce((SELECT jsonb_agg(jsonb_build_object('id', h.id, 'hell', h.hell, 'vorschau', h.vorschau, 'dateiname', h.dateiname,
        'groesse', h.groesse, 'angelegt', to_char(h.angelegt_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY')) ORDER BY h.id)
      FROM marketing_hintergruende h WHERE h.unternehmen_id = p_unternehmen_id), '[]'::jsonb))
  FROM (SELECT p_unternehmen_id AS id) q LEFT JOIN ally_cd c ON c.unternehmen_id = q.id
$function$
;

CREATE OR REPLACE FUNCTION public.dokumente_ordner()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Hauptordner für erzeugte Dokumente; bleibt bei einer Umbenennung des Produkts gleich, damit Dateien nicht verstreut werden
  SELECT coalesce(nullif(btrim(ally_einstellung('dokumente_ordner')), ''), 'Dokumente')
$function$
;

CREATE OR REPLACE FUNCTION public.eigenes_unternehmen()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('name', n.name, 'inhaber', n.inhaber, 'ort', n.ort, 'website', n.website, 'leistungen', n.leistungen,
    'kurz', n.name || coalesce(' in ' || n.ort, '') || coalesce(' (Inhaberschaft: ' || n.inhaber || ')', ''),
    'text', n.name || coalesce(' in ' || n.ort, '') || coalesce(' (Inhaberschaft: ' || n.inhaber || ')', '')
      || coalesce('. Leistungen: ' || n.leistungen, '') || coalesce('. Website: ' || n.website, ''))
  FROM (
    SELECT coalesce(nullif(trim(x.name), ''), f.name) AS name,
      nullif(trim(coalesce(x.inhaber, f.inhaber)), '') AS inhaber,
      nullif(trim(coalesce(x.ort, f.ort)), '') AS ort,
      nullif(trim(coalesce(x.website, f.website)), '') AS website,
      nullif(trim(x.leistungen), '') AS leistungen
    FROM ally_firma f LEFT JOIN ally_unternehmen x ON x.id = f.unternehmen_id
    ORDER BY f.id LIMIT 1) n
$function$
;

CREATE OR REPLACE FUNCTION public.einladung_auswahl_ablegen(p_link_token text, p_plattform text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  r jsonb := talent_einladung_suchen(p_link_token);
  tok text := lower(btrim(coalesce(p_link_token, '')));
  pl text := lower(btrim(coalesce(p_plattform, '')));
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  w text := lower(btrim(coalesce(d->>'anmeldeweg', '')));
  sch text := d->>'schluessel';
  gb timestamptz;
  konten jsonb := '[]'::jsonb;
  e jsonb;
  code text;
  pfad text;
BEGIN
  IF r->>'grund' IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'grund', r->>'grund', 'fehler', talent_einladung_grund_text(r->>'grund'));
  END IF;
  IF NOT pl = ANY (talents_plattformen())
     OR NOT EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = (r->>'talent_id')::integer AND k.plattform = pl) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'kanal', 'fehler', 'Dieser Kanal ist in deiner Einladung nicht vorgesehen.');
  END IF;
  IF w = '' OR NOT w = ANY (talent_wege(pl)) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'daten', 'fehler', 'Unbekannter Anmeldeweg.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'technik', 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  IF btrim(coalesce(sch, '')) = '' OR length(sch) > 4000 THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'daten', 'fehler', 'Kein gültiger Zugangsschlüssel.');
  END IF;
  IF jsonb_typeof(d->'konten') IS DISTINCT FROM 'array' OR jsonb_array_length(d->'konten') NOT BETWEEN 1 AND 50 THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'daten', 'fehler', 'Keine gültige Konto-ID.');
  END IF;
  FOR e IN SELECT z.x FROM (SELECT DISTINCT ON (btrim(a.x->>'extern_id')) a.x, a.o FROM jsonb_array_elements(d->'konten') WITH ORDINALITY AS a(x, o)
                            ORDER BY btrim(a.x->>'extern_id'), a.o) z ORDER BY z.o LOOP
    IF jsonb_typeof(e) <> 'object' OR btrim(coalesce(e->>'extern_id', '')) !~ '^[A-Za-z0-9_.:-]{1,100}$' THEN
      RETURN jsonb_build_object('ok', false, 'grund', 'daten', 'fehler', 'Keine gültige Konto-ID.');
    END IF;
    IF nullif(btrim(coalesce(e->>'extern_seite_id', '')), '') !~ '^[A-Za-z0-9_.:-]{1,100}$' THEN
      RETURN jsonb_build_object('ok', false, 'grund', 'daten', 'fehler', 'Keine gültige Seiten-ID.');
    END IF;
    IF length(coalesce(e->>'schluessel_zusatz', '')) > 4000 THEN
      RETURN jsonb_build_object('ok', false, 'grund', 'daten', 'fehler', 'Kein gültiger Zugangsschlüssel.');
    END IF;
    konten := konten || jsonb_build_array(jsonb_build_object('extern_id', btrim(e->>'extern_id'),
      'extern_name', nullif(left(ltrim(btrim(coalesce(e->>'extern_name', '')), '@'), 200), ''),
      'extern_seite_id', nullif(btrim(coalesce(e->>'extern_seite_id', '')), ''),
      'schluessel_zusatz', nullif(e->>'schluessel_zusatz', ''),
      'seite_name', nullif(left(btrim(regexp_replace(coalesce(e->>'seite_name', ''), '[[:cntrl:]]', ' ', 'g')), 200), '')));
  END LOOP;
  BEGIN
    gb := talents_gueltig_bis(d->>'gueltig_bis');
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'daten', 'fehler', 'Ungültiges Ablaufdatum.');
  END;
  -- Aufräumen: alte Einträge (1 Tag) und abgelaufene Zwischenstände (15 Minuten, enthalten Schlüssel)
  DELETE FROM talent_anmeldungen WHERE erstellt_am < now() - interval '1 day' OR (art = 'auswahl' AND erstellt_am <= now() - interval '15 minutes');
  code := encode(gen_random_bytes(24), 'hex');
  INSERT INTO talent_anmeldungen (state_hash, einladung_id, plattform, anmeldeweg, link_token, art, daten)
  VALUES (ally_web_hash(code), (r->>'einladung_id')::integer, pl, w, ally_verschluesseln(tok), 'auswahl',
    ally_verschluesseln((jsonb_build_object('schluessel', sch, 'gueltig_bis', gb, 'konten', konten)
      || CASE WHEN d ? 'berechtigungen' THEN jsonb_build_object('berechtigungen', to_jsonb(talents_liste(d->'berechtigungen'))) ELSE '{}'::jsonb END
      -- Meta-Nutzer-ID mitnehmen (Migration 50), einladung_auswahl_abschliessen gibt sie an einladung_kanal_speichern weiter (Stefan 18.10.2026)
      || CASE WHEN btrim(coalesce(d->>'meta_nutzer_id', '')) ~ '^[0-9]{1,30}$' THEN jsonb_build_object('meta_nutzer_id', btrim(d->>'meta_nutzer_id')) ELSE '{}'::jsonb END)::text));
  pfad := ally_webhook_aussen() || '/einladung/auswahl?a=' || code;
  RETURN jsonb_build_object('ok', true, 'auswahl', code, 'auswahl_pfad', pfad, 'aussen', ally_webhook_aussen(),
    'auswahl_adresse', rtrim(btrim(ally_einstellung('n8n_oeffentlich')), '/') || pfad,
    'plattform', pl, 'weg', w, 'anzahl', jsonb_array_length(konten),
    'gueltig_bis_zeit', to_char((now() + interval '15 minutes') AT TIME ZONE 'Europe/Berlin', 'HH24:MI'));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'grund', 'technik',
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_auswahl_abschliessen(p_auswahl text, p_extern_ids jsonb, p_abbrechen boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- Löst den Auswahl-Code einmalig ein und speichert die gewählten Accounts (verschlüsselt) über einladung_kanal_speichern (Stefan 18.10.2026)
DECLARE
  c text := lower(btrim(coalesce(p_auswahl, '')));
  a talent_anmeldungen%ROWTYPE;
  tok text;
  b jsonb;
  r jsonb;
  dat jsonb;
  ids text[];
  gew jsonb;
  kid integer;
  tid integer;
  erg jsonb;
BEGIN
  IF c !~ '^[0-9a-f]{48}$' THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'ungueltig', 'fehler', 'Diese Auswahl ist nicht mehr gültig. Bitte den Einladungslink aus der Nachricht noch einmal öffnen.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'technik', 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  SELECT * INTO a FROM talent_anmeldungen x WHERE x.state_hash = ally_web_hash(c) AND x.art = 'auswahl' FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'ungueltig', 'fehler', 'Diese Auswahl ist nicht mehr gültig. Bitte den Einladungslink aus der Nachricht noch einmal öffnen.');
  END IF;
  tok := ally_entschluesseln(a.link_token);
  b := jsonb_build_object('link_token', tok, 'einladung_pfad', ally_webhook_aussen() || '/einladung?t=' || tok, 'aussen', ally_webhook_aussen(),
    'einladung_adresse', talents_basis() || '?t=' || tok, 'plattform', a.plattform, 'weg', a.anmeldeweg);
  IF coalesce(p_abbrechen, false) THEN
    DELETE FROM talent_anmeldungen WHERE state_hash = a.state_hash;
    RETURN b || jsonb_build_object('ok', false, 'grund', 'abgebrochen', 'fehler', 'Anmeldung abgebrochen.');
  END IF;
  IF a.erstellt_am <= now() - interval '15 minutes' THEN
    DELETE FROM talent_anmeldungen WHERE state_hash = a.state_hash;
    RETURN b || jsonb_build_object('ok', false, 'grund', 'zeit', 'fehler', 'Die Auswahl hat zu lange gedauert. Bitte noch einmal auf den Knopf für den Kanal tippen.');
  END IF;
  r := talent_einladung_suchen(tok);
  IF r->>'grund' IS NOT NULL THEN
    DELETE FROM talent_anmeldungen WHERE state_hash = a.state_hash;
    RETURN b || jsonb_build_object('ok', false, 'grund', r->>'grund', 'fehler', talent_einladung_grund_text(r->>'grund'));
  END IF;
  tid := (r->>'talent_id')::integer;
  dat := ally_entschluesseln(a.daten)::jsonb;
  ids := talents_liste(p_extern_ids);
  -- Leere oder unbekannte Auswahl: Code bleibt gültig (erneut absenden möglich)
  IF cardinality(ids) = 0 THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'leer', 'fehler', 'Bitte mindestens einen Account auswählen.');
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(ids) i WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(dat->'konten') x WHERE x->>'extern_id' = i)) THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'auswahl', 'fehler', 'In der Auswahl ist ein unbekannter Account. Bitte die Seite neu laden.');
  END IF;
  DELETE FROM talent_anmeldungen WHERE state_hash = a.state_hash;  -- Einmalgebrauch
  kid := talents_einladung_kanal(tid, a.plattform);
  IF kid IS NULL THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'kanal', 'fehler', 'Dieser Kanal ist in deiner Einladung nicht vorgesehen.');
  END IF;
  SELECT jsonb_agg(e.x ORDER BY e.o) INTO gew FROM jsonb_array_elements(dat->'konten') WITH ORDINALITY AS e(x, o) WHERE e.x->>'extern_id' = ANY (ids);
  erg := einladung_kanal_speichern(kid, (dat - 'konten') || jsonb_build_object('konten', gew, 'anmeldeweg', a.anmeldeweg));
  RETURN b || erg || jsonb_build_object('grund', CASE WHEN (erg->>'ok')::boolean THEN NULL WHEN coalesce((erg->>'doppelt')::boolean, false) THEN 'doppelt' ELSE 'fehler' END);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'grund', 'technik',
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_auswahl_lesen(p_auswahl text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
-- Für die Auswahlseite: Accounts ohne Schlüssel, verbraucht den Auswahl-Code nicht (Stefan 18.10.2026)
DECLARE
  c text := lower(btrim(coalesce(p_auswahl, '')));
  a talent_anmeldungen%ROWTYPE;
  b jsonb := jsonb_build_object('firma', coalesce(eigenes_unternehmen()->>'name', ''), 'produkt_name', produkt_name(), 'anbieter_name', anbieter_name());
  r jsonb;
  dat jsonb;
  tid integer;
  pn text;
  liste jsonb;
BEGIN
  IF c !~ '^[0-9a-f]{48}$' THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'ungueltig', 'fehler', 'Diese Auswahl ist nicht mehr gültig. Bitte den Einladungslink aus der Nachricht noch einmal öffnen.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'technik', 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  SELECT * INTO a FROM talent_anmeldungen x WHERE x.state_hash = ally_web_hash(c) AND x.art = 'auswahl';
  IF NOT FOUND THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'ungueltig', 'fehler', 'Diese Auswahl ist nicht mehr gültig. Bitte den Einladungslink aus der Nachricht noch einmal öffnen.');
  END IF;
  pn := talents_plattform_name(a.plattform);
  b := b || jsonb_build_object('plattform', a.plattform, 'plattform_name', pn, 'weg', a.anmeldeweg);
  IF a.erstellt_am <= now() - interval '15 minutes' THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'zeit', 'fehler', 'Die Auswahl hat zu lange gedauert. Bitte den Einladungslink noch einmal öffnen und erneut verbinden.');
  END IF;
  r := talent_einladung_suchen(ally_entschluesseln(a.link_token));
  IF r->>'grund' IS NOT NULL THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', r->>'grund', 'fehler', talent_einladung_grund_text(r->>'grund'));
  END IF;
  tid := (r->>'talent_id')::integer;
  dat := ally_entschluesseln(a.daten)::jsonb;
  SELECT coalesce(jsonb_agg(jsonb_build_object('extern_id', x->>'extern_id', 'extern_name', x->>'extern_name',
      'text', talents_konto_text(a.plattform, x->>'extern_name', x->>'extern_id'), 'seite_name', x->>'seite_name',
      'belegt', z.belegt, 'schon_verbunden', z.schon, 'auswaehlbar', NOT z.belegt, 'vorausgewaehlt', NOT z.belegt,
      'hinweis', CASE WHEN z.belegt THEN 'Bereits mit einem anderen Talent verbunden. Bitte die Agentur kontaktieren.'
                      WHEN z.schon THEN 'Schon verbunden. Die Verbindung wird erneuert.' END)
      ORDER BY lower(coalesce(x->>'extern_name', '')) COLLATE "C", e.o), '[]'::jsonb)
    INTO liste
  FROM jsonb_array_elements(dat->'konten') WITH ORDINALITY AS e(x, o)
  CROSS JOIN LATERAL (SELECT
      EXISTS (SELECT 1 FROM talent_kanaele y WHERE y.talent_id <> tid AND y.plattform = a.plattform AND y.extern_id = x->>'extern_id'
              AND y.status IN ('verbunden', 'abgelaufen')) AS belegt,
      EXISTS (SELECT 1 FROM talent_kanaele y WHERE y.talent_id = tid AND y.plattform = a.plattform AND y.extern_id = x->>'extern_id'
              AND y.status IN ('verbunden', 'abgelaufen')) AS schon) z;
  RETURN b || jsonb_build_object('ok', true,
    'talent', jsonb_build_object('anzeigename', talent_anzeigename(tid), 'begruessung', 'Hallo' || coalesce(' ' || talent_anzeigename(tid), '')),
    -- Facebook-Seiten: eigene Texte (Stefan 18.10.2026)
    'titel', CASE WHEN a.plattform = 'facebook' THEN 'Welche Facebook-Seiten gehören zu dieser Einladung?' ELSE 'Welche Accounts gehören zu dieser Einladung?' END,
    'text', CASE WHEN a.plattform = 'facebook' THEN 'Wir haben mehrere Facebook-Seiten gefunden. Bitte wähle die Seiten aus, die zu dieser Einladung gehören.'
                 ELSE 'Wir haben mehrere ' || pn || '-Accounts gefunden. Bitte wähle die Accounts aus, die zu dieser Einladung gehören.' END,
    'knopf', CASE WHEN a.plattform = 'facebook' THEN 'Ausgewählte Seiten verbinden' ELSE 'Ausgewählte Accounts verbinden' END, 'knopf_abbrechen', 'Abbrechen',
    'gueltig_bis_zeit', to_char((a.erstellt_am + interval '15 minutes') AT TIME ZONE 'Europe/Berlin', 'HH24:MI'),
    'konten', liste, 'anzahl', jsonb_array_length(liste),
    'anzahl_auswaehlbar', (SELECT count(*) FROM jsonb_array_elements(liste) x WHERE (x->>'auswaehlbar')::boolean));
EXCEPTION WHEN OTHERS THEN
  RETURN b || jsonb_build_object('ok', false, 'grund', 'technik',
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_daten(p_link_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  r jsonb := talent_einladung_suchen(p_link_token);
  b jsonb := jsonb_build_object('firma', coalesce(eigenes_unternehmen()->>'name', ''), 'produkt_name', produkt_name(), 'anbieter_name', anbieter_name());
  tid integer;
BEGIN
  IF r->>'grund' IS NOT NULL THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', r->>'grund', 'fehler', talent_einladung_grund_text(r->>'grund'));
  END IF;
  tid := (r->>'talent_id')::integer;
  RETURN b || jsonb_build_object('ok', true,
    -- Ohne Namen: anzeigename null, Begrüßung nur "Hallo" (Stefan 18.10.2026)
    'talent', jsonb_build_object('anzeigename', talent_anzeigename(tid), 'begruessung', 'Hallo' || coalesce(' ' || talent_anzeigename(tid), '')),
    'gueltig_bis', r->>'gueltig_bis',
    -- Je Plattform ein Eintrag mit allen verbundenen Accounts und den angebotenen Wegen (Stefan 18.10.2026).
    -- status/extern_name/verbunden_am wie bisher (Plattform gesamt bzw. erster verbundener Account). Keine IDs, keine Schlüssel.
    'kanaele', coalesce((SELECT jsonb_agg(jsonb_build_object('plattform', p.pl, 'name', talents_plattform_name(p.pl), 'status', p.status,
          'extern_name', p.erster_name, 'verbunden_am', p.erstes_datum, 'bereit', talent_plattform_bereit(p.pl),
          'doppelt_meldung', talents_doppelt_meldung(p.pl),
          'accounts', p.accounts, 'anzahl_verbunden', p.n_verb,
          'knopf_weiterer', CASE WHEN p.n_konten > 0 THEN 'Weiteren Account verbinden' END,
          'wege', (SELECT jsonb_agg(jsonb_build_object('weg', w.w, 'name', talents_weg_name(p.pl, w.w),
                     -- Knopf und Hinweis je Plattform und Weg (Stefan 18.10.2026)
                     'knopf', talents_weg_knopf(p.pl, w.w),
                     'hinweis', talents_weg_hinweis(p.pl, w.w),
                     'bevorzugt', w.n = 1,
                     'bereit', (talent_weg(p.pl, w.w)->>'bereit')::boolean) ORDER BY w.n)
                   FROM unnest(talent_wege(p.pl)) WITH ORDINALITY AS w(w, n)))
        ORDER BY array_position(talents_plattformen(), p.pl))
      FROM (SELECT k.plattform AS pl,
              CASE WHEN bool_or(k.status = 'verbunden') THEN 'verbunden' WHEN bool_or(k.status = 'abgelaufen') THEN 'abgelaufen'
                   WHEN bool_or(k.status = 'offen') THEN 'offen' ELSE 'getrennt' END AS status,
              count(*) FILTER (WHERE k.status = 'verbunden') AS n_verb,
              count(*) FILTER (WHERE k.status IN ('verbunden', 'abgelaufen') AND k.extern_id IS NOT NULL) AS n_konten,
              (array_agg(k.extern_name ORDER BY k.status = 'verbunden' DESC, k.verbunden_am, k.id) FILTER (WHERE k.status IN ('verbunden', 'abgelaufen')))[1] AS erster_name,
              (array_agg(talents_datum(k.verbunden_am) ORDER BY k.status = 'verbunden' DESC, k.verbunden_am, k.id) FILTER (WHERE k.status IN ('verbunden', 'abgelaufen')))[1] AS erstes_datum,
              coalesce(jsonb_agg(jsonb_build_object('extern_name', k.extern_name,
                  'text', talents_konto_text(k.plattform, k.extern_name, NULL),
                  'status', k.status, 'status_text', CASE WHEN k.status = 'verbunden' THEN 'verbunden' ELSE 'Verbindung abgelaufen, bitte neu verbinden' END,
                  'verbunden_am', talents_datum(k.verbunden_am), 'weg', k.anmeldeweg,
                  'weg_text', CASE WHEN k.plattform = 'instagram' THEN CASE k.anmeldeweg WHEN 'facebook' THEN 'über Facebook' WHEN 'instagram' THEN 'direkt über Instagram' END END)
                ORDER BY lower(coalesce(k.extern_name, '')) COLLATE "C", k.id) FILTER (WHERE k.status IN ('verbunden', 'abgelaufen') AND k.extern_id IS NOT NULL), '[]'::jsonb) AS accounts
            FROM talent_kanaele k WHERE k.talent_id = tid GROUP BY k.plattform) p), '[]'::jsonb));
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_kanal_fehler(p_kanal_id integer, p_fehler text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  k talent_kanaele%ROWTYPE;
  ziel integer;
BEGIN
  SELECT * INTO k FROM talent_kanaele WHERE id = p_kanal_id;
  IF k.id IS NULL THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  -- Fehler einer Anmeldung nie an einen verbundenen Account schreiben (sonst Warnzeichen "Letzter Abruf fehlgeschlagen"),
  -- sondern an den Platzhalter der Plattform; ohne Platzhalter wird nichts vermerkt (Stefan 18.10.2026)
  ziel := CASE WHEN k.status <> 'verbunden' THEN k.id
               ELSE (SELECT y.id FROM talent_kanaele y WHERE y.talent_id = k.talent_id AND y.plattform = k.plattform AND y.extern_id IS NULL ORDER BY y.id LIMIT 1) END;
  IF ziel IS NOT NULL THEN
    UPDATE talent_kanaele SET letzter_fehler = nullif(left(btrim(coalesce(p_fehler, '')), 300), ''), geaendert_am = now() WHERE id = ziel;
  END IF;
  RETURN jsonb_build_object('ok', true, 'vermerkt', ziel IS NOT NULL);
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_kanal_speichern(p_kanal_id integer, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- Speichert 1..n Accounts einer Plattform beim Talent des Kanals p_kanal_id (Stefan 18.10.2026): derselbe Account beim Talent
-- wird erneuert (auch nach "getrennt"), sonst wird der Platzhalter belegt, sonst eine neue Zeile angelegt.
-- p_daten: gemeinsam schluessel, gueltig_bis, berechtigungen, anmeldeweg; je Account extern_id, extern_name, extern_seite_id,
-- schluessel_zusatz – entweder direkt in p_daten (ein Account, wie bisher) oder als Liste konten[].
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  k talent_kanaele%ROWTYPE;
  alt talent_kanaele%ROWTYPE;
  t_status text;
  sch text := d->>'schluessel';
  w text := lower(btrim(coalesce(d->>'anmeldeweg', '')));
  ber text[];
  gb timestamptz;
  konten jsonb;
  e jsonb;
  eid text;
  ename text;
  sid text;
  zus text;
  ziel integer;
  wie text;
  andere integer;
  am text;
  agentur text[] := '{}';
  namen text[] := '{}';
  nm text;
  name_neu boolean := false;
  gesp jsonb := '[]'::jsonb;
  abgl jsonb := '[]'::jsonb;
  ziel_fehler integer;
  -- Meta-Nutzer-ID (app-bezogen) für die Zuordnung der Rückmeldungen von Meta (Migration 50); ungültig = ignorieren (Stefan 18.10.2026)
  mid text := CASE WHEN btrim(coalesce(d->>'meta_nutzer_id', '')) ~ '^[0-9]{1,30}$' THEN btrim(d->>'meta_nutzer_id') END;
BEGIN
  SELECT * INTO k FROM talent_kanaele WHERE id = p_kanal_id;
  IF k.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Kanal.');
  END IF;
  SELECT t.status INTO t_status FROM talents t WHERE t.id = k.talent_id;
  IF t_status <> 'aktiv' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Talent liegt im Papierkorb.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  IF btrim(coalesce(sch, '')) = '' OR length(sch) > 4000 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Kein gültiger Zugangsschlüssel.');
  END IF;
  konten := CASE WHEN jsonb_typeof(d->'konten') = 'array' THEN d->'konten' ELSE jsonb_build_array(d) END;
  IF jsonb_array_length(konten) NOT BETWEEN 1 AND 50 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Keine gültige Konto-ID.');
  END IF;
  FOR e IN SELECT x FROM jsonb_array_elements(konten) x LOOP
    IF jsonb_typeof(e) <> 'object' OR btrim(coalesce(e->>'extern_id', '')) !~ '^[A-Za-z0-9_.:-]{1,100}$' THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Keine gültige Konto-ID.');
    END IF;
    IF nullif(btrim(coalesce(e->>'extern_seite_id', '')), '') !~ '^[A-Za-z0-9_.:-]{1,100}$' THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Keine gültige Seiten-ID.');
    END IF;
    IF length(coalesce(e->>'schluessel_zusatz', '')) > 4000 THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Kein gültiger Zugangsschlüssel.');
    END IF;
  END LOOP;
  IF w = '' THEN
    w := k.anmeldeweg;
  END IF;
  IF w IS NOT NULL AND NOT w = ANY (talent_wege(k.plattform)) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Anmeldeweg.');
  END IF;
  BEGIN
    gb := talents_gueltig_bis(d->>'gueltig_bis');
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Ungültiges Ablaufdatum.');
  END;
  ber := CASE WHEN d ? 'berechtigungen' THEN talents_liste(d->'berechtigungen') END;
  -- Sperren in fester Reihenfolge: erst Talent + Plattform (Platzhalter), dann je Account (gegen gleichzeitige Anmeldungen)
  PERFORM pg_advisory_xact_lock(hashtext('talent_platzhalter:' || k.talent_id || ':' || k.plattform));
  PERFORM pg_advisory_xact_lock(hashtext('talent_konto:' || k.plattform || ':' || z.eid))
  FROM (SELECT DISTINCT btrim(x->>'extern_id') AS eid FROM jsonb_array_elements(konten) x ORDER BY 1) z;

  FOR e IN SELECT z.x FROM (SELECT DISTINCT ON (btrim(a.x->>'extern_id')) a.x, a.o FROM jsonb_array_elements(konten) WITH ORDINALITY AS a(x, o)
                            ORDER BY btrim(a.x->>'extern_id'), a.o) z ORDER BY z.o LOOP
    eid := btrim(e->>'extern_id');
    ename := nullif(left(ltrim(btrim(coalesce(e->>'extern_name', '')), '@'), 200), '');  -- ohne @
    -- Instagram-Anmeldung: keine Facebook-Seite, kein Seiten-Schlüssel
    sid := CASE WHEN w = 'instagram' THEN NULL ELSE nullif(btrim(coalesce(e->>'extern_seite_id', '')), '') END;
    zus := CASE WHEN w = 'instagram' THEN NULL ELSE nullif(e->>'schluessel_zusatz', '') END;
    -- Keine Doppelten: derselbe Account (Plattform + extern_id) darf nur bei EINEM Talent verbunden oder abgelaufen sein
    andere := NULL;
    SELECT y.talent_id INTO andere FROM talent_kanaele y
    WHERE y.talent_id <> k.talent_id AND y.plattform = k.plattform AND y.extern_id = eid AND y.status IN ('verbunden', 'abgelaufen')
    ORDER BY y.id LIMIT 1;
    IF andere IS NOT NULL THEN
      am := 'Account ' || coalesce(CASE WHEN ename IS NOT NULL THEN talents_konto_text(k.plattform, ename) END, 'mit der ID ' || eid) || ' ist bereits bei '
        || coalesce(talent_anzeigename(andere), 'einem anderen Talent') || ' verbunden.';
      agentur := agentur || am;
      namen := namen || coalesce(CASE WHEN ename IS NOT NULL THEN talents_konto_text(k.plattform, ename) END, eid);
      abgl := abgl || jsonb_build_array(jsonb_build_object('extern_id', eid, 'extern_name', ename));
      CONTINUE;
    END IF;
    -- Zielzeile: derselbe Account beim Talent, sonst der Platzhalter, sonst eine neue Zeile
    ziel := NULL;
    wie := 'erneuert';
    SELECT y.id INTO ziel FROM talent_kanaele y WHERE y.talent_id = k.talent_id AND y.plattform = k.plattform AND y.extern_id = eid;
    IF ziel IS NULL THEN
      wie := 'platzhalter';
      SELECT y.id INTO ziel FROM talent_kanaele y WHERE y.talent_id = k.talent_id AND y.plattform = k.plattform AND y.extern_id IS NULL ORDER BY y.id LIMIT 1;
    END IF;
    IF ziel IS NULL THEN
      wie := 'neu';
      INSERT INTO talent_kanaele (talent_id, plattform) VALUES (k.talent_id, k.plattform) RETURNING id INTO ziel;
    END IF;
    SELECT * INTO alt FROM talent_kanaele WHERE id = ziel;
    UPDATE talent_kanaele SET status = 'verbunden', anmeldeweg = w, extern_id = eid, extern_name = ename, extern_seite_id = sid,
      schluessel = ally_verschluesseln(sch), schluessel_zusatz = ally_verschluesseln(zus), gueltig_bis = gb, berechtigungen = ber,
      schluessel_art = CASE WHEN w = 'instagram' THEN 'nutzer' WHEN alt.anmeldeweg IS DISTINCT FROM w THEN NULL ELSE alt.schluessel_art END,
      verbunden_am = CASE WHEN alt.status = 'verbunden' AND alt.verbunden_am IS NOT NULL THEN alt.verbunden_am ELSE now() END,
      geprueft_am = now(), letzter_fehler = NULL, geaendert_am = now(),
      meta_nutzer_id = coalesce(mid, CASE WHEN alt.anmeldeweg IS NOT DISTINCT FROM w AND alt.extern_id IS NOT DISTINCT FROM eid THEN alt.meta_nutzer_id END)
    WHERE id = ziel;
    gesp := gesp || jsonb_build_array(jsonb_build_object('kanal_id', ziel, 'extern_id', eid, 'extern_name', ename, 'art', wie));
    IF nm IS NULL THEN
      nm := nullif(btrim(left(ltrim(regexp_replace(coalesce(ename, ''), '[[:cntrl:]]', '', 'g'), '@'), 120)), '');
    END IF;
  END LOOP;

  IF jsonb_array_length(gesp) = 0 THEN
    -- Nichts gespeichert: Hinweis für die Agentur beim Platzhalter bzw. beim übergebenen, nicht verbundenen Kanal (nie bei einem verbundenen Account)
    ziel_fehler := CASE WHEN k.status <> 'verbunden' THEN k.id
                        ELSE (SELECT y.id FROM talent_kanaele y WHERE y.talent_id = k.talent_id AND y.plattform = k.plattform AND y.extern_id IS NULL ORDER BY y.id LIMIT 1) END;
    IF ziel_fehler IS NOT NULL THEN
      UPDATE talent_kanaele SET letzter_fehler = left(array_to_string(agentur, ' '), 300), geaendert_am = now() WHERE id = ziel_fehler;
    END IF;
    RETURN jsonb_build_object('ok', false, 'doppelt', true, 'kanal_id', k.id, 'talent_id', k.talent_id, 'plattform', k.plattform,
      'meldung', talents_doppelt_meldung(k.plattform), 'fehler', talents_doppelt_meldung(k.plattform), 'agentur_meldung', array_to_string(agentur, ' '),
      'anzahl', 0, 'gespeichert', gesp, 'abgelehnt', abgl);
  END IF;
  -- Talent ohne Namen: Name des ersten gespeicherten Accounts übernehmen (ohne @)
  IF nm IS NOT NULL THEN
    UPDATE talents SET name = nm, geaendert_am = now() WHERE id = k.talent_id AND name IS NULL;
    name_neu := FOUND;
  END IF;
  RETURN jsonb_build_object('ok', true, 'kanal_id', (gesp->0->>'kanal_id')::integer, 'talent_id', k.talent_id, 'plattform', k.plattform,
    'extern_name', gesp->0->>'extern_name', 'anzeigename', talent_anzeigename(k.talent_id), 'name_uebernommen', name_neu, 'doppelt', false,
    'anzahl', jsonb_array_length(gesp), 'gespeichert', gesp, 'abgelehnt', abgl, 'doppelt_anzahl', jsonb_array_length(abgl),
    'doppelt_meldung', CASE WHEN cardinality(namen) = 1 THEN 'Der ' || talents_plattform_name(k.plattform) || '-Account ' || namen[1]
                              || ' ist bereits mit einem anderen Talent verbunden und wurde nicht verbunden. Bitte die Agentur kontaktieren.'
                            WHEN cardinality(namen) > 1 THEN 'Diese ' || talents_plattform_name(k.plattform) || '-Accounts sind bereits mit einem anderen Talent verbunden und wurden nicht verbunden: '
                              || array_to_string(namen, ', ') || '. Bitte die Agentur kontaktieren.' END,
    'agentur_meldung', nullif(array_to_string(agentur, ' '), ''));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false,
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_start(p_link_token text, p_plattform text, p_weg text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  r jsonb := talent_einladung_suchen(p_link_token);
  tok text := lower(btrim(coalesce(p_link_token, '')));
  pl text := lower(btrim(coalesce(p_plattform, '')));
  w text := lower(btrim(coalesce(p_weg, '')));
  wd jsonb;
  eid integer;
  firma text := coalesce(nullif(btrim(eigenes_unternehmen()->>'name'), ''), 'der Agentur');
  st text;
BEGIN
  -- Testdaten (Migration 79)
  IF talents_ist_testdaten(CASE WHEN coalesce(r->>'talent_id', '') ~ '^[0-9]{1,9}$' THEN (r->>'talent_id')::integer END) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'testdaten', 'fehler', 'Diese Einladung gehört zu Testdaten. Damit lassen sich keine Accounts verbinden.');
  END IF;
  -- Weitere Plattformen: eigener Start mit fertiger Weiterleitung "ziel" (z. B. YouTube mit access_type=offline) (Stefan 18.10.2026)
  IF pl = ANY (talents_weitere_plattformen()) THEN
    RETURN einladung_start_weitere(p_link_token, p_plattform);
  END IF;
  IF r->>'grund' IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'grund', r->>'grund', 'fehler', talent_einladung_grund_text(r->>'grund'));
  END IF;
  eid := (r->>'einladung_id')::integer;
  IF NOT pl = ANY (talents_plattformen())
     OR NOT EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = (r->>'talent_id')::integer AND k.plattform = pl) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'kanal', 'fehler', 'Dieser Kanal ist in deiner Einladung nicht vorgesehen.');
  END IF;
  IF w = '' THEN
    SELECT x.w INTO w FROM unnest(talent_wege(pl)) WITH ORDINALITY AS x(w, n) WHERE (talent_weg(pl, x.w)->>'bereit')::boolean ORDER BY x.n LIMIT 1;
  END IF;
  IF w IS NULL OR NOT w = ANY (talent_wege(pl)) OR NOT (talent_weg(pl, w)->>'bereit')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'nicht_bereit',
      'fehler', 'Die Anmeldung für ' || talents_plattform_name(pl) || ' ist noch nicht eingerichtet. Bitte später noch einmal versuchen oder bei ' || firma || ' nachfragen.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'technik', 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  IF btrim(ally_einstellung('n8n_oeffentlich')) = '' THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'technik', 'fehler', 'Die öffentliche Adresse ist nicht eingetragen (Einstellung n8n_oeffentlich).');
  END IF;
  wd := talent_weg(pl, w);
  -- Aufräumen: alte Anmeldeversuche (älter als 1 Tag); Begrenzung: höchstens 20 Versuche je Einladung in 15 Minuten
  DELETE FROM talent_anmeldungen WHERE erstellt_am < now() - interval '1 day';
  IF (SELECT count(*) FROM talent_anmeldungen a WHERE a.einladung_id = eid AND a.erstellt_am > now() - interval '15 minutes') >= 20 THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'zu_viele', 'fehler', 'Zu viele Anmeldeversuche. Bitte in 15 Minuten noch einmal versuchen.');
  END IF;
  st := encode(gen_random_bytes(24), 'hex');
  INSERT INTO talent_anmeldungen (state_hash, einladung_id, plattform, anmeldeweg, link_token)
  VALUES (ally_web_hash(st), eid, pl, w, ally_verschluesseln(tok));
  RETURN jsonb_build_object('ok', true, 'state', st, 'plattform', pl, 'weg', w,
    'app_id', wd->>'app_id', 'scopes', wd->>'scopes', 'graph_version', wd->>'graph_version',
    'anmelde_adresse', wd->>'anmelde_adresse', 'rueckleitung', wd->>'rueckleitung',
    -- Instagram-Anmeldung, wenn schon ein Instagram-Account verbunden ist: neu anmelden lassen, damit ein weiterer Account gewählt werden kann (Stefan 18.10.2026)
    'zusatz_parameter', CASE WHEN w = 'instagram' AND EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = (r->>'talent_id')::integer AND k.plattform = pl
                               AND k.extern_id IS NOT NULL AND k.status IN ('verbunden', 'abgelaufen')) THEN 'force_reauth=true' ELSE '' END);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'grund', 'technik',
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_start_weitere(p_link_token text, p_plattform text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  r jsonb := talent_einladung_suchen(p_link_token);
  tok text := lower(btrim(coalesce(p_link_token, '')));
  pl text := lower(btrim(coalesce(p_plattform, '')));
  w text;
  wd jsonb;
  eid integer;
  tid integer;
  firma text := coalesce(nullif(btrim(eigenes_unternehmen()->>'name'), ''), 'der Agentur');
  st text;
  hat_konto boolean;
  zusatz text := '';
BEGIN
  -- Testdaten (Migration 79)
  IF talents_ist_testdaten(CASE WHEN coalesce(r->>'talent_id', '') ~ '^[0-9]{1,9}$' THEN (r->>'talent_id')::integer END) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'testdaten', 'fehler', 'Diese Einladung gehört zu Testdaten. Damit lassen sich keine Accounts verbinden.');
  END IF;
  IF r->>'grund' IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'grund', r->>'grund', 'fehler', talent_einladung_grund_text(r->>'grund'));
  END IF;
  eid := (r->>'einladung_id')::integer;
  tid := (r->>'talent_id')::integer;
  IF NOT pl = ANY (talents_weitere_plattformen())
     OR NOT EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = tid AND k.plattform = pl) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'kanal', 'fehler', 'Dieser Kanal ist in deiner Einladung nicht vorgesehen.');
  END IF;
  w := (talent_wege(pl))[1];
  wd := talent_weg_weitere(pl, w);
  IF NOT coalesce((wd->>'bereit')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'nicht_bereit',
      'fehler', 'Die Anmeldung für ' || talents_plattform_name(pl) || ' ist noch nicht eingerichtet. Bitte später noch einmal versuchen oder bei ' || firma || ' nachfragen.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'technik', 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  -- Aufräumen und Begrenzung wie einladung_start: höchstens 20 Versuche je Einladung in 15 Minuten
  DELETE FROM talent_anmeldungen WHERE erstellt_am < now() - interval '1 day';
  IF (SELECT count(*) FROM talent_anmeldungen a WHERE a.einladung_id = eid AND a.erstellt_am > now() - interval '15 minutes') >= 20 THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'zu_viele', 'fehler', 'Zu viele Anmeldeversuche. Bitte in 15 Minuten noch einmal versuchen.');
  END IF;
  hat_konto := EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = tid AND k.plattform = pl AND k.extern_id IS NOT NULL AND k.status IN ('verbunden', 'abgelaufen'));
  -- Zusatzparameter laut Doku: Google access_type=offline (Refresh-Token), prompt=select_account consent (Kontowahl, Refresh-Token auch bei erneuter Anmeldung);
  -- TikTok disable_auto_auth=1 (Zustimmungsseite immer zeigen), wenn schon ein TikTok-Account verbunden ist (weiteren Account wählen)
  zusatz := CASE pl WHEN 'youtube' THEN 'access_type=offline&include_granted_scopes=true&prompt=' || talents_adresse_kodieren('select_account consent')
                    WHEN 'tiktok' THEN CASE WHEN hat_konto THEN 'disable_auto_auth=1' ELSE '' END
                    ELSE '' END;
  st := encode(gen_random_bytes(24), 'hex');
  INSERT INTO talent_anmeldungen (state_hash, einladung_id, plattform, anmeldeweg, link_token)
  VALUES (ally_web_hash(st), eid, pl, w, ally_verschluesseln(tok));
  RETURN jsonb_build_object('ok', true, 'state', st, 'plattform', pl, 'weg', w,
    'app_id', wd->>'app_id', 'scopes', wd->>'scopes', 'anmelde_adresse', wd->>'anmelde_adresse', 'rueckleitung', wd->>'rueckleitung',
    'zusatz_parameter', zusatz,
    'ziel', (wd->>'anmelde_adresse') || '?' || (wd->>'client_param') || '=' || talents_adresse_kodieren(wd->>'app_id')
      || '&redirect_uri=' || talents_adresse_kodieren(wd->>'rueckleitung') || '&response_type=code'
      || '&scope=' || talents_adresse_kodieren(wd->>'scopes') || '&state=' || st || CASE WHEN zusatz <> '' THEN '&' || zusatz ELSE '' END);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'grund', 'technik',
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_zurueck(p_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  st text := lower(btrim(coalesce(p_state, '')));
  a talent_anmeldungen%ROWTYPE;
  tok text;
  b jsonb;
  r jsonb;
  wd jsonb;
  kid integer;
  tid integer;
BEGIN
  IF st !~ '^[0-9a-f]{48}$' THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'ungueltig', 'fehler', 'Die Anmeldung konnte nicht zugeordnet werden. Bitte den Einladungslink noch einmal öffnen.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'technik', 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  -- Nur Instagram-Anmeldungen; die weiteren Plattformen kommen über einladung_zurueck_weitere zurück (Stefan 18.10.2026)
  DELETE FROM talent_anmeldungen x WHERE x.state_hash = ally_web_hash(st) AND x.art = 'state' AND x.plattform = 'instagram' RETURNING * INTO a;
  IF a.state_hash IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'ungueltig', 'fehler', 'Die Anmeldung konnte nicht zugeordnet werden. Bitte den Einladungslink noch einmal öffnen.');
  END IF;
  tok := ally_entschluesseln(a.link_token);
  b := jsonb_build_object('link_token', tok, 'einladung_pfad', ally_webhook_aussen() || '/einladung?t=' || tok, 'aussen', ally_webhook_aussen(),
    'einladung_adresse', talents_basis() || '?t=' || tok, 'plattform', a.plattform, 'weg', a.anmeldeweg);
  IF a.erstellt_am <= now() - interval '15 minutes' THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'zeit', 'fehler', 'Die Anmeldung hat zu lange gedauert. Bitte noch einmal auf den Knopf für den Kanal tippen.');
  END IF;
  r := talent_einladung_suchen(tok);
  IF r->>'grund' IS NOT NULL THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', r->>'grund', 'fehler', talent_einladung_grund_text(r->>'grund'));
  END IF;
  tid := (r->>'talent_id')::integer;
  wd := talent_weg(a.plattform, a.anmeldeweg);
  IF NOT (wd->>'bereit')::boolean THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'nicht_bereit', 'fehler', 'Die Anmeldung für ' || talents_plattform_name(a.plattform) || ' ist gerade nicht eingerichtet.');
  END IF;
  -- Mehrere Accounts je Plattform: Platzhalter bevorzugt; gespeichert wird je Account über einladung_kanal_speichern (Stefan 18.10.2026)
  kid := talents_einladung_kanal(tid, a.plattform);
  IF kid IS NULL THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'kanal', 'fehler', 'Dieser Kanal ist in deiner Einladung nicht vorgesehen.');
  END IF;
  RETURN b || jsonb_build_object('ok', true, 'kanal_id', kid, 'talent_id', tid,
    'app_id', wd->>'app_id', 'app_secret', ally_geheim(wd->>'geheim'), 'rueckleitung', wd->>'rueckleitung',
    'graph_version', wd->>'graph_version', 'token_adresse', wd->>'token_adresse',
    'langzeit_adresse', wd->>'langzeit_adresse', 'api', wd->>'api',
    'anzeigename', talent_anzeigename(tid), 'firma', coalesce(eigenes_unternehmen()->>'name', ''));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'grund', 'technik',
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.einladung_zurueck_weitere(p_state text, p_plattform text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  st text := lower(btrim(coalesce(p_state, '')));
  pl text := lower(btrim(coalesce(p_plattform, '')));
  a talent_anmeldungen%ROWTYPE;
  tok text;
  b jsonb;
  r jsonb;
  wd jsonb;
  kid integer;
  tid integer;
  sec text;
BEGIN
  IF st !~ '^[0-9a-f]{48}$' OR NOT pl = ANY (talents_weitere_plattformen()) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'ungueltig', 'fehler', 'Die Anmeldung konnte nicht zugeordnet werden. Bitte den Einladungslink noch einmal öffnen.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'technik', 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  DELETE FROM talent_anmeldungen x WHERE x.state_hash = ally_web_hash(st) AND x.art = 'state' AND x.plattform = pl RETURNING * INTO a;
  IF a.state_hash IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'ungueltig', 'fehler', 'Die Anmeldung konnte nicht zugeordnet werden. Bitte den Einladungslink noch einmal öffnen.');
  END IF;
  tok := ally_entschluesseln(a.link_token);
  b := jsonb_build_object('link_token', tok, 'einladung_pfad', ally_webhook_aussen() || '/einladung?t=' || tok, 'aussen', ally_webhook_aussen(),
    'einladung_adresse', talents_basis() || '?t=' || tok, 'plattform', a.plattform, 'weg', a.anmeldeweg);
  IF a.erstellt_am <= now() - interval '15 minutes' THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'zeit', 'fehler', 'Die Anmeldung hat zu lange gedauert. Bitte noch einmal auf den Knopf für den Kanal tippen.');
  END IF;
  r := talent_einladung_suchen(tok);
  IF r->>'grund' IS NOT NULL THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', r->>'grund', 'fehler', talent_einladung_grund_text(r->>'grund'));
  END IF;
  tid := (r->>'talent_id')::integer;
  wd := talent_weg_weitere(a.plattform, a.anmeldeweg);
  IF NOT coalesce((wd->>'bereit')::boolean, false) THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'nicht_bereit', 'fehler', 'Die Anmeldung für ' || talents_plattform_name(a.plattform) || ' ist gerade nicht eingerichtet.');
  END IF;
  kid := talents_einladung_kanal(tid, a.plattform);
  IF kid IS NULL THEN
    RETURN b || jsonb_build_object('ok', false, 'grund', 'kanal', 'fehler', 'Dieser Kanal ist in deiner Einladung nicht vorgesehen.');
  END IF;
  sec := ally_geheim(wd->>'geheim');
  RETURN b || jsonb_build_object('ok', true, 'kanal_id', kid, 'talent_id', tid,
    'app_id', wd->>'app_id', 'app_secret', sec, 'client_param', wd->>'client_param', 'token_auth', wd->>'token_auth',
    -- Pinterest: Kopfzeile Authorization: Basic base64(client_id:client_secret)
    'basic', CASE WHEN wd->>'token_auth' = 'basic' THEN replace(encode(convert_to((wd->>'app_id') || ':' || sec, 'UTF8'), 'base64'), E'\n', '') END,
    'rueckleitung', wd->>'rueckleitung', 'graph_version', wd->>'graph_version', 'scopes', wd->>'scopes',
    'token_adresse', wd->>'token_adresse', 'langzeit_adresse', wd->>'langzeit_adresse', 'api', wd->>'api', 'data_api', wd->>'data_api',
    'anzeigename', talent_anzeigename(tid), 'firma', coalesce(eigenes_unternehmen()->>'name', ''));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'grund', 'technik',
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.ki_buchen(p_funktion text, p_workflow text, p_user text, p_antwort jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  u jsonb := coalesce(p_antwort->'usage', '{}'::jsonb);
  m text := coalesce(p_antwort->>'model', '');
  e int; cs int; cl int; a int; h int;
BEGIN
  BEGIN
    e := coalesce((u->>'input_tokens')::int, 0);
    cs := coalesce((u->>'cache_creation_input_tokens')::int, 0);
    cl := coalesce((u->>'cache_read_input_tokens')::int, 0);
    a := coalesce((u->>'output_tokens')::int, 0);
    -- Migration 185: 1-Stunden-Cache nur, wenn die Antwort ihn ausweist (usage.cache_creation.ephemeral_1h_input_tokens); sonst 0 = alles zum 5-Minuten-Preis wie bisher
    h := CASE WHEN (u->'cache_creation'->>'ephemeral_1h_input_tokens') ~ '^[0-9]{1,9}$' THEN least((u->'cache_creation'->>'ephemeral_1h_input_tokens')::int, cs) ELSE 0 END;
    IF e + cs + cl + a > 0 THEN
      -- (Stefan 18.10.2026) Kundenfaktor und Schlüssel zum Zeitpunkt der Buchung festhalten
      INSERT INTO ki_verbrauch (matrix_user_id, funktion, workflow, modell, tokens_eingabe, tokens_cache_schreiben, tokens_cache_lesen, tokens_ausgabe, kosten_usd, preis_faktor, schluessel)
      VALUES (nullif(trim(coalesce(p_user, '')), ''), coalesce(nullif(p_funktion, ''), 'unbekannt'), p_workflow, m, e, cs, cl, a, ki_kosten_usd(m, e, cs, cl, a, h),
              ki_faktor_aktuell(), ki_schluessel_aktuell());
    END IF;
  EXCEPTION WHEN others THEN
    -- Migration 185: Buchungsfehler nicht mehr still verschlucken – protokollieren und dem Superadmin melden (höchstens einmal je Modell und Tag); Antwort wie bisher
    PERFORM ki_kosten_melden('buchung_fehler', m, p_funktion, p_workflow, SQLERRM);
  END;
  RETURN coalesce(p_antwort->'content', '[]'::jsonb);
END $function$
;

CREATE OR REPLACE FUNCTION public.ki_faktor_aktuell()
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((SELECT CASE WHEN v.ki_schluessel = 'plattform' THEN v.preis_faktor ELSE 1 END FROM plattform_vertrag v WHERE v.id = 1), 1)
$function$
;

CREATE OR REPLACE FUNCTION public.ki_gesperrt()
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(ki_monat_stand()->>'stufe' = 'gesperrt', false)
$function$
;

CREATE OR REPLACE FUNCTION public.ki_kosten_melden(p_grund text, p_modell text, p_funktion text, p_workflow text, p_fehler text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  gr text := CASE WHEN p_grund = 'preis_fehlt' THEN 'preis_fehlt' ELSE 'buchung_fehler' END;
  md text := left(coalesce(nullif(btrim(coalesce(p_modell, '')), ''), '(ohne Modell)'), 100);
  k text; tag date := (now() AT TIME ZONE 'Europe/Berlin')::date; z system_meldungen; titel text; txt text; wo text; pr record;
BEGIN
  k := 'ki_kosten|' || gr || '|' || md;
  wo := 'Funktion ' || coalesce(nullif(left(btrim(coalesce(p_funktion, '')), 60), ''), 'unbekannt') || ', Ablauf ' || coalesce(nullif(left(btrim(coalesce(p_workflow, '')), 80), ''), 'unbekannt');
  IF gr = 'preis_fehlt' THEN
    titel := 'KI-Kosten: kein Preis für „' || md || '“';
    txt := 'Für das Modell „' || md || '“ (' || wo || ') gibt es keinen Eintrag in den KI-Preisen. Der Verbrauch ist mit seinen Tokens gespeichert, aber ohne Kosten: '
        || 'er zählt nicht zum KI-Budget und erscheint in der Übersicht mit 0 €. Bitte den Preis ergänzen. Diese Meldung kommt höchstens einmal am Tag je Modell.';
  ELSE
    titel := 'KI-Kosten: Buchung fehlgeschlagen';
    txt := 'Eine KI-Nutzung (Modell „' || md || '“, ' || wo || ') konnte nicht gebucht werden: ' || left(regexp_replace(coalesce(p_fehler, 'unbekannter Fehler'), '\s+', ' ', 'g'), 300)
        || '. Sie fehlt in der Übersicht und im KI-Budget. Diese Meldung kommt höchstens einmal am Tag je Modell.';
  END IF;
  BEGIN
    RAISE LOG 'Ally KI-Kosten (%): %', gr, txt;
    INSERT INTO system_meldungen (schluessel) VALUES (k) ON CONFLICT DO NOTHING;
    SELECT * INTO z FROM system_meldungen WHERE schluessel = k FOR UPDATE;
    IF z.zuletzt_gesendet IS NULL OR (z.zuletzt_gesendet AT TIME ZONE 'Europe/Berlin')::date < tag THEN
      UPDATE system_meldungen SET zuletzt_gesendet = now(), unterdrueckt = 0, letzter_text = left(txt, 2000), geaendert_am = now() WHERE schluessel = k;
      FOR pr IN SELECT p.matrix_user_id FROM ally_personen p WHERE p.aktiv AND coalesce(ally_hat_recht(p.matrix_user_id, 'superadmin'), false) ORDER BY p.matrix_user_id LOOP
        PERFORM ally_benachrichtigen(pr.matrix_user_id, 'systemfehler', titel, txt, jsonb_build_object('seite', 'ki-verbrauch'), k || '|' || tag::text, 'KI-Kosten', false);
      END LOOP;
    ELSE
      UPDATE system_meldungen SET unterdrueckt = unterdrueckt + 1, letzter_text = left(txt, 2000), geaendert_am = now() WHERE schluessel = k;
    END IF;
  EXCEPTION WHEN others THEN
    RAISE LOG 'Ally KI-Kosten: Meldung nicht möglich (%): %', SQLERRM, txt;
  END;
END $function$
;

CREATE OR REPLACE FUNCTION public.ki_kosten_usd(p_modell text, p_ein integer, p_cache_schreiben integer, p_cache_lesen integer, p_aus integer)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  SELECT round((coalesce(p_ein, 0) * p.eingabe + coalesce(p_cache_schreiben, 0) * p.cache_schreiben_5m
              + coalesce(p_cache_lesen, 0) * p.cache_lesen + coalesce(p_aus, 0) * p.ausgabe)
              * CASE WHEN p.schwelle_tokens IS NOT NULL
                      AND coalesce(p_ein, 0) + coalesce(p_cache_schreiben, 0) + coalesce(p_cache_lesen, 0) > p.schwelle_tokens
                     THEN coalesce(p.faktor_ueber_schwelle, 1) ELSE 1 END
              / 1000000.0, 6)
  FROM ki_preis_zu(p_modell) p WHERE p.modell IS NOT NULL
$function$
;

CREATE OR REPLACE FUNCTION public.ki_kosten_usd(p_modell text, p_ein integer, p_cache_schreiben integer, p_cache_lesen integer, p_aus integer, p_cache_1h integer)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  SELECT round((coalesce(p_ein, 0) * p.eingabe
              + (coalesce(p_cache_schreiben, 0) - least(greatest(coalesce(p_cache_1h, 0), 0), coalesce(p_cache_schreiben, 0))) * p.cache_schreiben_5m
              + least(greatest(coalesce(p_cache_1h, 0), 0), coalesce(p_cache_schreiben, 0)) * p.cache_schreiben_1h
              + coalesce(p_cache_lesen, 0) * p.cache_lesen + coalesce(p_aus, 0) * p.ausgabe)
              * CASE WHEN p.schwelle_tokens IS NOT NULL
                      AND coalesce(p_ein, 0) + coalesce(p_cache_schreiben, 0) + coalesce(p_cache_lesen, 0) > p.schwelle_tokens
                     THEN coalesce(p.faktor_ueber_schwelle, 1) ELSE 1 END
              / 1000000.0, 6)
  FROM ki_preis_zu(p_modell) p WHERE p.modell IS NOT NULL
$function$
;

CREATE OR REPLACE FUNCTION public.ki_modell(p_art text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
  -- Wirksames Modell für Workflows (Stefan 18.10.2026): im Sparmodus auch für anspruchsvolle Aufgaben das Modell für einfache Aufgaben
  IF p_art = 'anspruchsvoll' AND ki_sparmodus() THEN
    RETURN ki_modell_eingestellt('einfach');
  END IF;
  RETURN ki_modell_eingestellt(p_art);
END $function$
;

CREATE OR REPLACE FUNCTION public.ki_modell_eingestellt(p_art text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  m text;
BEGIN
  IF p_art IS NULL OR p_art NOT IN ('einfach', 'anspruchsvoll') THEN
    RAISE EXCEPTION 'ki_modell_eingestellt: unbekannte Art %, erlaubt sind einfach und anspruchsvoll', p_art;
  END IF;
  m := btrim(ally_einstellung('ki_modell_' || p_art));
  IF EXISTS (SELECT 1 FROM ki_preise k WHERE k.modell = m AND k.freigegeben) THEN
    RETURN m;
  END IF;
  SELECT k.modell INTO m FROM ki_preise k WHERE k.freigegeben
  ORDER BY CASE WHEN p_art = 'einfach' THEN k.ausgabe END ASC NULLS LAST,
           CASE WHEN p_art = 'anspruchsvoll' THEN k.ausgabe END DESC NULLS LAST,
           CASE WHEN p_art = 'einfach' THEN k.eingabe END ASC NULLS LAST,
           CASE WHEN p_art = 'anspruchsvoll' THEN k.eingabe END DESC NULLS LAST,
           k.modell
  LIMIT 1;
  RETURN m;  -- NULL, wenn kein Modell freigegeben ist
END $function$
;

CREATE OR REPLACE FUNCTION public.ki_modelle_json(p_intern boolean)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'modell', k.modell, 'name', coalesce(k.anzeige_name, k.modell), 'freigegeben', k.freigegeben,
      'eingestellt', CASE WHEN k.modell = z.e AND k.modell = z.a THEN 'beide' WHEN k.modell = z.e THEN 'einfach' WHEN k.modell = z.a THEN 'anspruchsvoll' END,
      'kunde_usd', jsonb_build_object('eingabe', round(k.eingabe * z.f, 4), 'cache_schreiben', round(k.cache_schreiben_5m * z.f, 4),
        'cache_lesen', round(k.cache_lesen * z.f, 4), 'ausgabe', round(k.ausgabe * z.f, 4)),
      'kunde_eur', CASE WHEN z.kurs IS NOT NULL THEN jsonb_build_object('eingabe', round(k.eingabe * z.f * z.kurs, 4), 'cache_schreiben', round(k.cache_schreiben_5m * z.f * z.kurs, 4),
        'cache_lesen', round(k.cache_lesen * z.f * z.kurs, 4), 'ausgabe', round(k.ausgabe * z.f * z.kurs, 4)) END,
      'schwelle_tokens', k.schwelle_tokens, 'faktor_ueber_schwelle', k.faktor_ueber_schwelle)
    || CASE WHEN p_intern THEN jsonb_build_object(
      'liste_usd', jsonb_build_object('eingabe', k.eingabe, 'cache_schreiben_5m', k.cache_schreiben_5m, 'cache_schreiben_1h', k.cache_schreiben_1h,
        'cache_lesen', k.cache_lesen, 'ausgabe', k.ausgabe),
      'quelle', k.quelle, 'stand', to_char(k.stand, 'DD.MM.YYYY')) ELSE '{}'::jsonb END
    ORDER BY k.ausgabe, k.eingabe, k.modell), '[]'::jsonb)
  FROM ki_preise k,
    (SELECT ki_faktor_aktuell() AS f, (SELECT usd_eur FROM plattform_vertrag WHERE id = 1) AS kurs,
            btrim(ally_einstellung('ki_modell_einfach')) AS e, btrim(ally_einstellung('ki_modell_anspruchsvoll')) AS a) z
  WHERE p_intern OR k.freigegeben
$function$
;

CREATE OR REPLACE FUNCTION public.ki_monat_funktionen()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object('funktion', x.funktion, 'name', coalesce(m.name, x.funktion), 'aufrufe', x.aufrufe,
           'tokens', x.tokens, 'usd', round(x.usd, 2), 'ohne_preis', x.ohne_preis,
           'eur', (SELECT round(x.usd * v.usd_eur, 2) FROM plattform_vertrag v WHERE v.id = 1)) ORDER BY x.usd DESC), '[]'::jsonb)
  FROM (
    -- (Stefan 18.10.2026) usd = Kundenpreis (kosten_usd * preis_faktor der Zeile)
    SELECT funktion, count(*) AS aufrufe, sum(tokens_eingabe + tokens_cache_schreiben + tokens_cache_lesen + tokens_ausgabe) AS tokens, coalesce(sum(kosten_usd * preis_faktor), 0) AS usd,
      count(*) FILTER (WHERE kosten_usd IS NULL) AS ohne_preis   -- Migration 189: Buchungen ohne Preis (Kosten unbekannt) zählen, Beträge wie bisher nur mit Preis
    FROM ki_verbrauch
    WHERE zeit >= date_trunc('month', now() AT TIME ZONE 'Europe/Berlin') AT TIME ZONE 'Europe/Berlin'
    GROUP BY funktion
  ) x LEFT JOIN plattform_module m ON m.schluessel = x.funktion
$function$
;

CREATE OR REPLACE FUNCTION public.ki_monat_intern()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH x AS (
    SELECT * FROM ki_verbrauch
    WHERE zeit >= date_trunc('month', now() AT TIME ZONE 'Europe/Berlin') AT TIME ZONE 'Europe/Berlin'
  ), k AS (SELECT usd_eur FROM plattform_vertrag WHERE id = 1),
  s AS (
    SELECT coalesce(sum(kosten_usd) FILTER (WHERE schluessel = 'plattform'), 0) AS kosten,
           coalesce(sum(kosten_usd * preis_faktor) FILTER (WHERE schluessel = 'plattform'), 0) AS kunde,
           coalesce(sum(kosten_usd) FILTER (WHERE schluessel = 'kunde'), 0) AS eigen,
           count(*) AS aufrufe, count(*) FILTER (WHERE kosten_usd IS NULL) AS ohne_preis
    FROM x
  )
  SELECT jsonb_build_object(
    'kosten_usd', round(s.kosten, 2), 'kunde_usd', round(s.kunde, 2), 'anteil_usd', round(s.kunde - s.kosten, 2),
    'kosten_eur', round(s.kosten * k.usd_eur, 2), 'kunde_eur', round(s.kunde * k.usd_eur, 2), 'anteil_eur', round((s.kunde - s.kosten) * k.usd_eur, 2),
    'eigener_schluessel_usd', round(s.eigen, 2), 'eigener_schluessel_eur', round(s.eigen * k.usd_eur, 2),
    'aufrufe', s.aufrufe, 'ohne_preis', s.ohne_preis, 'kurs', k.usd_eur,
    'funktionen', (SELECT coalesce(jsonb_agg(jsonb_build_object('funktion', f.funktion, 'name', coalesce(m.name, f.funktion), 'aufrufe', f.aufrufe,
        'kosten_usd', round(f.kosten, 2), 'kunde_usd', round(f.kunde, 2), 'anteil_usd', round(f.kunde - f.kosten, 2), 'eigener_schluessel_usd', round(f.eigen, 2), 'ohne_preis', f.ohne_preis)
        ORDER BY f.kunde + f.eigen DESC), '[]'::jsonb)
      FROM (SELECT funktion, count(*) AS aufrufe,
                   coalesce(sum(kosten_usd) FILTER (WHERE schluessel = 'plattform'), 0) AS kosten,
                   coalesce(sum(kosten_usd * preis_faktor) FILTER (WHERE schluessel = 'plattform'), 0) AS kunde,
                   coalesce(sum(kosten_usd) FILTER (WHERE schluessel = 'kunde'), 0) AS eigen,
                   count(*) FILTER (WHERE kosten_usd IS NULL) AS ohne_preis   -- Migration 189: Buchungen ohne Preis (Kosten unbekannt) zählen, Beträge wie bisher nur mit Preis
            FROM x GROUP BY funktion) f LEFT JOIN plattform_module m ON m.schluessel = f.funktion),
    'modelle', (SELECT coalesce(jsonb_agg(jsonb_build_object('modell', g.modell, 'name', coalesce(p.anzeige_name, g.modell), 'aufrufe', g.aufrufe,
        'kosten_usd', round(g.kosten, 2), 'kunde_usd', round(g.kunde, 2), 'ohne_preis', g.ohne_preis) ORDER BY g.kosten DESC), '[]'::jsonb)
      FROM (SELECT modell, count(*) AS aufrufe, coalesce(sum(kosten_usd), 0) AS kosten, coalesce(sum(kosten_usd * preis_faktor), 0) AS kunde,
                   count(*) FILTER (WHERE kosten_usd IS NULL) AS ohne_preis   -- Migration 189: Buchungen ohne Preis (Kosten unbekannt) zählen, Beträge wie bisher nur mit Preis
            FROM x GROUP BY modell) g LEFT JOIN ki_preise p ON p.modell = g.modell))
  FROM s, k
$function$
;

CREATE OR REPLACE FUNCTION public.ki_monat_stand()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH v AS (
    SELECT coalesce(sum(kosten_usd * preis_faktor), 0) AS usd, count(*) AS aufrufe, count(*) FILTER (WHERE kosten_usd IS NULL) AS ohne_preis FROM ki_verbrauch   -- Migration 189: Buchungen ohne Preis (Kosten unbekannt) zählen, Beträge wie bisher nur mit Preis
    WHERE zeit >= date_trunc('month', now() AT TIME ZONE 'Europe/Berlin') AT TIME ZONE 'Europe/Berlin'
  ), k AS (SELECT * FROM plattform_vertrag WHERE id = 1)
  SELECT jsonb_build_object(
    'verbrauch_usd', round(v.usd, 2),
    'aufrufe', v.aufrufe, 'ohne_preis', v.ohne_preis,
    'verbrauch_eur', CASE WHEN k.usd_eur IS NOT NULL THEN round(v.usd * k.usd_eur, 2) END,
    'budget_eur', k.ki_budget_eur,
    'prozent', CASE WHEN k.ki_budget_eur > 0 AND k.usd_eur IS NOT NULL THEN round(v.usd * k.usd_eur / k.ki_budget_eur * 100, 1) END,
    'stufe', CASE
      WHEN k.ki_budget_eur IS NULL OR k.usd_eur IS NULL THEN 'ok'
      WHEN v.usd * k.usd_eur >= k.ki_budget_eur THEN CASE WHEN k.budget_modus = 'sperre' THEN 'gesperrt' ELSE 'ueber_budget' END
      WHEN v.usd * k.usd_eur >= k.ki_budget_eur * k.spar_prozent / 100.0 THEN 'sparen'
      WHEN v.usd * k.usd_eur >= k.ki_budget_eur * k.warn_prozent / 100.0 THEN 'hinweis'
      ELSE 'ok' END,
    -- (Stefan 18.10.2026) bei eigenem Schlüssel rechnet Anthropic direkt mit dem Kunden ab; die Werte sind dann nur zur Information
    'schluessel', k.ki_schluessel,
    'informativ', k.ki_schluessel = 'kunde')
  FROM v, k
$function$
;

CREATE OR REPLACE FUNCTION public.ki_preis_zu(p_modell text)
 RETURNS ki_preise
 LANGUAGE sql
 STABLE
AS $function$
  SELECT p.* FROM ki_preise p
  WHERE p.modell = p_modell OR p_modell LIKE p.modell || '-%'
  ORDER BY (p.modell = p_modell) DESC, length(p.modell) DESC
  LIMIT 1
$function$
;

CREATE OR REPLACE FUNCTION public.ki_schluessel_aktuell()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((SELECT v.ki_schluessel FROM plattform_vertrag v WHERE v.id = 1), 'plattform')
$function$
;

CREATE OR REPLACE FUNCTION public.ki_sparmodus()
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Sparmodus: Verbrauch hat spar_prozent des Budgets erreicht (Stufe sparen) oder liegt darüber
  SELECT coalesce(ki_monat_stand()->>'stufe' IN ('sparen', 'ueber_budget', 'gesperrt'), false)
$function$
;

CREATE OR REPLACE FUNCTION public.ki_sperre_melden()
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  monat text := to_char(now() AT TIME ZONE 'Europe/Berlin', 'YYYY-MM');
BEGIN
  IF NOT ki_gesperrt() THEN
    RETURN false;
  END IF;
  -- Gleichzeitige Aufrufe nacheinander abarbeiten, damit nur einer true liefert
  PERFORM pg_advisory_xact_lock(hashtext('ki_sperre_melden'));
  IF ally_einstellung('ki_sperre_gemeldet') = monat THEN
    RETURN false;
  END IF;
  PERFORM ally_einstellung_setzen('ki_sperre_gemeldet', monat, NULL);
  RETURN true;
END $function$
;

CREATE OR REPLACE FUNCTION public.ki_sperre_text()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN ki_gesperrt() THEN
    'Das KI-Budget für diesen Monat ist erreicht. Bis zum Monatsende erledigt ' || produkt_name() || ' keine KI-Aufgaben mehr.'
    || CASE WHEN anbieter_name() <> '' THEN ' Ansprechperson: ' || anbieter_name() || '.' ELSE '' END
  ELSE '' END
$function$
;

CREATE OR REPLACE FUNCTION public.ki_verbrauch_ohne_preis_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM ki_kosten_melden('preis_fehlt', NEW.modell, NEW.funktion, NEW.workflow, NULL);
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.ki_web_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  u text;
  m text := NULL;
  fehler text := NULL;
  v plattform_vertrag%ROWTYPE;
  ist_sa boolean;
  me text; ma text; q text; cred text; meldung text;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := s.matrix_user_id;
  ist_sa := ally_hat_recht(u, 'superadmin');
  SELECT * INTO v FROM plattform_vertrag WHERE id = 1;

  IF NOT ally_hat_recht(u, 'admin') THEN
    fehler := 'Die KI-Einstellungen ändern Admins.';

  ELSIF p_aktion = 'ki_modelle' THEN
    me := btrim(coalesce(d->>'einfach', ''));
    ma := btrim(coalesce(d->>'anspruchsvoll', ''));
    IF NOT EXISTS (SELECT 1 FROM ki_preise k WHERE k.modell = me AND k.freigegeben)
       OR NOT EXISTS (SELECT 1 FROM ki_preise k WHERE k.modell = ma AND k.freigegeben) THEN
      fehler := 'Bitte für einfache und für anspruchsvolle Aufgaben je ein Modell aus der Liste wählen.';
    ELSE
      PERFORM ally_einstellung_setzen('ki_modell_einfach', me, u);
      PERFORM ally_einstellung_setzen('ki_modell_anspruchsvoll', ma, u);
      m := 'KI-Modelle gespeichert. Einfache Aufgaben: ' || (SELECT coalesce(anzeige_name, modell) FROM ki_preise WHERE modell = me)
        || ', anspruchsvolle Aufgaben: ' || (SELECT coalesce(anzeige_name, modell) FROM ki_preise WHERE modell = ma) || '.';
    END IF;

  ELSIF p_aktion IN ('ki_zugang_vorbereiten', 'ki_zugang_abschliessen') THEN
    -- Admin hinterlegt immer den eigenen Schlüssel (kunde); Superadmin wählt die Quelle (plattform = Schlüssel des Anbieters)
    q := CASE WHEN ist_sa THEN coalesce(nullif(btrim(d->>'quelle'), ''), 'kunde') ELSE 'kunde' END;
    cred := btrim(ally_einstellung('ki_credential_id'));
    -- Migration 172 (B8b, Fixieren): eigener Schlüssel erlaubt = KI-Zugang nicht fixiert
    IF NOT (ist_sa OR NOT ally_fixiert('ki_zugang', '')) THEN
      fehler := 'Einen eigenen KI-Zugang einzurichten ist in eurem Paket nicht vorgesehen. Bitte bei ' || coalesce(nullif(anbieter_name(), ''), 'eurem Anbieter') || ' nachfragen.';
    ELSIF q NOT IN ('plattform', 'kunde') THEN
      fehler := 'Bitte angeben, wessen Schlüssel hinterlegt wird.';
    ELSIF cred !~ '^[A-Za-z0-9]{8,40}$' THEN
      fehler := 'Für den KI-Zugang sind in n8n keine Zugangsdaten eingerichtet. Bitte die ' || produkt_name() || '-Betreuung fragen.';
    ELSIF p_aktion = 'ki_zugang_vorbereiten' THEN
      RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'credential_id', cred, 'quelle', q);
    ELSIF lower(coalesce(d->>'test_ok', '')) IN ('true', '1') THEN
      UPDATE plattform_vertrag SET ki_schluessel = q, geaendert_am = now(), geaendert_von = u WHERE id = 1;
      PERFORM ally_einstellung_setzen('ki_zugang_geprueft', now()::text, u);
      m := 'KI-Zugang geprüft und gespeichert. ' || CASE WHEN q = 'kunde'
        THEN 'Ab jetzt gilt euer eigener Anthropic-Schlüssel. Die KI-Kosten rechnet Anthropic direkt mit euch ab, der Verbrauch hier ist nur zur Information.'
        ELSE 'Ab jetzt gilt der KI-Zugang von ' || coalesce(nullif(anbieter_name(), ''), 'eurem Anbieter') || '.' END;
    ELSE
      meldung := left(btrim(coalesce(d->>'meldung', '')), 300);
      fehler := 'KI-Zugang nicht gespeichert. ' || coalesce(nullif(meldung, ''), 'Die Prüfung ist fehlgeschlagen.');
    END IF;

  ELSE
    fehler := 'Unbekannte Aktion.';
  END IF;

  UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'fehler', fehler);
  -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung, die Änderungen dieser Aktion sind zurückgenommen
EXCEPTION WHEN SQLSTATE 'AT002' THEN
  RETURN ally_fix_meldung(p_token, SQLERRM);
END $function$
;

CREATE OR REPLACE FUNCTION public.ki_web_daten(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
  v plattform_vertrag%ROWTYPE;
  ist_sa boolean;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  IF NOT ally_hat_recht(s.matrix_user_id, 'admin') THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Die KI-Einstellungen ändern Admins.');
  END IF;
  ist_sa := ally_hat_recht(s.matrix_user_id, 'superadmin');
  SELECT * INTO v FROM plattform_vertrag WHERE id = 1;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true,
    'modell_einfach', ki_modell_eingestellt('einfach'), 'modell_anspruchsvoll', ki_modell_eingestellt('anspruchsvoll'),
    'modelle', ki_modelle_json(false),
    'kurs', v.usd_eur,
    'kurs_stand', (SELECT to_char(wert::date, 'DD.MM.YYYY') FROM ally_einstellungen WHERE schluessel = 'kurs_usd_eur_stand' AND wert ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'),
    'ki_schluessel', v.ki_schluessel,
    -- Migration 172 (B8b, Fixieren): eigener Schlüssel erlaubt = KI-Zugang nicht fixiert
    'eigener_schluessel_erlaubt', NOT ally_fixiert('ki_zugang', ''),
    'darf_schluessel_aendern', ist_sa OR NOT ally_fixiert('ki_zugang', ''),
    'superadmin', ist_sa,
    'zugang_geprueft', (SELECT to_char(wert::timestamptz AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI') FROM ally_einstellungen
        WHERE schluessel = 'ki_zugang_geprueft' AND wert ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T]'),
    'anbieter_name', anbieter_name());
END $function$
;

CREATE OR REPLACE FUNCTION public.linkedin_seite_speichern(p_token text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE s record; d jsonb := coalesce(p_daten, '{}'::jsonb); ok boolean := false; m text;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT ally_hat_recht(s.matrix_user_id, 'admin') THEN
    m := 'Die Unternehmensseite verbinden Admins.';
  ELSIF coalesce(d->>'token', '') <> '' AND coalesce(d->>'org', '') ~ '^[0-9]{1,20}$' THEN
    PERFORM ally_token_setzen('linkedin_seite_token', d->>'token', s.matrix_user_id);   -- Migration 187b: Token verschlüsselt, nie im Klartext
    INSERT INTO ally_einstellungen (schluessel, wert, geaendert_am) VALUES
      ('linkedin_seite_ablauf', to_char((now() + make_interval(secs => greatest(coalesce((d->>'expires_in')::int, 0), 0))) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'), now()),
      ('linkedin_seite_org', d->>'org', now()),
      ('linkedin_seite_name', left(coalesce(nullif(d->>'name', ''), 'Unternehmensseite'), 200), now()),
      ('linkedin_seite_von', s.matrix_user_id, now())
    ON CONFLICT (schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
    ok := true;
    m := 'Unternehmensseite verbunden' || CASE WHEN coalesce(d->>'name', '') <> '' THEN ': ' || (d->>'name') ELSE '' END
      || '. Die Verbindung gilt 60 Tage, danach einmal neu verbinden.';
  ELSE
    m := 'Unternehmensseite konnte nicht verbunden werden' || CASE WHEN coalesce(d->>'fehler', '') <> '' THEN ' (' || left(d->>'fehler', 200) || ')' ELSE '' END || '.';
  END IF;
  UPDATE ally_web_sitzungen SET flash = m, flash_art = CASE WHEN ok THEN 'ok' ELSE 'fehler' END WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', ok, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.linkedin_speichern(p_token text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE s record; d jsonb := coalesce(p_daten, '{}'::jsonb); ok boolean := false; m text;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF coalesce(d->>'token', '') <> '' AND coalesce(d->>'sub', '') ~ '^[A-Za-z0-9_-]{1,100}$' THEN
    PERFORM ally_nutzer_token_setzen(s.matrix_user_id, 'linkedin_token', d->>'token');   -- Migration 187b: Token verschlüsselt, nie im Klartext
    INSERT INTO ally_nutzer_einstellungen (matrix_user_id, schluessel, wert, geaendert_am) VALUES
      (s.matrix_user_id, 'linkedin_ablauf', to_char((now() + make_interval(secs => greatest(coalesce((d->>'expires_in')::int, 0), 0))) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'), now()),
      (s.matrix_user_id, 'linkedin_name', left(coalesce(nullif(d->>'name', ''), 'LinkedIn'), 200), now()),
      (s.matrix_user_id, 'linkedin_sub', d->>'sub', now()),
      (s.matrix_user_id, 'linkedin_konto', left(coalesce(nullif(d->>'name', ''), 'LinkedIn'), 200), now())
    ON CONFLICT (matrix_user_id, schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
    ok := true;
    m := 'LinkedIn ist verbunden' || CASE WHEN coalesce(d->>'name', '') <> '' THEN ' als ' || (d->>'name') ELSE '' END
      || '. ' || produkt_name() || ' postet nur nach deiner Freigabe im Chat. Die Verbindung gilt 60 Tage, danach einmal neu verbinden.';
  ELSE
    m := 'LinkedIn konnte nicht verbunden werden' || CASE WHEN coalesce(d->>'fehler', '') <> '' THEN ' (' || left(d->>'fehler', 200) || ')' ELSE '' END || '. Bitte noch einmal versuchen.';
  END IF;
  UPDATE ally_web_sitzungen SET flash = m, flash_art = CASE WHEN ok THEN 'ok' ELSE 'fehler' END WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', ok, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.linkedin_start(p_token text, p_art text DEFAULT 'profil'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE s record; seite boolean := coalesce(p_art, '') = 'seite'; cid text; sec boolean; st text; fehler text;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true); END IF;
  cid := linkedin_wert(CASE WHEN seite THEN 'linkedin_seite_client_id' ELSE 'linkedin_client_id' END);
  sec := ally_geheim_vorhanden(CASE WHEN seite THEN 'linkedin_seite_client_secret' ELSE 'linkedin_client_secret' END);   -- Migration 186: nur ob vorhanden
  IF NOT plattform_modul_an('marketing_posten') THEN fehler := 'Das Paket Marketing veröffentlichen ist nicht gebucht.';
  ELSIF seite AND NOT ally_hat_recht(s.matrix_user_id, 'admin') THEN fehler := 'Die Unternehmensseite verbinden Admins.';
  ELSIF cid = '' OR NOT sec THEN
    fehler := CASE WHEN seite THEN 'Für die Unternehmensseite fehlen noch Client ID und Primary Client Secret.'
      ELSE 'LinkedIn ist noch nicht eingerichtet. Das machen Admins unter LinkedIn (Client ID und Primary Client Secret).' END;
  END IF;
  IF fehler IS NOT NULL THEN
    UPDATE ally_web_sitzungen SET flash = fehler, flash_art = 'fehler' WHERE token_hash = s.token_hash;
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  st := encode(gen_random_bytes(24), 'hex');
  INSERT INTO ally_nutzer_einstellungen (matrix_user_id, schluessel, wert, geaendert_am)
  VALUES (s.matrix_user_id, CASE WHEN seite THEN 'linkedin_seite_state' ELSE 'linkedin_state' END, st, now())
  ON CONFLICT (matrix_user_id, schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'art', CASE WHEN seite THEN 'seite' ELSE 'profil' END, 'client_id', cid, 'state', st,
    'scope', CASE WHEN seite THEN 'r_organization_admin w_organization_social' ELSE 'openid profile w_member_social' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.linkedin_web_einstellen(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE s record; d jsonb := coalesce(p_daten, '{}'::jsonb); m text; ok boolean := false; adm boolean; pre text;
  cid text := btrim(coalesce(d->>'client_id', '')); sec text := btrim(coalesce(d->>'client_secret', ''));
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true); END IF;
  adm := ally_hat_recht(s.matrix_user_id, 'admin');
  IF p_aktion IN ('linkedin_app', 'linkedin_seite_app') THEN
    pre := CASE WHEN p_aktion = 'linkedin_seite_app' THEN 'linkedin_seite_' ELSE 'linkedin_' END;
    IF NOT adm THEN m := 'Client ID und Primary Client Secret tragen Admins ein.';
    ELSIF cid !~ '^[A-Za-z0-9]{4,100}$' THEN m := 'Bitte die Client ID aus LinkedIn Developers angeben.';
    -- Migration 186: das Primary Client Secret liegt verschlüsselt in ally_geheimnisse (wie die Meta-App-Secrets), nie im Klartext
    ELSIF sec = '' AND NOT ally_geheim_vorhanden(pre || 'client_secret') THEN m := 'Bitte das Primary Client Secret angeben.';
    ELSIF coalesce(nullif(sec, ''), ally_geheim(pre || 'client_secret')) = cid THEN m := 'Client ID und Primary Client Secret sind gleich. Bitte das Primary Client Secret aus LinkedIn Developers eintragen.';
    ELSIF length(sec) > 500 OR sec ~ '[[:space:][:cntrl:]]' THEN m := 'Das Primary Client Secret sieht nicht richtig aus.';
    ELSE
      INSERT INTO ally_einstellungen (schluessel, wert, geaendert_am) VALUES (pre || 'client_id', cid, now())
        ON CONFLICT (schluessel) DO UPDATE SET wert = EXCLUDED.wert, geaendert_am = now();
      IF sec <> '' THEN
        PERFORM ally_geheim_setzen(pre || 'client_secret', sec, s.matrix_user_id);
      END IF;
      ok := true; m := 'Gespeichert. Jetzt mit „' || CASE WHEN p_aktion = 'linkedin_seite_app' THEN 'Unternehmensseite verbinden' ELSE 'Mit LinkedIn verbinden' END || '“ weitermachen.';
    END IF;
  ELSIF p_aktion = 'linkedin_trennen' THEN
    PERFORM ally_nutzer_token_setzen(s.matrix_user_id, 'linkedin_token', '');   -- Migration 187a: auch das verschlüsselte Token
    DELETE FROM ally_nutzer_einstellungen WHERE matrix_user_id = s.matrix_user_id
      AND schluessel IN ('linkedin_token', 'linkedin_ablauf', 'linkedin_name', 'linkedin_sub', 'linkedin_konto', 'linkedin_state');
    ok := true; m := 'LinkedIn-Verbindung getrennt. ' || produkt_name() || ' postet für dich nicht mehr auf dein Profil.';
  ELSIF p_aktion = 'linkedin_seite_trennen' THEN
    IF NOT adm THEN m := 'Die Unternehmensseite trennen Admins.';
    ELSE
      PERFORM ally_token_setzen('linkedin_seite_token', '', s.matrix_user_id);   -- Migration 187a: auch das verschlüsselte Token
      DELETE FROM ally_einstellungen WHERE schluessel IN ('linkedin_seite_token', 'linkedin_seite_ablauf', 'linkedin_seite_org', 'linkedin_seite_name', 'linkedin_seite_von');
      ok := true; m := 'Unternehmensseite getrennt. ' || produkt_name() || ' postet dort nicht mehr.';
    END IF;
  ELSE
    m := 'Unbekannte Aktion.';
  END IF;
  UPDATE ally_web_sitzungen SET flash = m, flash_art = CASE WHEN ok THEN 'ok' ELSE 'fehler' END WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', ok, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.linkedin_web_stand(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE s record; ablauf text; sab text; adm boolean;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN RETURN NULL; END IF;
  adm := ally_hat_recht(s.matrix_user_id, 'admin');
  ablauf := ally_nutzer_wert(s.matrix_user_id, 'linkedin_ablauf');
  sab := linkedin_wert('linkedin_seite_ablauf');
  RETURN jsonb_build_object(
    'app', linkedin_wert('linkedin_client_id') <> '' AND ally_geheim_vorhanden('linkedin_client_secret'),   -- Migration 186
    'admin', adm,
    'client_id', CASE WHEN adm THEN linkedin_wert('linkedin_client_id') ELSE '' END,
    'verbunden', ally_nutzer_token_vorhanden(s.matrix_user_id, 'linkedin_token'),   -- Migration 187a
    'name', coalesce(ally_nutzer_wert(s.matrix_user_id, 'linkedin_name'), ''),
    'bis', CASE WHEN ablauf ~ '^\d{4}-\d{2}-\d{2}' THEN to_char(ablauf::timestamptz AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY') ELSE '' END,
    'abgelaufen', CASE WHEN ablauf ~ '^\d{4}-\d{2}-\d{2}' THEN ablauf::timestamptz < now() ELSE false END,
    'seite_app', linkedin_wert('linkedin_seite_client_id') <> '' AND ally_geheim_vorhanden('linkedin_seite_client_secret'),
    'seite_client_id', CASE WHEN adm THEN linkedin_wert('linkedin_seite_client_id') ELSE '' END,
    'seite_verbunden', ally_token_vorhanden('linkedin_seite_token'),
    'seite_name', linkedin_wert('linkedin_seite_name'),
    'seite_bis', CASE WHEN sab ~ '^\d{4}-\d{2}-\d{2}' THEN to_char(sab::timestamptz AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY') ELSE '' END,
    'seite_abgelaufen', CASE WHEN sab ~ '^\d{4}-\d{2}-\d{2}' THEN sab::timestamptz < now() ELSE false END);
END $function$
;

CREATE OR REPLACE FUNCTION public.linkedin_wert(p_schluessel text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((SELECT wert FROM ally_einstellungen WHERE schluessel = p_schluessel), '');
$function$
;

CREATE OR REPLACE FUNCTION public.linkedin_zurueck(p_token text, p_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE s record; k text; seite boolean;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF coalesce(p_state, '') !~ '^[0-9a-f]{48}$' THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true); END IF;
  DELETE FROM ally_nutzer_einstellungen WHERE matrix_user_id = s.matrix_user_id AND schluessel IN ('linkedin_state', 'linkedin_seite_state') AND wert = p_state
    AND geaendert_am > now() - interval '15 minutes'
  RETURNING schluessel INTO k;
  IF k IS NULL THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true); END IF;
  seite := k = 'linkedin_seite_state';
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'art', CASE WHEN seite THEN 'seite' ELSE 'profil' END,
    'client_id', linkedin_wert(CASE WHEN seite THEN 'linkedin_seite_client_id' ELSE 'linkedin_client_id' END),
    -- Migration 186: entschlüsselt nur für den Code-Tausch in ALLY 12 (dort ohne gespeicherte Ausführungsdaten)
    'client_secret', ally_geheim(CASE WHEN seite THEN 'linkedin_seite_client_secret' ELSE 'linkedin_client_secret' END),
    'firma', coalesce(eigenes_unternehmen()->>'name', ''));
END $function$
;

CREATE OR REPLACE FUNCTION public.mail_einordnung_aktion(p_postfach text, p_kategorie text)
 RETURNS TABLE(aktion text, ziel_ordner text)
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 95 (22.10.2026): Zielordner gegen die vom Server eingelesene Ordnerliste des Postfachs auflösen.
  -- Zurück kommt der Pfad genau so, wie der Server ihn führt (Trennzeichen „/“ oder „.“ und Groß-/Kleinschreibung aus der Liste).
  -- Fehlt er in der Liste, gilt ordner_fehlt; MAIL 2 liest dann die Liste einmal neu ein (MAIL 5) und prüft erneut.
  WITH p AS (SELECT * FROM ally_postfaecher WHERE adresse = lower(trim(coalesce(p_postfach, '')))),
  e AS (SELECT (SELECT eigene_einordnung FROM p) IS TRUE AS eigen, (SELECT einordnung->>p_kategorie FROM p) AS wert),
  g AS (SELECT k.aktion, k.ziel_ordner FROM mail_kategorien k WHERE k.kategorie_key = p_kategorie AND k.aktiv LIMIT 1),
  w AS (
    SELECT CASE WHEN e.eigen THEN CASE WHEN e.wert = 'hinweis' THEN 'notify_matrix' WHEN e.wert LIKE 'ordner:_%' THEN 'move_folder' END
                ELSE (SELECT aktion FROM g) END AS aktion,
           CASE WHEN e.eigen THEN CASE WHEN e.wert LIKE 'ordner:_%' THEN substr(e.wert, 8) END
                ELSE (SELECT ziel_ordner FROM g) END AS ziel
    FROM e
  ),
  l AS (SELECT pp.ordner FROM postfach_plaetze pp WHERE pp.adresse = lower(trim(coalesce(p_postfach, '')))
          AND jsonb_typeof(pp.ordner) = 'array' AND jsonb_array_length(pp.ordner) > 0 LIMIT 1),
  r AS (
    SELECT w.aktion, w.ziel, EXISTS (SELECT 1 FROM l) AS liste,
           (SELECT o FROM l, jsonb_array_elements_text(l.ordner) o WHERE o = w.ziel LIMIT 1) AS genau,
           (SELECT o FROM l, jsonb_array_elements_text(l.ordner) o
             WHERE lower(translate(o, '.', '/')) = lower(translate(coalesce(w.ziel, ''), '.', '/')) ORDER BY o LIMIT 1) AS gleich
    FROM w
  )
  SELECT CASE WHEN r.aktion = 'move_folder' AND r.liste AND coalesce(r.genau, r.gleich) IS NULL THEN 'ordner_fehlt' ELSE r.aktion END,
         CASE WHEN r.aktion = 'move_folder' THEN coalesce(r.genau, r.gleich, r.ziel) ELSE r.ziel END
  FROM r;
$function$
;

CREATE OR REPLACE FUNCTION public.mail_regel_loeschen(p_user text, p_muster text, p_postfach text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v text := lower(trim(both '@ ' from coalesce(p_muster, '')));
  pf text := lower(trim(coalesce(p_postfach, '')));
  n int;
  liste text;
BEGIN
  IF NOT ally_hat_recht(p_user, 'absender_regeln') THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Dafür fehlt das Recht „Absender-Regeln verwalten“. Es vergibt eine Person mit der Rolle Admin.');
  END IF;
  -- Migration 90: Regeln persönlicher Postfächer nur von der Person, der sie gehören
  IF pf NOT IN ('', 'alle') AND EXISTS (SELECT 1 FROM ally_postfaecher WHERE lower(adresse) = pf AND art = 'persoenlich' AND eigentuemer IS DISTINCT FROM p_user) THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Regeln für das persönliche Postfach einer anderen Person lassen sich nicht löschen.');
  END IF;
  -- Migration 128 (E13): nicht löschen, sondern in den Papierkorb legen
  -- Prüfung 128 (B1): ohne Postfach (Chat) nur Regeln, die die Person sehen darf – Regeln persönlicher Postfächer anderer weder zählen noch nennen noch verschieben
  IF pf = '' THEN
    SELECT count(*), string_agg(coalesce(r.postfach, 'alle'), ', ' ORDER BY r.postfach NULLS FIRST) INTO n, liste FROM mail_absender_regeln r WHERE r.muster = v
       AND NOT EXISTS (SELECT 1 FROM ally_postfaecher px WHERE lower(px.adresse) = lower(r.postfach) AND px.art = 'persoenlich' AND px.eigentuemer IS DISTINCT FROM p_user);
    IF n > 1 THEN
      RETURN jsonb_build_object('ok', false, 'meldung', 'Für ' || v || ' gibt es mehrere Regeln (' || liste || '). Bitte das Postfach angeben, „alle“ für die gemeinsame Regel.');
    END IF;
    WITH weg AS (DELETE FROM mail_absender_regeln r WHERE r.muster = v
       AND NOT EXISTS (SELECT 1 FROM ally_postfaecher px WHERE lower(px.adresse) = lower(r.postfach) AND px.art = 'persoenlich' AND px.eigentuemer IS DISTINCT FROM p_user) RETURNING r.*)
    INSERT INTO mail_absender_regeln_papierkorb (muster, kategorie_key, notiz, quelle, postfach, regel_updated_at, geloescht_von)
    SELECT muster, kategorie_key, notiz, quelle, postfach, updated_at, p_user FROM weg;
  ELSE
    WITH weg AS (DELETE FROM mail_absender_regeln WHERE muster = v AND lower(coalesce(postfach, 'alle')) = pf RETURNING *)
    INSERT INTO mail_absender_regeln_papierkorb (muster, kategorie_key, notiz, quelle, postfach, regel_updated_at, geloescht_von)
    SELECT muster, kategorie_key, notiz, quelle, postfach, updated_at, p_user FROM weg;
  END IF;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n = 0 THEN RETURN jsonb_build_object('ok', false, 'meldung', 'Regel nicht gefunden.'); END IF;
  RETURN jsonb_build_object('ok', true, 'meldung', 'Regel für ' || v || CASE WHEN pf NOT IN ('', 'alle') THEN ' (nur ' || pf || ')' ELSE '' END
    || ' in den Papierkorb gelegt. Dort kannst du sie wiederherstellen oder endgültig löschen.');
END $function$
;

CREATE OR REPLACE FUNCTION public.mail_regel_papierkorb(p_user text, p_was text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  x record; n int;
BEGIN
  -- Migration 128: Papierkorb der Absender-Regeln. Regeln persönlicher Postfächer anderer Personen sind nicht sichtbar und bleiben unberührt.
  IF NOT ally_hat_recht(p_user, 'absender_regeln') THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Dafür fehlt das Recht „Absender-Regeln verwalten“. Es vergibt eine Person mit der Rolle Admin.');
  END IF;
  IF p_was = 'regel_papierkorb_leeren' THEN
    -- wie der Papierkorb der Verkaufsberichte: gelöscht wird genau, was beim Öffnen der Warnung im Papierkorb lag (ids), nichts, was inzwischen dazukam
    IF coalesce(p_id, '') !~ '^[0-9]{1,18}(,[0-9]{1,18})*$' OR cardinality(string_to_array(p_id, ',')) > 1000 THEN
      RETURN jsonb_build_object('ok', false, 'meldung', 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.');
    END IF;
    DELETE FROM mail_absender_regeln_papierkorb k
     WHERE k.id = ANY (string_to_array(p_id, ',')::bigint[])
       AND NOT EXISTS (SELECT 1 FROM ally_postfaecher px WHERE lower(px.adresse) = lower(k.postfach) AND px.art = 'persoenlich' AND px.eigentuemer IS DISTINCT FROM p_user);
    GET DIAGNOSTICS n = ROW_COUNT;
    RETURN jsonb_build_object('ok', true, 'anzahl', n, 'meldung', CASE WHEN n = 0 THEN 'Diese Regeln liegen nicht mehr im Papierkorb.' WHEN n = 1 THEN '1 Regel endgültig gelöscht.'
      ELSE n || ' Regeln endgültig gelöscht.' END);
  END IF;
  IF p_was NOT IN ('regel_wiederherstellen', 'regel_endgueltig') THEN RETURN jsonb_build_object('ok', false, 'meldung', 'Unbekannte Aktion.'); END IF;
  IF coalesce(p_id, '') !~ '^[0-9]{1,18}$' THEN RETURN jsonb_build_object('ok', false, 'meldung', 'Diese Regel liegt nicht mehr im Papierkorb.'); END IF;
  SELECT * INTO x FROM mail_absender_regeln_papierkorb k WHERE k.id = p_id::bigint FOR UPDATE;
  IF NOT FOUND OR EXISTS (SELECT 1 FROM ally_postfaecher px WHERE lower(px.adresse) = lower(x.postfach) AND px.art = 'persoenlich' AND px.eigentuemer IS DISTINCT FROM p_user) THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Diese Regel liegt nicht mehr im Papierkorb.');
  END IF;
  IF p_was = 'regel_endgueltig' THEN
    DELETE FROM mail_absender_regeln_papierkorb WHERE id = x.id;
    RETURN jsonb_build_object('ok', true, 'meldung', 'Regel für ' || x.muster || ' endgültig gelöscht.');
  END IF;
  -- wiederherstellen: nur, wenn es für Absender und Postfach keine neue Regel gibt und das Postfach noch angebunden ist
  IF EXISTS (SELECT 1 FROM mail_absender_regeln r WHERE r.muster = x.muster AND coalesce(r.postfach, '') = coalesce(x.postfach, '')) THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Für ' || x.muster || ' gibt es inzwischen eine neue Regel' || CASE WHEN x.postfach IS NOT NULL THEN ' (nur ' || x.postfach || ')' ELSE '' END
      || '. Die Regel im Papierkorb lässt sich deshalb nicht wiederherstellen.');
  END IF;
  IF x.postfach IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_postfaecher WHERE lower(adresse) = lower(x.postfach)) THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Das Postfach ' || x.postfach || ' ist nicht mehr angebunden. Die Regel lässt sich deshalb nicht wiederherstellen.');
  END IF;
  INSERT INTO mail_absender_regeln (muster, kategorie_key, notiz, quelle, postfach, updated_at)
  VALUES (x.muster, x.kategorie_key, x.notiz, x.quelle, x.postfach, coalesce(x.regel_updated_at, now()));
  DELETE FROM mail_absender_regeln_papierkorb WHERE id = x.id;
  RETURN jsonb_build_object('ok', true, 'meldung', 'Regel für ' || x.muster || ' wiederhergestellt.');
END $function$
;

CREATE OR REPLACE FUNCTION public.mail_regel_speichern(p_user text, p_muster text, p_kategorie text, p_notiz text, p_postfach text, p_quelle text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v text := lower(trim(both '@ ' from coalesce(p_muster, '')));
  pf text := lower(trim(coalesce(p_postfach, '')));
BEGIN
  IF pf IN ('', 'alle') THEN pf := NULL; END IF;
  IF NOT ally_hat_recht(p_user, 'absender_regeln') THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Dafür fehlt das Recht „Absender-Regeln verwalten“. Es vergibt eine Person mit der Rolle Admin.');
  ELSIF v = '' OR v !~ '^[a-z0-9._%+\-]*@?[a-z0-9.\-]+\.[a-z]{2,}$' THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Bitte eine Domain (z. B. canva.com) oder Mailadresse angeben.');
  ELSIF EXISTS (SELECT 1 FROM ally_postfaecher px WHERE split_part(px.adresse, '@', 2) <> ''
        AND (v = split_part(px.adresse, '@', 2) OR v LIKE '%.' || split_part(px.adresse, '@', 2) OR split_part(v, '@', 2) = split_part(px.adresse, '@', 2))) THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Regeln für die Domain eines eigenen Postfachs sind nicht erlaubt, sie würden alle Formularanfragen treffen.');
  ELSIF coalesce(p_kategorie, '') NOT IN ('keine', 'geschaeft', 'kunde', 'spam', 'system_report') THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Bitte eine Kategorie wählen: keine, geschaeft, kunde, spam oder system_report.');
  ELSIF pf IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_postfaecher WHERE adresse = pf) THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Das Postfach ' || pf || ' ist nicht angebunden.');
  -- Migration 90: Regeln für ein persönliches Postfach nur von der Person, der es gehört
  ELSIF pf IS NOT NULL AND EXISTS (SELECT 1 FROM ally_postfaecher WHERE adresse = pf AND art = 'persoenlich' AND eigentuemer IS DISTINCT FROM p_user) THEN
    RETURN jsonb_build_object('ok', false, 'meldung', 'Für das persönliche Postfach einer anderen Person lassen sich keine Regeln anlegen.');
  END IF;
  INSERT INTO mail_absender_regeln (muster, kategorie_key, notiz, quelle, postfach)
  VALUES (v, p_kategorie, nullif(trim(coalesce(p_notiz, '')), ''), coalesce(nullif(p_quelle, ''), 'web'), pf)
  ON CONFLICT (muster, (coalesce(postfach, ''))) DO UPDATE SET kategorie_key = EXCLUDED.kategorie_key, notiz = EXCLUDED.notiz, quelle = EXCLUDED.quelle, updated_at = now();
  RETURN jsonb_build_object('ok', true, 'muster', v, 'kategorie', p_kategorie, 'postfach', coalesce(pf, 'alle'),
    'meldung', 'Regel für ' || v || ' gespeichert (' || CASE WHEN pf IS NULL THEN 'alle Postfächer' ELSE 'nur ' || pf END || ').');
END $function$
;

CREATE OR REPLACE FUNCTION public.marketing_papierkorb(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; u text; e marketing_papierkorb%ROWTYPE; th marketing_themen%ROWTYPE;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  m text := NULL; fehler text := NULL; n integer := 0; ids bigint[]; mit_ordner bigint[]; auf uuid; weiter text := NULL;
BEGIN
  -- Migration 133: Papierkorb der Marketing-Themen (Seite Marketing › Papierkorb). Nur eigene Einträge (Themen gehören einer Person).
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', true); END IF;
  u := s.matrix_user_id;
  IF NOT plattform_modul_an('marketing') THEN
    fehler := 'Das Paket Marketing ist nicht gebucht.';
  ELSIF p_aktion = 'mk_papierkorb_wiederherstellen' THEN
    IF coalesce(d->>'id', '') ~ '^[0-9]{1,18}$' THEN SELECT * INTO e FROM marketing_papierkorb x WHERE x.id = (d->>'id')::bigint AND x.matrix_user_id = u FOR UPDATE; END IF;
    IF e.id IS NULL THEN
      fehler := 'Dieses Thema liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.';
    ELSIF marketing_pk_im_auftrag(e.id) THEN
      fehler := '„' || e.titel || '“ wird gerade endgültig gelöscht. Bitte die Seite neu laden.';
    ELSIF EXISTS (SELECT 1 FROM marketing_themen t WHERE t.id = e.thema_id) THEN
      fehler := 'Dieses Thema gibt es schon wieder. Bitte die Seite neu laden.';
    ELSE
      INSERT INTO marketing_themen SELECT (jsonb_populate_record(NULL::marketing_themen, e.daten->'thema')).*;
      -- Geplante Posts kommen nie geplant zurück: storniert, neu freigeben (Koordinator 23.10.2026)
      SELECT count(*) INTO n FROM jsonb_array_elements(coalesce(e.daten->'posts', '[]')) p WHERE p->>'status' IN ('freigegeben', 'in_arbeit');
      INSERT INTO marketing_posts
      SELECT (jsonb_populate_record(NULL::marketing_posts, p || CASE WHEN p->>'status' IN ('freigegeben', 'in_arbeit')
               THEN jsonb_build_object('status', 'storniert', 'medien_token', NULL, 'geaendert_am', now()) ELSE '{}'::jsonb END)).*
      FROM jsonb_array_elements(coalesce(e.daten->'posts', '[]')) p
      ON CONFLICT DO NOTHING;
      DELETE FROM marketing_papierkorb WHERE id = e.id;
      m := '„' || e.titel || '“ wiederhergestellt.'
        || CASE WHEN n = 1 THEN ' 1 Post ist wieder da und muss neu freigegeben werden.' WHEN n > 1 THEN ' ' || n || ' Posts sind wieder da und müssen neu freigegeben werden.' ELSE '' END;
    END IF;
  ELSIF p_aktion IN ('mk_papierkorb_endgueltig', 'mk_papierkorb_leeren') THEN
    IF p_aktion = 'mk_papierkorb_endgueltig' AND coalesce(d->>'id', '') ~ '^[0-9]{1,18}$' THEN
      ids := ARRAY[(d->>'id')::bigint];
    ELSIF p_aktion = 'mk_papierkorb_leeren' AND coalesce(d->>'ids', '') ~ '^[0-9]{1,18}(,[0-9]{1,18})*$' AND cardinality(string_to_array(d->>'ids', ',')) <= 1000 THEN
      ids := string_to_array(d->>'ids', ',')::bigint[];
    END IF;
    -- M1: Einträge in einem offenen Löschauftrag nicht noch einmal
    SELECT count(*) INTO n FROM marketing_papierkorb x WHERE x.id = ANY (coalesce(ids, '{}')) AND x.matrix_user_id = u AND marketing_pk_im_auftrag(x.id);
    ids := ARRAY(SELECT x.id FROM marketing_papierkorb x WHERE x.id = ANY (coalesce(ids, '{}')) AND x.matrix_user_id = u AND NOT marketing_pk_im_auftrag(x.id) ORDER BY x.id FOR UPDATE);
    IF cardinality(ids) = 0 AND n > 0 THEN
      fehler := CASE WHEN n = 1 THEN 'Das Thema wird gerade endgültig gelöscht. Bitte die Seite neu laden.' ELSE 'Diese Themen werden gerade endgültig gelöscht. Bitte die Seite neu laden.' END;
    ELSIF cardinality(ids) = 0 THEN
      fehler := CASE WHEN p_aktion = 'mk_papierkorb_leeren' THEN 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.' ELSE 'Dieses Thema liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.' END;
    ELSE
      -- ohne Ordner sofort; mit Ordner über den Löschauftrag (ALLY 37, SPEICHER 1)
      DELETE FROM marketing_papierkorb x WHERE x.id = ANY (ids) AND x.ordner IS NULL;
      GET DIAGNOSTICS n = ROW_COUNT;
      mit_ordner := ARRAY(SELECT x.id FROM marketing_papierkorb x WHERE x.id = ANY (ids) ORDER BY x.id);
      IF cardinality(mit_ordner) = 0 THEN
        m := CASE WHEN n = 1 THEN '1 Thema endgültig gelöscht.' ELSE n || ' Themen endgültig gelöscht.' END;
      ELSE
        INSERT INTO marketing_pk_loeschauftraege (token_hash, matrix_user_id, ids, sofort) VALUES (s.token_hash, u, mit_ordner, n) RETURNING auftrag INTO auf;
        weiter := 'mk_papierkorb';
      END IF;
    END IF;
  ELSIF p_aktion = 'mk_papierkorb_entfernen' THEN
    -- Aus dem Papierkorb entfernen, Ordner bleibt (Koordinator 24.10.2026): nur bei nicht erkanntem Ordner und ohne offenen Löschauftrag; im Speicherort wird nichts angefasst
    IF coalesce(d->>'id', '') ~ '^[0-9]{1,18}$' THEN SELECT * INTO e FROM marketing_papierkorb x WHERE x.id = (d->>'id')::bigint AND x.matrix_user_id = u FOR UPDATE; END IF;
    IF e.id IS NULL THEN
      fehler := 'Dieses Thema liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.';
    ELSIF marketing_pk_im_auftrag(e.id) THEN
      fehler := '„' || e.titel || '“ wird gerade endgültig gelöscht. Bitte die Seite neu laden.';
    ELSIF e.ordner IS NULL OR (marketing_pk_pfad_ok(e.ordner, e.thema_id) AND e.stand IS DISTINCT FROM 'nicht_erkannt') THEN
      fehler := 'Entfernen ohne Ordner geht nur, wenn der Ordner nicht eindeutig erkannt ist. Bitte „Endgültig löschen“ verwenden.';
    ELSE
      DELETE FROM marketing_papierkorb WHERE id = e.id;
      m := '„' || e.titel || '“ ist aus dem Papierkorb entfernt. Der Ordner „' || e.ordner || '“ bleibt im Speicherort; Ally kennt ihn nicht mehr.';
    END IF;
  ELSE
    fehler := 'Diese Aktion gibt es nicht.';
  END IF;
  IF weiter IS NULL THEN
    PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
    RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'weiter', weiter, 'auftrag', auf::text, 'ids', to_jsonb(mit_ordner));
END $function$
;

CREATE OR REPLACE FUNCTION public.marketing_pk_abschliessen(p_token text, p_auftrag text, p_ergebnis jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; a marketing_pk_loeschauftraege%ROWTYPE; e record; r jsonb; n_weg integer := 0; n_fehlte integer := 0; rest text[] := '{}'; m text; st text;
BEGIN
  -- Migration 133 (ALLY 37, nach allen Ordnern): entfernt nur Einträge, die in diesem Auftrag freigegeben wurden (G5) und deren Ordner gelöscht ist oder schon fehlte;
  -- die anderen bleiben mit Grund und Stand im Papierkorb. p_ergebnis: [{id?, pfad?, status: geloescht | fehlte | gesperrt | nicht_erkannt | fehler, fehler?}].
  -- Die Meldung unterscheidet gelöscht, „Ordner fehlte bereits“ und „bleibt“ (G4).
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF coalesce(p_auftrag, '') ~ '^[0-9a-f-]{36}$' THEN SELECT * INTO a FROM marketing_pk_loeschauftraege x WHERE x.auftrag = p_auftrag::uuid FOR UPDATE; END IF;
  IF a.auftrag IS NULL OR a.token_hash <> s.token_hash OR a.abgeschlossen_am IS NOT NULL THEN
    PERFORM ally_web_meldung(p_token, 'Der Löschauftrag ist nicht mehr gültig. Bitte die Seite neu laden.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  UPDATE marketing_pk_loeschauftraege SET abgeschlossen_am = now() WHERE auftrag = a.auftrag;
  FOR e IN SELECT x.* FROM marketing_papierkorb x WHERE x.id = ANY (a.ids) AND x.matrix_user_id = a.matrix_user_id FOR UPDATE LOOP
    SELECT y INTO r FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_ergebnis) = 'array' THEN p_ergebnis ELSE '[]'::jsonb END) y
      WHERE y->>'id' = e.id::text OR (y->>'pfad' = e.ordner AND y->>'id' IS NULL)
      ORDER BY CASE y->>'status' WHEN 'gesperrt' THEN 0 WHEN 'fehler' THEN 1 WHEN 'nicht_erkannt' THEN 2 ELSE 3 END LIMIT 1;
    st := r->>'status';
    -- nur freigegeben (G5) und nur ein als Themenordner erkannter Pfad zählt als gelöscht bzw. fehlend
    IF st IN ('geloescht', 'fehlte') AND e.id = ANY (a.frei) AND marketing_pk_pfad_ok(e.ordner, e.thema_id) THEN
      DELETE FROM marketing_papierkorb WHERE id = e.id;
      IF st = 'geloescht' THEN n_weg := n_weg + 1; ELSE n_fehlte := n_fehlte + 1; END IF;
    ELSE
      st := CASE WHEN st IN ('gesperrt', 'nicht_erkannt', 'fehler') THEN st ELSE 'fehler' END;
      UPDATE marketing_papierkorb SET stand = st, grund = left(coalesce(nullif(r->>'fehler', ''), CASE st
          WHEN 'nicht_erkannt' THEN 'Der Speicherort meldet unter „' || e.ordner || '“ keinen eindeutigen Ordner. Nichts gelöscht.'
          ELSE 'Der Ordner wurde nicht gelöscht.' END), 300) WHERE id = e.id;
      rest := rest || ('„' || e.titel || '“: ' || left(coalesce(nullif(r->>'fehler', ''), CASE st
          WHEN 'nicht_erkannt' THEN 'kein eindeutiger Ordner im Speicherort' ELSE 'Ordner nicht gelöscht' END), 200));
    END IF;
  END LOOP;
  m := CASE WHEN n_weg = 0 THEN '' WHEN n_weg = 1 THEN '1 Thema endgültig gelöscht, samt Ordner im Speicherort. ' ELSE n_weg || ' Themen endgültig gelöscht, samt Ordnern im Speicherort. ' END
    || CASE WHEN n_fehlte = 0 THEN '' WHEN n_fehlte = 1 THEN '1 Thema endgültig gelöscht; sein Ordner fehlte bereits im Speicherort. '
            ELSE n_fehlte || ' Themen endgültig gelöscht; ihre Ordner fehlten bereits im Speicherort. ' END
    || CASE WHEN a.sofort = 0 THEN '' WHEN a.sofort = 1 THEN '1 Thema ohne Ordner endgültig gelöscht. ' ELSE a.sofort || ' Themen ohne Ordner endgültig gelöscht. ' END
    || CASE WHEN cardinality(rest) = 0 THEN '' WHEN cardinality(rest) = 1 THEN 'Bleibt im Papierkorb – ' || rest[1]
            ELSE cardinality(rest) || ' bleiben im Papierkorb – ' || array_to_string(rest[1:3], '; ') || CASE WHEN cardinality(rest) > 3 THEN ' …' ELSE '' END END;
  PERFORM ally_web_meldung(p_token, coalesce(nullif(btrim(m), ''), 'Nichts gelöscht.'), CASE WHEN cardinality(rest) = 0 THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', cardinality(rest) = 0, 'angemeldet', true, 'geloescht', n_weg + n_fehlte + a.sofort, 'bleiben', cardinality(rest));
END $function$
;

CREATE OR REPLACE FUNCTION public.marketing_pk_freigeben(p_token text, p_auftrag text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE s record; a marketing_pk_loeschauftraege%ROWTYPE; e marketing_papierkorb%ROWTYPE;
BEGIN
  -- Migration 133 (ALLY 37, je Ordner unmittelbar vor dem Prüfen und Löschen): Sitzung und Löschauftrag gültig, Eintrag gehört dazu und der Person,
  -- Ordner eindeutig ein Themenordner dieses Themas im erwarteten Pfad (marketing_pk_pfad_ok) und von keinem anderen Thema benutzt.
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('frei', false, 'grund', 'Nicht angemeldet.'); END IF;
  IF coalesce(p_auftrag, '') ~ '^[0-9a-f-]{36}$' THEN SELECT * INTO a FROM marketing_pk_loeschauftraege x WHERE x.auftrag = p_auftrag::uuid; END IF;
  IF a.auftrag IS NULL OR a.token_hash <> s.token_hash OR a.matrix_user_id <> s.matrix_user_id OR a.gueltig_bis < now() OR a.abgeschlossen_am IS NOT NULL THEN
    RETURN jsonb_build_object('frei', false, 'grund', 'Der Löschauftrag ist nicht mehr gültig. Bitte erneut löschen.');
  END IF;
  IF coalesce(p_id, '') ~ '^[0-9]{1,18}$' AND p_id::bigint = ANY (a.ids) THEN
    SELECT * INTO e FROM marketing_papierkorb x WHERE x.id = p_id::bigint AND x.matrix_user_id = a.matrix_user_id FOR UPDATE;
  END IF;
  IF e.id IS NULL THEN RETURN jsonb_build_object('frei', false, 'id', p_id, 'grund', 'Liegt nicht mehr im Papierkorb.'); END IF;
  IF NOT marketing_pk_pfad_ok(e.ordner, e.thema_id) THEN
    RETURN jsonb_build_object('frei', false, 'id', e.id, 'grund', 'Der Ordner „' || coalesce(e.ordner, '') || '“ ist nicht eindeutig als Themenordner erkannt und wird nicht gelöscht. Bitte im Speicherort prüfen.');
  END IF;
  -- G2: auch ein lebendes Thema mit einem übergeordneten Ordner sperrt
  IF EXISTS (SELECT 1 FROM marketing_themen t WHERE t.ordner = e.ordner OR t.ordner LIKE e.ordner || '/%' OR e.ordner LIKE t.ordner || '/%') THEN
    RETURN jsonb_build_object('frei', false, 'id', e.id, 'grund', 'Ein anderes Thema benutzt den Ordner „' || e.ordner || '“. Er wird nicht gelöscht.');
  END IF;
  -- G5: nur in diesem Auftrag freigegebene Einträge nimmt der Abschluss als gelöscht an
  UPDATE marketing_pk_loeschauftraege SET frei = frei || e.id WHERE auftrag = a.auftrag AND NOT e.id = ANY (frei);
  RETURN jsonb_build_object('frei', true, 'id', e.id, 'pfad', e.ordner);
END $function$
;

CREATE OR REPLACE FUNCTION public.marketing_pk_im_auftrag(p_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 133 (Prüfung M1): Liegt der Eintrag in einem offenen Löschauftrag (bis gueltig_bis + 5 Minuten Spielraum für ein DELETE kurz nach Ablauf)?
  SELECT EXISTS (SELECT 1 FROM marketing_pk_loeschauftraege a WHERE p_id = ANY (a.ids) AND a.abgeschlossen_am IS NULL AND a.gueltig_bis > now() - interval '5 minutes')
$function$
;

CREATE OR REPLACE FUNCTION public.marketing_pk_legen(p_thema integer, p_u text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE th marketing_themen%ROWTYPE; neu bigint;
BEGIN
  -- Migration 133: Thema mit seinen Posts als Schnappschuss in den Papierkorb, Zeilen entfernen. Rechte und Sperren prüft der Aufrufer.
  SELECT * INTO th FROM marketing_themen WHERE id = p_thema AND matrix_user_id = p_u FOR UPDATE;
  IF th.id IS NULL THEN RETURN NULL; END IF;
  INSERT INTO marketing_papierkorb (thema_id, matrix_user_id, titel, ordner, daten, geloescht_von)
  VALUES (th.id, th.matrix_user_id, th.titel, th.ordner,
          jsonb_build_object('thema', to_jsonb(th), 'posts', (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id), '[]'::jsonb) FROM marketing_posts p WHERE p.thema_id = th.id)), p_u)
  RETURNING id INTO neu;
  DELETE FROM marketing_posts WHERE thema_id = th.id;
  DELETE FROM marketing_themen WHERE id = th.id;
  RETURN neu;
END $function$
;

CREATE OR REPLACE FUNCTION public.marketing_pk_liste(p_u text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 133: die eigenen Themen im Papierkorb (neueste zuerst) mit Zahlen genau aus dem Schnappschuss.
  -- ordner_erkannt: Ordner im erwarteten Pfad (wird beim endgültigen Löschen gelöscht); wird_geloescht: in einem offenen Löschauftrag (M1);
  -- entfernbar: Ordner nicht erkannt (Pfad oder letzter Versuch) und kein offener Auftrag – „Aus dem Papierkorb entfernen, Ordner bleibt“.
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'titel', e.titel, 'ordner', e.ordner, 'grund', e.grund, 'stand', e.stand,
      'ordner_erkannt', e.ordner IS NOT NULL AND marketing_pk_pfad_ok(e.ordner, e.thema_id),
      'wird_geloescht', marketing_pk_im_auftrag(e.id),
      'entfernbar', coalesce(e.ordner IS NOT NULL AND (NOT marketing_pk_pfad_ok(e.ordner, e.thema_id) OR e.stand = 'nicht_erkannt') AND NOT marketing_pk_im_auftrag(e.id), false),  -- H1
      'geloescht', to_char(e.geloescht_am AT TIME ZONE 'Europe/Berlin', 'FMDD.FMMM.YYYY'),
      'status', e.daten->'thema'->>'status',
      'posts', jsonb_array_length(coalesce(e.daten->'posts', '[]')),
      'geplant', (SELECT count(*) FROM jsonb_array_elements(coalesce(e.daten->'posts', '[]')) p WHERE p->>'status' IN ('freigegeben', 'in_arbeit')),
      'gepostet', (SELECT count(*) FROM jsonb_array_elements(coalesce(e.daten->'posts', '[]')) p WHERE p->>'status' = 'gepostet'))
    ORDER BY e.geloescht_am DESC, e.id DESC), '[]'::jsonb)
  FROM marketing_papierkorb e WHERE e.matrix_user_id = p_u
$function$
;

CREATE OR REPLACE FUNCTION public.marketing_pk_pfad_ok(p_pfad text, p_thema integer)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 133: Ist der Pfad eindeutig ein Themenordner dieses Themas? …/<JJJJ-MM oder _Verworfen>/<JJJJ-MM-TT>_thema-<Nummer>_<Name>,
  -- relativ, höchstens 1000 Zeichen, Teile höchstens 255 Zeichen, keine leeren/„.“/„..“-Teile, keine Steuer- oder Platzhalterzeichen (Regeln von SPEICHER 1),
  -- kein Teil mit Leerzeichen am Anfang oder Ende (Prüfung G3: SPEICHER 1 kürzt sonst den Pfad).
  SELECT p_pfad IS NOT NULL AND length(p_pfad) <= 1000 AND left(p_pfad, 1) <> '/' AND position(E'\\' IN p_pfad) = 0
    AND p_pfad !~ '[[:cntrl:]*?{}]'
    AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(p_pfad, '/')) t WHERE t IN ('', '.', '..') OR length(t) > 255 OR t ~ '^[[:space:]]|[[:space:]]$')
    AND cardinality(string_to_array(p_pfad, '/')) >= 3
    AND (string_to_array(p_pfad, '/'))[cardinality(string_to_array(p_pfad, '/')) - 1] ~ '^([0-9]{4}-[0-9]{2}|_Verworfen)$'
    AND (string_to_array(p_pfad, '/'))[cardinality(string_to_array(p_pfad, '/'))] ~ ('^[0-9]{4}-[0-9]{2}-[0-9]{2}_thema-' || p_thema || '_')
$function$
;

CREATE OR REPLACE FUNCTION public.marketing_profil_text(p_user text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Marketing-Profil einer Person als Text fuer die KI (Seite Marketing, Teil "Für mich"). Ohne neue Felder: bisheriger Freitext.
  SELECT CASE WHEN t.themen IS NULL AND t.zielgruppe IS NULL AND t.stil IS NULL AND t.nogos IS NULL
              THEN coalesce(ally_nutzer_wert(p_user, 'marketing_profil'), '')
              ELSE concat_ws(E'\n', 'Ansprache: ' || CASE WHEN t.ansprache = 'sie' THEN 'Sie (siezen)' ELSE 'Du (duzen)' END,
                'Themen: ' || t.themen, 'Zielgruppe: ' || t.zielgruppe, 'Stil: ' || t.stil, 'No-Gos: ' || t.nogos) END
  FROM (SELECT nullif(trim(ally_nutzer_wert(p_user, 'marketing_themenfelder')), '') AS themen,
               nullif(trim(ally_nutzer_wert(p_user, 'marketing_zielgruppe')), '') AS zielgruppe,
               nullif(trim(ally_nutzer_wert(p_user, 'marketing_stil')), '') AS stil,
               nullif(trim(ally_nutzer_wert(p_user, 'marketing_nogos')), '') AS nogos,
               lower(trim(coalesce(ally_nutzer_wert(p_user, 'marketing_ansprache'), 'du'))) AS ansprache) t
$function$
;

CREATE OR REPLACE FUNCTION public.meta_adresse(p_pfad text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT rtrim(btrim(coalesce(ally_einstellung('n8n_oeffentlich'), '')), '/') || p_pfad
$function$
;

CREATE OR REPLACE FUNCTION public.meta_app_text(p_app text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Threads ergänzt (Stefan 19.10.2026), Migration 53
  SELECT CASE p_app WHEN 'facebook' THEN 'Facebook' WHEN 'instagram' THEN 'Instagram' WHEN 'threads' THEN 'Threads' ELSE p_app END
$function$
;

CREATE OR REPLACE FUNCTION public.meta_app_web_aktion(p_token text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  u text;
  m text := NULL;
  fehler text := NULL;
  aid text;
  sec text;
  alt_id text;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := s.matrix_user_id;
  aid := btrim(coalesce(d->>'app_id', ''));
  sec := btrim(coalesce(d->>'app_secret', ''));
  alt_id := btrim(ally_einstellung('meta_app_id'));
  BEGIN
    IF NOT ally_hat_recht(u, 'superadmin') THEN
      fehler := 'Das dürfen nur Superadmins.';
    ELSIF aid !~ '^[0-9]{5,20}$' THEN
      fehler := 'Bitte die App-ID von Meta angeben (nur Ziffern, steht bei Meta unter App-Einstellungen › Allgemein).';
    ELSIF sec <> '' AND (sec !~ '^[A-Za-z0-9]{16,64}$' OR sec = aid) THEN
      fehler := 'Der App-Geheimcode hat ein unerwartetes Format. Bitte bei Meta unter App-Einstellungen › Allgemein kopieren.';
    ELSIF sec <> '' AND NOT ally_verschluesselung_bereit() THEN
      fehler := 'Verschlüsselung ist nicht eingerichtet.';
    ELSE
      PERFORM ally_einstellung_setzen('meta_app_id', aid, u);
      IF sec <> '' THEN
        PERFORM ally_geheim_setzen('meta_app_secret', sec, u);
      END IF;
      m := 'Meta-App gespeichert.'
        || CASE WHEN sec <> '' THEN '' WHEN ally_geheim_vorhanden('meta_app_secret') THEN ' Der App-Geheimcode bleibt unverändert.'
                ELSE ' Es fehlt noch der App-Geheimcode.' END
        || CASE WHEN alt_id <> '' AND alt_id <> aid AND EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.status = 'verbunden' AND k.anmeldeweg = 'facebook')
                THEN ' Hinweis: Bereits verbundene Kanäle gehören zur bisherigen App und müssen neu verbunden werden.' ELSE '' END;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    fehler := CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM
                   ELSE 'Das hat nicht geklappt. Bitte noch einmal versuchen. (' || left(SQLERRM, 200) || ')' END;
  END;
  UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'fehler', fehler);
END $function$
;

CREATE OR REPLACE FUNCTION public.meta_base64url(p text)
 RETURNS bytea
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT decode(rpad(translate(rtrim(p, '='), '-_', '+/'), ((length(rtrim(p, '=')) + 3) / 4) * 4, '='), 'base64')
$function$
;

CREATE OR REPLACE FUNCTION public.meta_ig_app_web_aktion(p_token text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  u text;
  m text := NULL;
  fehler text := NULL;
  aid text;
  sec text;
  alt_id text;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := s.matrix_user_id;
  aid := btrim(coalesce(d->>'app_id', ''));
  sec := btrim(coalesce(d->>'app_secret', ''));
  alt_id := btrim(ally_einstellung('meta_ig_app_id'));
  BEGIN
    IF NOT ally_hat_recht(u, 'superadmin') THEN
      fehler := 'Das dürfen nur Superadmins.';
    ELSIF aid !~ '^[0-9]{5,20}$' THEN
      fehler := 'Bitte die Instagram-App-ID angeben (nur Ziffern, steht bei Meta im App-Dashboard unter Instagram › API-Einrichtung mit Instagram-Login).';
    ELSIF sec <> '' AND (sec !~ '^[A-Za-z0-9]{16,64}$' OR sec = aid) THEN
      fehler := 'Der Instagram-App-Geheimcode hat ein unerwartetes Format. Bitte bei Meta im App-Dashboard unter Instagram › API-Einrichtung mit Instagram-Login kopieren.';
    ELSIF sec <> '' AND NOT ally_verschluesselung_bereit() THEN
      fehler := 'Verschlüsselung ist nicht eingerichtet.';
    ELSE
      PERFORM ally_einstellung_setzen('meta_ig_app_id', aid, u);
      IF sec <> '' THEN
        PERFORM ally_geheim_setzen('meta_ig_app_secret', sec, u);
      END IF;
      -- Texte ohne "Meta-App für …" (eine Meta-App mit zwei Abschnitten) (Stefan 19.10.2026)
      m := 'Anmeldung über Instagram gespeichert.'
        || CASE WHEN sec <> '' THEN '' WHEN ally_geheim_vorhanden('meta_ig_app_secret') THEN ' Der Instagram-App-Geheimcode bleibt unverändert.'
                ELSE ' Es fehlt noch der Instagram-App-Geheimcode.' END
        || CASE WHEN alt_id <> '' AND alt_id <> aid AND EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.status = 'verbunden' AND k.anmeldeweg = 'instagram')
                THEN ' Hinweis: Die Instagram-App-ID hat sich geändert. Accounts, die bereits direkt über Instagram verbunden sind, müssen neu verbunden werden.' ELSE '' END;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    fehler := CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM
                   ELSE 'Das hat nicht geklappt. Bitte noch einmal versuchen. (' || left(SQLERRM, 200) || ')' END;
  END;
  UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'fehler', fehler);
END $function$
;

CREATE OR REPLACE FUNCTION public.meta_konten_text(p_konten jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT coalesce(string_agg(t.talent || ': ' || t.konten, '; ' ORDER BY t.talent COLLATE "C"), 'keine Angaben') FROM (
    SELECT e->>'talent' AS talent, string_agg(e->>'konto', ', ' ORDER BY (e->>'kanal_id')::integer) AS konten
    FROM jsonb_array_elements(coalesce(p_konten, '[]'::jsonb)) e GROUP BY e->>'talent') t
$function$
;

CREATE OR REPLACE FUNCTION public.meta_lauf(p_ausfuehren boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  r record;
  nachgeprueft integer := 0;
  geloescht integer := 0;
  x jsonb;
  m jsonb;
  pn text := produkt_name();
  empf jsonb := talents_admin_empfaenger();
BEGIN
  IF p_ausfuehren THEN
    FOR r IN SELECT id FROM meta_rueckmeldungen WHERE status = 'keine_daten' AND nutzer_id IS NOT NULL AND nachpruefen_bis > now() ORDER BY id LOOP
      x := meta_rueckmeldung_anwenden(r.id);
      IF (x->>'anzahl')::integer > 0 THEN nachgeprueft := nachgeprueft + 1; END IF;
    END LOOP;
    FOR r IN SELECT id FROM meta_rueckmeldungen WHERE status = 'vorgemerkt' AND loeschen_ab <= now() ORDER BY id LOOP
      x := meta_loeschung_ausfuehren(r.id);
      IF x->>'ok' = 'true' THEN geloescht := geloescht + 1; END IF;
    END LOOP;
    UPDATE meta_rueckmeldungen SET nutzer_id = NULL WHERE nutzer_id IS NOT NULL AND status = 'keine_daten' AND nachpruefen_bis <= now();
    UPDATE meta_rueckmeldungen SET konten = '[]'::jsonb
    WHERE konten <> '[]'::jsonb AND ((art = 'abmeldung' AND gemeldet_am IS NOT NULL) OR (art = 'loeschung' AND erledigt_gemeldet_am IS NOT NULL)
                                     OR eingegangen_am < now() - interval '30 days');
    DELETE FROM meta_rueckmeldungen WHERE eingegangen_am < now() - interval '365 days';
  END IF;
  SELECT coalesce(jsonb_agg(z.m ORDER BY z.id, z.rang), '[]'::jsonb) INTO m FROM (
    SELECT q.id, 1 AS rang, jsonb_build_object('id', q.id, 'art', 'eingang',
      'titel', CASE WHEN q.art = 'loeschung' THEN 'Talents: Löschung von Daten angefordert' ELSE 'Talents: Verbindung bei ' || meta_app_text(q.app) || ' entfernt' END,
      'text', CASE WHEN q.art = 'loeschung' THEN
          'Über ' || meta_app_text(q.app) || ' wurde am ' || talents_datum(q.eingegangen_am) || ' die Löschung der Daten verlangt, die ' || pn
          || ' über diese Anmeldung abgerufen hat. Betroffen: ' || meta_konten_text(q.konten) || '. Die Verbindung ist bereits getrennt, '
          || pn || ' ruft keine neuen Zahlen mehr ab. Am ' || talents_datum(q.loeschen_ab) || ' löscht ' || pn
          || ' die gespeicherten Zahlen, Beiträge und Zielgruppen dieser Accounts. Das ist eine Pflicht aus den Plattform-Bedingungen von Meta '
          || 'und lässt sich nicht abschalten. Verbindet das Talent den Account vorher neu, bleiben nur die Daten ab der neuen Verbindung. '
          || 'Bestätigungscode: ' || q.code || '.'
        ELSE
          'Über ' || meta_app_text(q.app) || ' wurde am ' || talents_datum(q.eingegangen_am) || ' gemeldet, dass ' || pn
          || ' in den Einstellungen des Kontos entfernt wurde. Betroffen: ' || meta_konten_text(q.konten) || '. Die Verbindung ist getrennt, '
          || pn || ' ruft keine neuen Zahlen mehr ab; die bisher gespeicherten Zahlen bleiben erhalten. Soll der Account wieder verbunden werden, '
          || 'im Talent-Profil über das Zahnrad unter „Accounts und Verbindungen“ einen neuen Einladungslink erzeugen und an das Talent schicken.' END,
      'empfaenger', empf) AS m
    FROM meta_rueckmeldungen q
    WHERE q.gemeldet_am IS NULL AND q.anzahl > 0 AND q.konten <> '[]'::jsonb
      AND (q.art = 'abmeldung' OR q.status = 'vorgemerkt' OR q.status = 'erledigt')
    UNION ALL
    SELECT q.id, 2, jsonb_build_object('id', q.id, 'art', 'erledigt', 'titel', 'Talents: Daten gelöscht',
      'text', pn || ' hat am ' || talents_datum(q.erledigt_am) || ' die Daten gelöscht, deren Löschung am ' || talents_datum(q.eingegangen_am)
        || ' über ' || meta_app_text(q.app) || ' verlangt wurde. Betroffen: ' || meta_konten_text(q.konten) || '. Bestätigungscode: ' || q.code || '.',
      'empfaenger', empf)
    FROM meta_rueckmeldungen q
    WHERE q.art = 'loeschung' AND q.status = 'erledigt' AND q.erledigt_gemeldet_am IS NULL AND q.anzahl > 0 AND q.konten <> '[]'::jsonb
  ) z WHERE jsonb_array_length(empf) > 0;
  RETURN jsonb_build_object('ok', true, 'test', NOT p_ausfuehren, 'nachgeprueft', nachgeprueft, 'geloescht', geloescht,
    'anzahl', jsonb_array_length(m), 'meldungen', m);
END $function$
;

CREATE OR REPLACE FUNCTION public.meta_links()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object(
    'datenschutz', meta_adresse(ally_webhook_aussen() || '/meta/datenschutz'),
    'datenloeschung', meta_adresse(ally_webhook_aussen() || '/meta/datenloeschung'),
    'nutzungsbedingungen', meta_adresse(ally_webhook_aussen() || '/meta/nutzungsbedingungen'),
    'status', meta_adresse(ally_webhook_aussen() || '/meta/loeschung-status'),
    'impressum', nullif(btrim(coalesce(ally_einstellung('rechtstexte_impressum_url'), '')), ''))
$function$
;

CREATE OR REPLACE FUNCTION public.meta_loeschfrist_tage()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN btrim(coalesce(ally_einstellung('meta_loeschfrist_tage'), '')) ~ '^[0-9]{1,2}$'
               AND btrim(ally_einstellung('meta_loeschfrist_tage'))::integer BETWEEN 1 AND 30
              THEN btrim(ally_einstellung('meta_loeschfrist_tage'))::integer ELSE 3 END
$function$
;

CREATE OR REPLACE FUNCTION public.meta_loeschung_ausfuehren(p_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  r meta_rueckmeldungen%ROWTYPE;
  k record;
  geloescht integer := 0;
  teilweise integer := 0;
BEGIN
  SELECT * INTO r FROM meta_rueckmeldungen WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR r.art <> 'loeschung' OR r.status <> 'vorgemerkt' THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  FOR k IN SELECT * FROM talent_kanaele WHERE id = ANY (r.kanal_ids) ORDER BY id FOR UPDATE LOOP
    IF k.status = 'verbunden' AND k.verbunden_am > r.eingegangen_am THEN
      DELETE FROM talent_kanal_tage WHERE kanal_id = k.id AND abgerufen_am <= r.eingegangen_am;
      DELETE FROM talent_zielgruppen WHERE kanal_id = k.id AND abgerufen_am <= r.eingegangen_am;
      DELETE FROM talent_beitraege WHERE kanal_id = k.id AND erfasst_am <= r.eingegangen_am;
      DELETE FROM talent_meldungen WHERE kanal_id = k.id AND gemeldet_am <= r.eingegangen_am;
      UPDATE talent_kanaele SET letzter_fehler = NULL WHERE id = k.id AND letzter_fehler LIKE 'Löschung der Daten über %';
      teilweise := teilweise + 1;
    ELSE
      DELETE FROM talent_kanaele WHERE id = k.id;
      INSERT INTO talent_kanaele (talent_id, plattform, status)
      SELECT k.talent_id, k.plattform, 'offen'
      WHERE EXISTS (SELECT 1 FROM talents t WHERE t.id = k.talent_id)
        AND NOT EXISTS (SELECT 1 FROM talent_kanaele x WHERE x.talent_id = k.talent_id AND x.plattform = k.plattform);
      geloescht := geloescht + 1;
    END IF;
  END LOOP;
  UPDATE meta_rueckmeldungen SET status = 'erledigt', erledigt_am = now(), nutzer_id = NULL WHERE id = p_id;
  RETURN jsonb_build_object('ok', true, 'geloescht', geloescht, 'teilweise', teilweise);
END $function$
;

CREATE OR REPLACE FUNCTION public.meta_loeschung_offen(p_kanal_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM meta_rueckmeldungen r WHERE r.art = 'loeschung' AND r.status = 'vorgemerkt' AND p_kanal_id = ANY (r.kanal_ids))
$function$
;

CREATE OR REPLACE FUNCTION public.meta_loeschung_status(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c text := upper(btrim(coalesce(p_code, '')));
  r meta_rueckmeldungen%ROWTYPE;
  pn text := produkt_name();
  an text := coalesce(nullif(anbieter_name(), ''), 'dem anbietenden Unternehmen');  -- Dativ: nur in „betrieben von …“ (Migration 73)
  basis jsonb;
BEGIN
  -- Threads ergänzt (Stefan 19.10.2026), Migration 53
  basis := jsonb_build_object('ok', true, 'seite', 'status', 'produkt_name', pn, 'anbieter_name', anbieter_name(),
    'kontakt_email', nullif(btrim(coalesce(ally_einstellung('rechtstexte_kontakt_email'), '')), ''), 'code', NULL, 'links', meta_links());
  IF c = '' THEN
    RETURN basis || jsonb_build_object('gefunden', false, 'titel', 'Stand einer Löschanfrage',
      'text', 'Gib den Bestätigungscode ein, den du nach deiner Löschanfrage bei Facebook, Instagram oder Threads erhalten hast.');
  END IF;
  IF c !~ '^[0-9A-F]{16}$' THEN
    RETURN basis || jsonb_build_object('gefunden', false, 'code', left(c, 40), 'titel', 'Bestätigungscode unbekannt',
      'text', 'Dieser Bestätigungscode hat nicht das erwartete Format. Er besteht aus 16 Zeichen (Ziffern und Buchstaben A bis F).');
  END IF;
  SELECT * INTO r FROM meta_rueckmeldungen WHERE code = c AND art = 'loeschung';
  IF NOT FOUND THEN
    RETURN basis || jsonb_build_object('gefunden', false, 'code', c, 'titel', 'Bestätigungscode unbekannt',
      'text', 'Zu diesem Bestätigungscode gibt es hier keine Löschanfrage. Bitte prüfe den Code. Anfragen werden nach einem Jahr aus der Übersicht entfernt.');
  END IF;
  RETURN basis || jsonb_build_object('gefunden', true, 'code', c, 'status', r.status,
    'eingegangen', talents_datum(r.eingegangen_am), 'loeschen_ab', talents_datum(r.loeschen_ab), 'erledigt_am', talents_datum(r.erledigt_am),
    'titel', CASE r.status WHEN 'vorgemerkt' THEN 'Löschung vorgemerkt' WHEN 'erledigt' THEN 'Daten gelöscht' ELSE 'Keine Daten gespeichert' END,
    'text', CASE r.status
      WHEN 'vorgemerkt' THEN 'Deine Anfrage über ' || meta_app_text(r.app) || ' ist am ' || talents_datum(r.eingegangen_am) || ' eingegangen. '
        || 'Die Verbindung zu ' || pn || ' wurde sofort getrennt und die Zugangsschlüssel wurden gelöscht; es werden keine neuen Daten mehr abgerufen. '
        || 'Die gespeicherten Daten werden am ' || talents_datum(r.loeschen_ab) || ' gelöscht. Die Agentur, die dich eingeladen hat, ist informiert.'
      WHEN 'erledigt' THEN 'Deine Anfrage über ' || meta_app_text(r.app) || ' ist am ' || talents_datum(r.eingegangen_am) || ' eingegangen. '
        || 'Die Daten, die ' || pn || ' über diese Verbindung gespeichert hatte, wurden am ' || talents_datum(r.erledigt_am) || ' gelöscht.'
      ELSE 'Deine Anfrage über ' || meta_app_text(r.app) || ' ist am ' || talents_datum(r.eingegangen_am) || ' eingegangen. '
        || 'Zu deinem Konto waren bei ' || pn || ' (betrieben von ' || an || ') keine Daten aus dieser Anmeldung gespeichert. Es ist nichts weiter zu tun.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.meta_meldung_gemerkt(p_id integer, p_art text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF p_art = 'eingang' THEN
    UPDATE meta_rueckmeldungen SET gemeldet_am = now() WHERE id = p_id AND gemeldet_am IS NULL;
  ELSIF p_art = 'erledigt' THEN
    UPDATE meta_rueckmeldungen SET erledigt_gemeldet_am = now(), gemeldet_am = coalesce(gemeldet_am, now())
    WHERE id = p_id AND erledigt_gemeldet_am IS NULL AND status = 'erledigt';
  ELSE
    RETURN jsonb_build_object('ok', false);
  END IF;
  RETURN jsonb_build_object('ok', FOUND);
END $function$
;

CREATE OR REPLACE FUNCTION public.meta_nutzer_id_liste()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v text := coalesce(nullif(btrim(ally_einstellung('talents_graph_version')), ''), 'v26.0');
  l jsonb;
BEGIN
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Verschlüsselung ist nicht eingerichtet.', 'kanaele', '[]'::jsonb);
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('kanal_id', k.id, 'anmeldeweg', coalesce(k.anmeldeweg, 'facebook'),
      'adresse', CASE WHEN k.anmeldeweg = 'instagram' THEN 'https://graph.instagram.com/' || v || '/me' ELSE 'https://graph.facebook.com/' || v || '/me' END,
      'felder', CASE WHEN k.anmeldeweg = 'instagram' THEN 'id,user_id' ELSE 'id' END,
      'schluessel', ally_entschluesseln(k.schluessel)) ORDER BY k.id), '[]'::jsonb) INTO l
  FROM (SELECT * FROM talent_kanaele k WHERE k.meta_nutzer_id IS NULL AND k.status = 'verbunden' AND k.schluessel IS NOT NULL
          AND k.extern_id IS NOT NULL AND k.plattform IN ('instagram', 'facebook') ORDER BY k.id LIMIT 10) k;
  RETURN jsonb_build_object('ok', true, 'anzahl', jsonb_array_length(l), 'kanaele', l);
END $function$
;

CREATE OR REPLACE FUNCTION public.meta_nutzer_id_setzen(p_kanal_id integer, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  k talent_kanaele%ROWTYPE;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  i text;
BEGIN
  IF jsonb_typeof(d->'data') = 'array' AND jsonb_typeof(d->'data'->0) = 'object' THEN
    d := d->'data'->0;
  END IF;
  SELECT * INTO k FROM talent_kanaele WHERE id = p_kanal_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Kanal.');
  END IF;
  i := CASE WHEN jsonb_typeof(d->'id') IN ('string', 'number') THEN d->>'id' ELSE '' END;
  IF i !~ '^[0-9]{1,30}$' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Keine gültige Meta-Kennung (user_id).');
  END IF;
  IF k.anmeldeweg = 'instagram' AND coalesce(d->>'user_id', '') <> coalesce(k.extern_id, '') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Antwort gehört nicht zu diesem Instagram-Account.');
  END IF;
  UPDATE talent_kanaele SET meta_nutzer_id = i WHERE id = p_kanal_id AND meta_nutzer_id IS NULL;
  RETURN jsonb_build_object('ok', true, 'kanal_id', p_kanal_id, 'gesetzt', FOUND);
END $function$
;

CREATE OR REPLACE FUNCTION public.meta_rechtstext(p_seite text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  pn text := produkt_name();
  an text := coalesce(nullif(anbieter_name(), ''), 'das anbietende Unternehmen');
  an_dat text := coalesce(nullif(anbieter_name(), ''), 'dem anbietenden Unternehmen');  -- Dativ (Migration 73)
  an_gross text := coalesce(nullif(anbieter_name(), ''), 'Das anbietende Unternehmen');  -- Satzanfang (Migration 73)
  mail text := nullif(btrim(coalesce(ally_einstellung('rechtstexte_kontakt_email'), '')), '');
  anschrift text := nullif(btrim(coalesce(ally_einstellung('rechtstexte_anschrift'), '')), '');
  frei text := btrim(coalesce(ally_einstellung('rechtstexte_freigegeben'), ''));
  entwurf boolean;
  frist integer := meta_loeschfrist_tage();
  l jsonb := meta_links();
  kontakt text;
  a jsonb := '[]'::jsonb;
  titel text;
  unter text;
  stand text;
BEGIN
  -- Threads ergänzt (Stefan 19.10.2026), Migration 53: überall, wo die Meta-Apps aufgezählt werden, dazu Weg 3 der Datenlöschung.
  entwurf := frei !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$';
  stand := CASE WHEN entwurf THEN 'Entwurf vom 19.10.2026' ELSE 'Stand: ' || to_char(frei::date, 'DD.MM.YYYY') END;
  kontakt := an || coalesce(', ' || replace(anschrift, E'\n', ', '), '') || coalesce(', E-Mail: ' || mail, '');
  IF p_seite = 'datenschutz' THEN
    titel := 'Datenschutzhinweise für Talents';
    unter := 'Verbindung deiner Social-Media-Accounts mit ' || pn || ' (Instagram über Facebook-Anmeldung oder direkt über Instagram, Threads)';
    a := jsonb_build_array(
      jsonb_build_object('titel', 'Kurz gesagt', 'absaetze', jsonb_build_array(
        'Deine Agentur bzw. die für dich zuständige Person nutzt ' || pn || ', um die Statistiken deiner Social-Media-Accounts auszuwerten. ' || pn || ' liest dafür Kennzahlen und Beitragsdaten, '
        || 'veröffentlicht nichts, liest keine Nachrichten und sieht kein Passwort. Du kannst die Verbindung jederzeit trennen und die Löschung deiner Daten verlangen.'),
        'liste', '[]'::jsonb, 'pruefen', NULL),
      jsonb_build_object('titel', 'Wer verantwortlich ist', 'absaetze', jsonb_build_array(
        'Verantwortlich für die Verarbeitung ist die Agentur bzw. die Person, die dich eingeladen hat. Name und Kontakt stehen auf deiner Einladungsseite und in der Nachricht mit dem Einladungslink.',
        an_gross || ' betreibt ' || pn || ' und die dafür nötigen Apps bei Meta (Facebook, Instagram und Threads) und verarbeitet die Daten im Auftrag deiner Agentur (Auftragsverarbeitung nach Art. 28 DSGVO). '
        || an_gross || ' nutzt die Daten nicht für eigene Zwecke.',
        'Kontakt zu ' || an_dat || ': ' || kontakt || '.'),
        'liste', '[]'::jsonb,
        'pruefen', 'Rollenverteilung prüfen: Agentur Verantwortliche, ' || an || ' Auftragsverarbeiter (konzept.md). Prüfen, ob ' || an
          || ' für den Betrieb der Meta-Apps selbst Verantwortlicher ist (z. B. Bearbeitung der Lösch- und Abmeldemeldungen von Meta, Sicherheit).'
          || CASE WHEN mail IS NULL OR anschrift IS NULL THEN ' Kontakt-E-Mail und Anschrift fehlen noch (Einstellungen › Plattform-Apps).' ELSE '' END),
      jsonb_build_object('titel', 'Welche Daten ' || pn || ' liest und speichert', 'absaetze', jsonb_build_array(
        'Nur von den Accounts, die du selbst verbindest, und nur mit den Berechtigungen, denen du bei Facebook, Instagram oder Threads zustimmst:'),
        'liste', jsonb_build_array(
