 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN p IS NULL THEN 'nicht verfügbar' ELSE talents_zahl_text(p) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_chat_w(p jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN p->>'wert' IS NULL THEN 'nicht verfügbar' ELSE p->>'text' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_csv(p_kopf text[], p_zeilen jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT chr(65279) || array_to_string(ARRAY(SELECT talents_csv_feld(k) FROM unnest(p_kopf) WITH ORDINALITY AS u(k, o) ORDER BY o), ';') || E'\r\n'
    || coalesce((SELECT string_agg((SELECT string_agg(talents_csv_feld(f.v #>> '{}'), ';' ORDER BY f.o) FROM jsonb_array_elements(z.z) WITH ORDINALITY AS f(v, o)), E'\r\n' ORDER BY z.o)
                 FROM jsonb_array_elements(coalesce(p_zeilen, '[]'::jsonb)) WITH ORDINALITY AS z(z, o)) || E'\r\n', '')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_csv_feld(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT '"' || replace(CASE WHEN p ~ '^[=+@-]' AND p !~ '^-?[0-9]+([.][0-9]+)?$' THEN '''' || p ELSE coalesce(p, '') END, '"', '""') || '"'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_csv_lesen(p_text text)
 RETURNS TABLE(nr integer, felder text[])
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  s text := replace(replace(coalesce(p_text, ''), E'\r\n', E'\n'), E'\r', E'\n');
  z text[];
  erste text;
  sep text;
  i integer := 1;
  n integer;
  c text;
  feld text := '';
  zeile text[] := '{}';
  q boolean := false;
  anz integer := 0;
BEGIN
  IF left(s, 1) = chr(65279) THEN s := substr(s, 2); END IF;
  erste := split_part(s, E'\n', 1);
  sep := CASE WHEN length(erste) - length(replace(erste, E'\t', '')) > greatest(length(erste) - length(replace(erste, ';', '')), length(erste) - length(replace(erste, ',', ''))) THEN E'\t'
              WHEN length(erste) - length(replace(erste, ',', '')) > length(erste) - length(replace(erste, ';', '')) THEN ',' ELSE ';' END;
  z := regexp_split_to_array(s, '');
  n := coalesce(array_length(z, 1), 0);
  WHILE i <= n + 1 LOOP
    c := CASE WHEN i <= n THEN z[i] ELSE E'\n' END;
    IF q AND i <= n THEN
      IF c = '"' THEN
        IF i < n AND z[i + 1] = '"' THEN feld := feld || '"'; i := i + 1; ELSE q := false; END IF;
      ELSE
        feld := feld || c;
      END IF;
    ELSIF c = '"' AND feld = '' THEN
      q := true;
    ELSIF c = sep THEN
      zeile := zeile || btrim(feld); feld := '';
    ELSIF c = E'\n' THEN
      zeile := zeile || btrim(feld); feld := ''; q := false;
      IF array_to_string(zeile, '') <> '' THEN
        anz := anz + 1; nr := anz; felder := zeile; RETURN NEXT;
      END IF;
      zeile := '{}';
    ELSE
      feld := feld || c;
    END IF;
    i := i + 1;
  END LOOP;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_datum(p timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT to_char(p AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_datum_lesen(p text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  x text := btrim(coalesce(p, ''));
BEGIN
  IF x ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RETURN to_date(x, 'YYYY-MM-DD');
  ELSIF x ~ '^[0-9]{1,2}[.][0-9]{1,2}[.][0-9]{4}$' THEN
    RETURN to_date(x, 'DD.MM.YYYY');
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_dezimal_text(p numeric, p_stellen integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN p IS NULL THEN NULL ELSE replace(to_char(round(p, p_stellen),
    'FM999999999990' || CASE WHEN p_stellen > 0 THEN '.' || repeat('0', p_stellen) ELSE '' END), '.', ',') END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_angaben(p_id bigint, p_ov jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Angaben zu einem manuellen Wert und seiner Überschneidung für Verlauf und Anzeige (Migration 65)
  SELECT jsonb_build_object('plattform', m.plattform, 'plattform_name', talents_plattform_name(m.plattform), 'konto', m.konto,
    'kennzahl', m.kennzahl, 'kennzahl_name', talents_manuell_kennzahl_name(m.bereich, m.kennzahl),
    'von', to_char(coalesce(m.von, m.bis), 'YYYY-MM-DD'), 'bis', to_char(m.bis, 'YYYY-MM-DD'), 'zeitraum_text', talents_manuell_zeitraum_text(m.von, m.bis),
    'manuell_wert', m.wert, 'quelle_text', m.quelle_text,
    'auto_wert', p_ov->'wert', 'auto_tage', p_ov->'tage', 'tage_soll', p_ov->'tage_soll', 'kanaele', p_ov->'kanaele', 'accounts', p_ov->>'accounts')
  FROM talent_manuell_werte m WHERE m.id = p_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_darf(p_user text, p_talent_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Doppelte Daten entscheiden (Stefan 20.10.2026, 09:26: „an die zuständige Person“): Admin, zuständiges Management (talent_zugang_darf) oder eine für das Talent
  -- zuständige Person (talent_personen). Sehen dürfen alle, die das Talent sehen (talent_sichtbar).
  -- Migration 66: Entscheiden ist eine Änderung, dafür braucht es das Verwalten-Recht für das Talent (talent_verwaltbar).
  -- Nach Migration 64 (Rollen): immer nur, wer das Talent über seine Rechte sehen darf (Rolle ohne Recht sieht und entscheidet nichts).
  SELECT coalesce(talent_verwaltbar(p_user, p_talent_id), false)
     AND (coalesce(talent_zugang_darf(p_user, p_talent_id), false)
          OR EXISTS (SELECT 1 FROM talent_personen tp JOIN ally_personen q ON q.matrix_user_id = tp.matrix_user_id
                     WHERE tp.talent_id = p_talent_id AND tp.matrix_user_id = p_user AND q.aktiv))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_entscheiden(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  tid integer; mid bigint;
  w talent_manuell_werte%ROWTYPE;
  alt talent_doppelt_entscheidungen%ROWTYPE; hat_alt boolean := false;
  st jsonb; ov jsonb; ks integer[];
  neu text; vorher text; fehler text := NULL; m text := NULL; ang jsonb;
BEGIN
  -- Doppelte Daten entscheiden (Stefan 20.10.2026, 09:26; über talent_zugang_ui_aktion tz_dd_automatisch / tz_dd_manuell mit talent_id und doppelt_id).
  -- automatisch = automatischen Wert behalten, manuellen archivieren (nicht löschen); manuell = manuellen Wert verwenden, automatischen für den Zeitraum nicht zählen.
  -- Gespeichert: wer, was, wann (talent_doppelt_entscheidungen und talent_doppelt_verlauf). Jederzeit änderbar.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  tid := CASE WHEN coalesce(d->>'talent_id', '') ~ '^[0-9]{1,9}$' THEN (d->>'talent_id')::integer END;
  mid := CASE WHEN coalesce(d->>'doppelt_id', '') ~ '^[0-9]{1,18}$' THEN (d->>'doppelt_id')::bigint END;
  neu := CASE p_aktion WHEN 'tz_dd_automatisch' THEN 'automatisch' WHEN 'tz_dd_manuell' THEN 'manuell' END;
  IF neu IS NULL THEN
    fehler := 'Diese Aktion gibt es hier nicht.';
  ELSIF tid IS NULL OR NOT talents_doppelt_darf(s.person, tid) THEN
    fehler := 'Das dürfen Admins oder der Manager oder die Managerin des Talents.';
  ELSE
    SELECT * INTO w FROM talent_manuell_werte x WHERE x.id = mid AND x.talent_id = tid AND x.bereich = 'konto' FOR UPDATE;
    IF NOT FOUND THEN
      fehler := 'Diesen Wert gibt es nicht mehr.';
    ELSE
      SELECT * INTO alt FROM talent_doppelt_entscheidungen x WHERE x.manuell_id = mid FOR UPDATE;
      hat_alt := FOUND;
      st := talents_doppelt_status(mid);
      ov := nullif(st->'ueberschneidung', 'null'::jsonb);
      IF ov IS NULL AND NOT hat_alt THEN
        fehler := 'Für diesen Wert gibt es keine automatischen Zahlen im selben Zeitraum. Er zählt ohnehin.';
      ELSIF st->>'status' = neu THEN
        m := 'Diese Entscheidung gilt schon.';
      ELSE
        ks := CASE WHEN ov IS NOT NULL THEN ARRAY(SELECT (x #>> '{}')::integer FROM jsonb_array_elements(ov->'kanaele') x ORDER BY 1) ELSE alt.kanaele END;
        vorher := st->>'status';
        INSERT INTO talent_doppelt_entscheidungen (manuell_id, talent_id, status, kanaele, signatur, auto_wert, manuell_wert, entschieden_von, entschieden_am)
        VALUES (mid, tid, neu, ks, talents_manuell_signatur(mid), (ov->>'wert')::numeric, w.wert, s.person, now())
        ON CONFLICT (manuell_id) DO UPDATE SET status = EXCLUDED.status, kanaele = EXCLUDED.kanaele, signatur = EXCLUDED.signatur, auto_wert = EXCLUDED.auto_wert,
          manuell_wert = EXCLUDED.manuell_wert, entschieden_von = EXCLUDED.entschieden_von, entschieden_am = EXCLUDED.entschieden_am;
        ang := talents_doppelt_angaben(mid, ov) || jsonb_build_object('status_vorher', vorher);
        INSERT INTO talent_doppelt_verlauf (talent_id, manuell_id, aktion, anlass, person, angaben) VALUES (tid, mid, neu, 'person', s.person, ang);
        m := CASE neu WHEN 'automatisch' THEN 'Gespeichert: Der automatische Wert zählt, der manuelle Wert ist archiviert (' || (ang->>'kennzahl_name') || ', ' || (ang->>'zeitraum_text') || ').'
                      ELSE 'Gespeichert: Der manuelle Wert zählt, der automatische bleibt gespeichert und zählt für diesen Zeitraum nicht (' || (ang->>'kennzahl_name') || ', ' || (ang->>'zeitraum_text') || ').' END;
      END IF;
    END IF;
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_kurztext(p_angaben jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Eine Zeile je doppeltem Wert, z. B. „Instagram @name, Reichweite, 01.10.2026 bis 07.10.2026: automatisch 1.234, manuell 1.300“ (Migration 65)
  SELECT concat_ws(', ', p_angaben->>'plattform_name' || coalesce(' ' || coalesce(nullif(p_angaben->>'konto', ''), p_angaben->>'accounts'), ''),
           p_angaben->>'kennzahl_name', p_angaben->>'zeitraum_text')
    || ': automatisch ' || coalesce(talents_zahl_text((p_angaben->>'auto_wert')::numeric), '–')
    || ', manuell ' || coalesce(talents_zahl_text((p_angaben->>'manuell_wert')::numeric), '–')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_meldung(p_plattform text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Facebook-Seite und YouTube-Kanal mit eigenem Wort (Stefan 18.10.2026)
  SELECT CASE p_plattform
    WHEN 'facebook' THEN 'Diese Facebook-Seite ist bereits mit einem anderen Talent verbunden. Bitte die Agentur kontaktieren.'
    WHEN 'youtube' THEN 'Dieser YouTube-Kanal ist bereits mit einem anderen Talent verbunden. Bitte die Agentur kontaktieren.'
    ELSE 'Dieser ' || coalesce(talents_plattform_name(p_plattform), 'Plattform') || '-Account ist bereits mit einem anderen Talent verbunden. Bitte die Agentur kontaktieren.' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_nach_abruf()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  ids bigint[];
BEGIN
  -- Trigger auf talent_kanal_tage (Migration 65, je Anweisung): nach jedem automatischen Abruf (auch beim ersten Abruf eines später verbundenen Accounts)
  -- die manuellen Konto-Werte desselben Talents und derselben Plattform im betroffenen Zeitraum prüfen. Fehler brechen den Abruf nie ab (nur Warnung).
  BEGIN
    ids := ARRAY(SELECT DISTINCT m.id
      FROM (SELECT n.kanal_id, min(n.tag) AS von, max(n.tag) AS bis FROM neu n GROUP BY n.kanal_id) x
      JOIN talent_kanaele k ON k.id = x.kanal_id
      JOIN talent_manuell_werte m ON m.talent_id = k.talent_id AND m.plattform = k.plattform AND m.bereich = 'konto'
        AND m.bis >= x.von AND coalesce(m.von, m.bis) <= x.bis);
    IF cardinality(ids) > 0 THEN
      PERFORM talents_doppelt_pruefen(ids, 'abruf');
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Doppelte Daten: Prüfung nach dem Abruf fehlgeschlagen (%).', SQLERRM;
  END;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_nach_wert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  d talent_doppelt_entscheidungen%ROWTYPE;
BEGIN
  -- Trigger auf talent_manuell_werte (Migration 65): neu bestätigter oder geänderter manueller Konto-Wert -> doppelte Daten prüfen.
  -- Ändert sich ein entschiedener Wert, gilt die Entscheidung nicht mehr (Verlauf „geändert“). Ein Fehler hier bricht das Speichern nie ab (nur Warnung);
  -- gezählt wird trotzdem richtig, weil talents_zahlen die Überschneidung bei jeder Abfrage selbst prüft.
  IF NEW.bereich <> 'konto' THEN RETURN NULL; END IF;
  IF current_setting('talents.pk_zurueck', true) = '1' THEN RETURN NULL; END IF;  -- Migration 130 (G1)
  BEGIN
    IF TG_OP = 'UPDATE' THEN
      SELECT * INTO d FROM talent_doppelt_entscheidungen x WHERE x.manuell_id = NEW.id;
      IF FOUND AND d.signatur <> talents_manuell_signatur(NEW.id) THEN
        INSERT INTO talent_doppelt_verlauf (talent_id, manuell_id, aktion, anlass, angaben)
        VALUES (NEW.talent_id, NEW.id, 'geaendert', 'bearbeiten', talents_doppelt_angaben(NEW.id, NULL) || jsonb_build_object('status_vorher', d.status));
      END IF;
    END IF;
    PERFORM talents_doppelt_pruefen(ARRAY[NEW.id], CASE TG_OP WHEN 'INSERT' THEN 'hochladen' ELSE 'bearbeiten' END);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Doppelte Daten: Prüfung für den manuellen Wert % fehlgeschlagen (%).', NEW.id, SQLERRM;
  END;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_offen_anzahl(p_talent_id integer)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  -- Anzahl offener doppelter Daten eines Talents (für „Doppelte Daten prüfen“, Migration 65)
  SELECT count(*)::integer FROM talent_manuell_werte w
  WHERE w.talent_id = p_talent_id AND w.bereich = 'konto' AND talents_manuell_ueberschneidung(w.id) IS NOT NULL
    AND talents_doppelt_status(w.id)->>'status' = 'offen'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_pruefen(p_ids bigint[], p_anlass text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  m record;
  st jsonb; ov jsonb; ang jsonb;
  ks integer[];
  sig text;
  alt talent_doppelt_meldungen%ROWTYPE;
  n integer := 0;
  neu jsonb := '{}'::jsonb;
  t text; liste jsonb; p text; empf text[]; txt text;
BEGIN
  -- Doppelte Daten erkennen (Stefan 20.10.2026, 09:26): beim Bestätigen/Bearbeiten eines manuellen Werts und bei jedem automatischen Abruf (Trigger).
  -- Neu erkannte Überschneidungen kommen in den Verlauf; je Talent eine Benachrichtigung (Glocke, Art doppelte_daten) an die zuständigen Personen,
  -- ohne zuständige Person an die Admins. Schon gemeldete Überschneidungen (gleicher Wert, keine weiteren Accounts) werden nicht erneut gemeldet.
  FOR m IN SELECT w.id, w.talent_id FROM talent_manuell_werte w WHERE w.id = ANY (p_ids) AND w.bereich = 'konto' ORDER BY w.talent_id, w.id LOOP
    st := talents_doppelt_status(m.id);
    CONTINUE WHEN st IS NULL OR st->>'status' <> 'offen';
    ov := nullif(st->'ueberschneidung', 'null'::jsonb);
    ks := ARRAY(SELECT (x #>> '{}')::integer FROM jsonb_array_elements(ov->'kanaele') x ORDER BY 1);
    sig := talents_manuell_signatur(m.id);
    SELECT * INTO alt FROM talent_doppelt_meldungen x WHERE x.manuell_id = m.id;
    CONTINUE WHEN FOUND AND alt.signatur = sig AND alt.kanaele @> ks;
    INSERT INTO talent_doppelt_meldungen (manuell_id, kanaele, signatur, gemeldet_am) VALUES (m.id, ks, sig, now())
    ON CONFLICT (manuell_id) DO UPDATE SET kanaele = EXCLUDED.kanaele, signatur = EXCLUDED.signatur, gemeldet_am = now();
    ang := talents_doppelt_angaben(m.id, ov);
    INSERT INTO talent_doppelt_verlauf (talent_id, manuell_id, aktion, anlass, angaben)
    VALUES (m.talent_id, m.id, 'erkannt', CASE WHEN p_anlass IN ('hochladen', 'abruf', 'bearbeiten') THEN p_anlass END, ang);
    n := n + 1;
    neu := jsonb_set(neu, ARRAY[m.talent_id::text], coalesce(neu->(m.talent_id::text), '[]'::jsonb) || jsonb_build_array(talents_doppelt_kurztext(ang)));
  END LOOP;
  FOR t, liste IN SELECT x.key, x.value FROM jsonb_each(neu) x LOOP
    empf := ARRAY(SELECT tp.matrix_user_id FROM talent_personen tp JOIN ally_personen q ON q.matrix_user_id = tp.matrix_user_id
                  WHERE tp.talent_id = t::integer AND q.aktiv AND talents_doppelt_darf(tp.matrix_user_id, t::integer) ORDER BY 1);
    IF cardinality(empf) = 0 THEN
      empf := ARRAY(SELECT q.matrix_user_id FROM ally_personen q WHERE q.aktiv AND coalesce(ally_hat_recht(q.matrix_user_id, 'admin'), false) ORDER BY 1);
    END IF;
    txt := CASE WHEN jsonb_array_length(liste) = 1 THEN 'Ein manueller Wert überschneidet sich mit automatisch geladenen Zahlen: '
                ELSE jsonb_array_length(liste) || ' manuelle Werte überschneiden sich mit automatisch geladenen Zahlen: ' END
      || (SELECT string_agg(x #>> '{}', '; ') FROM (SELECT x FROM jsonb_array_elements(liste) x LIMIT 5) y)
      || CASE WHEN jsonb_array_length(liste) > 5 THEN '; …' ELSE '' END
      || '. Bis zur Entscheidung zählt der automatische Wert. Bitte auf der Talent-Seite unter „Doppelte Daten prüfen“ entscheiden.';
    FOREACH p IN ARRAY empf LOOP
      PERFORM ally_benachrichtigen(p, 'doppelte_daten', 'Doppelte Daten: ' || coalesce(talent_listenname(t::integer), 'Talent'), txt,
        jsonb_build_object('seite', 'talent', 'parameter', jsonb_build_object('id', t::integer), 'anker', 'a-doppelte-daten'),
        'doppelt:' || t || ':' || md5(liste::text), 'Talents', false);
    END LOOP;
  END LOOP;
  RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_status(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  m talent_manuell_werte%ROWTYPE;
  d talent_doppelt_entscheidungen%ROWTYPE;
  hat_d boolean := false;
  gueltig boolean := false;
  ov jsonb;
  ks integer[] := '{}';
BEGIN
  -- Doppelte Daten (Stefan 20.10.2026, 09:26): zählt dieser manuelle Wert?
  -- keins = keine Überschneidung (zählt); offen = Überschneidung ohne gültige Entscheidung (zählt nicht, der automatische Wert hat Vorrang);
  -- automatisch = automatischen Wert behalten (manueller archiviert, zählt nie); manuell = manuellen Wert verwenden (zählt; ausschluss = Accounts,
  -- deren automatische Werte für Kennzahl und Zeitraum nicht zählen). Kommt nach der Entscheidung ein weiterer Account dazu, ist der Wert wieder offen.
  SELECT * INTO m FROM talent_manuell_werte x WHERE x.id = p_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO d FROM talent_doppelt_entscheidungen x WHERE x.manuell_id = p_id;
  IF FOUND THEN hat_d := true; gueltig := d.signatur = talents_manuell_signatur(p_id); END IF;
  ov := talents_manuell_ueberschneidung(p_id);
  IF ov IS NOT NULL THEN ks := ARRAY(SELECT (x #>> '{}')::integer FROM jsonb_array_elements(ov->'kanaele') x); END IF;
  IF gueltig AND d.status = 'automatisch' THEN
    RETURN jsonb_build_object('status', 'automatisch', 'zaehlt', false, 'ueberschneidung', ov, 'ausschluss', '[]'::jsonb);
  ELSIF ov IS NULL THEN
    RETURN jsonb_build_object('status', CASE WHEN gueltig THEN 'manuell' ELSE 'keins' END, 'zaehlt', true, 'ueberschneidung', NULL,
      'ausschluss', CASE WHEN gueltig THEN to_jsonb(d.kanaele) ELSE '[]'::jsonb END);
  ELSIF gueltig AND d.status = 'manuell' AND ks <@ d.kanaele THEN
    RETURN jsonb_build_object('status', 'manuell', 'zaehlt', true, 'ueberschneidung', ov, 'ausschluss', to_jsonb(d.kanaele));
  END IF;
  RETURN jsonb_build_object('status', 'offen', 'zaehlt', false, 'ueberschneidung', ov, 'ausschluss', '[]'::jsonb,
    'grund', CASE WHEN gueltig THEN 'weiterer_account' WHEN hat_d THEN 'geaendert' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_doppelt_ui(p_token text, p_talent_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s record;
  darf boolean;
  e jsonb := '[]'::jsonb;
  m record; st jsonb; ov jsonb; d talent_doppelt_entscheidungen%ROWTYPE; ang jsonb; n_offen integer := 0; n integer := 0;
BEGIN
  -- Abschnitt „Doppelte Daten prüfen“ auf der Talent-Seite (ALLY 25, Migration 65): offene zuerst, dann entschiedene; beide Werte nebeneinander (automatisch,
  -- manuell, Zeitraum, Quelle), Entscheidung mit Person und Zeit, Verlauf. Nur Personen-Sitzungen; Talent-Sitzungen und fremde Talents bekommen nichts.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen OR p_talent_id IS NULL OR NOT coalesce(talent_sichtbar(s.person, p_talent_id), false) THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  darf := talents_doppelt_darf(s.person, p_talent_id);
  FOR m IN SELECT w.id FROM talent_manuell_werte w
           WHERE w.talent_id = p_talent_id AND w.bereich = 'konto'
             AND (EXISTS (SELECT 1 FROM talent_doppelt_entscheidungen x WHERE x.manuell_id = w.id) OR talents_manuell_ueberschneidung(w.id) IS NOT NULL)
           ORDER BY w.bis DESC, w.id DESC LIMIT 200 LOOP
    st := talents_doppelt_status(m.id);
    CONTINUE WHEN st->>'status' = 'keins';
    ov := nullif(st->'ueberschneidung', 'null'::jsonb);
    SELECT * INTO d FROM talent_doppelt_entscheidungen x WHERE x.manuell_id = m.id;
    ang := talents_doppelt_angaben(m.id, ov);
    IF st->>'status' = 'offen' THEN n_offen := n_offen + 1; END IF;
    n := n + 1;
    e := e || jsonb_build_array(ang || jsonb_build_object('id', m.id, 'status', st->>'status',
      'status_text', CASE st->>'status' WHEN 'offen' THEN CASE st->>'grund' WHEN 'weiterer_account' THEN 'offen (weiterer Account)' WHEN 'geaendert' THEN 'offen (Wert geändert)' ELSE 'offen' END
                                     WHEN 'automatisch' THEN 'automatischer Wert zählt' ELSE 'manueller Wert zählt' END,
      'zaehlt_text', CASE st->>'status' WHEN 'offen' THEN 'Bis zur Entscheidung zählt der automatische Wert.'
                                        WHEN 'automatisch' THEN 'Der manuelle Wert ist archiviert und zählt nicht.'
                                        ELSE 'Der automatische Wert bleibt gespeichert, zählt für diesen Zeitraum aber nicht.' END,
      'auto_text', CASE WHEN ov IS NULL THEN 'keine automatischen Zahlen mehr im Zeitraum'
                        ELSE coalesce(talents_zahl_text((ov->>'wert')::numeric), '–')
                             || CASE WHEN (ov->>'tage_soll')::integer > 1 THEN ' (' || (ov->>'tage') || ' von ' || (ov->>'tage_soll') || ' Tagen)' ELSE '' END END,
      'manuell_text', coalesce(talents_zahl_text((ang->>'manuell_wert')::numeric), '–'),
      'entscheidung', CASE WHEN d.manuell_id IS NOT NULL THEN jsonb_build_object('status', d.status,
          'text', CASE d.status WHEN 'automatisch' THEN 'Automatischen Wert behalten' ELSE 'Manuellen Wert verwenden' END,
          'von', coalesce((SELECT q.name FROM ally_personen q WHERE q.matrix_user_id = d.entschieden_von), d.entschieden_von),
          'am', talents_zeit(d.entschieden_am), 'gueltig', st->>'status' <> 'offen') END,
      'verlauf', (SELECT coalesce(jsonb_agg(jsonb_build_object('am', talents_zeit(v.am),
          'text', CASE v.aktion WHEN 'erkannt' THEN 'erkannt' || CASE v.anlass WHEN 'abruf' THEN ' beim automatischen Abruf' WHEN 'hochladen' THEN ' beim Bestätigen' WHEN 'bearbeiten' THEN ' nach Änderung' ELSE '' END
                                 WHEN 'automatisch' THEN 'entschieden: automatischen Wert behalten' WHEN 'manuell' THEN 'entschieden: manuellen Wert verwenden'
                                 ELSE 'manueller Wert geändert – Entscheidung gilt nicht mehr' END,
          'von', CASE WHEN v.person IS NOT NULL THEN coalesce((SELECT q.name FROM ally_personen q WHERE q.matrix_user_id = v.person), v.person) ELSE 'Ally' END)
          ORDER BY v.am DESC, v.id DESC), '[]'::jsonb)
        FROM (SELECT * FROM talent_doppelt_verlauf v WHERE v.manuell_id = m.id AND v.talent_id = p_talent_id ORDER BY v.am DESC, v.id DESC LIMIT 10) v),
      'darf', darf));
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'darf', darf, 'offen', n_offen, 'anzahl', n,
    'eintraege', (SELECT coalesce(jsonb_agg(x ORDER BY (x->>'status') <> 'offen', x->>'bis' DESC, (x->>'id')::bigint DESC), '[]'::jsonb) FROM jsonb_array_elements(e) x),
    'info', 'Für denselben Account, dieselbe Kennzahl und denselben Zeitraum gibt es automatische und manuelle Zahlen. Bis zur Entscheidung zählt der automatische Wert. '
            || '„Automatischen Wert behalten“ archiviert den manuellen Wert (er wird nicht gelöscht). „Manuellen Wert verwenden“ zählt den manuellen Wert; '
            || 'der automatische bleibt gespeichert, zählt für diesen Zeitraum aber nicht. Die Entscheidung lässt sich jederzeit ändern.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_einbruch(p_kanal_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH h AS (SELECT talents_heute() AS heute, talents_einbruch_schwelle() AS sw),
  d AS (SELECT kt.tag, talents_zahl(kt.werte->'reach') AS r, talents_zahl(kt.werte->'total_interactions') AS i
        FROM talent_kanal_tage kt, h WHERE kt.kanal_id = p_kanal_id AND kt.tag BETWEEN h.heute - 35 AND h.heute - 1),
  s AS (SELECT avg(d.r) FILTER (WHERE d.tag >= h.heute - 7) AS r7, count(d.r) FILTER (WHERE d.tag >= h.heute - 7)::integer AS rn7,
               avg(d.r) FILTER (WHERE d.tag < h.heute - 7) AS r28, count(d.r) FILTER (WHERE d.tag < h.heute - 7)::integer AS rn28,
               avg(d.i) FILTER (WHERE d.tag >= h.heute - 7) AS i7, count(d.i) FILTER (WHERE d.tag >= h.heute - 7)::integer AS in7,
               avg(d.i) FILTER (WHERE d.tag < h.heute - 7) AS i28, count(d.i) FILTER (WHERE d.tag < h.heute - 7)::integer AS in28
        FROM h LEFT JOIN d ON true)
  SELECT jsonb_build_object('kanal_id', p_kanal_id, 'schwelle', h.sw, 'von', to_char(h.heute - 7, 'YYYY-MM-DD'), 'bis', to_char(h.heute - 1, 'YYYY-MM-DD'),
    'reichweite', x.r, 'interaktionen', x.i,
    'einbruch', coalesce((x.r->>'einbruch')::boolean, false) OR coalesce((x.i->>'einbruch')::boolean, false))
  FROM h, s CROSS JOIN LATERAL (SELECT talents_einbruch_teil(s.r7, s.rn7, s.r28, s.rn28, 20, h.sw) AS r,
                                       talents_einbruch_teil(s.i7, s.in7, s.i28, s.in28, 5, h.sw) AS i) x
$function$
;

CREATE OR REPLACE FUNCTION public.talents_einbruch_schwelle()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN btrim(ally_einstellung('talents_einbruch_prozent')) ~ '^[0-9]{1,2}$'
                AND btrim(ally_einstellung('talents_einbruch_prozent'))::integer BETWEEN 1 AND 99
    THEN btrim(ally_einstellung('talents_einbruch_prozent'))::integer ELSE 30 END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_einbruch_teil(p_schnitt7 numeric, p_tage7 integer, p_schnitt28 numeric, p_tage28 integer, p_min numeric, p_schwelle integer)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT jsonb_build_object('schnitt_7', round(p_schnitt7, 1), 'schnitt_28', round(p_schnitt28, 1), 'tage_7', p_tage7, 'tage_28', p_tage28,
    'minus_prozent', m.minus, 'genug_daten', m.genug, 'einbruch', m.genug AND m.minus >= p_schwelle)
  FROM (SELECT coalesce(p_tage7, 0) >= 5 AND coalesce(p_tage28, 0) >= 20 AND coalesce(p_schnitt28, 0) >= p_min AND p_schnitt7 IS NOT NULL AS genug,
               CASE WHEN p_schnitt28 > 0 AND p_schnitt7 IS NOT NULL THEN round((1 - p_schnitt7 / p_schnitt28) * 100)::integer END AS minus) m
$function$
;

CREATE OR REPLACE FUNCTION public.talents_einladung_kanal(p_talent_id integer, p_plattform text)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT k.id FROM talent_kanaele k WHERE k.talent_id = p_talent_id AND k.plattform = p_plattform
  ORDER BY k.extern_id IS NULL DESC, k.status = 'verbunden', k.id LIMIT 1
$function$
;

CREATE OR REPLACE FUNCTION public.talents_einladung_standard()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT jsonb_build_object('betreff', 'Einladung: deine Kanäle mit [Agentur] verbinden',
    'text', E'Hallo [Name],\n\ndamit wir die Zahlen deiner Kanäle an einer Stelle auswerten können, verbinde sie bitte über diesen Link mit [Agentur]:\n[Link]\n\n'
      || 'Der Link gilt bis [Gültig bis]. Du meldest dich dabei direkt bei der jeweiligen Plattform an, dein Passwort sehen wir nicht. '
      || E'Die Freigabe kannst du jederzeit in den Einstellungen der Plattform wieder entziehen.\n\nViele Grüße\n[Agentur]')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_einladung_tage()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN btrim(ally_einstellung('talents_einladung_tage')) ~ '^[0-9]{1,2}$'
    THEN greatest(1, least(btrim(ally_einstellung('talents_einladung_tage'))::integer, 60)) ELSE 7 END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_einstellung_zahl(p_schluessel text, p_min integer, p_max integer, p_standard integer)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN btrim(coalesce(ally_einstellung(p_schluessel), '')) ~ '^[0-9]{1,5}$'
              AND btrim(ally_einstellung(p_schluessel))::integer BETWEEN p_min AND p_max
    THEN btrim(ally_einstellung(p_schluessel))::integer ELSE p_standard END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_entschluesseln_still(p bytea)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
  RETURN ally_entschluesseln(p);
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_erinnerungen_ausfuehren(p_jetzt timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  f record; d record; lid bigint; aid bigint; a record;
  n_e integer := 0; n_b integer := 0; n_m integer := 0; b integer;
  titel text; txt text; name_d text; tname text;
BEGIN
  -- Erinnerungen ausführen (BA6; Aufruf stündlich durch den Workflow „TALENTS Erinnerungen“, Vorschlag). Holt nach, was in den letzten 2 Tagen fällig wurde,
  -- jede Erinnerung genau einmal je Regel, Deliverable und Datum (talent_erinnerungen_lauf; verschobene Deadline = neue Erinnerung).
  -- An das Talent: Eintrag „Erinnerung“ im Talent-Bereich (Kanäle wie in der Regel), Benachrichtigung bei Kanal Talent-Bereich, Mail als offen vorgemerkt (Versand BA8).
  -- An die zuständigen Personen: Benachrichtigung in der Glocke (ally_benachrichtigen). Dazu: fällige eigene Erinnerungen (von Hand angelegt) melden.
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', true, 'erinnerungen', 0, 'benachrichtigungen', 0, 'mail_offen', 0);
  END IF;
  FOR f IN SELECT * FROM talents_erinnerungen_faellig(p_jetzt - interval '2 days', p_jetzt, NULL) x ORDER BY x.faellig_am, x.regel_id, x.deliverable_id LOOP
    lid := NULL;
    INSERT INTO talent_erinnerungen_lauf (regel_id, deliverable_id, bezug_datum, faellig_am, ausgefuehrt_am) VALUES (f.regel_id, f.deliverable_id, f.bezug_datum, f.faellig_am, p_jetzt)
    ON CONFLICT (regel_id, deliverable_id, bezug_datum) DO NOTHING RETURNING id INTO lid;
    CONTINUE WHEN lid IS NULL;
    SELECT dl.format, dl.anzahl, dl.titel, dl.deadline, dl.veroeffentlichen_am, k.name AS k_name, k.marke AS k_marke INTO d
    FROM talent_deliverables dl JOIN talent_kampagnen k ON k.id = dl.kampagne_id WHERE dl.id = f.deliverable_id;
    name_d := talents_planung_deliverable_name(d.format, d.anzahl, d.titel);
    tname := coalesce(talent_anzeigename(f.talent_id), 'Talent ' || f.talent_id);
    n_e := n_e + 1; b := 0; aid := NULL;
    IF f.empfaenger = 'talent' THEN
      titel := talents_planung_frist_text(f.bezug, f.versatz_tage) || ': ' || name_d;
      txt := d.k_marke || ' – ' || d.k_name || ', ' || CASE f.bezug WHEN 'deadline' THEN 'Deadline ' ELSE 'Veröffentlichung ' END || to_char(f.bezug_datum, 'DD.MM.YYYY') || '.';
      INSERT INTO talent_aufgaben (talent_id, kampagne_id, deliverable_id, art, titel, text, faellig_am, kanaele, quelle, regel_id, benachrichtigt_am, mail_status, erstellt_von)
      VALUES (f.talent_id, f.kampagne_id, f.deliverable_id, 'erinnerung', left(titel, 160), txt, f.faellig_am,
        ARRAY(SELECT k FROM unnest(f.kanaele) k WHERE k IN ('bereich', 'kalender', 'mail')), 'regel', f.regel_id,
        CASE WHEN 'bereich' = ANY (f.kanaele) THEN p_jetzt END, CASE WHEN 'mail' = ANY (f.kanaele) THEN 'offen' END, NULL)
      RETURNING id INTO aid;
      IF 'bereich' = ANY (f.kanaele) AND talents_benachrichtigen_talent(f.talent_id, 'kampagne_erinnerung', titel, txt, 'erinnerung:' || aid) THEN b := b + 1; END IF;
      IF 'mail' = ANY (f.kanaele) THEN n_m := n_m + 1; END IF;
    ELSE
      titel := talents_planung_frist_text(f.bezug, f.versatz_tage) || ': ' || name_d || ' von ' || tname;
      txt := d.k_marke || ' – ' || d.k_name || ', ' || CASE f.bezug WHEN 'deadline' THEN 'Deadline ' ELSE 'Veröffentlichung ' END || to_char(f.bezug_datum, 'DD.MM.YYYY') || '.';
      b := talents_planung_personen_melden(talents_planung_empfaenger(f.talent_id, f.kampagne_id), 'kampagne_erinnerung', left(titel, 120), txt,
        jsonb_build_object('seite', 'kampagnen', 'parameter', jsonb_build_object('kampagne', f.kampagne_id), 'anker', 'a-deliverables'),
        'r' || f.regel_id || 'd' || f.deliverable_id || ':' || to_char(f.bezug_datum, 'YYYYMMDD'), NULL);
    END IF;
    n_b := n_b + b;
    UPDATE talent_erinnerungen_lauf SET aufgabe_id = aid, benachrichtigungen = b WHERE id = lid;
  END LOOP;
  -- Von Hand angelegte Erinnerungen: zum Zeitpunkt eine Benachrichtigung im Talent-Bereich
  FOR a IN SELECT x.* FROM talent_aufgaben x JOIN talents t ON t.id = x.talent_id AND t.status = 'aktiv'
           WHERE x.art = 'erinnerung' AND x.quelle = 'hand' AND x.status = 'offen' AND x.benachrichtigt_am IS NULL
             AND x.faellig_am <= p_jetzt AND x.faellig_am > p_jetzt - interval '2 days' AND 'bereich' = ANY (x.kanaele)
           ORDER BY x.faellig_am, x.id LOOP
    UPDATE talent_aufgaben SET benachrichtigt_am = p_jetzt WHERE id = a.id;
    IF talents_benachrichtigen_talent(a.talent_id, 'kampagne_erinnerung', 'Erinnerung: ' || a.titel, a.text, 'erinnerung:' || a.id) THEN n_b := n_b + 1; END IF;
    n_e := n_e + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'erinnerungen', n_e, 'benachrichtigungen', n_b, 'mail_offen', n_m);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_erinnerungen_faellig(p_von timestamp with time zone, p_bis timestamp with time zone, p_kampagne_id integer)
 RETURNS TABLE(regel_id integer, deliverable_id bigint, kampagne_id integer, talent_id integer, bezug text, bezug_datum date, versatz_tage integer, faellig_am timestamp with time zone, empfaenger text, kanaele text[])
 LANGUAGE sql
 STABLE
AS $function$
  -- Erinnerungen, die zwischen p_von (ausschließlich) und p_bis (einschließlich) fällig werden und noch nicht ausgeführt sind (BA6).
  -- Nur laufende bzw. geplante, nicht abgebrochene Kampagnen mit eingeschalteten Erinnerungen, aktive Talents, Paket Talents gebucht.
  -- Deadline-Regeln nur, solange der Entwurf noch fehlt (geplant, Entwurf, Überarbeiten); Veröffentlichungs-Regeln bis zur Veröffentlichung.
  WITH k AS (
    SELECT ka.id FROM talent_kampagnen ka
    WHERE ka.abgebrochen_am IS NULL AND ka.erinnerungen_an AND NOT ka.testdaten /* Testdaten (Migration 79) */ AND plattform_modul_an('talents') AND (p_kampagne_id IS NULL OR ka.id = p_kampagne_id)),
  x AS (
    SELECT r.id AS regel_id, d.id AS deliverable_id, d.kampagne_id, d.talent_id, r.bezug,
      CASE r.bezug WHEN 'deadline' THEN d.deadline ELSE d.veroeffentlichen_am END AS bd, r.versatz_tage, r.uhrzeit, r.empfaenger, r.kanaele, d.status, d.sichtbar_fuer_talent
    FROM k CROSS JOIN LATERAL talents_erinnerungsregeln_wirksam(k.id) r
    JOIN talent_deliverables d ON d.kampagne_id = k.id
    JOIN talents t ON t.id = d.talent_id AND t.status = 'aktiv' AND NOT t.testdaten
    WHERE r.aktiv)
  SELECT x.regel_id, x.deliverable_id, x.kampagne_id, x.talent_id, x.bezug, x.bd, x.versatz_tage, f.f, x.empfaenger, x.kanaele
  FROM x CROSS JOIN LATERAL (SELECT ((x.bd + x.versatz_tage) + x.uhrzeit) AT TIME ZONE 'Europe/Berlin' AS f) f
  WHERE x.bd IS NOT NULL AND f.f > p_von AND f.f <= p_bis
    AND CASE x.bezug WHEN 'deadline' THEN x.status IN ('geplant', 'entwurf', 'ueberarbeiten') ELSE x.status NOT IN ('veroeffentlicht', 'abgerechnet') END
    AND (x.empfaenger <> 'talent' OR x.sichtbar_fuer_talent)
    AND NOT EXISTS (SELECT 1 FROM talent_erinnerungen_lauf l WHERE l.regel_id = x.regel_id AND l.deliverable_id = x.deliverable_id AND l.bezug_datum = x.bd)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_erinnerungsregeln_wirksam(p_kampagne_id integer)
 RETURNS SETOF talent_erinnerungsregeln
 LANGUAGE sql
 STABLE
AS $function$
  -- Regeln, die für eine Kampagne gelten: eigene Regeln der Kampagne, sonst die Standard-Regeln (kampagne_id NULL)
  -- Migration 129: ohne Regeln im Papierkorb
  SELECT r.* FROM talent_erinnerungsregeln r
  WHERE r.geloescht_am IS NULL
    AND (r.kampagne_id = p_kampagne_id
     OR (r.kampagne_id IS NULL AND NOT EXISTS (SELECT 1 FROM talent_erinnerungsregeln e WHERE e.kampagne_id = p_kampagne_id AND e.geloescht_am IS NULL)))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_export_daten(p_ids integer[], p_teil text, p_offset integer, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  r jsonb;
BEGIN
  -- Accounts mit offener Löschanfrage von Meta (Migration 50) sind in keinem Teil mit Kanalbezug enthalten (Stefan 18.10.2026)
  -- Migration 153 (Stefan 25.10.2026): Testdaten werden mit exportiert (bis Migration 153 hier herausgefiltert, Migration 79)
  IF p_teil = 'talents' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(t.id, t.name, t.kuenstlername, t.email, t.status,
        (SELECT string_agg(p.name, ', ' ORDER BY lower(p.name) COLLATE "C") FROM talent_personen tp JOIN ally_personen p ON p.matrix_user_id = tp.matrix_user_id WHERE tp.talent_id = t.id),
        t.notiz, t.verfolgung_tage, talents_export_zeit(t.erstellt_am), talents_export_zeit(t.archiviert_am)) AS z,
        row_number() OVER (ORDER BY t.id) AS o, count(*) OVER () AS n
      FROM talents t WHERE t.id = ANY (p_ids) ORDER BY t.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'kanaele' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(k.id, k.talent_id, k.plattform, k.extern_name, k.extern_id, k.status, k.anmeldeweg, talents_export_zeit(k.verbunden_am),
        talents_export_zeit(k.gueltig_bis), talents_export_zeit(k.letzter_abruf), array_to_string(k.berechtigungen, ',')) AS z,
        row_number() OVER (ORDER BY k.id) AS o, count(*) OVER () AS n
      FROM talent_kanaele k WHERE k.talent_id = ANY (p_ids) AND NOT meta_loeschung_offen(k.id) ORDER BY k.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'konto_tage' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(d.kanal_id, k.talent_id, k.plattform, k.extern_name, to_char(d.tag, 'YYYY-MM-DD'), talents_zahl(d.werte->'reach'), talents_aufrufe(d.werte),
        talents_interaktionen(d.werte), talents_zahl(d.werte->'followers_count'), d.werte::text, talents_export_zeit(d.abgerufen_am)) AS z,
        row_number() OVER (ORDER BY d.kanal_id, d.tag) AS o, count(*) OVER () AS n
      FROM talent_kanal_tage d JOIN talent_kanaele k ON k.id = d.kanal_id WHERE k.talent_id = ANY (p_ids) AND NOT meta_loeschung_offen(k.id) ORDER BY d.kanal_id, d.tag OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil IN ('beitraege', 'storys') THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(b.id, b.kanal_id, k.talent_id, k.plattform, k.extern_name, b.extern_id, talents_beitrag_art(b.art, b.produkt_art),
        talents_export_zeit(coalesce(b.erstellt, b.erfasst_am)), b.link, b.text_inhalt, b.verfolgung_tage, CASE WHEN b.abgeschlossen THEN 'ja' ELSE 'nein' END,
        talents_zahl(b.werte->'reach'), talents_aufrufe(b.werte), talents_interaktionen(b.werte), b.werte::text, talents_export_zeit(b.aktualisiert_am)) AS z,
        row_number() OVER (ORDER BY b.kanal_id, coalesce(b.erstellt, b.erfasst_am), b.id) AS o, count(*) OVER () AS n
      FROM talent_beitraege b JOIN talent_kanaele k ON k.id = b.kanal_id
      WHERE k.talent_id = ANY (p_ids) AND NOT meta_loeschung_offen(k.id) AND (talents_beitrag_art(b.art, b.produkt_art) = 'story') = (p_teil = 'storys')
      ORDER BY b.kanal_id, coalesce(b.erstellt, b.erfasst_am), b.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'beitrag_tage' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(d.beitrag_id, k.talent_id, to_char(d.tag, 'YYYY-MM-DD'), talents_zahl(d.werte->'reach'), talents_aufrufe(d.werte), talents_interaktionen(d.werte),
        d.werte::text, talents_export_zeit(d.abgerufen_am)) AS z,
        row_number() OVER (ORDER BY d.beitrag_id, d.tag) AS o, count(*) OVER () AS n
      FROM talent_beitrag_tage d JOIN talent_beitraege b ON b.id = d.beitrag_id JOIN talent_kanaele k ON k.id = b.kanal_id
      WHERE k.talent_id = ANY (p_ids) AND NOT meta_loeschung_offen(k.id) ORDER BY d.beitrag_id, d.tag OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'zielgruppen' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(z.kanal_id, k.talent_id, k.plattform, k.extern_name, to_char(z.stand, 'YYYY-MM-DD'), z.art, e.key, e.value #>> '{}') AS z,
        row_number() OVER (ORDER BY z.kanal_id, z.stand, z.art COLLATE "C", e.key COLLATE "C") AS o, count(*) OVER () AS n
      FROM talent_zielgruppen z JOIN talent_kanaele k ON k.id = z.kanal_id CROSS JOIN LATERAL jsonb_each(z.werte) e
      WHERE k.talent_id = ANY (p_ids) AND NOT meta_loeschung_offen(k.id) ORDER BY z.kanal_id, z.stand, z.art COLLATE "C", e.key COLLATE "C" OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'kampagnen' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(k.id, k.marke, k.name, to_char(k.von, 'YYYY-MM-DD'), to_char(k.bis, 'YYYY-MM-DD'), array_to_string(k.marken_konten, ', '),
        array_to_string(k.hashtags, ', '), array_to_string(k.schlagwoerter, ', '),
        (SELECT string_agg(kt.talent_id::text, ', ' ORDER BY kt.talent_id) FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = ANY (p_ids)),
        talents_export_zeit(k.erstellt_am)) AS z,
        row_number() OVER (ORDER BY k.id) AS o, count(*) OVER () AS n
      FROM talent_kampagnen k WHERE EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = ANY (p_ids))
      ORDER BY k.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'kampagne_beitraege' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(kb.kampagne_id, kb.beitrag_id, k.talent_id, kb.status, kb.quelle, kb.grund, talents_export_zeit(coalesce(kb.geaendert_am, kb.erstellt_am))) AS z,
        row_number() OVER (ORDER BY kb.kampagne_id, kb.beitrag_id) AS o, count(*) OVER () AS n
      FROM talent_kampagne_beitraege kb JOIN talent_beitraege b ON b.id = kb.beitrag_id JOIN talent_kanaele k ON k.id = b.kanal_id
      WHERE k.talent_id = ANY (p_ids) AND NOT meta_loeschung_offen(k.id) ORDER BY kb.kampagne_id, kb.beitrag_id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'notizen' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(n.id, n.talent_id, talents_export_zeit(n.erstellt_am), coalesce((SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = n.erstellt_von), 'Ehemalige Person'),
        n.text, talents_export_zeit(n.geaendert_am)) AS z,
        row_number() OVER (ORDER BY n.talent_id, n.erstellt_am, n.id) AS o, count(*) OVER () AS n
      FROM talent_notizen n WHERE n.talent_id = ANY (p_ids) ORDER BY n.talent_id, n.erstellt_am, n.id OFFSET p_offset LIMIT p_limit) q;
  -- Zahlen ohne Verbindung (Migration 47) (Stefan 18.10.2026)
  ELSIF p_teil = 'manuelle_werte' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(w.talent_id, w.plattform, w.konto, w.bereich, w.kennzahl, w.wert, w.werte::text, to_char(w.von, 'YYYY-MM-DD'), to_char(w.bis, 'YYYY-MM-DD'),
        to_char(w.beitrag_datum, 'YYYY-MM-DD'), w.beitrag_link, w.quelle, w.quelle_text, talents_export_zeit(w.bestaetigt_am)) AS z,
        row_number() OVER (ORDER BY w.talent_id, w.bis, w.id) AS o, count(*) OVER () AS n
      FROM talent_manuell_werte w WHERE w.talent_id = ANY (p_ids) ORDER BY w.talent_id, w.bis, w.id OFFSET p_offset LIMIT p_limit) q;
  -- Gesamtkonzepte, Ziele, Marken-Suchen, Kriterien, Texte (Migration 49)
  ELSIF p_teil IN (SELECT e->>'teil' FROM jsonb_array_elements(talents_ki_export_teile()) e) THEN
    r := talents_ki_export_daten(p_ids, p_teil, p_offset, p_limit);
  -- Deliverables, Entwürfe und Aufgaben (Migration 61, Stefan 20.10.2026)
  ELSIF p_teil IN (SELECT e->>'teil' FROM jsonb_array_elements(talents_planung_export_teile()) e) THEN
    r := talents_planung_export_daten(p_ids, p_teil, p_offset, p_limit);
  -- Zugang und Talent-Bereich (Migration 62, Stefan 20.10.2026)
  ELSIF p_teil IN (SELECT e->>'teil' FROM jsonb_array_elements(talents_bereich_export_teile()) e) THEN
    r := talents_bereich_export_daten(p_ids, p_teil, p_offset, p_limit);
  END IF;
  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_export_geld(p_user text, p_talent_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Honorare im DSGVO-Export (Migration 64): Recht „Honorare und Budgets sehen“ für alle, oder für zugeordnete und das Talent ist der Person zugeordnet
  SELECT CASE ally_recht_reichweite(p_user, 'talents_betraege')
    WHEN 'alle' THEN true
    WHEN 'zugeordnet' THEN EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = p_talent_id AND tp.matrix_user_id = p_user)
    ELSE false END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_export_start(p_token text, p_talent text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  g jsonb := talents_export_umfang(p_token, p_talent);
  ids integer[]; teile jsonb; je integer := 2000; name text; bes text; ohne integer;
BEGIN
  IF NOT (g->>'ok')::boolean THEN RETURN g; END IF;
  -- Migration 153 (Stefan 25.10.2026: „dafür sind Testdaten da“): Testdaten werden exportiert wie echte Talents – einzeln, als Auswahl (auch gemischt) und mit „alle“.
  -- Bis Migration 153: einzelnes Test-Talent und Auswahl nur aus Testdaten abgelehnt („Testdaten werden nicht exportiert.“), Testdaten sonst nicht mitgezählt (Migration 79/146).
  ids := ARRAY(SELECT x::integer FROM jsonb_array_elements_text(g->'ids') x);
  name := CASE WHEN g->>'umfang' = 'talent' THEN talent_listenname((g->>'talent_id')::integer) END;
  SELECT jsonb_agg(e || jsonb_build_object('anzahl', n.n, 'seiten', greatest(1, ceil(n.n / je::numeric)::integer)) ORDER BY o) INTO teile
  FROM jsonb_array_elements(talents_export_teile()) WITH ORDINALITY AS a(e, o)
  CROSS JOIN LATERAL (SELECT (talents_export_daten(ids, e->>'teil', 0, 1)->>'anzahl')::integer AS n) n;
  SELECT count(*)::integer INTO ohne FROM talent_kanaele k WHERE k.talent_id = ANY (ids) AND meta_loeschung_offen(k.id);
  bes := 'Export aus ' || produkt_name() || ' – Talents' || E'\r\n'
    || 'Erstellt am ' || talents_zeit(now()) || ' für ' || coalesce(nullif(btrim(eigenes_unternehmen()->>'name'), ''), 'die Agentur') || E'\r\n'
    || 'Umfang: ' || CASE WHEN g->>'umfang' = 'auswahl' THEN 'ausgewählte Talents (' || cardinality(ids) || ')' WHEN name IS NULL THEN 'alle Talents (' || cardinality(ids) || ')' ELSE name || ' (Talent ' || (g->>'talent_id') || ')' END || E'\r\n\r\n'
    || 'Format: CSV, UTF-8, Trennzeichen Semikolon, Text in Anführungszeichen, Dezimalzahlen mit Punkt, Zeiten in deutscher Zeit (Europe/Berlin). '
    || 'Texte, die mit = + - @ beginnen, haben zum Schutz vor Formeln ein vorangestelltes Hochkomma. Zugangsschlüssel der Talents sind nie enthalten.' || E'\r\n'
    -- Berichte liegen als PDF im Ordner Berichte/ (Migration 47); Accounts mit offener Löschanfrage von Meta fehlen (Migration 50) (Stefan 18.10.2026)
    || 'Erzeugte Berichte (PDF) liegen im Ordner Berichte/. Texte von Mails sind nicht enthalten.' || E'\r\n'
    || CASE WHEN ohne > 0 THEN 'Nicht enthalten: ' || ohne || CASE WHEN ohne = 1 THEN ' Account, für den' ELSE ' Accounts, für die' END
         || ' über Meta die Löschung der Daten verlangt wurde (die Verbindung ist getrennt, die Daten werden gelöscht).' || E'\r\n' ELSE '' END
    || (SELECT string_agg(E'\r\n' || (e->>'datei') || ' – ' || (e->>'titel') || ' (' || (e->>'anzahl') || ' Zeilen)' || E'\r\n'
          || (SELECT string_agg('  ' || (s->>'name') || ': ' || (s->>'beschreibung'), E'\r\n' ORDER BY so) FROM jsonb_array_elements(e->'spalten') WITH ORDINALITY AS sp(s, so)), E'\r\n' ORDER BY o)
        FROM jsonb_array_elements(teile) WITH ORDINALITY AS a(e, o)) || E'\r\n';
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'umfang', g->>'umfang', 'talent_id', g->'talent_id', 'anzeigename', name, 'anzahl_talents', cardinality(ids),
    'dateiname', CASE WHEN g->>'umfang' = 'auswahl' THEN 'talents-auswahl-export-' WHEN name IS NULL THEN 'talents-export-' ELSE 'talent-' || (g->>'talent_id') || '-export-' END || to_char(talents_heute(), 'YYYY-MM-DD') || '.zip',
    'erstellt', talents_zeit(now()),
    -- Migration 146: Umfang für talents_export_teil, so wie er geprüft wurde (Talent, „alle“ oder die Nummern der Auswahl); ALLY 20 „Seiten planen“ gibt ihn weiter
    'teil_umfang', CASE g->>'umfang' WHEN 'talent' THEN g->>'talent_id' WHEN 'auswahl' THEN (SELECT string_agg(x, ',' ORDER BY x::integer) FROM jsonb_array_elements_text(g->'ids') x) ELSE 'alle' END, 'je_seite', je, 'teile', teile, 'beschreibung_datei', 'LIESMICH.txt', 'beschreibung', bes);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_export_teil(p_token text, p_talent text, p_teil text, p_seite integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  g jsonb := talents_export_umfang(p_token, p_talent);
  t jsonb; ids integer[]; r jsonb; s integer := greatest(coalesce(p_seite, 1), 1); je integer := 2000; u text;
BEGIN
  IF NOT (g->>'ok')::boolean THEN RETURN g; END IF;
  SELECT e INTO t FROM jsonb_array_elements(talents_export_teile()) e WHERE e->>'teil' = p_teil;
  IF t IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Unbekannter Teil des Exports.');
  END IF;
  ids := ARRAY(SELECT x::integer FROM jsonb_array_elements_text(g->'ids') x);
  r := talents_export_daten(ids, p_teil, (s - 1) * je, je);
  -- Honorare (Spalte 11 der Deliverables) nur für Admin und die für das Talent zuständige Person aus dem Management; sonst leer (Stefan 20.10.2026, BA7)
  IF p_teil = 'deliverables' THEN
    u := talents_ansicht_start(p_token)->>'u';
    r := jsonb_set(r, '{zeilen}', (SELECT coalesce(jsonb_agg(CASE WHEN talents_export_geld(u, (z->>2)::integer) THEN z ELSE jsonb_set(z, '{10}', 'null'::jsonb) END ORDER BY o), '[]'::jsonb)
      FROM jsonb_array_elements(r->'zeilen') WITH ORDINALITY AS x(z, o)));
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'teil', p_teil, 'datei', t->>'datei', 'seite', s, 'je_seite', je,
    'spalten', (SELECT jsonb_agg(x->'name' ORDER BY o) FROM jsonb_array_elements(t->'spalten') WITH ORDINALITY AS a(x, o)),
    'zeilen', r->'zeilen', 'anzahl_seite', jsonb_array_length(r->'zeilen'));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_export_teile()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Teil 11 Zahlen ohne Verbindung (Migration 47), danach die Teile aus Migration 49 (talents_ki_export_teile) (Stefan 18.10.2026)
  -- und die Kampagnenplanung aus Migration 61 (talents_planung_export_teile: Deliverables, Entwürfe, Aufgaben) (Stefan 20.10.2026)
  -- und Zugang und Talent-Bereich aus Migration 62 (talents_bereich_export_teile) (Stefan 20.10.2026, BA7)
  SELECT jsonb_agg(e ORDER BY o) FROM (SELECT e, o FROM jsonb_array_elements((
  SELECT jsonb_agg(jsonb_build_object('teil', x.t, 'datei', x.t || '.csv', 'titel', x.ti,
    'spalten', (SELECT jsonb_agg(jsonb_build_object('name', split_part(s, '|', 1), 'beschreibung', split_part(s, '|', 2)) ORDER BY o) FROM unnest(x.sp) WITH ORDINALITY AS u(s, o))) ORDER BY x.o)
  FROM (VALUES
    (1, 'talents', 'Talents mit Stammdaten', ARRAY['talent_id|Nummer des Talents in Ally', 'name|Name', 'kuenstlername|Künstlername', 'email|E-Mail-Adresse des Talents',
      'status|aktiv oder archiviert', 'zustaendig|Manager und Managerinnen der Agentur', 'notiz|Notiz in den Stammdaten', 'verfolgung_tage|eigene Verfolgungsdauer für Beiträge in Tagen (leer = Standard, 0 = unbegrenzt)',
      'erstellt_am|angelegt am', 'archiviert_am|archiviert am']),
    (2, 'kanaele', 'Kanäle (Accounts) je Talent', ARRAY['kanal_id|Nummer des Kanals in Ally', 'talent_id|Talent', 'plattform|Plattform', 'account|Name des Accounts',
      'account_id|Kennung des Accounts bei der Plattform', 'status|offen, verbunden, abgelaufen oder getrennt', 'anmeldeweg|Anmeldung (facebook = über Facebook, instagram = direkt)',
      'verbunden_am|verbunden am', 'gueltig_bis|Verbindung gültig bis', 'letzter_abruf|letzter Abruf der Zahlen', 'berechtigungen|erteilte Berechtigungen']),
    (3, 'konto_tage', 'Zahlen je Konto und Tag', ARRAY['kanal_id|Kanal', 'talent_id|Talent', 'plattform|Plattform', 'account|Account', 'tag|Tag (JJJJ-MM-TT)',
      'reichweite|Reichweite des Tages', 'aufrufe|Aufrufe des Tages', 'interaktionen|Interaktionen des Tages', 'follower|Follower am Tag',
      'werte_json|alle gelieferten Kennzahlen des Tages (JSON, Namen der Plattform)', 'abgerufen_am|abgerufen am']),
    (4, 'beitraege', 'Beiträge (ohne Storys) mit letztem Stand', ARRAY['beitrag_id|Nummer des Beitrags in Ally', 'kanal_id|Kanal', 'talent_id|Talent', 'plattform|Plattform',
      'account|Account', 'beitrag_kennung|Kennung des Beitrags bei der Plattform', 'art|Reel, Karussell, Bild, Video, Story oder sonstige', 'veroeffentlicht|veröffentlicht am',
      'link|Link zum Beitrag', 'text|Beitragstext (nur bei Anmeldung über Facebook)', 'verfolgung_tage|eigene Verfolgungsdauer in Tagen (leer = Standard, 0 = unbegrenzt)',
      'abgeschlossen|ja = Zahlen eingefroren', 'reichweite|Reichweite (letzter Stand)', 'aufrufe|Aufrufe (letzter Stand)', 'interaktionen|Interaktionen (letzter Stand)',
      'werte_json|alle gelieferten Kennzahlen (JSON, Namen der Plattform)', 'zuletzt_abgerufen|Zahlen abgerufen am']),
    (5, 'storys', 'Storys mit letztem Stand', ARRAY['beitrag_id|Nummer der Story in Ally', 'kanal_id|Kanal', 'talent_id|Talent', 'plattform|Plattform',
      'account|Account', 'beitrag_kennung|Kennung bei der Plattform', 'art|Story', 'veroeffentlicht|veröffentlicht am', 'link|Link', 'text|Text (Storys haben meist keinen)',
      'verfolgung_tage|immer leer (Storys: 24 Stunden)', 'abgeschlossen|ja = Zahlen eingefroren', 'reichweite|Reichweite', 'aufrufe|Aufrufe', 'interaktionen|Interaktionen',
      'werte_json|alle gelieferten Kennzahlen (JSON)', 'zuletzt_abgerufen|Zahlen abgerufen am']),
    (6, 'beitrag_tage', 'Verlauf je Beitrag und Abruftag (Gesamtstand seit Veröffentlichung)', ARRAY['beitrag_id|Beitrag oder Story', 'talent_id|Talent', 'tag|Abruftag (JJJJ-MM-TT)',
      'reichweite|Reichweite bis zu diesem Tag', 'aufrufe|Aufrufe bis zu diesem Tag', 'interaktionen|Interaktionen bis zu diesem Tag', 'werte_json|alle gelieferten Kennzahlen (JSON)', 'abgerufen_am|abgerufen am']),
    (7, 'zielgruppen', 'Zielgruppen-Stände (Demografie)', ARRAY['kanal_id|Kanal', 'talent_id|Talent', 'plattform|Plattform', 'account|Account', 'stand|Stand vom (JJJJ-MM-TT)',
      'art|Gruppe und Aufteilung, z. B. follower_demographics:age', 'merkmal|Merkmal, z. B. Altersgruppe, Land, Stadt, F/M/U', 'wert|Anzahl']),
    (8, 'kampagnen', 'Kampagnen', ARRAY['kampagne_id|Nummer der Kampagne', 'marke|Marke', 'name|Name der Kampagne', 'von|Beginn', 'bis|Ende', 'marken_accounts|Marken-@Namen zur Erkennung',
      'hashtags|Hashtags zur Erkennung', 'schlagwoerter|Schlagwörter zur Erkennung', 'talents|beteiligte Talents (Nummern)', 'erstellt_am|angelegt am']),
    (9, 'kampagne_beitraege', 'Zuordnung von Beiträgen zu Kampagnen', ARRAY['kampagne_id|Kampagne', 'beitrag_id|Beitrag', 'talent_id|Talent',
      'status|bestaetigt (zugeordnet), vorschlag (von Ally vorgeschlagen) oder entfernt (vom Manager oder von der Managerin abgelehnt)', 'quelle|automatisch (Vorschlag) oder manuell',
      'grund|Grund des Vorschlags', 'geaendert_am|zuletzt geändert am']),
    (10, 'notizen', 'Notizen der Agentur', ARRAY['notiz_id|Nummer der Notiz', 'talent_id|Talent', 'erstellt_am|geschrieben am', 'autor|geschrieben von', 'text|Text', 'geaendert_am|zuletzt geändert am']),
    (11, 'manuelle_werte', 'Zahlen ohne Verbindung (vom Talent geliefert, vom Manager oder von der Managerin bestätigt)', ARRAY['talent_id|Talent', 'plattform|Plattform', 'konto|Account (@Name)',
      'bereich|konto, beitrag oder zielgruppe', 'kennzahl|Kennzahl', 'wert|Wert (leer bei Zielgruppe)', 'werte_json|Zielgruppe als JSON (z. B. Altersgruppen in Prozent)',
      'von|Zeitraum von', 'bis|Zeitraum bis (bei Follower: Stand)', 'beitrag_datum|Datum des Beitrags', 'beitrag_link|Link zum Beitrag',
      'quelle|hochladen, mail, chat oder hand', 'quelle_text|Herkunft (z. B. Mail vom …, Datei …)', 'bestaetigt_am|bestätigt am'])
  ) AS x(o, t, ti, sp)) || talents_ki_export_teile() || talents_planung_export_teile() || talents_bereich_export_teile()) WITH ORDINALITY AS a(e, o)) z
$function$
;

CREATE OR REPLACE FUNCTION public.talents_export_umfang(p_token text, p_talent text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb := talents_ansicht_start(p_token);
  x text := lower(btrim(coalesce(p_talent, '')));
BEGIN
  IF NOT (c->>'ok')::boolean THEN RETURN c - 'u'; END IF;
  IF NOT (c->>'verw')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Exportieren darf, wer das Recht „Talents und Kampagnen verwalten“ für alle Talents hat.');
  END IF;
  IF x IN ('', 'alle') THEN
    RETURN jsonb_build_object('ok', true, 'umfang', 'alle', 'talent_id', NULL, 'ids', to_jsonb(ARRAY(SELECT t.id FROM talents t ORDER BY t.id)));
  ELSIF x ~ '^[0-9]{1,9}$' AND EXISTS (SELECT 1 FROM talents t WHERE t.id = x::integer) THEN
    RETURN jsonb_build_object('ok', true, 'umfang', 'talent', 'talent_id', x::integer, 'ids', jsonb_build_array(x::integer));
  -- Migration 146 (Stefan 24.10.2026, E4): ausgewählte Talents als Liste „12,15,20“ (2 bis 1000 Nummern); alle müssen es geben, doppelte zählen einmal
  ELSIF x ~ '^[0-9]{1,9}(,[0-9]{1,9})+$' AND cardinality(string_to_array(x, ',')) <= 1000 THEN
    IF EXISTS (SELECT 1 FROM unnest(string_to_array(x, ',')) v WHERE NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = v::integer)) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Unbekanntes Talent. Bitte die Seite neu laden.');
    END IF;
    RETURN jsonb_build_object('ok', true, 'umfang', 'auswahl', 'talent_id', NULL,
      'ids', to_jsonb(ARRAY(SELECT DISTINCT v::integer FROM unnest(string_to_array(x, ',')) v ORDER BY 1)));
  END IF;
  RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Unbekanntes Talent. Bitte die Seite neu laden.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_export_zeit(p timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT to_char(p AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD HH24:MI:SS')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_gueltig_bis(p text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  x text := btrim(coalesce(p, ''));
  n numeric;
BEGIN
  IF x = '' OR x = '0' THEN
    RETURN NULL;
  END IF;
  IF x ~ '^[0-9]{1,12}([.][0-9]+)?$' THEN
    n := x::numeric;
    RETURN CASE WHEN n < 1000000000 THEN now() + make_interval(secs => n::double precision) ELSE to_timestamp(n::double precision) END;
  END IF;
  RETURN x::timestamptz;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_heute()
 RETURNS date
 LANGUAGE sql
 STABLE
AS $function$
  SELECT (now() AT TIME ZONE 'Europe/Berlin')::date
$function$
;

CREATE OR REPLACE FUNCTION public.talents_hinweis_verzoegerung()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT 'Instagram liefert Zahlen mit bis zu 48 Stunden Verzögerung. Die Werte der letzten beiden Tage können sich noch ändern.'::text
$function$
;

CREATE OR REPLACE FUNCTION public.talents_import(p_token text, p_import_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; imp talent_importe%ROWTYPE; z jsonb; anz integer; seite integer; je integer := 10;
  nf boolean := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN lower(coalesce(p_filter->>'nur_fehler', '')) IN ('1', 'true', 'ja') ELSE false END;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  IF NOT (c->>'verw')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Importieren darf, wer das Recht „Talents und Kampagnen verwalten“ für alle Talents hat.');
  END IF;
  IF p_import_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'import', NULL,
      'vorlage', jsonb_build_object('dateiname', 'talents-vorlage.csv',
        'csv', talents_csv(ARRAY['Name', 'Künstlername', 'E-Mail', 'Kanäle', 'Manager/in'], '[["Lena Beispiel","Lena K.","lena@example.org","Instagram, YouTube",""]]'::jsonb)),
      'erklaerung', 'Eine Zeile je Talent. Spalten: Name; Künstlername; E-Mail; Kanäle (z. B. „Instagram, YouTube“); Manager/in (Name oder E-Mail-Adresse einer Person, mehrere mit Komma; leer = du). '
        || 'Pflicht sind Name oder Künstlername und Kanäle. Höchstens 200 Zeilen. Gleiche E-Mail-Adressen werden abgelehnt.',
      -- Migration 165 (Bauplan B5c): Rollen für Talents zur Auswahl (Stefan G10)
      'rollen', (SELECT coalesce(jsonb_agg(jsonb_build_object('wert', r.schluessel, 'text', r.name) ORDER BY r.sortierung, lower(r.name), r.schluessel), '[]'::jsonb)
        FROM ally_rollen r WHERE r.art = 'talent' AND r.archiviert_am IS NULL),
      'offen', (SELECT coalesce(jsonb_agg(jsonb_build_object('import_id', i.id, 'erstellt', talents_zeit(i.erstellt_am), 'anzahl', jsonb_array_length(i.zeilen)) ORDER BY i.id DESC), '[]'::jsonb)
                FROM talent_importe i WHERE i.erstellt_von = c->>'u' AND i.angelegt_am IS NULL));
  END IF;
  SELECT * INTO imp FROM talent_importe i WHERE i.id = p_import_id AND i.erstellt_von = c->>'u';
  IF imp.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diesen Import gibt es nicht mehr. Bitte die Tabelle neu hochladen.');
  END IF;
  z := coalesce(imp.ergebnis, imp.zeilen);
  SELECT count(*)::integer INTO anz FROM jsonb_array_elements(z) x WHERE NOT nf OR NOT (x->>'ok')::boolean;
  seite := talents_seite_nr(p_filter->>'seite', anz, je);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true,
    'import', jsonb_build_object('id', imp.id, 'erstellt', talents_zeit(imp.erstellt_am), 'angelegt', imp.angelegt_am IS NOT NULL, 'angelegt_am', talents_zeit(imp.angelegt_am),
      'rolle_name', (SELECT r.name FROM ally_rollen r WHERE r.schluessel = coalesce(imp.rolle, 'talent'))),
    'filter', jsonb_build_object('nur_fehler', nf, 'seite', seite),
    'zeilen', (SELECT coalesce(jsonb_agg((x.v - 'personen' - 'einladung_id')
                  || CASE WHEN x.v->>'einladung_id' IS NOT NULL THEN jsonb_build_object('link', (SELECT talent_einladung_link(e.id) FROM talent_einladungen e
                       WHERE e.id = (x.v->>'einladung_id')::integer AND e.widerrufen_am IS NULL AND e.gueltig_bis > now())) ELSE '{}'::jsonb END ORDER BY x.o), '[]'::jsonb)
               FROM (SELECT v, row_number() OVER (ORDER BY (v->>'zeile')::integer) AS o FROM jsonb_array_elements(z) v WHERE NOT nf OR NOT (v->>'ok')::boolean) x
               WHERE x.o > (seite - 1) * je AND x.o <= seite * je),
    'anzahl', anz, 'anzahl_gesamt', jsonb_array_length(z),
    'anzahl_ok', (SELECT count(*) FROM jsonb_array_elements(z) x WHERE (x->>'ok')::boolean),
    'anzahl_fehler', (SELECT count(*) FROM jsonb_array_elements(z) x WHERE NOT (x->>'ok')::boolean),
    'anzahl_angelegt', (SELECT count(*) FROM jsonb_array_elements(z) x WHERE x->>'ergebnis' = 'angelegt'),
    'seite', seite, 'seiten', greatest(1, ceil(anz / je::numeric)::integer), 'je_seite', je,
    'darf_anlegen', imp.angelegt_am IS NULL AND EXISTS (SELECT 1 FROM jsonb_array_elements(z) x WHERE (x->>'ok')::boolean));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_import_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
DECLARE
  c jsonb; u text;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  fehler text; m text; erg jsonb; r jsonb; iid integer; imp talent_importe%ROWTYPE; e jsonb; ausgabe jsonb := '[]'::jsonb; tid integer; ei jsonb; n integer := 0;
BEGIN
  c := talents_aktion_start(p_token, true);
  IF c ? 'stumm' THEN RETURN c - 'stumm'; END IF;
  IF NOT (c->>'ok')::boolean THEN
    RETURN talents_aktion_ende(p_token, c->>'fehler', NULL, NULL, NULL);
  END IF;
  u := c->>'u';
  IF btrim(coalesce(d->>'import_id', '')) ~ '^[0-9]{1,9}$' THEN
    SELECT * INTO imp FROM talent_importe WHERE id = btrim(d->>'import_id')::integer AND erstellt_von = u FOR UPDATE;
  END IF;
  BEGIN
    IF p_aktion = 'import_pruefen' THEN
      IF btrim(coalesce(d->>'csv', '')) = '' THEN
        fehler := 'Bitte eine Tabelle (CSV) auswählen.';
      ELSIF length(d->>'csv') > 200000 THEN
        fehler := 'Die Tabelle ist zu groß (höchstens 200 Zeilen und 200 KB).';
      -- Migration 165 (Bauplan B5c): eine vorgemerkte Rolle für alle Talents der Tabelle (Stefan G10): nur aktive Rollen der Art talent; ohne Angabe gilt Talent.
      ELSIF nullif(btrim(coalesce(d->>'rolle', '')), '') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_rollen r WHERE r.schluessel = btrim(d->>'rolle') AND r.art = 'talent' AND r.archiviert_am IS NULL) THEN
        fehler := 'Diese Rolle gibt es nicht oder sie ist archiviert. Bitte eine andere wählen.';
      ELSE
        r := talents_import_pruefen(d->>'csv', u);
        IF NOT (r->>'ok')::boolean THEN
          fehler := r->>'fehler';
        ELSE
          -- alte Importe (älter als 7 Tage) und eigene, nicht angelegte entfallen (enthalten Namen und E-Mail-Adressen)
          DELETE FROM talent_importe WHERE erstellt_am < now() - interval '7 days' OR (erstellt_von = u AND angelegt_am IS NULL);
          INSERT INTO talent_importe (erstellt_von, zeilen, rolle) VALUES (u, r->'zeilen', nullif(btrim(coalesce(d->>'rolle', '')), '')) RETURNING id INTO iid;
          erg := jsonb_build_object('art', 'import_vorschau', 'import_id', iid, 'anzahl', r->'anzahl', 'anzahl_ok', r->'anzahl_ok');
          m := 'Tabelle geprüft: ' || (r->>'anzahl') || CASE WHEN (r->>'anzahl')::integer = 1 THEN ' Zeile' ELSE ' Zeilen' END || ', davon '
            || (r->>'anzahl_ok') || ' ohne Fehler.' || CASE WHEN (r->>'anzahl_ok')::integer > 0 THEN ' Bitte die Vorschau prüfen und dann „Talents anlegen“ wählen.' ELSE ' Bitte die Tabelle korrigieren und neu hochladen.' END;
        END IF;
      END IF;
    ELSIF p_aktion IN ('import_anlegen', 'import_verwerfen') AND imp.id IS NULL THEN
      fehler := 'Diesen Import gibt es nicht mehr. Bitte die Tabelle neu hochladen.';
    ELSIF p_aktion = 'import_verwerfen' THEN
      DELETE FROM talent_importe WHERE id = imp.id;
      m := 'Import verworfen.';
    ELSIF p_aktion = 'import_anlegen' THEN
      iid := imp.id;
      IF imp.angelegt_am IS NOT NULL THEN
        fehler := 'Diese Tabelle wurde schon angelegt.';
      ELSIF imp.rolle IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_rollen r WHERE r.schluessel = imp.rolle AND r.art = 'talent' AND r.archiviert_am IS NULL) THEN
        fehler := 'Die gewählte Rolle gibt es nicht mehr oder sie ist archiviert. Bitte die Tabelle neu hochladen.';
      ELSIF NOT ally_verschluesselung_bereit() THEN
        fehler := 'Verschlüsselung ist nicht eingerichtet.';
      ELSIF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(imp.zeilen) x WHERE (x->>'ok')::boolean) THEN
        fehler := 'In dieser Tabelle ist keine Zeile ohne Fehler. Bitte die Tabelle korrigieren und neu hochladen.';
      ELSE
        FOR e IN SELECT x FROM jsonb_array_elements(imp.zeilen) x LOOP
          IF NOT (e->>'ok')::boolean THEN
            ausgabe := ausgabe || jsonb_build_array(e || jsonb_build_object('ergebnis', 'übersprungen'));
          ELSIF e->>'email' IS NOT NULL AND EXISTS (SELECT 1 FROM talents t WHERE lower(t.email) = e->>'email') THEN
            ausgabe := ausgabe || jsonb_build_array(e || jsonb_build_object('ok', false, 'fehler', 'Diese E-Mail-Adresse gehört inzwischen zu einem Talent.', 'ergebnis', 'übersprungen'));
          ELSIF e->>'name' IS NOT NULL AND EXISTS (SELECT 1 FROM talents t WHERE lower(t.name) = lower(e->>'name') AND coalesce(lower(t.kuenstlername), '') = coalesce(lower(e->>'kuenstlername'), '')) THEN
            ausgabe := ausgabe || jsonb_build_array(e || jsonb_build_object('ok', false, 'fehler', 'Ein Talent mit diesem Namen gibt es inzwischen.', 'ergebnis', 'übersprungen'));
          ELSE
            INSERT INTO talents (name, kuenstlername, email, erstellt_von, geaendert_von, rolle) VALUES (e->>'name', e->>'kuenstlername', e->>'email', u, u, imp.rolle) RETURNING id INTO tid;
            INSERT INTO talent_personen (talent_id, matrix_user_id)
            SELECT tid, p FROM jsonb_array_elements_text(e->'personen') p WHERE EXISTS (SELECT 1 FROM ally_personen ap WHERE ap.matrix_user_id = p AND ap.aktiv AND NOT ally_rolle_ist_talent(ap.rolle)) ON CONFLICT DO NOTHING;
            IF NOT EXISTS (SELECT 1 FROM talent_personen WHERE talent_id = tid) THEN
              INSERT INTO talent_personen (talent_id, matrix_user_id) VALUES (tid, u);
            END IF;
            INSERT INTO talent_kanaele (talent_id, plattform) SELECT tid, k FROM jsonb_array_elements_text(e->'kanaele') k;
            ei := talent_einladung_anlegen(tid, u);
            n := n + 1;
            ausgabe := ausgabe || jsonb_build_array(e || jsonb_build_object('ergebnis', 'angelegt', 'talent_id', tid,
              'einladung_id', (SELECT max(x.id) FROM talent_einladungen x WHERE x.talent_id = tid), 'gueltig_bis', ei->>'gueltig_bis', 'link', ei->>'link'));
          END IF;
        END LOOP;
        UPDATE talent_importe SET angelegt_am = now(), ergebnis = (SELECT jsonb_agg(x - 'link') FROM jsonb_array_elements(ausgabe) x) WHERE id = imp.id;
        IF n = 0 THEN
          fehler := 'Es wurde kein Talent angelegt: Alle Zeilen haben inzwischen einen Fehler (z. B. E-Mail-Adresse schon vergeben).';
        ELSE
          erg := jsonb_build_object('art', 'import_ergebnis', 'import_id', imp.id, 'anzahl_angelegt', n, 'anzahl_uebersprungen', jsonb_array_length(ausgabe) - n,
            'dateiname', 'einladungslinks-' || to_char(talents_heute(), 'YYYY-MM-DD') || '.csv',
            'csv', talents_csv(ARRAY['Name', 'Künstlername', 'E-Mail', 'Link', 'gültig bis', 'Ergebnis'],
              (SELECT jsonb_agg(jsonb_build_array(x->>'name', x->>'kuenstlername', x->>'email', x->>'link', x->>'gueltig_bis', coalesce(x->>'fehler', x->>'ergebnis')) ORDER BY (x->>'zeile')::integer)
               FROM jsonb_array_elements(ausgabe) x)));
          m := CASE WHEN n = 1 THEN '1 Talent angelegt' ELSE n || ' Talents angelegt' END || ', jeweils mit Einladungslink. Die Tabelle mit allen Links steht zum Herunterladen bereit.'
            || CASE WHEN jsonb_array_length(ausgabe) > n THEN ' ' || (jsonb_array_length(ausgabe) - n) || ' Zeilen wurden wegen eines Fehlers übersprungen.' ELSE '' END;
        END IF;
      END IF;
    ELSE
      fehler := 'Unbekannte Aktion.';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    erg := NULL;
    fehler := CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Das hat nicht geklappt. Bitte noch einmal versuchen. (' || left(SQLERRM, 200) || ')' END;
  END;
  RETURN talents_aktion_ende(p_token, fehler, m, erg, jsonb_build_object('import_id', coalesce(iid, imp.id)));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_import_csv(p_token text, p_import_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; imp talent_importe%ROWTYPE;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  SELECT * INTO imp FROM talent_importe i WHERE i.id = p_import_id AND i.erstellt_von = c->>'u' AND i.angelegt_am IS NOT NULL;
  IF NOT (c->>'verw')::boolean OR imp.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diesen Import gibt es nicht mehr.');
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'dateiname', 'einladungslinks-' || to_char(talents_tag(imp.angelegt_am), 'YYYY-MM-DD') || '.csv',
    'csv', talents_csv(ARRAY['Name', 'Künstlername', 'E-Mail', 'Link', 'gültig bis', 'Ergebnis'],
      (SELECT jsonb_agg(jsonb_build_array(x->>'name', x->>'kuenstlername', x->>'email', l.link, CASE WHEN l.link IS NOT NULL THEN x->>'gueltig_bis' END,
          coalesce(x->>'fehler', CASE WHEN x->>'ergebnis' = 'angelegt' AND l.link IS NULL THEN 'angelegt, Link nicht mehr gültig' ELSE x->>'ergebnis' END)) ORDER BY (x->>'zeile')::integer)
       FROM jsonb_array_elements(imp.ergebnis) x
       LEFT JOIN LATERAL (SELECT talent_einladung_link(e.id) AS link FROM talent_einladungen e WHERE e.id = (x->>'einladung_id')::integer AND e.widerrufen_am IS NULL AND e.gueltig_bis > now()) l ON true)));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_import_pruefen(p_csv text, p_user text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
DECLARE
  z record; i integer; h text;
  i_na integer; i_kn integer; i_em integer; i_ka integer; i_zu integer;
  zeilen jsonb := '[]'::jsonb; gesehen jsonb := '{}'::jsonb;
  na text; kn text; em text; ka text[]; pe text[]; fe text[]; tok text; y text; n integer; pid text; pn text[];
BEGIN
  FOR z IN SELECT * FROM talents_csv_lesen(p_csv) LOOP
    IF z.nr = 1 THEN
      FOR i IN 1 .. coalesce(array_length(z.felder, 1), 0) LOOP
        h := regexp_replace(lower(z.felder[i]), '[^a-zäöüß]', '', 'g');
        IF h = 'name' THEN i_na := i;
        ELSIF h IN ('künstlername', 'kuenstlername', 'kunstlername') THEN i_kn := i;
        ELSIF h IN ('email', 'mail', 'emailadresse') THEN i_em := i;
        ELSIF h IN ('kanäle', 'kanaele', 'kanal', 'kanale', 'plattformen', 'plattform') THEN i_ka := i;
        ELSIF h ~ '^(manager|zuständig|zustaendig)' THEN i_zu := i;
        END IF;
      END LOOP;
      IF (i_na IS NULL AND i_kn IS NULL) OR i_ka IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'fehler', 'Die erste Zeile muss die Spaltennamen enthalten: Name; Künstlername; E-Mail; Kanäle; Manager/in. '
          || 'Pflicht sind Name oder Künstlername und Kanäle.');
      END IF;
      CONTINUE;
    END IF;
    IF z.nr > 201 THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Die Tabelle hat mehr als 200 Zeilen. Bitte in mehrere Tabellen aufteilen.');
    END IF;
    fe := '{}';
    na := nullif(btrim(coalesce(z.felder[i_na], '')), '');
    kn := nullif(btrim(coalesce(z.felder[i_kn], '')), '');
    em := nullif(lower(btrim(coalesce(z.felder[i_em], ''))), '');
    IF na IS NULL AND kn IS NULL THEN
      fe := fe || 'Name oder Künstlername fehlt.'::text;
    ELSIF length(coalesce(na, '')) > 120 OR length(coalesce(kn, '')) > 120 OR concat(na, kn) ~ '[[:cntrl:]]' THEN
      fe := fe || 'Name und Künstlername dürfen höchstens 120 Zeichen haben.'::text;
    ELSIF na IS NOT NULL AND EXISTS (SELECT 1 FROM talents t WHERE lower(t.name) = lower(na) AND coalesce(lower(t.kuenstlername), '') = coalesce(lower(kn), '')) THEN
      fe := fe || 'Ein Talent mit diesem Namen gibt es schon.'::text;
    END IF;
    IF em IS NOT NULL AND (length(em) > 200 OR em !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$') THEN
      fe := fe || 'Ungültige E-Mail-Adresse.'::text;
    ELSIF em IS NOT NULL AND EXISTS (SELECT 1 FROM talents t WHERE lower(t.email) = em) THEN
      fe := fe || 'Diese E-Mail-Adresse gehört schon zu einem Talent.'::text;
    ELSIF em IS NOT NULL AND gesehen ? em THEN
      fe := fe || ('Diese E-Mail-Adresse steht schon in Zeile ' || (gesehen->>em) || '.')::text;
    END IF;
    IF em IS NOT NULL AND NOT gesehen ? em THEN gesehen := gesehen || jsonb_build_object(em, z.nr); END IF;
    ka := '{}';
    FOREACH tok IN ARRAY regexp_split_to_array(lower(btrim(coalesce(z.felder[i_ka], ''))), '[[:space:],;|/+]+') LOOP
      CONTINUE WHEN tok = '';
      y := (SELECT p FROM unnest(talents_plattformen()) p WHERE p = tok OR lower(talents_plattform_name(p)) = tok LIMIT 1);
      IF y IS NULL THEN
        fe := fe || ('Unbekannter Kanal: ' || left(tok, 40) || '.')::text;
      ELSIF NOT y = ANY (ka) THEN
        ka := ka || y;
      END IF;
    END LOOP;
    IF cardinality(ka) = 0 AND NOT EXISTS (SELECT 1 FROM unnest(fe) e WHERE e LIKE 'Unbekannter Kanal%') THEN
      fe := fe || 'Bitte mindestens einen Kanal angeben (z. B. Instagram).'::text;
    END IF;
    pe := '{}'; pn := '{}';
    FOREACH tok IN ARRAY regexp_split_to_array(btrim(coalesce(z.felder[i_zu], '')), '[,;|]+') LOOP
      tok := btrim(tok);
      CONTINUE WHEN tok = '';
      SELECT count(*)::integer, min(p.matrix_user_id) INTO n, pid FROM ally_personen p
      WHERE p.aktiv AND NOT ally_rolle_ist_talent(p.rolle) AND (lower(p.name) = lower(tok) OR lower(coalesce(p.email, '')) = lower(tok) OR lower(coalesce(p.benutzername, '')) = lower(tok) OR p.matrix_user_id = tok);
      IF n = 0 THEN
        fe := fe || ('Unbekannte Person bei „Manager/in“: ' || left(tok, 60) || '.')::text;
      ELSIF n > 1 THEN
        fe := fe || ('Mehrere Personen passen zu „' || left(tok, 60) || '“. Bitte die E-Mail-Adresse angeben.')::text;
      ELSIF NOT pid = ANY (pe) THEN
        pe := pe || pid;
      END IF;
    END LOOP;
    IF cardinality(pe) = 0 AND EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = p_user AND p.aktiv) AND NOT EXISTS (SELECT 1 FROM unnest(fe) e WHERE e LIKE 'Unbekannte Person bei%' OR e LIKE 'Mehrere Personen%') THEN
      pe := ARRAY[p_user];
    END IF;
    zeilen := zeilen || jsonb_build_array(jsonb_build_object('zeile', z.nr, 'name', na, 'kuenstlername', kn, 'email', em,
      'kanaele', to_jsonb(ka), 'kanaele_text', (SELECT string_agg(talents_plattform_name(x), ', ' ORDER BY o) FROM unnest(ka) WITH ORDINALITY AS u(x, o)),
      'personen', to_jsonb(pe), 'personen_text', (SELECT string_agg(p.name, ', ' ORDER BY lower(p.name) COLLATE "C") FROM ally_personen p WHERE p.matrix_user_id = ANY (pe)),
      'ok', cardinality(fe) = 0, 'fehler', CASE WHEN cardinality(fe) > 0 THEN array_to_string(fe, ' ') END));
  END LOOP;
  IF jsonb_array_length(zeilen) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', CASE WHEN i_ka IS NULL THEN 'Die Tabelle ist leer.' ELSE 'Die Tabelle enthält keine Zeilen unter der Kopfzeile.' END);
  END IF;
  RETURN jsonb_build_object('ok', true, 'zeilen', zeilen, 'anzahl', jsonb_array_length(zeilen),
    'anzahl_ok', (SELECT count(*) FROM jsonb_array_elements(zeilen) e WHERE (e->>'ok')::boolean));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_interaktionen(w jsonb)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT coalesce(talents_zahl(w->'total_interactions'),
    CASE WHEN num_nonnulls(x.l, x.c, x.s, x.h) > 0 THEN coalesce(x.l, 0) + coalesce(x.c, 0) + coalesce(x.s, 0) + coalesce(x.h, 0) END)
  FROM (SELECT coalesce(talents_zahl(w->'likes'), talents_zahl(w->'like_count')) AS l,
               coalesce(talents_zahl(w->'comments'), talents_zahl(w->'comments_count')) AS c,
               coalesce(talents_zahl(w->'saved'), talents_zahl(w->'saves')) AS s,
               talents_zahl(w->'shares') AS h) x
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ist_testdaten(p_talent_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 79: gehört das Talent zu den Testdaten? (NULL oder unbekannt: nein)
  SELECT coalesce((SELECT t.testdaten FROM talents t WHERE t.id = p_talent_id), false)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kachel(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb;
  u text;
  verw boolean;
  heute date := talents_heute();
  n_t integer; n_k integer; n_bald integer; n_ab integer; n_neu integer; n_story integer;
  warn text;
  zeilen jsonb;
  vr jsonb := '{}'::jsonb;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN
    RETURN c || jsonb_build_object('anzeigen', false);
  END IF;
  u := c->>'u';
  verw := (c->>'verw')::boolean;

  SELECT count(*)::integer INTO n_t FROM talents t
  WHERE t.status = 'aktiv' AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u));
  SELECT count(*) FILTER (WHERE k.status = 'verbunden')::integer,
         count(*) FILTER (WHERE k.status = 'verbunden' AND k.gueltig_bis IS NOT NULL AND k.gueltig_bis < now() + interval '7 days')::integer,
         count(*) FILTER (WHERE k.status = 'abgelaufen')::integer
    INTO n_k, n_bald, n_ab
  FROM talent_kanaele k JOIN talents t ON t.id = k.talent_id
  WHERE t.status = 'aktiv' AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u));

  -- Neue Beiträge seit gestern 0 Uhr (Europe/Berlin), ohne Storys (Storys getrennt gezählt)
  SELECT count(*) FILTER (WHERE talents_beitrag_art(b.art, b.produkt_art) <> 'story')::integer,
         count(*) FILTER (WHERE talents_beitrag_art(b.art, b.produkt_art) = 'story')::integer
    INTO n_neu, n_story
  FROM talent_beitraege b JOIN talent_kanaele k ON k.id = b.kanal_id JOIN talents t ON t.id = k.talent_id
  WHERE t.status = 'aktiv' AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u))
    AND b.erstellt >= ((heute - 1)::timestamp AT TIME ZONE 'Europe/Berlin');

  -- Diese Woche: Reichweite je Tag (Schnitt) der letzten 7 Tage gegen die 7 Tage davor; genug Daten = je mindestens 5 Tage mit Zahlen
  -- und vorher mindestens 20 pro Tag. Höchstens 2 Zeilen: größter Anstieg, größter Rückgang.
  -- Migration 138 (Stefan 24.10.2026, 10:38): vorgerechnete Zahlen aus talents_zahlen_vorrat nur bei Zugriff auf alle Talents; ein Talent ohne gültigen
  -- Vorrat (anderer Zeitraum oder Datenstand) und Personen mit Zugriff auf einen Teil der Talents rechnen wie bisher live (gleiche Werte).
  IF c->>'zugriff' = 'alle' THEN
    SELECT coalesce(jsonb_object_agg(x.talent_id::text, jsonb_build_object('j', x.j, 'v', x.v)), '{}'::jsonb) INTO vr
    FROM talents_zahlen_vorrat_lesen('kachel', heute - 7, heute - 1, heute - 14, heute - 8) x WHERE x.talent_id IS NOT NULL;
  END IF;
  WITH w AS (
    SELECT t.id, talent_listenname(t.id) AS anz, j.reichweite AS rj, j.tage AS tj, v.reichweite AS rv, v.tage AS tv
    FROM talents t
    CROSS JOIN LATERAL (SELECT ARRAY(SELECT k.id FROM talent_kanaele k WHERE k.talent_id = t.id) AS kids) kk
    CROSS JOIN LATERAL (SELECT vr->(t.id::text) AS w) q
    CROSS JOIN LATERAL (SELECT x.* FROM jsonb_populate_record(NULL::talents_zahlen_zeile, q.w->'j') x WHERE q.w IS NOT NULL
                        UNION ALL SELECT * FROM talents_zahlen(kk.kids, heute - 7, heute - 1, ARRAY[t.id], '', true) WHERE q.w IS NULL) j
    CROSS JOIN LATERAL (SELECT x.* FROM jsonb_populate_record(NULL::talents_zahlen_zeile, q.w->'v') x WHERE q.w IS NOT NULL
                        UNION ALL SELECT * FROM talents_zahlen(kk.kids, heute - 14, heute - 8, ARRAY[t.id], '', true) WHERE q.w IS NULL) v
    WHERE t.status = 'aktiv' AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u))),
  g AS (
    SELECT w.*, round((w.rj / w.tj) / (w.rv / w.tv) * 100 - 100)::integer AS p FROM w
    WHERE w.tj >= 5 AND w.tv >= 5 AND w.rj IS NOT NULL AND w.rv IS NOT NULL AND w.rv / w.tv >= 20),
  a AS ((SELECT 1 AS o, g.* FROM g WHERE g.p > 0 ORDER BY g.p DESC, lower(g.anz), g.id LIMIT 1)
        UNION ALL
        (SELECT 2 AS o, g.* FROM g WHERE g.p < 0 ORDER BY g.p, lower(g.anz), g.id LIMIT 1))
  SELECT coalesce(jsonb_agg(jsonb_build_object('talent_id', a.id, 'anzeigename', a.anz, 'richtung', CASE WHEN a.p > 0 THEN 'hoch' ELSE 'runter' END,
      'prozent', a.p, 'text', 'Reichweite ' || (talents_veraenderung(a.rj / a.tj, a.rv / a.tv)->>'text')) ORDER BY a.o), '[]'::jsonb)
    INTO zeilen FROM a;

  warn := concat_ws(', ',
    CASE WHEN n_ab = 1 THEN '1 Verbindung ist abgelaufen' WHEN n_ab > 1 THEN n_ab || ' Verbindungen sind abgelaufen' END,
    CASE WHEN n_bald = 1 THEN '1 Verbindung läuft bald ab' WHEN n_bald > 1 THEN n_bald || ' Verbindungen laufen bald ab' END);

  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'anzeigen', true, 'titel', 'Talents', 'ziel', 'talents',
    'zugriff', c->>'zugriff', 'darf_verwalten', verw,
    'anzahl_talents', n_t, 'anzahl_kanaele', n_k,
    'kopf', CASE WHEN n_t = 0 THEN 'Noch keine Talents'
                 ELSE CASE WHEN n_t = 1 THEN '1 Talent' ELSE talents_zahl_text(n_t) || ' Talents' END
                   || ' · ' || CASE WHEN n_k = 1 THEN '1 Kanal' ELSE talents_zahl_text(n_k) || ' Kanäle' END END,
    'leer_hinweis', CASE WHEN n_t = 0 THEN CASE WHEN verw THEN 'Talents lädst du auf der Seite Talents mit „Talent einladen“ ein.'
                                              ELSE 'Dir sind noch keine Talents zugeordnet.' END END,
    'warnung', CASE WHEN n_ab + n_bald > 0 THEN jsonb_build_object('anzahl_abgelaufen', n_ab, 'anzahl_bald', n_bald, 'text', warn) END,
    'woche', jsonb_build_object('titel', 'Diese Woche', 'von', to_char(heute - 7, 'DD.MM.YYYY'), 'bis', to_char(heute - 1, 'DD.MM.YYYY'), 'zeilen', zeilen),
    'neue_beitraege', jsonb_build_object('anzahl', n_neu, 'storys', n_story,
      'text', CASE WHEN n_neu = 0 THEN 'Keine neuen Beiträge seit gestern' WHEN n_neu = 1 THEN '1 neuer Beitrag seit gestern'
                   ELSE talents_zahl_text(n_neu) || ' neue Beiträge seit gestern' END));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne(p_token text, p_kampagne_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; u text; verw boolean; adm boolean; k talent_kampagnen%ROWTYPE;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  sicht integer[]; je integer := 10; ts integer; vs integer; bs integer; n_t integer; n_v integer; n_b integer;
  erg jsonb; hinweise text[] := '{}';
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  u := c->>'u'; verw := (c->>'verw')::boolean; adm := ally_hat_recht(u, 'admin');
  SELECT * INTO k FROM talent_kampagnen x WHERE x.id = p_kampagne_id;
  sicht := ARRAY(SELECT kt.talent_id FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id
                 AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = kt.talent_id AND tp.matrix_user_id = u)));
  -- Migration 66: sehen nach „Talents ansehen“, ändern nach „Talents und Kampagnen verwalten“ (verw)
  IF k.id IS NULL OR (c->>'zugriff' <> 'alle' AND cardinality(sicht) = 0) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diese Kampagne gibt es nicht oder du bist bei keinem ihrer Talents als Manager oder Managerin eingetragen.');
  END IF;
  -- Ergebnis je Talent: zugeordnete (bestätigte) Beiträge, Werte bis Kampagnenende
  WITH b AS (SELECT c2.talent_id, talents_beitrag_werte_bis(kb.beitrag_id, k.bis) AS w
             FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
             WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c2.talent_id = ANY (sicht)),
  t AS (SELECT x.tid, count(b.w)::integer AS n, sum(talents_zahl(b.w->'reach')) AS r, sum(talents_aufrufe(b.w)) AS a, sum(talents_interaktionen(b.w)) AS i
        FROM unnest(sicht) AS x(tid) LEFT JOIN b ON b.talent_id = x.tid GROUP BY x.tid)
  SELECT jsonb_build_object('gesamt', jsonb_build_object('beitraege', coalesce(sum(t.n), 0), 'reichweite', talents_wert(sum(t.r)), 'aufrufe', talents_wert(sum(t.a)),
      'interaktionen', talents_wert(sum(t.i)), 'talents', count(*), 'talents_ohne_beitrag', count(*) FILTER (WHERE t.n = 0)),
    'zeilen', coalesce(jsonb_agg(jsonb_build_object('talent_id', t.tid, 'anzeigename', talent_listenname(t.tid), 'beitraege', t.n,
      'reichweite', talents_wert(t.r), 'aufrufe', talents_wert(t.a), 'interaktionen', talents_wert(t.i), 'ohne_beitrag', t.n = 0,
      'vorschlaege', (SELECT count(*) FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
                      WHERE kb.kampagne_id = k.id AND kb.status = 'vorschlag' AND c2.talent_id = t.tid))
      ORDER BY lower(talent_listenname(t.tid)) COLLATE "C", t.tid), '[]'::jsonb)) INTO erg
  FROM t;
  n_t := cardinality(sicht);
  ts := talents_seite_nr(f->>'tseite', n_t, je);
  SELECT count(*)::integer INTO n_v FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
  WHERE kb.kampagne_id = k.id AND kb.status = 'vorschlag' AND c2.talent_id = ANY (sicht);
  SELECT count(*)::integer INTO n_b FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
  WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c2.talent_id = ANY (sicht);
  vs := talents_seite_nr(f->>'vseite', n_v, je);
  bs := talents_seite_nr(f->>'bseite', n_b, je);
  IF cardinality(k.marken_konten) + cardinality(k.hashtags) + cardinality(k.schlagwoerter) = 0 THEN
    hinweise := hinweise || 'Ohne Erkennungsmerkmale schlägt Ally keine Beiträge vor. Beiträge lassen sich unter „Beiträge zuordnen“ selbst auswählen.'::text;
  END IF;
  IF EXISTS (SELECT 1 FROM talent_kanaele c2 WHERE c2.talent_id = ANY (sicht) AND c2.plattform = 'instagram' AND c2.anmeldeweg = 'instagram' AND c2.status <> 'offen') THEN
    hinweise := hinweise || 'Beitragstexte liefert Instagram nur bei der Anmeldung über Facebook. Beiträge von Accounts mit Instagram-Anmeldung bitte selbst zuordnen.'::text;
  END IF;
  IF c->>'zugriff' <> 'alle' THEN
    hinweise := hinweise || 'Du siehst nur die Talents, die du als Manager oder Managerin betreust.'::text;
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_verwalten', verw, 'darf_loeschen', adm,
    'kampagne', talents_kampagne_kurz(k.id, CASE WHEN c->>'zugriff' = 'alle' THEN NULL ELSE sicht END) || jsonb_build_object(
      'marken_konten', to_jsonb(k.marken_konten), 'hashtags', to_jsonb(k.hashtags), 'schlagwoerter', to_jsonb(k.schlagwoerter),
      'merkmale_text', nullif(concat_ws(', ', (SELECT string_agg('@' || x, ', ') FROM unnest(k.marken_konten) x), (SELECT string_agg('#' || x, ', ') FROM unnest(k.hashtags) x),
                                        (SELECT string_agg('„' || x || '“', ', ') FROM unnest(k.schlagwoerter) x)), ''),
      'talent_ids', CASE WHEN verw THEN to_jsonb(sicht) END, 'loeschen_bestaetigung', CASE WHEN adm THEN k.name END),
    'filter', jsonb_build_object('tseite', ts, 'vseite', vs, 'bseite', bs),
    'ergebnis', jsonb_build_object('gesamt', erg->'gesamt',
      'zeilen', (SELECT coalesce(jsonb_agg(z.v ORDER BY z.o), '[]'::jsonb) FROM jsonb_array_elements(erg->'zeilen') WITH ORDINALITY AS z(v, o) WHERE z.o > (ts - 1) * je AND z.o <= ts * je),
      'anzahl', n_t, 'seite', ts, 'seiten', greatest(1, ceil(n_t / je::numeric)::integer), 'je_seite', je,
      'erklaerung', 'Summe der zugeordneten Beiträge, Zahlen bis Kampagnenende (letzter Abruf bis ' || to_char(least(k.bis, talents_heute()), 'DD.MM.YYYY') || ').'),
    'vorschlaege', jsonb_build_object('anzahl', n_v, 'seite', vs, 'seiten', greatest(1, ceil(n_v / je::numeric)::integer), 'je_seite', je,
      'beitraege', (SELECT coalesce(jsonb_agg(talents_beitrag_json(x.id) || jsonb_build_object('grund', x.grund, 'talent', talent_listenname(x.tid)) ORDER BY x.erst DESC, x.id), '[]'::jsonb)
        FROM (SELECT bb.id, kb.grund, c2.talent_id AS tid, coalesce(bb.erstellt, bb.erfasst_am) AS erst FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id
              JOIN talent_kanaele c2 ON c2.id = bb.kanal_id WHERE kb.kampagne_id = k.id AND kb.status = 'vorschlag' AND c2.talent_id = ANY (sicht)
              ORDER BY coalesce(bb.erstellt, bb.erfasst_am) DESC, bb.id OFFSET (vs - 1) * je LIMIT je) x)),
    'beitraege', jsonb_build_object('anzahl', n_b, 'seite', bs, 'seiten', greatest(1, ceil(n_b / je::numeric)::integer), 'je_seite', je,
      'beitraege', (SELECT coalesce(jsonb_agg(talents_beitrag_json(x.id) || jsonb_build_object('grund', x.grund, 'quelle', x.quelle, 'talent', talent_listenname(x.tid),
          'bis_ende', jsonb_build_object('reichweite', talents_wert(talents_zahl(x.w->'reach')), 'aufrufe', talents_wert(talents_aufrufe(x.w)), 'interaktionen', talents_wert(talents_interaktionen(x.w))))
          ORDER BY x.erst DESC, x.id), '[]'::jsonb)
        FROM (SELECT bb.id, kb.grund, kb.quelle, c2.talent_id AS tid, coalesce(bb.erstellt, bb.erfasst_am) AS erst, talents_beitrag_werte_bis(bb.id, k.bis) AS w
              FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id
              JOIN talent_kanaele c2 ON c2.id = bb.kanal_id WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c2.talent_id = ANY (sicht)
              ORDER BY coalesce(bb.erstellt, bb.erfasst_am) DESC, bb.id OFFSET (bs - 1) * je LIMIT je) x),
      'leer_text', CASE WHEN n_b = 0 THEN 'Noch keine Beiträge zugeordnet.' END),
    'talent_auswahl', CASE WHEN verw THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'anzeigename', talent_listenname(t.id), 'gewaehlt', t.id = ANY (sicht))
        ORDER BY lower(talent_listenname(t.id)) COLLATE "C", t.id), '[]'::jsonb) FROM talents t WHERE t.status = 'aktiv' OR t.id = ANY (sicht)) END,
    'hinweise', to_jsonb(hinweise));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb; u text; adm boolean;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  fehler text; m text; k talent_kampagnen%ROWTYPE; kid integer; bid bigint; x text;
  n_marke text; n_name text; n_von date; n_bis date; n_talents integer[]; n_mk text[]; n_ht text[]; n_sw text[];
  anz integer; weg integer; r jsonb; tid integer; st text; b record; fk text;
BEGIN
  c := talents_aktion_start(p_token, true);
  IF c ? 'stumm' THEN RETURN c - 'stumm'; END IF;
  IF NOT (c->>'ok')::boolean THEN
    RETURN talents_aktion_ende(p_token, c->>'fehler', NULL, NULL, NULL);
  END IF;
  u := c->>'u'; adm := (c->>'adm')::boolean;
  x := btrim(coalesce(d->>'id', d->>'kampagne_id', ''));
  IF x ~ '^[0-9]{1,9}$' THEN
    SELECT * INTO k FROM talent_kampagnen WHERE id = x::integer FOR UPDATE;
  END IF;
  BEGIN
    IF p_aktion <> 'kampagne_neu' AND k.id IS NULL THEN
      fehler := 'Unbekannte Kampagne. Bitte die Seite neu laden.';

    ELSIF p_aktion IN ('kampagne_neu', 'kampagne_bearbeiten') THEN
      n_marke := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'marke' THEN nullif(btrim(coalesce(d->>'marke', '')), '') ELSE k.marke END;
      n_name := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'name' THEN nullif(btrim(coalesce(d->>'name', '')), '') ELSE k.name END;
      n_von := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'von' THEN talents_datum_lesen(d->>'von') ELSE k.von END;
      n_bis := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'bis' THEN talents_datum_lesen(d->>'bis') ELSE k.bis END;
      n_mk := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'marken_konten' THEN talents_merkmale(coalesce(d->'marken_konten', '[]'), 'marke') ELSE k.marken_konten END;
      n_ht := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'hashtags' THEN talents_merkmale(coalesce(d->'hashtags', '[]'), 'hashtag') ELSE k.hashtags END;
      n_sw := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'schlagwoerter' THEN talents_merkmale(coalesce(d->'schlagwoerter', '[]'), 'wort') ELSE k.schlagwoerter END;
      IF p_aktion = 'kampagne_neu' OR d ? 'talents' THEN
        n_talents := ARRAY(SELECT DISTINCT x2::integer FROM unnest(talents_liste(d->'talents')) x2 WHERE x2 ~ '^[0-9]{1,9}$');
      END IF;
      IF n_marke IS NULL OR n_name IS NULL THEN
        fehler := 'Bitte Marke und Namen der Kampagne angeben.';
      ELSIF length(n_marke) > 120 OR length(n_name) > 120 OR n_marke ~ '[[:cntrl:]]' OR n_name ~ '[[:cntrl:]]' THEN
        fehler := 'Marke und Name dürfen höchstens 120 Zeichen haben.';
      ELSIF n_von IS NULL OR n_bis IS NULL THEN
        fehler := 'Bitte Beginn und Ende der Kampagne als Datum angeben (TT.MM.JJJJ).';
      ELSIF n_bis < n_von THEN
        fehler := 'Das Ende der Kampagne liegt vor dem Beginn.';
      ELSIF n_bis - n_von > 366 THEN
        fehler := 'Eine Kampagne darf höchstens 366 Tage dauern.';
      ELSIF n_mk IS NULL THEN
        fehler := 'Bitte die Marken-Accounts als @Name angeben (Buchstaben, Ziffern, Punkt, Unterstrich; höchstens 10).';
      ELSIF n_ht IS NULL THEN
        fehler := 'Bitte die Hashtags ohne Leerzeichen angeben, getrennt durch Komma oder Leerzeichen (höchstens 10).';
      ELSIF n_sw IS NULL THEN
        fehler := 'Bitte die Schlagwörter mit Komma trennen (je 2 bis 60 Zeichen, höchstens 10).';
      ELSIF n_talents IS NOT NULL AND cardinality(n_talents) = 0 THEN
        fehler := 'Bitte mindestens ein Talent auswählen.';
      ELSIF n_talents IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(n_talents) t2 WHERE NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = t2
              AND (t.status = 'aktiv' OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = t.id)))) THEN
        fehler := 'In der Auswahl ist ein unbekanntes oder archiviertes Talent. Bitte die Seite neu laden.';
      ELSIF EXISTS (SELECT 1 FROM talent_kampagnen k2 WHERE lower(k2.marke) = lower(n_marke) AND lower(k2.name) = lower(n_name) AND k2.id IS DISTINCT FROM k.id) THEN
        fehler := 'Eine Kampagne mit diesem Namen gibt es für diese Marke schon.';
      ELSIF p_aktion = 'kampagne_neu' THEN
        INSERT INTO talent_kampagnen (marke, name, von, bis, marken_konten, hashtags, schlagwoerter, erstellt_von, geaendert_von)
        VALUES (n_marke, n_name, n_von, n_bis, n_mk, n_ht, n_sw, u, u) RETURNING id INTO kid;
        INSERT INTO talent_kampagne_talents (kampagne_id, talent_id) SELECT kid, t2 FROM unnest(n_talents) t2;
        r := talents_kampagnen_vorschlaege(kid);
        m := 'Kampagne angelegt.' || CASE WHEN (r->>'neu')::integer = 1 THEN ' Ally schlägt 1 passenden Beitrag vor.'
                                          WHEN (r->>'neu')::integer > 1 THEN ' Ally schlägt ' || (r->>'neu') || ' passende Beiträge vor.' ELSE '' END;
      ELSE
        kid := k.id;
        UPDATE talent_kampagnen SET marke = n_marke, name = n_name, von = n_von, bis = n_bis, marken_konten = n_mk, hashtags = n_ht, schlagwoerter = n_sw,
          geaendert_am = now(), geaendert_von = u WHERE id = kid;
        weg := 0;
        IF n_talents IS NOT NULL THEN
          -- Talent nicht mehr dabei: seine Zuordnungen in dieser Kampagne entfallen
          DELETE FROM talent_kampagne_beitraege kb USING talent_beitraege bb, talent_kanaele c2
          WHERE kb.kampagne_id = kid AND bb.id = kb.beitrag_id AND c2.id = bb.kanal_id AND NOT (c2.talent_id = ANY (n_talents)) AND kb.status = 'bestaetigt';
          GET DIAGNOSTICS weg = ROW_COUNT;
          DELETE FROM talent_kampagne_beitraege kb USING talent_beitraege bb, talent_kanaele c2
          WHERE kb.kampagne_id = kid AND bb.id = kb.beitrag_id AND c2.id = bb.kanal_id AND NOT (c2.talent_id = ANY (n_talents));
          DELETE FROM talent_kampagne_talents WHERE kampagne_id = kid AND NOT (talent_id = ANY (n_talents));
          INSERT INTO talent_kampagne_talents (kampagne_id, talent_id) SELECT kid, t2 FROM unnest(n_talents) t2 ON CONFLICT DO NOTHING;
        END IF;
        r := talents_kampagnen_vorschlaege(kid);
        m := 'Kampagne gespeichert.' || CASE WHEN weg > 0 THEN ' ' || weg || CASE WHEN weg = 1 THEN ' Zuordnung' ELSE ' Zuordnungen' END
                                               || ' von Talents, die nicht mehr dabei sind, wurden entfernt.' ELSE '' END
          || CASE WHEN (r->>'neu')::integer > 0 THEN ' Neue Vorschläge: ' || (r->>'neu') || '.' ELSE '' END;
      END IF;

    ELSIF p_aktion = 'kampagne_loeschen' THEN
      IF NOT adm THEN
        fehler := 'Kampagnen endgültig löschen können nur Admins.';
      ELSIF btrim(coalesce(d->>'bestaetigung', '')) IS DISTINCT FROM k.name THEN
        fehler := 'Zum endgültigen Löschen bitte den Namen der Kampagne genau so eingeben: ' || k.name;
      ELSE
        -- Migration 131: in den Papierkorb (zurück und endgültig in der neuen Oberfläche: Kampagnen › Papierkorb)
        PERFORM talents_kampagnen_pk_legen('kampagne', k.id, u);
        m := 'Die Kampagne „' || k.name || '“ liegt jetzt im Papierkorb (Kampagnen › Papierkorb). Die Beiträge und Zahlen der Talents bleiben erhalten.';
      END IF;

    ELSIF p_aktion IN ('beitrag_bestaetigen', 'beitrag_zuordnen', 'beitrag_entfernen') THEN
      kid := k.id;
      IF btrim(coalesce(d->>'beitrag_id', '')) ~ '^[0-9]{1,15}$' THEN
        SELECT bb.id, bb.abgeschlossen, talents_beitrag_art(bb.art, bb.produkt_art) AS art, c2.talent_id INTO b
        FROM talent_beitraege bb JOIN talent_kanaele c2 ON c2.id = bb.kanal_id WHERE bb.id = btrim(d->>'beitrag_id')::bigint;
      END IF;
      SELECT kb.status INTO st FROM talent_kampagne_beitraege kb WHERE kb.kampagne_id = k.id AND kb.beitrag_id = b.id;
      IF b.id IS NULL OR NOT EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = b.talent_id) THEN
        fehler := 'Dieser Beitrag gehört zu keinem Talent der Kampagne. Bitte die Seite neu laden.';
      ELSIF p_aktion = 'beitrag_entfernen' THEN
        INSERT INTO talent_kampagne_beitraege (kampagne_id, beitrag_id, status, quelle, geaendert_am, geaendert_von)
        VALUES (k.id, b.id, 'entfernt', 'manuell', now(), u)
        ON CONFLICT (kampagne_id, beitrag_id) DO UPDATE SET status = 'entfernt', geaendert_am = now(), geaendert_von = u;
        m := 'Beitrag aus der Kampagne entfernt. Ally schlägt ihn nicht noch einmal vor.';
      ELSE
        INSERT INTO talent_kampagne_beitraege (kampagne_id, beitrag_id, status, quelle, geaendert_am, geaendert_von)
        VALUES (k.id, b.id, 'bestaetigt', 'manuell', now(), u)
        ON CONFLICT (kampagne_id, beitrag_id) DO UPDATE SET status = 'bestaetigt', geaendert_am = now(), geaendert_von = u;
        -- Kampagne läuft noch: Beitrag weiter verfolgen
        IF b.abgeschlossen AND b.art <> 'story' AND k.bis >= talents_heute() THEN
          UPDATE talent_beitraege SET abgeschlossen = false WHERE id = b.id;
        END IF;
        m := CASE WHEN st = 'bestaetigt' THEN 'Der Beitrag ist der Kampagne schon zugeordnet.' ELSE 'Beitrag der Kampagne zugeordnet.' END
          || CASE WHEN b.abgeschlossen AND b.art <> 'story' AND k.bis >= talents_heute() THEN ' Er wird bis zum Kampagnenende weiter verfolgt.' ELSE '' END;
      END IF;
      bid := b.id;

    ELSIF p_aktion = 'vorschlaege_bestaetigen' THEN
      kid := k.id;
      UPDATE talent_kampagne_beitraege SET status = 'bestaetigt', geaendert_am = now(), geaendert_von = u WHERE kampagne_id = k.id AND status = 'vorschlag';
      GET DIAGNOSTICS anz = ROW_COUNT;
      IF anz = 0 THEN
        fehler := 'Es gibt keine offenen Vorschläge.';
      ELSE
        m := CASE WHEN anz = 1 THEN '1 Vorschlag bestätigt.' ELSE anz || ' Vorschläge bestätigt.' END;
      END IF;

    ELSE
      fehler := 'Unbekannte Aktion.';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Talent mit Deliverables oder Aufgaben (Migration 61) lässt sich nicht herausnehmen: verständliche Meldung statt der Datenbank-Meldung (Stefan 20.10.2026)
    GET STACKED DIAGNOSTICS fk := CONSTRAINT_NAME;
    fehler := CASE WHEN SQLSTATE = '23503' AND fk IN ('talent_deliverables_kampagne_talent', 'talent_aufgaben_kampagne_talent')
                   THEN 'Talents mit Deliverables oder Aufgaben in dieser Kampagne lassen sich nicht herausnehmen. Bitte zuerst deren Deliverables und Aufgaben löschen.'
                   ELSE 'Die Aktion konnte nicht ausgeführt werden. Bitte erneut versuchen. (' || left(SQLERRM, 200) || ')' END;
    kid := k.id;
  END;
  RETURN talents_aktion_ende(p_token, fehler, m, NULL, jsonb_build_object('kampagne_id', CASE WHEN fehler IS NULL AND p_aktion = 'kampagne_loeschen' THEN NULL ELSE coalesce(kid, k.id) END,
    'beitrag_id', bid));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne_bis(p_beitrag_id bigint)
 RETURNS date
 LANGUAGE sql
 STABLE
AS $function$
  SELECT max(k.bis) FROM talent_kampagne_beitraege kb JOIN talent_kampagnen k ON k.id = kb.kampagne_id
  WHERE kb.beitrag_id = p_beitrag_id AND kb.status <> 'entfernt'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne_ist_testdaten(p_kampagne_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 79: gehört die Kampagne zu den Testdaten? (NULL oder unbekannt: nein)
  SELECT coalesce((SELECT k.testdaten FROM talent_kampagnen k WHERE k.id = p_kampagne_id), false)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne_kurz(p_kampagne_id integer, p_talents integer[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('kampagne_id', k.id, 'marke', k.marke, 'name', k.name, 'titel', k.marke || ' – ' || k.name,
    'von', to_char(k.von, 'DD.MM.YYYY'), 'bis', to_char(k.bis, 'DD.MM.YYYY'), 'von_iso', to_char(k.von, 'YYYY-MM-DD'), 'bis_iso', to_char(k.bis, 'YYYY-MM-DD'),
    'zeitraum_text', to_char(k.von, 'DD.MM.YYYY') || ' bis ' || to_char(k.bis, 'DD.MM.YYYY'),
    'status', st.s, 'status_text', CASE st.s WHEN 'geplant' THEN 'geplant' WHEN 'laufend' THEN 'läuft' ELSE 'beendet' END,
    'anzahl_talents', (SELECT count(*) FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND (p_talents IS NULL OR kt.talent_id = ANY (p_talents))),
    'anzahl_beitraege', z.best, 'anzahl_vorschlaege', z.vor,
    'talents_ohne_beitrag', (SELECT count(*) FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND (p_talents IS NULL OR kt.talent_id = ANY (p_talents))
       AND NOT EXISTS (SELECT 1 FROM talent_kampagne_beitraege kb JOIN talent_beitraege b ON b.id = kb.beitrag_id JOIN talent_kanaele c ON c.id = b.kanal_id
                       WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c.talent_id = kt.talent_id)))
  FROM talent_kampagnen k
  CROSS JOIN LATERAL (SELECT talents_kampagne_status(k.von, k.bis) AS s) st
  CROSS JOIN LATERAL (SELECT count(*) FILTER (WHERE kb.status = 'bestaetigt') AS best, count(*) FILTER (WHERE kb.status = 'vorschlag') AS vor
                      FROM talent_kampagne_beitraege kb JOIN talent_beitraege b ON b.id = kb.beitrag_id JOIN talent_kanaele c ON c.id = b.kanal_id
                      WHERE kb.kampagne_id = k.id AND (p_talents IS NULL OR c.talent_id = ANY (p_talents))) z
  WHERE k.id = p_kampagne_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne_status(p_von date, p_bis date)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN p_von > talents_heute() THEN 'geplant' WHEN p_bis < talents_heute() THEN 'beendet' ELSE 'laufend' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne_treffer(p_text text, p_marken text[], p_tags text[], p_woerter text[])
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN coalesce(btrim(p_text), '') <> '' THEN coalesce(
    (SELECT 'Erwähnt @' || m FROM unnest(p_marken) WITH ORDINALITY AS u(m, o)
     WHERE lower(p_text) ~ ('(^|[^0-9a-zß-ÿ_.])@' || talents_regex(m) || '($|[^0-9a-zß-ÿ_.]|[.]($|[^0-9a-zß-ÿ_]))') ORDER BY o LIMIT 1),
    (SELECT 'Hashtag #' || h FROM unnest(p_tags) WITH ORDINALITY AS u(h, o)
     WHERE lower(p_text) ~ ('(^|[^0-9a-zß-ÿ_])#' || talents_regex(h) || '($|[^0-9a-zß-ÿ_])') ORDER BY o LIMIT 1),
    (SELECT 'Schlagwort „' || w || '“' FROM unnest(p_woerter) WITH ORDINALITY AS u(w, o)
     WHERE lower(p_text) ~ ('(^|[^0-9a-zß-ÿ_])' || talents_regex(lower(w)) || '($|[^0-9a-zß-ÿ_])') ORDER BY o LIMIT 1)) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne_ui(p_token text, p_kampagne_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; u text; verw boolean; adm boolean; mgmt boolean; r text; geld boolean; planen boolean; bearb boolean; loeschen boolean; k talent_kampagnen%ROWTYPE;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  sp text := coalesce(f #>> '{sortierung,spalte}', '');
  ri text := CASE WHEN f #>> '{sortierung,richtung}' = 'ab' THEN 'ab' ELSE 'auf' END;
  tids integer[]; je integer := 20; heute date := talents_heute();
  d_anz integer; ds integer; v_anz integer; vs integer; b_anz integer; bs integer; fr_anz integer; fs integer;
  erg jsonb; reich numeric; inter numeric; res jsonb;
BEGIN
  -- Seite Kampagne (BA6, ALLY 26, Entwurf Kampagne.dc.html): Kopf, Überblick (Deliverables erledigt, nächste Deadline, Reichweite bisher, Budget verplant),
  -- Offen, Ziele, Briefing mit Links der Marke, Talents und Deliverables (Sortierung, 20 je Seite), Zeitplan, Erinnerungen, Freigaben, Reporting.
  -- Zugriff 'eigene' sieht nur die eigenen Talents. Budget nur für Admin und das zuständige Management, Honorare zusätzlich für das Management der
  -- eigenen Talents (talents_planung_geld, Stefan 20.10.2026). Bearbeiten: Admin, „Talents verwalten“, zuständiges Management (nur eigene Talents);
  -- Löschen: Admin oder zuständiges Management, wenn alle Talents der Kampagne die eigenen sind.
  -- Migration 64: „Management“ = Recht „Talents und Kampagnen verwalten“ für zugeordnete; Honorar-Spalte nur mit „Honorare und Budgets sehen“.
  c := talents_planung_start(p_token, 'kampagnen');
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  u := c->>'u'; verw := (c->>'verw')::boolean; adm := (c->>'adm')::boolean; mgmt := (c->>'mgmt')::boolean;
  SELECT * INTO k FROM talent_kampagnen x WHERE x.id = p_kampagne_id;
  r := talents_planung_recht(u, k.id);
  IF k.id IS NULL OR r IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diese Kampagne gibt es nicht oder du bist bei keinem ihrer Talents als Manager oder Managerin eingetragen.');
  END IF;
  geld := talents_planung_geld(u, k.id, NULL);
  planen := talents_planung_planen(u, k.id);
  bearb := verw OR (mgmt AND k.zustaendig = u);
  loeschen := adm OR (mgmt AND k.zustaendig = u AND NOT EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND NOT coalesce(talent_verwaltbar(u, kt.talent_id), false)));
  tids := ARRAY(SELECT kt.talent_id FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND (r = 'alle' OR talent_sichtbar(u, kt.talent_id))
                ORDER BY lower(talent_listenname(kt.talent_id)) COLLATE "C", kt.talent_id);
  IF sp NOT IN ('talent', 'plattform', 'format', 'deadline', 'veroeffentlichung', 'status', 'honorar') OR (sp = 'honorar' AND ally_recht_reichweite(u, 'talents_betraege') IS NULL) THEN sp := ''; END IF;
  SELECT count(*)::integer INTO d_anz FROM talent_deliverables d WHERE d.kampagne_id = k.id AND d.talent_id = ANY (tids);
  ds := talents_seite_nr(f->>'dseite', d_anz, je);
  SELECT count(*)::integer INTO fr_anz FROM talent_deliverable_versionen v JOIN talent_deliverables d ON d.id = v.deliverable_id WHERE d.kampagne_id = k.id AND d.talent_id = ANY (tids);
  fs := talents_seite_nr(f->>'fseite', fr_anz, je);
  -- Ergebnis je Talent wie talents_kampagne: bestätigte Beiträge, Zahlen bis Kampagnenende
  WITH b AS (SELECT c2.talent_id, talents_beitrag_werte_bis(kb.beitrag_id, k.bis) AS w
             FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
             WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c2.talent_id = ANY (tids)),
  t AS (SELECT x.tid, count(b.w)::integer AS n, sum(talents_zahl(b.w->'reach')) AS rw, sum(talents_aufrufe(b.w)) AS a, sum(talents_interaktionen(b.w)) AS i
        FROM unnest(tids) AS x(tid) LEFT JOIN b ON b.talent_id = x.tid GROUP BY x.tid)
  SELECT jsonb_build_object('reichweite', sum(t.rw), 'interaktionen', sum(t.i), 'beitraege', coalesce(sum(t.n), 0),
    'zeilen', coalesce(jsonb_agg(jsonb_build_object('talent_id', t.tid, 'talent', talent_listenname(t.tid), 'beitraege', t.n, 'reichweite', talents_wert(t.rw)->>'text',
      'aufrufe', talents_wert(t.a)->>'text', 'interaktionen', talents_wert(t.i)->>'text', 'ohne_beitrag', t.n = 0) ORDER BY lower(talent_listenname(t.tid)) COLLATE "C", t.tid), '[]'::jsonb)) INTO erg
  FROM t;
  reich := (erg->>'reichweite')::numeric; inter := (erg->>'interaktionen')::numeric;
  SELECT count(*)::integer INTO v_anz FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
  WHERE kb.kampagne_id = k.id AND kb.status = 'vorschlag' AND c2.talent_id = ANY (tids);
  vs := talents_seite_nr(f->>'vseite', v_anz, 10);
  SELECT count(*)::integer INTO b_anz FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
  WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c2.talent_id = ANY (tids);
  bs := talents_seite_nr(f->>'bseite', b_anz, 10);

  WITH d AS (SELECT x.* FROM talent_deliverables x WHERE x.kampagne_id = k.id AND x.talent_id = ANY (tids))
  SELECT jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', r, 'geld', geld, 'honorar', ally_recht_reichweite(u, 'talents_betraege') IS NOT NULL,
    'darf_planen', planen, 'darf_bearbeiten', bearb, 'darf_loeschen', loeschen, 'darf_zuordnen', verw OR mgmt,
    'kampagne', talents_kampagne_kurz(k.id, CASE WHEN r = 'alle' THEN NULL ELSE tids END) || jsonb_build_object(
      'status', talents_planung_kampagne_status(k.von, k.bis, k.abgebrochen_am), 'abgebrochen', k.abgebrochen_am IS NOT NULL,
      'zustaendig', k.zustaendig, 'zustaendig_name', (SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = k.zustaendig),
      'budget_text', CASE WHEN geld THEN talents_planung_betrag_text(k.budget_cent) END, 'budget_cent', CASE WHEN geld THEN k.budget_cent END,
      'ziel_reichweite', k.ziel_reichweite, 'ziel_interaktionsrate', k.ziel_interaktionsrate, 'ziel_link_klicks', k.ziel_link_klicks, 'link_klicks', k.link_klicks,
      'briefing_ziel', k.briefing_ziel, 'kernbotschaft', k.kernbotschaft, 'dos', k.dos, 'donts', k.donts, 'werbekennzeichnung', k.werbekennzeichnung,
      'erinnerungen_an', k.erinnerungen_an,
      'marken_konten', to_jsonb(k.marken_konten), 'hashtags', to_jsonb(k.hashtags), 'schlagwoerter', to_jsonb(k.schlagwoerter),
      'loeschen_bestaetigung', CASE WHEN loeschen THEN k.name END),
    'kennzahlen', jsonb_build_object(
      'gesamt', (SELECT count(*) FROM d), 'erledigt', (SELECT count(*) FROM d WHERE d.status IN ('veroeffentlicht', 'abgerechnet')),
      'naechste', (SELECT jsonb_build_object('datum', talents_planung_tag_text(x.dl), 'ueberfaellig', x.dl < heute,
           'neben', (SELECT string_agg(DISTINCT talents_planung_format_text(d2.format), ', ') FROM d d2 WHERE d2.deadline = x.dl AND d2.status IN ('geplant', 'entwurf', 'ueberarbeiten'))
             || ', ' || (SELECT count(DISTINCT d2.talent_id) FROM d d2 WHERE d2.deadline = x.dl AND d2.status IN ('geplant', 'entwurf', 'ueberarbeiten'))
             || CASE WHEN (SELECT count(DISTINCT d2.talent_id) FROM d d2 WHERE d2.deadline = x.dl AND d2.status IN ('geplant', 'entwurf', 'ueberarbeiten')) = 1 THEN ' Talent' ELSE ' Talents' END)
         FROM (SELECT min(d.deadline) AS dl FROM d WHERE d.status IN ('geplant', 'entwurf', 'ueberarbeiten')) x WHERE x.dl IS NOT NULL),
      'reichweite', talents_wert(reich)->>'text', 'reichweite_wert', reich,
      'verplant_text', CASE WHEN geld THEN talents_planung_betrag_text((SELECT coalesce(sum(d.honorar_cent), 0) FROM d)::bigint) END,
      'freigaben_offen', (SELECT count(*) FROM talent_deliverable_versionen v JOIN d ON d.id = v.deliverable_id WHERE v.pruefung IN ('offen', 'intern_ok', 'bei_marke'))),
    'ziele', jsonb_build_object(
      'reichweite', CASE WHEN k.ziel_reichweite IS NOT NULL THEN jsonb_build_object('ziel', talents_zahl_text(k.ziel_reichweite), 'ist', talents_wert(reich)->>'text',
        'prozent', CASE WHEN k.ziel_reichweite > 0 AND reich IS NOT NULL THEN round(reich * 100 / k.ziel_reichweite) END) END,
      'interaktionsrate', CASE WHEN k.ziel_interaktionsrate IS NOT NULL THEN jsonb_build_object('ziel', replace(trim_scale(k.ziel_interaktionsrate)::text, '.', ','),
        'ist', CASE WHEN reich > 0 AND inter IS NOT NULL THEN replace(round(inter * 100 / reich, 1)::text, '.', ',') END,
        'erreicht', reich > 0 AND inter IS NOT NULL AND round(inter * 100 / reich, 2) >= k.ziel_interaktionsrate) END,
      'link_klicks', CASE WHEN k.ziel_link_klicks IS NOT NULL THEN jsonb_build_object('ziel', talents_zahl_text(k.ziel_link_klicks),
        'ist', CASE WHEN k.link_klicks IS NOT NULL THEN talents_zahl_text(k.link_klicks) END,
        'prozent', CASE WHEN k.ziel_link_klicks > 0 AND k.link_klicks IS NOT NULL THEN round(k.link_klicks * 100.0 / k.ziel_link_klicks) END) END),
    'offen', (SELECT coalesce(jsonb_agg(o.e ORDER BY o.rang, o.t, o.id), '[]'::jsonb) FROM (
        (SELECT 1 AS rang, d.deadline::timestamptz AS t, d.id, jsonb_build_object('art', 'deadline', 'deliverable_id', d.id, 'talent_id', d.talent_id,
           'marke', talents_planung_tag_text(d.deadline), 'warn', d.deadline <= heute + 1,
           'text', talents_planung_deliverable_name(d.format, d.anzahl, d.titel) || ' von ' || coalesce(talent_listenname(d.talent_id), 'Talent')) AS e
         FROM d WHERE d.status IN ('geplant', 'entwurf', 'ueberarbeiten') AND d.deadline <= heute + 2 ORDER BY d.deadline, d.id LIMIT 6)
        UNION ALL
        (SELECT 2, v.eingereicht_am, v.id, jsonb_build_object('art', 'freigabe', 'deliverable_id', d.id, 'version_id', v.id,
           'marke', CASE WHEN v.pruefung = 'bei_marke' THEN 'Marke' ELSE 'Freigabe' END, 'warn', false,
           'text', talents_planung_deliverable_name(d.format, d.anzahl, d.titel) || ' von ' || coalesce(talent_listenname(d.talent_id), 'Talent')
             || CASE WHEN v.pruefung = 'bei_marke' THEN ' liegt bei der Marke' ELSE ' wartet auf Prüfung' END)
         FROM talent_deliverable_versionen v JOIN d ON d.id = v.deliverable_id WHERE v.pruefung IN ('offen', 'intern_ok', 'bei_marke') ORDER BY v.eingereicht_am, v.id LIMIT 6)) o),
    'links', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'titel', l.titel, 'link', l.link, 'dienst_text', talents_planung_dienst_text(l.dienst)) ORDER BY l.id), '[]'::jsonb)
      FROM talent_kampagne_links l WHERE l.kampagne_id = k.id),
    'deliverables', jsonb_build_object('anzahl', d_anz, 'seite', ds, 'je_seite', je,
      'sortierung', jsonb_build_object('spalte', CASE WHEN sp = '' THEN 'deadline' ELSE sp END, 'richtung', CASE WHEN sp = '' THEN 'auf' ELSE ri END),
      'zeilen', (SELECT coalesce(jsonb_agg(talents_planung_deliverable_json(z.id, talents_planung_geld(u, k.id, z.talent_id)) ORDER BY z.o), '[]'::jsonb) FROM (
          SELECT d.id, d.talent_id, row_number() OVER (ORDER BY
            CASE WHEN sp = 'talent' AND ri = 'auf' THEN lower(talent_listenname(d.talent_id)) END ASC, CASE WHEN sp = 'talent' AND ri = 'ab' THEN lower(talent_listenname(d.talent_id)) END DESC,
            CASE WHEN sp = 'plattform' AND ri = 'auf' THEN d.plattform END ASC, CASE WHEN sp = 'plattform' AND ri = 'ab' THEN d.plattform END DESC,
            CASE WHEN sp = 'format' AND ri = 'auf' THEN d.format END ASC, CASE WHEN sp = 'format' AND ri = 'ab' THEN d.format END DESC,
            CASE WHEN sp = 'veroeffentlichung' AND ri = 'auf' THEN d.veroeffentlichen_am END ASC NULLS LAST, CASE WHEN sp = 'veroeffentlichung' AND ri = 'ab' THEN d.veroeffentlichen_am END DESC NULLS LAST,
            CASE WHEN sp = 'status' AND ri = 'auf' THEN array_position(ARRAY['geplant', 'entwurf', 'ueberarbeiten', 'pruefung', 'bei_marke', 'freigegeben', 'veroeffentlicht', 'abgerechnet'], d.status) END ASC,
            CASE WHEN sp = 'status' AND ri = 'ab' THEN array_position(ARRAY['geplant', 'entwurf', 'ueberarbeiten', 'pruefung', 'bei_marke', 'freigegeben', 'veroeffentlicht', 'abgerechnet'], d.status) END DESC,
            CASE WHEN sp = 'honorar' AND ri = 'auf' AND talents_planung_geld(u, k.id, d.talent_id) THEN d.honorar_cent END ASC NULLS LAST,
            CASE WHEN sp = 'honorar' AND ri = 'ab' AND talents_planung_geld(u, k.id, d.talent_id) THEN d.honorar_cent END DESC NULLS LAST,
            CASE WHEN sp = 'deadline' AND ri = 'ab' THEN d.deadline END DESC,
            d.deadline, lower(talent_listenname(d.talent_id)), d.id) AS o
          FROM d) z WHERE z.o > (ds - 1) * je AND z.o <= ds * je)),
    'zeitplan', (SELECT coalesce(jsonb_agg(jsonb_build_object('talent_id', d.talent_id, 'talent', coalesce(talent_listenname(d.talent_id), 'Talent'),
        'format_text', talents_planung_format_text(d.format) || CASE WHEN d.anzahl > 1 THEN ' (' || d.anzahl || ')' ELSE '' END,
        'deadline', to_char(d.deadline, 'YYYY-MM-DD'), 'veroeffentlichen', to_char(d.veroeffentlichen_am, 'YYYY-MM-DD'),
        'erledigt', d.status IN ('freigegeben', 'veroeffentlicht', 'abgerechnet'), 'ueberfaellig', d.status IN ('geplant', 'entwurf', 'ueberarbeiten') AND d.deadline < heute)
        ORDER BY lower(talent_listenname(d.talent_id)) COLLATE "C", d.talent_id, d.deadline, d.id), '[]'::jsonb) FROM d),
    'erinnerungen', jsonb_build_object('an', k.erinnerungen_an, 'eigene', EXISTS (SELECT 1 FROM talent_erinnerungsregeln x WHERE x.kampagne_id = k.id AND x.geloescht_am IS NULL),
      'regeln', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'standard', x.kampagne_id IS NULL, 'bezug', x.bezug, 'versatz_tage', x.versatz_tage,
          'uhrzeit', to_char(x.uhrzeit, 'HH24:MI'), 'empfaenger', x.empfaenger, 'kanaele', to_jsonb(x.kanaele), 'aktiv', x.aktiv,
          'text', talents_planung_regel_text(x.bezug, x.versatz_tage), 'empfaenger_text', CASE x.empfaenger WHEN 'talent' THEN 'an das Talent' ELSE 'an den Manager oder die Managerin' END,
          'kanaele_text', CASE WHEN x.empfaenger = 'zustaendig' THEN 'Benachrichtigung in ' || coalesce(nullif(produkt_name(), ''), 'der Oberfläche') ELSE talents_planung_kanaele_text(x.kanaele) END)
          ORDER BY x.empfaenger DESC, x.versatz_tage, x.bezug, x.id), '[]'::jsonb) FROM talents_erinnerungsregeln_wirksam(k.id) x),
      'vorschau', (SELECT coalesce(jsonb_agg(jsonb_build_object('zeit_text', talents_planung_zeit_text(e.faellig_am, false),
          'text', talents_planung_frist_text(e.bezug, e.versatz_tage) || ': ' || talents_planung_deliverable_name(d.format, d.anzahl, d.titel) || ' von ' || coalesce(talent_listenname(d.talent_id), 'Talent'),
          'empfaenger_text', CASE e.empfaenger WHEN 'talent' THEN talents_planung_kanaele_text(e.kanaele) ELSE 'Manager/in' END) ORDER BY e.faellig_am, e.deliverable_id), '[]'::jsonb)
        FROM (SELECT * FROM talents_erinnerungen_faellig(now(), now() + interval '30 days', k.id) y WHERE y.talent_id = ANY (tids) ORDER BY y.faellig_am LIMIT 10) e
        JOIN talent_deliverables d ON d.id = e.deliverable_id),
      'gesendet', (SELECT count(*) FROM talent_erinnerungen_lauf l JOIN d ON d.id = l.deliverable_id)),
    'freigaben', jsonb_build_object('anzahl', fr_anz, 'seite', fs, 'je_seite', je,
      'zeilen', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'deliverable_id', z.deliverable_id, 'version', z.version, 'talent', coalesce(talent_listenname(z.talent_id), 'Talent'),
          'name', talents_planung_deliverable_name(z.format, z.anzahl, z.titel), 'link', z.link, 'dienst_text', talents_planung_dienst_text(z.dienst),
          'eingereicht_text', talents_planung_zeit_text(z.eingereicht_am, false), 'pruefung', z.pruefung, 'pruefung_text', talents_planung_pruefung_text(z.pruefung),
          'wartet', z.pruefung IN ('offen', 'intern_ok', 'bei_marke')) ORDER BY z.o), '[]'::jsonb)
        FROM (SELECT v.*, d.talent_id, d.format, d.anzahl, d.titel, row_number() OVER (ORDER BY v.pruefung IN ('offen', 'intern_ok', 'bei_marke') DESC, v.eingereicht_am DESC, v.id DESC) AS o
              FROM talent_deliverable_versionen v JOIN d ON d.id = v.deliverable_id) z WHERE z.o > (fs - 1) * je AND z.o <= fs * je)),
    'reporting', jsonb_build_object('gesamt', jsonb_build_object('beitraege', erg->'beitraege', 'reichweite', talents_wert(reich)->>'text', 'interaktionen', talents_wert(inter)->>'text'),
      'zeilen', erg->'zeilen',
      'vorschlaege', jsonb_build_object('anzahl', v_anz, 'seite', vs, 'je_seite', 10,
        'beitraege', (SELECT coalesce(jsonb_agg(talents_beitrag_json(x.id) || jsonb_build_object('grund', x.grund, 'talent', talent_listenname(x.tid)) ORDER BY x.erst DESC, x.id), '[]'::jsonb)
          FROM (SELECT bb.id, kb.grund, c2.talent_id AS tid, coalesce(bb.erstellt, bb.erfasst_am) AS erst FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id
                JOIN talent_kanaele c2 ON c2.id = bb.kanal_id WHERE kb.kampagne_id = k.id AND kb.status = 'vorschlag' AND c2.talent_id = ANY (tids)
                ORDER BY coalesce(bb.erstellt, bb.erfasst_am) DESC, bb.id OFFSET (vs - 1) * 10 LIMIT 10) x)),
      'beitraege', jsonb_build_object('anzahl', b_anz, 'seite', bs, 'je_seite', 10,
        'beitraege', (SELECT coalesce(jsonb_agg(talents_beitrag_json(x.id) || jsonb_build_object('talent', talent_listenname(x.tid), 'quelle', x.quelle,
            'reichweite_bis_ende', talents_wert(talents_zahl(x.w->'reach'))->>'text') ORDER BY x.erst DESC, x.id), '[]'::jsonb)
          FROM (SELECT bb.id, kb.quelle, c2.talent_id AS tid, coalesce(bb.erstellt, bb.erfasst_am) AS erst, talents_beitrag_werte_bis(bb.id, k.bis) AS w
                FROM talent_kampagne_beitraege kb JOIN talent_beitraege bb ON bb.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
                WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c2.talent_id = ANY (tids)
                ORDER BY coalesce(bb.erstellt, bb.erfasst_am) DESC, bb.id OFFSET (bs - 1) * 10 LIMIT 10) x))),
    'talents', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', x, 'anzeigename', talent_listenname(x)) ORDER BY o), '[]'::jsonb) FROM unnest(tids) WITH ORDINALITY AS t(x, o)),
    'talent_auswahl', CASE WHEN bearb THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'anzeigename', talent_listenname(t.id),
        'gewaehlt', EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = t.id))
        ORDER BY lower(talent_listenname(t.id)) COLLATE "C", t.id), '[]'::jsonb)
      FROM talents t WHERE (t.status = 'aktiv' OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = t.id))
        AND t.testdaten = coalesce(k.testdaten, false) AND (verw OR coalesce(talent_verwaltbar(u, t.id), false))) END,
    'personen', CASE WHEN verw THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.matrix_user_id, 'name', p.name || CASE WHEN p.testdaten THEN ' (Testdaten)' ELSE '' END) ORDER BY lower(p.name), p.matrix_user_id), '[]'::jsonb)
      FROM ally_personen p WHERE p.aktiv AND talents_zugriff(p.matrix_user_id) IS NOT NULL AND (coalesce(k.testdaten, false) OR NOT p.testdaten)) END,
    'filter', jsonb_build_object('dseite', ds, 'fseite', fs, 'vseite', vs, 'bseite', bs)) INTO res
  FROM (SELECT 1) eins;
  RETURN res;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagne_zuordnen(p_token text, p_kampagne_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; k talent_kampagnen%ROWTYPE;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  ta integer; be text := CASE WHEN f->>'bereich' = 'alle' THEN 'alle' ELSE 'zeitraum' END;
  anz integer; seite integer; je integer := 10;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  IF NOT (c->>'verw')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Beiträge zuordnen darf, wer das Recht „Talents und Kampagnen verwalten“ für alle Talents hat.');
  END IF;
  SELECT * INTO k FROM talent_kampagnen x WHERE x.id = p_kampagne_id;
  IF k.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diese Kampagne gibt es nicht.');
  END IF;
  ta := (SELECT kt.talent_id FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id
         ORDER BY kt.talent_id::text = btrim(coalesce(f->>'talent', '')) DESC, lower(talent_listenname(kt.talent_id)) COLLATE "C", kt.talent_id LIMIT 1);
  SELECT count(*)::integer INTO anz FROM talent_beitraege b JOIN talent_kanaele c2 ON c2.id = b.kanal_id
  WHERE c2.talent_id = ta AND (be = 'alle' OR talents_tag(coalesce(b.erstellt, b.erfasst_am)) BETWEEN k.von AND k.bis);
  seite := talents_seite_nr(f->>'seite', anz, je);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_verwalten', true,
    'kampagne', talents_kampagne_kurz(k.id, NULL),
    'filter', jsonb_build_object('talent', coalesce(ta::text, ''), 'bereich', be, 'seite', seite),
    'talent_auswahl', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', kt.talent_id, 'anzeigename', talent_listenname(kt.talent_id),
        'anzahl_zugeordnet', (SELECT count(*) FROM talent_kampagne_beitraege kb JOIN talent_beitraege b ON b.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = b.kanal_id
                              WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c2.talent_id = kt.talent_id))
        ORDER BY lower(talent_listenname(kt.talent_id)) COLLATE "C", kt.talent_id), '[]'::jsonb) FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id),
    'bereich_auswahl', '[{"schluessel":"zeitraum","name":"Im Kampagnenzeitraum"},{"schluessel":"alle","name":"Alle Beiträge"}]'::jsonb,
    'beitraege', (SELECT coalesce(jsonb_agg(talents_beitrag_json(x.id) || jsonb_build_object('zuordnung', x.st,
        'zuordnung_text', CASE x.st WHEN 'bestaetigt' THEN 'zugeordnet' WHEN 'vorschlag' THEN 'vorgeschlagen' WHEN 'entfernt' THEN 'entfernt' END, 'grund', x.grund)
        ORDER BY x.erst DESC, x.id), '[]'::jsonb)
      FROM (SELECT b.id, coalesce(b.erstellt, b.erfasst_am) AS erst, kb.status AS st, kb.grund FROM talent_beitraege b JOIN talent_kanaele c2 ON c2.id = b.kanal_id
            LEFT JOIN talent_kampagne_beitraege kb ON kb.kampagne_id = k.id AND kb.beitrag_id = b.id
            WHERE c2.talent_id = ta AND (be = 'alle' OR talents_tag(coalesce(b.erstellt, b.erfasst_am)) BETWEEN k.von AND k.bis)
            ORDER BY coalesce(b.erstellt, b.erfasst_am) DESC, b.id OFFSET (seite - 1) * je LIMIT je) x),
    'anzahl', anz, 'seite', seite, 'seiten', greatest(1, ceil(anz / je::numeric)::integer), 'je_seite', je,
    'leer_text', CASE WHEN ta IS NULL THEN 'Dieser Kampagne ist noch kein Talent zugeordnet.' WHEN anz = 0 THEN
      CASE WHEN be = 'zeitraum' THEN 'Keine Beiträge im Kampagnenzeitraum. Unter „Alle Beiträge“ stehen auch ältere und spätere.' ELSE 'Noch keine Beiträge von diesem Talent.' END END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen(p_token text, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; u text; verw boolean;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  st text := lower(btrim(coalesce(f->>'status', '')));
  su text := lower(left(btrim(coalesce(f->>'suche', '')), 100));
  ta integer; sicht integer[]; basis integer[]; anz integer; seite integer; je integer := 10; gesamt integer;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  u := c->>'u'; verw := (c->>'verw')::boolean;
  -- Migration 66: sehen nach „Talents ansehen“, darf_verwalten nach „Talents und Kampagnen verwalten“
  sicht := CASE WHEN c->>'zugriff' = 'alle' THEN NULL ELSE ARRAY(SELECT tp.talent_id FROM talent_personen tp WHERE tp.matrix_user_id = u) END;
  IF st NOT IN ('', 'laufend', 'geplant', 'beendet') THEN st := ''; END IF;
  ta := CASE WHEN btrim(coalesce(f->>'talent', '')) ~ '^[0-9]{1,9}$' AND talent_sichtbar(u, btrim(f->>'talent')::integer) THEN btrim(f->>'talent')::integer END;
  SELECT count(*)::integer INTO gesamt FROM talent_kampagnen k
  WHERE c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = ANY (sicht));
  basis := ARRAY(SELECT k.id FROM talent_kampagnen k
    WHERE (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = ANY (sicht)))
      AND (ta IS NULL OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = ta))
      AND (su = '' OR position(su IN lower(k.marke || ' ' || k.name)) > 0)
    ORDER BY CASE talents_kampagne_status(k.von, k.bis) WHEN 'laufend' THEN 0 WHEN 'geplant' THEN 1 ELSE 2 END,
             CASE WHEN k.bis < talents_heute() THEN talents_heute() - k.bis ELSE k.von - talents_heute() END, k.id);
  SELECT count(*)::integer INTO anz FROM talent_kampagnen k WHERE k.id = ANY (basis) AND (st = '' OR talents_kampagne_status(k.von, k.bis) = st);
  seite := talents_seite_nr(f->>'seite', anz, je);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_verwalten', verw,
    'filter', jsonb_build_object('status', st, 'talent', coalesce(ta::text, ''), 'suche', left(btrim(coalesce(f->>'suche', '')), 100), 'seite', seite),
    'zeilen', (SELECT coalesce(jsonb_agg(talents_kampagne_kurz(x.id, sicht) ORDER BY x.o), '[]'::jsonb)
               FROM (SELECT b.id, b.o FROM unnest(basis) WITH ORDINALITY AS b(id, o) JOIN talent_kampagnen k ON k.id = b.id
                     WHERE st = '' OR talents_kampagne_status(k.von, k.bis) = st ORDER BY b.o OFFSET (seite - 1) * je LIMIT je) x),
    'anzahl', anz, 'seite', seite, 'seiten', greatest(1, ceil(anz / je::numeric)::integer), 'je_seite', je,
    'status_auswahl', (SELECT jsonb_agg(jsonb_build_object('schluessel', a.k, 'name', a.n,
        'anzahl', (SELECT count(*) FROM talent_kampagnen k WHERE k.id = ANY (basis) AND (a.k = '' OR talents_kampagne_status(k.von, k.bis) = a.k))) ORDER BY a.o)
      FROM (VALUES ('', 'Alle', 1), ('laufend', 'Laufend', 2), ('geplant', 'Geplant', 3), ('beendet', 'Beendet', 4)) AS a(k, n, o)),
    'auswahl', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'titel', k.marke || ' – ' || k.name,
        'status_text', CASE talents_kampagne_status(k.von, k.bis) WHEN 'geplant' THEN 'geplant' WHEN 'laufend' THEN 'läuft' ELSE 'beendet' END) ORDER BY b.o), '[]'::jsonb)
      FROM unnest(ARRAY(SELECT k2.id FROM talent_kampagnen k2 WHERE c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k2.id AND kt.talent_id = ANY (sicht))
                        ORDER BY k2.bis < talents_heute(), lower(k2.marke || ' ' || k2.name) COLLATE "C", k2.id)) WITH ORDINALITY AS b(id, o)
      JOIN talent_kampagnen k ON k.id = b.id),
    'talent_auswahl', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'anzeigename', talent_listenname(t.id)) ORDER BY lower(talent_listenname(t.id)) COLLATE "C", t.id), '[]'::jsonb)
      FROM talents t WHERE t.status = 'aktiv' AND (c->>'zugriff' = 'alle' OR t.id = ANY (sicht))),
    'leer_text', CASE WHEN anz > 0 THEN NULL WHEN gesamt = 0 THEN CASE WHEN verw THEN 'Noch keine Kampagnen. Lege die erste mit „Neue Kampagne“ an.'
                                                                     ELSE 'Für deine Talents gibt es noch keine Kampagnen.' END
                      ELSE 'Keine Kampagnen für diesen Filter.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_papierkorb(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb; u text; adm boolean; mgmt boolean; e talent_kampagnen_papierkorb%ROWTYPE; r jsonb; ks integer[];
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  m text := NULL; fehler text := NULL; n integer := 0; n2 integer := 0;
BEGIN
  -- Migration 131: Papierkorb der Kampagnen (Seite Kampagnen › Papierkorb). Rechte je Eintrag wie beim Löschen (talents_kampagnen_pk_darf).
  c := talents_planung_start(p_token, 'kampagnen');
  IF NOT coalesce((c->>'angemeldet')::boolean, false) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  u := c->>'u'; adm := coalesce((c->>'adm')::boolean, false); mgmt := coalesce((c->>'mgmt')::boolean, false);
  IF NOT (c->>'ok')::boolean THEN
    fehler := coalesce(c->>'fehler', 'Bitte neu anmelden.');
  ELSIF p_aktion IN ('kp_papierkorb_wiederherstellen', 'kp_papierkorb_endgueltig') THEN
    IF coalesce(d->>'id', '') ~ '^[0-9]{1,18}$' THEN SELECT * INTO e FROM talent_kampagnen_papierkorb x WHERE x.id = (d->>'id')::bigint FOR UPDATE; END IF;
    IF e.id IS NULL OR NOT talents_kampagnen_pk_darf(u, adm, mgmt, e) THEN
      fehler := 'Dieser Eintrag liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.';
    ELSIF p_aktion = 'kp_papierkorb_wiederherstellen' THEN
      r := talents_kampagnen_pk_zurueck(e.id, u);
      fehler := r->>'fehler'; m := r->>'meldung';
    ELSE
      DELETE FROM talent_kampagnen_papierkorb x WHERE x.id = e.id OR (e.art = 'kampagne' AND x.kampagne_id = e.kampagne_id AND x.art <> 'kampagne');
      GET DIAGNOSTICS n = ROW_COUNT;
      m := CASE e.art WHEN 'kampagne' THEN 'Kampagne „' || e.titel || '“ endgültig gelöscht'
                        || CASE WHEN n = 2 THEN ', dazu 1 weiterer Eintrag dieser Kampagne aus dem Papierkorb' WHEN n > 2 THEN ', dazu ' || (n - 1) || ' weitere Einträge dieser Kampagne aus dem Papierkorb' ELSE '' END
                        || '. Beiträge und Zahlen der Talents bleiben erhalten.'
                      WHEN 'deliverable' THEN e.titel || ' endgültig gelöscht.'
                      WHEN 'link' THEN 'Link „' || e.titel || '“ endgültig gelöscht.'
                      ELSE 'Erinnerung „' || e.titel || '“ endgültig gelöscht.' END;
    END IF;
  ELSIF p_aktion = 'kp_papierkorb_leeren' THEN
    IF coalesce(d->>'ids', '') !~ '^[0-9]{1,18}(,[0-9]{1,18})*$' OR cardinality(string_to_array(d->>'ids', ',')) > 1000 THEN
      fehler := 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.';
    ELSE
      -- genau die angezeigten Einträge (soweit erlaubt), dazu die übrigen Einträge ihrer Kampagnen
      ks := ARRAY(SELECT x.kampagne_id FROM talent_kampagnen_papierkorb x WHERE x.id = ANY (string_to_array(d->>'ids', ',')::bigint[]) AND x.art = 'kampagne'
                    AND talents_kampagnen_pk_darf(u, adm, mgmt, x));
      DELETE FROM talent_kampagnen_papierkorb x WHERE x.id = ANY (string_to_array(d->>'ids', ',')::bigint[]) AND talents_kampagnen_pk_darf(u, adm, mgmt, x);
      GET DIAGNOSTICS n = ROW_COUNT;
      DELETE FROM talent_kampagnen_papierkorb x WHERE x.kampagne_id = ANY (ks) AND x.art <> 'kampagne';
      GET DIAGNOSTICS n2 = ROW_COUNT;
      n := n + n2;
      m := CASE WHEN n = 0 THEN 'Diese Einträge liegen nicht mehr im Papierkorb.' WHEN n = 1 THEN '1 Eintrag endgültig gelöscht.' ELSE n || ' Einträge endgültig gelöscht.' END;
    END IF;
  ELSE
    fehler := 'Diese Aktion gibt es nicht.';
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_pk_darf(p_u text, p_adm boolean, p_mgmt boolean, p_e talent_kampagnen_papierkorb)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 131: Wer einen Eintrag im Papierkorb der Kampagnen sehen, wiederherstellen und endgültig löschen darf (wie beim Löschen).
  SELECT CASE
    WHEN p_e.art <> 'kampagne' AND EXISTS (SELECT 1 FROM talent_kampagnen k WHERE k.id = p_e.kampagne_id) THEN
      CASE WHEN p_e.art = 'deliverable' THEN coalesce(talent_verwaltbar(p_u, p_e.talent_id), false) AND talents_planung_recht(p_u, p_e.kampagne_id) IS NOT NULL
           ELSE talents_planung_planen(p_u, p_e.kampagne_id) END
    ELSE coalesce(p_adm, false)
      OR coalesce(p_mgmt, false) AND coalesce((SELECT k.zustaendig = p_u AND NOT EXISTS (SELECT 1 FROM unnest(k.talents) t WHERE NOT coalesce(talent_verwaltbar(p_u, t), false))
                                               FROM talent_kampagnen_papierkorb k WHERE k.art = 'kampagne' AND k.kampagne_id = p_e.kampagne_id), false)
  END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_pk_legen(p_art text, p_id bigint, p_u text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
  k talent_kampagnen%ROWTYPE; tid integer; ti text;
  dl bigint[] := '{}'; au bigint[] := '{}'; rg integer[] := '{}'; ve bigint[] := '{}';
  dt jsonb := '{}'::jsonb; neu bigint;
BEGIN
  -- Migration 131: Schnappschuss in den Papierkorb und Entfernen (Bauart A). Rechte prüft der Aufrufer. NULL, wenn es das Objekt nicht (mehr) gibt.
  IF p_art = 'kampagne' THEN
    SELECT * INTO k FROM talent_kampagnen WHERE id = p_id FOR UPDATE;
    IF k.id IS NULL THEN RETURN NULL; END IF;
    dl := ARRAY(SELECT x.id FROM talent_deliverables x WHERE x.kampagne_id = k.id);
    rg := ARRAY(SELECT x.id FROM talent_erinnerungsregeln x WHERE x.kampagne_id = k.id);
    au := ARRAY(SELECT x.id FROM talent_aufgaben x WHERE x.kampagne_id = k.id OR x.deliverable_id = ANY (dl));
    ti := k.marke || ' – ' || k.name;
    dt := jsonb_build_object(
      'kampagnen', (SELECT jsonb_agg(to_jsonb(x)) FROM talent_kampagnen x WHERE x.id = k.id),
      'kampagne_talents', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.talent_id), '[]'::jsonb) FROM talent_kampagne_talents x WHERE x.kampagne_id = k.id),
      'kampagne_beitraege', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.beitrag_id), '[]'::jsonb) FROM talent_kampagne_beitraege x WHERE x.kampagne_id = k.id),
      'links', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id), '[]'::jsonb) FROM talent_kampagne_links x WHERE x.kampagne_id = k.id));
  ELSIF p_art = 'deliverable' THEN
    SELECT ka.* INTO k FROM talent_deliverables x JOIN talent_kampagnen ka ON ka.id = x.kampagne_id WHERE x.id = p_id;
    IF k.id IS NULL THEN RETURN NULL; END IF;
    dl := ARRAY[p_id];
    au := ARRAY(SELECT x.id FROM talent_aufgaben x WHERE x.deliverable_id = p_id);
    SELECT x.talent_id, talents_planung_deliverable_name(x.format, x.anzahl, x.titel) || ' von ' || coalesce(talent_listenname(x.talent_id), 'Talent')
      INTO tid, ti FROM talent_deliverables x WHERE x.id = p_id;
  ELSIF p_art = 'link' THEN
    SELECT ka.* INTO k FROM talent_kampagne_links x JOIN talent_kampagnen ka ON ka.id = x.kampagne_id WHERE x.id = p_id;
    IF k.id IS NULL THEN RETURN NULL; END IF;
    SELECT x.titel INTO ti FROM talent_kampagne_links x WHERE x.id = p_id;
    dt := jsonb_build_object('links', (SELECT jsonb_agg(to_jsonb(x)) FROM talent_kampagne_links x WHERE x.id = p_id));
  ELSIF p_art = 'regel' THEN
    SELECT ka.* INTO k FROM talent_erinnerungsregeln x JOIN talent_kampagnen ka ON ka.id = x.kampagne_id WHERE x.id = p_id AND x.geloescht_am IS NULL;
    IF k.id IS NULL THEN RETURN NULL; END IF;
    rg := ARRAY[p_id::integer];
    SELECT talents_planung_regel_text(x.bezug, x.versatz_tage) || CASE WHEN x.empfaenger = 'talent' THEN ' an das Talent' ELSE ' an den Manager oder die Managerin' END
      INTO ti FROM talent_erinnerungsregeln x WHERE x.id = p_id;
  ELSE
    RAISE EXCEPTION 'Papierkorb der Kampagnen: unbekannte Art %', p_art;
  END IF;
  ve := ARRAY(SELECT x.id FROM talent_deliverable_versionen x WHERE x.deliverable_id = ANY (dl));
  dt := dt || jsonb_build_object(
    'regeln', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id), '[]'::jsonb) FROM talent_erinnerungsregeln x WHERE x.id = ANY (rg)),
    'deliverables', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id), '[]'::jsonb) FROM talent_deliverables x WHERE x.id = ANY (dl)),
    'versionen', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id), '[]'::jsonb) FROM talent_deliverable_versionen x WHERE x.id = ANY (ve)),
    'aufgaben', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id), '[]'::jsonb) FROM talent_aufgaben x WHERE x.id = ANY (au)),
    'nachrichten', (SELECT coalesce(jsonb_agg(to_jsonb(x) - 'geheim' ORDER BY x.id), '[]'::jsonb) FROM ally_systemnachrichten x WHERE x.aufgabe_id = ANY (au)),
    'lauf', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id), '[]'::jsonb) FROM talent_erinnerungen_lauf x WHERE x.deliverable_id = ANY (dl) OR x.regel_id = ANY (rg)),
    'aufgabe_regel', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'regel_id', x.regel_id) ORDER BY x.id), '[]'::jsonb)
                      FROM talent_aufgaben x WHERE x.regel_id = ANY (rg) AND NOT x.id = ANY (au)),
    'aufgabe_version', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'version_id', x.version_id) ORDER BY x.id), '[]'::jsonb)
                        FROM talent_aufgaben x WHERE x.version_id = ANY (ve) AND NOT x.id = ANY (au)),
    'lauf_aufgabe', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'aufgabe_id', x.aufgabe_id) ORDER BY x.id), '[]'::jsonb)
                     FROM talent_erinnerungen_lauf x WHERE x.aufgabe_id = ANY (au) AND NOT (x.deliverable_id = ANY (dl) OR x.regel_id = ANY (rg))));
  INSERT INTO talent_kampagnen_papierkorb (art, objekt_id, kampagne_id, talent_id, zustaendig, talents, titel, kampagne_titel, daten, testdaten, geloescht_von)
  VALUES (p_art, p_id, k.id, tid, k.zustaendig, ARRAY(SELECT x.talent_id FROM talent_kampagne_talents x WHERE x.kampagne_id = k.id ORDER BY 1),
          coalesce(ti, '–'), k.marke || ' – ' || k.name, dt, k.testdaten, p_u)
  RETURNING id INTO neu;
  IF p_art = 'kampagne' THEN DELETE FROM talent_kampagnen WHERE id = k.id;
  ELSIF p_art = 'deliverable' THEN DELETE FROM talent_deliverables WHERE id = p_id;
  ELSIF p_art = 'link' THEN DELETE FROM talent_kampagne_links WHERE id = p_id;
  ELSE DELETE FROM talent_erinnerungsregeln WHERE id = p_id;
  END IF;
  RETURN neu;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_pk_liste(p_u text, p_adm boolean, p_mgmt boolean)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 131: Einträge im Papierkorb der Kampagnen, die die Person sehen darf (neueste zuerst). leeren_anzahl = was „Papierkorb leeren“ genau löscht:
  -- die sichtbaren Einträge und die übrigen Einträge ihrer Kampagnen im Papierkorb.
  WITH s AS (SELECT e.* FROM talent_kampagnen_papierkorb e WHERE talents_kampagnen_pk_darf(p_u, p_adm, p_mgmt, e))
  SELECT jsonb_build_object(
    'eintraege', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'art', s.art,
        'art_text', CASE s.art WHEN 'kampagne' THEN 'Kampagne' WHEN 'deliverable' THEN 'Deliverable' WHEN 'link' THEN 'Link' ELSE 'Erinnerung' END,
        'titel', s.titel, 'kampagne', s.kampagne_titel, 'kampagne_da', EXISTS (SELECT 1 FROM talent_kampagnen k WHERE k.id = s.kampagne_id),
        'umfang', talents_kampagnen_pk_umfang(s.daten, s.art),
        'mit', CASE WHEN s.art = 'kampagne' THEN (SELECT count(*) FROM talent_kampagnen_papierkorb x WHERE x.kampagne_id = s.kampagne_id AND x.art <> 'kampagne') ELSE 0 END,
        'geloescht', to_char(s.geloescht_am AT TIME ZONE 'Europe/Berlin', 'FMDD.FMMM.YYYY'),
        'von', (SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = s.geloescht_von)) ORDER BY s.geloescht_am DESC, s.id DESC), '[]'::jsonb) FROM s),
    'leeren_anzahl', (SELECT count(*) FROM s) + (SELECT count(*) FROM talent_kampagnen_papierkorb x
        WHERE x.art <> 'kampagne' AND x.kampagne_id IN (SELECT s.kampagne_id FROM s WHERE s.art = 'kampagne') AND x.id NOT IN (SELECT s.id FROM s)))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_pk_talent_weg()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  e record; weg jsonb; ds jsonb;
BEGIN
  -- Migration 131: Wird ein Talent endgültig gelöscht, verschwinden seine Zeilen auch aus dem Papierkorb der Kampagnen (wie per Fremdschlüssel in den Tabellen).
  DELETE FROM talent_kampagnen_papierkorb WHERE art = 'deliverable' AND talent_id = OLD.id;
  FOR e IN SELECT x.id, x.daten FROM talent_kampagnen_papierkorb x WHERE OLD.id = ANY (x.talents) FOR UPDATE LOOP
    weg := (SELECT coalesce(jsonb_agg(j->'id'), '[]'::jsonb) FROM jsonb_array_elements(coalesce(e.daten->'deliverables', '[]')) j WHERE (j->>'talent_id')::integer = OLD.id);
    ds := e.daten || jsonb_build_object(
      'kampagne_talents', (SELECT coalesce(jsonb_agg(j), '[]'::jsonb) FROM jsonb_array_elements(coalesce(e.daten->'kampagne_talents', '[]')) j WHERE (j->>'talent_id')::integer <> OLD.id),
      'deliverables', (SELECT coalesce(jsonb_agg(j), '[]'::jsonb) FROM jsonb_array_elements(coalesce(e.daten->'deliverables', '[]')) j WHERE NOT weg @> jsonb_build_array(j->'id')),
      'versionen', (SELECT coalesce(jsonb_agg(j), '[]'::jsonb) FROM jsonb_array_elements(coalesce(e.daten->'versionen', '[]')) j WHERE NOT weg @> jsonb_build_array(j->'deliverable_id')),
      'lauf', (SELECT coalesce(jsonb_agg(j), '[]'::jsonb) FROM jsonb_array_elements(coalesce(e.daten->'lauf', '[]')) j WHERE NOT weg @> jsonb_build_array(j->'deliverable_id')),
      'aufgaben', (SELECT coalesce(jsonb_agg(j), '[]'::jsonb) FROM jsonb_array_elements(coalesce(e.daten->'aufgaben', '[]')) j WHERE (j->>'talent_id')::integer <> OLD.id),
      'nachrichten', (SELECT coalesce(jsonb_agg(j), '[]'::jsonb) FROM jsonb_array_elements(coalesce(e.daten->'nachrichten', '[]')) j WHERE (j->>'talent_id')::integer IS DISTINCT FROM OLD.id));
    -- talent_weg: Zahl der so entfernten Deliverables und Aufgaben (die Meldung beim Wiederherstellen nennt sie)
    ds := ds || jsonb_build_object('talent_weg', coalesce((e.daten->>'talent_weg')::integer, 0)
            + jsonb_array_length(coalesce(e.daten->'deliverables', '[]')) - jsonb_array_length(ds->'deliverables')
            + jsonb_array_length(coalesce(e.daten->'aufgaben', '[]')) - jsonb_array_length(ds->'aufgaben'));
    UPDATE talent_kampagnen_papierkorb x SET daten = ds, talents = array_remove(x.talents, OLD.id) WHERE x.id = e.id;
  END LOOP;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_pk_umfang(p_daten jsonb, p_art text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 131: was mit einem Eintrag im Papierkorb liegt, als Text (genau aus dem Schnappschuss); leer, wenn nichts dazugehört.
  SELECT coalesce(string_agg(z.t, ', ' ORDER BY z.o), '') FROM (
    SELECT 1 AS o, CASE WHEN n = 1 THEN '1 Deliverable' ELSE n || ' Deliverables' END AS t FROM (SELECT jsonb_array_length(coalesce(p_daten->'deliverables', '[]')) AS n) x WHERE p_art = 'kampagne' AND n > 0
    UNION ALL SELECT 2, CASE WHEN n = 1 THEN '1 Entwurf' ELSE n || ' Entwürfe' END FROM (SELECT jsonb_array_length(coalesce(p_daten->'versionen', '[]')) AS n) x WHERE n > 0
    UNION ALL SELECT 3, CASE WHEN n = 1 THEN '1 Aufgabe oder Termin' ELSE n || ' Aufgaben und Termine' END FROM (SELECT jsonb_array_length(coalesce(p_daten->'aufgaben', '[]')) AS n) x WHERE n > 0
    UNION ALL SELECT 4, CASE WHEN n = 1 THEN '1 Link' ELSE n || ' Links' END FROM (SELECT jsonb_array_length(coalesce(p_daten->'links', '[]')) AS n) x WHERE p_art = 'kampagne' AND n > 0
    UNION ALL SELECT 5, CASE WHEN n = 1 THEN '1 eigene Erinnerung' ELSE n || ' eigene Erinnerungen' END FROM (SELECT jsonb_array_length(coalesce(p_daten->'regeln', '[]')) AS n) x WHERE p_art = 'kampagne' AND n > 0
  ) z
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_pk_zurueck(p_id bigint, p_u text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  e talent_kampagnen_papierkorb%ROWTYPE; dt jsonb; kid integer; n_soll integer; n_ist integer; eigene_vorher boolean; zus text; m text;
BEGIN
  -- Migration 131: Eintrag aus dem Papierkorb der Kampagnen zurück (alte Nummern, Reihenfolge nach Fremdschlüsseln). Rechte prüft der Aufrufer.
  SELECT * INTO e FROM talent_kampagnen_papierkorb WHERE id = p_id FOR UPDATE;
  IF e.id IS NULL THEN RETURN jsonb_build_object('fehler', 'Dieser Eintrag liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.'); END IF;
  dt := e.daten; kid := e.kampagne_id;
  IF e.art = 'kampagne' THEN
    IF EXISTS (SELECT 1 FROM talent_kampagnen k WHERE k.id = kid) THEN
      RETURN jsonb_build_object('fehler', 'Diese Kampagne gibt es schon wieder. Bitte die Seite neu laden.');
    END IF;
    zus := dt->'kampagnen'->0->>'zustaendig';
    IF zus IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = zus) THEN zus := NULL; END IF;
    INSERT INTO talent_kampagnen SELECT (jsonb_populate_record(NULL::talent_kampagnen, (dt->'kampagnen'->0) || jsonb_build_object('zustaendig', zus))).*;
    INSERT INTO talent_kampagne_talents SELECT x.* FROM jsonb_populate_recordset(NULL::talent_kampagne_talents, dt->'kampagne_talents') x
      WHERE EXISTS (SELECT 1 FROM talents t WHERE t.id = x.talent_id) ON CONFLICT DO NOTHING;
    INSERT INTO talent_kampagne_beitraege SELECT x.* FROM jsonb_populate_recordset(NULL::talent_kampagne_beitraege, dt->'kampagne_beitraege') x
      WHERE EXISTS (SELECT 1 FROM talent_beitraege b WHERE b.id = x.beitrag_id) ON CONFLICT DO NOTHING;
  ELSIF NOT EXISTS (SELECT 1 FROM talent_kampagnen k WHERE k.id = kid) THEN
    RETURN jsonb_build_object('fehler', 'Die Kampagne „' || e.kampagne_titel || '“ ist nicht mehr da. Bitte zuerst die Kampagne aus dem Papierkorb wiederherstellen.');
  ELSIF e.art = 'deliverable' AND NOT EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = kid AND kt.talent_id = e.talent_id) THEN
    RETURN jsonb_build_object('fehler', 'Das Talent gehört nicht mehr zur Kampagne „' || e.kampagne_titel || '“. Bitte das Talent zuerst wieder der Kampagne zuordnen.');
  ELSIF e.art = 'regel' AND EXISTS (SELECT 1 FROM talent_erinnerungsregeln g, jsonb_populate_recordset(NULL::talent_erinnerungsregeln, dt->'regeln') x
                                    WHERE g.kampagne_id = kid AND g.geloescht_am IS NULL AND g.bezug = x.bezug AND g.versatz_tage = x.versatz_tage AND g.empfaenger = x.empfaenger) THEN
    RETURN jsonb_build_object('fehler', 'Die gleiche Erinnerung gibt es in dieser Kampagne inzwischen schon. Bitte den Eintrag im Papierkorb endgültig löschen oder die andere Regel zuerst ändern.');
  END IF;
  eigene_vorher := EXISTS (SELECT 1 FROM talent_erinnerungsregeln g WHERE g.kampagne_id = kid);
  INSERT INTO talent_kampagne_links SELECT x.* FROM jsonb_populate_recordset(NULL::talent_kampagne_links, coalesce(dt->'links', '[]')) x ON CONFLICT DO NOTHING;
  INSERT INTO talent_erinnerungsregeln SELECT x.* FROM jsonb_populate_recordset(NULL::talent_erinnerungsregeln, coalesce(dt->'regeln', '[]')) x ON CONFLICT DO NOTHING;
  INSERT INTO talent_deliverables
  SELECT (jsonb_populate_record(NULL::talent_deliverables, j || jsonb_build_object('beitrag_id',
           CASE WHEN EXISTS (SELECT 1 FROM talent_beitraege b WHERE b.id = (j->>'beitrag_id')::bigint) THEN j->'beitrag_id' ELSE 'null'::jsonb END))).*
  FROM jsonb_array_elements(coalesce(dt->'deliverables', '[]')) j
  WHERE EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = (j->>'kampagne_id')::integer AND kt.talent_id = (j->>'talent_id')::integer)
  ON CONFLICT DO NOTHING;
  INSERT INTO talent_deliverable_versionen SELECT x.* FROM jsonb_populate_recordset(NULL::talent_deliverable_versionen, coalesce(dt->'versionen', '[]')) x
    WHERE EXISTS (SELECT 1 FROM talent_deliverables d WHERE d.id = x.deliverable_id) ON CONFLICT DO NOTHING;
  INSERT INTO talent_aufgaben
  SELECT (jsonb_populate_record(NULL::talent_aufgaben, j || jsonb_build_object(
           'regel_id', CASE WHEN EXISTS (SELECT 1 FROM talent_erinnerungsregeln g WHERE g.id = (j->>'regel_id')::integer) THEN j->'regel_id' ELSE 'null'::jsonb END,
           'version_id', CASE WHEN EXISTS (SELECT 1 FROM talent_deliverable_versionen v WHERE v.id = (j->>'version_id')::bigint) THEN j->'version_id' ELSE 'null'::jsonb END))).*
  FROM jsonb_array_elements(coalesce(dt->'aufgaben', '[]')) j
  WHERE EXISTS (SELECT 1 FROM talents t WHERE t.id = (j->>'talent_id')::integer)
    AND (j->>'kampagne_id' IS NULL OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = (j->>'kampagne_id')::integer AND kt.talent_id = (j->>'talent_id')::integer))
    AND (j->>'deliverable_id' IS NULL OR EXISTS (SELECT 1 FROM talent_deliverables d WHERE d.id = (j->>'deliverable_id')::bigint AND d.talent_id = (j->>'talent_id')::integer))
  ON CONFLICT DO NOTHING;
  INSERT INTO ally_systemnachrichten SELECT x.* FROM jsonb_populate_recordset(NULL::ally_systemnachrichten, coalesce(dt->'nachrichten', '[]')) x
    WHERE EXISTS (SELECT 1 FROM talent_aufgaben a WHERE a.id = x.aufgabe_id) ON CONFLICT DO NOTHING;
  INSERT INTO talent_erinnerungen_lauf
  SELECT (jsonb_populate_record(NULL::talent_erinnerungen_lauf, j || jsonb_build_object('aufgabe_id',
           CASE WHEN EXISTS (SELECT 1 FROM talent_aufgaben a WHERE a.id = (j->>'aufgabe_id')::bigint) THEN j->'aufgabe_id' ELSE 'null'::jsonb END))).*
  FROM jsonb_array_elements(coalesce(dt->'lauf', '[]')) j
  WHERE EXISTS (SELECT 1 FROM talent_erinnerungsregeln g WHERE g.id = (j->>'regel_id')::integer)
    AND EXISTS (SELECT 1 FROM talent_deliverables d WHERE d.id = (j->>'deliverable_id')::bigint)
  ON CONFLICT DO NOTHING;
  UPDATE talent_aufgaben a SET regel_id = (j->>'regel_id')::integer FROM jsonb_array_elements(coalesce(dt->'aufgabe_regel', '[]')) j
  WHERE a.id = (j->>'id')::bigint AND a.regel_id IS NULL AND EXISTS (SELECT 1 FROM talent_erinnerungsregeln g WHERE g.id = (j->>'regel_id')::integer);
  UPDATE talent_aufgaben a SET version_id = (j->>'version_id')::bigint FROM jsonb_array_elements(coalesce(dt->'aufgabe_version', '[]')) j
  WHERE a.id = (j->>'id')::bigint AND a.version_id IS NULL AND EXISTS (SELECT 1 FROM talent_deliverable_versionen v WHERE v.id = (j->>'version_id')::bigint);
  UPDATE talent_erinnerungen_lauf l SET aufgabe_id = (j->>'aufgabe_id')::bigint FROM jsonb_array_elements(coalesce(dt->'lauf_aufgabe', '[]')) j
  WHERE l.id = (j->>'id')::bigint AND l.aufgabe_id IS NULL AND EXISTS (SELECT 1 FROM talent_aufgaben a WHERE a.id = (j->>'aufgabe_id')::bigint);
  -- Was nicht zurückkam (Talent oder Beitrag inzwischen endgültig gelöscht)
  -- dazu, was der Auslöser auf talents schon aus dem Schnappschuss genommen hat (talent_weg)
  n_soll := jsonb_array_length(coalesce(dt->'deliverables', '[]')) + jsonb_array_length(coalesce(dt->'aufgaben', '[]')) + coalesce((dt->>'talent_weg')::integer, 0);
  SELECT (SELECT count(*) FROM talent_deliverables d WHERE d.id IN (SELECT (j->>'id')::bigint FROM jsonb_array_elements(coalesce(dt->'deliverables', '[]')) j))
       + (SELECT count(*) FROM talent_aufgaben a WHERE a.id IN (SELECT (j->>'id')::bigint FROM jsonb_array_elements(coalesce(dt->'aufgaben', '[]')) j)) INTO n_ist;
  DELETE FROM talent_kampagnen_papierkorb WHERE id = e.id;
  m := CASE e.art WHEN 'kampagne' THEN 'Kampagne „' || e.titel || '“ wiederhergestellt.'
                  WHEN 'deliverable' THEN e.titel || ' wiederhergestellt.'
                  WHEN 'link' THEN 'Link „' || e.titel || '“ wiederhergestellt.'
                  ELSE 'Erinnerung „' || e.titel || '“ wiederhergestellt.' END
    || CASE WHEN n_soll - n_ist = 1 THEN ' 1 Eintrag gehört zu einem inzwischen gelöschten Talent und kommt nicht zurück.'
            WHEN n_soll - n_ist > 1 THEN ' ' || (n_soll - n_ist) || ' Einträge gehören zu inzwischen gelöschten Talents und kommen nicht zurück.' ELSE '' END
    || CASE WHEN e.art = 'regel' AND NOT eigene_vorher THEN ' Für diese Kampagne gelten damit wieder eigene Erinnerungen statt der Standard-Erinnerungen.' ELSE '' END
    -- Prüfung 131 N3: der stündliche Lauf holt Fälliges der letzten 2 Tage einmal nach
    || CASE WHEN e.art <> 'link' AND (jsonb_array_length(coalesce(dt->'deliverables', '[]')) > 0 OR jsonb_array_length(coalesce(dt->'regeln', '[]')) > 0)
            THEN ' Erinnerungen, die in den letzten 2 Tagen fällig geworden wären, kommen einmal nach.' ELSE '' END;
  RETURN jsonb_build_object('meldung', m);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_ui(p_token text, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; u text; verw boolean; adm boolean; mgmt boolean;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  st text := lower(btrim(coalesce(f->>'status', '')));
  su text := lower(left(btrim(coalesce(f->>'suche', '')), 100));
  sp text := coalesce(f #>> '{sortierung,spalte}', '');
  ri text := CASE WHEN f #>> '{sortierung,richtung}' = 'ab' THEN 'ab' ELSE 'auf' END;
  ta integer; je integer := 20; seite integer; anz integer; heute date := talents_heute();
  r jsonb;
BEGIN
  -- Seite Kampagnen, Liste (BA6, ALLY 26): Kennzahlen, Offen, Meldungen, alle sichtbaren Kampagnen (Filter, Sortierung und 20 je Seite in der Datenbank),
  -- nächste Deadlines und wartende Freigaben über alle Kampagnen. Sichtbar: Admin und Recht „Talents verwalten“ alle, sonst Kampagnen mit eigenen Talents
  -- oder als zuständige Person (nur die eigenen Talents). Budget nur für Admin und das zuständige Management (talents_planung_geld).
  -- Neue Kampagne: Admin, „Talents verwalten“ und Management (für die eigenen Talents, Stefan 20.10.2026).
  -- Migration 64: Budget-Feld nur mit dem Recht „Honorare und Budgets sehen“.
  c := talents_planung_start(p_token, 'kampagnen');
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  u := c->>'u'; verw := (c->>'verw')::boolean; adm := (c->>'adm')::boolean; mgmt := (c->>'mgmt')::boolean;
  IF st NOT IN ('', 'laufend', 'geplant', 'beendet', 'abgebrochen') THEN st := ''; END IF;
  IF sp NOT IN ('kampagne', 'zeitraum', 'status', 'talents', 'deliverables', 'naechste', 'budget') THEN sp := ''; END IF;
  ta := CASE WHEN btrim(coalesce(f->>'talent', '')) ~ '^[0-9]{1,9}$' AND talent_sichtbar(u, btrim(f->>'talent')::integer) THEN btrim(f->>'talent')::integer END;
  WITH k AS (SELECT ka.*, talents_planung_recht(u, ka.id) AS r, talents_planung_geld(u, ka.id, NULL) AS g FROM talent_kampagnen ka),
  v AS (SELECT k.*, talents_planung_kampagne_status(k.von, k.bis, k.abgebrochen_am) AS stat,
          ARRAY(SELECT kt.talent_id FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND (k.r = 'alle' OR talent_sichtbar(u, kt.talent_id))) AS tids
        FROM k WHERE k.r IS NOT NULL),
  w AS (SELECT v.*, (SELECT count(*)::integer FROM talent_deliverables d WHERE d.kampagne_id = v.id AND d.talent_id = ANY (v.tids)) AS d_ges,
          (SELECT count(*)::integer FROM talent_deliverables d WHERE d.kampagne_id = v.id AND d.talent_id = ANY (v.tids) AND d.status IN ('veroeffentlicht', 'abgerechnet')) AS d_erl,
          (SELECT min(d.deadline) FROM talent_deliverables d WHERE d.kampagne_id = v.id AND d.talent_id = ANY (v.tids) AND d.status IN ('geplant', 'entwurf', 'ueberarbeiten')) AS naechste,
          (st = '' OR v.stat = st) AND (su = '' OR position(su IN lower(v.marke || ' ' || v.name || ' ' || CASE v.stat WHEN 'geplant' THEN 'geplant' WHEN 'laufend' THEN 'läuft laufend' WHEN 'abgebrochen' THEN 'abgebrochen' ELSE 'beendet' END
            || ' ' || coalesce((SELECT string_agg(talent_listenname(t.x), ' ') FROM unnest(v.tids) AS t(x)), ''))) > 0) AND (ta IS NULL OR ta = ANY (v.tids)) AS treffer
        FROM v),
  sicht AS (SELECT d.* FROM talent_deliverables d JOIN w ON w.id = d.kampagne_id AND d.talent_id = ANY (w.tids) WHERE w.stat <> 'abgebrochen'),
  vers AS (SELECT x.*, sicht.kampagne_id, sicht.talent_id, sicht.format, sicht.anzahl, sicht.titel AS d_titel FROM talent_deliverable_versionen x JOIN sicht ON sicht.id = x.deliverable_id)
  SELECT jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_anlegen', verw OR mgmt, 'darf_budget', ally_recht_reichweite(u, 'talents_betraege') IS NOT NULL, 'darf_regeln', verw,
    'filter', jsonb_build_object('status', st, 'suche', left(btrim(coalesce(f->>'suche', '')), 100), 'talent', coalesce(ta::text, '')),
    'sortierung', jsonb_build_object('spalte', CASE WHEN sp = '' THEN 'status' ELSE sp END, 'richtung', CASE WHEN sp = '' THEN 'auf' ELSE ri END),
    'kennzahlen', jsonb_build_object(
      'laufend', (SELECT count(*) FROM w WHERE w.stat = 'laufend'),
      'geplant', (SELECT count(*) FROM w WHERE w.stat = 'geplant'),
      'deliverables_offen', (SELECT count(*) FROM sicht WHERE sicht.status NOT IN ('freigegeben', 'veroeffentlicht', 'abgerechnet')),
      'deadlines_7', (SELECT count(*) FROM sicht WHERE sicht.status IN ('geplant', 'entwurf', 'ueberarbeiten') AND sicht.deadline BETWEEN heute AND heute + 7),
      'ueberfaellig', (SELECT count(*) FROM sicht WHERE sicht.status IN ('geplant', 'entwurf', 'ueberarbeiten') AND sicht.deadline < heute),
      'freigaben_offen', (SELECT count(*) FROM vers WHERE vers.pruefung IN ('offen', 'intern_ok', 'bei_marke'))),
    'offen', (SELECT coalesce(jsonb_agg(o.e ORDER BY o.rang, o.t, o.id), '[]'::jsonb) FROM (
        (SELECT 1 AS rang, sicht.deadline::timestamptz AS t, sicht.id, jsonb_build_object('art', 'ueberfaellig', 'kampagne_id', sicht.kampagne_id, 'deliverable_id', sicht.id,
           'marke', CASE WHEN heute - sicht.deadline = 1 THEN 'seit gestern' ELSE 'seit ' || (heute - sicht.deadline) || ' Tagen' END,
           'text', talents_planung_deliverable_name(sicht.format, sicht.anzahl, sicht.titel) || ' von ' || coalesce(talent_listenname(sicht.talent_id), 'Talent')) AS e
         FROM sicht WHERE sicht.status IN ('geplant', 'entwurf', 'ueberarbeiten') AND sicht.deadline < heute ORDER BY sicht.deadline, sicht.id LIMIT 6)
        UNION ALL
        (SELECT 2, vers.eingereicht_am, vers.id, jsonb_build_object('art', 'freigabe', 'kampagne_id', vers.kampagne_id, 'deliverable_id', vers.deliverable_id, 'version_id', vers.id,
           'marke', CASE WHEN vers.pruefung = 'bei_marke' THEN 'Marke' ELSE 'Freigabe' END,
           'text', talents_planung_deliverable_name(vers.format, vers.anzahl, vers.d_titel) || ' von ' || coalesce(talent_listenname(vers.talent_id), 'Talent')
             || CASE WHEN vers.pruefung = 'bei_marke' THEN ' liegt bei der Marke' ELSE ' wartet auf Prüfung' END)
         FROM vers WHERE vers.pruefung IN ('offen', 'intern_ok', 'bei_marke') ORDER BY vers.eingereicht_am, vers.id LIMIT 6)) o),
    'meldungen', (SELECT coalesce(jsonb_agg(o.e ORDER BY o.t DESC, o.id DESC), '[]'::jsonb) FROM (
        (SELECT vers.eingereicht_am AS t, vers.id, jsonb_build_object('kampagne_id', vers.kampagne_id, 'marke', talents_planung_tag_text((vers.eingereicht_am AT TIME ZONE 'Europe/Berlin')::date),
           'text', 'Neuer Entwurf: ' || talents_planung_deliverable_name(vers.format, vers.anzahl, vers.d_titel) || ' von ' || coalesce(talent_listenname(vers.talent_id), 'Talent')) AS e
         FROM vers WHERE vers.eingereicht_am > now() - interval '7 days' ORDER BY vers.eingereicht_am DESC LIMIT 6)
        UNION ALL
        (SELECT vers.geprueft_am, vers.id, jsonb_build_object('kampagne_id', vers.kampagne_id, 'marke', talents_planung_tag_text((vers.geprueft_am AT TIME ZONE 'Europe/Berlin')::date),
           'text', 'Freigegeben: ' || talents_planung_deliverable_name(vers.format, vers.anzahl, vers.d_titel) || ' von ' || coalesce(talent_listenname(vers.talent_id), 'Talent'))
         FROM vers WHERE vers.pruefung = 'freigegeben' AND vers.geprueft_am > now() - interval '7 days' ORDER BY vers.geprueft_am DESC LIMIT 6)
        UNION ALL
        (SELECT a.erledigt_am, a.id, jsonb_build_object('kampagne_id', a.kampagne_id, 'talent_id', a.talent_id, 'marke', talents_planung_tag_text((a.erledigt_am AT TIME ZONE 'Europe/Berlin')::date),
           'text', coalesce(talent_listenname(a.talent_id), 'Talent') || ' hat erledigt: ' || a.titel)
         FROM talent_aufgaben a JOIN w ON w.id = a.kampagne_id AND a.talent_id = ANY (w.tids)
         WHERE a.status = 'erledigt' AND a.erledigt_von = 'talent' AND a.erledigt_am > now() - interval '7 days' ORDER BY a.erledigt_am DESC LIMIT 6)) o),
    'anzahl', (SELECT count(*) FROM w WHERE w.treffer),
    'gesamt_sichtbar', (SELECT count(*) FROM w),
    'zeilen', (SELECT coalesce(jsonb_agg(z.e ORDER BY z.o), '[]'::jsonb) FROM (
        SELECT jsonb_build_object('id', w.id, 'titel', w.marke || ' – ' || w.name, 'marke', w.marke, 'name', w.name,
          'zeitraum', to_char(w.von, 'DD.MM.') || '–' || to_char(w.bis, 'DD.MM.YYYY'), 'status', w.stat,
          'status_text', CASE w.stat WHEN 'geplant' THEN 'geplant' WHEN 'laufend' THEN 'läuft' WHEN 'abgebrochen' THEN 'abgebrochen' ELSE 'beendet' END,
          'talents', cardinality(w.tids), 'd_ges', w.d_ges, 'd_erl', w.d_erl,
          'naechste_text', CASE WHEN w.naechste IS NULL THEN '' ELSE talents_planung_tag_text(w.naechste) END, 'ueberfaellig', w.naechste < heute,
          'budget_text', CASE WHEN w.g THEN talents_planung_betrag_text(w.budget_cent) END) AS e,
          row_number() OVER (ORDER BY
            CASE WHEN sp = 'kampagne' AND ri = 'auf' THEN lower(w.marke || ' ' || w.name) END ASC, CASE WHEN sp = 'kampagne' AND ri = 'ab' THEN lower(w.marke || ' ' || w.name) END DESC,
            CASE WHEN sp = 'zeitraum' AND ri = 'auf' THEN w.von END ASC, CASE WHEN sp = 'zeitraum' AND ri = 'ab' THEN w.von END DESC,
            CASE WHEN sp = 'talents' AND ri = 'auf' THEN cardinality(w.tids) END ASC, CASE WHEN sp = 'talents' AND ri = 'ab' THEN cardinality(w.tids) END DESC,
            CASE WHEN sp = 'deliverables' AND ri = 'auf' THEN w.d_ges END ASC, CASE WHEN sp = 'deliverables' AND ri = 'ab' THEN w.d_ges END DESC,
            CASE WHEN sp = 'naechste' AND ri = 'auf' THEN w.naechste END ASC NULLS LAST, CASE WHEN sp = 'naechste' AND ri = 'ab' THEN w.naechste END DESC NULLS LAST,
            CASE WHEN sp = 'budget' AND ri = 'auf' THEN CASE WHEN w.g THEN w.budget_cent END END ASC NULLS LAST,
            CASE WHEN sp = 'budget' AND ri = 'ab' THEN CASE WHEN w.g THEN w.budget_cent END END DESC NULLS LAST,
            CASE WHEN sp = 'status' AND ri = 'ab' THEN CASE w.stat WHEN 'laufend' THEN 0 WHEN 'geplant' THEN 1 WHEN 'beendet' THEN 2 ELSE 3 END END DESC,
            CASE w.stat WHEN 'laufend' THEN 0 WHEN 'geplant' THEN 1 WHEN 'beendet' THEN 2 ELSE 3 END,
            CASE WHEN w.bis < heute THEN heute - w.bis ELSE w.von - heute END, w.id) AS o
        FROM w WHERE w.treffer) z
      WHERE z.o > (talents_seite_nr(f->>'seite', (SELECT count(*)::integer FROM w WHERE w.treffer), je) - 1) * je
        AND z.o <= talents_seite_nr(f->>'seite', (SELECT count(*)::integer FROM w WHERE w.treffer), je) * je),
    'seite', talents_seite_nr(f->>'seite', (SELECT count(*)::integer FROM w WHERE w.treffer), je), 'je_seite', je,
    'naechste', (SELECT coalesce(jsonb_agg(jsonb_build_object('kampagne_id', x.kampagne_id, 'kampagne', x.kt, 'deliverable_id', x.id, 'talent', coalesce(talent_listenname(x.talent_id), 'Talent'),
        'name', talents_planung_deliverable_name(x.format, x.anzahl, x.titel), 'deadline_text', talents_planung_tag_text(x.deadline), 'ueberfaellig', x.deadline < heute,
        'status_text', talents_planung_status_text(x.status)) ORDER BY x.deadline, x.id), '[]'::jsonb)
      FROM (SELECT sicht.*, (SELECT w.marke || ' – ' || w.name FROM w WHERE w.id = sicht.kampagne_id) AS kt FROM sicht
            WHERE sicht.status IN ('geplant', 'entwurf', 'ueberarbeiten') AND sicht.deadline <= heute + 14 ORDER BY sicht.deadline, sicht.id LIMIT 20) x),
    'freigaben', (SELECT coalesce(jsonb_agg(jsonb_build_object('kampagne_id', x.kampagne_id, 'kampagne', (SELECT w.marke || ' – ' || w.name FROM w WHERE w.id = x.kampagne_id),
        'deliverable_id', x.deliverable_id, 'version_id', x.id, 'talent', coalesce(talent_listenname(x.talent_id), 'Talent'),
        'name', talents_planung_deliverable_name(x.format, x.anzahl, x.d_titel) || ' · Version ' || x.version, 'eingereicht_text', talents_planung_zeit_text(x.eingereicht_am, false),
        'pruefung_text', talents_planung_pruefung_text(x.pruefung)) ORDER BY x.eingereicht_am, x.id), '[]'::jsonb)
      FROM (SELECT vers.* FROM vers WHERE vers.pruefung IN ('offen', 'intern_ok', 'bei_marke') ORDER BY vers.eingereicht_am, vers.id LIMIT 20) x),
    'talent_auswahl', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'anzeigename', talent_listenname(t.id)) ORDER BY lower(talent_listenname(t.id)) COLLATE "C", t.id), '[]'::jsonb)
      FROM talents t WHERE t.status = 'aktiv' AND talent_sichtbar(u, t.id)),
    'personen', CASE WHEN verw THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.matrix_user_id, 'name', p.name || CASE WHEN p.testdaten THEN ' (Testdaten)' ELSE '' END) ORDER BY lower(p.name), p.matrix_user_id), '[]'::jsonb)
      FROM ally_personen p WHERE p.aktiv AND talents_zugriff(p.matrix_user_id) IS NOT NULL) END,
    'ich', u, 'papierkorb', talents_kampagnen_pk_liste(u, adm, mgmt)) INTO r
  FROM (SELECT 1) eins;
  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kampagnen_vorschlaege(p_kampagne_id integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  heute date := talents_heute();
  n_neu integer; n_weg integer; n_auf integer; ks integer[];
BEGIN
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', true, 'kampagnen', 0, 'neu', 0, 'entfernt', 0, 'wieder_verfolgt', 0, 'hinweis', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  -- laufende und vor höchstens 30 Tagen beendete Kampagnen (oder genau eine)
  ks := ARRAY(SELECT k.id FROM talent_kampagnen k WHERE CASE WHEN p_kampagne_id IS NULL THEN k.bis >= heute - 30 ELSE k.id = p_kampagne_id END);
  -- Vorschläge, die nicht mehr passen (Talent nicht mehr dabei, Datum außerhalb, Merkmal geändert), entfallen
  DELETE FROM talent_kampagne_beitraege kb
  WHERE kb.kampagne_id = ANY (ks) AND kb.status = 'vorschlag'
    AND NOT EXISTS (SELECT 1 FROM talent_kampagnen k JOIN talent_kampagne_talents kt ON kt.kampagne_id = k.id
                    JOIN talent_kanaele c ON c.talent_id = kt.talent_id JOIN talent_beitraege b ON b.kanal_id = c.id
                    WHERE k.id = kb.kampagne_id AND b.id = kb.beitrag_id AND talents_tag(coalesce(b.erstellt, b.erfasst_am)) BETWEEN k.von AND k.bis
                      AND talents_kampagne_treffer(b.text_inhalt, k.marken_konten, k.hashtags, k.schlagwoerter) IS NOT NULL);
  GET DIAGNOSTICS n_weg = ROW_COUNT;
  INSERT INTO talent_kampagne_beitraege (kampagne_id, beitrag_id, status, quelle, grund)
  SELECT k.id, b.id, 'vorschlag', 'automatisch', g.grund
  FROM talent_kampagnen k JOIN talent_kampagne_talents kt ON kt.kampagne_id = k.id
  JOIN talent_kanaele c ON c.talent_id = kt.talent_id JOIN talent_beitraege b ON b.kanal_id = c.id
  CROSS JOIN LATERAL (SELECT talents_kampagne_treffer(b.text_inhalt, k.marken_konten, k.hashtags, k.schlagwoerter) AS grund) g
  WHERE k.id = ANY (ks) AND talents_tag(coalesce(b.erstellt, b.erfasst_am)) BETWEEN k.von AND k.bis AND g.grund IS NOT NULL
  ON CONFLICT (kampagne_id, beitrag_id) DO NOTHING;
  GET DIAGNOSTICS n_neu = ROW_COUNT;
  -- Beiträge laufender Kampagnen werden mindestens bis Kampagnenende verfolgt: eingefrorene wieder öffnen
  UPDATE talent_beitraege b SET abgeschlossen = false
  WHERE b.abgeschlossen AND talents_beitrag_art(b.art, b.produkt_art) <> 'story' AND talents_kampagne_bis(b.id) >= heute
    AND EXISTS (SELECT 1 FROM talent_kampagne_beitraege kb WHERE kb.beitrag_id = b.id AND kb.status <> 'entfernt');
  GET DIAGNOSTICS n_auf = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'kampagnen', cardinality(ks), 'neu', n_neu, 'entfernt', n_weg, 'wieder_verfolgt', n_auf);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kanal_auswahl(p_kanaele integer[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH k AS (
    SELECT k.id, k.plattform, k.status, nullif(ltrim(btrim(coalesce(k.extern_name, '')), '@'), '') AS nm, k.extern_id IS NOT NULL AS konto,
      array_position(talents_plattformen(), k.plattform) AS pr
    FROM talent_kanaele k WHERE k.id = ANY (p_kanaele)),
  p AS (SELECT k.plattform, min(k.pr) AS pr, count(*) FILTER (WHERE k.konto) AS n FROM k GROUP BY k.plattform),
  e AS (
    SELECT p.pr, 0 AS o, ''::text AS sort, 0 AS id,
      jsonb_build_object('schluessel', p.plattform, 'name', talents_plattform_name(p.plattform) || CASE WHEN p.n > 1 THEN ' (alle Accounts)' ELSE '' END,
        'plattform', p.plattform, 'kanal_id', NULL, 'alle', p.n > 1) AS x
    FROM p WHERE p.n <> 1
    UNION ALL
    SELECT k.pr, 1, lower(coalesce(k.nm, '')), k.id,
      jsonb_build_object('schluessel', 'k' || k.id,
        'name', talents_plattform_name(k.plattform) || ' ' || coalesce(CASE WHEN k.nm IS NOT NULL THEN talents_konto_text(k.plattform, k.nm) END, 'Account ' || k.id) || CASE WHEN k.status = 'getrennt' THEN ' (getrennt)' ELSE '' END,
        'plattform', k.plattform, 'kanal_id', k.id, 'alle', false)
    FROM k WHERE k.konto)
  -- "@" nur bei Instagram, Threads, Pinterest (Stefan 18.10.2026)
  SELECT coalesce(jsonb_agg(e.x ORDER BY e.pr, e.o, e.sort COLLATE "C", e.id), '[]'::jsonb) FROM e
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kanal_filter(p_filter text, p_kanaele integer[])
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s text[];
BEGIN
  -- Kanal-Filter: '' = alle Accounts, sonst Plattform-Schlüssel oder 'k<kanal_id>' (Stefan 18.10.2026) – seit Migration 152 (7d, Stefan 24.10.2026, 16:52)
  -- auch mehrere, durch Komma getrennt. Gelesen werden höchstens 20 Einträge; ungültige fallen weg. Ein einzelner gültiger Wert bleibt wie bisher.
  -- Bei mehreren: 'k<id>' fällt weg, wenn seine Plattform gewählt ist; sind alle Accounts einer Plattform mit mehreren Accounts einzeln gewählt,
  -- steht dafür die Plattform; ist alles gewählt, was die Account-Auswahl anbietet (talents_kanal_auswahl), gilt '' = Alle Accounts (Koordinator 25.10.2026).
  -- Reihenfolge fest: Plattform-Reihenfolge, je Plattform zuerst der Plattform-Schlüssel, dann die Accounts nach Nummer.
  s := ARRAY(SELECT DISTINCT x.s FROM (SELECT btrim(e) AS s FROM unnest((string_to_array(lower(coalesce(p_filter, '')), ','))[1:20]) AS e) x
             WHERE x.s <> '' AND EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.id = ANY (p_kanaele) AND (k.plattform = x.s OR 'k' || k.id = x.s)));
  IF cardinality(s) = 0 THEN RETURN ''; END IF;
  IF cardinality(s) = 1 THEN RETURN s[1]; END IF;
  s := ARRAY(SELECT x FROM unnest(s) x
             WHERE NOT EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.id = ANY (p_kanaele) AND 'k' || k.id = x AND k.plattform = ANY (s)));
  WITH k AS (SELECT k.id, k.plattform, k.extern_id IS NOT NULL AS konto FROM talent_kanaele k WHERE k.id = ANY (p_kanaele)),
    voll AS (SELECT k.plattform FROM k WHERE k.konto GROUP BY k.plattform HAVING count(*) > 1 AND bool_and('k' || k.id = ANY (s)))
  SELECT ARRAY(SELECT x FROM unnest(s) x WHERE NOT EXISTS (SELECT 1 FROM k JOIN voll USING (plattform) WHERE 'k' || k.id = x)) || ARRAY(SELECT voll.plattform FROM voll) INTO s;
  IF NOT EXISTS (SELECT 1 FROM (SELECT k.plattform FROM talent_kanaele k WHERE k.id = ANY (p_kanaele) GROUP BY k.plattform
                                HAVING count(*) FILTER (WHERE k.extern_id IS NOT NULL) <> 1) p WHERE NOT p.plattform = ANY (s))
     AND NOT EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.id = ANY (p_kanaele) AND k.extern_id IS NOT NULL AND NOT ('k' || k.id = ANY (s) OR k.plattform = ANY (s))) THEN
    RETURN '';
  END IF;
  RETURN (SELECT string_agg(y.x, ',' ORDER BY array_position(talents_plattformen(), y.p), y.x ~ '^k[0-9]+$', y.n)
          FROM (SELECT x, CASE WHEN x ~ '^k[0-9]+$' THEN (SELECT k.plattform FROM talent_kanaele k WHERE 'k' || k.id = x) ELSE x END AS p,
                       CASE WHEN x ~ '^k[0-9]+$' THEN substr(x, 2)::bigint ELSE 0 END AS n
                FROM unnest(s) x) y);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kanal_json(p_kanal_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('kanal_id', k.id, 'plattform', k.plattform, 'name', talents_plattform_name(k.plattform),
    'extern_name', nullif(ltrim(btrim(coalesce(k.extern_name, '')), '@'), ''),
    -- "@" nur bei Instagram, Threads, Pinterest (Stefan 18.10.2026)
    'text', CASE WHEN nullif(ltrim(btrim(coalesce(k.extern_name, '')), '@'), '') IS NOT NULL THEN talents_konto_text(k.plattform, k.extern_name) ELSE talents_plattform_name(k.plattform) END,
    'status', k.status, 'anmeldeweg', k.anmeldeweg, 'filter_kanal', 'k' || k.id,
    'status_text', CASE k.status WHEN 'verbunden' THEN 'verbunden' WHEN 'abgelaufen' THEN 'Verbindung abgelaufen'
                                 WHEN 'offen' THEN 'noch nicht verbunden' ELSE 'getrennt' END,
    'verbunden_am', talents_datum(k.verbunden_am), 'gueltig_bis', talents_datum(k.gueltig_bis),
    'stand', talents_zeit(k.letzter_abruf),
    'datenstand', (SELECT to_char(max(kt.tag), 'DD.MM.YYYY') FROM talent_kanal_tage kt WHERE kt.kanal_id = k.id),
    'profil_link', CASE WHEN k.plattform = 'instagram' AND ltrim(btrim(coalesce(k.extern_name, '')), '@') ~ '^[A-Za-z0-9._]{1,30}$'
                        THEN 'https://www.instagram.com/' || ltrim(btrim(k.extern_name), '@') || '/' END)
  FROM talent_kanaele k WHERE k.id = p_kanal_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kanal_passt(p_filter text, p_plattform text, p_kanal_id integer)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 152 (7d): p_filter darf eine Liste sein (talents_kanal_filter); ein einzelner Wert wie bisher
  SELECT coalesce(p_filter, '') = '' OR p_filter = p_plattform OR p_filter = 'k' || p_kanal_id
    OR (strpos(p_filter, ',') > 0 AND (p_plattform = ANY (string_to_array(p_filter, ',')) OR 'k' || p_kanal_id = ANY (string_to_array(p_filter, ','))))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kanal_text(p_plattform text, p_extern_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT coalesce(talents_plattform_name(p_plattform), p_plattform)
    -- "@" nur bei Instagram, Threads, Pinterest (Stefan 18.10.2026)
    || CASE WHEN nullif(ltrim(btrim(coalesce(p_extern_name, '')), '@'), '') IS NOT NULL THEN ' (' || talents_konto_text(p_plattform, p_extern_name) || ')' ELSE '' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kanal_zahlen(p_kanaele integer[], p_von date, p_bis date)
 RETURNS TABLE(reichweite numeric, aufrufe numeric, interaktionen numeric, tage integer, follower numeric, follower_zuwachs numeric)
 LANGUAGE sql
 STABLE
AS $function$
  WITH d AS (
    SELECT kt.tag, talents_zahl(kt.werte->'reach') AS r, talents_aufrufe(kt.werte) AS a, talents_interaktionen(kt.werte) AS i
    FROM talent_kanal_tage kt WHERE kt.kanal_id = ANY (p_kanaele) AND kt.tag BETWEEN p_von AND p_bis),
  f AS (
    SELECT (SELECT talents_zahl(kt.werte->'followers_count') FROM talent_kanal_tage kt
            WHERE kt.kanal_id = k.k AND kt.tag <= p_bis AND talents_zahl(kt.werte->'followers_count') IS NOT NULL ORDER BY kt.tag DESC LIMIT 1) AS ende,
           (SELECT talents_zahl(kt.werte->'followers_count') FROM talent_kanal_tage kt
            WHERE kt.kanal_id = k.k AND kt.tag < p_von AND talents_zahl(kt.werte->'followers_count') IS NOT NULL ORDER BY kt.tag DESC LIMIT 1) AS anfang
    FROM unnest(p_kanaele) AS k(k))
  SELECT (SELECT sum(d.r) FROM d), (SELECT sum(d.a) FROM d), (SELECT sum(d.i) FROM d),
    (SELECT count(DISTINCT d.tag) FROM d WHERE d.r IS NOT NULL OR d.a IS NOT NULL OR d.i IS NOT NULL)::integer,
    (SELECT sum(f.ende) FROM f), (SELECT sum(f.ende - f.anfang) FROM f WHERE f.ende IS NOT NULL AND f.anfang IS NOT NULL)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kennzahl(p_jetzt numeric, p_vorher numeric, p_tage_jetzt integer, p_tage_vorher integer, p_laenge integer)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT talents_wert(p_jetzt) || jsonb_build_object('vorher', talents_wert(p_vorher),
    'veraenderung', CASE WHEN coalesce(p_tage_jetzt, 0) > 0 AND coalesce(p_tage_vorher, 0) > 0 AND p_laenge > 0
                          AND p_tage_jetzt * 2 >= p_laenge AND p_tage_vorher * 2 >= p_laenge
                         THEN talents_veraenderung(p_jetzt / p_tage_jetzt, p_vorher / p_tage_vorher)
                         ELSE talents_veraenderung(NULL, NULL) END)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_abschluss(p_auftrag_id integer, p_fehler text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE talent_ki_auftraege SET status = CASE WHEN p_fehler IS NULL THEN 'fertig' ELSE 'fehler' END, fehler = p_fehler, erledigt_am = now()
  WHERE id = p_auftrag_id;
  IF p_fehler IS NOT NULL THEN
    PERFORM talents_ki_ziel_fehler(p_auftrag_id, p_fehler);
  END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_anfrage_sichtbar(p_user text, p_anfrage_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM talent_ki_anfragen q LEFT JOIN mail_rueckfragen m ON m.id = q.mail_id
    WHERE q.id = p_anfrage_id AND (q.erstellt_von = p_user OR talents_zugriff(p_user) = 'alle'
      OR (q.quelle = 'mail' AND m.postfach IS NOT NULL AND ally_postfach_zustaendig(p_user, m.postfach))))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_aufraeumen()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a integer; e integer; k integer;
BEGIN
  UPDATE talent_ki_anfragen SET anfrage = '(Inhalt der Mail nach 30 Tagen gelöscht)'
  WHERE quelle = 'mail' AND erstellt_am < now() - interval '30 days' AND anfrage <> '(Inhalt der Mail nach 30 Tagen gelöscht)';
  GET DIAGNOSTICS a = ROW_COUNT;
  UPDATE talent_mail_entwuerfe SET text = '(nach 30 Tagen gelöscht, der Entwurf liegt im Postfach)'
  WHERE status IN ('abgelegt', 'fehler') AND erstellt_am < now() - interval '30 days' AND text <> '(nach 30 Tagen gelöscht, der Entwurf liegt im Postfach)';
  GET DIAGNOSTICS e = ROW_COUNT;
  DELETE FROM talent_ki_auftraege WHERE status IN ('fertig', 'fehler') AND erstellt_am < now() - interval '90 days';
  GET DIAGNOSTICS k = ROW_COUNT;
  RETURN jsonb_build_object('anfragen_geleert', a, 'entwuerfe_geleert', e, 'auftraege_geloescht', k);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_auftrag_anlegen(p_art text, p_talent_id integer, p_ref_id integer, p_user text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  i integer;
BEGIN
  SELECT id INTO i FROM talent_ki_auftraege WHERE art = p_art AND ref_id IS NOT DISTINCT FROM p_ref_id
    AND talent_id IS NOT DISTINCT FROM p_talent_id AND status IN ('offen', 'laeuft') LIMIT 1;
  IF i IS NULL THEN
    INSERT INTO talent_ki_auftraege (art, talent_id, ref_id, erstellt_von) VALUES (p_art, p_talent_id, p_ref_id, p_user) RETURNING id INTO i;
  END IF;
  RETURN i;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_ausschluss(p_talent_id integer, p_marke text, p_branche text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN k.ebene = 'agentur' AND k.feld = 'marke' THEN 'Die Marke steht auf der Sperrliste der Agentur.'
              WHEN k.ebene = 'agentur' AND k.feld = 'wettbewerber' THEN 'Die Marke ist für die Agentur als Wettbewerber ausgeschlossen.'
              WHEN k.ebene = 'agentur' THEN 'Die Branche ist für die Agentur ausgeschlossen.'
              WHEN k.feld = 'marke' THEN 'Die Marke steht auf der Sperrliste des Talents.'
              WHEN k.feld = 'wettbewerber' THEN 'Exklusivität: Die Marke ist Wettbewerber eines aktuellen Partners des Talents.'
              ELSE 'Die Branche ist für dieses Talent ausgeschlossen.' END
  FROM talent_markensuche_kriterien k
  WHERE k.richtung = 'ausschliessen' AND (k.ebene = 'agentur' OR k.talent_id = p_talent_id)
    AND ((k.feld IN ('marke', 'wettbewerber') AND talents_ki_norm(p_marke) <> ''
          AND (talents_ki_norm(p_marke) = k.wert_norm OR (length(k.wert_norm) >= 4 AND strpos(talents_ki_norm(p_marke), k.wert_norm) > 0)))
      OR (k.feld = 'branche' AND talents_ki_norm(p_branche) <> ''
          AND (talents_ki_norm(p_branche) = k.wert_norm OR (length(k.wert_norm) >= 4 AND strpos(talents_ki_norm(p_branche), k.wert_norm) > 0))))
  ORDER BY k.ebene = 'agentur' DESC, k.feld, k.id
  LIMIT 1
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_e_anfrage(p_auftrag_id integer, j jsonb, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  q talent_ki_anfragen;
  kand integer[];
  e jsonb;
  tid integer;
  grund text;
  vor jsonb := '[]'::jsonb;
  aus jsonb := '[]'::jsonb;
  gesehen integer[] := '{}';
  v_marke text := talents_ki_kurz(j->>'marke', 120);
  v_branche text := talents_ki_kurz(j->>'branche', 120);
  m record;
  tx integer;
  person text;
  anh bigint[];
  txt text;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO q FROM talent_ki_anfragen WHERE id = a.ref_id;
  SELECT coalesce(array_agg((x->>'talent_id')::integer), '{}') INTO kand FROM jsonb_array_elements(talents_ki_kandidaten(q.id)) x;
  FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(j->'vorschlaege') = 'array' THEN j->'vorschlaege' ELSE '[]'::jsonb END) x LOOP
    tid := talents_ki_zahl(e->'talent_id')::integer;
    CONTINUE WHEN tid IS NULL OR NOT (tid = ANY (kand)) OR tid = ANY (gesehen);
    gesehen := gesehen || tid;
    grund := talents_ki_ausschluss(tid, v_marke, v_branche);
    IF grund IS NOT NULL THEN
      aus := aus || jsonb_build_array(jsonb_build_object('talent_id', tid, 'name', talent_anzeigename(tid), 'grund', grund));
    ELSIF jsonb_array_length(vor) < 5 THEN
      vor := vor || jsonb_build_array(jsonb_build_object('talent_id', tid, 'name', talent_anzeigename(tid),
        'passung', CASE WHEN e->>'passung' = 'gut' THEN 'gut' ELSE 'mittel' END,
        'passung_text', CASE WHEN e->>'passung' = 'gut' THEN 'passt gut' ELSE 'passt teilweise' END,
        'begruendung', talents_ki_kurz(e->>'begruendung', 400)));
    END IF;
  END LOOP;
  UPDATE talent_ki_anfragen SET status = 'fertig', marke = v_marke, branche = v_branche, vorschlaege = vor, ausgeschlossen = aus, fehler = NULL WHERE id = q.id;
  IF a.art = 'kooperation' THEN
    txt := talents_ki_kurz(replace(j->>'antwort_text', E'\r', ''), 8000);
    IF txt IS NOT NULL THEN
      INSERT INTO talent_ki_texte (art, anfrage_id, titel, eingabe, text, status, erstellt_von, hinweise)
      VALUES ('antwort_marke', q.id, coalesce(talents_ki_kurz(j->>'antwort_betreff', 200), 'Ihre Kooperationsanfrage'), q.anfrage, txt, 'entwurf', a.erstellt_von,
              CASE WHEN jsonb_array_length(talents_ki_zahlen_pruefen(txt, talents_ki_kandidaten(q.id))) > 0
                   THEN jsonb_build_array('Bitte prüfen, diese Zahlen stehen nicht in den gespeicherten Daten: '
                        || array_to_string(ARRAY(SELECT jsonb_array_elements_text(talents_ki_zahlen_pruefen(txt, talents_ki_kandidaten(q.id)))), ', '))
                   ELSE '[]'::jsonb END)
      RETURNING id INTO tx;
      UPDATE talent_ki_anfragen SET text_id = tx WHERE id = q.id;
      -- Antwort-Entwurf im Entwurfsordner nur, wenn eine zuständige Person des Postfachs Mail-Entwürfe eingeschaltet hat (wie ALLY 6)
      SELECT r.* INTO m FROM mail_rueckfragen r WHERE r.id = q.mail_id;
      IF m.id IS NOT NULL AND ally_postfach_aktiv(m.postfach) THEN
        SELECT np.matrix_user_id INTO person FROM ally_nutzer_postfaecher np JOIN ally_postfaecher p ON p.adresse = np.postfach
        WHERE np.postfach = m.postfach AND coalesce(ally_funktion_an(np.matrix_user_id, p.schalter), false)
        ORDER BY np.matrix_user_id LIMIT 1;
        IF person IS NOT NULL THEN
          SELECT coalesce(array_agg(d.id ORDER BY d.id), '{}') INTO anh FROM (
            SELECT DISTINCT ON (d.talent_id) d.id FROM talent_ablage_dateien d
            WHERE d.art = 'mediakit' AND d.talent_id IN (SELECT (x->>'talent_id')::integer FROM jsonb_array_elements(vor) x)
            ORDER BY d.talent_id, d.id DESC LIMIT 3) d;
          INSERT INTO talent_mail_entwuerfe (art, postfach, an, an_name, betreff, text, antwort_auf, anhaenge, erstellt_von)
          VALUES ('kooperation', m.postfach, coalesce(nullif(m.antwort_an, ''), m.absender), m.absender_name,
                  CASE WHEN m.betreff ~* '^(re|aw|antw)\s*:' THEN m.betreff ELSE 'Re: ' || coalesce(m.betreff, '') END, txt, m.id, anh, person);
        END IF;
      END IF;
    END IF;
  END IF;
  PERFORM talents_ki_abschluss(a.id);
  RETURN jsonb_build_object('ok', true, 'fertig', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_e_kampagnen(p_auftrag_id integer, j jsonb, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  k jsonb := talents_ki_kampagnen('kandidaten', jsonb_build_object('anzahl', 40));
  v jsonb := '[]'::jsonb;
  r jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('kampagne_id', (z->>'kampagne_id')::integer, 'beitrag_id', (z->>'beitrag_id')::bigint,
           'grund', talents_ki_kurz(z->>'grund', 200))), '[]'::jsonb) INTO v
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(j->'zuordnungen') = 'array' THEN j->'zuordnungen' ELSE '[]'::jsonb END) z
  WHERE talents_ki_zahl(z->'kampagne_id') IS NOT NULL AND talents_ki_zahl(z->'beitrag_id') IS NOT NULL
    AND EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(k->'kampagnen', '[]'::jsonb)) c, jsonb_array_elements(coalesce(c->'beitraege', '[]'::jsonb)) b
                WHERE (c->>'kampagne_id')::integer = talents_ki_zahl(z->'kampagne_id') AND (b->>'beitrag_id')::bigint = talents_ki_zahl(z->'beitrag_id'));
  IF jsonb_array_length(v) > 0 THEN
    r := talents_ki_kampagnen_speichern(jsonb_build_object('vorschlaege', v));
  END IF;
  PERFORM talents_ki_abschluss(p_auftrag_id);
  RETURN jsonb_build_object('ok', true, 'fertig', true, 'vorschlaege', jsonb_array_length(v), 'gespeichert', r);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_e_konzept(p_auftrag_id integer, j jsonb, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  k talent_konzepte;
  pl text[];
  e jsonb;
  kan jsonb := '[]'::jsonb;
  plan jsonb := '[]'::jsonb;
  f jsonb;
  vz date; bz date;
  verworfen integer := 0;
  zahl numeric;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO k FROM talent_konzepte WHERE id = a.ref_id;
  SELECT coalesce(array_agg(DISTINCT x.plattform), '{}') INTO pl FROM talent_kanaele x WHERE x.talent_id = k.talent_id AND x.status <> 'getrennt';
  IF talents_ki_kurz(j->>'positionierung', 1500) IS NULL THEN
    RAISE EXCEPTION 'Die KI hat keine Positionierung geliefert.';
  END IF;
  FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(j->'kanaele') = 'array' THEN j->'kanaele' ELSE '[]'::jsonb END) x LIMIT 8 LOOP
    IF jsonb_typeof(e) = 'object' AND e->>'plattform' = ANY (pl) THEN
      SELECT coalesce(jsonb_object_agg(fa, greatest(0, least(21, round(coalesce(talents_ki_zahl(e->'formate'->fa), 0))))), '{}'::jsonb) INTO f
      FROM unnest(ARRAY['reel', 'karussell', 'story', 'video', 'bild']) fa;
      kan := kan || jsonb_build_array(jsonb_build_object('plattform', e->>'plattform', 'plattform_name', talents_plattform_name(e->>'plattform'),
        'beitraege_pro_woche', greatest(0, least(21, round(coalesce(talents_ki_zahl(e->'beitraege_pro_woche'), 0), 1))), 'formate', f,
        'hinweis', talents_ki_kurz(e->>'hinweis', 200)));
    ELSE
      verworfen := verworfen + 1;
    END IF;
  END LOOP;
  FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(j->'themenplan') = 'array' THEN j->'themenplan' ELSE '[]'::jsonb END) x LIMIT 15 LOOP
    IF jsonb_typeof(e) = 'object' AND talents_ki_kurz(e->>'thema', 80) IS NOT NULL AND talents_ki_zahl(e->'woche') BETWEEN 1 AND 5 THEN
      plan := plan || jsonb_build_array(jsonb_build_object('woche', talents_ki_zahl(e->'woche')::integer, 'thema', talents_ki_kurz(e->>'thema', 80),
        'format', CASE WHEN e->>'format' IN ('reel', 'karussell', 'story', 'video', 'bild') THEN e->>'format' END,
        'format_name', CASE WHEN e->>'format' IN ('reel', 'karussell', 'story', 'video', 'bild') THEN talents_beitrag_art_name(e->>'format') END,
        'idee', talents_ki_kurz(e->>'idee', 300)));
    END IF;
  END LOOP;
  UPDATE talent_konzepte SET status = 'entwurf', positionierung = talents_ki_kurz(j->>'positionierung', 1500), zielgruppe = talents_ki_kurz(j->>'zielgruppe', 1000),
    kanaele = kan, themenplan = plan, begruendung = talents_ki_kurz(j->>'begruendung', 1500), fehler = NULL, geaendert_am = now()
  WHERE id = k.id;
  DELETE FROM talent_konzept_ziele WHERE konzept_id = k.id AND von_ki;
  FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(j->'ziele') = 'array' THEN j->'ziele' ELSE '[]'::jsonb END) x LIMIT 5 LOOP
    vz := CASE WHEN e->>'von' ~ '^\d{4}-\d{2}-\d{2}$' THEN (e->>'von')::date END;
    bz := CASE WHEN e->>'bis' ~ '^\d{4}-\d{2}-\d{2}$' THEN (e->>'bis')::date END;
    zahl := talents_ki_zahl(e->'zielwert');
    IF jsonb_typeof(e) = 'object' AND e->>'kennzahl' IN ('follower', 'follower_zuwachs', 'reichweite', 'aufrufe', 'interaktionen', 'interaktionsrate', 'beitraege')
       AND (e->'plattform' IS NULL OR jsonb_typeof(e->'plattform') = 'null' OR e->>'plattform' = ANY (pl))
       AND zahl IS NOT NULL AND zahl >= 0 AND (e->>'kennzahl' <> 'interaktionsrate' OR zahl <= 100)
       AND vz IS NOT NULL AND bz IS NOT NULL AND vz >= talents_heute() - 1 AND vz <= talents_heute() + 60 AND bz >= vz AND bz - vz <= 366 THEN
      INSERT INTO talent_konzept_ziele (konzept_id, talent_id, kennzahl, plattform, zielwert, von, bis, von_ki, erstellt_von)
      VALUES (k.id, k.talent_id, e->>'kennzahl', nullif(e->>'plattform', ''), round(zahl, 1), vz, bz, true, a.erstellt_von);
    ELSE
      verworfen := verworfen + 1;
    END IF;
  END LOOP;
  PERFORM talents_ki_abschluss(a.id);
  RETURN jsonb_build_object('ok', true, 'fertig', true, 'verworfen', verworfen);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_e_markensuche(p_auftrag_id integer, j jsonb, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  l talent_markensuche_laeufe;
  e jsonb;
  quellen text[];
  hosts text[];
  name text; norm text; url text; web text; kont text; weg text; br text;
  neu integer := 0; bek integer := 0; verw integer := 0;
  anzahl integer := least(12, greatest(1, coalesce(nullif(ally_einstellung('talents_markensuche_anzahl'), '')::integer, 10)));
  ws integer := coalesce(talents_ki_zahl(p_daten->'websuchen')::integer, 0);
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO l FROM talent_markensuche_laeufe WHERE id = a.ref_id;
  SELECT coalesce(array_agg(DISTINCT talents_ki_url_norm(x)), '{}'), coalesce(array_agg(DISTINCT talents_ki_host(x)), '{}') INTO quellen, hosts
  FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_daten->'quellen') = 'array' THEN p_daten->'quellen' ELSE '[]'::jsonb END) x
  WHERE x ~* '^https?://';
  FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(j->'marken') = 'array' THEN j->'marken' ELSE '[]'::jsonb END) x LIMIT 30 LOOP
    name := talents_ki_kurz(e->>'name', 120);
    norm := talents_ki_norm(name);
    url := talents_ki_kurz(e->>'quelle_url', 1000);
    br := talents_ki_kurz(e->>'branche', 120);
    -- Nur mit belegter Quelle aus den Suchergebnissen, nicht gesperrt, nicht doppelt
    IF name IS NULL OR norm = '' OR url IS NULL OR url !~* '^https?://' OR NOT (talents_ki_url_norm(url) = ANY (quellen))
       OR talents_ki_ausschluss(l.talent_id, name, br) IS NOT NULL
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(l.kriterien->'ausschliessen'->'marke', '[]'::jsonb) || coalesce(l.kriterien->'ausschliessen'->'wettbewerber', '[]'::jsonb)) s
                  WHERE talents_ki_norm(s) = norm OR (length(talents_ki_norm(s)) >= 4 AND strpos(norm, talents_ki_norm(s)) > 0))
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(l.kriterien->'ausschliessen'->'branche', '[]'::jsonb)) s
                  WHERE talents_ki_norm(br) <> '' AND length(talents_ki_norm(s)) >= 3 AND strpos(talents_ki_norm(br), talents_ki_norm(s)) > 0) THEN
      verw := verw + 1;
      CONTINUE;
    END IF;
    CONTINUE WHEN EXISTS (SELECT 1 FROM talent_markensuche_treffer t WHERE t.lauf_id = l.id AND t.marke_norm = norm);
    web := CASE WHEN e->>'website' ~* '^https?://[^[:space:]]+$' AND talents_ki_host(e->>'website') = ANY (hosts) THEN left(e->>'website', 500) END;
    weg := CASE WHEN e->>'kontaktweg' IN ('kooperationsprogramm', 'kontaktformular', 'presse', 'allgemeine_mail') THEN e->>'kontaktweg' ELSE 'unbekannt' END;
    kont := btrim(coalesce(e->>'kontakt', ''));
    -- Kontakt: nur Seiten-Adressen oder allgemeine Mailadressen (keine persönlichen Adressen)
    kont := CASE WHEN kont ~* '^https://[^[:space:]]{4,}$' AND length(kont) <= 500 THEN kont
                 WHEN lower(kont) ~ '^(info|kontakt|contact|hello|hallo|presse|press|pr|marketing|kooperation|kooperationen|cooperation|partner|partnerships|influencer|collab|collaborations|social|office|service|mail)@[a-z0-9.-]+\.[a-z]{2,}$' THEN lower(kont)
                 END;
    IF kont IS NULL AND weg <> 'unbekannt' THEN
      weg := 'unbekannt';
    END IF;
    IF EXISTS (SELECT 1 FROM talent_markensuche_treffer t WHERE t.talent_id = l.talent_id AND t.marke_norm = norm AND t.lauf_id <> l.id) THEN
      bek := bek + 1;
      INSERT INTO talent_markensuche_treffer (lauf_id, talent_id, marke, marke_norm, website, branche, begruendung, quelle_url, quelle_titel, kontaktweg, kontakt, bereits_bekannt)
      VALUES (l.id, l.talent_id, name, norm, web, br, talents_ki_kurz(e->>'begruendung', 400), left(url, 1000), talents_ki_kurz(e->>'quelle_titel', 200), weg, kont, true);
    ELSIF neu < anzahl THEN
      neu := neu + 1;
      INSERT INTO talent_markensuche_treffer (lauf_id, talent_id, marke, marke_norm, website, branche, begruendung, quelle_url, quelle_titel, kontaktweg, kontakt)
      VALUES (l.id, l.talent_id, name, norm, web, br, talents_ki_kurz(e->>'begruendung', 400), left(url, 1000), talents_ki_kurz(e->>'quelle_titel', 200), weg, kont);
    END IF;
  END LOOP;
  UPDATE talent_markensuche_laeufe SET status = 'fertig', anzahl_neu = neu, anzahl_bekannt = bek, anzahl_verworfen = verw, websuchen = ws,
    hinweis = CASE WHEN neu = 0 AND bek = 0 THEN 'Die Suche hat keine passenden Marken mit belegter Quelle gefunden.'
                   WHEN verw > 0 THEN verw || CASE WHEN verw = 1 THEN ' Treffer wurde' ELSE ' Treffer wurden' END || ' verworfen (ohne belegte Quelle oder ausgeschlossen).' END,
    fehler = NULL
  WHERE id = l.id;
  UPDATE talent_ki_auftraege SET websuchen = ws WHERE id = a.id;
  PERFORM talents_ki_abschluss(a.id);
  RETURN jsonb_build_object('ok', true, 'fertig', true, 'neu', neu, 'bekannt', bek, 'verworfen', verw);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_e_text(p_auftrag_id integer, j jsonb, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  t talent_ki_texte;
  txt text;
  erlaubt jsonb;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO t FROM talent_ki_texte WHERE id = a.ref_id;
  txt := talents_ki_kurz(replace(j->>'text', E'\r', ''), 8000);
  IF txt IS NULL THEN
    RAISE EXCEPTION 'Die KI hat keinen Text geliefert.';
  END IF;
  erlaubt := jsonb_build_array(CASE WHEN t.talent_id IS NOT NULL THEN talents_ki_profil(t.talent_id) END,
    CASE WHEN t.art = 'mediakit' THEN talents_wf_zahlen(t.talent_id, '', talents_heute() - 90, talents_heute() - 1)->'beste' END,
    CASE WHEN t.art = 'kampagne_zusammenfassung' THEN talents_ki_kampagnen('info', jsonb_build_object('kampagne_id', t.kampagne_id)) END,
    t.eingabe);
  UPDATE talent_ki_texte SET status = 'entwurf', text = txt,
    titel = coalesce(talents_ki_kurz(coalesce(j->>'titel', j->>'betreff'), 200), titel),
    hinweise = CASE WHEN jsonb_array_length(talents_ki_zahlen_pruefen(txt, erlaubt)) > 0
                    THEN jsonb_build_array('Bitte prüfen, diese Zahlen stehen nicht in den gespeicherten Daten: ' || array_to_string(ARRAY(SELECT jsonb_array_elements_text(talents_ki_zahlen_pruefen(txt, erlaubt))), ', '))
                    ELSE '[]'::jsonb END,
    fehler = NULL, geaendert_am = now()
  WHERE id = t.id;
  PERFORM talents_ki_abschluss(a.id);
  RETURN jsonb_build_object('ok', true, 'fertig', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_e_was_funktioniert(p_auftrag_id integer, j jsonb, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  w talent_ki_auswertungen;
  e jsonb;
  n integer := 0;
  v jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO w FROM talent_ki_auswertungen WHERE id = a.ref_id;
  IF a.schritt = 1 THEN
    FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(j->'themen') = 'array' THEN j->'themen' ELSE '[]'::jsonb END) x LOOP
      IF jsonb_typeof(e) = 'object' AND talents_ki_zahl(e->'id') IS NOT NULL AND talents_ki_kurz(e->>'thema', 60) IS NOT NULL THEN
        INSERT INTO talent_ki_themen (beitrag_id, thema)
        SELECT b.id, talents_ki_kurz(e->>'thema', 60) FROM talent_beitraege b
        WHERE b.id = talents_ki_zahl(e->'id')::bigint AND b.kanal_id = ANY (talents_ki_kanaele(w.talent_id, w.kanal))
          AND coalesce(btrim(b.text_inhalt), '') <> ''
        ON CONFLICT (beitrag_id) DO NOTHING;
        GET DIAGNOSTICS n = ROW_COUNT;
      END IF;
    END LOOP;
    UPDATE talent_ki_auftraege SET schritt = 2, status = 'offen' WHERE id = a.id;
    RETURN jsonb_build_object('ok', true, 'fertig', false, 'naechster_schritt', 2);
  END IF;
  FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(j->'vorschlaege') = 'array' THEN j->'vorschlaege' ELSE '[]'::jsonb END) x LIMIT 5 LOOP
    IF jsonb_typeof(e) = 'object' AND talents_ki_kurz(e->>'titel', 80) IS NOT NULL AND talents_ki_kurz(e->>'text', 400) IS NOT NULL THEN
      v := v || jsonb_build_array(jsonb_build_object('titel', talents_ki_kurz(e->>'titel', 80), 'text', talents_ki_kurz(e->>'text', 400),
        'grundlage', talents_ki_kurz(e->>'grundlage', 200),
        'bitte_pruefen', talents_ki_zahlen_pruefen(coalesce(e->>'text', '') || ' ' || coalesce(e->>'grundlage', ''), w.zahlen)));
    END IF;
  END LOOP;
  UPDATE talent_ki_auswertungen SET status = 'fertig', vorschlaege = v WHERE id = w.id;
  PERFORM talents_ki_abschluss(a.id);
  RETURN jsonb_build_object('ok', true, 'fertig', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_einstellungen_aktion(p_token text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  s jsonb := talents_ki_sitzung(p_token);
  u text;
BEGIN
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  IF NOT coalesce((s->>'admin')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diese Einstellungen dürfen nur Admins ändern.');
  END IF;
  u := s->>'u';
  -- Migration 180 (KI-Analyse): Tag und Uhrzeit nur, solange die Standard-Analyse wöchentlich läuft (sonst stellt man sie auf ihrer Seite ein)
  IF EXISTS (SELECT 1 FROM talents_briefings x WHERE x.standard AND x.geloescht_am IS NULL AND x.intervall = 'woche') AND coalesce(d->>'briefing_tag', '') !~ '^[1-7]$' THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte einen Wochentag für die Wochenanalyse wählen.');
  END IF;
  IF EXISTS (SELECT 1 FROM talents_briefings x WHERE x.standard AND x.geloescht_am IS NULL AND x.intervall = 'woche')
     AND coalesce(d->>'briefing_uhrzeit', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte die Uhrzeit als SS:MM angeben, z. B. 08:00.');
  END IF;
  IF coalesce(d->>'abweichung_prozent', '') !~ '^[0-9]{1,3}$' OR (d->>'abweichung_prozent')::integer NOT BETWEEN 10 AND 90 THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Die Schwelle für „deutlich abweichend“ muss zwischen 10 und 90 Prozent liegen.');
  END IF;
  IF coalesce(d->>'marken_anzahl', '') !~ '^[0-9]{1,2}$' OR (d->>'marken_anzahl')::integer NOT BETWEEN 1 AND 12 THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Treffer je Marken-Suche: 1 bis 12.');
  END IF;
  IF coalesce(d->>'marken_websuchen', '') !~ '^[0-9]{1,2}$' OR (d->>'marken_websuchen')::integer NOT BETWEEN 1 AND 10 THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Websuchen je Marken-Suche: 1 bis 10.');
  END IF;
  -- Migration 175 (B10a, Briefing): Tag und Uhrzeit stehen im Briefing für Manager/innen (fixiert wie bisher über den Trigger, Einstellung talents_ki)
  -- Migration 180: nur die Standard-Analyse; gibt es sie nicht mehr (gelöscht), legt diese Einstellung keine neue an (Stefan 30.10.2026)
  UPDATE talents_briefings b SET tag = CASE WHEN coalesce(d->>'briefing_tag', '') ~ '^[1-7]$' THEN (d->>'briefing_tag')::smallint END, uhrzeit = d->>'briefing_uhrzeit',
    geaendert_am = now(), geaendert_von = u
    WHERE b.standard AND b.geloescht_am IS NULL AND b.intervall = 'woche' AND coalesce(d->>'briefing_tag', '') ~ '^[1-7]$'
      AND coalesce(d->>'briefing_uhrzeit', '') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$';
  PERFORM ally_einstellung_setzen('talents_konzept_abweichung_prozent', ((d->>'abweichung_prozent')::integer)::text, u);
  PERFORM ally_einstellung_setzen('talents_markensuche_anzahl', ((d->>'marken_anzahl')::integer)::text, u);
  PERFORM ally_einstellung_setzen('talents_markensuche_websuchen', ((d->>'marken_websuchen')::integer)::text, u);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Einstellungen gespeichert.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_einstellungen_daten(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s jsonb := talents_ki_sitzung(p_token);
BEGIN
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  IF NOT coalesce((s->>'admin')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diese Einstellungen dürfen nur Admins ändern.');
  END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true,
    -- Migration 175 (B10a, Briefing): Tag und Uhrzeit aus dem Briefing für Manager/innen
    -- Migration 180 (KI-Analyse): Tag und Uhrzeit änderbar nur, wenn die Standard-Analyse wöchentlich läuft (briefing_da); sonst ihr echter Zeitplan in Worten
    -- (briefing_zeitplan, z. B. „Nur von Hand“; Prüfung M180 H1), mit ihrem Namen
    'briefing_da', EXISTS (SELECT 1 FROM talents_briefings x WHERE x.standard AND x.geloescht_am IS NULL AND x.intervall = 'woche'),
    'briefing_zeitplan', (SELECT talents_briefing_zeitplan_text(x.intervall, x.tag, x.uhrzeit) FROM talents_briefings x WHERE x.standard AND x.geloescht_am IS NULL),
    'briefing_name', (SELECT x.name FROM talents_briefings x WHERE x.standard AND x.geloescht_am IS NULL),
    'briefing_tag', coalesce((SELECT b.tag::text FROM talents_briefings b WHERE b.standard AND b.geloescht_am IS NULL AND b.tag <= 7), '1'),
    'briefing_uhrzeit', coalesce((SELECT b.uhrzeit FROM talents_briefings b WHERE b.standard AND b.geloescht_am IS NULL), '08:00'),
    'tage', '[{"wert": "1", "name": "Montag"}, {"wert": "2", "name": "Dienstag"}, {"wert": "3", "name": "Mittwoch"}, {"wert": "4", "name": "Donnerstag"},
              {"wert": "5", "name": "Freitag"}, {"wert": "6", "name": "Samstag"}, {"wert": "7", "name": "Sonntag"}]'::jsonb,
    'abweichung_prozent', coalesce(nullif(ally_einstellung('talents_konzept_abweichung_prozent'), ''), '25'),
    'marken_anzahl', coalesce(nullif(ally_einstellung('talents_markensuche_anzahl'), ''), '10'),
    'marken_websuchen', coalesce(nullif(ally_einstellung('talents_markensuche_websuchen'), ''), '5'),
    'websuche_hinweis', 'Jede Websuche kostet etwa 1 Cent zusätzlich zur KI-Nutzung und zählt zum KI-Budget.',
    'kriterien_agentur', (SELECT coalesce(jsonb_agg(talents_markensuche_kriterium_json(k.id) ORDER BY k.richtung, k.feld, k.wert_norm), '[]'::jsonb)
                          FROM talent_markensuche_kriterien k WHERE k.ebene = 'agentur'));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_ergebnis(p_auftrag_id integer, p_schritt integer, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  j jsonb;
  r jsonb;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id FOR UPDATE;
  IF NOT FOUND OR a.status <> 'laeuft' OR a.schritt <> p_schritt THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Der Auftrag ist nicht mehr offen.');
  END IF;
  j := talents_ki_json(p_daten->>'text');
  IF j IS NULL THEN
    RETURN talents_ki_fehler(a.id, 'Die Antwort der KI war kein gültiges JSON.') || jsonb_build_object('fertig', false);
  END IF;
  BEGIN
    r := CASE a.art
      WHEN 'was_funktioniert' THEN talents_ki_e_was_funktioniert(a.id, j, p_daten)
      WHEN 'konzept' THEN talents_ki_e_konzept(a.id, j, p_daten)
      WHEN 'konzept_ueberarbeiten' THEN talents_ki_e_konzept(a.id, j, p_daten)
      WHEN 'text' THEN talents_ki_e_text(a.id, j, p_daten)
      WHEN 'talent_anfrage' THEN talents_ki_e_anfrage(a.id, j, p_daten)
      WHEN 'kooperation' THEN talents_ki_e_anfrage(a.id, j, p_daten)
      WHEN 'markensuche' THEN talents_ki_e_markensuche(a.id, j, p_daten)
      WHEN 'kampagnen_zuordnung' THEN talents_ki_e_kampagnen(a.id, j, p_daten)
    END;
  EXCEPTION WHEN others THEN
    RETURN talents_ki_fehler(a.id, 'Die Antwort der KI war unvollständig: ' || left(SQLERRM, 200)) || jsonb_build_object('fertig', false);
  END;
  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_export_daten(p_ids integer[], p_teil text, p_offset integer, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  r jsonb;
BEGIN
  IF p_teil = 'konzept_angaben' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(a.talent_id, a.themen, a.ziele, a.zielgruppe, a.nogos, a.stunden_pro_woche, talents_export_zeit(a.geaendert_am)) AS z,
        row_number() OVER (ORDER BY a.talent_id) AS o, count(*) OVER () AS n
      FROM talent_konzept_angaben a WHERE a.talent_id = ANY (p_ids) ORDER BY a.talent_id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'konzepte' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(c.id, c.talent_id, c.status, c.art, c.positionierung, c.zielgruppe, c.kanaele::text, c.themenplan::text, c.begruendung,
        talents_export_zeit(c.erstellt_am), talents_export_zeit(c.aktiv_seit)) AS z, row_number() OVER (ORDER BY c.id) AS o, count(*) OVER () AS n
      FROM talent_konzepte c WHERE c.talent_id = ANY (p_ids) ORDER BY c.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'konzept_ziele' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(z.id, z.konzept_id, z.talent_id, z.kennzahl, z.plattform, z.zielwert, to_char(z.von, 'YYYY-MM-DD'), to_char(z.bis, 'YYYY-MM-DD'),
        CASE WHEN z.von_ki THEN 'ja' ELSE 'nein' END) AS z, row_number() OVER (ORDER BY z.id) AS o, count(*) OVER () AS n
      FROM talent_konzept_ziele z WHERE z.talent_id = ANY (p_ids) ORDER BY z.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'marken_suchen' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(t.id, t.lauf_id, t.talent_id, talents_export_zeit(l.erstellt_am), t.marke, t.website, t.branche, t.begruendung, t.quelle_url, t.kontaktweg, t.kontakt,
        CASE WHEN t.bereits_bekannt THEN 'ja' ELSE 'nein' END, t.bewertung, t.bewertung_grund) AS z, row_number() OVER (ORDER BY t.id) AS o, count(*) OVER () AS n
      FROM talent_markensuche_treffer t JOIN talent_markensuche_laeufe l ON l.id = t.lauf_id WHERE t.talent_id = ANY (p_ids) ORDER BY t.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'marken_kriterien' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(k.id, k.ebene, k.talent_id, k.richtung, k.feld, k.wert, k.grund, talents_export_zeit(k.erstellt_am)) AS z,
        row_number() OVER (ORDER BY k.id) AS o, count(*) OVER () AS n
      FROM talent_markensuche_kriterien k WHERE k.talent_id = ANY (p_ids) OR (k.ebene = 'agentur' AND cardinality(p_ids) > 1) ORDER BY k.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'texte' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(x.id, x.talent_id, x.kampagne_id, x.art, x.titel, x.text, x.status, talents_export_zeit(x.geaendert_am)) AS z,
        row_number() OVER (ORDER BY x.id) AS o, count(*) OVER () AS n
      FROM talent_ki_texte x WHERE x.talent_id = ANY (p_ids) ORDER BY x.id OFFSET p_offset LIMIT p_limit) q;
  ELSE
    RAISE EXCEPTION 'talents_ki_export_daten: unbekannter Teil %', p_teil;
  END IF;
  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_export_teile()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT jsonb_agg(jsonb_build_object('teil', x.t, 'datei', x.t || '.csv', 'titel', x.ti,
    'spalten', (SELECT jsonb_agg(jsonb_build_object('name', split_part(s, '|', 1), 'beschreibung', split_part(s, '|', 2)) ORDER BY o) FROM unnest(x.sp) WITH ORDINALITY AS u(s, o))) ORDER BY x.o)
  FROM (VALUES
    (11, 'konzept_angaben', 'Angaben für das Gesamtkonzept', ARRAY['talent_id|Talent', 'themen|Themen', 'ziele|Ziele (Text)', 'zielgruppe|Zielgruppe', 'nogos|No-Gos',
      'stunden_pro_woche|Zeit pro Woche in Stunden', 'geaendert_am|zuletzt geändert am']),
    (12, 'konzepte', 'Gesamtkonzepte (Entwürfe, aktiv, abgelegt)', ARRAY['konzept_id|Nummer des Konzepts', 'talent_id|Talent', 'status|entwurf, aktiv, abgelegt oder fehler',
      'art|neu oder ueberarbeitung (Vorschlag bei Abweichung)', 'positionierung|Positionierung', 'zielgruppe|Zielgruppe', 'kanaele_json|Kanäle mit Beiträgen pro Woche und Formaten (JSON)',
      'themenplan_json|Themenplan (JSON)', 'begruendung|Begründung', 'erstellt_am|erstellt am', 'aktiv_seit|aktiv seit']),
    (13, 'konzept_ziele', 'Ziele der Konzepte (Soll)', ARRAY['ziel_id|Nummer des Ziels', 'konzept_id|Konzept', 'talent_id|Talent', 'kennzahl|Kennzahl', 'plattform|Plattform (leer = alle)',
      'zielwert|Zielwert', 'von|Beginn', 'bis|Ende', 'von_ki|ja = Vorschlag der KI']),
    (14, 'marken_suchen', 'Marken-Suchen und Treffer mit Bewertung', ARRAY['treffer_id|Nummer des Treffers', 'lauf_id|Suche', 'talent_id|Talent', 'gesucht_am|Suche am',
      'marke|Marke', 'website|Website', 'branche|Branche', 'begruendung|Begründung', 'quelle|Quelle (Adresse)', 'kontaktweg|Kontaktweg', 'kontakt|Kontakt',
      'bereits_bekannt|ja = schon früher vorgeschlagen', 'bewertung|passt oder passt_nicht', 'bewertung_grund|Grund']),
    (15, 'marken_kriterien', 'Kriterien der Marken-Suche (Agentur und Talent, Sperrliste = Ausschließen › Marke)', ARRAY['kriterium_id|Nummer', 'ebene|agentur oder talent',
      'talent_id|Talent (leer = Agentur)', 'richtung|einschliessen oder ausschliessen', 'feld|Kriterium', 'wert|Wert', 'grund|Grund', 'erstellt_am|erstellt am']),
    (16, 'texte', 'Texte als Entwurf (Mediakit, Kampagnen-Zusammenfassung, Antwort an Marke)', ARRAY['text_id|Nummer', 'talent_id|Talent', 'kampagne_id|Kampagne', 'art|Art',
      'titel|Titel', 'text|Text', 'status|Status', 'geaendert_am|zuletzt geändert am'])
  ) AS x(o, t, ti, sp)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_fehler(p_auftrag_id integer, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v integer;
BEGIN
  UPDATE talent_ki_auftraege SET versuche = versuche + 1, status = 'offen', fehler = left(talents_text_sauber(p_text), 300)
  WHERE id = p_auftrag_id AND status IN ('laeuft', 'offen') RETURNING versuche INTO v;
  IF v IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Der Auftrag ist nicht mehr offen.');
  END IF;
  IF v >= 3 THEN
    PERFORM talents_ki_abschluss(p_auftrag_id, 'Die KI-Funktion ist dreimal gescheitert. Bitte später erneut starten.');
    RETURN jsonb_build_object('ok', true, 'endgueltig', true);
  END IF;
  RETURN jsonb_build_object('ok', true, 'endgueltig', false, 'versuche', v);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_host(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT regexp_replace(lower(substring(btrim(coalesce(p, '')) FROM '^https?://([^/:?#]+)')), '^www\.', '')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_json(p text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  a integer := strpos(coalesce(p, ''), '{');
  t text := coalesce(p, '');
  e integer;
  j jsonb;
BEGIN
  IF a = 0 THEN
    RETURN NULL;
  END IF;
  e := length(t) - strpos(reverse(t), '}') + 1;
  IF strpos(reverse(t), '}') = 0 OR e <= a THEN
    RETURN NULL;
  END IF;
  j := substr(t, a, e - a + 1)::jsonb;
  RETURN CASE WHEN jsonb_typeof(j) = 'object' THEN j END;
EXCEPTION WHEN others THEN
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kampagne_info(p_kampagne_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((
    SELECT talents_kampagne_kurz(k.id, NULL) || jsonb_build_object('ok', true,
      'talents', (SELECT coalesce(jsonb_agg(jsonb_build_object('talent_id', kt.talent_id, 'name', talent_anzeigename(kt.talent_id)) ORDER BY lower(talent_anzeigename(kt.talent_id)) COLLATE "C"), '[]'::jsonb)
                  FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id),
      'ergebnis', (SELECT jsonb_build_object('beitraege', count(*), 'reichweite', sum(talents_zahl(w.w->'reach')), 'aufrufe', sum(talents_aufrufe(w.w)),
                     'interaktionen', sum(talents_interaktionen(w.w)),
                     'je_talent', (SELECT coalesce(jsonb_agg(jsonb_build_object('name', talent_anzeigename(y.talent_id), 'beitraege', y.n, 'reichweite', y.r, 'aufrufe', y.a, 'interaktionen', y.i)
                                     ORDER BY lower(talent_anzeigename(y.talent_id)) COLLATE "C"), '[]'::jsonb)
                                   FROM (SELECT c2.talent_id, count(*) n, sum(talents_zahl(talents_beitrag_werte_bis(kb2.beitrag_id, k.bis)->'reach')) r,
                                                sum(talents_aufrufe(talents_beitrag_werte_bis(kb2.beitrag_id, k.bis))) a, sum(talents_interaktionen(talents_beitrag_werte_bis(kb2.beitrag_id, k.bis))) i
                                         FROM talent_kampagne_beitraege kb2 JOIN talent_beitraege b2 ON b2.id = kb2.beitrag_id JOIN talent_kanaele c2 ON c2.id = b2.kanal_id
                                         WHERE kb2.kampagne_id = k.id AND kb2.status = 'bestaetigt' GROUP BY c2.talent_id) y))
                   FROM talent_kampagne_beitraege kb CROSS JOIN LATERAL (SELECT talents_beitrag_werte_bis(kb.beitrag_id, k.bis) AS w) w
                   WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt'))
    FROM talent_kampagnen k WHERE k.id = p_kampagne_id),
    jsonb_build_object('ok', false, 'fehler', 'Diese Kampagne gibt es nicht.'))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kampagne_sichtbar(p_user text, p_kampagne_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM talent_kampagnen k WHERE k.id = p_kampagne_id
    AND (talents_zugriff(p_user) = 'alle' OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND talent_sichtbar(p_user, kt.talent_id))))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kampagnen(p_funktion text, p_arg jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
  RETURN CASE p_funktion
    WHEN 'kandidaten' THEN talents_ki_kampagnen_kandidaten(coalesce((p_arg->>'anzahl')::integer, 40))
    WHEN 'info' THEN talents_ki_kampagne_info(CASE WHEN p_arg->>'kampagne_id' ~ '^[0-9]{1,9}$' THEN (p_arg->>'kampagne_id')::integer END)
    WHEN 'fuer_mail' THEN jsonb_build_object('kampagne_ids', to_jsonb(talents_ki_kampagnen_fuer_mail(p_arg->>'absender', p_arg->>'betreff', coalesce((p_arg->>'datum')::timestamptz, now()))))
    WHEN 'des_talents' THEN talents_ki_kampagnen_des_talents((p_arg->>'talent_id')::integer, coalesce((p_arg->>'nur_laufend')::boolean, false))
  END;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kampagnen_des_talents(p_talent_id integer, p_nur_laufend boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('kampagnen', coalesce(jsonb_agg(x.o ORDER BY x.bis DESC, x.id DESC), '[]'::jsonb))
  FROM (SELECT k.id, k.bis, jsonb_build_object('kampagne_id', k.id, 'marke', k.marke, 'name', k.name, 'titel', k.marke || ' – ' || k.name,
          'zeitraum_text', to_char(k.von, 'DD.MM.YYYY') || ' bis ' || to_char(k.bis, 'DD.MM.YYYY'), 'status', talents_kampagne_status(k.von, k.bis),
          'beitraege', (SELECT count(*) FROM talent_kampagne_beitraege kb JOIN talent_beitraege b ON b.id = kb.beitrag_id JOIN talent_kanaele c ON c.id = b.kanal_id
                        WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c.talent_id = p_talent_id)) AS o
        FROM talent_kampagnen k JOIN talent_kampagne_talents kt ON kt.kampagne_id = k.id AND kt.talent_id = p_talent_id
        WHERE NOT coalesce(p_nur_laufend, false) OR talents_kampagne_status(k.von, k.bis) = 'laufend'
        ORDER BY k.bis DESC, k.id DESC LIMIT 10) x
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kampagnen_fuer_mail(p_absender text, p_betreff text, p_datum timestamp with time zone)
 RETURNS integer[]
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(array_agg(k.id ORDER BY k.id), '{}') FROM talent_kampagnen k
  WHERE (p_datum AT TIME ZONE 'Europe/Berlin')::date BETWEEN k.von - 14 AND k.bis + 30
    AND length(talents_ki_norm(k.marke)) >= 3
    AND (talents_ki_norm(split_part(split_part(lower(coalesce(p_absender, '')), '@', 2), '.', greatest(1, array_length(string_to_array(split_part(lower(coalesce(p_absender, '')), '@', 2), '.'), 1) - 1)))
           = talents_ki_norm(k.marke)
         OR lower(coalesce(p_betreff, '')) ~ ('(^|[^[:alnum:]])' || talents_regex(lower(k.marke)) || '($|[^[:alnum:]])'))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kampagnen_kandidaten(p_anzahl integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH b AS (
    SELECT k.id AS kid, x.id AS beitrag_id, c.talent_id, coalesce(x.erstellt, x.erfasst_am) AS d, x.text_inhalt
    FROM talent_kampagnen k
    JOIN talent_kampagne_talents kt ON kt.kampagne_id = k.id
    JOIN talents t ON t.id = kt.talent_id AND t.status = 'aktiv'
    JOIN talent_kanaele c ON c.talent_id = kt.talent_id
    JOIN talent_beitraege x ON x.kanal_id = c.id
    WHERE k.von <= talents_heute() AND k.bis >= talents_heute() - 3
      AND (coalesce(x.erstellt, x.erfasst_am) AT TIME ZONE 'Europe/Berlin')::date BETWEEN k.von AND k.bis
      AND coalesce(btrim(x.text_inhalt), '') <> '' AND talents_beitrag_art(x.art, x.produkt_art) <> 'story'
      AND NOT EXISTS (SELECT 1 FROM talent_kampagne_beitraege kb WHERE kb.kampagne_id = k.id AND kb.beitrag_id = x.id)
    ORDER BY k.id, x.id
    LIMIT greatest(1, least(coalesce(p_anzahl, 40), 100)))
  SELECT jsonb_build_object('kampagnen', coalesce(jsonb_agg(jsonb_build_object('kampagne_id', k.id, 'name', k.name, 'marke', k.marke,
      'merkmale', (SELECT jsonb_agg(m) FROM (SELECT '@' || x AS m FROM unnest(k.marken_konten) x UNION ALL SELECT '#' || x FROM unnest(k.hashtags) x
                                             UNION ALL SELECT x FROM unnest(k.schlagwoerter) x) mm),
      'von', to_char(k.von, 'YYYY-MM-DD'), 'bis', to_char(k.bis, 'YYYY-MM-DD'),
      'beitraege', (SELECT jsonb_agg(jsonb_build_object('beitrag_id', b.beitrag_id, 'talent_id', b.talent_id, 'datum', to_char(b.d AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD'),
                      'text', talents_ki_kurz(b.text_inhalt, 400)) ORDER BY b.beitrag_id) FROM b WHERE b.kid = k.id)) ORDER BY k.id), '[]'::jsonb))
  FROM talent_kampagnen k WHERE k.id IN (SELECT DISTINCT kid FROM b)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kampagnen_speichern(p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n integer;
BEGIN
  INSERT INTO talent_kampagne_beitraege (kampagne_id, beitrag_id, status, quelle, grund)
  SELECT k.id, x.id, 'vorschlag', 'automatisch', left('KI: ' || coalesce(talents_ki_kurz(v->>'grund', 200), 'erkennt die Marke im Beitragstext'), 300)
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_daten->'vorschlaege') = 'array' THEN p_daten->'vorschlaege' ELSE '[]'::jsonb END) v
  JOIN talent_kampagnen k ON k.id = (v->>'kampagne_id')::integer
  JOIN talent_beitraege x ON x.id = (v->>'beitrag_id')::bigint
  JOIN talent_kanaele c ON c.id = x.kanal_id
  WHERE (v->>'kampagne_id') ~ '^[0-9]{1,9}$' AND (v->>'beitrag_id') ~ '^[0-9]{1,15}$'
    AND EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = c.talent_id)
    AND (coalesce(x.erstellt, x.erfasst_am) AT TIME ZONE 'Europe/Berlin')::date BETWEEN k.von AND k.bis
  ON CONFLICT (kampagne_id, beitrag_id) DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'gespeichert', n);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kanaele(p_talent_id integer, p_kanal text DEFAULT ''::text)
 RETURNS integer[]
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(array_agg(k.id ORDER BY k.id), '{}') FROM talent_kanaele k
  WHERE k.talent_id = p_talent_id AND k.extern_id IS NOT NULL AND talents_kanal_passt(coalesce(p_kanal, ''), k.plattform, k.id)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kandidaten(p_anfrage_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  q talent_ki_anfragen;
  r jsonb;
BEGIN
  SELECT * INTO q FROM talent_ki_anfragen WHERE id = p_anfrage_id;
  SELECT coalesce(jsonb_agg(x.o ORDER BY x.f DESC NULLS LAST, x.id), '[]'::jsonb) INTO r
  FROM (SELECT t.id, p.p - 'kennzahlen_28_tage' || jsonb_build_object(
               'kennzahlen_28_tage', (SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('plattform', e->>'plattform', 'follower', e->'follower',
                    'reichweite', e->'reichweite', 'interaktionsrate_prozent', e->'interaktionsrate_prozent', 'beitraege_pro_woche', e->'beitraege_pro_woche'))), '[]'::jsonb)
                    FROM jsonb_array_elements(p.p->'kennzahlen_28_tage') e),
               'ausschluesse', (SELECT coalesce(jsonb_agg(talents_markensuche_feld_name(k.feld) || ': ' || k.wert ORDER BY k.id), '[]'::jsonb)
                                FROM talent_markensuche_kriterien k WHERE k.talent_id = t.id AND k.richtung = 'ausschliessen'),
               'fruehere_kampagnen', talents_ki_kampagnen('des_talents', jsonb_build_object('talent_id', t.id))->'kampagnen') AS o,
               (SELECT sum(talents_zahl(e->'follower')) FROM jsonb_array_elements(p.p->'kennzahlen_28_tage') e) AS f
        FROM talents t CROSS JOIN LATERAL (SELECT talents_ki_profil(t.id) AS p) p
        WHERE t.status = 'aktiv' AND NOT t.testdaten /* Testdaten (Migration 79) */ AND NOT (t.id = ANY (q.talent_ids))
          AND (q.quelle = 'mail' OR talent_sichtbar(q.erstellt_von, t.id))
        ORDER BY 3 DESC NULLS LAST, t.id LIMIT 40) x;
  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kennzahlen(p_talent_id integer, p_tage integer DEFAULT 28)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'plattform', p.plattform, 'plattform_name', talents_plattform_name(p.plattform),
      'konten', p.konten,
      'follower', z.follower, 'follower_zuwachs', z.follower_zuwachs,
      'reichweite', z.reichweite, 'aufrufe', z.aufrufe, 'interaktionen', z.interaktionen,
      'interaktionsrate_prozent', CASE WHEN p.plattform = 'instagram' AND z.reichweite > 0 AND z.interaktionen IS NOT NULL
                                       THEN round(z.interaktionen / z.reichweite * 100, 1) END,
      'tage_mit_zahlen', z.tage,
      'beitraege', b.anzahl, 'beitraege_pro_woche', round(b.anzahl::numeric * 7 / p_tage, 1), 'formate', b.formate)
      ORDER BY array_position(talents_plattformen(), p.plattform)), '[]'::jsonb)
  FROM (SELECT k.plattform, array_agg(k.id) AS ids,
               jsonb_agg('@' || ltrim(k.extern_name, '@') ORDER BY k.id) FILTER (WHERE k.extern_name IS NOT NULL) AS konten
        FROM talent_kanaele k WHERE k.talent_id = p_talent_id AND k.extern_id IS NOT NULL AND k.status <> 'getrennt'
        GROUP BY k.plattform) p
  CROSS JOIN LATERAL talents_zahlen(p.ids, talents_heute() - p_tage, talents_heute() - 1, ARRAY[p_talent_id], p.plattform, true) z
  CROSS JOIN LATERAL (
    SELECT count(*)::integer AS anzahl,
           coalesce(jsonb_object_agg(x.art, x.n), '{}'::jsonb) AS formate
    FROM (SELECT talents_beitrag_art(b.art, b.produkt_art) AS art, count(*) AS n FROM talent_beitraege b
          WHERE b.kanal_id = ANY (p.ids) AND coalesce(b.erstellt, b.erfasst_am) >= (talents_heute() - p_tage)::timestamp AT TIME ZONE 'Europe/Berlin'
            AND coalesce(b.erstellt, b.erfasst_am) < talents_heute()::timestamp AT TIME ZONE 'Europe/Berlin'
          GROUP BY 1) x) b
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_kurz(p text, p_laenge integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT nullif(left(btrim(regexp_replace(regexp_replace(coalesce(p, ''), '[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]', '', 'g'),
         '[\U0001F000-\U0001FAFF☀-➿️‍]', '', 'g')), p_laenge), '')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_laeuft_text()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT 'Wird erstellt. Das dauert meist 1 bis 3 Minuten. Bitte die Seite danach neu laden.'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_norm(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT regexp_replace(
           regexp_replace(lower(btrim(coalesce(p, ''))), '\m(gmbh|ag|kg|co|se|ug|inc|ltd|llc|e\.?\s?k|ohg|gbr|sarl|sa|bv|nv)\M\.?', ' ', 'g'),
           '[^[:alnum:]]+', '', 'g')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_p_anfrage(p_auftrag_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  q talent_ki_anfragen;
  k jsonb;
  mk jsonb;
  koop boolean;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO q FROM talent_ki_anfragen WHERE id = a.ref_id;
  IF NOT FOUND THEN
    PERFORM talents_ki_abschluss(a.id, 'Die Anfrage gibt es nicht mehr.');
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  koop := a.art = 'kooperation';
  k := talents_ki_kandidaten(q.id);
  IF jsonb_array_length(k) = 0 THEN
    UPDATE talent_ki_anfragen SET status = 'fertig', vorschlaege = '[]'::jsonb, fehler = 'Es gibt keine aktiven Talents, die in Frage kommen.' WHERE id = q.id;
    PERFORM talents_ki_abschluss(a.id);
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  SELECT coalesce(jsonb_agg(DISTINCT d.talent_id), '[]'::jsonb) INTO mk FROM talent_ablage_dateien d WHERE d.art = 'mediakit' AND d.talent_id IS NOT NULL;
  RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'anspruchsvoll', 'max_tokens', CASE WHEN koop THEN 3000 ELSE 2000 END, 'websuche', false,
    'system', 'Du schlägst einer Agentur passende Talents für eine Markenanfrage vor. ' || talents_ki_regeln()
      || E'\n\nAufgabe:\n- Lies aus der ANFRAGE die Marke und die Branche (wenn nicht genannt: null).\n'
      || E'- Wähle höchstens 5 passende Talents aus TALENTS (nur deren talent_id) mit passung "gut" oder "mittel" und einer begruendung in 1 bis 2 Sätzen (Zielgruppe, Themen, frühere Kampagnen).\n'
      || E'- Schlage kein Talent vor, dessen Ausschlüsse oder No-Gos die Marke oder Branche betreffen.\n'
      || CASE WHEN koop THEN E'- Schreibe zusätzlich den Entwurf einer Antwort an die Marke (antwort_betreff, antwort_text): Dank für die Anfrage, kurze Vorstellung der vorgeschlagenen Talents mit Kennzahlen nur aus den DATEN (immer mit "letzte 28 Tage"), '
                         || E'Hinweis auf das Mediakit im Anhang nur bei Talents aus MEDIAKITS, Fragen nach Zeitraum, Umfang und Budget. Beginne mit einer Anrede (im Zweifel siezen), ohne Grußformel und ohne Namen am Ende.\n'
                         || 'Format: {"marke":"…","branche":"…","vorschlaege":[{"talent_id":1,"passung":"gut","begruendung":"…"}],"antwort_betreff":"…","antwort_text":"…"}'
              ELSE 'Format: {"marke":"…","branche":"…","vorschlaege":[{"talent_id":1,"passung":"gut","begruendung":"…"}]}' END,
    'nachricht', 'ANFRAGE:' || E'\n' || talents_ki_kurz(q.anfrage, 8000) || E'\n\nTALENTS (DATEN): ' || k::text
      || CASE WHEN koop THEN E'\n\nMEDIAKITS (talent_id mit Mediakit-PDF): ' || mk::text ELSE '' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_p_kampagnen(p_auftrag_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  k jsonb;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  k := talents_ki_kampagnen('kandidaten', jsonb_build_object('anzahl', 40));
  IF jsonb_array_length(coalesce(k->'kampagnen', '[]'::jsonb)) = 0 THEN
    PERFORM talents_ki_abschluss(a.id);
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'einfach', 'max_tokens', 2000, 'websuche', false,
    'system', 'Du prüfst für eine Agentur, welche Beiträge zu einer laufenden Kampagne gehören. ' || talents_ki_regeln()
      || E'\n\nAufgabe: Ein Beitrag gehört zu einer Kampagne, wenn sein Text die Marke nennt, markiert (@) oder einen der Hashtags oder Merkmale der Kampagne enthält, auch abgewandelt (z. B. Marke ohne @, anderer Schreibweise) '
      || E'und das Datum im Zeitraum liegt. Im Zweifel nicht zuordnen. Ordne nur Paare aus den DATEN zu.\n'
      || 'Format: {"zuordnungen":[{"kampagne_id":1,"beitrag_id":2,"grund":"nennt @marke"}]}',
    'nachricht', 'DATEN: ' || k::text);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_p_konzept(p_auftrag_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  k talent_konzepte;
  akt talent_konzepte;
  plattformen jsonb;
  ziele jsonb;
  uebers boolean;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO k FROM talent_konzepte WHERE id = a.ref_id;
  IF NOT FOUND THEN
    PERFORM talents_ki_abschluss(a.id, 'Das Konzept gibt es nicht mehr.');
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  uebers := k.art = 'ueberarbeitung';
  SELECT coalesce(jsonb_agg(DISTINCT x.plattform), '[]'::jsonb) INTO plattformen FROM talent_kanaele x WHERE x.talent_id = k.talent_id AND x.status <> 'getrennt';
  SELECT * INTO akt FROM talent_konzepte WHERE talent_id = k.talent_id AND status = 'aktiv';
  IF akt.id IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(talents_ziel_stand(z.id) - 'ziel_id' - 'von_ki' ORDER BY z.id), '[]'::jsonb) INTO ziele FROM talent_konzept_ziele z WHERE z.konzept_id = akt.id;
  END IF;
  IF uebers AND akt.id IS NULL THEN
    PERFORM talents_ki_abschluss(a.id, 'Es gibt kein aktives Konzept zum Überarbeiten.');
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'anspruchsvoll', 'max_tokens', 4000, 'websuche', false,
    'system', 'Du bist in der Social-Media-Beratung einer Agentur tätig und arbeitest für ein Talent ein Gesamtkonzept aus. ' || talents_ki_regeln()
      || E'\n\nInhalt:\n- positionierung: Positionierung in 2 bis 4 Sätzen.\n'
      || E'- zielgruppe: Zielgruppe in 1 bis 3 Sätzen (aus ANGABEN und ZIELGRUPPE; nenne nur Anteile, die in den DATEN stehen).\n'
      || E'- kanaele: je Plattform aus PLATTFORMEN die Beiträge pro Woche und den Mix der Formate als Anzahl pro Woche (reel, karussell, story, video, bild) und einen kurzen hinweis. Passe die Menge an die Zeit pro Woche aus den ANGABEN an.\n'
      || E'- themenplan: Themenplan für die nächsten 4 Wochen ab BEGINN, je Woche 1 bis 3 Einträge mit woche (1 bis 4), thema, format und idee (1 Satz).\n'
      || E'- ziele: 2 bis 4 Ziele mit kennzahl (follower, follower_zuwachs, reichweite, aufrufe, interaktionen, interaktionsrate, beitraege), plattform (aus PLATTFORMEN oder null für alle Kanäle), zielwert (Zahl; interaktionsrate in Prozent), von und bis (JJJJ-MM-TT, 1 bis 3 Monate ab BEGINN) und begruendung. Leite die Ziele aus den bisherigen Zahlen ab; sie sind ein Vorschlag.\n'
      || CASE WHEN uebers THEN E'- begruendung: Das AKTUELLE KONZEPT weicht deutlich von den Zahlen ab (siehe ZIELE MIT STAND). Begründe die Überarbeitung mit diesen Abweichungen in 2 bis 4 Sätzen.\n'
              ELSE E'- begruendung: in 1 bis 2 Sätzen, worauf das Konzept aufbaut.\n' END
      || 'Format: {"positionierung":"…","zielgruppe":"…","kanaele":[{"plattform":"instagram","beitraege_pro_woche":3,"formate":{"reel":2,"karussell":1,"story":0,"video":0,"bild":0},"hinweis":"…"}],'
      || '"themenplan":[{"woche":1,"thema":"…","format":"reel","idee":"…"}],"ziele":[{"kennzahl":"follower","plattform":"instagram","zielwert":12000,"von":"2026-11-01","bis":"2026-12-31","begruendung":"…"}],"begruendung":"…"}',
    'nachricht', 'BEGINN: ' || to_char(talents_heute(), 'YYYY-MM-DD') || E'\n\nPLATTFORMEN: ' || plattformen::text
      || E'\n\nTALENT UND ANGABEN: ' || talents_ki_profil(k.talent_id)::text
      || E'\n\nDATEN LETZTE 90 TAGE: ' || talents_ki_kennzahlen(k.talent_id, 90)::text
      || E'\n\nWAS FUNKTIONIERT (letzte 90 Tage): ' || (talents_wf_zahlen(k.talent_id, '', talents_heute() - 90, talents_heute() - 1) - 'beste' - 'von' - 'bis')::text
      || CASE WHEN akt.id IS NOT NULL THEN E'\n\nAKTUELLES KONZEPT: ' || jsonb_build_object('positionierung', akt.positionierung, 'zielgruppe', akt.zielgruppe,
              'kanaele', akt.kanaele, 'themenplan', akt.themenplan)::text || E'\n\nZIELE MIT STAND: ' || coalesce(ziele, '[]'::jsonb)::text ELSE '' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_p_markensuche(p_auftrag_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  l talent_markensuche_laeufe;
  bekannt jsonb;
  anzahl integer := least(12, greatest(1, coalesce(nullif(ally_einstellung('talents_markensuche_anzahl'), '')::integer, 10)));
  suchen integer := least(10, greatest(1, coalesce(nullif(ally_einstellung('talents_markensuche_websuchen'), '')::integer, 5)));
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO l FROM talent_markensuche_laeufe WHERE id = a.ref_id;
  IF NOT FOUND THEN
    PERFORM talents_ki_abschluss(a.id, 'Die Suche gibt es nicht mehr.');
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  SELECT coalesce(jsonb_agg(x.marke ORDER BY x.marke), '[]'::jsonb) INTO bekannt FROM (
    SELECT DISTINCT ON (t.marke_norm) t.marke FROM talent_markensuche_treffer t WHERE t.talent_id = l.talent_id ORDER BY t.marke_norm, t.id DESC LIMIT 80) x;
  RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'anspruchsvoll', 'max_tokens', 4000, 'websuche', true, 'max_suchen', suchen,
    'system', 'Du suchst für eine Agentur im Internet nach Marken (Unternehmen), die zu einem Talent passen und mit Influencern zusammenarbeiten könnten. ' || talents_ki_regeln()
      || E'\n\nAufgabe:\n- Nutze die Websuche. Nenne nur Marken, die du in den Suchergebnissen gefunden hast, mit der Adresse der Seite, auf der die Angaben stehen (quelle_url), und deren Titel (quelle_titel).\n'
      || E'- Halte dich an EINSCHLIESSEN. Schlage nie Marken oder Branchen aus AUSSCHLIESSEN vor, nichts, was gegen die No-Gos verstößt, und keine Marke aus BEKANNT.\n'
      || E'- Nur öffentliche Angaben zu Unternehmen. Keine Namen, Mailadressen oder Profile einzelner Personen.\n'
      || E'- kontaktweg nur offizielle Wege der Marke: kooperationsprogramm (Influencer- oder Partnerprogramm), kontaktformular, presse, allgemeine_mail (z. B. info@ oder kooperation@) oder unbekannt. kontakt = Adresse dieser Seite bzw. die allgemeine Mailadresse, sonst null.\n'
      || '- Höchstens ' || anzahl || E' Marken.\n'
      || 'Format: {"marken":[{"name":"…","website":"https://…","branche":"…","begruendung":"1 bis 2 Sätze, warum die Marke zum Talent passt","quelle_url":"https://…","quelle_titel":"…","kontaktweg":"kooperationsprogramm","kontakt":"https://…"}]}',
    'nachricht', 'TALENT: ' || (talents_ki_profil(l.talent_id) - 'talent_id')::text
      || E'\n\nEINSCHLIESSEN: ' || coalesce(l.kriterien->'einschliessen', '{}'::jsonb)::text
      || E'\n\nAUSSCHLIESSEN: ' || coalesce(l.kriterien->'ausschliessen', '{}'::jsonb)::text
      || E'\n\nNO-GOS DES TALENTS: ' || coalesce(l.kriterien->>'nogos', 'keine')
      || E'\n\nBEKANNT (nicht erneut vorschlagen): ' || bekannt::text);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_p_text(p_auftrag_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  t talent_ki_texte;
  kamp jsonb;
  firma text := coalesce(nullif(btrim(eigenes_unternehmen()->>'name'), ''), 'die Agentur');
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO t FROM talent_ki_texte WHERE id = a.ref_id;
  IF NOT FOUND THEN
    PERFORM talents_ki_abschluss(a.id, 'Der Text gibt es nicht mehr.');
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  IF t.art = 'mediakit' THEN
    RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'anspruchsvoll', 'max_tokens', 1500, 'websuche', false,
      'system', 'Du schreibst für ' || firma || ' den Text für das Mediakit eines Talents, mit dem die Agentur das Talent Marken vorstellt. ' || talents_ki_regeln()
        || E'\n\nAufbau des Textes (Absätze durch Leerzeilen getrennt): Kurzvorstellung (2 bis 3 Sätze), Themen und Stil, Zielgruppe (nur Anteile aus den DATEN), '
        || E'Kanäle mit Kennzahlen (nur Werte aus den DATEN, immer mit dem Zeitraum "letzte 28 Tage"), Zusammenarbeit (allgemein, ohne Preise). Höchstens 250 Wörter.\n'
        || 'Format: {"titel":"Mediakit …","text":"…"}',
      'nachricht', 'DATEN: ' || talents_ki_profil(t.talent_id)::text
        || E'\n\nBESTE BEITRÄGE (letzte 90 Tage): ' || (talents_wf_zahlen(t.talent_id, '', talents_heute() - 90, talents_heute() - 1)->'beste')::text);
  ELSIF t.art = 'kampagne_zusammenfassung' THEN
    kamp := talents_ki_kampagnen('info', jsonb_build_object('kampagne_id', t.kampagne_id));
    IF kamp IS NULL OR NOT coalesce((kamp->>'ok')::boolean, false) THEN
      PERFORM talents_ki_abschluss(a.id, coalesce(kamp->>'fehler', 'Kampagnen sind in dieser Instanz noch nicht eingerichtet.'));
      RETURN jsonb_build_object('ohne_ki', true);
    END IF;
    RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'anspruchsvoll', 'max_tokens', 1200, 'websuche', false,
      'system', 'Du schreibst für ' || firma || ' die Zusammenfassung für den Kampagnenbericht an eine Marke. ' || talents_ki_regeln()
        || E'\n\nInhalt: Ziel und Zeitraum der Kampagne, beteiligte Talents, Ergebnis gesamt und je Talent (nur Zahlen aus den DATEN), kurzer Ausblick ohne Versprechen. Höchstens 150 Wörter.\n'
        || 'Format: {"titel":"…","text":"…"}',
      'nachricht', 'DATEN: ' || kamp::text);
  END IF;
  RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'anspruchsvoll', 'max_tokens', 1500, 'websuche', false,
    'system', 'Du schreibst für ' || firma || ' den Entwurf einer Antwort-Mail an eine Marke. ' || talents_ki_regeln()
      || E'\n\nRegeln für die Mail: Beginne mit einer passenden Anrede (im Zweifel siezen). Keine Grußformel und kein Name am Ende, die Signatur wird angehängt. '
      || E'Nenne Preise, Termine, Verfügbarkeiten und Zusagen nur als Platzhalter in eckigen Klammern. Kennzahlen nur aus den DATEN, immer mit Zeitraum.\n'
      || 'Format: {"betreff":"…","text":"…"}',
    'nachricht', 'ANFRAGE DER MARKE:' || E'\n' || coalesce(talents_ki_kurz(t.eingabe, 8000), '(kein Text)')
      || CASE WHEN t.talent_id IS NOT NULL THEN E'\n\nDATEN ZUM TALENT: ' || talents_ki_profil(t.talent_id)::text ELSE '' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_p_was_funktioniert(p_auftrag_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
  w talent_ki_auswertungen;
  beitraege jsonb;
  vorhanden jsonb;
  z jsonb;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  SELECT * INTO w FROM talent_ki_auswertungen WHERE id = a.ref_id;
  IF NOT FOUND THEN
    PERFORM talents_ki_abschluss(a.id, 'Die Auswertung gibt es nicht mehr.');
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  IF a.schritt = 1 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'text', talents_ki_kurz(b.text_inhalt, 400)) ORDER BY b.id), '[]'::jsonb) INTO beitraege
    FROM (SELECT b.id, b.text_inhalt FROM talent_beitraege b
          WHERE b.kanal_id = ANY (talents_ki_kanaele(w.talent_id, w.kanal)) AND coalesce(btrim(b.text_inhalt), '') <> ''
            AND (coalesce(b.erstellt, b.erfasst_am) AT TIME ZONE 'Europe/Berlin')::date BETWEEN w.von AND w.bis
            AND talents_beitrag_art(b.art, b.produkt_art) <> 'story'
            AND NOT EXISTS (SELECT 1 FROM talent_ki_themen t WHERE t.beitrag_id = b.id)
          ORDER BY b.id LIMIT 60) b;
    IF jsonb_array_length(beitraege) = 0 THEN
      UPDATE talent_ki_auftraege SET schritt = 2 WHERE id = a.id;
      RETURN talents_ki_p_was_funktioniert(a.id);
    END IF;
    SELECT coalesce(jsonb_agg(DISTINCT t.thema), '[]'::jsonb) INTO vorhanden FROM talent_ki_themen t
      JOIN talent_beitraege b ON b.id = t.beitrag_id JOIN talent_kanaele k ON k.id = b.kanal_id WHERE k.talent_id = w.talent_id;
    RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'einfach', 'max_tokens', 3000, 'websuche', false,
      'system', 'Du ordnest Social-Media-Beiträge eines Talents Themen zu. ' || talents_ki_regeln() || E'\n\nAufgabe: Gib jedem Beitrag aus BEITRAEGE genau ein Thema (2 bis 4 Wörter, z. B. "Rezepte" oder "Training zu Hause"). '
        || E'Nutze möglichst die VORHANDENEN THEMEN; insgesamt höchstens 8 verschiedene Themen. Das Thema ergibt sich nur aus dem Beitragstext.\n'
        || 'Format: {"themen":[{"id":123,"thema":"…"}]}',
      'nachricht', 'VORHANDENE THEMEN: ' || vorhanden::text || E'\n\nBEITRAEGE:\n' || beitraege::text);
  END IF;
  -- Schritt 2: Zahlen rechnen (ohne KI), dann Vorschläge
  z := talents_wf_zahlen(w.talent_id, w.kanal, w.von, w.bis);
  UPDATE talent_ki_auswertungen SET zahlen = z, hinweis = z->>'hinweis' WHERE id = w.id;
  IF coalesce((z->>'anzahl_mit_zahlen')::integer, 0) = 0 THEN
    UPDATE talent_ki_auswertungen SET status = 'fertig', vorschlaege = '[]'::jsonb,
      hinweis = coalesce(z->>'hinweis', 'Im Zeitraum gibt es noch keine Beiträge mit Zahlen.') WHERE id = w.id;
    PERFORM talents_ki_abschluss(a.id);
    RETURN jsonb_build_object('ohne_ki', true);
  END IF;
  RETURN jsonb_build_object('ohne_ki', false, 'modell_art', 'anspruchsvoll', 'max_tokens', 2000, 'websuche', false,
    'system', 'Du bist in der Social-Media-Beratung einer Agentur tätig und leitest aus den Zahlen eines Talents Vorschläge für die nächsten Beiträge ab. ' || talents_ki_regeln()
      || E'\n\nAufgabe:\n- Nutze nur Gruppen mit "aussage": true als Beleg; Gruppen mit zu wenigen Beiträgen nicht.\n'
      || E'- Jeder Vorschlag nennt seine Grundlage aus den DATEN, z. B. "Reels: 2,3-mal Reichweite des Schnitts".\n'
      || E'- Beachte Themen, Ziele und No-Gos aus den ANGABEN.\n- Höchstens 5 Vorschläge.\n'
      || 'Format: {"vorschlaege":[{"titel":"höchstens 8 Wörter","text":"1 bis 2 Sätze","grundlage":"…"}]}',
    'nachricht', 'ANGABEN: ' || coalesce(talents_ki_profil(w.talent_id)->'angaben', 'null'::jsonb)::text
      || E'\n\nDATEN (' || (z->>'zeitraum_text') || '): ' || (z - 'beste' - 'von' - 'bis')::text);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_planen(p_erzwingen boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  heute text := to_char(talents_heute(), 'YYYY-MM-DD');
  t record;
  k integer;
  n integer := 0;
  kz jsonb;
  kampagnen boolean := false;
BEGIN
  IF NOT plattform_modul_an('talents') OR ki_gesperrt() THEN
    RETURN jsonb_build_object('ok', true, 'geplant', 0);
  END IF;
  IF NOT p_erzwingen AND ally_einstellung('talents_ki_geplant_am') = heute THEN
    RETURN jsonb_build_object('ok', true, 'geplant', 0, 'hinweis', 'Heute schon geplant.');
  END IF;
  PERFORM ally_einstellung_setzen('talents_ki_geplant_am', heute, 'TALENTS KI-Aufträge');
  PERFORM talents_ki_aufraeumen();
  FOR t IN
    SELECT c.id AS konzept_id, c.talent_id, c.geaendert_von, c.erstellt_von FROM talent_konzepte c JOIN talents x ON x.id = c.talent_id AND x.status = 'aktiv'
    WHERE c.status = 'aktiv'
      AND EXISTS (SELECT 1 FROM talent_konzept_ziele z WHERE z.konzept_id = c.id AND coalesce((talents_ziel_stand(z.id)->>'deutlich')::boolean, false))
      AND NOT EXISTS (SELECT 1 FROM talent_konzepte u WHERE u.talent_id = c.talent_id AND u.art = 'ueberarbeitung' AND u.erstellt_am > now() - interval '14 days')
      AND NOT EXISTS (SELECT 1 FROM talent_ki_auftraege o WHERE o.talent_id = c.talent_id AND o.art IN ('konzept', 'konzept_ueberarbeiten') AND o.status IN ('offen', 'laeuft'))
    ORDER BY c.talent_id LIMIT 20
  LOOP
    INSERT INTO talent_konzepte (talent_id, status, art, erstellt_von) VALUES (t.talent_id, 'wird_erstellt', 'ueberarbeitung', coalesce(t.geaendert_von, t.erstellt_von)) RETURNING id INTO k;
    UPDATE talent_konzepte SET ki_auftrag_id = talents_ki_auftrag_anlegen('konzept_ueberarbeiten', t.talent_id, k, coalesce(t.geaendert_von, t.erstellt_von)) WHERE id = k;
    n := n + 1;
  END LOOP;
  kz := talents_ki_kampagnen('kandidaten', jsonb_build_object('anzahl', 1));
  IF jsonb_array_length(coalesce(kz->'kampagnen', '[]'::jsonb)) > 0 THEN
    PERFORM talents_ki_auftrag_anlegen('kampagnen_zuordnung', NULL, NULL, NULL);
    kampagnen := true;
  END IF;
  RETURN jsonb_build_object('ok', true, 'geplant', n, 'kampagnen', kampagnen);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_profil(p_talent_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('talent_id', t.id, 'name', talent_anzeigename(t.id),
    'angaben', CASE WHEN a.talent_id IS NULL THEN NULL ELSE jsonb_strip_nulls(jsonb_build_object('themen', a.themen, 'ziele', a.ziele, 'zielgruppe', a.zielgruppe,
                    'nogos', a.nogos, 'stunden_pro_woche', a.stunden_pro_woche)) END,
    'kennzahlen_28_tage', talents_ki_kennzahlen(t.id, 28),
    'zielgruppe_follower', (SELECT coalesce(jsonb_object_agg(z->>'aufteilung', (SELECT jsonb_agg(e->>'name' || ' ' || (e->>'anteil_text'))
                                       FROM jsonb_array_elements(z->'eintraege') WITH ORDINALITY AS x(e, n) WHERE x.n <= 3)), '{}'::jsonb)
                            FROM jsonb_array_elements(talents_zielgruppe(talents_ki_kanaele(t.id))) z
                            WHERE z->>'gruppe' = 'follower_demographics' AND z->>'aufteilung' IN ('age', 'gender', 'country'))
  )
  FROM talents t LEFT JOIN talent_konzept_angaben a ON a.talent_id = t.id
  WHERE t.id = p_talent_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_prompt(p_auftrag_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  art text := (SELECT x.art FROM talent_ki_auftraege x WHERE x.id = p_auftrag_id);
BEGIN
  RETURN CASE art
    WHEN 'was_funktioniert' THEN talents_ki_p_was_funktioniert(p_auftrag_id)
    WHEN 'konzept' THEN talents_ki_p_konzept(p_auftrag_id)
    WHEN 'konzept_ueberarbeiten' THEN talents_ki_p_konzept(p_auftrag_id)
    WHEN 'text' THEN talents_ki_p_text(p_auftrag_id)
    WHEN 'talent_anfrage' THEN talents_ki_p_anfrage(p_auftrag_id)
    WHEN 'kooperation' THEN talents_ki_p_anfrage(p_auftrag_id)
    WHEN 'markensuche' THEN talents_ki_p_markensuche(p_auftrag_id)
    WHEN 'kampagnen_zuordnung' THEN talents_ki_p_kampagnen(p_auftrag_id)
  END;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_regeln()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT E'Regeln:\n'
    || E'- Schreibe auf Deutsch, sachlich, knapp und genderneutral (z. B. Person, Team). Keine Emojis, kein Markdown.\n'
    || E'- Verwende nur Zahlen, die in den DATEN stehen. Rechne nichts selbst aus und erfinde keine Werte, Marken, Kooperationen, Ergebnisse oder Erfahrungen.\n'
    || E'- Fehlt eine Angabe, schreibe "nicht verfügbar" bzw. setze einen Platzhalter in eckigen Klammern, z. B. [Preis einsetzen].\n'
    || E'- Alles ist ein Vorschlag für einen Menschen, der entscheidet.\n'
    || E'- Antworte ausschließlich mit einem gültigen JSON-Objekt im angegebenen Format, ohne Erklärung davor oder danach.'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_schritte(p_anzahl integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  a record;
  p jsonb;
  s jsonb := '[]'::jsonb;
  m text;
BEGIN
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', true, 'gesperrt', false, 'schritte', '[]'::jsonb, 'hinweis', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  -- Hängende Schritte (Workflow abgebrochen) nach 15 Minuten erneut freigeben; zählt als Versuch
  UPDATE talent_ki_auftraege SET status = 'offen', versuche = versuche + 1 WHERE status = 'laeuft' AND gestartet_am < now() - interval '15 minutes';
  FOR a IN SELECT x.id FROM talent_ki_auftraege x WHERE x.status = 'offen' AND x.versuche >= 3 LOOP
    PERFORM talents_ki_abschluss(a.id, 'Die KI-Funktion ist dreimal gescheitert. Bitte später erneut starten.');
  END LOOP;
  IF ki_gesperrt() THEN
    RETURN jsonb_build_object('ok', true, 'gesperrt', true, 'sperre_text', ki_sperre_text(), 'schritte', '[]'::jsonb);
  END IF;
  FOR a IN SELECT x.id FROM talent_ki_auftraege x WHERE x.status = 'offen' ORDER BY x.id FOR UPDATE SKIP LOCKED LOOP
    EXIT WHEN jsonb_array_length(s) >= greatest(1, least(coalesce(p_anzahl, 3), 10));
    -- Testdaten (Migration 79): keine KI für Test-Talents und für Aufträge von Test-Personen
    IF EXISTS (SELECT 1 FROM talent_ki_auftraege x WHERE x.id = a.id AND (talents_ist_testdaten(x.talent_id) OR ally_person_ist_testdaten(x.erstellt_von))) THEN
      PERFORM talents_ki_abschluss(a.id, 'Bei Testdaten wird keine KI genutzt.');
      CONTINUE;
    END IF;
    BEGIN
      p := talents_ki_prompt(a.id);
    EXCEPTION WHEN others THEN
      PERFORM talents_ki_abschluss(a.id, 'Die KI-Funktion konnte nicht vorbereitet werden: ' || left(SQLERRM, 200));
      CONTINUE;
    END;
    CONTINUE WHEN p IS NULL OR coalesce((p->>'ohne_ki')::boolean, false);
    m := ki_modell(coalesce(p->>'modell_art', 'anspruchsvoll'));
    IF m IS NULL THEN
      PERFORM talents_ki_abschluss(a.id, 'Es ist kein KI-Modell freigeschaltet (Einstellungen › Vertrag und Budget › KI-Budget und Verbrauch).');
      CONTINUE;
    END IF;
    UPDATE talent_ki_auftraege SET status = 'laeuft', gestartet_am = now() WHERE id = a.id;
    s := s || jsonb_build_array(jsonb_build_object('auftrag_id', a.id, 'schritt', (SELECT x.schritt FROM talent_ki_auftraege x WHERE x.id = a.id),
      'art', (SELECT x.art FROM talent_ki_auftraege x WHERE x.id = a.id), 'modell', m,
      'system', p->>'system', 'nachricht', p->>'nachricht', 'max_tokens', coalesce((p->>'max_tokens')::integer, 2000),
      'websuche', coalesce((p->>'websuche')::boolean, false), 'max_suchen', coalesce((p->>'max_suchen')::integer, 0),
      'user', coalesce((SELECT x.erstellt_von FROM talent_ki_auftraege x WHERE x.id = a.id), '')));
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'gesperrt', false, 'schritte', s);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_sitzung(p_token text, p_talent_id integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  r jsonb := talents_ansicht_start(p_token);
BEGIN
  IF NOT coalesce((r->>'ok')::boolean, false) THEN
    RETURN r;
  END IF;
  r := r || jsonb_build_object('admin', ally_hat_recht(r->>'u', 'admin'));
  IF p_talent_id IS NOT NULL AND NOT talent_sichtbar(r->>'u', p_talent_id) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Dieses Talent gibt es nicht oder du bist nicht als Manager oder Managerin eingetragen.');
  END IF;
  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_start_fehler(p_talent_id integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE
    WHEN p_talent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = p_talent_id AND t.status = 'aktiv') THEN 'Das Talent liegt im Papierkorb.'
    WHEN ki_gesperrt() THEN ki_sperre_text()
    WHEN ki_modell('anspruchsvoll') IS NULL THEN 'Es ist kein KI-Modell freigeschaltet (Einstellungen › Vertrag und Budget › KI-Budget und Verbrauch).'
  END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_talent_vergessen(p_talent_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n integer;
BEGIN
  UPDATE talent_ki_anfragen SET talent_ids = array_remove(talent_ids, p_talent_id),
    vorschlaege = (SELECT coalesce(jsonb_agg(v), '[]'::jsonb) FROM jsonb_array_elements(vorschlaege) v WHERE (v->>'talent_id')::integer IS DISTINCT FROM p_talent_id),
    ausgeschlossen = (SELECT coalesce(jsonb_agg(v), '[]'::jsonb) FROM jsonb_array_elements(ausgeschlossen) v WHERE (v->>'talent_id')::integer IS DISTINCT FROM p_talent_id)
  WHERE p_talent_id = ANY (talent_ids) OR vorschlaege @> jsonb_build_array(jsonb_build_object('talent_id', p_talent_id))
     OR ausgeschlossen @> jsonb_build_array(jsonb_build_object('talent_id', p_talent_id));
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'anfragen', n);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_text_sichtbar(p_user text, p_text_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM talent_ki_texte x WHERE x.id = p_text_id AND (
    (x.talent_id IS NOT NULL AND talent_sichtbar(p_user, x.talent_id))
    OR (x.talent_id IS NULL AND (x.erstellt_von = p_user OR talents_zugriff(p_user) = 'alle'
        OR (x.anfrage_id IS NOT NULL AND talents_ki_anfrage_sichtbar(p_user, x.anfrage_id))))))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_url_norm(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT rtrim(lower(split_part(split_part(btrim(coalesce(p, '')), '#', 1), '?', 1)), '/')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_websuche_buchen(p_workflow text, p_user text, p_antwort jsonb)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  n integer := 0;
  preis numeric;
BEGIN
  BEGIN
    n := coalesce((p_antwort->'usage'->'server_tool_use'->>'web_search_requests')::integer, 0);
    preis := nullif(ally_einstellung('ki_websuche_usd'), '')::numeric;
    IF n > 0 THEN
      INSERT INTO ki_verbrauch (matrix_user_id, funktion, workflow, modell, kosten_usd, preis_faktor, schluessel)
      VALUES (nullif(btrim(coalesce(p_user, '')), ''), 'talents', p_workflow, 'Websuche', round(n * coalesce(preis, 0.01), 6),
              ki_faktor_aktuell(), ki_schluessel_aktuell());
    END IF;
  EXCEPTION WHEN others THEN
    PERFORM ki_kosten_melden('buchung_fehler', 'Websuche', 'talents', p_workflow, SQLERRM);   -- Migration 185: nicht mehr still
  END;
  RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_zahl(p jsonb)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN jsonb_typeof(p) = 'number' THEN (p #>> '{}')::numeric
              WHEN jsonb_typeof(p) = 'string' AND replace(btrim(p #>> '{}'), ',', '.') ~ '^[0-9]{1,12}([.][0-9]{1,3})?$'
                THEN replace(btrim(p #>> '{}'), ',', '.')::numeric END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_zahlen_pruefen(p_text text, p_erlaubt jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  WITH erlaubt AS (
    SELECT DISTINCT regexp_replace(m[1], '[.,]', '', 'g') AS z
    FROM regexp_matches(coalesce(p_erlaubt::text, ''), '([0-9][0-9.,]*[0-9]|[0-9])', 'g') AS m
  ), gefunden AS (
    SELECT DISTINCT m[1] AS roh, regexp_replace(m[1], '[.,]', '', 'g') AS z, m[2] IS NOT NULL AS prozent
    FROM regexp_matches(coalesce(p_text, ''), '([0-9][0-9.,]*[0-9]|[0-9])(\s?%)?', 'g') AS m
  )
  SELECT coalesce(jsonb_agg(g.roh ORDER BY g.roh), '[]'::jsonb) FROM gefunden g
  WHERE (length(g.z) >= 3 OR g.prozent)
    AND g.z !~ '^(19|20)[0-9]{2}$'
    AND NOT EXISTS (SELECT 1 FROM erlaubt e WHERE e.z = g.z OR rtrim(e.z, '0') = rtrim(g.z, '0'))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_ki_ziel_fehler(p_auftrag_id integer, p_text text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_ki_auftraege;
BEGIN
  SELECT * INTO a FROM talent_ki_auftraege WHERE id = p_auftrag_id;
  IF a.art = 'was_funktioniert' THEN
    UPDATE talent_ki_auswertungen SET status = 'fehler', fehler = p_text WHERE id = a.ref_id AND status = 'wird_erstellt';
  ELSIF a.art IN ('konzept', 'konzept_ueberarbeiten') THEN
    UPDATE talent_konzepte SET status = 'fehler', fehler = p_text, geaendert_am = now() WHERE id = a.ref_id AND status = 'wird_erstellt';
  ELSIF a.art = 'text' THEN
    UPDATE talent_ki_texte SET status = 'fehler', fehler = p_text, geaendert_am = now() WHERE id = a.ref_id AND status = 'wird_erstellt';
  ELSIF a.art IN ('talent_anfrage', 'kooperation') THEN
    UPDATE talent_ki_anfragen SET status = 'fehler', fehler = p_text WHERE id = a.ref_id AND status = 'wird_erstellt';
  ELSIF a.art = 'markensuche' THEN
    UPDATE talent_markensuche_laeufe SET status = 'fehler', fehler = p_text WHERE id = a.ref_id AND status = 'wird_erstellt';
  END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_konto_text(p_plattform text, p_name text, p_id text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN nullif(ltrim(btrim(coalesce(p_name, '')), '@'), '') IS NULL
              THEN coalesce(talents_plattform_name(p_plattform), 'Plattform') || '-Account' || coalesce(' ' || nullif(btrim(coalesce(p_id, '')), ''), '')
              WHEN p_plattform IN ('instagram', 'threads', 'pinterest') THEN '@' || ltrim(btrim(p_name), '@')
              ELSE btrim(p_name) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_konzept_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  kid integer := CASE WHEN d->>'konzept_id' ~ '^[0-9]{1,9}$' THEN (d->>'konzept_id')::integer END;
  zid integer := CASE WHEN d->>'ziel_id' ~ '^[0-9]{1,9}$' THEN (d->>'ziel_id')::integer END;
  tid integer := CASE WHEN d->>'talent_id' ~ '^[0-9]{1,9}$' THEN (d->>'talent_id')::integer END;
  c talent_konzepte;
  s jsonb;
  u text;
  f text;
  std numeric;
  i integer;
  l jsonb;
  vz date; bz date; zw numeric;
BEGIN
  IF kid IS NOT NULL THEN
    SELECT * INTO c FROM talent_konzepte WHERE id = kid;
    tid := c.talent_id;
  ELSIF zid IS NOT NULL THEN
    SELECT k.* INTO c FROM talent_konzept_ziele z JOIN talent_konzepte k ON k.id = z.konzept_id WHERE z.id = zid;
    tid := c.talent_id;
  END IF;
  IF tid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte die Seite neu laden.');
  END IF;
  s := talents_ki_sitzung(p_token, tid);
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  u := s->>'u';
  IF NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = tid AND t.status = 'aktiv') THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Das Talent liegt im Papierkorb. Das Konzept lässt sich nur ansehen.');
  END IF;
  IF p_aktion = 'angaben_speichern' THEN
    std := CASE WHEN replace(btrim(coalesce(d->>'stunden_pro_woche', '')), ',', '.') ~ '^[0-9]{1,2}([.][0-9])?$' THEN replace(btrim(d->>'stunden_pro_woche'), ',', '.')::numeric END;
    IF coalesce(btrim(d->>'stunden_pro_woche'), '') <> '' AND (std IS NULL OR std <= 0 OR std > 80) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte die Zeit pro Woche als Stunden zwischen 0,5 und 80 angeben.');
    END IF;
    IF greatest(length(coalesce(d->>'themen', '')), length(coalesce(d->>'ziele', '')), length(coalesce(d->>'zielgruppe', '')), length(coalesce(d->>'nogos', ''))) > 1500 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Jedes Feld darf höchstens 1.500 Zeichen lang sein.');
    END IF;
    INSERT INTO talent_konzept_angaben (talent_id, themen, ziele, zielgruppe, nogos, stunden_pro_woche, geaendert_von)
    VALUES (tid, talents_ki_kurz(d->>'themen', 1500), talents_ki_kurz(d->>'ziele', 1500), talents_ki_kurz(d->>'zielgruppe', 1500), talents_ki_kurz(d->>'nogos', 1500), std, u)
    ON CONFLICT (talent_id) DO UPDATE SET themen = EXCLUDED.themen, ziele = EXCLUDED.ziele, zielgruppe = EXCLUDED.zielgruppe, nogos = EXCLUDED.nogos,
      stunden_pro_woche = EXCLUDED.stunden_pro_woche, geaendert_am = now(), geaendert_von = u;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Angaben gespeichert.');
  ELSIF p_aktion IN ('erstellen', 'ueberarbeitung_anfordern') THEN
    f := talents_ki_start_fehler(tid);
    IF f IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', f);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM talent_konzept_angaben a WHERE a.talent_id = tid AND coalesce(btrim(a.themen), '') <> '') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte zuerst die Angaben ausfüllen (mindestens die Themen).');
    END IF;
    IF p_aktion = 'ueberarbeitung_anfordern' AND NOT EXISTS (SELECT 1 FROM talent_konzepte k WHERE k.talent_id = tid AND k.status = 'aktiv') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Es gibt noch kein aktives Konzept.');
    END IF;
    IF EXISTS (SELECT 1 FROM talent_konzepte k WHERE k.talent_id = tid AND k.status = 'wird_erstellt') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Ein Konzept wird gerade erstellt. ' || talents_ki_laeuft_text());
    END IF;
    INSERT INTO talent_konzepte (talent_id, status, art, erstellt_von) VALUES (tid, 'wird_erstellt', CASE WHEN p_aktion = 'erstellen' THEN 'neu' ELSE 'ueberarbeitung' END, u) RETURNING id INTO i;
    UPDATE talent_konzepte SET ki_auftrag_id = talents_ki_auftrag_anlegen(CASE WHEN p_aktion = 'erstellen' THEN 'konzept' ELSE 'konzept_ueberarbeiten' END, tid, i, u) WHERE id = i;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'konzept_id', i, 'auftrag_id', (SELECT ki_auftrag_id FROM talent_konzepte WHERE id = i),
      'meldung', talents_ki_laeuft_text());
  END IF;
  -- ab hier: bestehendes Konzept bzw. Ziel
  IF c.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Dieses Konzept gibt es nicht. Bitte die Seite neu laden.');
  END IF;
  IF p_aktion = 'entwurf_speichern' THEN
    IF c.status NOT IN ('entwurf', 'aktiv') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Dieses Konzept lässt sich nicht mehr bearbeiten.');
    END IF;
    IF length(coalesce(d->>'positionierung', '')) > 1500 OR length(coalesce(d->>'zielgruppe', '')) > 1000 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Positionierung höchstens 1.500, Zielgruppe höchstens 1.000 Zeichen.');
    END IF;
    l := talents_konzept_listen(tid, CASE WHEN d ? 'kanaele' THEN d->'kanaele' ELSE c.kanaele END, CASE WHEN d ? 'themenplan' THEN d->'themenplan' ELSE c.themenplan END);
    UPDATE talent_konzepte SET positionierung = CASE WHEN d ? 'positionierung' THEN talents_ki_kurz(d->>'positionierung', 1500) ELSE positionierung END,
      zielgruppe = CASE WHEN d ? 'zielgruppe' THEN talents_ki_kurz(d->>'zielgruppe', 1000) ELSE zielgruppe END,
      kanaele = l->'kanaele', themenplan = l->'themenplan', geaendert_am = now(), geaendert_von = u
    WHERE id = c.id;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Konzept gespeichert.');
  ELSIF p_aktion = 'aktivieren' THEN
    IF c.status <> 'entwurf' THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Nur ein Entwurf lässt sich aktivieren.');
    END IF;
    UPDATE talent_konzepte SET status = 'abgelegt', geaendert_am = now(), geaendert_von = u WHERE talent_id = tid AND status = 'aktiv';
    UPDATE talent_konzepte SET status = 'aktiv', aktiv_seit = now(), geaendert_am = now(), geaendert_von = u WHERE id = c.id;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Konzept ist jetzt aktiv. Ally hält die Ziele nach und zeigt Soll und Ist.');
  ELSIF p_aktion = 'verwerfen' THEN
    IF c.status NOT IN ('entwurf', 'fehler') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Nur ein Entwurf lässt sich verwerfen.');
    END IF;
    UPDATE talent_konzepte SET status = 'abgelegt', geaendert_am = now(), geaendert_von = u WHERE id = c.id;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Entwurf verworfen.');
  ELSIF p_aktion = 'ziel_speichern' THEN
    IF c.status NOT IN ('entwurf', 'aktiv') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Ziele lassen sich nur bei einem Entwurf oder aktiven Konzept ändern.');
    END IF;
    vz := talents_datum_lesen(d->>'von');
    bz := talents_datum_lesen(d->>'bis');
    zw := talents_ki_zahl(d->'zielwert');
    IF d->>'kennzahl' NOT IN ('follower', 'follower_zuwachs', 'reichweite', 'aufrufe', 'interaktionen', 'interaktionsrate', 'beitraege') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte eine Kennzahl wählen.');
    END IF;
    IF nullif(d->>'plattform', '') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = tid AND k.plattform = d->>'plattform') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diese Plattform hat das Talent nicht.');
    END IF;
    IF zw IS NULL OR zw < 0 OR (d->>'kennzahl' = 'interaktionsrate' AND zw > 100) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte einen Zielwert als Zahl angeben (Interaktionsrate in Prozent, höchstens 100).');
    END IF;
    IF vz IS NULL OR bz IS NULL OR bz < vz OR bz - vz > 366 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte Beginn und Ende angeben (Ende nach dem Beginn, höchstens ein Jahr).');
    END IF;
    IF zid IS NOT NULL THEN
      UPDATE talent_konzept_ziele SET kennzahl = d->>'kennzahl', plattform = nullif(d->>'plattform', ''), zielwert = round(zw, 1), von = vz, bis = bz, von_ki = false
      WHERE id = zid;
    ELSE
      IF (SELECT count(*) FROM talent_konzept_ziele z WHERE z.konzept_id = c.id) >= 8 THEN
        RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Höchstens 8 Ziele je Konzept.');
      END IF;
      INSERT INTO talent_konzept_ziele (konzept_id, talent_id, kennzahl, plattform, zielwert, von, bis, erstellt_von)
      VALUES (c.id, tid, d->>'kennzahl', nullif(d->>'plattform', ''), round(zw, 1), vz, bz, u);
    END IF;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Ziel gespeichert.');
  ELSIF p_aktion = 'ziel_loeschen' THEN
    PERFORM talents_profil_pk_legen('ziel', zid, u);  -- Migration 130: in den Papierkorb
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Ziel liegt jetzt im Papierkorb. Im Papierkorb kannst du es wiederherstellen.');
  END IF;
  RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Unbekannte Aktion.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_konzept_daten(p_token text, p_talent_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s jsonb := talents_ki_sitzung(p_token, p_talent_id);
  a talent_konzept_angaben;
  akt integer;
  ent integer;
BEGIN
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  SELECT * INTO a FROM talent_konzept_angaben WHERE talent_id = p_talent_id;
  SELECT id INTO akt FROM talent_konzepte WHERE talent_id = p_talent_id AND status = 'aktiv';
  SELECT id INTO ent FROM talent_konzepte WHERE talent_id = p_talent_id AND status IN ('wird_erstellt', 'entwurf', 'fehler') ORDER BY id DESC LIMIT 1;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true,
    'talent', jsonb_build_object('talent_id', p_talent_id, 'name', talent_anzeigename(p_talent_id), 'status', (SELECT t.status FROM talents t WHERE t.id = p_talent_id)),
    'darf_bearbeiten', EXISTS (SELECT 1 FROM talents t WHERE t.id = p_talent_id AND t.status = 'aktiv'),
    'angaben', jsonb_build_object('themen', a.themen, 'ziele', a.ziele, 'zielgruppe', a.zielgruppe, 'nogos', a.nogos,
                                  'stunden_pro_woche', a.stunden_pro_woche, 'geaendert', talents_datum(a.geaendert_am)),
    'angaben_fehlen', a.talent_id IS NULL OR coalesce(btrim(a.themen), '') = '',
    'aktiv', CASE WHEN akt IS NOT NULL THEN talents_konzept_json(akt) END,
    'entwurf', CASE WHEN ent IS NOT NULL THEN talents_konzept_json(ent) END,
    'kennzahlen', '[{"wert": "follower", "name": "Follower (Stand am Ende)"}, {"wert": "follower_zuwachs", "name": "Follower-Zuwachs"},
                    {"wert": "reichweite", "name": "Reichweite (Summe)"}, {"wert": "aufrufe", "name": "Aufrufe (Summe)"},
                    {"wert": "interaktionen", "name": "Interaktionen (Summe)"}, {"wert": "interaktionsrate", "name": "Interaktionsrate in %"},
                    {"wert": "beitraege", "name": "Anzahl Beiträge"}]'::jsonb,
    'plattformen', (SELECT coalesce(jsonb_agg(jsonb_build_object('wert', x.plattform, 'name', talents_plattform_name(x.plattform)) ORDER BY array_position(talents_plattformen(), x.plattform)), '[]'::jsonb)
                    FROM (SELECT DISTINCT k.plattform FROM talent_kanaele k WHERE k.talent_id = p_talent_id) x),
    'formate', '[{"wert": "reel", "name": "Reel"}, {"wert": "karussell", "name": "Karussell"}, {"wert": "story", "name": "Story"}, {"wert": "video", "name": "Video"}, {"wert": "bild", "name": "Bild"}]'::jsonb,
    'ki_hinweis', talents_ki_start_fehler(p_talent_id),
    'abweichung_prozent', coalesce(nullif(ally_einstellung('talents_konzept_abweichung_prozent'), '')::integer, 25));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_konzept_json(p_konzept_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('konzept_id', c.id, 'status', c.status,
    'status_text', CASE c.status WHEN 'wird_erstellt' THEN talents_ki_laeuft_text() WHEN 'entwurf' THEN 'Entwurf' WHEN 'aktiv' THEN 'Aktiv seit ' || talents_datum(c.aktiv_seit)
                                 WHEN 'fehler' THEN 'Konnte nicht erstellt werden' ELSE 'Abgelegt' END,
    'laeuft', c.status = 'wird_erstellt',
    'art', c.art, 'art_text', CASE WHEN c.art = 'ueberarbeitung' THEN 'Vorschlag zur Überarbeitung' ELSE 'Konzept' END,
    'positionierung', c.positionierung, 'zielgruppe', c.zielgruppe, 'kanaele', c.kanaele,
    'themenplan', (SELECT coalesce(jsonb_agg(x ORDER BY (x->>'woche')::integer, n), '[]'::jsonb) FROM jsonb_array_elements(c.themenplan) WITH ORDINALITY y(x, n)),
    'begruendung', c.begruendung, 'fehler', c.fehler,
    'erstellt', talents_datum(c.erstellt_am), 'geaendert', talents_datum(c.geaendert_am),
    'von_ki', c.ki_auftrag_id IS NOT NULL,
    'ziele', (SELECT coalesce(jsonb_agg(talents_ziel_stand(z.id) ORDER BY z.von, z.id), '[]'::jsonb) FROM talent_konzept_ziele z WHERE z.konzept_id = c.id))
  FROM talent_konzepte c WHERE c.id = p_konzept_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_konzept_listen(p_talent_id integer, p_kanaele jsonb, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  pl text[];
  e jsonb;
  f jsonb;
  kan jsonb := '[]'::jsonb;
  plan jsonb := '[]'::jsonb;
BEGIN
  SELECT coalesce(array_agg(DISTINCT x.plattform), '{}') INTO pl FROM talent_kanaele x WHERE x.talent_id = p_talent_id;
  FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_kanaele) = 'array' THEN p_kanaele ELSE '[]'::jsonb END) x LIMIT 8 LOOP
    CONTINUE WHEN jsonb_typeof(e) <> 'object' OR NOT (e->>'plattform' = ANY (pl));
    SELECT coalesce(jsonb_object_agg(fa, greatest(0, least(21, round(coalesce(talents_ki_zahl(e->'formate'->fa), 0))))), '{}'::jsonb) INTO f
    FROM unnest(ARRAY['reel', 'karussell', 'story', 'video', 'bild']) fa;
    kan := kan || jsonb_build_array(jsonb_build_object('plattform', e->>'plattform', 'plattform_name', talents_plattform_name(e->>'plattform'),
      'beitraege_pro_woche', greatest(0, least(21, round(coalesce(talents_ki_zahl(e->'beitraege_pro_woche'), 0), 1))), 'formate', f,
      'hinweis', talents_ki_kurz(e->>'hinweis', 200)));
  END LOOP;
  FOR e IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_plan) = 'array' THEN p_plan ELSE '[]'::jsonb END) x LIMIT 15 LOOP
    CONTINUE WHEN jsonb_typeof(e) <> 'object' OR talents_ki_kurz(e->>'thema', 80) IS NULL OR NOT coalesce(talents_ki_zahl(e->'woche') BETWEEN 1 AND 5, false);
    plan := plan || jsonb_build_array(jsonb_build_object('woche', talents_ki_zahl(e->'woche')::integer, 'thema', talents_ki_kurz(e->>'thema', 80),
      'format', CASE WHEN e->>'format' IN ('reel', 'karussell', 'story', 'video', 'bild') THEN e->>'format' END,
      'format_name', CASE WHEN e->>'format' IN ('reel', 'karussell', 'story', 'video', 'bild') THEN talents_beitrag_art_name(e->>'format') END,
      'idee', talents_ki_kurz(e->>'idee', 300)));
  END LOOP;
  RETURN jsonb_build_object('kanaele', kan, 'themenplan', plan);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_kooperation_gemeldet(p_zuordnung_id integer)
 RETURNS jsonb
 LANGUAGE sql
AS $function$
  UPDATE talent_mail_zuordnung SET gemeldet_am = now() WHERE id = p_zuordnung_id AND art = 'kooperation' AND gemeldet_am IS NULL
  RETURNING jsonb_build_object('ok', true, 'zuordnung_id', id)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_kooperation_meldungen()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('ok', true, 'meldungen', coalesce(jsonb_agg(x.o ORDER BY x.id), '[]'::jsonb))
  FROM (
    SELECT z.id, jsonb_build_object('zuordnung_id', z.id,
      'titel', 'Markenanfrage an ' || z.postfach || ':',
      'text', coalesce(z.absender, '') || E'\nBetreff: ' || coalesce(z.betreff, '(ohne Betreff)') || E'\n\n'
        || CASE WHEN q.status = 'fehler' THEN 'Passende Talents: konnten nicht ermittelt werden.'
                WHEN jsonb_array_length(q.vorschlaege) = 0 THEN 'Passende Talents: keine gefunden.'
                ELSE 'Passende Talents: ' || (SELECT string_agg((v->>'name') || ' (' || (v->>'passung_text') || ')', ', ') FROM jsonb_array_elements(q.vorschlaege) v) END
        || E'\n'
        || CASE WHEN e.status = 'abgelegt' THEN 'Der Antwort-Entwurf liegt im Entwurfsordner von ' || z.postfach || '.'
                WHEN e.status = 'fehler' THEN 'Der Antwort-Entwurf konnte nicht abgelegt werden: ' || coalesce(e.fehler, 'unbekannter Fehler') || ' Der Text steht auf der Oberfläche unter Talents › Markenanfrage.'
                WHEN q.text_id IS NOT NULL THEN 'Den Antwort-Entwurf findest du auf der Oberfläche unter Talents › Markenanfrage.'
                ELSE 'Details auf der Oberfläche unter Talents › Markenanfrage.' END,
      'empfaenger', (SELECT coalesce(jsonb_agg(jsonb_build_object('user_id', n.matrix_user_id, 'room_id', n.room_id) ORDER BY n.matrix_user_id), '[]'::jsonb)
                     FROM ally_nutzer n
                     WHERE n.room_id IS NOT NULL AND ally_postfach_zustaendig(n.matrix_user_id, z.postfach) AND talents_zugriff(n.matrix_user_id) IS NOT NULL
                       AND ally_funktion_an(n.matrix_user_id, 'talents_kooperation'))) AS o
    FROM talent_mail_zuordnung z
    JOIN talent_ki_anfragen q ON q.id = z.anfrage_id
    LEFT JOIN LATERAL (SELECT e.* FROM talent_mail_entwuerfe e WHERE e.art = 'kooperation' AND e.antwort_auf = q.mail_id ORDER BY e.id DESC LIMIT 1) e ON true
    WHERE z.art = 'kooperation' AND z.gemeldet_am IS NULL AND q.status IN ('fertig', 'fehler')
      AND (e.id IS NULL OR e.status IN ('abgelegt', 'fehler'))
      AND z.eingang > now() - interval '14 days'
    ORDER BY z.id LIMIT 20) x
$function$
;

CREATE OR REPLACE FUNCTION public.talents_liste(p jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE jsonb_typeof(p)
    WHEN 'array' THEN ARRAY(SELECT DISTINCT btrim(e #>> '{}') FROM jsonb_array_elements(p) e WHERE jsonb_typeof(e) IN ('string', 'number') AND btrim(e #>> '{}') <> '')
    WHEN 'string' THEN ARRAY(SELECT DISTINCT btrim(x) FROM regexp_split_to_table(p #>> '{}', ',') x WHERE btrim(x) <> '')
    ELSE '{}'::text[] END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_liste_aktion(p_token text, p_art text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb; u text; ids integer[]; n integer := 0; ohne integer := 0;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  m text := NULL; fehler text := NULL;
BEGIN
  -- Migration 147 (Stefan 24.10.2026, Konzept D): eigene Liste „Meine Talents“ – hinzufügen (nur Talents, die die Person sieht) oder entfernen (nur aus der
  -- eigenen Liste; es wird nichts gelöscht). ids: Nummern mit Komma, höchstens 1000. Die Liste gibt keine Rechte. Setzt die Meldung selbst.
  c := talents_ansicht_start(p_token);
  IF NOT coalesce((c->>'angemeldet')::boolean, false) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT coalesce((c->>'ok')::boolean, false) THEN
    fehler := coalesce(c->>'fehler', 'Bitte neu anmelden.');
  ELSIF coalesce(d->>'ids', '') = '' THEN
    fehler := 'Bitte zuerst Talents markieren.';
  ELSIF d->>'ids' !~ '^[0-9]{1,9}(,[0-9]{1,9})*$' THEN
    fehler := 'Die Auswahl ist ungültig. Bitte die Seite neu laden.';
  ELSIF cardinality(string_to_array(d->>'ids', ',')) > 1000 THEN
    fehler := 'Höchstens 1.000 Talents auf einmal. Bitte weniger markieren.';
  ELSE
    u := c->>'u';
    ids := ARRAY(SELECT DISTINCT v::integer FROM unnest(string_to_array(d->>'ids', ',')) v);
    IF p_art = 'liste_hinzu' THEN
      SELECT count(*) INTO ohne FROM unnest(ids) i WHERE NOT talent_sichtbar(u, i);
      INSERT INTO talents_meine_liste (person, talent_id) SELECT u, i FROM unnest(ids) i WHERE talent_sichtbar(u, i) ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS n = ROW_COUNT;
      m := CASE WHEN n = 0 AND ohne = 0 THEN 'Diese Talents stehen schon auf deiner Liste.' WHEN n = 0 THEN 'Nichts hinzugefügt.'
                WHEN n = 1 THEN '1 Talent zur Liste hinzugefügt.' ELSE n || ' Talents zur Liste hinzugefügt.' END
           || CASE WHEN n > 0 AND cardinality(ids) - ohne - n > 0 THEN ' ' || (cardinality(ids) - ohne - n) || ' stand' || CASE WHEN cardinality(ids) - ohne - n > 1 THEN 'en' ELSE '' END || ' schon drauf.' ELSE '' END
           || CASE WHEN ohne > 0 THEN ' ' || ohne || CASE WHEN ohne = 1 THEN ' Talent gibt' ELSE ' Talents gibt' END || ' es nicht mehr oder du bist nicht als Manager oder Managerin eingetragen.' ELSE '' END;
    ELSIF p_art = 'liste_entfernen' THEN
      DELETE FROM talents_meine_liste l WHERE l.person = u AND l.talent_id = ANY (ids);
      GET DIAGNOSTICS n = ROW_COUNT;
      m := CASE WHEN n = 0 THEN 'Diese Talents stehen nicht mehr auf deiner Liste.' WHEN n = 1 THEN '1 Talent von der Liste entfernt.' ELSE n || ' Talents von der Liste entfernt.' END;
    ELSE
      fehler := 'Diese Aktion gibt es nicht.';
    END IF;
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_loesch_datei_ergebnis(p_id bigint, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  x talent_loesch_dateien%ROWTYPE; e text;
BEGIN
  SELECT * INTO x FROM talent_loesch_dateien WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Eintrag.'); END IF;
  IF x.erledigt_am IS NOT NULL THEN RETURN jsonb_build_object('ok', true, 'id', x.id, 'erledigt', true, 'ergebnis', x.ergebnis); END IF;
  e := CASE WHEN talents_bericht_ja(d->'fehlt', false) THEN 'fehlte' WHEN talents_bericht_ja(d->'ok', false) THEN 'geloescht'
            WHEN x.versuche + 1 >= 5 THEN 'aufgegeben' END;
  UPDATE talent_loesch_dateien SET versuche = versuche + 1, letzter_versuch = now(), erledigt_am = CASE WHEN e IS NOT NULL THEN now() END, ergebnis = e,
    fehler = CASE WHEN e IN ('geloescht', 'fehlte') THEN NULL ELSE left(coalesce(nullif(btrim(regexp_replace(coalesce(d->>'fehler', ''), '[[:cntrl:]]', ' ', 'g')), ''), 'Unbekannter Fehler.'), 300) END
  WHERE id = p_id;
  RETURN jsonb_build_object('ok', true, 'id', x.id, 'erledigt', e IS NOT NULL, 'ergebnis', e);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_loesch_dateien_liste(p_anzahl integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n integer := least(greatest(coalesce(p_anzahl, 20), 1), 100);
  liste jsonb; offen integer; aufg integer;
BEGIN
  DELETE FROM talent_loesch_dateien WHERE erledigt_am < now() - interval '90 days';
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'dienst', x.dienst, 'bereich', CASE WHEN x.dienst = 'ally' THEN 'ally' END,
      'pfad', x.pfad, 'extern_id', x.extern_id, 'ordner', x.ordner, 'versuche', x.versuche) ORDER BY x.ordner, x.id), '[]'::jsonb) INTO liste
  FROM (SELECT * FROM talent_loesch_dateien d WHERE d.erledigt_am IS NULL AND (d.letzter_versuch IS NULL OR d.letzter_versuch < now() - interval '1 hour')
        ORDER BY d.ordner, d.id LIMIT n) x;
  SELECT count(*) FILTER (WHERE erledigt_am IS NULL)::integer, count(*) FILTER (WHERE ergebnis = 'aufgegeben' AND erledigt_am > now() - interval '7 days')::integer
    INTO offen, aufg FROM talent_loesch_dateien;
  RETURN jsonb_build_object('ok', true, 'anzahl', jsonb_array_length(liste), 'weitere', greatest(offen - jsonb_array_length(liste), 0), 'dateien', liste,
    'hinweis', CASE WHEN aufg > 0 THEN aufg || ' Datei(en) gelöschter Talents ließen sich nach 5 Versuchen nicht löschen. Bitte im Speicherort selbst prüfen.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_loesch_ereignis(p_talent_id integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT 'loeschfrist:t' || t.id || 'a' || to_char(t.archiviert_am AT TIME ZONE 'UTC', 'YYYYMMDDHH24MISS') FROM talents t WHERE t.id = p_talent_id AND t.archiviert_am IS NOT NULL
$function$
;

CREATE OR REPLACE FUNCTION public.talents_loesch_frueheste(p_talent_id integer)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
AS $function$
  -- Frühester Löschtermin eines archivierten Talents (Stefan 19.10.2026, Migration 54). NULL = wird nicht automatisch gelöscht.
  -- Nie vor Archivierung + Löschfrist. Ankündigung: Chat-Ankündigung zugestellt (talent_meldungen_talent) -> deren Zeitpunkt (wie bisher);
  -- sonst Beginn der Ankündigung über die Oberfläche (talent_loesch_ankuendigungen.faellig_seit); sonst noch nicht angekündigt
  -- (frühestens ab jetzt bzw. ab Öffnung des Warnfensters). Danach jeweils talents_loeschwarnung_tage (Standard 14) Vorlauf.
  SELECT greatest(t.archiviert_am + make_interval(days => f.frist),
                  coalesce(m.gemeldet_am, a.faellig_seit,
                           greatest(now(), t.archiviert_am + make_interval(days => f.frist) - make_interval(days => w.tage)))
                  + make_interval(days => w.tage))
  FROM talents t
  CROSS JOIN LATERAL (SELECT CASE WHEN btrim(coalesce(ally_einstellung('talents_loeschfrist_tage'), '')) ~ '^[0-9]{1,4}$'
                                   AND btrim(ally_einstellung('talents_loeschfrist_tage'))::integer BETWEEN 1 AND 3650
                              THEN btrim(ally_einstellung('talents_loeschfrist_tage'))::integer END AS frist) f
  CROSS JOIN LATERAL (SELECT talents_einstellung_zahl('talents_loeschwarnung_tage', 1, 90, 14) AS tage) w
  LEFT JOIN talent_meldungen_talent m ON m.talent_id = t.id AND m.ereignis = talents_loesch_ereignis(t.id)
  LEFT JOIN talent_loesch_ankuendigungen a ON a.talent_id = t.id AND a.ereignis = talents_loesch_ereignis(t.id)
  WHERE t.id = p_talent_id AND t.status = 'archiviert' AND t.archiviert_am IS NOT NULL AND f.frist IS NOT NULL
$function$
;

CREATE OR REPLACE FUNCTION public.talents_loesch_termin(p_talent_id integer)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
AS $function$
  SELECT greatest(t.archiviert_am + make_interval(days => f.frist),
                  coalesce((SELECT m.gemeldet_am FROM talent_meldungen_talent m WHERE m.talent_id = t.id AND m.ereignis = talents_loesch_ereignis(t.id)), now())
                  + make_interval(days => talents_einstellung_zahl('talents_loeschwarnung_tage', 1, 90, 14)))
  FROM talents t CROSS JOIN LATERAL (SELECT CASE WHEN btrim(coalesce(ally_einstellung('talents_loeschfrist_tage'), '')) ~ '^[0-9]{1,4}$'
                                                 AND btrim(ally_einstellung('talents_loeschfrist_tage'))::integer BETWEEN 1 AND 3650
                                            THEN btrim(ally_einstellung('talents_loeschfrist_tage'))::integer END AS frist) f
  WHERE t.id = p_talent_id AND t.status = 'archiviert' AND t.archiviert_am IS NOT NULL AND f.frist IS NOT NULL
$function$
;

CREATE OR REPLACE FUNCTION public.talents_loeschfrist_ausfuehren()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  t record; geloescht jsonb := '[]'::jsonb; meldungen jsonb := '[]'::jsonb; offen integer; imp integer;
  lg jsonb; yt jsonb; dat_offen integer; naechst timestamptz;
BEGIN
  -- YouTube-Daten unbestätigter Kanäle am Tag 30 löschen (Pflicht, auch ohne gebuchtes Paket) (Stefan 18.10.2026)
  yt := talents_youtube_daten_loeschen();
  meldungen := meldungen || (yt->'meldungen');
  -- Importe (Namen, E-Mail-Adressen) nach 7 Tagen löschen
  DELETE FROM talent_importe WHERE erstellt_am < now() - interval '7 days';
  GET DIAGNOSTICS imp = ROW_COUNT;
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', true, 'anzahl', 0, 'geloescht', '[]'::jsonb, 'meldungen', meldungen, 'wartet_auf_ankuendigung', 0, 'hinweis', 'Das Paket Talents ist nicht gebucht.',
      'youtube', yt - 'meldungen', 'dateien_offen', (SELECT count(*)::integer FROM talent_loesch_dateien WHERE erledigt_am IS NULL));
  END IF;
  -- Löschen hängt nicht mehr am Chat (Stefan 19.10.2026, Migration 54): Sobald die Ankündigung fällig ist (Warnfenster offen, wie in
  -- talents_warnungen) und keine Chat-Ankündigung zugestellt wurde, wird der Beginn vermerkt. Die Oberfläche zeigt den Termin die ganze Zeit
  -- ("frühestens am"); nach talents_loeschwarnung_tage ohne Zustellung gilt die Löschung als über die Oberfläche angekündigt. Zugestellte
  -- Chat-Ankündigungen gelten wie bisher (deren Zeitpunkt + Warnfrist). Nichts wird früher gelöscht als mit sofort zugestellter Ankündigung.
  DELETE FROM talent_loesch_ankuendigungen a WHERE NOT EXISTS (SELECT 1 FROM talents x WHERE x.id = a.talent_id AND x.status = 'archiviert'
    AND talents_loesch_termin(x.id) IS NOT NULL AND a.ereignis = talents_loesch_ereignis(x.id));
  INSERT INTO talent_loesch_ankuendigungen (talent_id, ereignis, faellig_seit)
  SELECT x.id, talents_loesch_ereignis(x.id), now() FROM talents x
  WHERE x.status = 'archiviert' AND talents_loesch_termin(x.id) IS NOT NULL
    AND now() >= talents_loesch_termin(x.id) - make_interval(days => talents_einstellung_zahl('talents_loeschwarnung_tage', 1, 90, 14))
    AND NOT EXISTS (SELECT 1 FROM talent_meldungen_talent m WHERE m.talent_id = x.id AND m.ereignis = talents_loesch_ereignis(x.id))
  ON CONFLICT (talent_id) DO NOTHING;
  FOR t IN SELECT x.id, coalesce(talent_anzeigename(x.id), 'Talent Nr. ' || x.id) AS name, m.gemeldet_am, a.faellig_seit, x.archiviert_am, x.testdaten
           FROM talents x
           LEFT JOIN talent_meldungen_talent m ON m.talent_id = x.id AND m.ereignis = talents_loesch_ereignis(x.id)
           LEFT JOIN talent_loesch_ankuendigungen a ON a.talent_id = x.id AND a.ereignis = talents_loesch_ereignis(x.id)
           WHERE x.status = 'archiviert' AND (m.talent_id IS NOT NULL OR a.talent_id IS NOT NULL) AND talents_loesch_frueheste(x.id) <= now()
           ORDER BY x.id FOR UPDATE OF x LOOP
    -- Berichte, KI-Bezüge, Widerrufe; Dateien im Speicherort vorgemerkt (talent_loesch_dateien) (Stefan 18.10.2026)
    lg := talents_talent_loeschen(t.id, 'loeschfrist', NULL);
    geloescht := geloescht || jsonb_build_array(jsonb_build_object('talent_id', t.id, 'name', t.name, 'dateien', lg->'dateien', 'ordner', lg->'ordner',
      'ablage_dateien', lg->'ablage_dateien', 'dateien_vorgemerkt', lg->'dateien_vorgemerkt'));
    -- Testdaten (Migration 79): Test-Talents werden ohne Meldung gelöscht
    CONTINUE WHEN t.testdaten;
    meldungen := meldungen || jsonb_build_array(jsonb_build_object('talent_id', t.id, 'titel', 'Talents: Daten gelöscht',
      'text', 'Die Daten von ' || t.name || ' (im Papierkorb seit ' || talents_datum(t.archiviert_am) || ') wurden nach Ablauf der Löschfrist endgültig gelöscht. '
        || CASE WHEN t.gemeldet_am IS NOT NULL THEN 'Angekündigt am ' || talents_datum(t.gemeldet_am) || '.'
                ELSE 'Die Ankündigung im Chat konnte nicht zugestellt werden; angekündigt war die Löschung über die Oberfläche (Talents-Liste, seit '
                     || talents_datum(t.faellig_seit) || ').' END, 'empfaenger', talents_admin_empfaenger()));
  END LOOP;
  -- Löschfrist erreicht, aber die Ankündigungsfrist läuft noch (Chat oder Oberfläche) (Stefan 19.10.2026)
  SELECT count(*)::integer, min(talents_loesch_frueheste(x.id)) INTO offen, naechst FROM talents x WHERE x.status = 'archiviert' AND talents_loesch_termin(x.id) IS NOT NULL
    AND x.archiviert_am + make_interval(days => talents_einstellung_zahl('talents_loeschfrist_tage', 1, 3650, 0)) <= now();
  SELECT count(*)::integer INTO dat_offen FROM talent_loesch_dateien WHERE erledigt_am IS NULL;
  RETURN jsonb_build_object('ok', true, 'anzahl', jsonb_array_length(geloescht), 'geloescht', geloescht, 'meldungen', meldungen, 'wartet_auf_ankuendigung', offen, 'importe_geloescht', imp,
    'youtube', yt - 'meldungen', 'dateien_offen', dat_offen,
    'hinweis', CASE WHEN offen = 1 THEN 'Ein Talent im Papierkorb hat die Löschfrist erreicht; gelöscht wird es nach der Ankündigungsfrist, frühestens am ' || talents_datum(naechst) || '.'
                    WHEN offen > 1 THEN offen || ' Talents im Papierkorb haben die Löschfrist erreicht; gelöscht werden sie nach der Ankündigungsfrist, das nächste frühestens am ' || talents_datum(naechst) || '.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mail_daten(p_token text, p_talent_id integer, p_seite integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s jsonb := talents_ki_sitzung(p_token, p_talent_id);
  u text;
  seite integer := greatest(1, coalesce(p_seite, 1));
  n integer;
BEGIN
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  u := s->>'u';
  -- Mails nur aus Postfächern, für die die Person zuständig ist
  SELECT count(*) INTO n FROM talent_mail_zuordnung z WHERE z.talent_id = p_talent_id AND z.art = 'talent' AND ally_postfach_zustaendig(u, z.postfach);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'talent_id', p_talent_id,
    'mails', (SELECT coalesce(jsonb_agg(jsonb_build_object('datum', talents_datum(z.eingang) || ' ' || talents_zeit(z.eingang), 'absender', z.absender,
                 'betreff', coalesce(z.betreff, '(ohne Betreff)'), 'postfach', z.postfach) ORDER BY z.eingang DESC, z.id DESC), '[]'::jsonb)
              FROM (SELECT * FROM talent_mail_zuordnung z WHERE z.talent_id = p_talent_id AND z.art = 'talent' AND ally_postfach_zustaendig(u, z.postfach)
                    ORDER BY z.eingang DESC, z.id DESC OFFSET (seite - 1) * 10 LIMIT 10) z),
    'seite', seite, 'seiten', greatest(1, ceil(n::numeric / 10)::integer),
    'entwuerfe', talent_mail_verlauf(p_talent_id),   -- Migration 192: Entwürfe und Versand (Einladungen über Postfach und Systemnachrichten)
    'postfaecher', talents_mail_postfaecher(u),
    'email_hinterlegt', (SELECT coalesce(btrim(t.email), '') ~ '^[^@[:space:]]+@[^@[:space:]]+\.[A-Za-z]{2,}$' FROM talents t WHERE t.id = p_talent_id),
    'einladung_offen', EXISTS (SELECT 1 FROM talent_einladungen e WHERE e.talent_id = p_talent_id AND e.widerrufen_am IS NULL AND e.gueltig_bis > now()),
    'kampagnen', coalesce(talents_ki_kampagnen('des_talents', jsonb_build_object('talent_id', p_talent_id))->'kampagnen', '[]'::jsonb),
    'dateien', talents_ablage_dateien_liste(p_talent_id, '', 1),
    'hinweis', 'Ally legt die Mail nur als Entwurf im Entwurfsordner ab. Verschickt wird sie nur von dir.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mail_entwuerfe_holen(p_anzahl integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  r jsonb := '[]'::jsonb;
  e record;
BEGIN
  UPDATE talent_mail_entwuerfe SET status = CASE WHEN versuche >= 3 THEN 'fehler' ELSE 'offen' END,
    fehler = CASE WHEN versuche >= 3 THEN 'Der Entwurf konnte dreimal nicht abgelegt werden.' ELSE fehler END
  WHERE status = 'laeuft' AND gestartet_am < now() - interval '15 minutes' AND versand = 'entwurf';
  -- Migration 192: Einladungen über ein Postfach (versand senden) ohne Bestätigung nach 15 Minuten „unklar“, nie ein zweiter Versand (Benachrichtigung);
  -- nach 90 Tagen Empfänger und Betreff entfernen (wie Systemnachrichten). Die 3 Versuche gelten nur für Entwürfe.
  FOR e IN UPDATE talent_mail_entwuerfe SET status = 'unklar', fehler = 'Der Versand wurde nicht bestätigt. Die Mail wird nicht noch einmal gesendet.'
           WHERE status = 'laeuft' AND versand = 'senden' AND gestartet_am < now() - interval '15 minutes' RETURNING id LOOP
    PERFORM talent_einladung_fehler_melden('postfach', e.id);
  END LOOP;
  UPDATE talent_mail_entwuerfe SET an = NULL, betreff = '(nach 90 Tagen entfernt)'
  WHERE versand = 'senden' AND status IN ('gesendet', 'fehler', 'verfallen', 'unklar') AND erstellt_am < now() - interval '90 days' AND an IS NOT NULL;
  FOR e IN SELECT x.id FROM talent_mail_entwuerfe x WHERE x.status = 'offen' ORDER BY x.id FOR UPDATE SKIP LOCKED LIMIT greatest(1, least(coalesce(p_anzahl, 5), 20)) LOOP
    IF (SELECT x.versand FROM talent_mail_entwuerfe x WHERE x.id = e.id) = 'senden' THEN   -- Migration 192: Einladung senden (erneut geprüft, Mail mit Link erst hier)
      r := r || talent_einladung_versand_auftrag(e.id);
      CONTINUE;
    END IF;
    UPDATE talent_mail_entwuerfe SET status = 'laeuft', versuche = versuche + 1, gestartet_am = now() WHERE id = e.id;
    r := r || (
      SELECT jsonb_build_array(jsonb_build_object('id', m.id, 'art', m.art, 'postfach', m.postfach, 'an', m.an, 'an_name', m.an_name, 'betreff', m.betreff, 'text', m.text,
        'ordner', coalesce(nullif(btrim(p.entwurf_ordner), ''), nullif(btrim(ally_nutzer_wert(m.erstellt_von, 'entwurf_ordner')), ''), 'Entwürfe'),
        'absender_name', coalesce(nullif(btrim(ally_nutzer_wert(m.erstellt_von, 'absender_name')), ''), nullif(btrim(n.anzeigename), '')),
        'signatur_html', coalesce(nullif(p.signatur_html, ''), ally_nutzer_wert(m.erstellt_von, 'signatur_html')),
        'signatur_text', coalesce(nullif(p.signatur_text, ''), ally_nutzer_wert(m.erstellt_von, 'signatur_text')),
        'signatur_name', coalesce(nullif(btrim(ally_nutzer_wert(m.erstellt_von, 'signatur_name')), ''), nullif(split_part(btrim(coalesce(n.anzeigename, '')), ' ', 1), '')),
        'schrift_stapel', coalesce((SELECT s.stapel FROM mail_schriften s WHERE s.schluessel = p.schrift), 'Helvetica Neue, Helvetica, Arial, sans-serif'),
        'schrift_groesse', coalesce(p.schrift_groesse, 13),
        -- KI-Hinweis wie bei den übrigen Mail-Entwürfen, nur bei Texten der KI
        'ki_hinweis', m.art IN ('kooperation', 'antwort_marke', 'bericht_marke') AND ally_einstellung('ki_hinweis_mail') = 'an',
        'message_id', q.message_id, 'referenzen', q.referenzen,
        'anhaenge', (SELECT coalesce(jsonb_agg(jsonb_build_object('datei_id', d.id, 'name', d.name, 'mime', coalesce(d.mime, 'application/pdf'), 'bytes', d.bytes) ORDER BY d.id), '[]'::jsonb)
                     FROM talent_ablage_dateien d WHERE d.id = ANY (m.anhaenge))))
      FROM talent_mail_entwuerfe m
      LEFT JOIN ally_postfaecher p ON p.adresse = m.postfach
      LEFT JOIN ally_nutzer n ON n.matrix_user_id = m.erstellt_von
      LEFT JOIN mail_rueckfragen q ON q.id = m.antwort_auf
      WHERE m.id = e.id);
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'entwuerfe', r);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mail_entwurf_anlegen(p_token text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  art text := btrim(coalesce(d->>'art', ''));
  tid integer := CASE WHEN d->>'talent_id' ~ '^[0-9]{1,9}$' THEN (d->>'talent_id')::integer END;
  kid integer := CASE WHEN d->>'kampagne_id' ~ '^[0-9]{1,9}$' THEN (d->>'kampagne_id')::integer END;
  xid integer := CASE WHEN d->>'text_id' ~ '^[0-9]{1,9}$' THEN (d->>'text_id')::integer END;
  s jsonb;
  u text;
  pf text := lower(btrim(coalesce(d->>'postfach', '')));
  an text := lower(btrim(coalesce(d->>'an', '')));
  an_name text := talents_ki_kurz(d->>'an_name', 120);
  dateien bigint[] := '{}';
  t talents;
  ein talent_einladungen;
  link text;
  kamp jsonb;
  tx talent_ki_texte;
  betreff text; txt text; f text;
  firma text := coalesce(nullif(btrim(eigenes_unternehmen()->>'name'), ''), 'uns');
  i integer;
  dn text;
BEGIN
  s := talents_ki_sitzung(p_token, tid);
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  u := s->>'u';
  -- Migration 192 (Einladungsmail): versand system bzw. postfach = Einladung senden statt Entwurf (talent_einladung_vormerken; Rechte, Link, Grenzen, Postfach dort).
  IF coalesce(d->>'versand', '') NOT IN ('', 'entwurf') THEN
    RETURN talent_einladung_vormerken(u, tid, art, d->>'versand', pf);
  END IF;
  IF talents_ist_testdaten(tid) THEN  -- Testdaten (Migration 79)
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Für Testdaten werden keine Mail-Entwürfe angelegt.');
  END IF;
  IF art NOT IN ('einladung', 'erinnerung', 'bericht_talent', 'bericht_marke', 'antwort_marke') THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Unbekannte Art des Entwurfs.');
  END IF;
  IF pf = '' THEN
    pf := lower(btrim(coalesce(ally_nutzer_wert(u, 'standard_postfach'), '')));
  END IF;
  f := talents_mail_postfach_fehler(u, pf);
  IF f IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', f);
  END IF;
  IF jsonb_typeof(d->'datei_ids') = 'array' THEN
    SELECT coalesce(array_agg(DISTINCT x.id), '{}') INTO dateien FROM talent_ablage_dateien x
    WHERE x.id IN (SELECT (v #>> '{}')::bigint FROM jsonb_array_elements(d->'datei_ids') v WHERE (v #>> '{}') ~ '^[0-9]{1,15}$')
      AND (x.talent_id IS NULL OR talent_sichtbar(u, x.talent_id));
    IF cardinality(dateien) <> jsonb_array_length(d->'datei_ids') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Eine der gewählten Dateien gibt es nicht. Bitte die Seite neu laden.');
    END IF;
    IF cardinality(dateien) > 5 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Höchstens 5 Anhänge je Entwurf.');
    END IF;
    IF (SELECT coalesce(sum(x.bytes), 0) FROM talent_ablage_dateien x WHERE x.id = ANY (dateien)) > 15 * 1024 * 1024 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Die Anhänge sind zusammen größer als 15 MB. Bitte weniger Dateien wählen.');
    END IF;
  END IF;
  IF tid IS NOT NULL THEN
    SELECT * INTO t FROM talents WHERE id = tid;
  END IF;
  IF art IN ('einladung', 'erinnerung', 'bericht_talent') THEN
    IF t.id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte ein Talent wählen.');
    END IF;
    an := lower(btrim(coalesce(t.email, '')));
    an_name := talent_anzeigename(t.id);
    IF an !~ '^[^@[:space:]]+@[^@[:space:]]+\.[a-z]{2,}$' THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Für ' || coalesce(an_name, 'dieses Talent') || ' ist keine gültige E-Mail hinterlegt (Talent-Profil › Stammdaten).');
    END IF;
  END IF;
  IF art = 'einladung' THEN
    SELECT * INTO ein FROM talent_einladungen e WHERE e.talent_id = t.id AND e.widerrufen_am IS NULL AND e.gueltig_bis > now() ORDER BY e.id DESC LIMIT 1;
    link := talent_einladung_link(ein.id);
    IF ein.id IS NULL OR link IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Für ' || an_name || ' gibt es keinen gültigen Einladungslink. Bitte zuerst „Neuer Link“ wählen.');
    END IF;
    betreff := talent_einladungstext(t.id, link, ein.gueltig_bis)->>'betreff';
    txt := talents_mail_ohne_gruss(talent_einladungstext(t.id, link, ein.gueltig_bis)->>'text');
  ELSIF art IN ('erinnerung', 'bericht_marke') THEN
    kamp := CASE WHEN talents_ki_kampagne_sichtbar(u, kid) THEN talents_ki_kampagnen('info', jsonb_build_object('kampagne_id', kid)) END;
    IF kamp IS NULL OR NOT coalesce((kamp->>'ok')::boolean, false) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', coalesce(kamp->>'fehler', 'Diese Kampagne gibt es nicht oder du bist bei keinem ihrer Talents als Manager oder Managerin eingetragen.'));
    END IF;
    IF art = 'erinnerung' THEN
      IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(kamp->'talents', '[]'::jsonb)) x WHERE (x->>'talent_id')::integer = t.id) THEN
        RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', an_name || ' ist an dieser Kampagne nicht beteiligt.');
      END IF;
      betreff := 'Kampagne ' || coalesce(kamp->>'name', '') || ': dein Beitrag';
      txt := 'Hallo ' || an_name || E',\n\nfür die Kampagne „' || coalesce(kamp->>'name', '') || '“' || coalesce(' von ' || nullif(kamp->>'marke', ''), '')
        || coalesce(' (' || (kamp->>'zeitraum_text') || ')', '') || ' haben wir von dir noch keinen Beitrag gesehen. '
        || E'Magst du uns kurz sagen, wann er kommt? Falls er schon online ist, schick uns bitte den Link.';
    ELSE
      IF an !~ '^[^@[:space:]]+@[^@[:space:]]+\.[a-z]{2,}$' THEN
        RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte die E-Mail-Adresse der Marke angeben.');
      END IF;
      IF cardinality(dateien) = 0 THEN
        RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte den Kampagnenbericht als Anhang wählen.');
      END IF;
      SELECT * INTO tx FROM talent_ki_texte x WHERE x.art = 'kampagne_zusammenfassung' AND x.kampagne_id = kid AND x.status = 'entwurf' ORDER BY x.id DESC LIMIT 1;
      betreff := 'Bericht zur Kampagne ' || coalesce(kamp->>'name', '');
      txt := E'Guten Tag,\n\nanbei der Bericht zur Kampagne „' || coalesce(kamp->>'name', '') || '“' || coalesce(' (' || (kamp->>'zeitraum_text') || ')', '') || '.'
        || coalesce(E'\n\n' || nullif(btrim(tx.text), ''), '') || E'\n\nFür Rückfragen stehen wir gern zur Verfügung.';
    END IF;
  ELSIF art = 'bericht_talent' THEN
    IF cardinality(dateien) = 0 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte den Bericht als Anhang wählen.');
    END IF;
    SELECT string_agg('„' || x.name || '“', ', ' ORDER BY x.id) INTO dn FROM talent_ablage_dateien x WHERE x.id = ANY (dateien);
    betreff := 'Dein Bericht von ' || firma;
    txt := 'Hallo ' || an_name || E',\n\nanbei ' || CASE WHEN cardinality(dateien) = 1 THEN 'dein Bericht ' ELSE 'deine Berichte ' END || dn
      || E'. Wenn du Fragen dazu hast, melde dich gern.';
  ELSE
    SELECT * INTO tx FROM talent_ki_texte x WHERE x.id = xid AND x.art = 'antwort_marke' AND x.status = 'entwurf'
      AND (x.talent_id IS NULL OR talent_sichtbar(u, x.talent_id));
    IF tx.id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diesen Text gibt es nicht. Bitte die Seite neu laden.');
    END IF;
    IF an !~ '^[^@[:space:]]+@[^@[:space:]]+\.[a-z]{2,}$' THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte die E-Mail-Adresse der Marke angeben.');
    END IF;
    betreff := coalesce(nullif(btrim(tx.titel), ''), 'Ihre Anfrage');
    txt := talents_mail_ohne_gruss(tx.text);
  END IF;
  INSERT INTO talent_mail_entwuerfe (art, talent_id, kampagne_id, postfach, an, an_name, betreff, text, anhaenge, erstellt_von)
  VALUES (art, t.id, kid, pf, an, an_name, left(betreff, 300), left(txt, 20000), dateien, u)
  RETURNING id INTO i;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'entwurf_id', i,
    'meldung', 'Der Entwurf wird im Entwurfsordner von ' || pf || ' abgelegt. Verschickt wird er nur von dir.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mail_entwurf_ergebnis(p_id integer, p_ok boolean, p_fehler text DEFAULT NULL::text, p_test boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  e talent_mail_entwuerfe;
BEGIN
  SELECT * INTO e FROM talent_mail_entwuerfe WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Entwurf.');
  END IF;
  IF e.versand = 'senden' THEN   -- Migration 192: Einladung über ein Postfach (gesendet bzw. Fehler ohne neuen Versuch)
    RETURN talent_einladung_versand_ergebnis(p_id, p_ok, p_fehler, p_test);
  END IF;
  IF p_test THEN
    UPDATE talent_mail_entwuerfe SET status = 'offen', versuche = greatest(0, versuche - 1) WHERE id = p_id;
  ELSIF p_ok THEN
    UPDATE talent_mail_entwuerfe SET status = 'abgelegt', abgelegt_am = now(), fehler = NULL WHERE id = p_id;
  ELSE
    UPDATE talent_mail_entwuerfe SET status = CASE WHEN versuche >= 3 THEN 'fehler' ELSE 'offen' END, fehler = left(talents_text_sauber(coalesce(p_fehler, 'unbekannt')), 300)
    WHERE id = p_id;
  END IF;
  RETURN jsonb_build_object('ok', true, 'id', p_id, 'status', (SELECT status FROM talent_mail_entwuerfe WHERE id = p_id));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mail_ohne_gruss(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT btrim(regexp_replace(coalesce(p, ''), '\n\s*(Viele Grüße|Liebe Grüße|Beste Grüße|Herzliche Grüße|Mit freundlichen Grüßen|Freundliche Grüße)[^\n]*(\n[^\n]*)?\s*$', ''), E' \n')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_mail_postfach_fehler(p_user text, p_postfach text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE
    WHEN coalesce(btrim(p_postfach), '') = '' THEN 'Bitte ein Postfach wählen.'
    WHEN NOT EXISTS (SELECT 1 FROM ally_postfaecher p WHERE p.adresse = lower(btrim(p_postfach))) THEN 'Das Postfach ' || lower(btrim(p_postfach)) || ' ist nicht angebunden.'
    WHEN NOT ally_postfach_aktiv(p_postfach) THEN 'Das Postfach ' || lower(btrim(p_postfach)) || ' ist pausiert.'
    WHEN NOT ally_postfach_zustaendig(p_user, p_postfach) THEN 'Das Postfach ' || lower(btrim(p_postfach)) || ' ist für dich nicht freigeschaltet.'
    WHEN NOT coalesce(ally_funktion_an(p_user, (SELECT p.schalter FROM ally_postfaecher p WHERE p.adresse = lower(btrim(p_postfach)))), false)
      THEN 'Mail-Entwürfe für ' || lower(btrim(p_postfach)) || ' sind für dich ausgeschaltet. Einschalten auf der Seite Mail-Entwürfe unter „Für mich“.'
  END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_mail_postfaecher(p_user text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object('adresse', p.adresse, 'name', coalesce(nullif(p.name, ''), p.adresse),
      'standard', p.adresse = lower(btrim(coalesce(ally_nutzer_wert(p_user, 'standard_postfach'), ''))))
      ORDER BY p.sortierung, p.adresse COLLATE "C"), '[]'::jsonb)
  FROM (SELECT p.* FROM ally_postfaecher p WHERE talents_mail_postfach_fehler(p_user, p.adresse) IS NULL ORDER BY p.sortierung, p.adresse LIMIT 10) p
$function$
;

CREATE OR REPLACE FUNCTION public.talents_mails_zuordnen(p_anzahl integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  letzte integer;
  r record;
  m record;
  k jsonb;
  kid integer;
  q integer;
  n_t integer := 0; n_k integer := 0; n_q integer := 0; n integer := 0;
  c integer;
BEGIN
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', true, 'gelesen', 0);
  END IF;
  letzte := CASE WHEN ally_einstellung('talents_mail_letzte_id') ~ '^[0-9]{1,10}$' THEN ally_einstellung('talents_mail_letzte_id')::integer END;
  IF letzte IS NULL THEN
    -- Erster Lauf: die letzten 30 Tage nachholen
    letzte := coalesce((SELECT min(l.id) - 1 FROM mail_klassifizierung_log l WHERE l.created_at > now() - interval '30 days'),
                       (SELECT max(l.id) FROM mail_klassifizierung_log l), 0);
  END IF;
  FOR r IN SELECT l.* FROM mail_klassifizierung_log l WHERE l.id > letzte ORDER BY l.id LIMIT greatest(1, least(coalesce(p_anzahl, 200), 1000)) LOOP
    n := n + 1;
    letzte := r.id;
    IF coalesce(btrim(r.sender), '') <> '' THEN
      INSERT INTO talent_mail_zuordnung (log_id, art, talent_id, postfach, message_id, absender, betreff, eingang)
      SELECT r.id, 'talent', t.id, r.postfach, r.message_id, lower(btrim(r.sender)), left(r.subject, 300), r.created_at
      FROM talents t WHERE lower(btrim(coalesce(t.email, ''))) = lower(btrim(r.sender))
      ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS c = ROW_COUNT;
      n_t := n_t + c;
      k := talents_ki_kampagnen('fuer_mail', jsonb_build_object('absender', lower(btrim(r.sender)), 'betreff', r.subject, 'datum', r.created_at));
      IF k IS NOT NULL AND jsonb_typeof(k->'kampagne_ids') = 'array' THEN
        FOR kid IN SELECT (x #>> '{}')::integer FROM jsonb_array_elements(k->'kampagne_ids') x WHERE (x #>> '{}') ~ '^[0-9]{1,9}$' LOOP
          INSERT INTO talent_mail_zuordnung (log_id, art, kampagne_id, postfach, message_id, absender, betreff, eingang)
          VALUES (r.id, 'kampagne', kid, r.postfach, r.message_id, lower(btrim(r.sender)), left(r.subject, 300), r.created_at)
          ON CONFLICT DO NOTHING;
          GET DIAGNOSTICS c = ROW_COUNT;
          n_k := n_k + c;
        END LOOP;
      END IF;
    END IF;
    IF r.kategorie_key = 'kooperation' AND NOT EXISTS (SELECT 1 FROM talent_mail_zuordnung z WHERE z.log_id = r.id AND z.art = 'kooperation') THEN
      SELECT x.* INTO m FROM mail_rueckfragen x WHERE x.postfach = r.postfach AND x.message_id = r.message_id ORDER BY x.id DESC LIMIT 1;
      INSERT INTO talent_ki_anfragen (quelle, anfrage, mail_id)
      VALUES ('mail', left('Von: ' || coalesce(nullif(m.absender_name, '') || ' ', '') || coalesce(m.absender, r.sender, '') || E'\n'
                          || 'Betreff: ' || coalesce(m.betreff, r.subject, '') || E'\n\n'
                          || coalesce(talents_ki_kurz(m.inhalt, 10000), '(Der Text der Mail liegt nicht vor, nur der Betreff.)'), 12000),
              m.id)
      RETURNING id INTO q;
      UPDATE talent_ki_anfragen SET ki_auftrag_id = talents_ki_auftrag_anlegen('kooperation', NULL, q, NULL) WHERE id = q;
      INSERT INTO talent_mail_zuordnung (log_id, art, postfach, message_id, absender, betreff, eingang, anfrage_id)
      VALUES (r.id, 'kooperation', r.postfach, r.message_id, lower(btrim(coalesce(r.sender, ''))), left(r.subject, 300), r.created_at, q);
      n_q := n_q + 1;
    END IF;
  END LOOP;
  IF n > 0 THEN
    PERFORM ally_einstellung_setzen('talents_mail_letzte_id', letzte::text, 'TALENTS KI-Aufträge');
  ELSIF ally_einstellung('talents_mail_letzte_id') = '' THEN
    PERFORM ally_einstellung_setzen('talents_mail_letzte_id', letzte::text, 'TALENTS KI-Aufträge');
  END IF;
  RETURN jsonb_build_object('ok', true, 'gelesen', n, 'talents', n_t, 'kampagnen', n_k, 'kooperationen', n_q, 'letzte_id', letzte);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_absender(p_email text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN count(*) = 1 THEN jsonb_build_object('ok', true, 'talent_id', min(t.id), 'anzeigename', talent_listenname(min(t.id)))
              WHEN count(*) = 0 THEN jsonb_build_object('ok', false, 'grund', 'unbekannt', 'fehler', 'Kein aktives Talent mit dieser E-Mail-Adresse.')
              ELSE jsonb_build_object('ok', false, 'grund', 'mehrdeutig', 'fehler', 'Mehrere Talents haben diese E-Mail-Adresse.') END
  FROM talents t
  WHERE t.status = 'aktiv' AND t.email IS NOT NULL
    AND t.email = lower(btrim(substring(coalesce(p_email, '') FROM '([^<>[:space:]]+@[^<>[:space:]]+)')))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_filter(p_filter jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Filter „Manuelle Daten einbeziehen“ (Stefan 20.10.2026, 09:23): Standard an; manuell = '0' nimmt die manuellen Daten heraus (Migration 65)
  SELECT coalesce(CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter->>'manuell' END, '1') <> '0'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_kanaele(p_talent_id integer, p_plattform text, p_konto text)
 RETURNS integer[]
 LANGUAGE sql
 STABLE
AS $function$
  -- Doppelte Daten (Migration 65, Stefan 20.10.2026): Zu welchen Accounts des Talents gehört ein manueller Wert? Nur Accounts, die schon einmal verbunden waren.
  -- Mit Konto-Angabe: Account mit gleichem Namen. Instagram, Threads, Pinterest speichern den @-Namen; YouTube, TikTok, Facebook nur einen Anzeigenamen –
  -- passt dort kein Name, gelten vorsichtshalber alle Accounts der Plattform. Ohne Konto-Angabe: alle Accounts der Plattform.
  WITH k AS (SELECT k.id, lower(ltrim(btrim(coalesce(k.extern_name, '')), '@')) AS n FROM talent_kanaele k
             WHERE k.talent_id = p_talent_id AND k.plattform = p_plattform AND k.extern_id IS NOT NULL),
  w AS (SELECT lower(ltrim(btrim(coalesce(p_konto, '')), '@')) AS n)
  SELECT coalesce(CASE
      WHEN w.n = '' THEN (SELECT array_agg(k.id ORDER BY k.id) FROM k)
      WHEN EXISTS (SELECT 1 FROM k WHERE k.n = w.n) THEN (SELECT array_agg(k.id ORDER BY k.id) FROM k WHERE k.n = w.n)
      WHEN p_plattform IN ('youtube', 'tiktok', 'facebook') THEN (SELECT array_agg(k.id ORDER BY k.id) FROM k) END, '{}'::integer[])
  FROM w
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_kanal(p_talent_id integer, p_von date, p_bis date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Instagram-Kanal (Broadcast Channel) für Talent-Seite und Berichte (Stefan 19.10.2026, Migration 55): je Kennzahl der passende bestätigte Wert
  -- (Mitglieder: letzter Stand bis zum Ende des Zeitraums; übrige: ganz im Zeitraum, längster Zeitraum zuerst), gleiche Form wie talents_manuell_konto.
  WITH w AS (
    SELECT DISTINCT ON (m.kennzahl) m.*
    FROM talent_manuell_werte m
    WHERE m.talent_id = p_talent_id AND m.bereich = 'kanal'
      AND CASE WHEN m.kennzahl = 'mitglieder' THEN m.bis <= p_bis ELSE m.von >= p_von AND m.bis <= p_bis END
    ORDER BY m.kennzahl, CASE WHEN m.kennzahl = 'mitglieder' THEN 0 ELSE m.bis - m.von END DESC, m.bis DESC, m.bestaetigt_am DESC, m.id DESC)
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', w.id, 'plattform', w.plattform, 'plattform_name', 'Instagram-Kanal', 'konto', w.konto,
      'kennzahl', w.kennzahl, 'name', talents_manuell_kennzahl_name('kanal', w.kennzahl), 'wert', w.wert, 'text', talents_zahl_text(w.wert),
      'von', to_char(coalesce(w.von, w.bis), 'YYYY-MM-DD'), 'bis', to_char(w.bis, 'YYYY-MM-DD'), 'zeitraum_text', talents_manuell_zeitraum_text(w.von, w.bis),
      'quelle_text', w.quelle_text) ORDER BY array_position(ARRAY['mitglieder', 'interaktionen', 'geteilt', 'umfrage_stimmen'], w.kennzahl), w.kennzahl), '[]'::jsonb)
  FROM w
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_kennzahl_name(p_bereich text, p_kennzahl text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT coalesce((SELECT x->>'name' FROM jsonb_array_elements(talents_manuell_kennzahlen()) x WHERE x->>'bereich' = p_bereich AND x->>'schluessel' = p_kennzahl), p_kennzahl)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_kennzahlen()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Bereich kanal = Instagram-Kanal (Broadcast Channel), nur Instagram, getrennt vom Konto (Stefan 19.10.2026). Kennzahlen laut Meta (Social Media Today, 04.12.2024):
  -- Gesamtinteraktionen, Teilen, Umfrage-Stimmen; Mitglieder nur, wenn im Screenshot sichtbar (nicht in der Quelle).
  SELECT '[
    {"bereich": "konto", "schluessel": "follower", "name": "Follower", "stand": true},
    {"bereich": "konto", "schluessel": "reichweite", "name": "Reichweite", "stand": false},
    {"bereich": "konto", "schluessel": "aufrufe", "name": "Aufrufe", "stand": false},
    {"bereich": "konto", "schluessel": "interaktionen", "name": "Interaktionen", "stand": false},
    {"bereich": "konto", "schluessel": "profilaufrufe", "name": "Profilaufrufe", "stand": false},
    {"bereich": "konto", "schluessel": "beitraege", "name": "Anzahl Beiträge", "stand": false},
    {"bereich": "beitrag", "schluessel": "aufrufe", "name": "Aufrufe", "stand": true},
    {"bereich": "beitrag", "schluessel": "reichweite", "name": "Reichweite", "stand": true},
    {"bereich": "beitrag", "schluessel": "interaktionen", "name": "Interaktionen", "stand": true},
    {"bereich": "beitrag", "schluessel": "likes", "name": "Likes", "stand": true},
    {"bereich": "beitrag", "schluessel": "kommentare", "name": "Kommentare", "stand": true},
    {"bereich": "beitrag", "schluessel": "speicherungen", "name": "Speicherungen", "stand": true},
    {"bereich": "beitrag", "schluessel": "geteilt", "name": "Geteilt", "stand": true},
    {"bereich": "zielgruppe", "schluessel": "follower_demographics:age", "name": "Follower nach Alter", "stand": true},
    {"bereich": "zielgruppe", "schluessel": "follower_demographics:gender", "name": "Follower nach Geschlecht", "stand": true},
    {"bereich": "zielgruppe", "schluessel": "follower_demographics:country", "name": "Follower nach Land", "stand": true},
    {"bereich": "zielgruppe", "schluessel": "follower_demographics:city", "name": "Follower nach Stadt", "stand": true},
    {"bereich": "kanal", "schluessel": "mitglieder", "name": "Mitglieder", "stand": true},
    {"bereich": "kanal", "schluessel": "interaktionen", "name": "Gesamtinteraktionen", "stand": false},
    {"bereich": "kanal", "schluessel": "geteilt", "name": "Teilen", "stand": false},
    {"bereich": "kanal", "schluessel": "umfrage_stimmen", "name": "Umfrage-Stimmen", "stand": false}]'::jsonb
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_konto(p_talent_id integer, p_plattformen text[], p_von date, p_bis date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Zahlen ohne Verbindung (Konto) zur Anzeige. Migration 65 (Stefan 20.10.2026): alle Werte statt einem je Plattform und Kennzahl; Follower: letzter Stand je
  -- Plattform und Account bis zum Ende des Zeitraums, übrige: ganz im Zeitraum. Archivierte Werte (Entscheidung „automatischen Wert behalten“) fehlen;
  -- offene doppelte Daten sind gekennzeichnet (zaehlt = false). Ob ein Wert in die Summen eingeht, entscheidet talents_zahlen.
  WITH w AS (
    SELECT m.*, talents_doppelt_status(m.id) AS st,
      row_number() OVER (PARTITION BY m.plattform, lower(coalesce(m.konto, '')), m.kennzahl ORDER BY m.bis DESC, m.bestaetigt_am DESC, m.id DESC) AS nr
    FROM talent_manuell_werte m
    WHERE m.talent_id = p_talent_id AND m.bereich = 'konto' AND (p_plattformen IS NULL OR m.plattform = ANY (p_plattformen))
      AND CASE WHEN m.kennzahl = 'follower' THEN m.bis <= p_bis ELSE m.von >= p_von AND m.bis <= p_bis END),
  v AS (SELECT * FROM w WHERE (w.kennzahl <> 'follower' OR w.nr = 1) AND coalesce(w.st->>'status', 'keins') <> 'automatisch')
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'plattform', v.plattform, 'plattform_name', talents_plattform_name(v.plattform), 'konto', v.konto,
      'kennzahl', v.kennzahl, 'name', talents_manuell_kennzahl_name('konto', v.kennzahl), 'wert', v.wert, 'text', talents_zahl_text(v.wert),
      'von', to_char(coalesce(v.von, v.bis), 'YYYY-MM-DD'), 'bis', to_char(v.bis, 'YYYY-MM-DD'), 'zeitraum_text', talents_manuell_zeitraum_text(v.von, v.bis),
      'quelle_text', v.quelle_text, 'status', coalesce(v.st->>'status', 'keins'), 'zaehlt', coalesce((v.st->>'zaehlt')::boolean, false),
      'status_text', CASE v.st->>'status' WHEN 'offen' THEN 'doppelt – zählt bis zur Entscheidung nicht' WHEN 'manuell' THEN 'zählt statt der automatischen Zahlen' END)
      ORDER BY array_position(talents_plattformen(), v.plattform), v.kennzahl, v.bis DESC, v.id DESC), '[]'::jsonb)
  FROM v
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_signatur(p_id bigint)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Fingerabdruck eines manuellen Werts (Plattform, Konto, Bereich, Kennzahl, Zeitraum, Wert): ändert er sich, gilt eine Entscheidung nicht mehr (Migration 65)
  SELECT md5(concat_ws('|', m.plattform, lower(ltrim(btrim(coalesce(m.konto, '')), '@')), m.bereich, m.kennzahl,
                       to_char(coalesce(m.von, m.bis), 'YYYY-MM-DD'), to_char(m.bis, 'YYYY-MM-DD'), coalesce(m.wert::text, m.werte::text, '')))
  FROM talent_manuell_werte m WHERE m.id = p_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_ueberschneidung(p_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Doppelte Daten (Stefan 20.10.2026, 09:26): gibt es für denselben Account, dieselbe Kennzahl und denselben Zeitraum automatisch geladene Zahlen?
  -- Stand-Kennzahl (Follower): automatischer Stand am selben Tag. Zeitraum-Kennzahlen: mindestens ein automatischer Tageswert im Zeitraum. NULL = keine Überschneidung.
  WITH m AS (
    SELECT m.*, coalesce(m.von, m.bis) AS ab, talents_manuell_kanaele(m.talent_id, m.plattform, m.konto) AS ks
    FROM talent_manuell_werte m
    WHERE m.id = p_id AND m.bereich = 'konto' AND m.kennzahl IN ('follower', 'reichweite', 'aufrufe', 'interaktionen', 'profilaufrufe')),
  t AS (
    SELECT kt.kanal_id, kt.tag, talents_tageswert(kt.werte, m.kennzahl) AS w
    FROM m JOIN talent_kanal_tage kt ON kt.kanal_id = ANY (m.ks) AND kt.tag BETWEEN m.ab AND m.bis
    WHERE talents_tageswert(kt.werte, m.kennzahl) IS NOT NULL)
  SELECT CASE WHEN EXISTS (SELECT 1 FROM t) THEN jsonb_build_object(
      'kanaele', to_jsonb(ARRAY(SELECT DISTINCT t.kanal_id FROM t ORDER BY 1)),
      'wert', (SELECT sum(t.w) FROM t),
      'tage', (SELECT count(DISTINCT t.tag) FROM t),
      'tage_soll', (SELECT m.bis - m.ab + 1 FROM m),
      'von', (SELECT to_char(min(t.tag), 'YYYY-MM-DD') FROM t),
      'bis', (SELECT to_char(max(t.tag), 'YYYY-MM-DD') FROM t),
      'accounts', (SELECT string_agg(talents_konto_text(k.plattform, k.extern_name, NULL), ', ' ORDER BY k.id)
                   FROM talent_kanaele k WHERE k.id IN (SELECT DISTINCT t.kanal_id FROM t))) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_vorschlag_anlegen(p_user text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  q text := lower(btrim(coalesce(d->>'quelle', '')));
  c jsonb;
  n jsonb;
  tid integer;
  typ text := lower(btrim(coalesce(d->>'datei_typ', '')));
  gr bigint := CASE WHEN coalesce(d->>'datei_groesse', '') ~ '^[0-9]{1,12}$' THEN (d->>'datei_groesse')::bigint ELSE 0 END;
  dn text := left(btrim(regexp_replace(coalesce(d->>'datei_name', ''), '[[:cntrl:]/\\]', '_', 'g')), 120);
  art text;
  ende text;
  qt text;
  v_id bigint;
  md date;
  pfad text;
BEGIN
  IF q NOT IN ('hochladen', 'mail', 'chat') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte Quelle.');
  END IF;
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  -- Talent bestimmen
  IF q = 'mail' THEN
    n := talents_manuell_absender(d->>'absender');
    IF NOT (n->>'ok')::boolean THEN
      RETURN n;
    END IF;
    tid := (n->>'talent_id')::integer;
  ELSE
    c := talents_person_zugriff(p_user);
    IF NOT (c->>'ok')::boolean THEN
      RETURN c;
    END IF;
    IF coalesce(d->>'talent_id', '') ~ '^[0-9]{1,9}$' THEN
      tid := (d->>'talent_id')::integer;
    ELSIF btrim(coalesce(d->>'talent', '')) <> '' THEN
      n := talents_chat_finden(p_user, d->>'talent');
      IF NOT (n->>'ok')::boolean THEN
        RETURN n;
      END IF;
      tid := (n->>'talent_id')::integer;
    END IF;
    IF tid IS NULL OR NOT talent_sichtbar(p_user, tid) THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Dieses Talent gibt es nicht oder du bist nicht als Manager oder Managerin eingetragen.');
    END IF;
    -- Migration 66: nur, wer das Talent verwalten darf
    IF NOT talent_verwaltbar(p_user, tid) THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Zahlen ohne Verbindung ändert, wer das Recht „Talents und Kampagnen verwalten“ für dieses Talent hat.');
    END IF;
  END IF;
  -- Dateiart und Größe (Grenzen der KI-Schnittstelle: Bilder bis 5 MB, PDF bis 10 MB hier gewählt; Text bis 2 MB)
  art := CASE WHEN typ = 'application/pdf' THEN 'pdf'
              WHEN typ IN ('image/png', 'image/jpeg', 'image/webp', 'image/gif') THEN 'bild'
              WHEN typ IN ('text/plain', 'text/csv', 'application/json', 'text/tab-separated-values') THEN 'text' END;
  IF art IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Dateiart kann Ally nicht lesen. Möglich sind Bilder (PNG, JPG, WEBP), PDF und Plattform-Exporte als CSV, TXT oder JSON (keine ZIP-Dateien).');
  END IF;
  IF (art = 'bild' AND gr > 5242880) OR (art = 'pdf' AND gr > 10485760) OR (art = 'text' AND gr > 2097152) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Datei ist zu groß. Möglich sind Bilder bis 5 MB, PDF bis 10 MB und Text bis 2 MB.');
  END IF;
  IF gr = 0 AND q <> 'chat' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Datei ist leer.');
  END IF;
  -- Kosten begrenzen: höchstens 20 Vorschläge je Talent und Tag, höchstens 5 gleichzeitig beim Auslesen
  IF (SELECT count(*) FROM talent_manuell_vorschlaege v WHERE v.talent_id = tid AND v.erstellt_am > now() - interval '1 day') >= 20 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Für dieses Talent wurden heute schon 20 Dateien ausgelesen. Bitte morgen weitermachen.');
  END IF;
  IF (SELECT count(*) FROM talent_manuell_vorschlaege v WHERE v.status = 'auslesen' AND v.erstellt_am > now() - interval '15 minutes') >= 5 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Ally liest gerade schon fünf Dateien aus. Bitte in ein paar Minuten noch einmal versuchen.');
  END IF;
  md := coalesce(talents_bericht_datum(d->>'mail_datum'), talents_heute());
  qt := CASE q WHEN 'mail' THEN 'Mail vom ' || to_char(md, 'DD.MM.YYYY') || coalesce(' (' || nullif(lower(btrim(substring(coalesce(d->>'absender', '') FROM '([^<>[:space:]]+@[^<>[:space:]]+)'))), '') || ')', '')
               WHEN 'chat' THEN 'Chat am ' || to_char(talents_heute(), 'DD.MM.YYYY')
               ELSE 'Hochgeladen am ' || to_char(talents_heute(), 'DD.MM.YYYY') END
        || CASE WHEN dn <> '' THEN ', Datei ' || dn ELSE '' END;
  IF talents_ist_testdaten(tid) THEN  -- Testdaten (Migration 79): keine KI zum Auslesen
    RETURN jsonb_build_object('ok', false, 'fehler', 'Bei Testdaten werden keine Zahlen aus Dateien gelesen.');
  END IF;
  INSERT INTO talent_manuell_vorschlaege (talent_id, quelle, quelle_text, datei_name, datei_typ, erstellt_von)
  VALUES (tid, q, left(qt, 300), nullif(dn, ''), typ, nullif(btrim(coalesce(p_user, '')), ''))
  RETURNING id INTO v_id;
  ende := CASE art WHEN 'pdf' THEN '.pdf' WHEN 'text' THEN CASE typ WHEN 'text/csv' THEN '.csv' WHEN 'application/json' THEN '.json' ELSE '.txt' END
                   ELSE CASE typ WHEN 'image/png' THEN '.png' WHEN 'image/webp' THEN '.webp' WHEN 'image/gif' THEN '.gif' ELSE '.jpg' END END;
  pfad := talents_bericht_ordner(tid) || '/Zahlen-Eingang/' || to_char(now() AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD') || '_' || v_id || '_'
          || talents_bericht_sauber(regexp_replace(coalesce(nullif(dn, ''), q), '\.[A-Za-z0-9]{1,5}$', ''), 40) || ende;
  UPDATE talent_manuell_vorschlaege SET datei_pfad = CASE WHEN gr > 0 THEN pfad END WHERE id = v_id;
  RETURN jsonb_build_object('ok', true, 'vorschlag_id', v_id, 'talent_id', tid, 'anzeigename', talent_listenname(tid), 'art', art, 'datei_typ', typ,
    'datei_pfad', CASE WHEN gr > 0 THEN pfad END, 'quelle_text', left(qt, 300),
    'ki', jsonb_build_object('modell', ki_modell('einfach'), 'gesperrt', ki_gesperrt(), 'sperre_text', ki_sperre_text()),
    'kontext', jsonb_build_object('heute', to_char(talents_heute(), 'YYYY-MM-DD'), 'eingang', to_char(md, 'YYYY-MM-DD'),
      'plattformen', coalesce((SELECT jsonb_agg(DISTINCT k.plattform) FROM talent_kanaele k WHERE k.talent_id = tid), '[]'::jsonb),
      'konten', coalesce((SELECT jsonb_agg(DISTINCT '@' || ltrim(btrim(k.extern_name), '@')) FROM talent_kanaele k WHERE k.talent_id = tid AND nullif(btrim(coalesce(k.extern_name, '')), '') IS NOT NULL), '[]'::jsonb),
      'kennzahlen', (SELECT jsonb_agg(jsonb_build_object('bereich', x->>'bereich', 'kennzahl', x->>'schluessel', 'name', x->>'name')) FROM jsonb_array_elements(talents_manuell_kennzahlen()) x)));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_vorschlag_ergebnis(p_id bigint, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  v record;
  std text;
  liste jsonb := '[]'::jsonb;
  hin jsonb;
  x jsonb;
  w jsonb;
  nr integer := 0;
  verworfen integer := 0;
BEGIN
  SELECT * INTO v FROM talent_manuell_vorschlaege y WHERE y.id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diesen Vorschlag gibt es nicht.');
  END IF;
  IF v.status <> 'auslesen' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Dieser Vorschlag ist schon ausgelesen.');
  END IF;
  IF nullif(btrim(coalesce(d->>'fehler', '')), '') IS NOT NULL THEN
    UPDATE talent_manuell_vorschlaege SET status = 'fehler', fehler = left(btrim(d->>'fehler'), 500) WHERE id = p_id;
    RETURN jsonb_build_object('ok', true, 'vorschlag_id', p_id, 'talent_id', v.talent_id, 'anzahl', 0, 'fehlgeschlagen', true,
      'text', 'Die Zahlen von ' || talent_listenname(v.talent_id) || ' konnten nicht ausgelesen werden: ' || left(btrim(d->>'fehler'), 300)
              || ' Du kannst die Werte auf der Seite des Talents unter „Zahlen ohne Verbindung“ von Hand eintragen.');
  END IF;
  -- Standard-Plattform: aus dem Ergebnis, sonst die einzige Plattform des Talents
  std := lower(btrim(coalesce(d->>'plattform', '')));
  IF NOT std = ANY (talents_plattformen()) THEN
    SELECT CASE WHEN count(DISTINCT k.plattform) = 1 THEN min(k.plattform) END INTO std FROM talent_kanaele k WHERE k.talent_id = v.talent_id;
  END IF;
  FOR x IN SELECT e FROM jsonb_array_elements(CASE WHEN jsonb_typeof(d->'werte') = 'array' THEN d->'werte' ELSE '[]'::jsonb END) e LIMIT 60 LOOP
    w := talents_manuell_wert_lesen(CASE WHEN jsonb_typeof(x) = 'object' THEN x || CASE WHEN x->>'konto' IS NULL AND d->>'konto' IS NOT NULL THEN jsonb_build_object('konto', d->>'konto') ELSE '{}'::jsonb END ELSE '{}'::jsonb END,
                                    nr + 1, coalesce(std, ''));
    IF w IS NULL THEN
      verworfen := verworfen + 1;
    ELSE
      nr := nr + 1;
      liste := liste || jsonb_build_array(w);
    END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(left(btrim(h), 200)), '[]'::jsonb) INTO hin
  FROM (SELECT h FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(d->'hinweise') = 'array' THEN d->'hinweise' ELSE '[]'::jsonb END) h WHERE btrim(h) <> '' LIMIT 5) y;
  IF verworfen > 0 THEN
    hin := hin || to_jsonb(verworfen || CASE WHEN verworfen = 1 THEN ' Angabe war' ELSE ' Angaben waren' END || ' unvollständig oder unbekannt und wurde' || CASE WHEN verworfen = 1 THEN '' ELSE 'n' END || ' weggelassen.');
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(liste) e WHERE jsonb_array_length(e->'fehlt') > 0) THEN
    hin := hin || to_jsonb('Bei einigen Werten fehlt der Zeitraum. Bitte vor dem Bestätigen ergänzen.'::text);
  END IF;
  UPDATE talent_manuell_vorschlaege SET status = 'offen', werte = liste, hinweise = hin, fehler = CASE WHEN nr = 0 THEN 'Keine Zahlen erkannt.' END WHERE id = p_id;
  RETURN jsonb_build_object('ok', true, 'vorschlag_id', p_id, 'talent_id', v.talent_id, 'anzahl', nr,
    'text', CASE WHEN nr = 0 THEN 'In der Datei von ' || talent_listenname(v.talent_id) || ' hat Ally keine Zahlen erkannt. Du kannst sie unter Talents › ' || talent_listenname(v.talent_id) || ' › Zahlen ohne Verbindung von Hand eintragen.'
                 ELSE nr || CASE WHEN nr = 1 THEN ' Wert' ELSE ' Werte' END || ' von ' || talent_listenname(v.talent_id) || ' liegen zur Prüfung bereit (Talents › '
                      || talent_listenname(v.talent_id) || ' › Zahlen ohne Verbindung). Gespeichert wird erst nach deiner Bestätigung.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_web(p_token text, p_talent_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb := talents_ansicht_start(p_token);
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  u text;
  verw boolean;
  je constant integer := 10;
  anzahl integer;
  seiten integer;
  s integer := CASE WHEN coalesce(f->>'seite', '') ~ '^[0-9]{1,6}$' THEN greatest((f->>'seite')::integer, 1) ELSE 1 END;
BEGIN
  IF NOT (c->>'ok')::boolean THEN
    RETURN c;
  END IF;
  u := c->>'u';
  verw := (c->>'verw')::boolean;
  IF NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = p_talent_id) OR NOT talent_sichtbar(u, p_talent_id) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Dieses Talent gibt es nicht oder du bist nicht als Manager oder Managerin eingetragen.');
  END IF;
  SELECT count(*) INTO anzahl FROM talent_manuell_werte m WHERE m.talent_id = p_talent_id;
  seiten := greatest(1, ceil(anzahl / je::numeric)::integer);
  s := least(s, seiten);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'darf_verwalten', verw,
    'talent', jsonb_build_object('id', p_talent_id, 'anzeigename', talent_listenname(p_talent_id)),
    'erklaerung', 'Hier stehen manuelle Daten, die das Talent schickt (Bild, PDF oder Plattform-Export): hochgeladen, per Mail an ein Postfach der Agentur oder im Chat. '
                  || 'Ally liest die Zahlen aus; gespeichert werden sie erst nach deiner Bestätigung. In Reports sind sie als „manuell“ mit Quelle gekennzeichnet. '
                  -- Instagram-Kanal (Stefan 19.10.2026)
                  || 'Auch die Statistik eines Instagram-Kanals (Gesamtinteraktionen, Teilen, Umfrage-Stimmen) lässt sich so übernehmen; sie steht getrennt vom Instagram-Konto.',
    'hochladen', jsonb_build_object('aktion', '/webhook/web/talents-zahlen', 'feld', 'datei', 'accept', 'image/png,image/jpeg,image/webp,application/pdf,.csv,.txt,.json',
      'text', 'Bild (PNG, JPG, WEBP, bis 5 MB), PDF (bis 10 MB) oder Plattform-Export als CSV, TXT oder JSON (bis 2 MB).'),
    'vorschlaege', coalesce((SELECT jsonb_agg(jsonb_build_object('id', v.id, 'status', v.st,
        'status_text', CASE v.st WHEN 'auslesen' THEN 'wird ausgelesen …' WHEN 'offen' THEN 'bitte prüfen' ELSE 'nicht ausgelesen: ' || coalesce(v.fehler, 'Abgebrochen. Bitte erneut starten.') END,
        'quelle_text', v.quelle_text, 'eingang_text', talents_zeit(v.erstellt_am), 'werte', v.werte, 'hinweise', v.hinweise, 'fehler', v.fehler)
        ORDER BY v.erstellt_am DESC, v.id DESC)
      FROM (SELECT y.*, CASE WHEN y.status = 'auslesen' AND y.erstellt_am < now() - interval '15 minutes' THEN 'fehler' ELSE y.status END AS st
            FROM talent_manuell_vorschlaege y WHERE y.talent_id = p_talent_id AND (y.status IN ('auslesen', 'offen') OR (y.status = 'fehler' AND y.erstellt_am > now() - interval '7 days'))
            ORDER BY y.erstellt_am DESC, y.id DESC LIMIT 10) v), '[]'::jsonb),
    'werte', jsonb_build_object('anzahl', anzahl, 'seite', s, 'seiten', seiten, 'je_seite', je,
      'leer_text', CASE WHEN anzahl = 0 THEN 'Noch keine bestätigten Zahlen ohne Verbindung.' END,
      -- Instagram-Kanal als eigene Zeile "Instagram-Kanal" (ohne Bereichszusatz) (Stefan 19.10.2026)
      'zeilen', coalesce((SELECT jsonb_agg(jsonb_build_object('id', m.id, 'plattform_name', CASE WHEN m.bereich = 'kanal' THEN 'Instagram-Kanal' ELSE talents_plattform_name(m.plattform) END, 'konto', m.konto,
          'bereich_name', CASE m.bereich WHEN 'konto' THEN 'Konto' WHEN 'beitrag' THEN 'Beitrag' WHEN 'kanal' THEN NULL ELSE 'Zielgruppe' END,
          'kennzahl_name', talents_manuell_kennzahl_name(m.bereich, m.kennzahl),
          'text', CASE WHEN m.bereich = 'zielgruppe' THEN (SELECT string_agg(e.key || ': ' || talents_zahl_text(talents_zahl(e.value)), ', ' ORDER BY e.key) FROM jsonb_each(m.werte) e)
                       ELSE talents_zahl_text(m.wert) END,
          'zeitraum_text', talents_manuell_zeitraum_text(m.von, m.bis), 'quelle_text', m.quelle_text,
          'bestaetigt_text', talents_zeit(m.bestaetigt_am) || coalesce(' von ' || (SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = m.bestaetigt_von), ''),
          'darf_loeschen', verw OR m.bestaetigt_von = u) ORDER BY m.bis DESC, m.id DESC)
        FROM (SELECT * FROM talent_manuell_werte x WHERE x.talent_id = p_talent_id ORDER BY x.bis DESC, x.id DESC OFFSET (s - 1) * je LIMIT je) m), '[]'::jsonb)),
    'von_hand', jsonb_build_object('plattformen', (SELECT jsonb_agg(jsonb_build_object('schluessel', p, 'name', talents_plattform_name(p)) ORDER BY o)
                                                   FROM unnest(talents_plattformen()) WITH ORDINALITY x(p, o)),
      'kennzahlen', (SELECT jsonb_agg(jsonb_build_object('schluessel', x->>'schluessel', 'name', x->>'name', 'stand', (x->>'stand')::boolean))
                     FROM jsonb_array_elements(talents_manuell_kennzahlen()) x WHERE x->>'bereich' = 'konto'),
      'plattform_vorschlag', (SELECT k.plattform FROM talent_kanaele k WHERE k.talent_id = p_talent_id ORDER BY array_position(talents_plattformen(), k.plattform), k.id LIMIT 1)));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_web_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb := talents_ansicht_start(p_token);
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  u text;
  verw boolean;
  tid integer;
  v record;
  w jsonb;
  r jsonb;
  wert numeric;
  vo date; bi date;
  n integer := 0;
  ersetzt integer := 0;
  x integer;
  fehler text;
  ziel text;
  m record;
  vf boolean := false;
  mf boolean := false;
  wahl jsonb := '[]'::jsonb;
BEGIN
  IF NOT (c->>'ok')::boolean THEN
    IF coalesce((c->>'angemeldet')::boolean, false) THEN
      PERFORM ally_web_meldung(p_token, coalesce(c->>'fehler', 'Das geht gerade nicht.'), 'fehler', NULL);
    END IF;
    RETURN c || jsonb_build_object('ziel', '/webhook/web');
  END IF;
  u := c->>'u';
  verw := (c->>'verw')::boolean;
  -- Talent bestimmen (direkt oder über Vorschlag bzw. Wert)
  IF coalesce(d->>'vorschlag_id', '') ~ '^[0-9]{1,12}$' THEN
    SELECT * INTO v FROM talent_manuell_vorschlaege y WHERE y.id = (d->>'vorschlag_id')::bigint FOR UPDATE;
    vf := FOUND;
    IF vf THEN tid := v.talent_id; END IF;
  ELSIF coalesce(d->>'wert_id', '') ~ '^[0-9]{1,12}$' THEN
    SELECT * INTO m FROM talent_manuell_werte y WHERE y.id = (d->>'wert_id')::bigint;
    mf := FOUND;
    IF mf THEN tid := m.talent_id; END IF;
  ELSIF coalesce(d->>'talent_id', '') ~ '^[0-9]{1,9}$' THEN
    tid := (d->>'talent_id')::integer;
  END IF;
  IF tid IS NULL OR NOT talent_sichtbar(u, tid) THEN
    PERFORM ally_web_meldung(p_token, 'Dieses Talent gibt es nicht oder du bist nicht als Manager oder Managerin eingetragen.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ziel', '/webhook/web?ansicht=talents');
  END IF;
  ziel := '/webhook/web?ansicht=talents&talent=' || tid || '&b=zahlen';
  -- Migration 66: Zahlen ohne Verbindung ändert nur, wer das Talent verwalten darf („Talents ansehen“ allein erlaubt keine Änderungen)
  IF NOT talent_verwaltbar(u, tid) THEN
    PERFORM ally_web_meldung(p_token, 'Zahlen ohne Verbindung ändert, wer das Recht „Talents und Kampagnen verwalten“ für dieses Talent hat.', 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ziel', ziel);
  END IF;

  IF p_aktion = 'hochladen' THEN
    r := talents_manuell_vorschlag_anlegen(u, jsonb_build_object('talent_id', tid, 'quelle', 'hochladen', 'datei_name', d->'datei_name', 'datei_typ', d->'datei_typ', 'datei_groesse', d->'datei_groesse'));
    PERFORM ally_web_meldung(p_token, CASE WHEN (r->>'ok')::boolean THEN 'Datei erhalten. Ally liest die Zahlen aus; in etwa einer Minute stehen sie hier zur Prüfung. Bitte die Seite dann neu laden.'
      ELSE r->>'fehler' END, CASE WHEN (r->>'ok')::boolean THEN 'ok' ELSE 'fehler' END, NULL);
    RETURN jsonb_build_object('ok', (r->>'ok')::boolean, 'angemeldet', true, 'weiter', CASE WHEN (r->>'ok')::boolean THEN 'auslesen' END,
      'vorschlag', CASE WHEN (r->>'ok')::boolean THEN r END, 'nutzer', u, 'ziel', ziel);

  ELSIF p_aktion IN ('bestaetigen', 'verwerfen') THEN
    IF vf THEN vf := v.status = 'offen'; END IF;
    IF NOT vf THEN
      PERFORM ally_web_meldung(p_token, 'Dieser Vorschlag ist schon erledigt. Bitte die Seite neu laden.', 'fehler', NULL);
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ziel', ziel);
    END IF;
    IF p_aktion = 'verwerfen' THEN
      UPDATE talent_manuell_vorschlaege SET status = 'verworfen', geprueft_von = u, geprueft_am = now() WHERE id = v.id;
      PERFORM ally_web_meldung(p_token, 'Vorschlag verworfen. Es wurde nichts gespeichert.', 'ok', NULL);
      RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'ziel', ziel);
    END IF;
    -- erst alle gewählten Werte prüfen (Liste wahl), dann speichern
    FOR w IN SELECT e FROM jsonb_array_elements(v.werte) e LOOP
      CONTINUE WHEN NOT talents_bericht_ja(d->('n' || (w->>'nr') || '_ja'), false);
      wert := CASE WHEN w->>'bereich' = 'zielgruppe' THEN NULL ELSE coalesce(talents_manuell_zahl(d->('n' || (w->>'nr') || '_wert')), (w->>'wert')::numeric) END;
      bi := coalesce(talents_bericht_datum(d->>('n' || (w->>'nr') || '_bis')), talents_bericht_datum(w->>'bis'));
      vo := CASE WHEN (w->>'stand')::boolean THEN bi ELSE coalesce(talents_bericht_datum(d->>('n' || (w->>'nr') || '_von')), talents_bericht_datum(w->>'von')) END;
      fehler := 'Bei „' || (w->>'kennzahl_name') || '“ ' || CASE WHEN w->>'bereich' <> 'zielgruppe' AND wert IS NULL THEN 'fehlt eine gültige Zahl.'
        WHEN bi IS NULL OR vo IS NULL THEN 'fehlt der Zeitraum (von und bis bzw. Stand).' WHEN vo > bi THEN 'liegt der Beginn nach dem Ende.'
        WHEN bi > talents_heute() THEN 'liegt das Datum in der Zukunft.' END;
      EXIT WHEN fehler IS NOT NULL;
      wahl := wahl || jsonb_build_array(w || jsonb_build_object('wert', wert, 'von', vo, 'bis', bi));
    END LOOP;
    IF fehler IS NULL AND jsonb_array_length(wahl) = 0 THEN
      fehler := 'Bitte mindestens einen Wert auswählen oder den Vorschlag verwerfen.';
    END IF;
    IF fehler IS NOT NULL THEN
      PERFORM ally_web_meldung(p_token, fehler || ' Es wurde nichts gespeichert.', 'fehler', NULL);
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ziel', ziel || '#vorschlag-' || v.id);
    END IF;
    FOR w IN SELECT e FROM jsonb_array_elements(wahl) e LOOP
      -- gleicher Wert (Plattform, Konto, Bereich, Kennzahl, Zeitraum, Beitrag) wird ersetzt
      DELETE FROM talent_manuell_werte y WHERE y.talent_id = tid AND y.plattform = w->>'plattform' AND y.bereich = w->>'bereich' AND y.kennzahl = w->>'kennzahl'
        AND y.von IS NOT DISTINCT FROM (w->>'von')::date AND y.bis = (w->>'bis')::date AND coalesce(y.beitrag_link, '') = coalesce(w->>'beitrag_link', '')
        AND coalesce(y.konto, '') = coalesce(w->>'konto', '');
      GET DIAGNOSTICS x = ROW_COUNT;
      ersetzt := ersetzt + x;
      INSERT INTO talent_manuell_werte (talent_id, vorschlag_id, plattform, konto, bereich, kennzahl, wert, werte, von, bis, beitrag_datum, beitrag_link, beitrag_art,
                                        quelle, quelle_text, bestaetigt_von)
      VALUES (tid, v.id, w->>'plattform', w->>'konto', w->>'bereich', w->>'kennzahl', (w->>'wert')::numeric, CASE WHEN w->>'bereich' = 'zielgruppe' THEN w->'werte' END,
              (w->>'von')::date, (w->>'bis')::date, talents_bericht_datum(w->>'beitrag_datum'), w->>'beitrag_link', w->>'beitrag_art', v.quelle, v.quelle_text, u);
      n := n + 1;
    END LOOP;
    UPDATE talent_manuell_vorschlaege SET status = 'bestaetigt', geprueft_von = u, geprueft_am = now() WHERE id = v.id;
    PERFORM ally_web_meldung(p_token, n || CASE WHEN n = 1 THEN ' Wert' ELSE ' Werte' END || ' für ' || talent_listenname(tid) || ' gespeichert (manuell, Quelle: ' || v.quelle_text || ').'
      || CASE WHEN ersetzt > 0 THEN ' ' || ersetzt || CASE WHEN ersetzt = 1 THEN ' älterer Wert mit gleichem Zeitraum wurde ersetzt.' ELSE ' ältere Werte mit gleichem Zeitraum wurden ersetzt.' END ELSE '' END,
      'ok', NULL);
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'ziel', ziel, 'anzahl', n, 'ersetzt', ersetzt);

  ELSIF p_aktion = 'wert_neu' THEN
    w := talents_manuell_wert_lesen(jsonb_build_object('plattform', d->'plattform', 'bereich', 'konto', 'kennzahl', d->'kennzahl', 'wert', d->'wert',
      'von', d->'von', 'bis', d->'bis', 'konto', d->'konto'), 1, '');
    IF w IS NULL THEN
      fehler := 'Bitte Plattform, Kennzahl und eine gültige Zahl angeben.';
    ELSIF jsonb_array_length(w->'fehlt') > 0 THEN
      fehler := CASE WHEN (w->>'stand')::boolean THEN 'Bitte das Datum (Stand) angeben.' ELSE 'Bitte Beginn und Ende des Zeitraums angeben (Beginn vor Ende).' END;
    ELSIF (w->>'bis')::date > talents_heute() THEN
      fehler := 'Das Datum liegt in der Zukunft.';
    END IF;
    IF fehler IS NOT NULL THEN
      PERFORM ally_web_meldung(p_token, fehler || ' Es wurde nichts gespeichert.', 'fehler', NULL);
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ziel', ziel || '#von-hand');
    END IF;
    DELETE FROM talent_manuell_werte y WHERE y.talent_id = tid AND y.plattform = w->>'plattform' AND y.bereich = 'konto' AND y.kennzahl = w->>'kennzahl'
      AND y.von IS NOT DISTINCT FROM (w->>'von')::date AND y.bis = (w->>'bis')::date AND coalesce(y.konto, '') = coalesce(w->>'konto', '') AND y.beitrag_link IS NULL;
    GET DIAGNOSTICS ersetzt = ROW_COUNT;
    INSERT INTO talent_manuell_werte (talent_id, plattform, konto, bereich, kennzahl, wert, von, bis, quelle, quelle_text, bestaetigt_von)
    VALUES (tid, w->>'plattform', w->>'konto', 'konto', w->>'kennzahl', (w->>'wert')::numeric, (w->>'von')::date, (w->>'bis')::date, 'hand',
            'Von Hand eingetragen am ' || to_char(talents_heute(), 'DD.MM.YYYY') || coalesce(' (' || (SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = u) || ')', ''), u);
    PERFORM ally_web_meldung(p_token, (w->>'kennzahl_name') || ' für ' || talent_listenname(tid) || ' gespeichert (manuell).'
      || CASE WHEN ersetzt > 0 THEN ' Der ältere Wert mit gleichem Zeitraum wurde ersetzt.' ELSE '' END, 'ok', NULL);
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'ziel', ziel);

  ELSIF p_aktion = 'wert_loeschen' THEN
    IF NOT mf THEN
      PERFORM ally_web_meldung(p_token, 'Diesen Wert gibt es nicht mehr. Bitte die Seite neu laden.', 'fehler', NULL);
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ziel', ziel);
    END IF;
    IF NOT (verw OR m.bestaetigt_von IS NOT DISTINCT FROM u) THEN
      PERFORM ally_web_meldung(p_token, 'Diesen Wert dürfen nur die Person, die ihn bestätigt hat, und Personen mit „Talents und Kampagnen verwalten“ für alle Talents oder mit der Rolle Admin löschen.', 'fehler', NULL);
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ziel', ziel);
    END IF;
    PERFORM talents_profil_pk_legen('wert', m.id, u);  -- Migration 130: in den Papierkorb, mit Doppelt-Entscheidung
    PERFORM ally_web_meldung(p_token, talents_manuell_kennzahl_name(m.bereich, m.kennzahl) || ' (' || talents_manuell_zeitraum_text(m.von, m.bis) || ') liegt jetzt im Papierkorb. Im Papierkorb kannst du den Wert wiederherstellen.', 'ok', NULL);
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'ziel', ziel);
  END IF;
  PERFORM ally_web_meldung(p_token, 'Unbekannte Aktion. Bitte die Seite neu laden.', 'fehler', NULL);
  RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'ziel', ziel);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_wert_lesen(p jsonb, p_nr integer, p_plattform_standard text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  pl text := lower(btrim(coalesce(p->>'plattform', '')));
  be text := lower(btrim(coalesce(p->>'bereich', 'konto')));
  kz text := lower(btrim(coalesce(p->>'kennzahl', '')));
  w numeric;
  ws jsonb;
  vo date; bi date; bd date;
  stand boolean;
  link text := btrim(coalesce(p->>'beitrag_link', ''));
  fehlt text[] := '{}';
BEGIN
  IF pl = '' THEN pl := p_plattform_standard; END IF;
  IF NOT pl = ANY (talents_plattformen()) THEN RETURN NULL; END IF;
  IF be IN ('instagram_kanal', 'broadcast', 'broadcast_channel', 'channel') THEN be := 'kanal'; END IF;
  IF be NOT IN ('konto', 'beitrag', 'zielgruppe', 'kanal') THEN RETURN NULL; END IF;
  -- Instagram-Kanal (Broadcast Channel) nur bei Instagram (Stefan 19.10.2026)
  IF be = 'kanal' AND pl <> 'instagram' THEN RETURN NULL; END IF;
  kz := CASE kz WHEN 'reach' THEN 'reichweite' WHEN 'views' THEN 'aufrufe' WHEN 'impressions' THEN 'aufrufe' WHEN 'plays' THEN 'aufrufe'
                WHEN 'followers' THEN 'follower' WHEN 'followers_count' THEN 'follower' WHEN 'interactions' THEN 'interaktionen' WHEN 'total_interactions' THEN 'interaktionen'
                WHEN 'profile_views' THEN 'profilaufrufe' WHEN 'comments' THEN 'kommentare' WHEN 'saves' THEN 'speicherungen' WHEN 'saved' THEN 'speicherungen'
                WHEN 'shares' THEN 'geteilt' WHEN 'posts' THEN 'beitraege'
                -- Instagram-Kanal (Stefan 19.10.2026)
                WHEN 'members' THEN 'mitglieder' WHEN 'member_count' THEN 'mitglieder' WHEN 'gesamtinteraktionen' THEN 'interaktionen' WHEN 'teilen' THEN 'geteilt'
                WHEN 'poll_votes' THEN 'umfrage_stimmen' WHEN 'votes' THEN 'umfrage_stimmen' WHEN 'umfrage-stimmen' THEN 'umfrage_stimmen' ELSE kz END;
  SELECT (x->>'stand')::boolean INTO stand FROM jsonb_array_elements(talents_manuell_kennzahlen()) x WHERE x->>'bereich' = be AND x->>'schluessel' = kz;
  IF stand IS NULL THEN RETURN NULL; END IF;
  IF be = 'zielgruppe' THEN
    SELECT jsonb_object_agg(left(btrim(e.key), 60), talents_manuell_zahl(e.value)) INTO ws
    FROM (SELECT * FROM jsonb_each(CASE WHEN jsonb_typeof(p->'werte') = 'object' THEN p->'werte' ELSE '{}'::jsonb END) LIMIT 50) e
    WHERE talents_manuell_zahl(e.value) IS NOT NULL AND btrim(e.key) <> '';
    IF ws IS NULL THEN RETURN NULL; END IF;
  ELSE
    w := talents_manuell_zahl(p->'wert');
    IF w IS NULL THEN RETURN NULL; END IF;
  END IF;
  vo := talents_bericht_datum(p->>'von');
  bi := coalesce(talents_bericht_datum(p->>'bis'), talents_bericht_datum(p->>'stand'));
  IF stand THEN
    bi := coalesce(bi, vo); vo := bi;
  END IF;
  IF bi IS NULL OR vo IS NULL THEN fehlt := fehlt || 'zeitraum'::text; END IF;
  IF vo IS NOT NULL AND bi IS NOT NULL AND vo > bi THEN vo := NULL; fehlt := fehlt || 'zeitraum'::text; END IF;
  bd := talents_bericht_datum(p->>'beitrag_datum');
  RETURN jsonb_build_object('nr', p_nr, 'plattform', pl, 'plattform_name', CASE WHEN be = 'kanal' THEN 'Instagram-Kanal' ELSE talents_plattform_name(pl) END,
    'konto', CASE WHEN btrim(coalesce(p->>'konto', '')) ~ '^@?[A-Za-z0-9._]{1,60}$' THEN '@' || ltrim(btrim(p->>'konto'), '@') END,
    'bereich', be, 'kennzahl', kz, 'kennzahl_name', talents_manuell_kennzahl_name(be, kz), 'stand', stand,
    'wert', w, 'wert_text', CASE WHEN w IS NOT NULL THEN talents_zahl_text(w) END, 'werte', ws,
    'werte_text', CASE WHEN ws IS NOT NULL THEN (SELECT string_agg(e.key || ': ' || talents_dezimal_text((e.value #>> '{}')::numeric, CASE WHEN (e.value #>> '{}')::numeric % 1 = 0 THEN 0 ELSE 1 END), ', ' ORDER BY e.key) FROM jsonb_each(ws) e) END,
    'von', to_char(vo, 'YYYY-MM-DD'), 'bis', to_char(bi, 'YYYY-MM-DD'),
    'beitrag_datum', to_char(bd, 'YYYY-MM-DD'), 'beitrag_link', CASE WHEN link ~ '^https://[^[:space:]]+$' AND length(link) <= 500 THEN link END,
    'beitrag_art', CASE WHEN be = 'beitrag' THEN left(nullif(btrim(coalesce(p->>'beitrag_art', '')), ''), 30) END,
    'fehlt', to_jsonb(fehlt));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_zahl(p jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  s text;
  faktor numeric := 1;
  n numeric;
BEGIN
  IF p IS NULL OR jsonb_typeof(p) = 'null' THEN
    RETURN NULL;
  ELSIF jsonb_typeof(p) = 'number' THEN
    n := (p #>> '{}')::numeric;
  ELSIF jsonb_typeof(p) = 'string' THEN
    s := lower(btrim(p #>> '{}'));
    IF s ~ '(mio|million)' THEN faktor := 1000000; ELSIF s ~ '(tsd|tausend|\dk$|\d k$)' THEN faktor := 1000; END IF;
    s := btrim(regexp_replace(s, '[^0-9.,]', '', 'g'), '.,');
    IF s = '' THEN RETURN NULL; END IF;
    IF faktor > 1 THEN
      s := replace(s, ',', '.');
    ELSIF s ~ '^[0-9]{1,3}([.,][0-9]{3})+$' THEN
      s := regexp_replace(s, '[.,]', '', 'g');
    ELSE
      s := replace(s, ',', '.');
    END IF;
    IF s !~ '^[0-9]{1,15}(\.[0-9]{1,6})?$' THEN RETURN NULL; END IF;
    n := s::numeric * faktor;
  ELSE
    RETURN NULL;
  END IF;
  IF n < 0 OR n >= 1e15 THEN RETURN NULL; END IF;
  RETURN round(n, 2);
EXCEPTION WHEN others THEN
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_manuell_zeitraum_text(p_von date, p_bis date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN p_von IS NULL OR p_von = p_bis THEN 'Stand ' || to_char(p_bis, 'DD.MM.YYYY')
              ELSE to_char(p_von, 'DD.MM.YYYY') || ' bis ' || to_char(p_bis, 'DD.MM.YYYY') END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_markensuche_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  tid integer := CASE WHEN d->>'talent_id' ~ '^[0-9]{1,9}$' THEN (d->>'talent_id')::integer END;
  kid integer := CASE WHEN d->>'kriterium_id' ~ '^[0-9]{1,9}$' THEN (d->>'kriterium_id')::integer END;
  trid integer := CASE WHEN d->>'treffer_id' ~ '^[0-9]{1,9}$' THEN (d->>'treffer_id')::integer END;
  k talent_markensuche_kriterien;
  t talent_markensuche_treffer;
  s jsonb;
  u text;
  f text;
  v_ebene text := coalesce(d->>'ebene', 'talent');
  sk jsonb := '{}'::jsonb;
  r text; fe text; w text;
  i integer;
BEGIN
  IF kid IS NOT NULL THEN
    SELECT * INTO k FROM talent_markensuche_kriterien WHERE id = kid;
    tid := k.talent_id;
  ELSIF trid IS NOT NULL THEN
    SELECT * INTO t FROM talent_markensuche_treffer WHERE id = trid;
    tid := t.talent_id;
  END IF;
  s := talents_ki_sitzung(p_token, tid);
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  u := s->>'u';
  IF p_aktion = 'kriterium_hinzufuegen' THEN
    IF v_ebene NOT IN ('agentur', 'talent') OR (v_ebene = 'talent' AND tid IS NULL) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte die Ebene wählen.');
    END IF;
    IF v_ebene = 'agentur' AND NOT coalesce((s->>'verw')::boolean, false) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Kriterien für die ganze Agentur ändert, wer das Recht „Talents und Kampagnen verwalten“ für alle Talents hat.');
    END IF;
    f := talents_markensuche_wert_fehler(d->>'richtung', d->>'feld', d->>'wert');
    IF f IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', f);
    END IF;
    IF (SELECT count(*) FROM talent_markensuche_kriterien x WHERE x.ebene = v_ebene AND x.talent_id IS NOT DISTINCT FROM CASE WHEN v_ebene = 'talent' THEN tid END) >= 200 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Höchstens 200 Kriterien je Ebene.');
    END IF;
    INSERT INTO talent_markensuche_kriterien (ebene, talent_id, richtung, feld, wert, wert_norm, grund, erstellt_von)
    VALUES (v_ebene, CASE WHEN v_ebene = 'talent' THEN tid END, d->>'richtung', d->>'feld', btrim(d->>'wert'), talents_ki_norm(d->>'wert'), talents_ki_kurz(d->>'grund', 300), u)
    ON CONFLICT DO NOTHING;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Kriterium gespeichert.');
  ELSIF p_aktion = 'kriterium_entfernen' THEN
    IF k.id IS NULL OR (k.ebene = 'agentur' AND NOT coalesce((s->>'verw')::boolean, false)) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Dieses Kriterium gibt es nicht oder du darfst es nicht ändern.');
    END IF;
    DELETE FROM talent_markensuche_kriterien WHERE id = k.id;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', CASE WHEN k.feld = 'marke' THEN 'Marke von der Sperrliste genommen.' ELSE 'Kriterium entfernt.' END);
  ELSIF p_aktion = 'suche_starten' THEN
    IF tid IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte ein Talent wählen.');
    END IF;
    f := talents_ki_start_fehler(tid);
    IF f IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', f);
    END IF;
    IF EXISTS (SELECT 1 FROM talent_markensuche_laeufe x WHERE x.talent_id = tid AND x.status = 'wird_erstellt') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Eine Suche läuft gerade. ' || talents_ki_laeuft_text());
    END IF;
    -- Kriterien nur für diese Suche (gleiche Prüfung wie gespeicherte Kriterien, höchstens 10 Werte je Feld)
    FOR r, fe, w IN SELECT rr.richtung, ff.key, btrim(v.value) FROM (VALUES ('einschliessen'), ('ausschliessen')) rr(richtung)
        CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(d->rr.richtung) = 'object' THEN d->rr.richtung ELSE '{}'::jsonb END) ff
        CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(ff.value) = 'array' THEN ff.value ELSE '[]'::jsonb END) v LOOP
      f := talents_markensuche_wert_fehler(r, fe, w);
      IF f IS NOT NULL THEN
        RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', talents_markensuche_feld_name(fe) || ': ' || f);
      END IF;
      IF jsonb_array_length(coalesce(sk->r->fe, '[]'::jsonb)) < 10 AND NOT coalesce(sk->r->fe, '[]'::jsonb) ? w THEN
        sk := jsonb_set(CASE WHEN sk ? r THEN sk ELSE sk || jsonb_build_object(r, '{}'::jsonb) END, ARRAY[r, fe], coalesce(sk->r->fe, '[]'::jsonb) || to_jsonb(w));
      END IF;
    END LOOP;
    INSERT INTO talent_markensuche_laeufe (talent_id, suche_kriterien, kriterien, erstellt_von) VALUES (tid, sk, talents_markensuche_wirksam(tid, sk), u) RETURNING id INTO i;
    UPDATE talent_markensuche_laeufe SET ki_auftrag_id = talents_ki_auftrag_anlegen('markensuche', tid, i, u) WHERE id = i;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'lauf_id', i, 'auftrag_id', (SELECT ki_auftrag_id FROM talent_markensuche_laeufe WHERE id = i),
      'meldung', 'Die Suche läuft. Das dauert meist 1 bis 3 Minuten. Bitte die Seite danach neu laden.');
  ELSIF p_aktion IN ('bewerten', 'bewertung_zuruecknehmen') THEN
    IF t.id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diesen Treffer gibt es nicht. Bitte die Seite neu laden.');
    END IF;
    IF p_aktion = 'bewertung_zuruecknehmen' THEN
      UPDATE talent_markensuche_treffer SET bewertung = NULL, bewertung_grund = NULL, bewertet_von = NULL, bewertet_am = NULL WHERE id = t.id;
      RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Bewertung zurückgenommen.');
    END IF;
    IF coalesce(d->>'bewertung', '') NOT IN ('passt', 'passt_nicht') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte „passt“ oder „passt nicht“ wählen.');
    END IF;
    IF coalesce(d->>'sperren', '') = 'agentur' AND NOT coalesce((s->>'verw')::boolean, false) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Auf die Sperrliste der Agentur setzt, wer das Recht „Talents und Kampagnen verwalten“ für alle Talents hat.');
    END IF;
    UPDATE talent_markensuche_treffer SET bewertung = d->>'bewertung', bewertung_grund = talents_ki_kurz(d->>'grund', 300), bewertet_von = u, bewertet_am = now() WHERE id = t.id;
    IF d->>'bewertung' = 'passt_nicht' AND coalesce(d->>'sperren', '') IN ('talent', 'agentur') THEN
      INSERT INTO talent_markensuche_kriterien (ebene, talent_id, richtung, feld, wert, wert_norm, grund, erstellt_von)
      VALUES (d->>'sperren', CASE WHEN d->>'sperren' = 'talent' THEN t.talent_id END, 'ausschliessen', 'marke', left(t.marke, 120), t.marke_norm,
              coalesce(talents_ki_kurz(d->>'grund', 300), 'passt nicht (Marken-Suche)'), u)
      ON CONFLICT DO NOTHING;
      RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', t.marke || ' steht jetzt auf der Sperrliste ' || CASE WHEN d->>'sperren' = 'agentur' THEN 'der Agentur' ELSE 'des Talents' END || ' und wird nicht mehr vorgeschlagen.');
    END IF;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Bewertung gespeichert.');
  END IF;
  RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Unbekannte Aktion.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_markensuche_daten(p_token text, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  tid integer := CASE WHEN f->>'talent_id' ~ '^[0-9]{1,9}$' THEN (f->>'talent_id')::integer END;
  lid integer := CASE WHEN f->>'lauf_id' ~ '^[0-9]{1,9}$' THEN (f->>'lauf_id')::integer END;
  s jsonb := talents_ki_sitzung(p_token, tid);
  l talent_markensuche_laeufe;
BEGIN
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  IF tid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte ein Talent wählen.');
  END IF;
  SELECT * INTO l FROM talent_markensuche_laeufe x WHERE x.talent_id = tid AND (lid IS NULL OR x.id = lid) ORDER BY x.id DESC LIMIT 1;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true,
    'talent', jsonb_build_object('talent_id', tid, 'name', talent_anzeigename(tid)),
    'darf_starten', EXISTS (SELECT 1 FROM talents t WHERE t.id = tid AND t.status = 'aktiv'),
    'darf_agentur', coalesce((s->>'verw')::boolean, false),
    'kriterien_talent', (SELECT coalesce(jsonb_agg(talents_markensuche_kriterium_json(k.id) ORDER BY k.richtung, k.feld, k.wert_norm), '[]'::jsonb)
                         FROM talent_markensuche_kriterien k WHERE k.talent_id = tid),
    'kriterien_agentur', (SELECT coalesce(jsonb_agg(talents_markensuche_kriterium_json(k.id) ORDER BY k.richtung, k.feld, k.wert_norm), '[]'::jsonb)
                          FROM talent_markensuche_kriterien k WHERE k.ebene = 'agentur'),
    'wirksam', talents_markensuche_wirksam(tid),
    'felder', jsonb_build_object('einschliessen', (SELECT jsonb_agg(jsonb_build_object('feld', x, 'name', talents_markensuche_feld_name(x), 'optionen', talents_markensuche_optionen()->x))
                                                   FROM unnest(ARRAY['branche', 'markt', 'groesse', 'preis', 'werte', 'zusammenarbeit', 'influencer']) x),
                                 'ausschliessen', (SELECT jsonb_agg(jsonb_build_object('feld', x, 'name', talents_markensuche_feld_name(x), 'optionen', NULL))
                                                   FROM unnest(ARRAY['branche', 'marke', 'wettbewerber']) x)),
    'laeufe', (SELECT coalesce(jsonb_agg(jsonb_build_object('lauf_id', x.id, 'datum', talents_datum(x.erstellt_am) || ' ' || talents_zeit(x.erstellt_am),
                  'status_text', CASE x.status WHEN 'wird_erstellt' THEN 'läuft' WHEN 'fehler' THEN 'fehlgeschlagen' ELSE x.anzahl_neu || ' neue Marken' END) ORDER BY x.id DESC), '[]'::jsonb)
               FROM (SELECT * FROM talent_markensuche_laeufe x WHERE x.talent_id = tid ORDER BY x.id DESC LIMIT 10) x),
    'lauf', CASE WHEN l.id IS NULL THEN NULL ELSE jsonb_build_object('lauf_id', l.id, 'status', l.status, 'laeuft', l.status = 'wird_erstellt',
        'status_text', CASE l.status WHEN 'wird_erstellt' THEN talents_ki_laeuft_text() WHEN 'fehler' THEN coalesce(l.fehler, 'Die Suche ist fehlgeschlagen.') ELSE l.hinweis END,
        'datum', talents_datum(l.erstellt_am), 'websuchen', l.websuchen, 'suche_kriterien', l.suche_kriterien,
        'treffer', (SELECT coalesce(jsonb_agg(talents_markensuche_treffer_json(t.id) ORDER BY t.id), '[]'::jsonb)
                    FROM (SELECT * FROM talent_markensuche_treffer t WHERE t.lauf_id = l.id AND NOT t.bereits_bekannt ORDER BY t.id LIMIT 12) t),
        'bekannt', (SELECT coalesce(jsonb_agg(talents_markensuche_treffer_json(t.id) ORDER BY t.id), '[]'::jsonb)
                    FROM (SELECT * FROM talent_markensuche_treffer t WHERE t.lauf_id = l.id AND t.bereits_bekannt ORDER BY t.id LIMIT 12) t)) END,
    'hinweis_quellen', 'Die Treffer stammen aus einer Websuche und können falsch oder veraltet sein. Bitte vor jeder Kontaktaufnahme prüfen. Ally schreibt keine Marke an.',
    'ki_hinweis', talents_ki_start_fehler(tid));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_markensuche_feld_name(p_feld text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_feld WHEN 'branche' THEN 'Branche oder Produktkategorie' WHEN 'markt' THEN 'Markt und Sprache' WHEN 'groesse' THEN 'Größe der Marke'
    WHEN 'preis' THEN 'Preissegment' WHEN 'werte' THEN 'Werte' WHEN 'zusammenarbeit' THEN 'Art der Zusammenarbeit' WHEN 'influencer' THEN 'Erfahrung mit Influencern'
    WHEN 'marke' THEN 'Marke (Sperrliste)' WHEN 'wettbewerber' THEN 'Wettbewerber aktueller Partner (Exklusivität)' ELSE p_feld END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_markensuche_kriterium_json(p_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('kriterium_id', k.id, 'ebene', k.ebene, 'richtung', k.richtung, 'richtung_name', CASE k.richtung WHEN 'einschliessen' THEN 'Einschließen' ELSE 'Ausschließen' END,
    'feld', k.feld, 'feld_name', talents_markensuche_feld_name(k.feld), 'wert', k.wert,
    'wert_name', coalesce((SELECT o->>'name' FROM jsonb_array_elements(talents_markensuche_optionen()->k.feld) o WHERE o->>'wert' = k.wert), k.wert),
    'grund', k.grund, 'datum', talents_datum(k.erstellt_am))
  FROM talent_markensuche_kriterien k WHERE k.id = p_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_markensuche_optionen()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT '{"groesse": [{"wert": "klein", "name": "Kleine Marke oder Start-up"}, {"wert": "mittel", "name": "Mittelständische Marke"}, {"wert": "gross", "name": "Große Marke"}],
           "preis": [{"wert": "guenstig", "name": "Günstig"}, {"wert": "mittel", "name": "Mittleres Preissegment"}, {"wert": "premium", "name": "Premium"}, {"wert": "luxus", "name": "Luxus"}],
           "zusammenarbeit": [{"wert": "bezahlt", "name": "Bezahlte Kooperation"}, {"wert": "produkt", "name": "Produkt gegen Beitrag"}, {"wert": "provision", "name": "Provision"}, {"wert": "langfristig", "name": "Langfristige Partnerschaft"}],
           "influencer": [{"wert": "ja", "name": "Arbeitet nachweisbar schon mit Influencern"}]}'::jsonb
$function$
;

CREATE OR REPLACE FUNCTION public.talents_markensuche_treffer_json(p_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('treffer_id', t.id, 'marke', t.marke, 'website', t.website, 'branche', t.branche, 'begruendung', t.begruendung,
    'quelle_url', t.quelle_url, 'quelle_titel', coalesce(t.quelle_titel, talents_ki_host(t.quelle_url)),
    'kontaktweg', t.kontaktweg, 'kontaktweg_name', CASE t.kontaktweg WHEN 'kooperationsprogramm' THEN 'Kooperations- oder Influencer-Programm' WHEN 'kontaktformular' THEN 'Kontaktformular'
                                                   WHEN 'presse' THEN 'Presse' WHEN 'allgemeine_mail' THEN 'Allgemeine Mailadresse' ELSE 'nicht gefunden' END,
    'kontakt', t.kontakt, 'kontakt_ist_link', t.kontakt ~ '^https://',
    'bereits_bekannt', t.bereits_bekannt, 'bewertung', t.bewertung,
    'bewertung_text', CASE t.bewertung WHEN 'passt' THEN 'passt' WHEN 'passt_nicht' THEN 'passt nicht' END, 'bewertung_grund', t.bewertung_grund,
    'gesperrt', EXISTS (SELECT 1 FROM talent_markensuche_kriterien k WHERE k.richtung = 'ausschliessen' AND k.feld = 'marke' AND k.wert_norm = t.marke_norm
                        AND (k.ebene = 'agentur' OR k.talent_id = t.talent_id)))
  FROM talent_markensuche_treffer t WHERE t.id = p_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_markensuche_wert_fehler(p_richtung text, p_feld text, p_wert text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_richtung NOT IN ('einschliessen', 'ausschliessen') THEN 'Unbekannte Richtung.'
    WHEN p_richtung = 'einschliessen' AND p_feld NOT IN ('branche', 'markt', 'groesse', 'preis', 'werte', 'zusammenarbeit', 'influencer') THEN 'Unbekanntes Kriterium.'
    WHEN p_richtung = 'ausschliessen' AND p_feld NOT IN ('branche', 'marke', 'wettbewerber') THEN 'Unbekanntes Kriterium.'
    WHEN length(btrim(coalesce(p_wert, ''))) NOT BETWEEN 1 AND 120 THEN 'Bitte einen Wert mit höchstens 120 Zeichen angeben.'
    WHEN p_feld IN ('groesse', 'preis', 'zusammenarbeit', 'influencer')
         AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(talents_markensuche_optionen()->p_feld) o WHERE o->>'wert' = btrim(p_wert)) THEN 'Bitte einen Wert aus der Auswahl nehmen.'
    WHEN talents_ki_norm(p_wert) = '' THEN 'Bitte einen Wert mit Buchstaben oder Ziffern angeben.'
  END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_markensuche_wirksam(p_talent_id integer, p_suche jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH suche AS (
    SELECT r.richtung, f.key AS feld, btrim(v.value) AS wert
    FROM (VALUES ('einschliessen'), ('ausschliessen')) r(richtung)
    CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(p_suche->r.richtung) = 'object' THEN p_suche->r.richtung ELSE '{}'::jsonb END) f
    CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(f.value) = 'array' THEN f.value ELSE '[]'::jsonb END) v
    WHERE talents_markensuche_wert_fehler(r.richtung, f.key, v.value) IS NULL
  ), alle AS (
    SELECT 'suche' AS ebene, 1 AS rang, richtung, feld, wert FROM suche
    UNION ALL
    SELECT k.ebene, CASE k.ebene WHEN 'talent' THEN 2 ELSE 3 END, k.richtung, k.feld, k.wert FROM talent_markensuche_kriterien k
    WHERE k.ebene = 'agentur' OR k.talent_id = p_talent_id
  ), ein AS (
    SELECT a.feld, a.ebene, jsonb_agg(DISTINCT a.wert) AS werte FROM alle a
    WHERE a.richtung = 'einschliessen' AND a.rang = (SELECT min(b.rang) FROM alle b WHERE b.richtung = 'einschliessen' AND b.feld = a.feld)
    GROUP BY a.feld, a.ebene
  ), aus AS (
    SELECT feld, jsonb_agg(DISTINCT wert) AS werte FROM alle WHERE richtung = 'ausschliessen' GROUP BY feld
  )
  SELECT jsonb_build_object(
    'einschliessen', coalesce((SELECT jsonb_object_agg(feld, werte) FROM ein), '{}'::jsonb),
    'einschliessen_quelle', coalesce((SELECT jsonb_object_agg(feld, ebene) FROM ein), '{}'::jsonb),
    'ausschliessen', coalesce((SELECT jsonb_object_agg(feld, werte) FROM aus), '{}'::jsonb),
    'nogos', (SELECT nullif(btrim(a.nogos), '') FROM talent_konzept_angaben a WHERE a.talent_id = p_talent_id))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_mediakit_abgelegt(p_token text, p_auftrag jsonb, p_ergebnis jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; t record; c jsonb; person boolean := false; wer text; ok boolean := false; fehler text;
  a jsonb := CASE WHEN jsonb_typeof(p_auftrag) = 'object' THEN p_auftrag ELSE '{}'::jsonb END;
  e jsonb := CASE WHEN jsonb_typeof(p_ergebnis) = 'object' THEN p_ergebnis ELSE '{}'::jsonb END;
  tid integer := CASE WHEN coalesce(a->>'talent_id', '') ~ '^[0-9]{1,9}$' THEN (a->>'talent_id')::integer END;
  did bigint := CASE WHEN coalesce(e->>'datei_id', '') ~ '^[0-9]{1,15}$' THEN (e->>'datei_id')::bigint END;
BEGIN
  -- Migration 196: nach TALENTS Ablage (ALLY 20 „Mediakit eintragen“) die abgelegte Datei als Mediakit des Talents merken und die Meldung setzen.
  -- Prüft noch einmal Sitzung und Recht (wie talents_mediakit_ui_aktion) und dass die Datei eben für dieses Talent als Mediakit abgelegt wurde.
  -- Ein bestehender Link zum Teilen bleibt gültig und zeigt danach die neue Fassung; die vorige Datei bleibt im Speicherort.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF FOUND THEN
    person := true; c := talents_ansicht_start(p_token); wer := s.person;
    IF tid IS NULL OR NOT coalesce((c->>'ok')::boolean, false) OR NOT coalesce(talent_verwaltbar(c->>'u', tid), false) THEN fehler := 'Das Mediakit dieses Talents ändert nur, wer das Talent verwaltet.'; END IF;
  ELSE
    SELECT * INTO t FROM talent_web_sitzung(p_token);
    IF NOT FOUND THEN RETURN '{"ok": false, "angemeldet": false}'::jsonb; END IF;
    wer := 'talent:' || t.talent_id;
    IF tid IS DISTINCT FROM t.talent_id THEN fehler := 'Das Mediakit konnte nicht gespeichert werden.'; END IF;
  END IF;
  IF fehler IS NULL AND wer IS DISTINCT FROM a->>'von' THEN fehler := 'Das Mediakit konnte nicht gespeichert werden.'; END IF;
  IF fehler IS NULL AND NOT coalesce((e->>'ok')::boolean, false) THEN
    fehler := 'Das Mediakit konnte nicht abgelegt werden: ' || left(coalesce(nullif(e->>'fehler', ''), 'keine Antwort vom Speicherort.'), 300);
  END IF;
  IF fehler IS NULL AND NOT EXISTS (SELECT 1 FROM talent_ablage_dateien x WHERE x.id = did AND x.talent_id = tid AND x.art = 'mediakit' AND x.erstellt_am > now() - interval '15 minutes') THEN
    fehler := 'Das Mediakit konnte nicht gespeichert werden.';
  END IF;
  IF fehler IS NULL THEN
    INSERT INTO talent_mediakits AS m (talent_id, datei_id, hochgeladen_am, hochgeladen_von) VALUES (tid, did, now(), wer)
    ON CONFLICT (talent_id) DO UPDATE SET datei_id = EXCLUDED.datei_id, hochgeladen_am = EXCLUDED.hochgeladen_am, hochgeladen_von = EXCLUDED.hochgeladen_von;
    ok := true;
  END IF;
  IF person THEN PERFORM ally_web_meldung(p_token, coalesce(fehler, 'Mediakit gespeichert.' || CASE WHEN e->>'ort' IS NOT NULL THEN ' Abgelegt im Speicherort ' || left(e->>'ort', 60) || '.' ELSE '' END), CASE WHEN ok THEN 'ok' ELSE 'fehler' END, NULL);
  ELSE PERFORM talent_web_meldung(p_token, coalesce(fehler, 'Dein Mediakit ist gespeichert.'), CASE WHEN ok THEN 'ok' ELSE 'fehler' END); END IF;
  RETURN jsonb_build_object('ok', ok, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mediakit_adresse(p_token text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 196: öffentliche Adresse des Links zum Teilen (Oberfläche + /mediakit?t=<Code>, ALLY 45); NULL ohne eingerichtete Adresse oder bei ungültigem Code
  SELECT CASE WHEN talent_ui_adresse() IS NOT NULL AND coalesce(p_token, '') ~ '^[0-9a-f]{64}$' THEN talent_ui_adresse() || '/mediakit?t=' || p_token END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_mediakit_link_abruf(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE m talent_mediakits%ROWTYPE; st text; dn text;
BEGIN
  -- Migration 196: öffentlicher Link zum Teilen (ALLY 45, ohne Anmeldung). Nur der Code (64 Hex-Zeichen) aus der Adresse; gesucht über sha256 (link_hash).
  -- Liefert die Datei der Ablage zum Holen (TALENTS Ablage); zählt die Abrufe. Talents im Papierkorb (archiviert): nicht mehr verfügbar.
  IF coalesce(p_token, '') !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('ok', false, 'code', 404, 'text', 'Dieser Link ist ungültig.'); END IF;
  SELECT * INTO m FROM talent_mediakits x WHERE x.link_hash = ally_web_hash(p_token) FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 404, 'text', 'Dieser Link ist ungültig oder wurde widerrufen.'); END IF;
  SELECT x.status INTO st FROM talents x WHERE x.id = m.talent_id;
  SELECT x.name INTO dn FROM talent_ablage_dateien x WHERE x.id = m.datei_id AND x.talent_id = m.talent_id;
  IF st IS DISTINCT FROM 'aktiv' OR dn IS NULL THEN RETURN jsonb_build_object('ok', false, 'code', 410, 'text', 'Dieses Mediakit ist nicht mehr verfügbar.'); END IF;
  UPDATE talent_mediakits SET link_abrufe = link_abrufe + 1, link_zuletzt = now() WHERE talent_id = m.talent_id;
  RETURN jsonb_build_object('ok', true, 'datei_id', m.datei_id, 'name', dn);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mediakit_selbst_datei(p_token text, p_datei_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE s record; d record;
BEGIN
  -- Migration 196 (Plan 62b): das Talent sieht und lädt im Talent-Bereich sein aktuelles Mediakit (ALLY 20 „Download prüfen“, ta ohne Team-Sitzung).
  -- Talent-ID nur aus der Talent-Sitzung; nur die Datei, die gerade als Mediakit dieses Talents eingetragen ist. Sonst NULL (es passiert nichts).
  SELECT * INTO s FROM talent_web_sitzung(p_token);
  IF NOT FOUND OR p_datei_id IS NULL THEN RETURN NULL; END IF;
  SELECT x.id, x.name, x.mime INTO d FROM talent_mediakits m JOIN talent_ablage_dateien x ON x.id = m.datei_id AND x.talent_id = m.talent_id
  WHERE m.talent_id = s.talent_id AND m.datei_id = p_datei_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'datei_id', d.id, 'name', d.name, 'mime', coalesce(d.mime, 'application/pdf'));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mediakit_selbst_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE s record;
BEGIN
  -- Migration 196: „Mein Mediakit“ im Talent-Bereich (ALLY 38); Talent-ID nur aus der Talent-Sitzung. Das Talent pflegt sein Mediakit selbst (Stefan 01.11.2026).
  SELECT * INTO s FROM talent_web_sitzung(p_token);
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN talents_mediakit_stand(s.talent_id) || jsonb_build_object('ok', true, 'darf', true, 'adresse', talent_ui_adresse() IS NOT NULL);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mediakit_stand(p_talent_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 196: Stand des Mediakits eines Talents für Kachel und Talent-Bereich (ohne Rechteprüfung; nur aus talents_mediakit_ui / talents_mediakit_selbst_ui)
  SELECT jsonb_build_object(
    'datei', (SELECT jsonb_build_object('id', d.id, 'name', d.name, 'stand', talents_zeit(m.hochgeladen_am), 'bytes', d.bytes,
               'von', CASE WHEN m.hochgeladen_von LIKE 'talent:%' THEN 'Talent' ELSE (SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = m.hochgeladen_von) END)
              FROM talent_ablage_dateien d WHERE d.id = m.datei_id),
    'link', jsonb_build_object('aktiv', m.link_hash IS NOT NULL, 'seit', talents_zeit(m.link_seit), 'abrufe', coalesce(m.link_abrufe, 0), 'zuletzt', talents_zeit(m.link_zuletzt)))
  FROM (SELECT 1) x LEFT JOIN talent_mediakits m ON m.talent_id = p_talent_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_mediakit_ui(p_token text, p_talent_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE c jsonb := talents_ansicht_start(p_token);
BEGIN
  -- Migration 196: Kachel „Mediakit“ im Talent-Profil (ALLY 25 „Daten laden“). Sehen: wer das Talent sieht; ändern (hochladen, Link): wer das Talent verwaltet.
  IF NOT coalesce((c->>'ok')::boolean, false) OR p_talent_id IS NULL OR NOT coalesce(talent_sichtbar(c->>'u', p_talent_id), false) THEN RETURN NULL; END IF;
  RETURN talents_mediakit_stand(p_talent_id) || jsonb_build_object('ok', true, 'darf', coalesce(talent_verwaltbar(c->>'u', p_talent_id), false),
    'adresse', talent_ui_adresse() IS NOT NULL);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_mediakit_ui_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; t record; c jsonb; tid integer; wer text; tok text; person boolean := false; text_ text; ton text := 'ok';
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  typ text; gr bigint; r jsonb;
BEGIN
  -- Migration 196 (Stefan 01.11.2026, Mediakit): mk_hochladen, mk_link, mk_link_weg (ALLY 20 „Aktion ausführen“, vor allen anderen; NULL bei allen anderen Aktionen
  -- und ohne Sitzung). Person: Talent aus dem Formular, Recht „Talent verwalten“ (talent_verwaltbar); Talent: Talent-ID nur aus der Sitzung (Talent-Bereich).
  -- mk_hochladen prüft Art und Größe und gibt den Auftrag an ALLY 20 (weiter = mediakit; ALLY 20 legt die Datei über TALENTS Ablage ab, danach talents_mediakit_abgelegt).
  -- mk_link erzeugt einen neuen Link zum Teilen (der vorige gilt nicht mehr); gespeichert wird nur sha256, die Adresse geht einmal an die Oberfläche (mk_link).
  IF p_aktion IS NULL OR p_aktion NOT IN ('mk_hochladen', 'mk_link', 'mk_link_weg') THEN RETURN NULL; END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF FOUND THEN
    person := true;
    IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN
      RETURN coalesce(ally_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler', NULL), '{}'::jsonb) || '{"ok": false, "angemeldet": true, "ungueltig": true}'::jsonb;
    END IF;
    IF s.muss_pw_setzen THEN RETURN '{"ok": false, "angemeldet": true, "muss_pw_setzen": true}'::jsonb; END IF;
    IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'talent') THEN
      PERFORM ally_web_meldung(p_token, 'Talents sind für dich nicht freigeschaltet.', 'fehler', NULL); RETURN '{"ok": false, "angemeldet": true}'::jsonb;
    END IF;
    c := talents_ansicht_start(p_token);
    tid := CASE WHEN coalesce(d->>'talent_id', '') ~ '^[0-9]{1,9}$' THEN (d->>'talent_id')::integer END;
    IF tid IS NULL OR NOT coalesce((c->>'ok')::boolean, false) OR NOT EXISTS (SELECT 1 FROM talents x WHERE x.id = tid) OR NOT coalesce(talent_verwaltbar(c->>'u', tid), false) THEN
      PERFORM ally_web_meldung(p_token, 'Das Mediakit dieses Talents ändert nur, wer das Talent verwaltet.', 'fehler', NULL); RETURN '{"ok": false, "angemeldet": true}'::jsonb;
    END IF;
    wer := s.person;
  ELSE
    SELECT * INTO t FROM talent_web_sitzung(p_token);
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF coalesce(p_csrf, '') <> ally_ui_csrf(t.token_hash) THEN
      PERFORM talent_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler');
      RETURN '{"ok": false, "angemeldet": true, "ungueltig": true}'::jsonb;
    END IF;
    tid := t.talent_id; wer := 'talent:' || t.talent_id;
  END IF;

  IF p_aktion = 'mk_hochladen' THEN
    typ := lower(coalesce(d->>'datei_typ', ''));
    gr := CASE WHEN coalesce(d->>'datei_groesse', '') ~ '^[0-9]{1,12}$' THEN (d->>'datei_groesse')::bigint ELSE 0 END;
    IF gr <= 0 THEN text_ := 'Es ist keine Datei angekommen. Bitte erneut hochladen.';
    ELSIF typ <> 'application/pdf' AND lower(coalesce(d->>'datei_name', '')) !~ '\.pdf$' THEN text_ := 'Das Mediakit muss ein PDF sein.';
    ELSIF gr > 15728640 THEN text_ := 'Das PDF ist größer als 15 MB. Bitte eine kleinere Fassung hochladen.';
    ELSIF talents_ist_testdaten(tid) THEN text_ := 'Für Testdaten wird nichts im Speicherort abgelegt.';
    END IF;
    IF text_ IS NOT NULL THEN ton := 'fehler';
    ELSE
      RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'weiter', 'mediakit',
        'r', jsonb_build_object('talent_id', tid, 'von', wer, 'name', 'Mediakit_' || to_char(now() AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD_HH24-MI') || '.pdf'));
    END IF;
  ELSIF p_aktion = 'mk_link' THEN
    IF NOT EXISTS (SELECT 1 FROM talent_mediakits m WHERE m.talent_id = tid AND m.datei_id IS NOT NULL) THEN text_ := 'Bitte zuerst ein Mediakit hochladen.'; ton := 'fehler';
    ELSIF talent_ui_adresse() IS NULL THEN text_ := 'Die öffentliche Adresse der Oberfläche ist nicht eingerichtet. Ohne sie gibt es keinen Link zum Teilen.'; ton := 'fehler';
    ELSE
      tok := encode(gen_random_bytes(32), 'hex');
      UPDATE talent_mediakits SET link_hash = ally_web_hash(tok), link_seit = now(), link_von = wer, link_abrufe = 0, link_zuletzt = NULL WHERE talent_id = tid;
      text_ := 'Neuer Link zum Teilen erstellt. Ein früherer Link gilt nicht mehr.';
      r := jsonb_build_object('ok', true, 'angemeldet', true, 'mk_link', talents_mediakit_adresse(tok));
    END IF;
  ELSE
    UPDATE talent_mediakits SET link_hash = NULL, link_seit = NULL, link_von = NULL WHERE talent_id = tid AND link_hash IS NOT NULL;
    text_ := CASE WHEN FOUND THEN 'Der Link zum Teilen gilt nicht mehr.' ELSE 'Es gab keinen aktiven Link zum Teilen.' END;
  END IF;
  IF person THEN PERFORM ally_web_meldung(p_token, text_, ton, NULL); ELSE PERFORM talent_web_meldung(p_token, text_, ton); END IF;
  RETURN coalesce(r, jsonb_build_object('ok', ton = 'ok', 'angemeldet', true));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_meine_liste_ids(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; u text;
BEGIN
  -- Migration 147 (Stefan 24.10.2026, Konzept D): Nummern der eigenen Liste „Meine Talents“, nur Talents, die die Person sieht (die Liste gibt keine Rechte)
  c := talents_ansicht_start(p_token);
  IF NOT coalesce((c->>'ok')::boolean, false) THEN RETURN '[]'::jsonb; END IF;
  u := c->>'u';
  RETURN coalesce((SELECT jsonb_agg(l.talent_id ORDER BY l.talent_id) FROM talents_meine_liste l WHERE l.person = u AND talent_sichtbar(u, l.talent_id)), '[]'::jsonb);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_meine_liste_zustaendig()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Migration 148 (Stefan 24.10.2026, 17:41): neue Zuständigkeit → Talent auf die Liste „Meine Talents“ der Person (schon drauf: nichts). Nur Personen,
  -- die es gibt (talent_personen prüft das selbst per Fremdschlüssel); ein Fehler hier darf das Anlegen der Zuständigkeit nicht verhindern.
  INSERT INTO talents_meine_liste (person, talent_id)
    SELECT NEW.matrix_user_id, NEW.talent_id WHERE EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = NEW.matrix_user_id)
    ON CONFLICT DO NOTHING;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_merkmale(p jsonb, p_art text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  WITH r AS (
    SELECT btrim(x) AS x FROM (
      SELECT CASE WHEN jsonb_typeof(p) = 'array' THEN e #>> '{}' END AS v FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p) = 'array' THEN p ELSE '[]'::jsonb END) e
      UNION ALL SELECT p #>> '{}' WHERE jsonb_typeof(p) = 'string') q
    CROSS JOIN LATERAL regexp_split_to_table(coalesce(q.v, ''), CASE WHEN p_art = 'wort' THEN '[,;\n]+' ELSE '[,;[:space:]]+' END) AS x),
  n AS (SELECT DISTINCT ON (y) y, o FROM (SELECT CASE p_art WHEN 'marke' THEN lower(ltrim(x, '@')) WHEN 'hashtag' THEN lower(ltrim(x, '#')) ELSE x END AS y,
                                          row_number() OVER () AS o FROM r WHERE x <> '') z ORDER BY y, o)
  SELECT CASE WHEN EXISTS (SELECT 1 FROM n WHERE CASE p_art WHEN 'marke' THEN y !~ '^[a-z0-9._]{1,30}$'
                                                          WHEN 'hashtag' THEN y !~ '^[^[:space:]#@,;]{1,100}$'
                                                          ELSE length(y) NOT BETWEEN 2 AND 60 OR y ~ '[[:cntrl:]]' END)
                   OR (SELECT count(*) FROM n) > 10 THEN NULL
              ELSE ARRAY(SELECT y FROM n ORDER BY o) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_monat_text(p date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT (ARRAY['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'])[extract(month FROM p)::integer]
    || ' ' || extract(year FROM p)::integer
$function$
;

CREATE OR REPLACE FUNCTION public.talents_notiz_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb; u text; adm boolean;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  fehler text; m text; tid integer; nid bigint; n talent_notizen%ROWTYPE; x text;
BEGIN
  c := talents_aktion_start(p_token, false);
  IF c ? 'stumm' THEN RETURN c - 'stumm'; END IF;
  IF NOT (c->>'ok')::boolean THEN
    fehler := c->>'fehler';
  ELSE
    u := c->>'u'; adm := (c->>'adm')::boolean;
    x := replace(replace(coalesce(d->>'text', ''), E'\r\n', E'\n'), E'\r', E'\n');
    x := btrim(regexp_replace(x, '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f]', '', 'g'));
    BEGIN
      IF p_aktion = 'notiz_neu' THEN
        tid := CASE WHEN btrim(coalesce(d->>'talent_id', '')) ~ '^[0-9]{1,9}$' THEN btrim(d->>'talent_id')::integer END;
        IF tid IS NULL OR NOT talent_sichtbar(u, tid) THEN
          fehler := 'Unbekanntes Talent. Bitte die Seite neu laden.';
        -- Migration 66: Notizen schreibt nur, wer das Talent verwalten darf („Talents ansehen“ allein erlaubt keine Änderungen)
        ELSIF NOT talent_verwaltbar(u, tid) THEN
          fehler := 'Notizen schreibt, wer das Recht „Talents und Kampagnen verwalten“ für dieses Talent hat.';
        ELSIF x = '' THEN
          fehler := 'Bitte einen Text für die Notiz eingeben.';
        ELSIF length(x) > 4000 THEN
          fehler := 'Die Notiz darf höchstens 4000 Zeichen haben.';
        ELSE
          INSERT INTO talent_notizen (talent_id, text, erstellt_von) VALUES (tid, x, u) RETURNING id INTO nid;
          m := 'Notiz gespeichert.';
        END IF;
      ELSIF p_aktion IN ('notiz_bearbeiten', 'notiz_loeschen') THEN
        IF btrim(coalesce(d->>'id', '')) ~ '^[0-9]{1,15}$' THEN
          SELECT * INTO n FROM talent_notizen WHERE id = btrim(d->>'id')::bigint FOR UPDATE;
        END IF;
        tid := n.talent_id; nid := n.id;
        IF n.id IS NULL OR NOT talent_sichtbar(u, n.talent_id) THEN
          fehler := 'Unbekannte Notiz. Bitte die Seite neu laden.';
        ELSIF NOT talent_verwaltbar(u, n.talent_id) THEN
          fehler := 'Notizen ändert, wer das Recht „Talents und Kampagnen verwalten“ für dieses Talent hat.';
        ELSIF NOT (n.erstellt_von = u OR adm) THEN
          fehler := CASE WHEN p_aktion = 'notiz_loeschen' THEN 'Löschen' ELSE 'Ändern' END || ' kann nur, wer die Notiz geschrieben hat, oder eine Person mit der Rolle Admin.';
        ELSIF p_aktion = 'notiz_loeschen' AND lower(btrim(coalesce(d->>'bestaetigt', ''))) NOT IN ('true', 'ja', '1') THEN
          fehler := 'Bitte das Löschen der Notiz bestätigen.';
        ELSIF p_aktion = 'notiz_loeschen' THEN
          PERFORM talents_profil_pk_legen('notiz', n.id, u);  -- Migration 130: in den Papierkorb
          m := 'Notiz liegt jetzt im Papierkorb. Im Papierkorb kannst du sie wiederherstellen.';
        ELSIF x = '' THEN
          fehler := 'Bitte einen Text für die Notiz eingeben.';
        ELSIF length(x) > 4000 THEN
          fehler := 'Die Notiz darf höchstens 4000 Zeichen haben.';
        ELSE
          UPDATE talent_notizen SET text = x, geaendert_am = now(), geaendert_von = u WHERE id = n.id;
          m := 'Notiz geändert.';
        END IF;
      ELSE
        fehler := 'Unbekannte Aktion.';
      END IF;
    EXCEPTION WHEN OTHERS THEN
      fehler := 'Das hat nicht geklappt. Bitte noch einmal versuchen. (' || left(SQLERRM, 200) || ')';
    END;
  END IF;
  RETURN talents_aktion_ende(p_token, fehler, m, NULL, jsonb_build_object('talent_id', tid, 'notiz_id', nid));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_notiz_json(p_id bigint, p_user text, p_admin boolean)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('id', n.id, 'talent_id', n.talent_id, 'text', n.text, 'datum', talents_zeit(n.erstellt_am), 'datum_kurz', talents_datum(n.erstellt_am),
    'autor', coalesce((SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = n.erstellt_von), 'Ehemalige Person'),
    'eigene', n.erstellt_von = p_user, 'darf_bearbeiten', n.erstellt_von = p_user OR coalesce(p_admin, false),
    'geaendert', CASE WHEN n.geaendert_am IS NOT NULL THEN 'geändert am ' || talents_zeit(n.geaendert_am)
      || coalesce(' von ' || (SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = n.geaendert_von), '') END)
  FROM talent_notizen n WHERE n.id = p_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_notizen(p_token text, p_talent_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; u text; adm boolean; anz integer; seite integer; je integer := 10;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  u := c->>'u'; adm := ally_hat_recht(u, 'admin');
  IF NOT coalesce(talent_sichtbar(u, p_talent_id), false) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Dieses Talent gibt es nicht oder du bist nicht als Manager oder Managerin eingetragen.');
  END IF;
  SELECT count(*)::integer INTO anz FROM talent_notizen n WHERE n.talent_id = p_talent_id;
  seite := talents_seite_nr(CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter->>'seite' END, anz, je);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_verwalten', (c->>'verw')::boolean, 'darf_schreiben', coalesce(talent_verwaltbar(u, p_talent_id), false),
    'talent', (SELECT jsonb_build_object('id', t.id, 'anzeigename', talent_listenname(t.id), 'archiviert', t.status = 'archiviert') FROM talents t WHERE t.id = p_talent_id),
    'notizen', (SELECT coalesce(jsonb_agg(talents_notiz_json(x.id, u, adm) ORDER BY x.erstellt_am DESC, x.id DESC), '[]'::jsonb)
                FROM (SELECT n.id, n.erstellt_am FROM talent_notizen n WHERE n.talent_id = p_talent_id ORDER BY n.erstellt_am DESC, n.id DESC
                      OFFSET (seite - 1) * je LIMIT je) x),
    'anzahl', anz, 'seite', seite, 'seiten', greatest(1, ceil(anz / je::numeric)::integer), 'je_seite', je, 'max_zeichen', 4000,
    'leer_text', CASE WHEN anz = 0 THEN 'Noch keine Notizen.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_person_zugriff(p_user text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  u text := btrim(coalesce(p_user, ''));
  z text;
BEGIN
  IF u = '' OR NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = u AND p.aktiv) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Person ist nicht (mehr) eingerichtet.');
  END IF;
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  z := talents_zugriff(u);
  IF z IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Für Talents fehlt dir das Recht „Talents ansehen“. Rechte vergibt eine Person mit der Rolle Admin.');
  END IF;
  RETURN jsonb_build_object('ok', true, 'u', u, 'zugriff', z, 'verw', ally_hat_recht(u, 'talents_verwalten'));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_art_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'aufgabe' THEN 'Aufgabe' WHEN 'review' THEN 'Review zu Content' WHEN 'termin' THEN 'Termin' WHEN 'erinnerung' THEN 'Erinnerung' ELSE coalesce(p, '') END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_aufgabe_json(p_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('id', a.id, 'talent_id', a.talent_id, 'art', a.art, 'art_text', talents_planung_art_text(a.art), 'titel', a.titel, 'text', a.text, 'ort', a.ort,
    'zeit', coalesce(a.beginn, a.faellig_am), 'wann_text', talents_planung_zeit_text(coalesce(a.beginn, a.faellig_am), a.ganztags),
    'wann_iso', to_char(coalesce(a.beginn, a.faellig_am) AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD"T"HH24:MI'),
    'ende_iso', to_char(a.ende AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD"T"HH24:MI'), 'ganztags', a.ganztags,
    'heute_oder_frueher', (coalesce(a.beginn, a.faellig_am) AT TIME ZONE 'Europe/Berlin')::date <= talents_heute(),
    'kanaele', to_jsonb(a.kanaele), 'kanaele_text', talents_planung_kanaele_text(a.kanaele), 'intern', cardinality(a.kanaele) = 0,
    'status', a.status, 'status_text', CASE a.status WHEN 'offen' THEN 'offen' WHEN 'erledigt' THEN 'erledigt' ELSE 'abgesagt' END,
    'erledigt_text', CASE WHEN a.status = 'erledigt' THEN talents_planung_zeit_text(a.erledigt_am, false) || CASE WHEN a.erledigt_von = 'talent' THEN ' vom Talent' ELSE '' END END,
    'quelle', a.quelle, 'quelle_text', CASE a.quelle WHEN 'regel' THEN 'Erinnerungsregel' WHEN 'review' THEN 'Freigabe' ELSE CASE WHEN a.kampagne_id IS NOT NULL THEN 'aus der Kampagne' ELSE '' END END,
    'kampagne_id', a.kampagne_id, 'kampagne', (SELECT k.marke || ' – ' || k.name FROM talent_kampagnen k WHERE k.id = a.kampagne_id),
    'deliverable_id', a.deliverable_id, 'deliverable', (SELECT talents_planung_deliverable_name(d.format, d.anzahl, d.titel) FROM talent_deliverables d WHERE d.id = a.deliverable_id),
    'version_link', (SELECT v.link FROM talent_deliverable_versionen v WHERE v.id = a.version_id),
    'mail_text', CASE a.mail_status WHEN 'offen' THEN 'Mail vorgemerkt' WHEN 'gesendet' THEN 'Mail gesendet' WHEN 'fehler' THEN 'Mail nicht gesendet' END)
  FROM talent_aufgaben a WHERE a.id = p_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_betrag_lesen(p text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  x text := regexp_replace(coalesce(p, ''), '[[:space:]€$£]|EUR|CHF|USD|GBP', '', 'gi');
  e text;
BEGIN
  -- Betrag in Cent: leer = NULL, ungültig = -1. Erlaubt 18000, 18.000, 18.000,50, 1500,5 (Komma als Dezimalzeichen, Punkt nur als Tausendertrenner).
  IF x = '' THEN RETURN NULL; END IF;
  IF x ~ '^[0-9]{1,3}([.][0-9]{3})+(,[0-9]{1,2})?$' OR x ~ '^[0-9]{1,12}(,[0-9]{1,2})?$' THEN
    e := replace(split_part(x, ',', 1), '.', '');
    IF length(e) > 9 THEN RETURN -1; END IF;
    RETURN e::bigint * 100 + rpad(split_part(x, ',', 2), 2, '0')::bigint;
  END IF;
  RETURN -1;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_betrag_text(p_cent bigint)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- 1800000 -> "18.000 €", 150050 -> "1.500,50 €"
  SELECT CASE WHEN p_cent IS NULL THEN NULL ELSE
    replace(to_char(p_cent / 100, 'FM999,999,999,990'), ',', '.') || CASE WHEN p_cent % 100 <> 0 THEN ',' || lpad((p_cent % 100)::text, 2, '0') ELSE '' END
    || CASE talents_planung_waehrung() WHEN 'EUR' THEN ' €' ELSE ' ' || talents_planung_waehrung() END END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_deliverable_json(p_id bigint, p_geld boolean)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Ein Deliverable für die Oberfläche (BA6). Honorar nur mit p_geld. Versionen (Entwürfe als Link) neueste zuerst.
  SELECT jsonb_build_object('id', d.id, 'kampagne_id', d.kampagne_id, 'talent_id', d.talent_id, 'talent', coalesce(talent_listenname(d.talent_id), 'Talent ' || d.talent_id),
    'plattform', d.plattform, 'plattform_text', talents_planung_plattform_text(d.plattform), 'format', d.format, 'format_text', talents_planung_format_text(d.format),
    'anzahl', d.anzahl, 'titel', d.titel, 'name', talents_planung_deliverable_name(d.format, d.anzahl, d.titel),
    'deadline_iso', to_char(d.deadline, 'YYYY-MM-DD'), 'deadline_text', talents_planung_tag_text(d.deadline), 'deadline_datum', to_char(d.deadline, 'DD.MM.YYYY'),
    'veroeffentlichen_iso', to_char(d.veroeffentlichen_am, 'YYYY-MM-DD'), 'veroeffentlichen_text', talents_planung_tag_text(d.veroeffentlichen_am),
    'status', d.status, 'status_text', talents_planung_status_text(d.status),
    'offen', d.status IN ('geplant', 'entwurf', 'ueberarbeiten'),
    'erledigt', d.status IN ('veroeffentlicht', 'abgerechnet'),
    'ueberfaellig', d.status IN ('geplant', 'entwurf', 'ueberarbeiten') AND d.deadline < talents_heute(),
    'darf_honorar', coalesce(p_geld, false), 'honorar_cent', CASE WHEN p_geld THEN d.honorar_cent END, 'honorar_text', CASE WHEN p_geld THEN talents_planung_betrag_text(d.honorar_cent) END,
    'link', d.link, 'notiz', d.notiz, 'sichtbar_fuer_talent', d.sichtbar_fuer_talent, 'beitrag_id', d.beitrag_id,
    'versionen', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'version', v.version, 'quelle', v.quelle, 'link', v.link, 'dienst_text', talents_planung_dienst_text(v.dienst),
        'kommentar', v.kommentar, 'eingereicht_text', talents_planung_zeit_text(v.eingereicht_am, false),
        'eingereicht_von', CASE WHEN v.quelle = 'talent' THEN coalesce(talent_listenname(d.talent_id), 'Talent') ELSE coalesce((SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = v.eingereicht_von), 'Team') END,
        'pruefung', v.pruefung, 'pruefung_text', talents_planung_pruefung_text(v.pruefung), 'pruef_kommentar', v.pruef_kommentar, 'marke_kommentar', v.marke_kommentar,
        'geprueft_text', talents_planung_zeit_text(v.geprueft_am, false)) ORDER BY v.version DESC), '[]'::jsonb)
      FROM talent_deliverable_versionen v WHERE v.deliverable_id = d.id),
    'aufgaben_offen', (SELECT count(*) FROM talent_aufgaben a WHERE a.deliverable_id = d.id AND a.status = 'offen' AND a.art IN ('aufgabe', 'review')))
  FROM talent_deliverables d WHERE d.id = p_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_deliverable_name(p_format text, p_anzahl integer, p_titel text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- "Reel „Herbstkollektion“", "Story (3)"; Migration 183: "Reel Herbstlook" statt "Reel „Reel Herbstlook“", "Story Herbst (3)" statt "Story (3) „Story Herbst“"
  SELECT CASE WHEN x.t IS NOT NULL AND translate(left(x.t, length(x.f)), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') = translate(x.f, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz')
                   AND (length(x.t) = length(x.f) OR substr(x.t, length(x.f) + 1, 1) IN (' ', chr(9), chr(160)))
              THEN x.t || x.n
              ELSE x.f || x.n || CASE WHEN x.t IS NOT NULL THEN ' „' || x.t || '“' ELSE '' END END
  FROM (SELECT talents_planung_format_text(p_format) AS f, CASE WHEN coalesce(p_anzahl, 1) > 1 THEN ' (' || p_anzahl || ')' ELSE '' END AS n,
               nullif(btrim(coalesce(p_titel, '')), '') AS t) x
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_dienst(p_link text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Cloud-Dienst eines Links (gleiche Schlüssel wie talent_ablage_dienste), sonst 'sonstige'
  SELECT CASE
    WHEN h ~ '(^|[.])(drive|docs)[.]google[.]com$' THEN 'google_drive'
    WHEN h ~ '(^|[.])sharepoint[.]com$' THEN 'sharepoint'
    WHEN h ~ '(^|[.])(onedrive[.]live[.]com|1drv[.]ms)$' THEN 'onedrive'
    WHEN h ~ '(^|[.])(dropbox[.]com|db[.]tt)$' THEN 'dropbox'
    ELSE 'sonstige' END
  FROM (SELECT lower(substring(coalesce(p_link, '') FROM '^https://([^/:?#]+)')) AS h) x
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_dienst_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'google_drive' THEN 'Google Drive' WHEN 'onedrive' THEN 'OneDrive' WHEN 'sharepoint' THEN 'SharePoint' WHEN 'dropbox' THEN 'Dropbox' ELSE 'Link' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_einstellungen_ui(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb;
BEGIN
  -- Einstellungen › Kampagnen (BA6, ALLY 23): Standard-Erinnerungen (ändern mit „Talents verwalten“) und Währung der Beträge (nur Admin)
  c := talents_planung_start(p_token, 'kampagnen');
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  RETURN jsonb_build_object('ok', true, 'darf_regeln', (c->>'verw')::boolean, 'admin', (c->>'adm')::boolean, 'waehrung', talents_planung_waehrung(),
    'regeln', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'bezug', r.bezug, 'versatz_tage', r.versatz_tage, 'uhrzeit', to_char(r.uhrzeit, 'HH24:MI'), 'empfaenger', r.empfaenger,
        'kanaele', to_jsonb(r.kanaele), 'aktiv', r.aktiv, 'text', talents_planung_regel_text(r.bezug, r.versatz_tage),
        'empfaenger_text', CASE r.empfaenger WHEN 'talent' THEN 'an das Talent' ELSE 'an den Manager oder die Managerin' END,
        'kanaele_text', CASE WHEN r.empfaenger = 'zustaendig' THEN 'Benachrichtigung' ELSE talents_planung_kanaele_text(r.kanaele) END)
        ORDER BY r.empfaenger DESC, r.versatz_tage, r.bezug, r.id), '[]'::jsonb) FROM talent_erinnerungsregeln r WHERE r.kampagne_id IS NULL AND r.geloescht_am IS NULL),
    -- Migration 129: Papierkorb der Standard-Erinnerungen (nur wer sie ändern darf)
    'papierkorb', CASE WHEN (c->>'verw')::boolean THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'text', talents_planung_regel_text(r.bezug, r.versatz_tage),
        'empfaenger_text', CASE r.empfaenger WHEN 'talent' THEN 'an das Talent' ELSE 'an den Manager oder die Managerin' END,
        'geloescht', to_char(r.geloescht_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI'),
        'von', coalesce((SELECT nx.anzeigename FROM ally_nutzer nx WHERE nx.matrix_user_id = r.geloescht_von), r.geloescht_von))
        ORDER BY r.geloescht_am DESC, r.id DESC), '[]'::jsonb) FROM talent_erinnerungsregeln r WHERE r.kampagne_id IS NULL AND r.geloescht_am IS NOT NULL) END,
    'kampagnen_eigene', (SELECT count(DISTINCT r.kampagne_id) FROM talent_erinnerungsregeln r WHERE r.kampagne_id IS NOT NULL));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_empfaenger(p_talent_id integer, p_kampagne_id integer)
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
  -- Zuständige Personen für Meldungen zu einem Talent bzw. Deliverable: für das Talent zuständig, für die Kampagne zuständig (nur wenn die Person das Talent sieht); sonst die Admins.
  WITH z AS (
    SELECT p.matrix_user_id FROM talent_kampagnen k JOIN ally_personen p ON p.matrix_user_id = k.zustaendig AND p.aktiv
    WHERE k.id = p_kampagne_id AND talents_zugriff(p.matrix_user_id) IS NOT NULL AND coalesce(talent_sichtbar(p.matrix_user_id, p_talent_id), false)
    UNION
    SELECT p.matrix_user_id FROM talent_personen tp JOIN ally_personen p ON p.matrix_user_id = tp.matrix_user_id AND p.aktiv
    WHERE tp.talent_id = p_talent_id AND talents_zugriff(p.matrix_user_id) IS NOT NULL)
  SELECT CASE WHEN EXISTS (SELECT 1 FROM z) THEN ARRAY(SELECT z.matrix_user_id FROM z ORDER BY 1)
    ELSE ARRAY(SELECT p.matrix_user_id FROM ally_personen p WHERE p.aktiv AND ally_hat_recht(p.matrix_user_id, 'admin') ORDER BY 1) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_export_daten(p_ids integer[], p_teil text, p_offset integer, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  r jsonb;
BEGIN
  IF p_teil = 'deliverables' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(d.id, d.kampagne_id, d.talent_id, d.plattform, d.format, d.anzahl, d.titel, to_char(d.deadline, 'YYYY-MM-DD'), to_char(d.veroeffentlichen_am, 'YYYY-MM-DD'),
        d.status, d.honorar_cent, d.link, d.notiz, CASE WHEN d.sichtbar_fuer_talent THEN 'ja' ELSE 'nein' END, talents_export_zeit(d.erstellt_am)) AS z,
        row_number() OVER (ORDER BY d.talent_id, d.kampagne_id, d.deadline, d.id) AS o, count(*) OVER () AS n
      FROM talent_deliverables d WHERE d.talent_id = ANY (p_ids) ORDER BY d.talent_id, d.kampagne_id, d.deadline, d.id OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'entwuerfe' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(v.id, v.deliverable_id, d.talent_id, v.version, v.quelle, v.link, v.kommentar, talents_export_zeit(v.eingereicht_am), v.pruefung, v.pruef_kommentar,
        talents_export_zeit(v.geprueft_am), talents_export_zeit(v.marke_am), v.marke_kommentar) AS z,
        row_number() OVER (ORDER BY d.talent_id, v.deliverable_id, v.version) AS o, count(*) OVER () AS n
      FROM talent_deliverable_versionen v JOIN talent_deliverables d ON d.id = v.deliverable_id WHERE d.talent_id = ANY (p_ids)
      ORDER BY d.talent_id, v.deliverable_id, v.version OFFSET p_offset LIMIT p_limit) q;
  ELSIF p_teil = 'aufgaben' THEN
    SELECT jsonb_build_object('anzahl', coalesce(max(q.n), 0), 'zeilen', coalesce(jsonb_agg(q.z ORDER BY q.o), '[]'::jsonb)) INTO r FROM (
      SELECT jsonb_build_array(a.id, a.talent_id, a.kampagne_id, a.deliverable_id, a.art, a.titel, a.text, a.ort, talents_export_zeit(a.beginn), talents_export_zeit(a.ende),
        talents_export_zeit(a.faellig_am), array_to_string(a.kanaele, ','), a.status, talents_export_zeit(a.erledigt_am), talents_export_zeit(a.erstellt_am)) AS z,
        row_number() OVER (ORDER BY a.talent_id, a.erstellt_am, a.id) AS o, count(*) OVER () AS n
      FROM talent_aufgaben a WHERE a.talent_id = ANY (p_ids) ORDER BY a.talent_id, a.erstellt_am, a.id OFFSET p_offset LIMIT p_limit) q;
  END IF;
  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_export_teile()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Teile 17 bis 19 des Talent-Exports (DSGVO, BA6): Deliverables, Entwürfe und Freigaben, Aufgaben/Termine/Erinnerungen
  SELECT jsonb_agg(jsonb_build_object('teil', x.t, 'datei', x.t || '.csv', 'titel', x.ti,
    'spalten', (SELECT jsonb_agg(jsonb_build_object('name', split_part(s, '|', 1), 'beschreibung', split_part(s, '|', 2)) ORDER BY o) FROM unnest(x.sp) WITH ORDINALITY AS u(s, o))) ORDER BY x.o)
  FROM (VALUES
    (17, 'deliverables', 'Deliverables in Kampagnen', ARRAY['deliverable_id|Nummer des Deliverables', 'kampagne_id|Kampagne', 'talent_id|Talent', 'plattform|Plattform',
      'format|Format', 'anzahl|Anzahl', 'titel|Titel', 'deadline|Deadline (JJJJ-MM-TT)', 'veroeffentlichen_am|Veröffentlichung (JJJJ-MM-TT)', 'status|Status',
      'honorar|Honorar in Cent (nur mit dem Recht „Honorare und Budgets sehen“, sonst leer)', 'link|Link zum veröffentlichten Beitrag', 'notiz|Notiz der Agentur', 'sichtbar_fuer_talent|ja = im Talent-Bereich sichtbar', 'erstellt_am|angelegt am']),
    (18, 'entwuerfe', 'Entwürfe (Links) und Freigaben', ARRAY['version_id|Nummer', 'deliverable_id|Deliverable', 'talent_id|Talent', 'version|Version', 'quelle|talent oder team',
      'link|Link zum Entwurf beim Cloud-Dienst', 'kommentar|Kommentar beim Einreichen', 'eingereicht_am|eingereicht am', 'pruefung|Stand der Prüfung',
      'pruef_kommentar|Kommentar der Prüfung', 'geprueft_am|geprüft am', 'marke_am|an die Marke gegeben am', 'marke_kommentar|Kommentar der Marke']),
    (19, 'aufgaben', 'Aufgaben, Reviews, Termine und Erinnerungen', ARRAY['aufgabe_id|Nummer', 'talent_id|Talent', 'kampagne_id|Kampagne', 'deliverable_id|Deliverable',
      'art|aufgabe, review, termin oder erinnerung', 'titel|Titel', 'text|Text', 'ort|Ort', 'beginn|Beginn (Termin)', 'ende|Ende (Termin)', 'faellig_am|fällig am',
      'kanaele|Wege zum Talent (bereich, kalender, mail; leer = nur intern)', 'status|offen, erledigt oder abgesagt', 'erledigt_am|erledigt am', 'erstellt_am|angelegt am'])
  ) AS x(o, t, ti, sp)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_format_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'post' THEN 'Post' WHEN 'karussell' THEN 'Karussell' WHEN 'reel' THEN 'Reel' WHEN 'story' THEN 'Story' WHEN 'video' THEN 'Video'
    WHEN 'short' THEN 'Short' WHEN 'live' THEN 'Live' ELSE 'Beitrag' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_frist_text(p_bezug text, p_versatz integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Erinnerung aus Sicht des Tages: "Deadline in 3 Tagen", "Deadline heute", "Deadline seit 1 Tag überfällig"
  SELECT CASE WHEN p_bezug = 'veroeffentlichung' THEN 'Veröffentlichung' ELSE 'Deadline' END || ' ' ||
    CASE WHEN p_versatz = 0 THEN 'heute' WHEN p_versatz = -1 THEN 'morgen' WHEN p_versatz < 0 THEN 'in ' || (-p_versatz) || ' Tagen'
         WHEN p_versatz = 1 THEN 'seit 1 Tag überfällig' ELSE 'seit ' || p_versatz || ' Tagen überfällig' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_geld(p_user text, p_kampagne_id integer, p_talent_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Honorare und Budgets (Migration 64): Recht „Honorare und Budgets sehen“. Reichweite „alle“: alle; „zugeordnete“: Kampagnen, für die die Person
  -- zuständig ist (Budget und Honorare der Kampagne), und die eigenen Talents (Honorare). Talents sehen nie Beträge.
  SELECT CASE ally_recht_reichweite(p_user, 'talents_betraege')
    WHEN 'alle' THEN true
    WHEN 'zugeordnet' THEN EXISTS (SELECT 1 FROM talent_kampagnen k WHERE k.id = p_kampagne_id AND k.zustaendig = p_user)
      OR (p_talent_id IS NOT NULL AND EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = p_talent_id AND tp.matrix_user_id = p_user))
    ELSE false END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_kampagne_status(p_von date, p_bis date, p_abgebrochen timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN p_abgebrochen IS NOT NULL THEN 'abgebrochen' ELSE talents_kampagne_status(p_von, p_bis) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_kanaele_text(p text[])
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN coalesce(cardinality(p), 0) = 0 THEN 'nur intern' ELSE
    array_to_string(ARRAY(SELECT CASE k WHEN 'bereich' THEN 'Talent-Bereich' WHEN 'kalender' THEN 'Kalender des Talents' WHEN 'mail' THEN 'Mail' WHEN 'glocke' THEN 'Benachrichtigung'
      ELSE k END FROM unnest(p) WITH ORDINALITY AS u(k, o) ORDER BY CASE k WHEN 'bereich' THEN 1 WHEN 'kalender' THEN 2 WHEN 'mail' THEN 3 ELSE 4 END, o), ', ') END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_link(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Link auf einen Cloud-Dienst (BA6): nur https mit Rechnername, ohne Leerzeichen und spitze Klammern, höchstens 2000 Zeichen. Ungültig = NULL.
  -- Content und Dateien liegen nie auf dem Server, Ally speichert nur den Link.
  SELECT CASE WHEN length(btrim(coalesce(p, ''))) <= 2000 AND btrim(coalesce(p, '')) ~ '^https://[A-Za-z0-9.-]{3,253}(:[0-9]{1,5})?([/?#][^[:space:]<>"]*)?$'
    THEN btrim(p) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_link_oeffnen(p_token text, p_art text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; u text; lk text; kid integer; tid integer;
BEGIN
  -- Link zum Öffnen (BA6; ALLY 20 leitet mit 303 weiter, der Baukasten kennt nur interne Ziele): kl = Datei der Marke, v = Entwurf, d = veröffentlichter Beitrag.
  -- Nur mit Zugriff auf Kampagne bzw. Talent; nur https-Links aus der Datenbank.
  -- Migration 75 (Content-Galerie, Stefan 21.10.2026): b = Beitrag eines Talents auf der Plattform (talent_beitraege.link) aus dem Talent-Profil;
  -- nur wer das Talent sehen darf („Talents ansehen“ und zuständig bzw. alle), unabhängig vom Recht an Kampagnen.
  IF p_art = 'b' THEN
    IF coalesce(p_id, '') !~ '^[0-9]{1,15}$' THEN RETURN jsonb_build_object('ok', false); END IF;
    c := talents_ansicht_start(p_token);
    IF NOT coalesce((c->>'ok')::boolean, false) THEN RETURN jsonb_build_object('ok', false); END IF;
    SELECT b.link, k.talent_id INTO lk, tid FROM talent_beitraege b JOIN talent_kanaele k ON k.id = b.kanal_id WHERE b.id = p_id::bigint;
    IF tid IS NULL OR NOT coalesce(talent_sichtbar(c->>'u', tid), false) THEN lk := NULL; END IF;
    lk := talents_planung_link(lk);
    RETURN jsonb_build_object('ok', lk IS NOT NULL, 'url', lk);
  END IF;
  c := talents_planung_start(p_token, 'kampagnen');
  IF NOT (c->>'ok')::boolean THEN RETURN jsonb_build_object('ok', false); END IF;
  u := c->>'u';
  IF coalesce(p_id, '') !~ '^[0-9]{1,15}$' THEN RETURN jsonb_build_object('ok', false); END IF;
  IF p_art = 'kl' THEN
    SELECT l.link, l.kampagne_id INTO lk, kid FROM talent_kampagne_links l WHERE l.id = p_id::bigint;
    IF talents_planung_recht(u, kid) IS NULL THEN lk := NULL; END IF;
  ELSIF p_art = 'v' THEN
    SELECT v.link, d.kampagne_id, d.talent_id INTO lk, kid, tid FROM talent_deliverable_versionen v JOIN talent_deliverables d ON d.id = v.deliverable_id WHERE v.id = p_id::bigint;
    IF NOT coalesce(talents_planung_talent_ok(u, kid, tid), false) THEN lk := NULL; END IF;
  ELSIF p_art = 'd' THEN
    SELECT d.link, d.kampagne_id, d.talent_id INTO lk, kid, tid FROM talent_deliverables d WHERE d.id = p_id::bigint;
    IF NOT coalesce(talents_planung_talent_ok(u, kid, tid), false) THEN lk := NULL; END IF;
  END IF;
  lk := talents_planung_link(lk);
  RETURN jsonb_build_object('ok', lk IS NOT NULL, 'url', lk);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_management(p_user text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- „Talents und Kampagnen verwalten“ nur für zugeordnete Talents (Migration 64; bisher Rolle Management): eigene Talents anlegen und verwalten,
  -- Kampagnen für eigene Talents anlegen und planen. Wer das Recht für alle hat (oder Admin ist), zählt nicht dazu.
  SELECT coalesce(ally_recht_reichweite(p_user, 'talents_verwalten') = 'zugeordnet', false)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_personen_melden(p_personen text[], p_art text, p_titel text, p_text text, p_ziel jsonb, p_ref text, p_ohne text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  p text; e jsonb; n integer := 0;
BEGIN
  -- Benachrichtigung an mehrere Personen über ally_benachrichtigen (Migration 58); die auslösende Person (p_ohne) bekommt keine
  FOREACH p IN ARRAY coalesce(p_personen, '{}'::text[]) LOOP
    CONTINUE WHEN p IS NOT DISTINCT FROM p_ohne;
    e := ally_benachrichtigen(p, p_art, p_titel, p_text, p_ziel, p_ref, 'Kampagnen', false);
    IF coalesce((e->>'neu')::boolean, false) THEN n := n + 1; END IF;
  END LOOP;
  RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_planen(p_user text, p_kampagne_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Kampagne planen (Budget, Ziele, Briefing, Links, Erinnerungsregeln, Abbrechen; Migration 64): „Talents und Kampagnen verwalten“ für alle,
  -- oder für zugeordnete und für die Kampagne zuständig. Nur „Talents ansehen“ reicht nicht.
  SELECT coalesce((SELECT CASE ally_recht_reichweite(p_user, 'talents_verwalten') WHEN 'alle' THEN true
                               WHEN 'zugeordnet' THEN k.zustaendig IS NOT DISTINCT FROM p_user ELSE false END
    FROM talent_kampagnen k WHERE k.id = p_kampagne_id), false)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_plattform_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'instagram' THEN 'Instagram' WHEN 'tiktok' THEN 'TikTok' WHEN 'youtube' THEN 'YouTube' WHEN 'facebook' THEN 'Facebook' WHEN 'threads' THEN 'Threads'
    WHEN 'pinterest' THEN 'Pinterest' WHEN 'linkedin' THEN 'LinkedIn' ELSE 'Sonstige' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_prozent_lesen(p text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Prozentwert 0 bis 100 mit höchstens 2 Nachkommastellen (Komma oder Punkt): leer = NULL, ungültig = -1
  SELECT CASE WHEN x = '' THEN NULL
              WHEN x ~ '^[0-9]{1,3}([.,][0-9]{1,2})?$' AND replace(x, ',', '.')::numeric <= 100 THEN replace(x, ',', '.')::numeric
              ELSE -1 END
  FROM (SELECT regexp_replace(coalesce(p, ''), '[[:space:]%]', '', 'g') AS x) y
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_pruefung_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'offen' THEN 'wartet auf Prüfung' WHEN 'intern_ok' THEN 'intern geprüft' WHEN 'ueberarbeiten' THEN 'Überarbeiten' WHEN 'bei_marke' THEN 'bei der Marke'
    WHEN 'marke_aenderung' THEN 'Änderung der Marke' WHEN 'freigegeben' THEN 'freigegeben' WHEN 'ersetzt' THEN 'ersetzt' ELSE coalesce(p, '') END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_recht(p_user text, p_kampagne_id integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Zugriff auf eine Kampagne (BA6, Rollen nach Stefan 20.10.2026): 'alle' = alle Talents der Kampagne (Admin oder „Talents ansehen“ für alle; nur sehen, Ändern über talents_planung_talent_verwaltbar);
  -- 'eigene' = nur die eigenen Talents (für die Kampagne oder für eines ihrer Talents zuständig); NULL = kein Zugriff.
  -- Talents anderer Personen sieht man mit 'eigene' nie. Planen: talents_planung_planen. Honorare und Budgets: talents_planung_geld.
  SELECT CASE WHEN zz.z IS NULL OR k.id IS NULL THEN NULL
              WHEN zz.z = 'alle' THEN 'alle'
              WHEN k.zustaendig = p_user OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt JOIN talent_personen tp ON tp.talent_id = kt.talent_id
                           WHERE kt.kampagne_id = k.id AND tp.matrix_user_id = p_user) THEN 'eigene' END
  FROM (SELECT talents_zugriff(p_user) AS z) zz LEFT JOIN talent_kampagnen k ON k.id = p_kampagne_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_regel_text(p_bezug text, p_versatz integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Regel: "3 Tage vorher", "am Tag der Deadline", "1 Tag überfällig", "am Tag der Veröffentlichung"
  SELECT CASE WHEN p_versatz = 0 THEN 'am Tag der ' || CASE WHEN p_bezug = 'veroeffentlichung' THEN 'Veröffentlichung' ELSE 'Deadline' END
              WHEN p_versatz < 0 THEN (-p_versatz) || CASE WHEN p_versatz = -1 THEN ' Tag' ELSE ' Tage' END || ' vor der ' || CASE WHEN p_bezug = 'veroeffentlichung' THEN 'Veröffentlichung' ELSE 'Deadline' END
              ELSE p_versatz || CASE WHEN p_versatz = 1 THEN ' Tag' ELSE ' Tage' END || ' überfällig' || CASE WHEN p_bezug = 'veroeffentlichung' THEN ' (Veröffentlichung)' ELSE '' END END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_start(p_token text, p_seite text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; s record;
BEGIN
  -- Gemeinsamer Anfang der Kampagnen-Funktionen (BA6): angemeldet, Paket Talents, Recht für Talents, Seite für die Rolle freigegeben (Register).
  -- Talents (Rolle Talent) haben keine Person in ally_personen und kommen hier nie weiter.
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false, 'angemeldet', FOUND); END IF;
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c - 'u'; END IF;
  IF NOT (ally_ui_funktion_erlaubt(s.person, s.rolle, p_seite) OR (p_seite = 'talent' AND ally_ui_funktion_erlaubt(s.person, s.rolle, 'kampagnen'))) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Das ist für dich nicht freigeschaltet.');
  END IF;
  RETURN c || jsonb_build_object('rolle', s.rolle, 'adm', ally_hat_recht(s.person, 'admin'), 'mgmt', talents_planung_management(s.person));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_status_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'geplant' THEN 'geplant' WHEN 'entwurf' THEN 'Entwurf' WHEN 'pruefung' THEN 'Freigabe intern' WHEN 'ueberarbeiten' THEN 'Überarbeiten'
    WHEN 'bei_marke' THEN 'Freigabe Marke' WHEN 'freigegeben' THEN 'freigegeben' WHEN 'veroeffentlicht' THEN 'veröffentlicht' WHEN 'abgerechnet' THEN 'abgerechnet' ELSE coalesce(p, '') END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_tag_text(p date)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN p IS NULL THEN '' WHEN p = talents_heute() THEN 'heute' WHEN p = talents_heute() + 1 THEN 'morgen' WHEN p = talents_heute() - 1 THEN 'gestern'
    WHEN extract(year FROM p) = extract(year FROM talents_heute()) THEN to_char(p, 'DD.MM.') ELSE to_char(p, 'DD.MM.YYYY') END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_talent_ok(p_user text, p_kampagne_id integer, p_talent_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Darf die Person Einträge zu diesem Talent sehen und anlegen? Mit Kampagne: Talent gehört zur Kampagne und Zugriff 'alle' oder zuständig für das Talent.
  SELECT CASE WHEN p_kampagne_id IS NULL THEN coalesce(talent_sichtbar(p_user, p_talent_id), false)
    ELSE EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = p_kampagne_id AND kt.talent_id = p_talent_id)
         AND coalesce(CASE talents_planung_recht(p_user, p_kampagne_id) WHEN 'alle' THEN true WHEN 'eigene' THEN talent_sichtbar(p_user, p_talent_id) ELSE false END, false) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_talent_verwaltbar(p_user text, p_kampagne_id integer, p_talent_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Darf die Person Einträge zu diesem Talent anlegen und ändern (Deliverables, Freigaben, Aufgaben, Termine; Migration 66)? Mit Kampagne: Talent gehört zur Kampagne
  -- und die Person darf das Talent verwalten (talent_verwaltbar). Sehen bleibt bei talents_planung_talent_ok.
  SELECT CASE WHEN p_kampagne_id IS NULL THEN coalesce(talent_verwaltbar(p_user, p_talent_id), false)
    ELSE EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = p_kampagne_id AND kt.talent_id = p_talent_id)
         AND coalesce(talent_verwaltbar(p_user, p_talent_id), false) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_ui_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb; u text; verw boolean; adm boolean; mgmt boolean; zu text;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  fehler text; m text; r jsonb; recht text; geld boolean;
  k talent_kampagnen%ROWTYPE; dl talent_deliverables%ROWTYPE; v talent_deliverable_versionen%ROWTYPE; a talent_aufgaben%ROWTYPE; rg talent_erinnerungsregeln%ROWTYPE;
  x text; n integer; ids integer[]; t integer; betrag bigint; zahl1 bigint; zahl2 bigint; zahl3 bigint; proz numeric; dt1 date; dt2 date; z1 timestamptz; z2 timestamptz;
  kan text[]; lk text; neu_id bigint; seite text; name_d text; tname text; vs integer; ergebnis text; kom text; ar text; uz time; bz text; em text; ve integer;
  PLATT constant text[] := ARRAY['instagram', 'tiktok', 'youtube', 'facebook', 'threads', 'pinterest', 'linkedin', 'sonstige'];
  FORM constant text[] := ARRAY['post', 'karussell', 'reel', 'story', 'video', 'short', 'live', 'sonstiges'];
  STATI constant text[] := ARRAY['geplant', 'entwurf', 'pruefung', 'ueberarbeiten', 'bei_marke', 'freigegeben', 'veroeffentlicht', 'abgerechnet'];
BEGIN
  -- Aktionen der Kampagnenplanung (BA6, Migration 61), aufgerufen von ally_ui_aktion nach Sitzung, Schutzwert und Klappzuständen.
  -- tk_*: Kampagne anlegen, ändern, löschen, Beiträge zuordnen (talents_ui_kampagne_aktion = talents_kampagne_aktion mit den Rechten der Rollen, setzt die Meldung selbst).
  -- kp_*: Planung, Briefing, Links der Marke, Deliverables, Entwürfe und Freigaben, Erinnerungsregeln, Aufgaben/Termine/Erinnerungen je Talent.
  -- Rechte (Stefan 20.10.2026): sehen nach talents_planung_recht ('alle' = alle Talents, 'eigene' = nur eigene Talents), planen nach talents_planung_planen,
  -- Honorare und Budgets nach talents_planung_geld (Admin und zuständiges Management). Management legt Kampagnen für die eigenen Talents an und ist dann zuständig.
  -- Content nur als Link (https), nie als Datei. Benachrichtigungen an Talents über talents_benachrichtigen_talent, an Personen über ally_benachrichtigen.
  -- Migration 64: Budget einer neuen Kampagne nur mit „Honorare und Budgets sehen“ (alle, oder zugeordnete und selbst zuständig).
  seite := CASE WHEN p_aktion LIKE 'kp\_aufgabe\_%' THEN 'talent' ELSE 'kampagnen' END;
  c := talents_planung_start(p_token, seite);
  IF NOT coalesce((c->>'angemeldet')::boolean, false) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT (c->>'ok')::boolean THEN
    PERFORM ally_web_meldung(p_token, coalesce(c->>'fehler', 'Bitte neu anmelden.'), 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := c->>'u'; verw := (c->>'verw')::boolean; adm := (c->>'adm')::boolean; mgmt := (c->>'mgmt')::boolean;
  x := btrim(coalesce(d->>'kampagne_id', ''));
  IF x ~ '^[0-9]{1,9}$' THEN SELECT * INTO k FROM talent_kampagnen WHERE id = x::integer FOR UPDATE; END IF;

  -- ---------- Bestehende Kampagnen-Aktionen (wie ALLY 8) ----------
  IF p_aktion IN ('tk_kampagne_neu', 'tk_kampagne_bearbeiten', 'tk_kampagne_loeschen', 'tk_beitrag_bestaetigen', 'tk_beitrag_zuordnen', 'tk_beitrag_entfernen', 'tk_vorschlaege_bestaetigen') THEN
    IF p_aktion = 'tk_kampagne_neu' AND (verw OR mgmt) THEN
      -- Management legt Kampagnen für die eigenen Talents an und ist dann selbst zuständig (Stefan 20.10.2026)
      zu := CASE WHEN verw THEN nullif(btrim(coalesce(d->>'zustaendig', '')), '') ELSE u END;
      betrag := CASE WHEN ally_recht_reichweite(u, 'talents_betraege') = 'alle' OR (ally_recht_reichweite(u, 'talents_betraege') = 'zugeordnet' AND zu IS NOT DISTINCT FROM u)
                     THEN talents_planung_betrag_lesen(d->>'budget') END;
      IF zu IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = zu AND p.aktiv AND talents_zugriff(p.matrix_user_id) IS NOT NULL) THEN
        fehler := 'Diesen Manager oder diese Managerin gibt es nicht, oder ihm oder ihr fehlt das Recht für Talents.';
      ELSIF betrag = -1 THEN
        fehler := 'Bitte das Budget als Betrag angeben, z. B. 18.000 oder 1.500,50.';
      ELSIF NOT verw AND EXISTS (SELECT 1 FROM unnest(talents_liste(d->'talents')) y WHERE y !~ '^[0-9]{1,9}$' OR NOT coalesce(talent_verwaltbar(u, y::integer), false)) THEN
        fehler := 'In der Auswahl ist ein Talent, das dir nicht zugeordnet ist.';
      END IF;
    ELSIF p_aktion = 'tk_kampagne_bearbeiten' AND d ? 'talents' THEN
      x := btrim(coalesce(d->>'id', d->>'kampagne_id', ''));
      IF x ~ '^[0-9]{1,9}$' THEN
        ids := ARRAY(SELECT DISTINCT y::integer FROM unnest(talents_liste(d->'talents')) y WHERE y ~ '^[0-9]{1,9}$');
        IF NOT verw THEN
          -- Ohne „Talents verwalten“ nur eigene Talents wählen; Talents anderer Personen (hier nicht sichtbar) bleiben in der Kampagne
          IF EXISTS (SELECT 1 FROM unnest(ids) y WHERE NOT coalesce(talent_verwaltbar(u, y), false)) THEN
            fehler := 'In der Auswahl ist ein Talent, das dir nicht zugeordnet ist.';
          END IF;
          ids := ids || ARRAY(SELECT kt.talent_id FROM talent_kampagne_talents kt WHERE kt.kampagne_id = x::integer AND NOT coalesce(talent_verwaltbar(u, kt.talent_id), false));
          d := jsonb_set(d, '{talents}', to_jsonb(ARRAY(SELECT DISTINCT y::text FROM unnest(ids) y ORDER BY 1)));
        END IF;
        SELECT (SELECT count(*) FROM talent_deliverables dd WHERE dd.kampagne_id = x::integer AND NOT (dd.talent_id = ANY (ids)))
             + (SELECT count(*) FROM talent_aufgaben aa WHERE aa.kampagne_id = x::integer AND NOT (aa.talent_id = ANY (ids))) INTO n;
        IF fehler IS NULL AND n > 0 THEN
          fehler := 'Talents mit Deliverables oder Aufgaben in dieser Kampagne lassen sich nicht herausnehmen. Bitte zuerst deren Deliverables und Aufgaben löschen.';
        END IF;
      END IF;
    END IF;
    IF fehler IS NOT NULL THEN
      PERFORM ally_web_meldung(p_token, fehler, 'fehler', NULL);
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', fehler);
    END IF;
    r := talents_ui_kampagne_aktion(p_token, substr(p_aktion, 4), d - 'zustaendig' - 'budget');
    IF p_aktion = 'tk_kampagne_neu' AND coalesce((r->>'ok')::boolean, false) AND coalesce(r->>'kampagne_id', '') ~ '^[0-9]{1,9}$' THEN
      UPDATE talent_kampagnen SET zustaendig = zu, budget_cent = betrag WHERE id = (r->>'kampagne_id')::integer;
    END IF;
    RETURN r;
  END IF;

  BEGIN
    -- ---------- Kampagne: Planung, Briefing, Links, Abbrechen ----------
    IF p_aktion IN ('kp_planung', 'kp_briefing', 'kp_link_neu', 'kp_abbrechen', 'kp_fortsetzen', 'kp_regeln_standard') THEN
      recht := talents_planung_recht(u, k.id);
      IF k.id IS NULL OR recht IS NULL THEN
        fehler := 'Unbekannte Kampagne. Bitte die Seite neu laden.';
      ELSIF NOT talents_planung_planen(u, k.id) THEN
        fehler := 'Das dürfen der Manager oder die Managerin der Kampagne und alle mit dem Recht „Talents und Kampagnen verwalten“ für alle Talents.';
      ELSIF p_aktion = 'kp_planung' THEN
        -- Zuständigkeit ändert nur, wer alle Talents sieht; das Budget nur, wer Budgets sehen darf
        x := CASE WHEN d ? 'zustaendig' AND verw THEN nullif(btrim(coalesce(d->>'zustaendig', '')), '') ELSE k.zustaendig END;
        betrag := CASE WHEN d ? 'budget' AND talents_planung_geld(u, k.id, NULL) THEN talents_planung_betrag_lesen(d->>'budget') ELSE k.budget_cent END;
        zahl1 := CASE WHEN d ? 'ziel_reichweite' THEN talents_planung_zahl_lesen(d->>'ziel_reichweite') ELSE k.ziel_reichweite END;
        zahl2 := CASE WHEN d ? 'ziel_link_klicks' THEN talents_planung_zahl_lesen(d->>'ziel_link_klicks') ELSE k.ziel_link_klicks END;
        zahl3 := CASE WHEN d ? 'link_klicks' THEN talents_planung_zahl_lesen(d->>'link_klicks') ELSE k.link_klicks END;
        proz := CASE WHEN d ? 'ziel_interaktionsrate' THEN talents_planung_prozent_lesen(d->>'ziel_interaktionsrate') ELSE k.ziel_interaktionsrate END;
        IF x IS DISTINCT FROM k.zustaendig AND x IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = x AND p.aktiv AND talents_zugriff(p.matrix_user_id) IS NOT NULL) THEN
          fehler := 'Diesen Manager oder diese Managerin gibt es nicht, oder ihm oder ihr fehlt das Recht für Talents.';
        ELSIF betrag = -1 THEN
          fehler := 'Bitte das Budget als Betrag angeben, z. B. 18.000 oder 1.500,50.';
        ELSIF zahl1 = -1 OR zahl2 = -1 OR zahl3 = -1 THEN
          fehler := 'Bitte Reichweite und Link-Klicks als ganze Zahl angeben, z. B. 1.000.000.';
        ELSIF proz = -1 THEN
          fehler := 'Bitte die Interaktionsrate in Prozent angeben, z. B. 4,5.';
        ELSE
          UPDATE talent_kampagnen SET zustaendig = x, budget_cent = betrag, ziel_reichweite = zahl1, ziel_link_klicks = zahl2, link_klicks = zahl3, ziel_interaktionsrate = proz,
            erinnerungen_an = CASE WHEN d ? 'erinnerungen_sichtbar' THEN coalesce(d->>'erinnerungen_an', '') = '1' ELSE erinnerungen_an END,
            geaendert_am = now(), geaendert_von = u
          WHERE id = k.id;
          m := 'Planung gespeichert.';
        END IF;
      ELSIF p_aktion = 'kp_briefing' THEN
        IF length(coalesce(d->>'briefing_ziel', '')) > 2000 OR length(coalesce(d->>'kernbotschaft', '')) > 2000 OR length(coalesce(d->>'dos', '')) > 4000
           OR length(coalesce(d->>'donts', '')) > 4000 OR length(coalesce(d->>'werbekennzeichnung', '')) > 200 THEN
          fehler := 'Ein Text ist zu lang (Ziel und Kernbotschaft höchstens 2.000, Dos und Don''ts höchstens 4.000, Kennzeichnung höchstens 200 Zeichen).';
        ELSE
          UPDATE talent_kampagnen SET
            briefing_ziel = CASE WHEN d ? 'briefing_ziel' THEN nullif(btrim(d->>'briefing_ziel'), '') ELSE briefing_ziel END,
            kernbotschaft = CASE WHEN d ? 'kernbotschaft' THEN nullif(btrim(d->>'kernbotschaft'), '') ELSE kernbotschaft END,
            dos = CASE WHEN d ? 'dos' THEN nullif(btrim(d->>'dos'), '') ELSE dos END,
            donts = CASE WHEN d ? 'donts' THEN nullif(btrim(d->>'donts'), '') ELSE donts END,
            werbekennzeichnung = CASE WHEN d ? 'werbekennzeichnung' THEN nullif(btrim(d->>'werbekennzeichnung'), '') ELSE werbekennzeichnung END,
            geaendert_am = now(), geaendert_von = u
          WHERE id = k.id;
          m := 'Briefing gespeichert.';
        END IF;
      ELSIF p_aktion = 'kp_link_neu' THEN
        lk := talents_planung_link(d->>'link');
        IF nullif(btrim(coalesce(d->>'titel', '')), '') IS NULL OR length(btrim(d->>'titel')) > 120 THEN
          fehler := 'Bitte einen Titel mit höchstens 120 Zeichen angeben.';
        ELSIF lk IS NULL THEN
          fehler := 'Bitte einen vollständigen Link angeben, der mit https:// beginnt.';
        ELSIF (SELECT count(*) FROM talent_kampagne_links l WHERE l.kampagne_id = k.id) >= 30 THEN
          fehler := 'Eine Kampagne hat höchstens 30 Links.';
        ELSE
          INSERT INTO talent_kampagne_links (kampagne_id, titel, link, dienst, erstellt_von) VALUES (k.id, btrim(d->>'titel'), lk, talents_planung_dienst(lk), u);
          m := 'Link gespeichert.';
        END IF;
      ELSIF p_aktion = 'kp_abbrechen' THEN
        UPDATE talent_kampagnen SET abgebrochen_am = coalesce(abgebrochen_am, now()), geaendert_am = now(), geaendert_von = u WHERE id = k.id;
        m := 'Kampagne abgebrochen. Erinnerungen sind angehalten.';
      ELSIF p_aktion = 'kp_fortsetzen' THEN
        UPDATE talent_kampagnen SET abgebrochen_am = NULL, geaendert_am = now(), geaendert_von = u WHERE id = k.id;
        m := 'Kampagne läuft wieder.';
      ELSIF p_aktion = 'kp_regeln_standard' THEN
        -- Migration 131: jede eigene Regel einzeln in den Papierkorb
        n := 0;
        FOR t IN SELECT g.id FROM talent_erinnerungsregeln g WHERE g.kampagne_id = k.id ORDER BY g.id LOOP
          PERFORM talents_kampagnen_pk_legen('regel', t, u);
          n := n + 1;
        END LOOP;
        m := 'Für diese Kampagne gelten wieder die Standard-Erinnerungen.'
          || CASE WHEN n = 1 THEN ' Die eigene Regel liegt im Papierkorb.' WHEN n > 1 THEN ' Die ' || n || ' eigenen Regeln liegen im Papierkorb.' ELSE '' END;
      END IF;

    ELSIF p_aktion = 'kp_link_loeschen' THEN
      x := btrim(coalesce(d->>'id', ''));
      SELECT ka.* INTO k FROM talent_kampagne_links l JOIN talent_kampagnen ka ON ka.id = l.kampagne_id WHERE x ~ '^[0-9]{1,15}$' AND l.id = x::bigint;
      IF k.id IS NULL OR NOT talents_planung_planen(u, k.id) THEN
        fehler := 'Diesen Link gibt es nicht oder du darfst ihn nicht löschen.';
      ELSE
        PERFORM talents_kampagnen_pk_legen('link', x::bigint, u);  -- Migration 131: in den Papierkorb
        m := 'Link liegt jetzt im Papierkorb.';
      END IF;

    -- ---------- Deliverables ----------
    ELSIF p_aktion = 'kp_deliverable_neu' THEN
      recht := talents_planung_recht(u, k.id);
      ids := ARRAY(SELECT DISTINCT y::integer FROM unnest(talents_liste(coalesce(d->'talents', d->'talent_id'))) y WHERE y ~ '^[0-9]{1,9}$');
      dt1 := talents_datum_lesen(d->>'deadline');
      dt2 := talents_datum_lesen(d->>'veroeffentlichen_am');
      -- Honorar nur für Talents, deren Honorare die Person sehen darf (talents_planung_geld), sonst ohne Honorar
      geld := k.id IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(ids) y WHERE talents_planung_geld(u, k.id, y));
      betrag := CASE WHEN geld THEN talents_planung_betrag_lesen(d->>'honorar') END;
      IF k.id IS NULL OR recht IS NULL THEN
        fehler := 'Unbekannte Kampagne. Bitte die Seite neu laden.';
      ELSIF k.abgebrochen_am IS NOT NULL THEN
        fehler := 'Die Kampagne ist abgebrochen.';
      ELSIF cardinality(ids) = 0 THEN
        fehler := 'Bitte mindestens ein Talent auswählen.';
      ELSIF cardinality(ids) > 50 OR EXISTS (SELECT 1 FROM unnest(ids) y WHERE NOT talents_planung_talent_verwaltbar(u, k.id, y)) THEN
        fehler := 'In der Auswahl ist ein Talent, das nicht zur Kampagne gehört oder für dich nicht freigeschaltet ist.';
      ELSIF NOT (coalesce(d->>'plattform', '') = ANY (PLATT)) OR NOT (coalesce(d->>'format', '') = ANY (FORM)) THEN
        fehler := 'Bitte Plattform und Format auswählen.';
      ELSIF coalesce(nullif(btrim(d->>'anzahl'), ''), '1') !~ '^[0-9]{1,3}$' OR coalesce(nullif(btrim(d->>'anzahl'), ''), '1')::integer NOT BETWEEN 1 AND 100 THEN
        fehler := 'Bitte als Anzahl eine Zahl von 1 bis 100 angeben.';
      ELSIF length(btrim(coalesce(d->>'titel', ''))) > 120 OR length(coalesce(d->>'notiz', '')) > 2000 THEN
        fehler := 'Titel höchstens 120, Notiz höchstens 2.000 Zeichen.';
      ELSIF dt1 IS NULL THEN
        fehler := 'Bitte eine Deadline als Datum angeben.';
      ELSIF nullif(btrim(coalesce(d->>'veroeffentlichen_am', '')), '') IS NOT NULL AND dt2 IS NULL THEN
        fehler := 'Bitte die Veröffentlichung als Datum angeben.';
      ELSIF dt2 < dt1 THEN
        fehler := 'Die Veröffentlichung liegt vor der Deadline.';
      ELSIF dt1 < k.von - 366 OR dt1 > k.bis + 366 THEN
        fehler := 'Die Deadline liegt weit außerhalb der Kampagne.';
      ELSIF betrag = -1 THEN
        fehler := 'Bitte das Honorar als Betrag angeben, z. B. 2.400 oder 1.500,50.';
      ELSE
        n := 0;
        FOREACH t IN ARRAY ids LOOP
          INSERT INTO talent_deliverables (kampagne_id, talent_id, plattform, format, anzahl, titel, deadline, veroeffentlichen_am, honorar_cent, notiz, sichtbar_fuer_talent, erstellt_von, geaendert_von)
          VALUES (k.id, t, d->>'plattform', d->>'format', coalesce(nullif(btrim(d->>'anzahl'), ''), '1')::integer, nullif(btrim(coalesce(d->>'titel', '')), ''), dt1, dt2,
            CASE WHEN talents_planung_geld(u, k.id, t) THEN betrag END,
            nullif(btrim(coalesce(d->>'notiz', '')), ''), CASE WHEN d ? 'sichtbar_sichtbar' THEN coalesce(d->>'sichtbar_fuer_talent', '') = '1' ELSE true END, u, u)
          RETURNING id INTO neu_id;
          n := n + 1;
          IF (CASE WHEN d ? 'sichtbar_sichtbar' THEN coalesce(d->>'sichtbar_fuer_talent', '') = '1' ELSE true END) THEN
            PERFORM talents_benachrichtigen_talent(t, 'kampagne_aufgabe', 'Neues Deliverable: ' || talents_planung_deliverable_name(d->>'format', coalesce(nullif(btrim(d->>'anzahl'), ''), '1')::integer, d->>'titel'),
              k.marke || ' – ' || k.name || ', Deadline ' || to_char(dt1, 'DD.MM.YYYY') || '.', 'deliverable:' || neu_id);
          END IF;
        END LOOP;
        m := CASE WHEN n = 1 THEN 'Deliverable angelegt.' ELSE n || ' Deliverables angelegt.' END;
      END IF;

    ELSIF p_aktion IN ('kp_deliverable_aendern', 'kp_deliverable_status', 'kp_deliverable_loeschen', 'kp_erinnern', 'kp_version_neu') THEN
      x := btrim(coalesce(d->>'id', d->>'deliverable_id', ''));
      IF x ~ '^[0-9]{1,15}$' THEN SELECT * INTO dl FROM talent_deliverables WHERE id = x::bigint FOR UPDATE; END IF;
      IF dl.id IS NOT NULL THEN SELECT * INTO k FROM talent_kampagnen WHERE id = dl.kampagne_id; END IF;
      geld := dl.id IS NOT NULL AND talents_planung_geld(u, dl.kampagne_id, dl.talent_id);
      IF dl.id IS NULL OR NOT talents_planung_talent_verwaltbar(u, dl.kampagne_id, dl.talent_id) THEN
        fehler := 'Dieses Deliverable gibt es nicht oder es ist für dich nicht freigeschaltet. Bitte die Seite neu laden.';
      ELSE
        name_d := talents_planung_deliverable_name(dl.format, dl.anzahl, dl.titel);
        tname := coalesce(talent_listenname(dl.talent_id), 'Talent');
        IF p_aktion = 'kp_deliverable_aendern' THEN
          dt1 := CASE WHEN d ? 'deadline' THEN talents_datum_lesen(d->>'deadline') ELSE dl.deadline END;
          dt2 := CASE WHEN d ? 'veroeffentlichen_am' THEN talents_datum_lesen(d->>'veroeffentlichen_am') ELSE dl.veroeffentlichen_am END;
          betrag := CASE WHEN geld AND d ? 'honorar' THEN talents_planung_betrag_lesen(d->>'honorar') ELSE dl.honorar_cent END;
          lk := CASE WHEN d ? 'link' THEN talents_planung_link(d->>'link') ELSE dl.link END;
          IF d ? 'plattform' AND NOT (coalesce(d->>'plattform', '') = ANY (PLATT)) OR d ? 'format' AND NOT (coalesce(d->>'format', '') = ANY (FORM)) THEN
            fehler := 'Bitte Plattform und Format auswählen.';
          ELSIF d ? 'anzahl' AND (coalesce(btrim(d->>'anzahl'), '') !~ '^[0-9]{1,3}$' OR btrim(d->>'anzahl')::integer NOT BETWEEN 1 AND 100) THEN
            fehler := 'Bitte als Anzahl eine Zahl von 1 bis 100 angeben.';
          ELSIF length(btrim(coalesce(d->>'titel', ''))) > 120 OR length(coalesce(d->>'notiz', '')) > 2000 THEN
            fehler := 'Titel höchstens 120, Notiz höchstens 2.000 Zeichen.';
          ELSIF dt1 IS NULL THEN
            fehler := 'Bitte eine Deadline als Datum angeben.';
          ELSIF d ? 'veroeffentlichen_am' AND nullif(btrim(coalesce(d->>'veroeffentlichen_am', '')), '') IS NOT NULL AND dt2 IS NULL THEN
            fehler := 'Bitte die Veröffentlichung als Datum angeben.';
          ELSIF dt2 < dt1 THEN
            fehler := 'Die Veröffentlichung liegt vor der Deadline.';
          ELSIF dt1 < k.von - 366 OR dt1 > k.bis + 366 THEN
            fehler := 'Die Deadline liegt weit außerhalb der Kampagne.';
          ELSIF betrag = -1 THEN
            fehler := 'Bitte das Honorar als Betrag angeben, z. B. 2.400 oder 1.500,50.';
          ELSIF d ? 'link' AND nullif(btrim(coalesce(d->>'link', '')), '') IS NOT NULL AND lk IS NULL THEN
            fehler := 'Bitte einen vollständigen Link angeben, der mit https:// beginnt.';
          ELSE
            UPDATE talent_deliverables SET
              plattform = CASE WHEN d ? 'plattform' THEN d->>'plattform' ELSE plattform END,
              format = CASE WHEN d ? 'format' THEN d->>'format' ELSE format END,
              anzahl = CASE WHEN d ? 'anzahl' THEN btrim(d->>'anzahl')::integer ELSE anzahl END,
              titel = CASE WHEN d ? 'titel' THEN nullif(btrim(d->>'titel'), '') ELSE titel END,
              notiz = CASE WHEN d ? 'notiz' THEN nullif(btrim(d->>'notiz'), '') ELSE notiz END,
              deadline = dt1, veroeffentlichen_am = dt2, honorar_cent = betrag, link = lk,
              sichtbar_fuer_talent = CASE WHEN d ? 'sichtbar_sichtbar' THEN coalesce(d->>'sichtbar_fuer_talent', '') = '1' ELSE sichtbar_fuer_talent END,
              geaendert_am = now(), geaendert_von = u
            WHERE id = dl.id;
            m := 'Deliverable gespeichert.';
          END IF;
        ELSIF p_aktion = 'kp_deliverable_status' THEN
          lk := talents_planung_link(d->>'link');
          IF NOT (coalesce(d->>'status', '') = ANY (STATI)) THEN
            fehler := 'Diesen Status gibt es nicht.';
          ELSIF d->>'status' = 'abgerechnet' AND NOT geld THEN
            fehler := 'Als abgerechnet markiert, wer Honorare sehen darf (Recht „Honorare und Budgets sehen“).';
          ELSIF nullif(btrim(coalesce(d->>'link', '')), '') IS NOT NULL AND lk IS NULL THEN
            fehler := 'Bitte einen vollständigen Link angeben, der mit https:// beginnt.';
          ELSE
            UPDATE talent_deliverables SET status = d->>'status', link = coalesce(lk, link), geaendert_am = now(), geaendert_von = u WHERE id = dl.id;
            m := name_d || ' von ' || tname || ': ' || talents_planung_status_text(d->>'status') || '.';
          END IF;
        ELSIF p_aktion = 'kp_deliverable_loeschen' THEN
          IF coalesce(d->>'bestaetigt', '') <> 'ja' THEN
            fehler := 'Bitte das Löschen bestätigen.';
          ELSE
            PERFORM talents_kampagnen_pk_legen('deliverable', dl.id, u);  -- Migration 131: in den Papierkorb, mit Entwürfen und Aufgaben
            m := name_d || ' von ' || tname || ' liegt jetzt im Papierkorb, mit Entwürfen und Aufgaben. Im Papierkorb kannst du es wiederherstellen oder endgültig löschen.';
          END IF;
        ELSIF p_aktion = 'kp_erinnern' THEN
          IF NOT dl.sichtbar_fuer_talent THEN
            fehler := 'Dieses Deliverable ist für das Talent nicht sichtbar.';
          ELSE
            INSERT INTO talent_aufgaben (talent_id, kampagne_id, deliverable_id, art, titel, text, faellig_am, kanaele, quelle, benachrichtigt_am, erstellt_von, geaendert_von)
            VALUES (dl.talent_id, dl.kampagne_id, dl.id, 'erinnerung', left('Erinnerung: ' || name_d, 160),
              k.marke || ' – ' || k.name || ', Deadline ' || to_char(dl.deadline, 'DD.MM.YYYY') || '.', now(), ARRAY['bereich'], 'hand', now(), u, u)
            RETURNING id INTO neu_id;
            PERFORM talents_benachrichtigen_talent(dl.talent_id, 'kampagne_erinnerung', 'Erinnerung: ' || name_d, k.marke || ' – ' || k.name || ', Deadline ' || to_char(dl.deadline, 'DD.MM.YYYY') || '.',
              'erinnerung:' || neu_id);
            m := 'Erinnerung für ' || tname || ' angelegt.';
          END IF;
        ELSIF p_aktion = 'kp_version_neu' THEN
          lk := talents_planung_link(d->>'link');
          IF lk IS NULL THEN
            fehler := 'Bitte einen vollständigen Link zum Entwurf angeben, der mit https:// beginnt.';
          ELSIF length(coalesce(d->>'kommentar', '')) > 2000 THEN
            fehler := 'Der Kommentar hat höchstens 2.000 Zeichen.';
          ELSIF k.abgebrochen_am IS NOT NULL THEN
            fehler := 'Die Kampagne ist abgebrochen.';
          ELSE
            SELECT coalesce(max(x2.version), 0) + 1 INTO vs FROM talent_deliverable_versionen x2 WHERE x2.deliverable_id = dl.id;
            UPDATE talent_deliverable_versionen SET pruefung = 'ersetzt' WHERE deliverable_id = dl.id AND pruefung IN ('offen', 'intern_ok', 'bei_marke');
            INSERT INTO talent_deliverable_versionen (deliverable_id, version, quelle, link, dienst, kommentar, eingereicht_von)
            VALUES (dl.id, vs, 'team', lk, talents_planung_dienst(lk), nullif(btrim(coalesce(d->>'kommentar', '')), ''), u);
            UPDATE talent_deliverables SET status = 'pruefung', geaendert_am = now(), geaendert_von = u WHERE id = dl.id;
            UPDATE talent_aufgaben SET status = 'erledigt', erledigt_am = now(), erledigt_von = u, geaendert_am = now(), geaendert_von = u
            WHERE deliverable_id = dl.id AND art = 'review' AND status = 'offen';
            m := 'Entwurf eingetragen (Version ' || vs || ').';
          END IF;
        END IF;
      END IF;

    -- ---------- Freigaben ----------
    ELSIF p_aktion = 'kp_version_pruefen' THEN
      x := btrim(coalesce(d->>'id', ''));
      IF x ~ '^[0-9]{1,15}$' THEN SELECT * INTO v FROM talent_deliverable_versionen WHERE id = x::bigint FOR UPDATE; END IF;
      IF v.id IS NOT NULL THEN SELECT * INTO dl FROM talent_deliverables WHERE id = v.deliverable_id FOR UPDATE; END IF;
      IF dl.id IS NOT NULL THEN SELECT * INTO k FROM talent_kampagnen WHERE id = dl.kampagne_id; END IF;
      ergebnis := coalesce(d->>'ergebnis', '');
      kom := nullif(btrim(coalesce(d->>'kommentar', '')), '');
      IF v.id IS NULL OR NOT talents_planung_talent_verwaltbar(u, dl.kampagne_id, dl.talent_id) THEN
        fehler := 'Diesen Entwurf gibt es nicht oder er ist für dich nicht freigeschaltet. Bitte die Seite neu laden.';
      ELSIF ergebnis NOT IN ('intern_ok', 'ueberarbeiten', 'an_marke', 'marke_aenderung', 'freigeben') THEN
        fehler := 'Bitte ein Ergebnis wählen.';
      ELSIF NOT ((v.pruefung = 'offen' AND ergebnis IN ('intern_ok', 'ueberarbeiten', 'an_marke', 'freigeben'))
              OR (v.pruefung = 'intern_ok' AND ergebnis IN ('ueberarbeiten', 'an_marke', 'freigeben'))
              OR (v.pruefung = 'bei_marke' AND ergebnis IN ('marke_aenderung', 'freigeben'))) THEN
        fehler := 'Dieser Schritt passt nicht zum Stand des Entwurfs (' || talents_planung_pruefung_text(v.pruefung) || ').';
      ELSIF ergebnis IN ('ueberarbeiten', 'marke_aenderung') AND kom IS NULL THEN
        fehler := 'Bitte kurz schreiben, was überarbeitet werden soll.';
      ELSIF length(coalesce(kom, '')) > 2000 THEN
        fehler := 'Der Kommentar hat höchstens 2.000 Zeichen.';
      ELSE
        name_d := talents_planung_deliverable_name(dl.format, dl.anzahl, dl.titel);
        tname := coalesce(talent_listenname(dl.talent_id), 'Talent');
        IF ergebnis = 'intern_ok' THEN
          UPDATE talent_deliverable_versionen SET pruefung = 'intern_ok', pruef_kommentar = coalesce(kom, pruef_kommentar), geprueft_von = u, geprueft_am = now() WHERE id = v.id;
          m := 'Version ' || v.version || ' intern geprüft.';
        ELSIF ergebnis = 'an_marke' THEN
          UPDATE talent_deliverable_versionen SET pruefung = 'bei_marke', marke_am = now(), pruef_kommentar = coalesce(kom, pruef_kommentar),
            geprueft_von = coalesce(geprueft_von, u), geprueft_am = coalesce(geprueft_am, now()) WHERE id = v.id;
          UPDATE talent_deliverables SET status = 'bei_marke', geaendert_am = now(), geaendert_von = u WHERE id = dl.id;
          m := 'Version ' || v.version || ' liegt jetzt bei der Marke.';
        ELSIF ergebnis IN ('ueberarbeiten', 'marke_aenderung') THEN
          IF ergebnis = 'ueberarbeiten' THEN
            UPDATE talent_deliverable_versionen SET pruefung = 'ueberarbeiten', pruef_kommentar = kom, geprueft_von = u, geprueft_am = now() WHERE id = v.id;
          ELSE
            UPDATE talent_deliverable_versionen SET pruefung = 'marke_aenderung', marke_kommentar = kom, geprueft_von = u, geprueft_am = now() WHERE id = v.id;
          END IF;
          UPDATE talent_deliverables SET status = 'ueberarbeiten', geaendert_am = now(), geaendert_von = u WHERE id = dl.id;
          INSERT INTO talent_aufgaben (talent_id, kampagne_id, deliverable_id, version_id, art, titel, text, faellig_am, kanaele, quelle, benachrichtigt_am, erstellt_von, geaendert_von)
          VALUES (dl.talent_id, dl.kampagne_id, dl.id, v.id, 'review', left('Überarbeiten: ' || name_d, 160),
            CASE WHEN ergebnis = 'marke_aenderung' THEN 'Änderung der Marke: ' ELSE '' END || kom,
            CASE WHEN dl.deadline >= talents_heute() THEN (dl.deadline + time '18:00') AT TIME ZONE 'Europe/Berlin' END,
            CASE WHEN dl.sichtbar_fuer_talent THEN ARRAY['bereich'] ELSE '{}'::text[] END, 'review', now(), u, u)
          RETURNING id INTO neu_id;
          IF dl.sichtbar_fuer_talent THEN
            PERFORM talents_benachrichtigen_talent(dl.talent_id, 'kampagne_entwurf', 'Überarbeiten: ' || name_d, kom, 'review:' || v.id);
          END IF;
          m := 'Review an ' || tname || ' angelegt: Version ' || v.version || ' überarbeiten.';
        ELSE
          UPDATE talent_deliverable_versionen SET pruefung = 'freigegeben',
            marke_kommentar = CASE WHEN v.pruefung = 'bei_marke' THEN coalesce(kom, marke_kommentar) ELSE marke_kommentar END,
            pruef_kommentar = CASE WHEN v.pruefung <> 'bei_marke' THEN coalesce(kom, pruef_kommentar) ELSE pruef_kommentar END,
            geprueft_von = u, geprueft_am = now() WHERE id = v.id;
          UPDATE talent_deliverables SET status = 'freigegeben', geaendert_am = now(), geaendert_von = u WHERE id = dl.id;
          UPDATE talent_aufgaben SET status = 'erledigt', erledigt_am = now(), erledigt_von = u, geaendert_am = now(), geaendert_von = u
          WHERE deliverable_id = dl.id AND art = 'review' AND status = 'offen';
          IF dl.sichtbar_fuer_talent THEN
            PERFORM talents_benachrichtigen_talent(dl.talent_id, 'kampagne_entwurf', 'Freigegeben: ' || name_d, k.marke || ' – ' || k.name || '.', 'freigabe:' || v.id);
          END IF;
          m := name_d || ' von ' || tname || ' ist freigegeben.';
        END IF;
      END IF;

    -- ---------- Erinnerungsregeln (Kampagne oder Standard) ----------
    ELSIF p_aktion IN ('kp_regel_neu', 'kp_regel_aendern', 'kp_regel_loeschen') THEN
      IF p_aktion <> 'kp_regel_neu' THEN
        x := btrim(coalesce(d->>'id', ''));
        IF x ~ '^[0-9]{1,9}$' THEN SELECT * INTO rg FROM talent_erinnerungsregeln WHERE id = x::integer AND geloescht_am IS NULL FOR UPDATE; END IF;
        IF rg.id IS NOT NULL AND rg.kampagne_id IS NOT NULL THEN SELECT * INTO k FROM talent_kampagnen WHERE id = rg.kampagne_id; END IF;
      END IF;
      IF p_aktion <> 'kp_regel_neu' AND rg.id IS NULL THEN
        fehler := 'Diese Regel gibt es nicht. Bitte die Seite neu laden.';
      ELSIF (p_aktion = 'kp_regel_neu' AND k.id IS NULL OR p_aktion <> 'kp_regel_neu' AND rg.kampagne_id IS NULL) AND NOT verw THEN
        fehler := 'Standard-Erinnerungen ändert, wer das Recht „Talents und Kampagnen verwalten“ für alle Talents hat.';
      ELSIF k.id IS NOT NULL AND NOT talents_planung_planen(u, k.id) THEN
        fehler := 'Das dürfen der Manager oder die Managerin der Kampagne und alle mit dem Recht „Talents und Kampagnen verwalten“ für alle Talents.';
      ELSIF p_aktion = 'kp_regel_loeschen' THEN
        IF rg.kampagne_id IS NULL THEN
          -- Migration 129: Standard-Erinnerung in den Papierkorb (eigene Regeln einer Kampagne: Migration 131, talent_kampagnen_papierkorb)
          UPDATE talent_erinnerungsregeln SET geloescht_am = now(), geloescht_von = u, geaendert_am = now(), geaendert_von = u WHERE id = rg.id;
          m := 'Standard-Erinnerung liegt jetzt im Papierkorb. Sie erinnert nicht mehr. Im Papierkorb kannst du sie wiederherstellen oder endgültig löschen.';
        ELSE
          PERFORM talents_kampagnen_pk_legen('regel', rg.id, u);  -- Migration 131: in den Papierkorb
          m := 'Regel liegt jetzt im Papierkorb.'
            || CASE WHEN NOT EXISTS (SELECT 1 FROM talent_erinnerungsregeln g WHERE g.kampagne_id = rg.kampagne_id) THEN ' Für diese Kampagne gelten wieder die Standard-Erinnerungen.' ELSE '' END;
        END IF;
      ELSE
        bz := CASE WHEN d ? 'bezug' OR rg.id IS NULL THEN coalesce(d->>'bezug', '') ELSE rg.bezug END;
        em := CASE WHEN d ? 'empfaenger' OR rg.id IS NULL THEN coalesce(d->>'empfaenger', '') ELSE rg.empfaenger END;
        x := coalesce(nullif(btrim(d->>'uhrzeit'), ''), to_char(coalesce(rg.uhrzeit, '09:00'), 'HH24:MI'));
        IF d ? 'wann' OR rg.id IS NULL THEN
          ve := CASE WHEN d->>'wann' = 'am_tag' THEN 0
                     WHEN coalesce(btrim(d->>'tage'), '') ~ '^[0-9]{1,2}$' AND btrim(d->>'tage')::integer BETWEEN 1 AND 30 THEN
                       CASE d->>'wann' WHEN 'vorher' THEN -btrim(d->>'tage')::integer WHEN 'danach' THEN btrim(d->>'tage')::integer END END;
        ELSE
          ve := rg.versatz_tage;
        END IF;
        kan := CASE WHEN em = 'zustaendig' THEN ARRAY['glocke']
                    WHEN d ? 'kanaele' OR rg.id IS NULL THEN ARRAY(SELECT DISTINCT y FROM unnest(talents_liste(d->'kanaele')) y WHERE y IN ('bereich', 'kalender', 'mail') ORDER BY 1)
                    ELSE rg.kanaele END;
        IF bz NOT IN ('deadline', 'veroeffentlichung') OR em NOT IN ('talent', 'zustaendig') THEN
          fehler := 'Bitte Bezug und Empfang auswählen.';
        ELSIF ve IS NULL THEN
          fehler := 'Bitte wählen, wann erinnert wird (1 bis 30 Tage vorher, am Tag oder danach).';
        ELSIF x !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
          fehler := 'Bitte eine Uhrzeit angeben, z. B. 09:00.';
        ELSIF cardinality(kan) = 0 THEN
          fehler := 'Bitte mindestens einen Weg zum Talent wählen.';
        ELSE
          uz := x::time;
          IF p_aktion = 'kp_regel_neu' AND k.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talent_erinnerungsregeln e WHERE e.kampagne_id = k.id) THEN
            -- Erste eigene Regel: die Standard-Regeln werden für diese Kampagne übernommen, damit nichts wegfällt
            INSERT INTO talent_erinnerungsregeln (kampagne_id, bezug, versatz_tage, uhrzeit, empfaenger, kanaele, aktiv, erstellt_von, geaendert_von)
            SELECT k.id, s.bezug, s.versatz_tage, s.uhrzeit, s.empfaenger, s.kanaele, s.aktiv, u, u FROM talent_erinnerungsregeln s WHERE s.kampagne_id IS NULL AND s.geloescht_am IS NULL;
          END IF;
          IF p_aktion = 'kp_regel_neu' THEN
            INSERT INTO talent_erinnerungsregeln (kampagne_id, bezug, versatz_tage, uhrzeit, empfaenger, kanaele, aktiv, erstellt_von, geaendert_von)
            VALUES (k.id, bz, ve, uz, em, kan, true, u, u);
            m := 'Regel angelegt: ' || talents_planung_regel_text(bz, ve) || CASE WHEN em = 'talent' THEN ' an das Talent.' ELSE ' an den Manager oder die Managerin.' END;
          ELSE
            UPDATE talent_erinnerungsregeln SET bezug = bz, versatz_tage = ve, uhrzeit = uz, empfaenger = em, kanaele = kan,
              aktiv = CASE WHEN d ? 'aktiv_sichtbar' THEN coalesce(d->>'aktiv', '') = '1' ELSE aktiv END, geaendert_am = now(), geaendert_von = u
            WHERE id = rg.id;
            m := 'Regel gespeichert.';
          END IF;
        END IF;
      END IF;

    -- ---------- Aufgaben, Reviews, Termine, Erinnerungen je Talent ----------
    ELSIF p_aktion IN ('kp_aufgabe_neu', 'kp_aufgabe_aendern') THEN
      IF p_aktion = 'kp_aufgabe_aendern' THEN
        x := btrim(coalesce(d->>'id', ''));
        IF x ~ '^[0-9]{1,15}$' THEN SELECT * INTO a FROM talent_aufgaben WHERE id = x::bigint FOR UPDATE; END IF;
        t := a.talent_id;
        IF NOT (d ? 'kampagne_id') AND a.kampagne_id IS NOT NULL THEN SELECT * INTO k FROM talent_kampagnen WHERE id = a.kampagne_id; END IF;
      ELSE
        t := CASE WHEN btrim(coalesce(d->>'talent_id', '')) ~ '^[0-9]{1,9}$' THEN btrim(d->>'talent_id')::integer END;
      END IF;
      x := btrim(coalesce(d->>'deliverable_id', ''));
      IF x ~ '^[0-9]{1,15}$' THEN
        SELECT * INTO dl FROM talent_deliverables WHERE id = x::bigint;
        IF dl.id IS NOT NULL AND k.id IS NULL THEN SELECT * INTO k FROM talent_kampagnen WHERE id = dl.kampagne_id; END IF;
      ELSIF p_aktion = 'kp_aufgabe_aendern' AND NOT (d ? 'deliverable_id') AND a.deliverable_id IS NOT NULL THEN
        SELECT * INTO dl FROM talent_deliverables WHERE id = a.deliverable_id;
      END IF;
      ar := CASE WHEN d ? 'art' OR a.id IS NULL THEN coalesce(d->>'art', '') ELSE a.art END;
      z1 := talents_planung_zeit_lesen(d->>'wann');
      z2 := talents_planung_zeit_lesen(d->>'ende');
      kan := CASE WHEN d ? 'kanaele' OR d ? 'kanaele_sichtbar' OR a.id IS NULL
                  THEN ARRAY(SELECT DISTINCT y FROM unnest(talents_liste(d->'kanaele')) y WHERE y IN ('bereich', 'kalender', 'mail') ORDER BY 1) ELSE a.kanaele END;
      IF p_aktion = 'kp_aufgabe_aendern' AND a.id IS NULL THEN
        fehler := 'Diesen Eintrag gibt es nicht. Bitte die Seite neu laden.';
      ELSIF t IS NULL OR NOT (CASE WHEN k.id IS NULL THEN coalesce(talent_verwaltbar(u, t), false) ELSE talents_planung_talent_verwaltbar(u, k.id, t) END) THEN
        fehler := 'Dieses Talent gibt es nicht oder es ist für dich nicht freigeschaltet.';
      ELSIF dl.id IS NOT NULL AND (dl.talent_id <> t OR (k.id IS NOT NULL AND dl.kampagne_id <> k.id)) THEN
        fehler := 'Das Deliverable gehört nicht zu diesem Talent bzw. dieser Kampagne.';
      ELSIF ar NOT IN ('aufgabe', 'review', 'termin', 'erinnerung') THEN
        fehler := 'Bitte die Art wählen.';
      ELSIF (d ? 'titel' OR a.id IS NULL) AND (nullif(btrim(coalesce(d->>'titel', '')), '') IS NULL OR length(btrim(d->>'titel')) > 160) THEN
        fehler := 'Bitte beschreiben, worum es geht (höchstens 160 Zeichen).';
      ELSIF length(coalesce(d->>'text', '')) > 4000 OR length(coalesce(d->>'ort', '')) > 200 THEN
        fehler := 'Text höchstens 4.000, Ort höchstens 200 Zeichen.';
      ELSIF nullif(btrim(coalesce(d->>'wann', '')), '') IS NOT NULL AND z1 IS NULL OR nullif(btrim(coalesce(d->>'ende', '')), '') IS NOT NULL AND z2 IS NULL THEN
        fehler := 'Bitte Datum und Uhrzeit angeben.';
      ELSIF ar IN ('termin', 'erinnerung') AND z1 IS NULL AND (a.id IS NULL OR d ? 'wann') THEN
        fehler := CASE WHEN ar = 'termin' THEN 'Ein Termin braucht Datum und Uhrzeit.' ELSE 'Eine Erinnerung braucht Datum und Uhrzeit.' END;
      ELSIF z2 IS NOT NULL AND z2 < coalesce(z1, a.beginn) THEN
        fehler := 'Das Ende liegt vor dem Beginn.';
      ELSIF k.id IS NOT NULL AND k.abgebrochen_am IS NOT NULL AND a.id IS NULL THEN
        fehler := 'Die Kampagne ist abgebrochen.';
      ELSIF p_aktion = 'kp_aufgabe_neu' THEN
        INSERT INTO talent_aufgaben (talent_id, kampagne_id, deliverable_id, art, titel, text, ort, beginn, ende, ganztags, faellig_am, kanaele, quelle, benachrichtigt_am, mail_status, erstellt_von, geaendert_von)
        VALUES (t, k.id, dl.id, ar, btrim(d->>'titel'), coalesce(btrim(d->>'text'), ''), nullif(btrim(coalesce(d->>'ort', '')), ''),
          CASE WHEN ar = 'termin' THEN z1 END, CASE WHEN ar = 'termin' THEN z2 END, coalesce(d->>'ganztags', '') = '1' AND ar = 'termin',
          CASE WHEN ar <> 'termin' THEN z1 END, kan, 'hand',
          CASE WHEN 'bereich' = ANY (kan) AND NOT (ar = 'erinnerung' AND z1 > now()) THEN now() END, CASE WHEN 'mail' = ANY (kan) THEN 'offen' END, u, u)
        RETURNING id INTO neu_id;
        IF 'bereich' = ANY (kan) AND NOT (ar = 'erinnerung' AND z1 > now()) THEN
          PERFORM talents_benachrichtigen_talent(t, CASE WHEN ar = 'erinnerung' THEN 'kampagne_erinnerung' ELSE 'kampagne_aufgabe' END,
            CASE ar WHEN 'termin' THEN 'Neuer Termin: ' WHEN 'review' THEN 'Review: ' WHEN 'erinnerung' THEN 'Erinnerung: ' ELSE 'Neue Aufgabe: ' END || btrim(d->>'titel'),
            CASE WHEN z1 IS NOT NULL THEN talents_planung_zeit_text(z1, coalesce(d->>'ganztags', '') = '1' AND ar = 'termin') ELSE '' END, 'aufgabe:' || neu_id);
        END IF;
        m := CASE ar WHEN 'termin' THEN 'Termin angelegt.' WHEN 'review' THEN 'Review angelegt.' WHEN 'erinnerung' THEN 'Erinnerung angelegt.' ELSE 'Aufgabe angelegt.' END;
      ELSE
        UPDATE talent_aufgaben SET art = ar, titel = CASE WHEN d ? 'titel' THEN btrim(d->>'titel') ELSE titel END,
          text = CASE WHEN d ? 'text' THEN coalesce(btrim(d->>'text'), '') ELSE text END,
          ort = CASE WHEN d ? 'ort' THEN nullif(btrim(coalesce(d->>'ort', '')), '') ELSE ort END,
          kampagne_id = k.id, deliverable_id = dl.id,
          beginn = CASE WHEN ar = 'termin' THEN coalesce(CASE WHEN d ? 'wann' THEN z1 END, beginn, faellig_am) END,
          ende = CASE WHEN ar = 'termin' THEN CASE WHEN d ? 'ende' THEN z2 ELSE ende END END,
          ganztags = CASE WHEN d ? 'ganztags_sichtbar' THEN coalesce(d->>'ganztags', '') = '1' AND ar = 'termin' ELSE ganztags AND ar = 'termin' END,
          faellig_am = CASE WHEN ar <> 'termin' THEN CASE WHEN d ? 'wann' THEN z1 ELSE coalesce(faellig_am, beginn) END END,
          kanaele = kan,
          benachrichtigt_am = CASE WHEN ar = 'erinnerung' AND d ? 'wann' AND z1 > now() THEN NULL ELSE benachrichtigt_am END,
          mail_status = CASE WHEN 'mail' = ANY (kan) THEN 'offen' END,
          ics_sequenz = ics_sequenz + 1, geaendert_am = now(), geaendert_von = u
        WHERE id = a.id;
        m := 'Gespeichert.';
      END IF;

    ELSIF p_aktion IN ('kp_aufgabe_erledigt', 'kp_aufgabe_offen', 'kp_aufgabe_absagen', 'kp_aufgabe_loeschen') THEN
      x := btrim(coalesce(d->>'id', ''));
      IF x ~ '^[0-9]{1,15}$' THEN SELECT * INTO a FROM talent_aufgaben WHERE id = x::bigint FOR UPDATE; END IF;
      IF a.id IS NULL OR NOT (CASE WHEN a.kampagne_id IS NULL THEN coalesce(talent_verwaltbar(u, a.talent_id), false) ELSE talents_planung_talent_verwaltbar(u, a.kampagne_id, a.talent_id) END) THEN
        fehler := 'Diesen Eintrag gibt es nicht oder er ist für dich nicht freigeschaltet. Bitte die Seite neu laden.';
      ELSIF p_aktion = 'kp_aufgabe_loeschen' THEN
        IF coalesce(d->>'bestaetigt', '') <> 'ja' THEN
          fehler := 'Bitte das Löschen bestätigen.';
        ELSE
          PERFORM talents_profil_pk_legen('aufgabe', a.id, u);  -- Migration 130: in den Papierkorb des Talent-Profils
          m := talents_planung_art_text(a.art) || ' liegt jetzt im Papierkorb. Im Papierkorb kannst du den Eintrag wiederherstellen.';
        END IF;
      ELSE
        UPDATE talent_aufgaben SET status = CASE p_aktion WHEN 'kp_aufgabe_erledigt' THEN 'erledigt' WHEN 'kp_aufgabe_offen' THEN 'offen' ELSE 'abgesagt' END,
          erledigt_am = CASE WHEN p_aktion = 'kp_aufgabe_erledigt' THEN now() END, erledigt_von = CASE WHEN p_aktion = 'kp_aufgabe_erledigt' THEN u END,
          ics_sequenz = ics_sequenz + 1, mail_status = CASE WHEN p_aktion = 'kp_aufgabe_absagen' AND 'mail' = ANY (kanaele) THEN 'offen' ELSE mail_status END,
          geaendert_am = now(), geaendert_von = u
        WHERE id = a.id;
        m := CASE p_aktion WHEN 'kp_aufgabe_erledigt' THEN 'Als erledigt markiert.' WHEN 'kp_aufgabe_offen' THEN 'Wieder offen.' ELSE 'Abgesagt.' END;
      END IF;

    -- ---------- Einstellungen › Kampagnen: Währung der Beträge (nur Admin) ----------
    ELSIF p_aktion = 'kp_waehrung' THEN
      IF NOT adm THEN
        fehler := 'Das dürfen nur Admins.';
      ELSIF coalesce(d->>'waehrung', '') NOT IN ('EUR', 'CHF', 'USD', 'GBP') THEN
        fehler := 'Diese Währung gibt es hier nicht.';
      ELSE
        PERFORM ally_einstellung_setzen('talents_waehrung', d->>'waehrung', u);
        m := 'Währung gespeichert: ' || (d->>'waehrung') || '.';
      END IF;

    ELSE
      fehler := 'Unbekannte Aktion.';
    END IF;
  EXCEPTION
    WHEN unique_violation THEN
      fehler := CASE WHEN p_aktion LIKE 'kp\_regel%' THEN 'Diese Regel gibt es schon.' ELSE 'Das gibt es schon.' END;
    -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung
    WHEN SQLSTATE 'AT001' OR SQLSTATE 'AT002' THEN
      fehler := SQLERRM;
    WHEN OTHERS THEN
      fehler := 'Das hat nicht geklappt. Bitte noch einmal versuchen.';
  END;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m, ''), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'fehler', fehler);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_waehrung()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Währung der Honorare und Budgets (Einstellung talents_waehrung, Standard EUR)
  SELECT CASE upper(btrim(ally_einstellung('talents_waehrung'))) WHEN 'CHF' THEN 'CHF' WHEN 'USD' THEN 'USD' WHEN 'GBP' THEN 'GBP' ELSE 'EUR' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_zahl_lesen(p text)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Ganze Zahl (Reichweite, Link-Klicks): leer = NULL, ungültig = -1. Punkt als Tausendertrenner erlaubt.
  SELECT CASE WHEN x = '' THEN NULL
              WHEN (x ~ '^[0-9]{1,3}([.][0-9]{3})+$' OR x ~ '^[0-9]{1,11}$') AND length(replace(x, '.', '')) <= 11 THEN replace(x, '.', '')::bigint
              ELSE -1 END
  FROM (SELECT regexp_replace(coalesce(p, ''), '[[:space:]]', '', 'g') AS x) y
$function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_zeit_lesen(p text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  x text := btrim(coalesce(p, ''));
BEGIN
  -- Zeitpunkt aus dem Formular (ISO mit Zeitzone von ALLY 20, ohne Zeitzone = Berliner Zeit, reines Datum = 00:00 Berliner Zeit). Ungültig = NULL.
  IF x ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RETURN (x::date)::timestamp AT TIME ZONE 'Europe/Berlin';
  ELSIF x ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}(:[0-9]{2})?$' THEN
    RETURN x::timestamp AT TIME ZONE 'Europe/Berlin';
  ELSIF x ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]{1,6})?)?(Z|[+-][0-9]{2}(:?[0-9]{2})?)$' THEN
    RETURN x::timestamptz;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_planung_zeit_text(p timestamp with time zone, p_ganztags boolean)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN p IS NULL THEN '' ELSE talents_planung_tag_text((p AT TIME ZONE 'Europe/Berlin')::date)
    || CASE WHEN coalesce(p_ganztags, false) THEN '' ELSE ', ' || to_char(p AT TIME ZONE 'Europe/Berlin', 'HH24:MI') END END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_abruf_liste(p_plattform text, p_anzahl integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
  -- Nächtlicher Lauf: fällige Kanäle (Stefan 19.10.2026, Migration 52). Die Logik steht in talents_plattform_abruf_liste_fuer (gemeinsam mit dem Sofortabruf).
  RETURN talents_plattform_abruf_liste_fuer(p_plattform, p_anzahl, NULL, false);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_abruf_liste_fuer(p_plattform text, p_anzahl integer, p_kanal_id integer, p_erstabruf boolean, p_alle_beitraege boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- Migration 194 (Stefan 01.11.2026, „Daten jetzt abrufen“): p_alle_beitraege = true nur beim Knopf im Talent-Profil (mit Kanal): alle verfolgten Beiträge,
-- auch die heute schon aktualisierten. Standard false = wie bisher (ALLY 16, nächtlicher Lauf, talents_*abruf_liste mit vier Argumenten).
-- Kern von talents_plattform_abruf_liste (Stefan 19.10.2026): p_kanal_id NULL = nächtlicher Lauf (unverändert);
-- p_kanal_id gesetzt = Sofortabruf genau dieses Kanals nach der Verbindung (ALLY 16), auch wenn er heute schon abgerufen wurde.
-- p_erstabruf: Zeitraum der Tageswerte die letzten 30 Tage (TikTok: keine Tageswerte), Zielgruppe (YouTube, Threads) gleich mit.
DECLARE
  pl text := lower(btrim(coalesce(p_plattform, '')));
  heute date := talents_heute();
  n integer := CASE WHEN p_anzahl IS NULL OR p_anzahl < 1 THEN NULL ELSE least(p_anzahl, 1000) END;
  w text;
  wd jsonb;
  app jsonb := '{}'::jsonb;
  sec text;
  gesamt integer;
  liste jsonb;
  -- Tage, die beim ersten Abruf nachgeholt werden, und Tage, die jedes Mal erneut geholt werden (späte Daten)
  nachhol integer := CASE pl WHEN 'tiktok' THEN 0 ELSE 28 END;
  nachlauf integer := CASE pl WHEN 'youtube' THEN 4 WHEN 'pinterest' THEN 3 WHEN 'facebook' THEN 2 ELSE 1 END;
BEGIN
  IF NOT pl = ANY (talents_weitere_plattformen()) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte Plattform. Erlaubt: facebook, threads, youtube, pinterest, tiktok.', 'kanaele', '[]'::jsonb);
  END IF;
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', true, 'plattform', pl, 'heute', to_char(heute, 'YYYY-MM-DD'), 'anzahl', 0, 'weitere', 0,
      'kanaele', '[]'::jsonb, 'hinweis', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  -- Migration 195 (Stefan 01.11.2026, Abrufzeiten): Zeitplan-Lauf (alle 15 Minuten) ohne fällige Kanäle oder während ein Lauf
  -- dieser Art noch nicht gemeldete Kanäle hat (talents_abrufzeit_laeuft): gleich leer zurück, kein zweiter Lauf parallel.
  IF p_kanal_id IS NULL AND (talents_abrufzeit_laeuft('taeglich', pl) OR NOT EXISTS (SELECT 1 FROM talents_plattform_faellig(pl))) THEN
    RETURN jsonb_build_object('ok', true, 'plattform', pl, 'heute', to_char(heute, 'YYYY-MM-DD'), 'app', '{}'::jsonb, 'anzahl', 0, 'weitere', 0, 'kanaele', '[]'::jsonb);
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    -- Migration 195 (Stefan 01.11.2026, Abrufzeiten): im Zeitplan-Lauf gelten die fälligen Kanäle als versucht.
    IF p_kanal_id IS NULL THEN PERFORM talents_abrufzeit_versuch('taeglich', ARRAY(SELECT x.kanal_id FROM talents_plattform_faellig(pl) x)); END IF;
    RETURN jsonb_build_object('ok', false, 'fehler', 'Verschlüsselung ist nicht eingerichtet.', 'kanaele', '[]'::jsonb);
  END IF;
  w := (talent_wege(pl))[1];
  wd := talent_weg_weitere(pl, w);
  IF pl IN ('facebook', 'threads') AND coalesce(wd->>'graph_version', '') !~ '^v[0-9]{1,3}[.][0-9]{1,2}$' THEN
    -- Migration 195 (Stefan 01.11.2026, Abrufzeiten): im Zeitplan-Lauf gelten die fälligen Kanäle als versucht.
    IF p_kanal_id IS NULL THEN PERFORM talents_abrufzeit_versuch('taeglich', ARRAY(SELECT x.kanal_id FROM talents_plattform_faellig(pl) x)); END IF;
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die API-Version ist ungültig (Einstellung ' || CASE pl WHEN 'facebook' THEN 'talents_graph_version' ELSE 'talents_threads_version' END || ').', 'kanaele', '[]'::jsonb);
  END IF;
  -- App-Angaben für die Erneuerung der Zugänge (Google, Pinterest, TikTok); Threads verlängert ohne Geheimcode
  IF pl IN ('youtube', 'pinterest', 'tiktok') THEN
    sec := CASE WHEN ally_geheim_vorhanden(wd->>'geheim') THEN ally_geheim(wd->>'geheim') END;
    app := jsonb_build_object('token_adresse', wd->>'token_adresse', 'client_param', wd->>'client_param', 'client_id', wd->>'app_id',
      'client_secret', CASE WHEN pl <> 'pinterest' THEN sec END,
      'basic', CASE WHEN pl = 'pinterest' AND sec IS NOT NULL THEN replace(encode(convert_to((wd->>'app_id') || ':' || sec, 'UTF8'), 'base64'), E'\n', '') END,
      'fehler', CASE WHEN sec IS NULL OR coalesce(wd->>'app_id', '') = '' THEN 'Die App-Zugangsdaten für ' || talents_plattform_name(pl) || ' fehlen (Einstellungen › Plattform-Apps).' END);
  ELSIF pl = 'threads' THEN
    app := jsonb_build_object('verlaengern_adresse', wd->>'verlaengern_adresse');
  END IF;
  IF p_kanal_id IS NULL THEN
    SELECT count(*)::integer INTO gesamt FROM talents_plattform_faellig(pl);
  ELSE
    SELECT count(*)::integer INTO gesamt FROM talents_plattform_bereit(pl, p_kanal_id);
  END IF;
  SELECT coalesce(jsonb_agg(z.o ORDER BY z.zuletzt NULLS FIRST, z.kanal_id), '[]'::jsonb) INTO liste
  FROM (
    SELECT f.kanal_id, f.zuletzt,
      jsonb_build_object('kanal_id', k.id, 'talent_id', k.talent_id, 'anzeigename', talent_anzeigename(k.talent_id),
        'plattform', k.plattform, 'extern_id', k.extern_id, 'extern_name', k.extern_name, 'seite_id', k.extern_seite_id, 'anmeldeweg', k.anmeldeweg,
        'api', wd->>'api', 'data_api', wd->>'data_api',
        'schluessel', s.s, 'schluessel_fehler', s.s IS NULL,
        -- erneuern: vor dem Abruf einen Zugriffsschlüssel holen (Google, Pinterest, TikTok: immer; Threads: Verlängerung fällig)
        'erneuern', CASE WHEN pl IN ('youtube', 'pinterest', 'tiktok') THEN true WHEN pl = 'threads' THEN talents_plattform_verlaengern_faellig(k.id) ELSE false END,
        'gueltig_bis', k.gueltig_bis, 'geprueft_am', k.geprueft_am, 'letzter_abruf', k.letzter_abruf, 'zuletzt', f.zuletzt,
        'tag', to_char(heute - 1, 'YYYY-MM-DD'),
        'von', to_char(vb.von, 'YYYY-MM-DD'), 'bis', to_char(heute - 1, 'YYYY-MM-DD'),
        'tage', CASE WHEN pl = 'tiktok' THEN '[]'::jsonb ELSE (SELECT coalesce(jsonb_agg(jsonb_build_object('tag', to_char(d::date, 'YYYY-MM-DD'),
                    'since', extract(epoch FROM (d::date::timestamp AT TIME ZONE 'Europe/Berlin'))::bigint,
                    'until', extract(epoch FROM ((d::date + 1)::timestamp AT TIME ZONE 'Europe/Berlin'))::bigint) ORDER BY d), '[]'::jsonb)
                  FROM generate_series(vb.von, heute - 1, interval '1 day') d) END,
        -- Migration 151 (Punkt 2j): nur Facebook – vollständige Beitragsliste holen, wenn Bildadressen in 48 Stunden ablaufen
        'vorschau_auffrischen', pl = 'facebook' AND talents_vorschau_auffrischen(k.id),
        'seit', sb.seit, 'seit_unix', extract(epoch FROM sb.seit)::bigint,
        'zielgruppe_faellig', pl IN ('youtube', 'threads') AND ((p_kanal_id IS NOT NULL AND coalesce(p_erstabruf, false))
                              OR k.abruf_woechentlich_am IS NULL OR talents_tag(k.abruf_woechentlich_am) <= heute - 7),
        'beitraege', coalesce((SELECT jsonb_agg(jsonb_build_object('beitrag_id', b.id, 'extern_id', b.extern_id, 'art', b.art, 'produkt_art', b.produkt_art,
              'erstellt', b.erstellt, 'bis', CASE WHEN d.dauer > 0 THEN to_char(greatest(talents_tag(coalesce(b.erstellt, b.erfasst_am)) + d.dauer, d.kbis), 'YYYY-MM-DD') END)
            ORDER BY b.erstellt DESC NULLS LAST, b.id)
          -- wie talents_abruf_liste (Migration 46): Beiträge einer Kampagne mindestens bis Kampagnenende
          FROM talent_beitraege b CROSS JOIN LATERAL (SELECT coalesce(b.verfolgung_tage, t.verfolgung_tage, talents_verfolgung_standard()) AS dauer, talents_kampagne_bis(b.id) AS kbis) d
          WHERE b.kanal_id = k.id AND NOT b.abgeschlossen
            AND (d.dauer = 0 OR talents_tag(coalesce(b.erstellt, b.erfasst_am)) + d.dauer >= heute OR d.kbis >= heute)
            AND ((p_kanal_id IS NOT NULL AND coalesce(p_alle_beitraege, false)) OR b.aktualisiert_am IS NULL OR talents_tag(b.aktualisiert_am) < heute)), '[]'::jsonb))
      || CASE WHEN p_kanal_id IS NOT NULL THEN jsonb_build_object('erstabruf', coalesce(p_erstabruf, false)) ELSE '{}'::jsonb END AS o
    FROM ((SELECT * FROM talents_plattform_faellig(pl) x WHERE p_kanal_id IS NULL ORDER BY 2 NULLS FIRST, 1 LIMIT n)
          UNION ALL
          SELECT * FROM talents_plattform_bereit(pl, p_kanal_id) y WHERE p_kanal_id IS NOT NULL) f
    JOIN talent_kanaele k ON k.id = f.kanal_id
    JOIN talents t ON t.id = k.talent_id
    CROSS JOIN LATERAL (SELECT talents_entschluesseln_still(CASE WHEN pl = 'facebook' THEN k.schluessel_zusatz ELSE k.schluessel END) AS s) s
    -- Erstabruf beim Sofortabruf: 30 Tage zurück (Stefan 19.10.2026)
    CROSS JOIN LATERAL (SELECT CASE WHEN p_kanal_id IS NOT NULL AND coalesce(p_erstabruf, false) THEN heute - 30
                          ELSE least(heute - 1, greatest(heute - greatest(nachhol, 1),
                          coalesce(talents_tag(k.abruf_taeglich_am) - nachlauf, heute - greatest(nachhol, 1)))) END AS von) vb
    CROSS JOIN LATERAL (SELECT max(b.erstellt) - interval '1 day' AS seit FROM talent_beitraege b WHERE b.kanal_id = k.id) sb
  ) z;
  -- Migration 195 (Stefan 01.11.2026, Abrufzeiten): im Zeitplan-Lauf die ausgegebenen Kanäle als Versuch vermerken (nicht beim Sofortabruf mit Kanal).
  IF p_kanal_id IS NULL THEN
    PERFORM talents_abrufzeit_versuch('taeglich', ARRAY(SELECT (y->>'kanal_id')::integer FROM jsonb_array_elements(liste) y));
  END IF;
  RETURN jsonb_build_object('ok', true, 'plattform', pl, 'heute', to_char(heute, 'YYYY-MM-DD'), 'app', app,
    'anzahl', jsonb_array_length(liste), 'weitere', greatest(gesamt - jsonb_array_length(liste), 0), 'kanaele', liste)
    || CASE WHEN p_kanal_id IS NOT NULL THEN jsonb_build_object('kanal_id', p_kanal_id, 'erstabruf', coalesce(p_erstabruf, false),
         'hinweis', CASE WHEN jsonb_array_length(liste) = 0 THEN 'Dieser Kanal ist gerade nicht abrufbar (nicht verbunden, Talent nicht aktiv, ohne Schlüssel, andere Plattform oder Pause nach einer Abrufgrenze).' END)
       ELSE '{}'::jsonb END;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_abruf_speichern(p_kanal_id integer, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  k talent_kanaele%ROWTYPE;
  nm text;
  name_neu boolean := false;
  zg boolean := false;
  r jsonb;
BEGIN
  SELECT * INTO k FROM talent_kanaele WHERE id = p_kanal_id;
  IF k.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Kanal.');
  END IF;
  IF NOT k.plattform = ANY (talents_weitere_plattformen()) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Dieser Kanal gehört nicht zu Facebook, Threads, YouTube, Pinterest oder TikTok.');
  END IF;
  IF d::text ~* '(refresh_token|access_token|client_secret|client_key|fb_exchange_token|th_exchange_token)'
     OR d::text ~ '(ya29[.][A-Za-z0-9_-]{20,}|1//0[A-Za-z0-9_-]{20,}|act[.][A-Za-z0-9!*._-]{20,}|rft[.][A-Za-z0-9!*._-]{20,}|pina_[A-Za-z0-9]{20,}|pinr[A-Za-z0-9._-]{20,}|EAA[A-Za-z0-9]{30,})' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Die Daten enthalten einen Zugangsschlüssel. Bitte nur Kennzahlen und Beitragsangaben übergeben (ohne paging-Adressen).');
  END IF;
  IF d ? 'zielgruppe_vollstaendig' AND jsonb_typeof(d->'zielgruppe_vollstaendig') NOT IN ('boolean', 'null') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Das Feld zielgruppe_vollstaendig muss true oder false sein.');
  END IF;
  zg := coalesce((d->>'zielgruppe_vollstaendig')::boolean, false);
  nm := nullif(left(btrim(regexp_replace(ltrim(btrim(coalesce(d->>'konto_name', '')), '@'), '[[:cntrl:]]', ' ', 'g')), 200), '');
  r := talents_abruf_speichern(k.id, d - 'konto_name' - 'zielgruppe_vollstaendig' - 'plattform');
  IF coalesce((r->>'ok')::boolean, false) THEN
    IF nm IS NOT NULL AND nm IS DISTINCT FROM k.extern_name THEN
      UPDATE talent_kanaele SET extern_name = nm, geaendert_am = now() WHERE id = k.id;
      name_neu := true;
    END IF;
    IF zg THEN
      UPDATE talent_kanaele SET abruf_woechentlich_am = now(), geaendert_am = now() WHERE id = k.id;
    END IF;
  END IF;
  RETURN r || jsonb_build_object('konto_name_aktualisiert', name_neu, 'zielgruppe_vermerkt', zg AND coalesce((r->>'ok')::boolean, false));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_apps_json()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object('plattform', x.pl, 'name', x.name, 'anbieter', x.anbieter,
      'app_id', CASE WHEN x.pl = 'facebook' THEN btrim(ally_einstellung('meta_app_id')) ELSE btrim(ally_einstellung(x.id_einst)) END,
      'app_id_name', x.id_name, 'secret_name', x.sec_name, 'app_id_aenderbar', x.pl <> 'facebook',
      'secret_vorhanden', ally_geheim_vorhanden(x.sec),
      'schalter', x.pl = 'facebook', 'an', (w.d->>'an')::boolean,
      'rueckleitung', w.d->>'rueckleitung', 'scopes', w.d->>'scopes', 'bereit', (w.d->>'bereit')::boolean,
      'verbunden', (SELECT count(*) FROM talent_kanaele k WHERE k.plattform = x.pl AND k.status = 'verbunden'),
      'hinweis', x.hinweis) ORDER BY x.o), '[]'::jsonb)
  FROM (VALUES
    (1, 'facebook', 'Facebook-Seiten', 'Meta (gleiche App wie Instagram über Facebook)', NULL, 'App-ID (aus der Karte Meta-App)', NULL, 'meta_app_secret',
     'Erst einschalten, wenn die Berechtigung read_insights in der Meta-App hinzugefügt ist und die Rückleitungsadresse unter Facebook Login › Einstellungen › Gültige OAuth-Weiterleitungs-URIs eingetragen ist.'),
    (2, 'threads', 'Threads', 'Meta (Anwendungsfall „Access the Threads API“)', 'threads_app_id', 'Threads-App-ID', 'Threads-App-Geheimcode', 'threads_app_secret',
     'Threads app ID und Threads app secret stehen im App-Dashboard unter Settings. Rückleitungsadresse unter Client OAuth Settings eintragen.'),
    (3, 'youtube', 'YouTube', 'Google Cloud (OAuth-Client vom Typ Webanwendung)', 'google_client_id', 'Client-ID', 'Clientschlüssel', 'google_client_secret',
     'Rückleitungsadresse beim OAuth-Client unter „Autorisierte Weiterleitungs-URIs“ eintragen. YouTube Data API v3 und YouTube Analytics API aktivieren.'),
    (4, 'pinterest', 'Pinterest', 'Pinterest (My apps)', 'pinterest_app_id', 'App-ID', 'App-Secret', 'pinterest_app_secret',
     'Rückleitungsadresse unter My apps › Manage › Configure › Redirect URIs eintragen.'),
    (5, 'tiktok', 'TikTok', 'TikTok for Developers (Login Kit)', 'tiktok_client_key', 'Client Key', 'Client Secret', 'tiktok_client_secret',
     'Rückleitungsadresse im Login Kit unter Redirect URI eintragen. Vor der Freigabe nur bis zu 10 eigene Testkonten (Sandbox › Target users).')
  ) AS x(o, pl, name, anbieter, id_einst, id_name, sec_name, sec, hinweis)
  CROSS JOIN LATERAL (SELECT talent_weg_weitere(x.pl, (talent_wege(x.pl))[1]) AS d) w
$function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_bereit(p_plattform text, p_kanal_id integer)
 RETURNS TABLE(kanal_id integer, zuletzt timestamp with time zone)
 LANGUAGE sql
 STABLE
AS $function$
  -- Sofortabruf (Stefan 19.10.2026, Migration 52): wie talents_plattform_faellig, aber nur der Kanal p_kanal_id und ohne die Bedingung
  -- "heute noch nicht abgerufen". Facebook-Seite: abgerufen wird mit dem Seiten-Schlüssel (schluessel_zusatz).
  SELECT k.id, k.abruf_taeglich_am
  FROM talent_kanaele k JOIN talents t ON t.id = k.talent_id
  WHERE k.id = p_kanal_id AND p_plattform = ANY (talents_weitere_plattformen()) AND k.plattform = p_plattform
    AND k.status = 'verbunden' AND t.status = 'aktiv' AND coalesce(btrim(k.extern_id), '') <> ''
    AND CASE WHEN p_plattform = 'facebook' THEN k.schluessel_zusatz ELSE k.schluessel END IS NOT NULL
    AND (k.pause_bis IS NULL OR k.pause_bis <= now())
$function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_faellig(p_plattform text)
 RETURNS TABLE(kanal_id integer, zuletzt timestamp with time zone)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT k.id, k.abruf_taeglich_am
  FROM talent_kanaele k JOIN talents t ON t.id = k.talent_id AND NOT t.testdaten /* Testdaten (Migration 79) */
  WHERE p_plattform = ANY (talents_weitere_plattformen()) AND k.plattform = p_plattform
    AND k.status = 'verbunden' AND t.status = 'aktiv' AND coalesce(btrim(k.extern_id), '') <> ''
    -- Facebook-Seite: abgerufen wird mit dem Seiten-Schlüssel (schluessel_zusatz)
    AND CASE WHEN p_plattform = 'facebook' THEN k.schluessel_zusatz ELSE k.schluessel END IS NOT NULL
    AND (k.pause_bis IS NULL OR k.pause_bis <= now())
    -- Migration 195 (Stefan 01.11.2026, Abrufzeiten): täglich ab der eingestellten Uhrzeit, ohne Versuch in der Wartezeit
    AND talents_abrufzeit_faellig('taeglich', k.abruf_taeglich_am, k.id)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_hinweis(p_plattform text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_plattform
    WHEN 'facebook' THEN 'Facebook liefert Seiten-Statistiken erst ab 100 Likes der Seite; Angaben zu Alter und Geschlecht gibt es nicht.'
    WHEN 'threads' THEN 'Threads liefert für das Profil Aufrufe des Profils, keine Aufrufe der Beiträge. Zielgruppe ab 100 Followern.'
    WHEN 'youtube' THEN 'YouTube-Zahlen kommen mit 2 bis 3 Tagen Verzögerung. Summen, Veränderungen und Anteile berechnet Ally aus den YouTube-Daten; sie stammen nicht von YouTube.'
    WHEN 'pinterest' THEN 'Pinterest liefert Zahlen nur für die letzten 90 Tage; ältere Tage stammen aus den Abrufen von Ally.'
    WHEN 'tiktok' THEN 'TikTok liefert nur Gesamtzahlen. Tageswerte entstehen aus den täglichen Ständen, die Ally speichert; vor der Verbindung gibt es keine Werte.' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_name(p_plattform text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_plattform WHEN 'instagram' THEN 'Instagram' WHEN 'facebook' THEN 'Facebook' WHEN 'threads' THEN 'Threads'
    WHEN 'youtube' THEN 'YouTube' WHEN 'tiktok' THEN 'TikTok' WHEN 'pinterest' THEN 'Pinterest' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_schluessel_speichern(p_kanal_id integer, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  k talent_kanaele%ROWTYPE;
  sch text := nullif(btrim(coalesce(d->>'schluessel', '')), '');
  gb timestamptz;
  gb_setzen boolean := d ? 'gueltig_bis' AND nullif(btrim(coalesce(d->>'gueltig_bis', '')), '') IS NOT NULL;
BEGIN
  SELECT * INTO k FROM talent_kanaele WHERE id = p_kanal_id FOR UPDATE;
  IF k.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Kanal.');
  END IF;
  IF k.plattform NOT IN ('threads', 'youtube', 'pinterest', 'tiktok') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Erneuern lassen sich nur Kanäle von Threads, YouTube, Pinterest und TikTok.');
  END IF;
  IF k.status <> 'verbunden' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Dieser Kanal ist nicht verbunden.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  IF sch IS NOT NULL AND (length(sch) > 4000 OR sch ~ '[[:space:]]') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Kein gültiger Zugangsschlüssel.');
  END IF;
  IF k.plattform = 'threads' AND sch IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Kein gültiger Zugangsschlüssel.');
  END IF;
  IF gb_setzen THEN
    BEGIN
      gb := talents_gueltig_bis(d->>'gueltig_bis');
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Ungültiges Ablaufdatum.');
    END;
  END IF;
  UPDATE talent_kanaele SET schluessel = CASE WHEN sch IS NOT NULL THEN ally_verschluesseln(sch) ELSE schluessel END,
    gueltig_bis = CASE WHEN gb_setzen THEN gb ELSE gueltig_bis END,
    berechtigungen = CASE WHEN d ? 'berechtigungen' AND cardinality(talents_liste(d->'berechtigungen')) > 0 THEN talents_liste(d->'berechtigungen') ELSE berechtigungen END,
    geprueft_am = now(), geaendert_am = now()
  WHERE id = k.id
  RETURNING * INTO k;
  RETURN jsonb_build_object('ok', true, 'kanal_id', k.id, 'schluessel_neu', sch IS NOT NULL, 'gueltig_bis', k.gueltig_bis, 'gueltig_bis_text', talents_datum(k.gueltig_bis));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false,
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_plattform_verlaengern_faellig(p_kanal_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM talent_kanaele k JOIN talents t ON t.id = k.talent_id AND NOT t.testdaten /* Testdaten (Migration 79) */
    WHERE k.id = p_kanal_id AND k.plattform = 'threads' AND k.status = 'verbunden' AND t.status = 'aktiv' AND k.schluessel IS NOT NULL
      AND coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am) <= now() - interval '24 hours'
      AND (k.gueltig_bis IS NULL OR (k.gueltig_bis > now() AND k.gueltig_bis <= now() + interval '14 days')))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_plattformen()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT ARRAY['instagram', 'facebook', 'threads', 'youtube', 'tiktok', 'pinterest']
$function$
;

CREATE OR REPLACE FUNCTION public.talents_profil_papierkorb(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb; u text; verw boolean; adm boolean; e talent_profil_papierkorb%ROWTYPE; r jsonb;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  m text := NULL; fehler text := NULL; n integer := 0;
BEGIN
  -- Migration 130: Papierkorb des Talent-Profils (und Texte ohne Talent). Rechte je Eintrag wie beim Löschen (talents_profil_pk_darf). Setzt die Meldung selbst.
  c := talents_ansicht_start(p_token);
  IF NOT coalesce((c->>'angemeldet')::boolean, false) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT coalesce((c->>'ok')::boolean, false) THEN
    fehler := coalesce(c->>'fehler', 'Bitte neu anmelden.');
  ELSE
    u := c->>'u'; verw := coalesce((c->>'verw')::boolean, false); adm := ally_hat_recht(u, 'admin');
    IF p_aktion IN ('tp_papierkorb_wiederherstellen', 'tp_papierkorb_endgueltig') THEN
      IF coalesce(d->>'id', '') ~ '^[0-9]{1,18}$' THEN SELECT * INTO e FROM talent_profil_papierkorb x WHERE x.id = (d->>'id')::bigint FOR UPDATE; END IF;
      IF e.id IS NULL OR NOT talents_profil_pk_darf(u, verw, adm, e) THEN
        fehler := 'Dieser Eintrag liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.';
      ELSIF p_aktion = 'tp_papierkorb_wiederherstellen' THEN
        r := talents_profil_pk_zurueck(e.id, u);
        fehler := r->>'fehler'; m := r->>'meldung';
      ELSE
        DELETE FROM talent_profil_papierkorb x WHERE x.id = e.id;
        m := CASE e.art WHEN 'aufgabe' THEN talents_planung_art_text(e.daten->'aufgabe'->>'art') || ' „' || e.titel || '“ endgültig gelöscht.'
                        WHEN 'notiz' THEN 'Notiz endgültig gelöscht.' WHEN 'text' THEN 'Text „' || e.titel || '“ endgültig gelöscht.'
                        WHEN 'ziel' THEN 'Ziel „' || e.titel || '“ endgültig gelöscht.' ELSE e.titel || ' endgültig gelöscht.' END;
      END IF;
    ELSIF p_aktion = 'tp_papierkorb_leeren' THEN
      IF coalesce(d->>'ids', '') !~ '^[0-9]{1,18}(,[0-9]{1,18})*$' OR cardinality(string_to_array(d->>'ids', ',')) > 1000 THEN
        fehler := 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.';
      ELSE
        -- genau die angezeigten Einträge, soweit erlaubt
        DELETE FROM talent_profil_papierkorb x WHERE x.id = ANY (string_to_array(d->>'ids', ',')::bigint[]) AND talents_profil_pk_darf(u, verw, adm, x);
        GET DIAGNOSTICS n = ROW_COUNT;
        m := CASE WHEN n = 0 THEN 'Diese Einträge liegen nicht mehr im Papierkorb.' WHEN n = 1 THEN '1 Eintrag endgültig gelöscht.' ELSE n || ' Einträge endgültig gelöscht.' END;
      END IF;
    ELSE
      fehler := 'Diese Aktion gibt es nicht.';
    END IF;
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_profil_pk_darf(p_u text, p_verw boolean, p_adm boolean, p_e talent_profil_papierkorb)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 130: Recht an einem Eintrag im Papierkorb des Talent-Profils = Recht beim Löschen (talents_planung_ui_aktion, talents_notiz_aktion,
  -- talents_texte_aktion/talents_ki_text_sichtbar, talents_konzept_aktion, talents_manuell_web_aktion). Aufgabe mit inzwischen gelöschter Kampagne: Talent verwalten.
  SELECT CASE p_e.art
    WHEN 'aufgabe' THEN CASE WHEN p_e.kampagne_id IS NULL OR NOT EXISTS (SELECT 1 FROM talent_kampagnen k WHERE k.id = p_e.kampagne_id)
                               OR NOT EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = p_e.kampagne_id AND kt.talent_id = p_e.talent_id)
                             THEN coalesce(talent_verwaltbar(p_u, p_e.talent_id), false)
                             ELSE talents_planung_talent_verwaltbar(p_u, p_e.kampagne_id, p_e.talent_id) END
    WHEN 'notiz' THEN coalesce(talent_sichtbar(p_u, p_e.talent_id), false) AND coalesce(talent_verwaltbar(p_u, p_e.talent_id), false)
                      AND (p_e.daten->'notiz'->>'erstellt_von' = p_u OR p_adm)
    WHEN 'text' THEN CASE WHEN p_e.talent_id IS NOT NULL THEN coalesce(talent_sichtbar(p_u, p_e.talent_id), false)
                          ELSE p_e.daten->'text'->>'erstellt_von' = p_u OR talents_zugriff(p_u) = 'alle'
                               OR (p_e.daten->'text'->>'anfrage_id' ~ '^[0-9]{1,9}$' AND coalesce(talents_ki_anfrage_sichtbar(p_u, (p_e.daten->'text'->>'anfrage_id')::integer), false)) END
    WHEN 'ziel' THEN coalesce(talent_sichtbar(p_u, p_e.talent_id), false)
    WHEN 'wert' THEN coalesce(talent_sichtbar(p_u, p_e.talent_id), false) AND coalesce(talent_verwaltbar(p_u, p_e.talent_id), false)
                     AND (p_verw OR p_e.daten->'wert'->>'bestaetigt_von' = p_u)
    ELSE false END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_profil_pk_legen(p_art text, p_id bigint, p_u text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
  a talent_aufgaben%ROWTYPE; n talent_notizen%ROWTYPE; x talent_ki_texte%ROWTYPE; z talent_konzept_ziele%ROWTYPE; w talent_manuell_werte%ROWTYPE;
  tid integer; kid integer; ti text; dt jsonb; neu bigint;
BEGIN
  -- Migration 130: Unterobjekt des Talent-Profils als Schnappschuss in den Papierkorb legen und aus seiner Tabelle entfernen (Rechte prüft der Aufrufer).
  IF p_art = 'aufgabe' THEN
    SELECT * INTO a FROM talent_aufgaben WHERE id = p_id FOR UPDATE;
    IF a.id IS NULL THEN RAISE EXCEPTION 'Migration 130: Aufgabe % nicht gefunden', p_id; END IF;
    tid := a.talent_id; kid := a.kampagne_id; ti := coalesce(nullif(btrim(a.titel), ''), talents_planung_art_text(a.art));
    dt := jsonb_build_object('aufgabe', to_jsonb(a),
      'nachrichten', (SELECT coalesce(jsonb_agg(to_jsonb(y) - 'geheim' ORDER BY y.id), '[]'::jsonb) FROM ally_systemnachrichten y WHERE y.aufgabe_id = a.id),
      'lauf_aufgabe', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'aufgabe_id', l.aufgabe_id) ORDER BY l.id), '[]'::jsonb) FROM talent_erinnerungen_lauf l WHERE l.aufgabe_id = a.id));
    DELETE FROM talent_aufgaben WHERE id = a.id;
  ELSIF p_art = 'notiz' THEN
    SELECT * INTO n FROM talent_notizen WHERE id = p_id FOR UPDATE;
    IF n.id IS NULL THEN RAISE EXCEPTION 'Migration 130: Notiz % nicht gefunden', p_id; END IF;
    tid := n.talent_id; ti := left(regexp_replace(btrim(n.text), '\s+', ' ', 'g'), 80) || CASE WHEN length(btrim(n.text)) > 80 THEN '…' ELSE '' END;
    dt := jsonb_build_object('notiz', to_jsonb(n));
    DELETE FROM talent_notizen WHERE id = n.id;
  ELSIF p_art = 'text' THEN
    SELECT * INTO x FROM talent_ki_texte WHERE id = p_id FOR UPDATE;
    IF x.id IS NULL THEN RAISE EXCEPTION 'Migration 130: Text % nicht gefunden', p_id; END IF;
    tid := x.talent_id; kid := x.kampagne_id; ti := coalesce(nullif(btrim(x.titel), ''), 'Text');
    dt := jsonb_build_object('text', to_jsonb(x));
    DELETE FROM talent_ki_texte WHERE id = x.id;
  ELSIF p_art = 'ziel' THEN
    SELECT * INTO z FROM talent_konzept_ziele WHERE id = p_id FOR UPDATE;
    IF z.id IS NULL THEN RAISE EXCEPTION 'Migration 130: Ziel % nicht gefunden', p_id; END IF;
    tid := z.talent_id;
    ti := CASE z.kennzahl WHEN 'follower' THEN 'Follower' WHEN 'follower_zuwachs' THEN 'Follower-Zuwachs' WHEN 'reichweite' THEN 'Reichweite' WHEN 'aufrufe' THEN 'Aufrufe'
            WHEN 'interaktionen' THEN 'Interaktionen' WHEN 'interaktionsrate' THEN 'Interaktionsrate' WHEN 'beitraege' THEN 'Beiträge' ELSE coalesce(z.kennzahl, 'Ziel') END
          || ' ' || replace(regexp_replace(round(z.zielwert, 1)::text, '\.0$', ''), '.', ',')
          || CASE WHEN z.kennzahl = 'interaktionsrate' THEN ' %' ELSE '' END
          || ' (' || to_char(z.von, 'DD.MM.YYYY') || ' bis ' || to_char(z.bis, 'DD.MM.YYYY') || ')';
    dt := jsonb_build_object('ziel', to_jsonb(z));
    DELETE FROM talent_konzept_ziele WHERE id = z.id;
  ELSIF p_art = 'wert' THEN
    SELECT * INTO w FROM talent_manuell_werte WHERE id = p_id FOR UPDATE;
    IF w.id IS NULL THEN RAISE EXCEPTION 'Migration 130: Wert % nicht gefunden', p_id; END IF;
    tid := w.talent_id; ti := talents_manuell_kennzahl_name(w.bereich, w.kennzahl) || ' (' || talents_manuell_zeitraum_text(w.von, w.bis) || ')';
    -- Doppelt-Entscheidung und -Meldung hängen per Fremdschlüssel am Wert (ON DELETE CASCADE): mit in den Schnappschuss (Koordinator 24.10.2026)
    dt := jsonb_build_object('wert', to_jsonb(w),
      'entscheidungen', (SELECT coalesce(jsonb_agg(to_jsonb(e)), '[]'::jsonb) FROM talent_doppelt_entscheidungen e WHERE e.manuell_id = w.id),
      'meldungen', (SELECT coalesce(jsonb_agg(to_jsonb(e)), '[]'::jsonb) FROM talent_doppelt_meldungen e WHERE e.manuell_id = w.id));
    DELETE FROM talent_manuell_werte WHERE id = w.id;
  ELSE
    RAISE EXCEPTION 'Migration 130: unbekannte Art %', p_art;
  END IF;
  INSERT INTO talent_profil_papierkorb (art, objekt_id, talent_id, kampagne_id, titel, daten, testdaten, geloescht_von)
  VALUES (p_art, p_id, tid, kid, left(coalesce(nullif(ti, ''), '–'), 300), dt, coalesce((SELECT t.testdaten FROM talents t WHERE t.id = tid), false), p_u)
  RETURNING id INTO neu;
  RETURN neu;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_profil_pk_liste(p_token text, p_talent_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb := talents_ansicht_start(p_token); u text; verw boolean; adm boolean; l jsonb;
BEGIN
  -- Migration 130: Papierkorb des Talent-Profils (nur Einträge, für die die Person das Recht hat; neueste zuerst, höchstens 1000).
  -- Ohne Talent (NULL): Texte ohne Talent (Seite Talents › Papierkorb).
  IF NOT coalesce((c->>'ok')::boolean, false) THEN RETURN jsonb_build_object('ok', false); END IF;
  u := c->>'u'; verw := coalesce((c->>'verw')::boolean, false); adm := ally_hat_recht(u, 'admin');
  IF p_talent_id IS NOT NULL AND NOT coalesce(talent_sichtbar(u, p_talent_id), false) THEN RETURN jsonb_build_object('ok', false); END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id::text, 'art', x.art,
      'art_text', CASE x.art WHEN 'aufgabe' THEN talents_planung_art_text(x.daten->'aufgabe'->>'art') WHEN 'notiz' THEN 'Notiz' WHEN 'text' THEN 'KI-Text'
                             WHEN 'ziel' THEN 'Konzept-Ziel' ELSE 'Wert (manuell)' END,
      'titel', x.titel,
      'kampagne', (SELECT k.name FROM talent_kampagnen k WHERE k.id = x.kampagne_id),
      'geloescht', to_char(x.geloescht_am AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI'),
      'geloescht_von', coalesce((SELECT p.name FROM ally_personen p WHERE p.matrix_user_id = x.geloescht_von), ''),
      'testdaten', x.testdaten) ORDER BY x.geloescht_am DESC, x.id DESC), '[]'::jsonb) INTO l
  FROM (SELECT y.* FROM talent_profil_papierkorb y
        WHERE (p_talent_id IS NOT NULL AND y.talent_id = p_talent_id) OR (p_talent_id IS NULL AND y.talent_id IS NULL)
        ORDER BY y.geloescht_am DESC, y.id DESC) x
  WHERE talents_profil_pk_darf(u, verw, adm, x);
  RETURN jsonb_build_object('ok', true, 'eintraege', (SELECT coalesce(jsonb_agg(e), '[]'::jsonb) FROM (SELECT e FROM jsonb_array_elements(l) e LIMIT 1000) q));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_profil_pk_zurueck(p_id bigint, p_u text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  e talent_profil_papierkorb%ROWTYPE; dt jsonb; kt text; a talent_aufgaben%ROWTYPE; w talent_manuell_werte%ROWTYPE; z talent_konzept_ziele%ROWTYPE;
  ko_id integer; ko_status text; m text; nach boolean := false;
BEGIN
  -- Migration 130: Eintrag aus dem Papierkorb des Talent-Profils mit seiner alten Nummer wiederherstellen (Rechte prüft der Aufrufer). Fehler: {fehler}, sonst {meldung}.
  SELECT * INTO e FROM talent_profil_papierkorb WHERE id = p_id FOR UPDATE;
  IF e.id IS NULL THEN RETURN jsonb_build_object('fehler', 'Dieser Eintrag liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.'); END IF;
  dt := e.daten;
  -- Prüfung 130 G2: liegt das Talent selbst im Papierkorb, kommt nichts zurück (dort ruht alles)
  IF e.talent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = e.talent_id AND t.status = 'aktiv') THEN
    RETURN jsonb_build_object('fehler', 'Das Talent liegt im Papierkorb. Erst das Talent wiederherstellen, dann diesen Eintrag.');
  END IF;
  IF e.art = 'aufgabe' THEN
    a := jsonb_populate_record(NULL::talent_aufgaben, dt->'aufgabe');
    IF a.kampagne_id IS NOT NULL THEN
      kt := (SELECT k.name FROM talent_kampagnen k WHERE k.id = a.kampagne_id);
      IF kt IS NULL THEN
        kt := (SELECT p.titel FROM talent_kampagnen_papierkorb p WHERE p.art = 'kampagne' AND p.objekt_id = a.kampagne_id);
        RETURN jsonb_build_object('fehler', CASE WHEN kt IS NOT NULL THEN 'Die Kampagne „' || kt || '“ liegt im Papierkorb der Kampagnen. Bitte zuerst die Kampagne wiederherstellen.'
          ELSE 'Die Kampagne zu diesem Eintrag gibt es nicht mehr. Den Eintrag kannst du nur noch endgültig löschen.' END);
      END IF;
      IF NOT EXISTS (SELECT 1 FROM talent_kampagne_talents x WHERE x.kampagne_id = a.kampagne_id AND x.talent_id = a.talent_id) THEN
        RETURN jsonb_build_object('fehler', 'Das Talent gehört nicht mehr zur Kampagne „' || kt || '“. Bitte das Talent zuerst wieder der Kampagne zuordnen.');
      END IF;
    END IF;
    IF a.deliverable_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talent_deliverables d WHERE d.id = a.deliverable_id AND d.talent_id = a.talent_id) THEN
      RETURN jsonb_build_object('fehler', CASE WHEN EXISTS (SELECT 1 FROM talent_kampagnen_papierkorb p WHERE p.art = 'deliverable' AND p.objekt_id = a.deliverable_id)
        THEN 'Das Deliverable zu diesem Eintrag liegt im Papierkorb der Kampagnen. Bitte zuerst das Deliverable wiederherstellen.'
        ELSE 'Das Deliverable zu diesem Eintrag gibt es nicht mehr. Den Eintrag kannst du nur noch endgültig löschen.' END);
    END IF;
    -- wie 131: Regel und Version werden leer, wenn es sie nicht mehr gibt
    IF a.regel_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talent_erinnerungsregeln g WHERE g.id = a.regel_id) THEN a.regel_id := NULL; END IF;
    IF a.version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talent_deliverable_versionen v WHERE v.id = a.version_id) THEN a.version_id := NULL; END IF;
    INSERT INTO talent_aufgaben SELECT a.* ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN RETURN jsonb_build_object('fehler', 'Der Eintrag lässt sich nicht wiederherstellen (Nummer schon vergeben). Bitte die Seite neu laden.'); END IF;
    INSERT INTO ally_systemnachrichten SELECT y.* FROM jsonb_populate_recordset(NULL::ally_systemnachrichten, coalesce(dt->'nachrichten', '[]')) y ON CONFLICT DO NOTHING;
    UPDATE talent_erinnerungen_lauf l SET aufgabe_id = a.id FROM jsonb_array_elements(coalesce(dt->'lauf_aufgabe', '[]')) j2
    WHERE l.id = (j2->>'id')::bigint AND l.aufgabe_id IS NULL;
    nach := a.art = 'erinnerung' AND a.quelle = 'hand' AND a.status = 'offen' AND a.benachrichtigt_am IS NULL AND 'bereich' = ANY (a.kanaele)
            AND a.faellig_am <= now() AND a.faellig_am > now() - interval '2 days';
    m := talents_planung_art_text(a.art) || ' „' || e.titel || '“ wiederhergestellt.'
      || CASE WHEN nach THEN ' Die Erinnerung war in den letzten 2 Tagen fällig und kommt einmal nach.' ELSE '' END;
  ELSIF e.art = 'notiz' THEN
    INSERT INTO talent_notizen SELECT y.* FROM jsonb_populate_record(NULL::talent_notizen, dt->'notiz') y ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN RETURN jsonb_build_object('fehler', 'Die Notiz lässt sich nicht wiederherstellen (Nummer schon vergeben). Bitte die Seite neu laden.'); END IF;
    m := 'Notiz wiederhergestellt.';
  ELSIF e.art = 'text' THEN
    INSERT INTO talent_ki_texte SELECT y.* FROM jsonb_populate_record(NULL::talent_ki_texte, dt->'text') y ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN RETURN jsonb_build_object('fehler', 'Der Text lässt sich nicht wiederherstellen (Nummer schon vergeben). Bitte die Seite neu laden.'); END IF;
    m := 'Text „' || e.titel || '“ wiederhergestellt.';
  ELSIF e.art = 'ziel' THEN
    z := jsonb_populate_record(NULL::talent_konzept_ziele, dt->'ziel');
    SELECT k.id, k.status INTO ko_id, ko_status FROM talent_konzepte k WHERE k.id = z.konzept_id;
    IF ko_id IS NULL THEN
      RETURN jsonb_build_object('fehler', 'Das Konzept zu diesem Ziel gibt es nicht mehr. Den Eintrag kannst du nur noch endgültig löschen.');
    ELSIF ko_status NOT IN ('entwurf', 'aktiv') THEN
      RETURN jsonb_build_object('fehler', 'Ziele lassen sich nur bei einem Entwurf oder aktiven Konzept wiederherstellen. Dieses Konzept ist abgelegt.');
    ELSIF (SELECT count(*) FROM talent_konzept_ziele x WHERE x.konzept_id = z.konzept_id) >= 8 THEN
      RETURN jsonb_build_object('fehler', 'Höchstens 8 Ziele je Konzept. Bitte zuerst ein anderes Ziel löschen.');
    END IF;
    INSERT INTO talent_konzept_ziele SELECT z.* ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN RETURN jsonb_build_object('fehler', 'Das Ziel lässt sich nicht wiederherstellen (Nummer schon vergeben). Bitte die Seite neu laden.'); END IF;
    m := 'Ziel „' || e.titel || '“ wiederhergestellt.';
  ELSIF e.art = 'wert' THEN
    w := jsonb_populate_record(NULL::talent_manuell_werte, dt->'wert');
    -- wie beim Bestätigen: gleicher Schlüssel (Plattform, Konto, Bereich, Kennzahl, Zeitraum, Beitrag) gibt es nur einmal
    IF EXISTS (SELECT 1 FROM talent_manuell_werte y WHERE y.talent_id = w.talent_id AND y.plattform = w.plattform AND y.bereich = w.bereich AND y.kennzahl = w.kennzahl
                 AND y.von IS NOT DISTINCT FROM w.von AND y.bis = w.bis AND coalesce(y.beitrag_link, '') = coalesce(w.beitrag_link, '') AND coalesce(y.konto, '') = coalesce(w.konto, '')) THEN
      RETURN jsonb_build_object('fehler', 'Für ' || e.titel || ' gibt es inzwischen einen anderen Wert. Bitte den Eintrag im Papierkorb endgültig löschen oder zuerst den anderen Wert löschen.');
    END IF;
    IF w.vorschlag_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talent_manuell_vorschlaege v WHERE v.id = w.vorschlag_id) THEN w.vorschlag_id := NULL; END IF;
    -- Prüfung 130 G1: der Auslöser talent_manuell_werte_doppelt prüft erst, wenn Entscheidung und Meldung zurück sind (talents_doppelt_pruefen danach);
    -- eine schon entschiedene oder gemeldete Überschneidung meldet so nichts neu, nur eine echte neue
    PERFORM set_config('talents.pk_zurueck', '1', true);
    INSERT INTO talent_manuell_werte SELECT w.* ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
      PERFORM set_config('talents.pk_zurueck', '', true);
      RETURN jsonb_build_object('fehler', 'Der Wert lässt sich nicht wiederherstellen (Nummer schon vergeben). Bitte die Seite neu laden.');
    END IF;
    PERFORM set_config('talents.pk_zurueck', '', true);
    INSERT INTO talent_doppelt_entscheidungen SELECT y.* FROM jsonb_populate_recordset(NULL::talent_doppelt_entscheidungen, coalesce(dt->'entscheidungen', '[]')) y ON CONFLICT DO NOTHING;
    INSERT INTO talent_doppelt_meldungen SELECT y.* FROM jsonb_populate_recordset(NULL::talent_doppelt_meldungen, coalesce(dt->'meldungen', '[]')) y ON CONFLICT DO NOTHING;
    PERFORM talents_doppelt_pruefen(ARRAY[w.id], 'bearbeiten');
    m := e.titel || ' wiederhergestellt.';
  END IF;
  DELETE FROM talent_profil_papierkorb WHERE id = e.id;
  RETURN jsonb_build_object('meldung', m);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_regel_papierkorb(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb; rg talent_erinnerungsregeln%ROWTYPE;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  m text := NULL; fehler text := NULL; n integer := 0;
BEGIN
  -- Migration 129: Papierkorb der Standard-Erinnerungen (Einstellungen › Kampagnen). Recht wie beim Ändern: „Talents und Kampagnen verwalten“ für alle Talents.
  c := talents_planung_start(p_token, 'kampagnen');
  IF NOT coalesce((c->>'angemeldet')::boolean, false) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT (c->>'ok')::boolean THEN
    fehler := coalesce(c->>'fehler', 'Bitte neu anmelden.');
  ELSIF NOT coalesce((c->>'verw')::boolean, false) THEN
    fehler := 'Standard-Erinnerungen ändert, wer das Recht „Talents und Kampagnen verwalten“ für alle Talents hat.';
  ELSIF p_aktion IN ('kp_regel_wiederherstellen', 'kp_regel_endgueltig') THEN
    IF coalesce(d->>'id', '') ~ '^[0-9]{1,9}$' THEN SELECT * INTO rg FROM talent_erinnerungsregeln r WHERE r.id = (d->>'id')::integer FOR UPDATE; END IF;
    IF rg.id IS NULL OR rg.geloescht_am IS NULL OR rg.kampagne_id IS NOT NULL THEN
      fehler := 'Diese Regel liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.';
    ELSIF p_aktion = 'kp_regel_wiederherstellen' AND EXISTS (SELECT 1 FROM talent_erinnerungsregeln g WHERE g.kampagne_id IS NULL AND g.geloescht_am IS NULL
        AND g.bezug = rg.bezug AND g.versatz_tage = rg.versatz_tage AND g.empfaenger = rg.empfaenger) THEN
      fehler := 'Die gleiche Standard-Erinnerung gibt es inzwischen schon. Bitte die Regel im Papierkorb endgültig löschen oder die andere zuerst ändern.';
    ELSIF p_aktion = 'kp_regel_wiederherstellen' THEN
      UPDATE talent_erinnerungsregeln SET geloescht_am = NULL, geloescht_von = NULL, geaendert_am = now(), geaendert_von = c->>'u' WHERE id = rg.id;
      m := 'Standard-Erinnerung „' || talents_planung_regel_text(rg.bezug, rg.versatz_tage) || '“ wiederhergestellt.';
    ELSE
      DELETE FROM talent_erinnerungsregeln WHERE id = rg.id;
      m := 'Standard-Erinnerung „' || talents_planung_regel_text(rg.bezug, rg.versatz_tage) || '“ endgültig gelöscht.';
    END IF;
  ELSIF p_aktion = 'kp_regel_papierkorb_leeren' THEN
    IF coalesce(d->>'ids', '') !~ '^[0-9]{1,9}(,[0-9]{1,9})*$' OR cardinality(string_to_array(d->>'ids', ',')) > 1000 THEN
      fehler := 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.';
    ELSE
      DELETE FROM talent_erinnerungsregeln r WHERE r.id = ANY (string_to_array(d->>'ids', ',')::integer[]) AND r.geloescht_am IS NOT NULL AND r.kampagne_id IS NULL;
      GET DIAGNOSTICS n = ROW_COUNT;
      m := CASE WHEN n = 0 THEN 'Diese Regeln liegen nicht mehr im Papierkorb.' WHEN n = 1 THEN '1 Standard-Erinnerung endgültig gelöscht.' ELSE n || ' Standard-Erinnerungen endgültig gelöscht.' END;
    END IF;
  ELSE
    fehler := 'Diese Aktion gibt es nicht.';
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_regex(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT regexp_replace(coalesce(p, ''), '([].\\+*?^$(){}|[-])', '\\\1', 'g')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_rueckleitung()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT rtrim(btrim(ally_einstellung('n8n_oeffentlich')), '/') || ally_webhook_aussen() || '/einladung/zurueck'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_rueckleitung_instagram()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT rtrim(btrim(ally_einstellung('n8n_oeffentlich')), '/') || ally_webhook_aussen() || '/einladung/zurueck-instagram'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_rueckleitung_weg(p_weg text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN p_weg IN ('facebook', 'threads', 'google', 'pinterest', 'tiktok')
    THEN rtrim(btrim(ally_einstellung('n8n_oeffentlich')), '/') || ally_webhook_aussen() || '/einladung/zurueck-' || p_weg END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_seite_adresse(p_abfrage text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT rtrim(btrim(ally_einstellung('n8n_oeffentlich')), '/') || '/webhook/web' || CASE WHEN coalesce(p_abfrage, '') <> '' THEN '?' || p_abfrage ELSE '' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_seite_nr(p text, p_anzahl integer, p_je integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT greatest(1, least(CASE WHEN btrim(coalesce(p, '')) ~ '^[0-9]{1,6}$' THEN btrim(p)::integer ELSE 1 END,
                           greatest(1, ceil(coalesce(p_anzahl, 0)::numeric / greatest(p_je, 1))::integer)))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_sofortabruf_kanaele(p_talent_id integer)
 RETURNS TABLE(kanal_id integer, plattform text, art text)
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 194 (Stefan 01.11.2026, „Daten jetzt abrufen“): welche Abrufe der Knopf im Talent-Profil für dieses Talent startet. Dieselbe Prüfung wie beim
  -- Sofortabruf nach der Einladung (ALLY 16, Migration 52): verbunden, Talent aktiv, Zugang vorhanden, keine Pause nach einer Abrufgrenze (pause_bis).
  -- Wie der nächtliche Lauf ohne Testdaten. Instagram: täglich (TALENTS 1, mit Beiträgen), Zielgruppe (TALENTS 3) wie ALLY 16 und Storys (TALENTS 2, Einstieg
  -- „Sofort (Talent-Profil)“; Storys nur mit der Facebook-Anmeldung, prüft talents_abruf_bereit); die übrigen Plattformen ihr Tages-Workflow.
  SELECT k.id, k.plattform, a.art
  FROM talent_kanaele k
  JOIN talents t ON t.id = k.talent_id AND NOT t.testdaten
  CROSS JOIN (VALUES ('stuendlich'), ('taeglich'), ('woechentlich')) a(art)
  WHERE k.talent_id = p_talent_id AND plattform_modul_an('talents')
    AND CASE WHEN k.plattform = 'instagram' THEN EXISTS (SELECT 1 FROM talents_abruf_bereit(a.art, k.id))
             WHEN a.art = 'taeglich' AND k.plattform = ANY (talents_weitere_plattformen()) THEN EXISTS (SELECT 1 FROM talents_plattform_bereit(k.plattform, k.id))
             ELSE false END
  ORDER BY k.id, a.art
$function$
;

CREATE OR REPLACE FUNCTION public.talents_sofortabruf_laeuft(p_talent_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 194 (Stefan 01.11.2026, „Daten jetzt abrufen“): Abruf dieses Talents läuft noch = gestartet vor weniger als 10 Minuten und
  -- (seit weniger als 2 Minuten oder ein gestarteter, weiter verbundener Kanal hat sich seit dem Start nicht gemeldet). Gemeldet hat sich ein Kanal, sobald
  -- der Abruf ihn gespeichert oder einen Fehler vermerkt hat (talents_abruf_speichern bzw. talents_abruf_fehler setzen geaendert_am).
  SELECT EXISTS (SELECT 1 FROM talent_sofortabrufe s
    WHERE s.talent_id = p_talent_id AND s.gestartet_am > now() - interval '10 minutes'
      AND (s.gestartet_am > now() - interval '2 minutes'
           OR EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.id = ANY (s.kanaele) AND k.status = 'verbunden' AND k.geaendert_am < s.gestartet_am)))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_sofortabruf_stand(p_token text, p_talent_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb := talents_ansicht_start(p_token);
  s record;
BEGIN
  -- Migration 194 (Stefan 01.11.2026, „Daten jetzt abrufen“): für ALLY 25 („Abruf-Stand“). Ob die Person den Knopf für dieses Talent sieht (Rechte wie
  -- „Report erstellen“ und Datenimport im Talent-Profil: Seite „talent“ freigegeben, „Talents ansehen“, Talent sichtbar), ob ein Abruf läuft und wie viele
  -- Kanäle gerade abrufbar sind. Nur lesend.
  IF NOT coalesce((c->>'ok')::boolean, false) THEN RETURN '{"ok": false}'::jsonb; END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'talent') THEN RETURN '{"ok": false}'::jsonb; END IF;
  IF p_talent_id IS NULL OR NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = p_talent_id) OR NOT coalesce(talent_sichtbar(c->>'u', p_talent_id), false) THEN
    RETURN '{"ok": false}'::jsonb;
  END IF;
  RETURN jsonb_build_object('ok', true, 'laeuft', talents_sofortabruf_laeuft(p_talent_id),
    'abrufbar', (SELECT count(DISTINCT x.kanal_id) FROM talents_sofortabruf_kanaele(p_talent_id) x));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_sofortabruf_ui_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; e jsonb; c jsonb; tid integer; liste jsonb;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  nein jsonb := '{"ok": false, "angemeldet": true}'::jsonb;
  ja jsonb := '{"ok": true, "angemeldet": true}'::jsonb;
BEGIN
  -- Migration 194 (Stefan 01.11.2026, „Daten jetzt abrufen“): Aktion tl_daten_abrufen des Talent-Profils (ALLY 20 „Aktion ausführen“, vor allen anderen);
  -- NULL bei allen anderen Aktionen und ohne Sitzung einer Person (dann gilt alles wie bisher). Rechte wie „Report erstellen“ und Datenimport im Talent-Profil.
  -- Startet nichts selbst: gibt die abrufbaren Kanäle an ALLY 20 (weiter = start, was = talent_abruf), ALLY 20 startet die Abruf-Workflows wie ALLY 16.
  -- Gesperrt, solange ein Abruf dieses Talents läuft (talents_sofortabruf_laeuft); zwei gleichzeitige Klicks warten aufeinander (Beratungssperre je Talent).
  IF p_aktion IS DISTINCT FROM 'tl_daten_abrufen' THEN RETURN NULL; END IF;
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF coalesce(p_csrf, '') <> ally_ui_csrf(s.token_hash) THEN
    RETURN coalesce(ally_web_meldung(p_token, 'Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'fehler', NULL), '{}'::jsonb) || '{"ok": false, "angemeldet": true, "ungueltig": true}'::jsonb;
  END IF;
  IF s.muss_pw_setzen THEN RETURN '{"ok": false, "angemeldet": true, "muss_pw_setzen": true}'::jsonb; END IF;
  IF jsonb_typeof(p_zustand->'z') = 'array' THEN
    FOR e IN SELECT y FROM jsonb_array_elements(p_zustand->'z') y LIMIT 40 LOOP
      IF jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'offen') = 'boolean' THEN PERFORM ally_ui_zustand_merken(s.person, e->>'k', jsonb_build_object('offen', e->'offen')); END IF;
    END LOOP;
  END IF;
  IF NOT ally_ui_funktion_erlaubt(s.person, s.rolle, 'talent') THEN
    PERFORM ally_web_meldung(p_token, 'Talents sind für dich nicht freigeschaltet.', 'fehler', NULL); RETURN nein;
  END IF;
  c := talents_ansicht_start(p_token);
  IF NOT coalesce((c->>'ok')::boolean, false) THEN
    PERFORM ally_web_meldung(p_token, coalesce(c->>'fehler', 'Das geht gerade nicht.'), 'fehler', NULL); RETURN nein;
  END IF;
  tid := CASE WHEN coalesce(d->>'id', '') ~ '^[0-9]{1,9}$' THEN (d->>'id')::integer END;
  IF tid IS NULL OR NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = tid) OR NOT coalesce(talent_sichtbar(c->>'u', tid), false) THEN
    PERFORM ally_web_meldung(p_token, 'Dieses Talent gibt es nicht oder du bist nicht als Manager oder Managerin eingetragen.', 'fehler', NULL); RETURN nein;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('talent_sofortabruf'), tid);
  IF talents_sofortabruf_laeuft(tid) THEN
    PERFORM ally_web_meldung(p_token, 'Der Abruf für dieses Talent läuft schon. Bitte etwas warten und die Seite dann neu laden.', 'fehler', NULL); RETURN nein;
  END IF;
  SELECT jsonb_agg(jsonb_build_object('kanal_id', x.kanal_id, 'plattform', x.plattform, 'art', x.art) ORDER BY x.kanal_id, x.art) INTO liste
  FROM talents_sofortabruf_kanaele(tid) x;
  IF liste IS NULL THEN
    PERFORM ally_web_meldung(p_token, 'Gerade ist kein Kanal dieses Talents abrufbar: nicht verbunden, ohne Zugang, Talent archiviert oder Pause nach einer Abrufgrenze der Plattform.', 'fehler', NULL);
    RETURN nein;
  END IF;
  INSERT INTO talent_sofortabrufe AS a (talent_id, gestartet_am, gestartet_von, kanaele)
  VALUES (tid, now(), s.person, ARRAY(SELECT DISTINCT (y->>'kanal_id')::integer FROM jsonb_array_elements(liste) y ORDER BY 1))
  ON CONFLICT (talent_id) DO UPDATE SET gestartet_am = EXCLUDED.gestartet_am, gestartet_von = EXCLUDED.gestartet_von, kanaele = EXCLUDED.kanaele;
  PERFORM ally_web_meldung(p_token, 'Ally ruft die Daten von ' || coalesce(talent_anzeigename(tid), 'diesem Talent') || ' jetzt ab. Das dauert meist ein bis zwei Minuten. Danach die Seite neu laden.', 'ok', NULL);
  RETURN ja || jsonb_build_object('weiter', 'start', 'r', jsonb_build_object('was', 'talent_abruf', 'talent_id', tid, 'auftraege', liste));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_tag(p timestamp with time zone)
 RETURNS date
 LANGUAGE sql
 STABLE
AS $function$
  SELECT (p AT TIME ZONE 'Europe/Berlin')::date
$function$
;

CREATE OR REPLACE FUNCTION public.talents_tageswert(p_werte jsonb, p_kennzahl text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Wert einer Konto-Kennzahl in talent_kanal_tage (gleiche Regeln wie talents_kanal_zahlen); Kennzahlen ohne automatisches Gegenstück -> NULL (Migration 65)
  SELECT CASE p_kennzahl
    WHEN 'follower' THEN talents_zahl(p_werte->'followers_count')
    WHEN 'reichweite' THEN talents_zahl(p_werte->'reach')
    WHEN 'aufrufe' THEN talents_aufrufe(p_werte)
    WHEN 'interaktionen' THEN talents_interaktionen(p_werte)
    WHEN 'profilaufrufe' THEN coalesce(talents_zahl(p_werte->'profile_views'), talents_zahl(p_werte->'profile_visits')) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_talent(p_token text, p_talent_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb;
  u text;
  verw boolean;
  t record;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  zr jsonb;
  von date; bis date; vv date; vb date; laenge integer;
  kanal text;
  kids integer[];
  sj record; sv record;
  verlauf jsonb;
  beste jsonb;
  zg jsonb;
  hinweise text[] := '{}';
  n_verb integer; n_alle integer; n_ab integer; hat_tage boolean; ig boolean;
  n_beitraege integer;
  stand date;
  man jsonb; kz jsonb; kx jsonb; plattf text[];
  mz boolean;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN
    RETURN c;
  END IF;
  u := c->>'u';
  verw := (c->>'verw')::boolean;
  SELECT * INTO t FROM talents x WHERE x.id = p_talent_id;
  IF NOT FOUND OR NOT talent_sichtbar(u, p_talent_id) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Dieses Talent gibt es nicht oder du bist nicht als Manager oder Managerin eingetragen.');
  END IF;

  zr := talents_zeitraum(f, '28tage', false);
  von := (zr->>'von')::date; bis := (zr->>'bis')::date; vv := (zr->>'vor_von')::date; vb := (zr->>'vor_bis')::date;
  laenge := (zr->>'tage')::integer;
  -- Kanal: Plattform-Schlüssel oder 'k<kanal_id>' (ein Account dieses Talents) (Stefan 18.10.2026)
  kanal := talents_kanal_filter(f->>'kanal', ARRAY(SELECT k.id FROM talent_kanaele k WHERE k.talent_id = t.id));
  kids := ARRAY(SELECT k.id FROM talent_kanaele k WHERE k.talent_id = t.id AND talents_kanal_passt(kanal, k.plattform, k.id) ORDER BY k.id);
  -- Migration 65 (Stefan 20.10.2026): manuelle Daten fließen ein (Filter manuell = '0' nimmt sie heraus), doppelte Daten zählen nie doppelt (talents_zahlen)
  mz := talents_manuell_filter(f);
  SELECT * INTO sj FROM talents_zahlen(kids, von, bis, ARRAY[t.id], kanal, mz);
  SELECT * INTO sv FROM talents_zahlen(kids, vv, vb, ARRAY[t.id], kanal, mz);

  -- Verlauf je Tag (Summe der Kanäle; Tage ohne Zahlen = null)
  SELECT jsonb_build_object(
      'tage', coalesce(jsonb_agg(jsonb_build_object('tag', to_char(g.g, 'YYYY-MM-DD'), 'datum', to_char(g.g, 'DD.MM.'),
        'reichweite', d.r, 'aufrufe', d.a, 'interaktionen', d.i, 'follower', d.f) ORDER BY g.g), '[]'::jsonb),
      'max', jsonb_build_object('reichweite', max(d.r), 'aufrufe', max(d.a), 'interaktionen', max(d.i), 'follower', max(d.f)),
      'kennzahl', CASE WHEN count(d.r) > 0 THEN 'reichweite' WHEN count(d.a) > 0 THEN 'aufrufe' WHEN count(d.i) > 0 THEN 'interaktionen' END,
      'tage_mit_zahlen', count(d.tag), 'hat_daten', count(d.tag) > 0)
    INTO verlauf
  FROM generate_series(von, bis, interval '1 day') AS g(g)
  LEFT JOIN (SELECT kt.tag, sum(talents_zahl(kt.werte->'reach')) AS r, sum(talents_aufrufe(kt.werte)) AS a, sum(talents_interaktionen(kt.werte)) AS i,
                    sum(talents_zahl(kt.werte->'followers_count')) AS f
             FROM talent_kanal_tage kt WHERE kt.kanal_id = ANY (kids) AND kt.tag BETWEEN von AND bis GROUP BY kt.tag) d ON d.tag = g.g::date;

  -- Beste Beiträge im Zeitraum (ohne Storys): Reichweite, dann Aufrufe, dann Interaktionen
  SELECT coalesce(jsonb_agg(talents_beitrag_json(x.id) ORDER BY x.o), '[]'::jsonb) INTO beste
  FROM (SELECT b.id, row_number() OVER (ORDER BY talents_zahl(b.werte->'reach') DESC NULLS LAST, talents_aufrufe(b.werte) DESC NULLS LAST,
                                                 talents_interaktionen(b.werte) DESC NULLS LAST, b.erstellt DESC NULLS LAST, b.id DESC) AS o
        FROM talent_beitraege b
        WHERE b.kanal_id = ANY (kids) AND talents_beitrag_art(b.art, b.produkt_art) <> 'story'
          AND talents_tag(coalesce(b.erstellt, b.erfasst_am)) BETWEEN von AND bis) x
  WHERE x.o <= 6;

  -- Migration 77 (Stefan 21.10.2026): Filter zielgruppe = 'alle' liefert alle Einträge je Gruppe (Talent-Profil, eigene Seite „Alle anzeigen“), sonst höchstens 10
  zg := talents_zielgruppe_max(kids, CASE WHEN f->>'zielgruppe' = 'alle' THEN NULL ELSE 10 END);
  SELECT count(*) FILTER (WHERE k.status = 'verbunden')::integer, count(*)::integer, count(*) FILTER (WHERE k.status = 'abgelaufen')::integer,
         coalesce(bool_or(k.plattform = 'instagram' AND k.status <> 'offen'), false)
    INTO n_verb, n_alle, n_ab, ig
  FROM talent_kanaele k WHERE k.id = ANY (kids);
  hat_tage := EXISTS (SELECT 1 FROM talent_kanal_tage kt WHERE kt.kanal_id = ANY (kids));
  SELECT max(kt.tag) INTO stand FROM talent_kanal_tage kt WHERE kt.kanal_id = ANY (kids);
  SELECT count(*)::integer INTO n_beitraege FROM talent_beitraege b WHERE b.kanal_id = ANY (kids);

  -- Zahlen ohne Verbindung: Ersatz für fehlende Kennzahlen (gleiche Regel wie talents_baustein_kennzahlen) (Stefan 18.10.2026)
  man := talents_manuell_konto(t.id, talents_bericht_plattformen(t.id, kanal), von, bis);
  kz := jsonb_build_array(
      jsonb_build_object('schluessel', 'follower', 'name', 'Follower') || talents_wert(sj.follower)
        || jsonb_build_object('zuwachs', jsonb_build_object('wert', sj.follower_zuwachs, 'text', talents_vorzeichen_text(sj.follower_zuwachs)),
             'zusatz', CASE WHEN sj.follower_zuwachs IS NOT NULL THEN talents_vorzeichen_text(sj.follower_zuwachs) || ' im Zeitraum' END),
      jsonb_build_object('schluessel', 'reichweite', 'name', 'Reichweite') || talents_kennzahl(sj.reichweite, sv.reichweite, sj.tage, sv.tage, laenge),
      jsonb_build_object('schluessel', 'aufrufe', 'name', 'Aufrufe') || talents_kennzahl(sj.aufrufe, sv.aufrufe, sj.tage, sv.tage, laenge),
      jsonb_build_object('schluessel', 'interaktionen', 'name', 'Interaktionen') || talents_kennzahl(sj.interaktionen, sv.interaktionen, sj.tage, sv.tage, laenge));
  -- Migration 65: manuelle Werte sind in sj/sv schon enthalten (ohne Doppelzählung); kein Ersatz mehr, nur Kennzeichnung
  SELECT jsonb_agg(e || jsonb_build_object('manuell', coalesce(sj.manuell_anzahl, 0) > 0, 'quelle_text', CASE WHEN sj.manuell_anzahl > 0 THEN sj.manuell_text END) ORDER BY o) INTO kx
  FROM jsonb_array_elements(kz) WITH ORDINALITY AS a(e, o);
  plattf := ARRAY(SELECT DISTINCT k.plattform FROM talent_kanaele k WHERE k.id = ANY (kids) AND k.plattform <> 'instagram'
                  AND (k.status <> 'offen' OR EXISTS (SELECT 1 FROM talent_kanal_tage kt WHERE kt.kanal_id = k.id)));

  -- Hinweise bei fehlenden Daten
  IF t.status = 'archiviert' THEN
    hinweise := hinweise || 'Das Talent liegt im Papierkorb. Es werden keine neuen Zahlen abgerufen.'::text;
  END IF;
  IF n_verb = 0 AND n_ab = 0 AND NOT hat_tage THEN
    hinweise := hinweise || 'Noch kein Kanal verbunden. Sobald das Talent die Einladung annimmt, holt Ally jede Nacht die Zahlen.'::text;
  ELSIF NOT hat_tage THEN
    hinweise := hinweise || 'Noch keine Zahlen – der erste Abruf läuft nachts.'::text;
  ELSIF NOT (verlauf->>'hat_daten')::boolean THEN
    hinweise := hinweise || 'Für diesen Zeitraum liegen keine Zahlen vor.'::text;
  END IF;
  IF n_ab > 0 THEN
    hinweise := hinweise || ('Die Verbindung ist abgelaufen. Neue Zahlen gibt es erst, wenn sich das Talent neu anmeldet '
      || '(neuer Einladungslink im Talent-Profil über das Zahnrad unter „Accounts und Verbindungen“).')::text;
  END IF;

  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_verwalten', verw,
    'talent', jsonb_build_object('id', t.id, 'anzeigename', talent_listenname(t.id), 'name', t.name, 'kuenstlername', t.kuenstlername,
      'status', t.status, 'archiviert', t.status = 'archiviert',
      'zustaendig', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.matrix_user_id, 'name', p.name) ORDER BY lower(p.name)), '[]'::jsonb)
                     FROM talent_personen tp JOIN ally_personen p ON p.matrix_user_id = tp.matrix_user_id WHERE tp.talent_id = t.id)),
    'kanaele', (SELECT coalesce(jsonb_agg(talents_kanal_json(k.id) ORDER BY array_position(talents_plattformen(), k.plattform), k.extern_id IS NULL, lower(coalesce(k.extern_name, '')) COLLATE "C", k.id), '[]'::jsonb)
                FROM talent_kanaele k WHERE k.talent_id = t.id),
    'filter', jsonb_build_object('zeitraum', zr->>'schluessel', 'von', CASE WHEN zr->>'schluessel' = 'frei' THEN zr->>'von' ELSE '' END,
      'bis', CASE WHEN zr->>'schluessel' = 'frei' THEN zr->>'bis' ELSE '' END, 'kanal', kanal, 'manuell', CASE WHEN mz THEN '1' ELSE '0' END),
    'zeitraum', zr,
    -- je Account ein Eintrag, bei mehreren Accounts einer Plattform zusätzlich "… (alle Accounts)" (Stefan 18.10.2026)
    'kanal_auswahl', talents_kanal_auswahl(ARRAY(SELECT k.id FROM talent_kanaele k WHERE k.talent_id = t.id)),
    'kennzahlen', kx,
    'verlauf', verlauf,
    'beste_beitraege', beste,
    'beste_hinweis', CASE WHEN jsonb_array_length(beste) = 0 THEN 'Keine Beiträge in diesem Zeitraum.' END,
    'anzahl_beitraege', n_beitraege,
    'zielgruppe', zg,
    'zielgruppe_hinweis', CASE WHEN jsonb_array_length(zg) = 0 THEN 'Die Zielgruppe zeigt Instagram erst ab 100 Followern.' END,
    'datenstand', jsonb_build_object('tag', to_char(stand, 'YYYY-MM-DD'), 'text', CASE WHEN stand IS NOT NULL THEN 'Zahlen bis ' || to_char(stand, 'DD.MM.YYYY') ELSE 'Noch keine Zahlen' END),
    'hinweis_verzoegerung', CASE WHEN ig THEN talents_hinweis_verzoegerung() END,
    'warnungen', talents_warnzeichen(t.id, nullif(kanal, '')),
    'hinweise', to_jsonb(hinweise) || (SELECT coalesce(jsonb_agg(talents_plattform_hinweis(p) ORDER BY array_position(talents_plattformen(), p)), '[]'::jsonb) FROM unnest(plattf) p),
    'zeitraeume', talents_zeitraeume(false),
    -- Zahlen ohne Verbindung auf der Talent-Seite; YouTube-Summen von Ally berechnet (Stefan 18.10.2026)
    -- Migration 65: zaehlen = Filter „Manuelle Daten einbeziehen“, gezaehlt = Anzahl manueller Werte in den Summen, doppelt_offen = offene doppelte Daten
    'manuell', jsonb_build_object('zaehlen', mz, 'gezaehlt', coalesce(sj.manuell_anzahl, 0), 'gezaehlt_text', sj.manuell_text,
      'doppelt_offen', talents_doppelt_offen_anzahl(t.id),
      'anzahl_offen', (SELECT count(*)::integer FROM talent_manuell_vorschlaege v WHERE v.talent_id = t.id AND v.status = 'offen'),
      'link', '/webhook/web?ansicht=talents&talent=' || t.id || '&b=zahlen', 'werte', man,
      -- Instagram-Kanal (Broadcast Channel), eigene Zeilen, getrennt vom Konto (Stefan 19.10.2026)
      'kanal', talents_manuell_kanal(t.id, von, bis)),
    'abgeleitet', 'youtube' = ANY (plattf),
    'abgeleitet_text', CASE WHEN 'youtube' = ANY (plattf) THEN 'Von Ally aus den YouTube-Daten berechnet, nicht von YouTube.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_talent_loeschen(p_talent_id integer, p_anlass text, p_user text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  dateien jsonb; ablage jsonb; ordner text; ki jsonb; n_wid integer; n_dat integer; n_ber integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM talents WHERE id = p_talent_id FOR UPDATE) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekanntes Talent.');
  END IF;
  -- Speicherort von Ally (SPEICHER 1, Bereich ally): Berichte, Mediakits, Originaldateien der Zahlen ohne Verbindung
  SELECT coalesce(jsonb_agg(DISTINCT x.p), '[]'::jsonb) INTO dateien FROM (
    SELECT b.pfad AS p FROM talent_berichte b WHERE p_talent_id = ANY (b.talent_ids) AND nullif(b.pfad, '') IS NOT NULL
    UNION SELECT v.datei_pfad FROM talent_manuell_vorschlaege v WHERE v.talent_id = p_talent_id AND nullif(v.datei_pfad, '') IS NOT NULL) x;
  -- Ablage (Migration 49), vor dem Löschen lesen (ON DELETE CASCADE)
  SELECT coalesce(jsonb_agg(jsonb_build_object('dienst', a.dienst, 'pfad', a.pfad, 'extern_id', a.extern_id) ORDER BY a.id), '[]'::jsonb) INTO ablage
  FROM talent_ablage_dateien a WHERE a.talent_id = p_talent_id;
  ordner := talents_bericht_ordner(p_talent_id);
  IF ordner !~ ('^Talents/[A-Za-z0-9._-]+_ID-' || p_talent_id || '$') THEN ordner := NULL; END IF;
  INSERT INTO talent_loesch_dateien (talent_id, dienst, pfad, quelle, anlass)
  SELECT p_talent_id, 'ally', p #>> '{}', CASE WHEN (p #>> '{}') ~ '/Zahlen-Eingang/' THEN 'zahlen_eingang' ELSE 'bericht' END, p_anlass
  FROM jsonb_array_elements(dateien) p;
  INSERT INTO talent_loesch_dateien (talent_id, dienst, pfad, extern_id, quelle, anlass)
  SELECT p_talent_id, a->>'dienst', coalesce(a->>'pfad', ''), a->>'extern_id', 'ablage', p_anlass FROM jsonb_array_elements(ablage) a
  WHERE (coalesce(a->>'pfad', '') <> '' OR a->>'extern_id' IS NOT NULL)
    AND NOT (a->>'dienst' = 'ally' AND dateien ? coalesce(a->>'pfad', ''));
  IF ordner IS NOT NULL THEN
    INSERT INTO talent_loesch_dateien (talent_id, dienst, pfad, ordner, quelle, anlass) VALUES (p_talent_id, 'ally', ordner, true, 'ordner', p_anlass);
  END IF;
  SELECT count(*)::integer INTO n_dat FROM talent_loesch_dateien WHERE talent_id = p_talent_id AND erledigt_am IS NULL;
  -- Ordner-Kennungen in Cloud-Speicherorten vergessen (die leeren Ordner selbst bleiben dort)
  DELETE FROM talent_ablage_ordner WHERE schluessel = 'talent:' || p_talent_id OR schluessel LIKE 'talent:' || p_talent_id || ':%';
  DELETE FROM talent_berichte WHERE p_talent_id = ANY (talent_ids);
  GET DIAGNOSTICS n_ber = ROW_COUNT;
  SELECT count(*)::integer INTO n_wid FROM talent_kanaele k WHERE k.talent_id = p_talent_id AND talents_widerruf_vormerken(k.id, 'talent_geloescht', p_user);
  ki := talents_ki_talent_vergessen(p_talent_id);
  DELETE FROM talents WHERE id = p_talent_id;
  RETURN jsonb_build_object('ok', true, 'talent_id', p_talent_id, 'dateien', dateien, 'ordner', ordner, 'ablage_dateien', ablage,
    'berichte_geloescht', n_ber, 'dateien_vorgemerkt', n_dat, 'widerrufe_vorgemerkt', n_wid, 'ki_anfragen', coalesce((ki->>'anfragen')::integer, 0));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_talent_stand(p_talent_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('verbunden', x.verb, 'bald_ab', x.bald, 'abgelaufen', x.abg, 'getrennt', x.abg OR x.getr,
      'einladung_offen', x.ph AND x.gueltig, 'einladung_abgelaufen', x.ph AND NOT x.gueltig,
      'link_noetig', t.status = 'aktiv' AND NOT x.gueltig AND (x.abg OR x.ph),
      'text', CASE WHEN t.status = 'archiviert' THEN 'Archiviert' WHEN x.abg THEN 'Verbindung abgelaufen' WHEN x.bald THEN 'Verbindung läuft bald ab'
                   WHEN x.ph AND x.gueltig THEN 'Einladung offen' WHEN x.ph THEN 'Einladung abgelaufen' WHEN x.verb THEN 'Verbunden'
                   WHEN x.getr THEN 'Getrennt' ELSE 'Ohne Kanal' END,
      'warnung', t.status = 'aktiv' AND (x.abg OR x.bald OR (x.ph AND NOT x.gueltig)))
  FROM talents t
  CROSS JOIN LATERAL (SELECT
      EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = t.id AND k.status = 'verbunden') AS verb,
      EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = t.id AND k.status = 'verbunden' AND k.gueltig_bis < now() + interval '7 days') AS bald,
      EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = t.id AND k.status = 'abgelaufen') AS abg,
      EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = t.id AND k.status = 'getrennt'
              AND NOT EXISTS (SELECT 1 FROM talent_kanaele k2 WHERE k2.talent_id = t.id AND k2.plattform = k.plattform AND k2.status IN ('verbunden', 'abgelaufen'))) AS getr,
      EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = t.id AND k.extern_id IS NULL AND k.status = 'offen') AS ph,
      EXISTS (SELECT 1 FROM talent_einladungen e WHERE e.talent_id = t.id AND e.widerrufen_am IS NULL AND e.gueltig_bis > now()) AS gueltig) x
  WHERE t.id = p_talent_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_text_json(p_text_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('text_id', x.id, 'art', x.art,
    'art_name', CASE x.art WHEN 'mediakit' THEN 'Mediakit-Text' WHEN 'kampagne_zusammenfassung' THEN 'Zusammenfassung für den Kampagnenbericht' ELSE 'Antwort an eine Marke' END,
    'talent_id', x.talent_id, 'talent_name', talent_anzeigename(x.talent_id), 'kampagne_id', x.kampagne_id, 'anfrage_id', x.anfrage_id,
    'titel', x.titel, 'eingabe', x.eingabe, 'text', x.text, 'hinweise', x.hinweise, 'status', x.status, 'laeuft', x.status = 'wird_erstellt',
    'status_text', CASE x.status WHEN 'wird_erstellt' THEN talents_ki_laeuft_text() WHEN 'fehler' THEN coalesce(x.fehler, 'Konnte nicht erstellt werden.')
                                 ELSE CASE WHEN x.bearbeitet THEN 'Entwurf, bearbeitet' ELSE 'Entwurf der KI, bitte prüfen' END END,
    'erstellt', talents_datum(x.erstellt_am), 'geaendert', talents_datum(x.geaendert_am),
    'als_mail_moeglich', x.art = 'antwort_marke' AND x.status = 'entwurf')
  FROM talent_ki_texte x WHERE x.id = p_text_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_text_sauber(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT regexp_replace(regexp_replace(regexp_replace(coalesce(p, ''),
    '(access_token|client_secret|fb_exchange_token|input_token|code)=[^&[:space:]"'']+', '\1=***', 'gi'),
    'Bearer[[:space:]]+[A-Za-z0-9._|-]+', 'Bearer ***', 'gi'),
    '(EAA|IGAA|IGQV)[A-Za-z0-9_|-]{16,}', '***', 'g')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_texte_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  tid integer := CASE WHEN d->>'talent_id' ~ '^[0-9]{1,9}$' THEN (d->>'talent_id')::integer END;
  kid integer := CASE WHEN d->>'kampagne_id' ~ '^[0-9]{1,9}$' THEN (d->>'kampagne_id')::integer END;
  xid integer := CASE WHEN d->>'text_id' ~ '^[0-9]{1,9}$' THEN (d->>'text_id')::integer END;
  s jsonb;
  u text;
  f text;
  i integer;
  art text := coalesce(d->>'art', '');
BEGIN
  IF xid IS NOT NULL THEN
    tid := (SELECT x.talent_id FROM talent_ki_texte x WHERE x.id = xid);
  END IF;
  s := talents_ki_sitzung(p_token, tid);
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  u := s->>'u';
  IF p_aktion = 'erstellen' THEN
    IF art NOT IN ('mediakit', 'kampagne_zusammenfassung', 'antwort_marke') THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte die Art des Textes wählen.');
    END IF;
    IF art = 'mediakit' AND tid IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte ein Talent wählen.');
    END IF;
    IF art = 'kampagne_zusammenfassung' AND (kid IS NULL OR NOT talents_ki_kampagne_sichtbar(u, kid)) THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte eine Kampagne wählen, bei deren Talents du Manager oder Managerin bist.');
    END IF;
    IF art = 'antwort_marke' AND length(btrim(coalesce(d->>'eingabe', ''))) NOT BETWEEN 20 AND 12000 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Bitte die Anfrage der Marke einfügen (mindestens 20 Zeichen).');
    END IF;
    f := talents_ki_start_fehler(tid);
    IF f IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', f);
    END IF;
    INSERT INTO talent_ki_texte (art, talent_id, kampagne_id, titel, eingabe, erstellt_von, geaendert_von)
    VALUES (art, tid, kid, CASE art WHEN 'mediakit' THEN 'Mediakit ' || coalesce(talent_anzeigename(tid), '') WHEN 'kampagne_zusammenfassung' THEN 'Kampagnenbericht' ELSE 'Antwort an eine Marke' END,
            CASE WHEN art = 'antwort_marke' THEN left(btrim(d->>'eingabe'), 12000) END, u, u)
    RETURNING id INTO i;
    UPDATE talent_ki_texte SET ki_auftrag_id = talents_ki_auftrag_anlegen('text', tid, i, u) WHERE id = i;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'text_id', i, 'auftrag_id', (SELECT ki_auftrag_id FROM talent_ki_texte WHERE id = i), 'meldung', talents_ki_laeuft_text());
  END IF;
  IF xid IS NULL OR NOT talents_ki_text_sichtbar(u, xid) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diesen Text gibt es nicht. Bitte die Seite neu laden.');
  END IF;
  IF p_aktion = 'speichern' THEN
    IF (SELECT x.status FROM talent_ki_texte x WHERE x.id = xid) <> 'entwurf' THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Der Text wird noch erstellt oder ist fehlgeschlagen.');
    END IF;
    IF length(btrim(coalesce(d->>'text', ''))) NOT BETWEEN 1 AND 12000 OR length(coalesce(d->>'titel', '')) > 200 THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Text (höchstens 12.000 Zeichen) und Titel (höchstens 200 Zeichen) prüfen.');
    END IF;
    UPDATE talent_ki_texte SET text = btrim(replace(d->>'text', E'\r', '')), titel = coalesce(talents_ki_kurz(d->>'titel', 200), titel), bearbeitet = true,
      hinweise = '[]'::jsonb, geaendert_am = now(), geaendert_von = u WHERE id = xid;
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Text gespeichert.');
  ELSIF p_aktion = 'loeschen' THEN
    -- Migration 130: in den Papierkorb (ein Text, der gerade erstellt wird, bleibt)
    IF (SELECT x.status FROM talent_ki_texte x WHERE x.id = xid) = 'wird_erstellt' THEN
      RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Der Text wird gerade erstellt. Bitte warten, bis er fertig ist.');
    END IF;
    PERFORM talents_profil_pk_legen('text', xid, u);
    RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'meldung', 'Text liegt jetzt im Papierkorb. Im Papierkorb kannst du ihn wiederherstellen.');
  END IF;
  RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Unbekannte Aktion.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_texte_daten(p_token text, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  tid integer := CASE WHEN f->>'talent_id' ~ '^[0-9]{1,9}$' THEN (f->>'talent_id')::integer END;
  xid integer := CASE WHEN f->>'text_id' ~ '^[0-9]{1,9}$' THEN (f->>'text_id')::integer END;
  seite integer := CASE WHEN f->>'seite' ~ '^[0-9]{1,4}$' THEN greatest(1, (f->>'seite')::integer) ELSE 1 END;
  s jsonb := talents_ki_sitzung(p_token, tid);
  u text;
  n integer;
BEGIN
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  u := s->>'u';
  SELECT count(*) INTO n FROM talent_ki_texte x WHERE (tid IS NULL OR x.talent_id = tid) AND talents_ki_text_sichtbar(u, x.id);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'talent_id', tid, 'talent_name', talent_anzeigename(tid),
    'seite', seite, 'seiten', greatest(1, ceil(n::numeric / 10)::integer),
    'texte', (SELECT coalesce(jsonb_agg(jsonb_build_object('text_id', x.id, 'titel', coalesce(nullif(x.titel, ''), 'Ohne Titel'),
                'art_name', talents_text_json(x.id)->>'art_name', 'talent_name', talent_anzeigename(x.talent_id), 'status_text', talents_text_json(x.id)->>'status_text',
                'datum', talents_datum(x.geaendert_am)) ORDER BY x.id DESC), '[]'::jsonb)
              FROM (SELECT x.* FROM talent_ki_texte x WHERE (tid IS NULL OR x.talent_id = tid) AND talents_ki_text_sichtbar(u, x.id)
                    ORDER BY x.id DESC OFFSET (seite - 1) * 10 LIMIT 10) x),
    'text', CASE WHEN xid IS NOT NULL AND talents_ki_text_sichtbar(u, xid) THEN talents_text_json(xid) END,
    'arten', jsonb_build_array(jsonb_build_object('wert', 'mediakit', 'name', 'Mediakit-Text', 'braucht', 'talent'),
                               jsonb_build_object('wert', 'kampagne_zusammenfassung', 'name', 'Zusammenfassung für den Kampagnenbericht', 'braucht', 'kampagne'),
                               jsonb_build_object('wert', 'antwort_marke', 'name', 'Antwort an eine Marke', 'braucht', 'anfrage')),
    'kampagnen', CASE WHEN tid IS NOT NULL THEN coalesce(talents_ki_kampagnen('des_talents', jsonb_build_object('talent_id', tid))->'kampagnen', '[]'::jsonb) ELSE '[]'::jsonb END,
    'postfaecher', talents_mail_postfaecher(u),
    'ki_hinweis', talents_ki_start_fehler(tid));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_uebersicht(p_token text, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb;
  u text;
  verw boolean;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  zr jsonb;
  von date; bis date; vv date; vb date; laenge integer;
  kanal text; person text; suche text; sortierung text; seite integer; seiten integer; anzahl integer;
  je_seite constant integer := 10;
  alle jsonb;
  kids_alle integer[];
  sj record; sv record;
  zeilen jsonb;
  n_sichtbar integer;
  n_kanaele integer;
  ig boolean;
  stand date;
  plattf text[];
  mz boolean;
  nutze boolean;
  vr jsonb := '{}'::jsonb;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN
    RETURN c;
  END IF;
  u := c->>'u';
  verw := (c->>'verw')::boolean;

  -- Filter prüfen (ungültige Werte werden still auf den Standard gesetzt; Zeitraum mit Text in zeitraum.fehler)
  zr := talents_zeitraum(f, '28tage', false);
  von := (zr->>'von')::date; bis := (zr->>'bis')::date; vv := (zr->>'vor_von')::date; vb := (zr->>'vor_bis')::date;
  laenge := (zr->>'tage')::integer;
  -- Kanal: Plattform-Schlüssel oder 'k<kanal_id>' (ein Account eines sichtbaren aktiven Talents) (Stefan 18.10.2026)
  kanal := lower(btrim(coalesce(f->>'kanal', '')));
  IF NOT kanal = ANY (talents_plattformen()) THEN
    kanal := talents_kanal_filter(kanal, ARRAY(SELECT k.id FROM talent_kanaele k JOIN talents tx ON tx.id = k.talent_id WHERE tx.status = 'aktiv'
               AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = tx.id AND tp.matrix_user_id = u))));
  END IF;
  -- Migration 66: sehen (Filter nach zuständiger Person) nach „Talents ansehen“, darf_verwalten nach „Talents und Kampagnen verwalten“
  person := CASE WHEN c->>'zugriff' = 'alle' THEN btrim(coalesce(f->>'person', '')) ELSE '' END;
  IF person <> '' AND NOT EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = person) THEN
    person := '';
  END IF;
  suche := left(btrim(regexp_replace(coalesce(f->>'suche', ''), '[[:cntrl:]]', ' ', 'g')), 100);
  sortierung := lower(btrim(coalesce(f->>'sortierung', '')));
  IF sortierung NOT IN ('reichweite', 'veraenderung', 'interaktionen', 'follower_zuwachs') THEN
    sortierung := 'reichweite';
  END IF;
  seite := CASE WHEN btrim(coalesce(f->>'seite', '')) ~ '^[0-9]{1,6}$' THEN greatest(btrim(f->>'seite')::integer, 1) ELSE 1 END;
  -- Migration 65 (Stefan 20.10.2026): Filter „Manuelle Daten einbeziehen“ (Standard an)
  mz := talents_manuell_filter(f);

  -- Migration 138 (Stefan 24.10.2026, 10:38): vorgerechnete Zahlen aus talents_zahlen_vorrat nur in der Standardansicht (Zugriff auf alle Talents, kein Filter
  -- nach Person, Suche oder Kanal, manuelle Daten an). Ein Talent ohne gültigen Vorrat (anderer Zeitraum oder Datenstand) und jede andere Ansicht
  -- rechnen wie bisher live mit talents_zahlen; die Werte sind in beiden Fällen gleich.
  nutze := c->>'zugriff' = 'alle' AND person = '' AND suche = '' AND kanal = '' AND mz;
  IF nutze THEN
    SELECT coalesce(jsonb_object_agg(coalesce(x.talent_id::text, 'summe'), jsonb_build_object('j', x.j, 'v', x.v)), '{}'::jsonb) INTO vr
    FROM talents_zahlen_vorrat_lesen('uebersicht', von, bis, vv, vb) x;
  END IF;

  -- Alle gefilterten aktiven Talents mit Zahlen (Zeitraum und Vorzeitraum)
  WITH t AS (
    SELECT t.id, talent_listenname(t.id) AS anz,
      ARRAY(SELECT k.id FROM talent_kanaele k WHERE k.talent_id = t.id AND talents_kanal_passt(kanal, k.plattform, k.id) ORDER BY k.id) AS kids
    FROM talents t
    WHERE t.status = 'aktiv'
      AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u))
      AND (person = '' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = person))
      AND (kanal = '' OR EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = t.id AND talents_kanal_passt(kanal, k.plattform, k.id))
           OR (mz AND kanal = ANY (talents_plattformen()) AND EXISTS (SELECT 1 FROM talent_manuell_werte mw WHERE mw.talent_id = t.id AND mw.bereich = 'konto' AND mw.plattform = kanal)))
      AND (suche = '' OR position(lower(suche) IN lower(concat_ws(' ', t.name, t.kuenstlername, talent_listenname(t.id),
             (SELECT string_agg(k.extern_name, ' ') FROM talent_kanaele k WHERE k.talent_id = t.id)))) > 0)),
  z AS (
    SELECT t.id, t.anz, t.kids, j.reichweite AS rj, j.aufrufe AS aj, j.interaktionen AS ij, j.tage AS tj, j.follower AS fo, j.follower_zuwachs AS fz, j.manuell_anzahl AS mn,
      v.reichweite AS rv, v.aufrufe AS av, v.interaktionen AS iv, v.tage AS tv,
      CASE WHEN j.tage > 0 AND v.tage > 0 AND j.tage * 2 >= laenge AND v.tage * 2 >= laenge AND v.reichweite > 0 AND j.reichweite IS NOT NULL
           THEN (j.reichweite / j.tage) / (v.reichweite / v.tage) * 100 - 100 END AS pr
    FROM t
    CROSS JOIN LATERAL (SELECT vr->(t.id::text) AS w) q
    CROSS JOIN LATERAL (SELECT x.* FROM jsonb_populate_record(NULL::talents_zahlen_zeile, q.w->'j') x WHERE q.w IS NOT NULL
                        UNION ALL SELECT * FROM talents_zahlen(t.kids, von, bis, ARRAY[t.id], kanal, mz) WHERE q.w IS NULL) j
    CROSS JOIN LATERAL (SELECT x.* FROM jsonb_populate_record(NULL::talents_zahlen_zeile, q.w->'v') x WHERE q.w IS NOT NULL
                        UNION ALL SELECT * FROM talents_zahlen(t.kids, vv, vb, ARRAY[t.id], kanal, mz) WHERE q.w IS NULL) v)
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'anz', z.anz, 'kids', to_jsonb(z.kids), 'mn', z.mn,
      'rj', z.rj, 'aj', z.aj, 'ij', z.ij, 'tj', z.tj, 'fo', z.fo, 'fz', z.fz, 'rv', z.rv, 'av', z.av, 'iv', z.iv, 'tv', z.tv)
      ORDER BY CASE sortierung WHEN 'reichweite' THEN z.rj WHEN 'interaktionen' THEN z.ij WHEN 'follower_zuwachs' THEN z.fz ELSE z.pr END DESC NULLS LAST,
               lower(z.anz), z.id), '[]'::jsonb)
    INTO alle FROM z;

  anzahl := jsonb_array_length(alle);
  seiten := greatest(1, ceil(anzahl / je_seite::numeric)::integer);
  seite := least(seite, seiten);
  kids_alle := ARRAY(SELECT (x #>> '{}')::integer FROM jsonb_array_elements(alle) e, jsonb_array_elements(e->'kids') x);
  -- Migration 138: Summe aus dem Vorrat nur, wenn er für genau diese Talents (alle aktiven) und diesen Datenstand gilt
  IF vr ? 'summe' THEN
    SELECT * INTO sj FROM jsonb_populate_record(NULL::talents_zahlen_zeile, vr->'summe'->'j');
    SELECT * INTO sv FROM jsonb_populate_record(NULL::talents_zahlen_zeile, vr->'summe'->'v');
  ELSE
    SELECT * INTO sj FROM talents_zahlen(kids_alle, von, bis, ARRAY(SELECT (e->>'id')::integer FROM jsonb_array_elements(alle) e), kanal, mz);
    SELECT * INTO sv FROM talents_zahlen(kids_alle, vv, vb, ARRAY(SELECT (e->>'id')::integer FROM jsonb_array_elements(alle) e), kanal, mz);
  END IF;
  SELECT count(*)::integer, coalesce(bool_or(k.plattform = 'instagram'), false) INTO n_kanaele, ig
  FROM talent_kanaele k WHERE k.id = ANY (kids_alle) AND k.status = 'verbunden';
  SELECT max(kt.tag) INTO stand FROM talent_kanal_tage kt WHERE kt.kanal_id = ANY (kids_alle);
  plattf := ARRAY(SELECT DISTINCT k.plattform FROM talent_kanaele k WHERE k.id = ANY (kids_alle) AND k.plattform <> 'instagram'
                  AND (k.status <> 'offen' OR EXISTS (SELECT 1 FROM talent_kanal_tage kt WHERE kt.kanal_id = k.id)));

  -- Zeilen der Seite
  SELECT coalesce(jsonb_agg(jsonb_build_object('platz', e.o, 'talent_id', (e.x->>'id')::integer, 'anzeigename', e.x->>'anz',
      'kanaele', (SELECT coalesce(jsonb_agg(talents_kanal_json(k.id) ORDER BY array_position(talents_plattformen(), k.plattform), k.extern_id IS NULL, lower(coalesce(k.extern_name, '')) COLLATE "C", k.id), '[]'::jsonb)
                  FROM talent_kanaele k WHERE k.talent_id = (e.x->>'id')::integer AND k.status <> 'getrennt' AND talents_kanal_passt(kanal, k.plattform, k.id)),
      -- Migration 65: manuelle Daten sind in den Zahlen enthalten (talents_zahlen, ohne Doppelzählung); kein Ersatz mehr
      'follower', talents_wert((e.x->>'fo')::numeric),
      'follower_zuwachs', jsonb_build_object('wert', (e.x->>'fz')::numeric, 'text', talents_vorzeichen_text((e.x->>'fz')::numeric)),
      'reichweite', talents_kennzahl((e.x->>'rj')::numeric, (e.x->>'rv')::numeric, (e.x->>'tj')::integer, (e.x->>'tv')::integer, laenge),
      'aufrufe', talents_kennzahl((e.x->>'aj')::numeric, (e.x->>'av')::numeric, (e.x->>'tj')::integer, (e.x->>'tv')::integer, laenge),
      'interaktionen', talents_kennzahl((e.x->>'ij')::numeric, (e.x->>'iv')::numeric, (e.x->>'tj')::integer, (e.x->>'tv')::integer, laenge),
      'veraenderung', talents_kennzahl((e.x->>'rj')::numeric, (e.x->>'rv')::numeric, (e.x->>'tj')::integer, (e.x->>'tv')::integer, laenge)->'veraenderung',
      'hat_daten', coalesce((e.x->>'tj')::integer, 0) > 0,
      'warnungen', talents_warnzeichen((e.x->>'id')::integer, nullif(kanal, '')),
      -- offene Zahlen ohne Verbindung (Hinweis "Zahlen prüfen"); YouTube-Anteil = von Ally berechnet (Stefan 18.10.2026)
      'zahlen_offen', (SELECT count(*)::integer FROM talent_manuell_vorschlaege v WHERE v.talent_id = (e.x->>'id')::integer AND v.status = 'offen'),
      -- Migration 65: manuelle Werte in den Zahlen dieser Zeile, offene doppelte Daten
      'manuell', coalesce((e.x->>'mn')::integer, 0) > 0, 'doppelt_offen', talents_doppelt_offen_anzahl((e.x->>'id')::integer),
      'abgeleitet', EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.id IN (SELECT (j #>> '{}')::integer FROM jsonb_array_elements(e.x->'kids') j) AND k.plattform = 'youtube'))
      ORDER BY e.o), '[]'::jsonb)
    INTO zeilen
  FROM jsonb_array_elements(alle) WITH ORDINALITY AS e(x, o)
  WHERE e.o > (seite - 1) * je_seite AND e.o <= seite * je_seite;

  SELECT count(*)::integer INTO n_sichtbar FROM talents t
  WHERE c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u);

  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_verwalten', verw,
    'filter', jsonb_build_object('zeitraum', zr->>'schluessel', 'von', CASE WHEN zr->>'schluessel' = 'frei' THEN zr->>'von' ELSE '' END,
      'bis', CASE WHEN zr->>'schluessel' = 'frei' THEN zr->>'bis' ELSE '' END,
      'kanal', kanal, 'person', person, 'suche', suche, 'sortierung', sortierung, 'seite', seite, 'manuell', CASE WHEN mz THEN '1' ELSE '0' END),
    'zeitraum', zr,
    'summe', jsonb_build_object('talents', anzahl, 'kanaele', n_kanaele, 'manuell', coalesce(sj.manuell_anzahl, 0), 'manuell_text', sj.manuell_text,
      'follower', talents_wert(sj.follower),
      'follower_zuwachs', jsonb_build_object('wert', sj.follower_zuwachs, 'text', talents_vorzeichen_text(sj.follower_zuwachs)),
      'reichweite', talents_kennzahl(sj.reichweite, sv.reichweite, sj.tage, sv.tage, laenge),
      'aufrufe', talents_kennzahl(sj.aufrufe, sv.aufrufe, sj.tage, sv.tage, laenge),
      'interaktionen', talents_kennzahl(sj.interaktionen, sv.interaktionen, sj.tage, sv.tage, laenge)),
    'zeilen', zeilen,
    'anzahl', anzahl, 'seite', seite, 'seiten', seiten, 'je_seite', je_seite,
    'leer_text', CASE WHEN anzahl > 0 THEN NULL
                      WHEN n_sichtbar = 0 AND verw THEN 'Noch keine Talents. Talents lädst du oben mit „Talent einladen“ ein.'
                      WHEN n_sichtbar = 0 THEN 'Dir sind noch keine Talents zugeordnet.'
                      ELSE 'Keine Talents für diesen Filter.' END,
    'datenstand', jsonb_build_object('tag', to_char(stand, 'YYYY-MM-DD'), 'text', CASE WHEN stand IS NOT NULL THEN 'Zahlen bis ' || to_char(stand, 'DD.MM.YYYY') ELSE 'Noch keine Zahlen' END),
    'hinweis_verzoegerung', CASE WHEN ig THEN talents_hinweis_verzoegerung() END,
    -- Auswahl "Talent öffnen": alle sichtbaren Talents (aktive zuerst, alphabetisch; archivierte am Ende)
    'auswahl', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'anzeigename', talent_listenname(t.id), 'archiviert', t.status = 'archiviert')
                  ORDER BY t.status = 'archiviert', lower(talent_listenname(t.id)), t.id), '[]'::jsonb)
                FROM talents t WHERE c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u)),
    -- Filter "zuständige Person": nur bei Zugriff auf alle Talents; Personen, die für mindestens ein aktives Talent zuständig sind
    'personen', CASE WHEN c->>'zugriff' = 'alle' THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.matrix_user_id, 'name', p.name, 'ich', p.matrix_user_id = u) ORDER BY lower(p.name), p.matrix_user_id), '[]'::jsonb)
                  FROM ally_personen p WHERE p.aktiv AND EXISTS (SELECT 1 FROM talent_personen tp JOIN talents tx ON tx.id = tp.talent_id
                                                                 WHERE tp.matrix_user_id = p.matrix_user_id AND tx.status = 'aktiv')) ELSE '[]'::jsonb END,
    -- je Account ein Eintrag, bei mehreren Accounts einer Plattform zusätzlich "… (alle Accounts)" (Stefan 18.10.2026)
    'kanal_auswahl', talents_kanal_auswahl(ARRAY(SELECT k.id FROM talent_kanaele k JOIN talents t ON t.id = k.talent_id WHERE t.status = 'aktiv'
                       AND (c->>'zugriff' = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u)))),
    'sortierungen', '[{"schluessel": "reichweite", "name": "Reichweite"}, {"schluessel": "veraenderung", "name": "Veränderung"},
                      {"schluessel": "interaktionen", "name": "Interaktionen"}, {"schluessel": "follower_zuwachs", "name": "Follower-Zuwachs"}]'::jsonb,
    'zeitraeume', talents_zeitraeume(false),
    -- Hinweise zu den Zahlen der weiteren Plattformen; Summen mit YouTube sind von Ally berechnet (YouTube-Richtlinien III.E.4.h) (Stefan 18.10.2026)
    'hinweise', (SELECT coalesce(jsonb_agg(talents_plattform_hinweis(p) ORDER BY array_position(talents_plattformen(), p)), '[]'::jsonb) FROM unnest(plattf) p),
    'abgeleitet', 'youtube' = ANY (plattf),
    'abgeleitet_text', CASE WHEN 'youtube' = ANY (plattf) THEN 'Von Ally aus den YouTube-Daten berechnet, nicht von YouTube.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ui_kampagne_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb; u text; adm boolean; verw boolean; mgmt boolean;
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  fehler text; m text; k talent_kampagnen%ROWTYPE; kid integer; bid bigint; x text;
  n_marke text; n_name text; n_von date; n_bis date; n_talents integer[]; n_mk text[]; n_ht text[]; n_sw text[];
  anz integer; weg integer; r jsonb; tid integer; st text; b record; fk text;
BEGIN
  -- Kampagnen in der neuen Oberfläche (BA6, Migration 61; Kopie von talents_kampagne_aktion, das ALLY 8 unverändert nutzt). Rollen nach Stefan 20.10.2026:
  -- Management legt Kampagnen für die eigenen Talents an, bearbeitet und löscht die Kampagnen, für die es zuständig ist (nur eigene Talents hinzufügen
  -- oder herausnehmen; löschen nur, wenn alle Talents die eigenen sind), und ordnet Beiträge der eigenen Talents zu. Admin und „Talents verwalten“ wie bisher.
  c := talents_aktion_start(p_token, false);
  IF c ? 'stumm' THEN RETURN c - 'stumm'; END IF;
  IF NOT (c->>'ok')::boolean THEN
    RETURN talents_aktion_ende(p_token, c->>'fehler', NULL, NULL, NULL);
  END IF;
  u := c->>'u'; adm := (c->>'adm')::boolean; verw := coalesce((c->>'verw')::boolean, false); mgmt := talents_planung_management(u);
  x := btrim(coalesce(d->>'id', d->>'kampagne_id', ''));
  IF x ~ '^[0-9]{1,9}$' THEN
    SELECT * INTO k FROM talent_kampagnen WHERE id = x::integer FOR UPDATE;
  END IF;
  BEGIN
    IF NOT verw AND NOT mgmt THEN
      fehler := 'Dafür fehlt dir das Recht „Talents und Kampagnen verwalten“. Rechte vergibt eine Person mit der Rolle Admin.';
    ELSIF p_aktion <> 'kampagne_neu' AND (k.id IS NULL OR NOT verw AND talents_planung_recht(u, k.id) IS NULL) THEN
      fehler := 'Unbekannte Kampagne. Bitte die Seite neu laden.';
    ELSIF NOT verw AND p_aktion = 'kampagne_bearbeiten' AND k.zustaendig IS DISTINCT FROM u THEN
      fehler := 'Das dürfen der Manager oder die Managerin der Kampagne und alle mit dem Recht „Talents und Kampagnen verwalten“ für alle Talents.';

    ELSIF p_aktion IN ('kampagne_neu', 'kampagne_bearbeiten') THEN
      n_marke := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'marke' THEN nullif(btrim(coalesce(d->>'marke', '')), '') ELSE k.marke END;
      n_name := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'name' THEN nullif(btrim(coalesce(d->>'name', '')), '') ELSE k.name END;
      n_von := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'von' THEN talents_datum_lesen(d->>'von') ELSE k.von END;
      n_bis := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'bis' THEN talents_datum_lesen(d->>'bis') ELSE k.bis END;
      n_mk := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'marken_konten' THEN talents_merkmale(coalesce(d->'marken_konten', '[]'), 'marke') ELSE k.marken_konten END;
      n_ht := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'hashtags' THEN talents_merkmale(coalesce(d->'hashtags', '[]'), 'hashtag') ELSE k.hashtags END;
      n_sw := CASE WHEN p_aktion = 'kampagne_neu' OR d ? 'schlagwoerter' THEN talents_merkmale(coalesce(d->'schlagwoerter', '[]'), 'wort') ELSE k.schlagwoerter END;
      IF p_aktion = 'kampagne_neu' OR d ? 'talents' THEN
        n_talents := ARRAY(SELECT DISTINCT x2::integer FROM unnest(talents_liste(d->'talents')) x2 WHERE x2 ~ '^[0-9]{1,9}$');
      END IF;
      IF n_marke IS NULL OR n_name IS NULL THEN
        fehler := 'Bitte Marke und Namen der Kampagne angeben.';
      ELSIF length(n_marke) > 120 OR length(n_name) > 120 OR n_marke ~ '[[:cntrl:]]' OR n_name ~ '[[:cntrl:]]' THEN
        fehler := 'Marke und Name dürfen höchstens 120 Zeichen haben.';
      ELSIF n_von IS NULL OR n_bis IS NULL THEN
        fehler := 'Bitte Beginn und Ende der Kampagne als Datum angeben (TT.MM.JJJJ).';
      ELSIF n_bis < n_von THEN
        fehler := 'Das Ende der Kampagne liegt vor dem Beginn.';
      ELSIF n_bis - n_von > 366 THEN
        fehler := 'Eine Kampagne darf höchstens 366 Tage dauern.';
      ELSIF n_mk IS NULL THEN
        fehler := 'Bitte die Marken-Accounts als @Name angeben (Buchstaben, Ziffern, Punkt, Unterstrich; höchstens 10).';
      ELSIF n_ht IS NULL THEN
        fehler := 'Bitte die Hashtags ohne Leerzeichen angeben, getrennt durch Komma oder Leerzeichen (höchstens 10).';
      ELSIF n_sw IS NULL THEN
        fehler := 'Bitte die Schlagwörter mit Komma trennen (je 2 bis 60 Zeichen, höchstens 10).';
      ELSIF n_talents IS NOT NULL AND cardinality(n_talents) = 0 THEN
        fehler := 'Bitte mindestens ein Talent auswählen.';
      ELSIF n_talents IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(n_talents) t2 WHERE NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = t2
              AND (t.status = 'aktiv' OR EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = t.id)))) THEN
        fehler := 'In der Auswahl ist ein unbekanntes Talent oder eines im Papierkorb. Bitte die Seite neu laden.';
      ELSIF NOT verw AND n_talents IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(n_talents) t2 WHERE NOT coalesce(talent_verwaltbar(u, t2), false)
              AND NOT EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = t2)) THEN
        fehler := 'In der Auswahl ist ein Talent, das dir nicht zugeordnet ist.';
      ELSIF NOT verw AND n_talents IS NOT NULL AND EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND NOT (kt.talent_id = ANY (n_talents))
              AND NOT coalesce(talent_verwaltbar(u, kt.talent_id), false)) THEN
        fehler := 'Talents anderer Personen lassen sich hier nicht herausnehmen.';
      ELSIF EXISTS (SELECT 1 FROM talent_kampagnen k2 WHERE lower(k2.marke) = lower(n_marke) AND lower(k2.name) = lower(n_name) AND k2.id IS DISTINCT FROM k.id) THEN
        fehler := 'Eine Kampagne mit diesem Namen gibt es für diese Marke schon.';
      ELSIF p_aktion = 'kampagne_neu' THEN
        INSERT INTO talent_kampagnen (marke, name, von, bis, marken_konten, hashtags, schlagwoerter, erstellt_von, geaendert_von)
        VALUES (n_marke, n_name, n_von, n_bis, n_mk, n_ht, n_sw, u, u) RETURNING id INTO kid;
        INSERT INTO talent_kampagne_talents (kampagne_id, talent_id) SELECT kid, t2 FROM unnest(n_talents) t2;
        r := talents_kampagnen_vorschlaege(kid);
        m := 'Kampagne angelegt.' || CASE WHEN (r->>'neu')::integer = 1 THEN ' Ally schlägt 1 passenden Beitrag vor.'
                                          WHEN (r->>'neu')::integer > 1 THEN ' Ally schlägt ' || (r->>'neu') || ' passende Beiträge vor.' ELSE '' END;
      ELSE
        kid := k.id;
        UPDATE talent_kampagnen SET marke = n_marke, name = n_name, von = n_von, bis = n_bis, marken_konten = n_mk, hashtags = n_ht, schlagwoerter = n_sw,
          geaendert_am = now(), geaendert_von = u WHERE id = kid;
        weg := 0;
        IF n_talents IS NOT NULL THEN
          -- Talent nicht mehr dabei: seine Zuordnungen in dieser Kampagne entfallen
          DELETE FROM talent_kampagne_beitraege kb USING talent_beitraege bb, talent_kanaele c2
          WHERE kb.kampagne_id = kid AND bb.id = kb.beitrag_id AND c2.id = bb.kanal_id AND NOT (c2.talent_id = ANY (n_talents)) AND kb.status = 'bestaetigt';
          GET DIAGNOSTICS weg = ROW_COUNT;
          DELETE FROM talent_kampagne_beitraege kb USING talent_beitraege bb, talent_kanaele c2
          WHERE kb.kampagne_id = kid AND bb.id = kb.beitrag_id AND c2.id = bb.kanal_id AND NOT (c2.talent_id = ANY (n_talents));
          DELETE FROM talent_kampagne_talents WHERE kampagne_id = kid AND NOT (talent_id = ANY (n_talents));
          INSERT INTO talent_kampagne_talents (kampagne_id, talent_id) SELECT kid, t2 FROM unnest(n_talents) t2 ON CONFLICT DO NOTHING;
        END IF;
        r := talents_kampagnen_vorschlaege(kid);
        m := 'Kampagne gespeichert.' || CASE WHEN weg > 0 THEN ' ' || weg || CASE WHEN weg = 1 THEN ' Zuordnung' ELSE ' Zuordnungen' END
                                               || ' von Talents, die nicht mehr dabei sind, wurden entfernt.' ELSE '' END
          || CASE WHEN (r->>'neu')::integer > 0 THEN ' Neue Vorschläge: ' || (r->>'neu') || '.' ELSE '' END;
      END IF;

    ELSIF p_aktion = 'kampagne_loeschen' THEN
      IF NOT adm AND NOT (mgmt AND k.zustaendig = u AND NOT EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id
                                                                     AND NOT coalesce(talent_verwaltbar(u, kt.talent_id), false))) THEN
        fehler := 'Kampagnen in den Papierkorb legen können Admins sowie der Manager oder die Managerin der Kampagne, wenn ihm oder ihr alle Talents der Kampagne zugeordnet sind.';
      ELSE
        -- Migration 131: in den Papierkorb, mit allem, was zur Kampagne gehört (zurück und endgültig: talents_kampagnen_papierkorb)
        PERFORM talents_kampagnen_pk_legen('kampagne', k.id, u);
        m := 'Die Kampagne „' || k.name || '“ liegt jetzt im Papierkorb, mit Deliverables, Entwürfen, Aufgaben und eigenen Erinnerungen. Ally erinnert dafür nicht mehr. Im Papierkorb kannst du sie wiederherstellen oder endgültig löschen.';
      END IF;

    ELSIF p_aktion IN ('beitrag_bestaetigen', 'beitrag_zuordnen', 'beitrag_entfernen') THEN
      kid := k.id;
      IF btrim(coalesce(d->>'beitrag_id', '')) ~ '^[0-9]{1,15}$' THEN
        SELECT bb.id, bb.abgeschlossen, talents_beitrag_art(bb.art, bb.produkt_art) AS art, c2.talent_id INTO b
        FROM talent_beitraege bb JOIN talent_kanaele c2 ON c2.id = bb.kanal_id WHERE bb.id = btrim(d->>'beitrag_id')::bigint;
      END IF;
      SELECT kb.status INTO st FROM talent_kampagne_beitraege kb WHERE kb.kampagne_id = k.id AND kb.beitrag_id = b.id;
      IF b.id IS NULL OR NOT EXISTS (SELECT 1 FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND kt.talent_id = b.talent_id)
         OR NOT verw AND NOT coalesce(talent_verwaltbar(u, b.talent_id), false) THEN
        fehler := 'Dieser Beitrag gehört zu keinem Talent der Kampagne. Bitte die Seite neu laden.';
      ELSIF p_aktion = 'beitrag_entfernen' THEN
        INSERT INTO talent_kampagne_beitraege (kampagne_id, beitrag_id, status, quelle, geaendert_am, geaendert_von)
        VALUES (k.id, b.id, 'entfernt', 'manuell', now(), u)
        ON CONFLICT (kampagne_id, beitrag_id) DO UPDATE SET status = 'entfernt', geaendert_am = now(), geaendert_von = u;
        m := 'Beitrag aus der Kampagne entfernt. Ally schlägt ihn nicht noch einmal vor.';
      ELSE
        INSERT INTO talent_kampagne_beitraege (kampagne_id, beitrag_id, status, quelle, geaendert_am, geaendert_von)
        VALUES (k.id, b.id, 'bestaetigt', 'manuell', now(), u)
        ON CONFLICT (kampagne_id, beitrag_id) DO UPDATE SET status = 'bestaetigt', geaendert_am = now(), geaendert_von = u;
        -- Kampagne läuft noch: Beitrag weiter verfolgen
        IF b.abgeschlossen AND b.art <> 'story' AND k.bis >= talents_heute() THEN
          UPDATE talent_beitraege SET abgeschlossen = false WHERE id = b.id;
        END IF;
        m := CASE WHEN st = 'bestaetigt' THEN 'Der Beitrag ist der Kampagne schon zugeordnet.' ELSE 'Beitrag der Kampagne zugeordnet.' END
          || CASE WHEN b.abgeschlossen AND b.art <> 'story' AND k.bis >= talents_heute() THEN ' Er wird bis zum Kampagnenende weiter verfolgt.' ELSE '' END;
      END IF;
      bid := b.id;

    ELSIF p_aktion = 'vorschlaege_bestaetigen' THEN
      kid := k.id;
      UPDATE talent_kampagne_beitraege SET status = 'bestaetigt', geaendert_am = now(), geaendert_von = u WHERE kampagne_id = k.id AND status = 'vorschlag'
        AND (verw OR EXISTS (SELECT 1 FROM talent_beitraege bb JOIN talent_kanaele c2 ON c2.id = bb.kanal_id
                             WHERE bb.id = talent_kampagne_beitraege.beitrag_id AND coalesce(talent_verwaltbar(u, c2.talent_id), false)));
      GET DIAGNOSTICS anz = ROW_COUNT;
      IF anz = 0 THEN
        fehler := 'Es gibt keine offenen Vorschläge.';
      ELSE
        m := CASE WHEN anz = 1 THEN '1 Vorschlag bestätigt.' ELSE anz || ' Vorschläge bestätigt.' END;
      END IF;

    ELSE
      fehler := 'Unbekannte Aktion.';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Talent mit Deliverables oder Aufgaben (Migration 61) lässt sich nicht herausnehmen: verständliche Meldung statt der Datenbank-Meldung (Stefan 20.10.2026)
    GET STACKED DIAGNOSTICS fk := CONSTRAINT_NAME;
    fehler := CASE WHEN SQLSTATE = '23503' AND fk IN ('talent_deliverables_kampagne_talent', 'talent_aufgaben_kampagne_talent')
                   THEN 'Talents mit Deliverables oder Aufgaben in dieser Kampagne lassen sich nicht herausnehmen. Bitte zuerst deren Deliverables und Aufgaben löschen.'
                   ELSE 'Die Aktion konnte nicht ausgeführt werden. Bitte erneut versuchen. (' || left(SQLERRM, 200) || ')' END;
    kid := k.id;
  END;
  RETURN talents_aktion_ende(p_token, fehler, m, NULL, jsonb_build_object('kampagne_id', CASE WHEN fehler IS NULL AND p_aktion = 'kampagne_loeschen' THEN NULL ELSE coalesce(kid, k.id) END,
    'beitrag_id', bid));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ui_kampagne_zuordnen(p_token text, p_kampagne_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; k talent_kampagnen%ROWTYPE;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  ta integer; be text := CASE WHEN f->>'bereich' = 'alle' THEN 'alle' ELSE 'zeitraum' END;
  anz integer; seite integer; je integer := 10; verw boolean; u text;
BEGIN
  -- Beiträge zuordnen in der neuen Oberfläche (BA6, Migration 61; Kopie von talents_kampagne_zuordnen, das ALLY 8 unverändert nutzt):
  -- zusätzlich Management für die eigenen Talents einer Kampagne (Stefan 20.10.2026); Talents anderer Personen erscheinen nicht.
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  u := c->>'u'; verw := (c->>'verw')::boolean;
  IF NOT verw AND NOT talents_planung_management(u) THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Beiträge zuordnen darf, wer das Recht „Talents und Kampagnen verwalten“ hat.');
  END IF;
  SELECT * INTO k FROM talent_kampagnen x WHERE x.id = p_kampagne_id;
  IF k.id IS NULL OR NOT verw AND talents_planung_recht(u, k.id) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Diese Kampagne gibt es nicht.');
  END IF;
  ta := (SELECT kt.talent_id FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id AND (verw OR coalesce(talent_verwaltbar(u, kt.talent_id), false))
         ORDER BY kt.talent_id::text = btrim(coalesce(f->>'talent', '')) DESC, lower(talent_listenname(kt.talent_id)) COLLATE "C", kt.talent_id LIMIT 1);
  SELECT count(*)::integer INTO anz FROM talent_beitraege b JOIN talent_kanaele c2 ON c2.id = b.kanal_id
  WHERE c2.talent_id = ta AND (be = 'alle' OR talents_tag(coalesce(b.erstellt, b.erfasst_am)) BETWEEN k.von AND k.bis);
  seite := talents_seite_nr(f->>'seite', anz, je);
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_verwalten', true,
    'kampagne', talents_kampagne_kurz(k.id, CASE WHEN verw THEN NULL ELSE ARRAY(SELECT kt.talent_id FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id
      AND coalesce(talent_verwaltbar(u, kt.talent_id), false)) END),
    'filter', jsonb_build_object('talent', coalesce(ta::text, ''), 'bereich', be, 'seite', seite),
    'talent_auswahl', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', kt.talent_id, 'anzeigename', talent_listenname(kt.talent_id),
        'anzahl_zugeordnet', (SELECT count(*) FROM talent_kampagne_beitraege kb JOIN talent_beitraege b ON b.id = kb.beitrag_id JOIN talent_kanaele c2 ON c2.id = b.kanal_id
                              WHERE kb.kampagne_id = k.id AND kb.status = 'bestaetigt' AND c2.talent_id = kt.talent_id))
        ORDER BY lower(talent_listenname(kt.talent_id)) COLLATE "C", kt.talent_id), '[]'::jsonb) FROM talent_kampagne_talents kt WHERE kt.kampagne_id = k.id
        AND (verw OR coalesce(talent_verwaltbar(u, kt.talent_id), false))),
    'bereich_auswahl', '[{"schluessel":"zeitraum","name":"Im Kampagnenzeitraum"},{"schluessel":"alle","name":"Alle Beiträge"}]'::jsonb,
    'beitraege', (SELECT coalesce(jsonb_agg(talents_beitrag_json(x.id) || jsonb_build_object('zuordnung', x.st,
        'zuordnung_text', CASE x.st WHEN 'bestaetigt' THEN 'zugeordnet' WHEN 'vorschlag' THEN 'vorgeschlagen' WHEN 'entfernt' THEN 'entfernt' END, 'grund', x.grund)
        ORDER BY x.erst DESC, x.id), '[]'::jsonb)
      FROM (SELECT b.id, coalesce(b.erstellt, b.erfasst_am) AS erst, kb.status AS st, kb.grund FROM talent_beitraege b JOIN talent_kanaele c2 ON c2.id = b.kanal_id
            LEFT JOIN talent_kampagne_beitraege kb ON kb.kampagne_id = k.id AND kb.beitrag_id = b.id
            WHERE c2.talent_id = ta AND (be = 'alle' OR talents_tag(coalesce(b.erstellt, b.erfasst_am)) BETWEEN k.von AND k.bis)
            ORDER BY coalesce(b.erstellt, b.erfasst_am) DESC, b.id OFFSET (seite - 1) * je LIMIT je) x),
    'anzahl', anz, 'seite', seite, 'seiten', greatest(1, ceil(anz / je::numeric)::integer), 'je_seite', je,
    'leer_text', CASE WHEN ta IS NULL THEN 'Dieser Kampagne ist noch kein Talent zugeordnet.' WHEN anz = 0 THEN
      CASE WHEN be = 'zeitraum' THEN 'Keine Beiträge im Kampagnenzeitraum. Unter „Alle Beiträge“ stehen auch ältere und spätere.' ELSE 'Noch keine Beiträge von diesem Talent.' END END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ui_rechte(p_token text, p_talent_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb := talents_ansicht_start(p_token);
  u text; verw boolean; mgmt boolean;
BEGIN
  -- Rechte für die Talent-Seiten der neuen Oberfläche (ALLY 24, ALLY 25; Stefan 20.10.2026). anlegen = Talent einladen (Admin, „Talents verwalten“, Management);
  -- talent = dieses Talent verwalten (Stammdaten, Einladungslink, Accounts trennen, archivieren): mit „Talents verwalten“ alle, Management nur die eigenen Talents.
  -- Zuständige Personen wählen und Talents importieren bleibt bei „Talents verwalten“, endgültig löschen beim Admin.
  IF NOT coalesce((c->>'ok')::boolean, false) THEN RETURN jsonb_build_object('ok', false); END IF;
  u := c->>'u'; verw := (c->>'verw')::boolean; mgmt := talents_planung_management(u);
  RETURN jsonb_build_object('ok', true, 'verw', verw, 'mgmt', mgmt, 'anlegen', verw OR mgmt,
    'talent', p_talent_id IS NOT NULL AND (verw OR (mgmt AND coalesce(talent_verwaltbar(u, p_talent_id), false))));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ui_talent_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
DECLARE
  s record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  u text;
  m text := NULL;
  fehler text := NULL;
  erg jsonb := NULL;
  t talents%ROWTYPE;
  verw boolean;
  adm boolean;
  mgmt boolean;
  neu boolean;
  x text;
  n_name text; n_kname text; n_email text; n_notiz text; n_tage integer; n_personen text[]; n_kanaele text[];
  tage_gesetzt boolean := false;
  tid integer;
  anz integer;
  k talent_kanaele%ROWTYPE;
  v_alt text; e_alt text;
  b_neu text; vl_neu text; lf_neu text; lw_neu text; kw_neu text; sammel record; zeilen jsonb;
  az_neu text; as_neu text; zt_neu text; zz_neu text;
  wid boolean; lg jsonb;
BEGIN
  -- Talents in der neuen Oberfläche (BA6, Migration 61; Kopie von talents_web_aktion, das ALLY 8 unverändert nutzt). Rollen nach Stefan 20.10.2026:
  -- Management legt die eigenen Talents selbst an (sie gehören automatisch der anlegenden Person) und verwaltet sie (bearbeiten, Einladungslink, Accounts trennen,
  -- archivieren, reaktivieren, Links erneuern); zuständige Personen ändern, Einstellungen und endgültig löschen bleiben bei „Talents verwalten“ bzw. Admin.
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := s.matrix_user_id;
  verw := ally_hat_recht(u, 'talents_verwalten');
  adm := ally_hat_recht(u, 'admin');
  mgmt := NOT verw AND talents_planung_management(u);
  x := btrim(coalesce(d->>'id', ''));
  IF x ~ '^[0-9]{1,9}$' THEN
    SELECT * INTO t FROM talents WHERE id = x::integer;
  END IF;

  BEGIN
    IF NOT plattform_modul_an('talents') THEN
      fehler := 'Das Paket Talents ist nicht gebucht.';
    ELSIF p_aktion = 'einstellungen' AND NOT adm THEN
      fehler := 'Die Einstellungen für Talents ändern Admins.';
    ELSIF p_aktion IN ('talent_loeschen', 'papierkorb_leeren') AND NOT adm THEN
      fehler := 'Talents endgültig löschen können nur Admins.';
    ELSIF NOT verw AND NOT mgmt THEN
      fehler := 'Dafür fehlt dir das Recht „Talents und Kampagnen verwalten“. Rechte vergibt eine Person mit der Rolle Admin.';
    ELSIF NOT verw AND p_aktion NOT IN ('talent_neu', 'links_erneuern', 'papierkorb_leeren') AND NOT coalesce(talent_verwaltbar(u, t.id), false) THEN
      fehler := 'Unbekanntes Talent. Bitte die Seite neu laden.';
    ELSIF p_aktion IN ('talent_bearbeiten', 'einladung_neu', 'kanal_trennen', 'talent_archivieren', 'talent_reaktivieren', 'talent_loeschen') AND t.id IS NULL THEN
      fehler := 'Unbekanntes Talent. Bitte die Seite neu laden.';

    ELSIF p_aktion IN ('talent_neu', 'talent_bearbeiten') THEN
      neu := p_aktion = 'talent_neu';
      -- Name optional; leer = NULL (Stefan 18.10.2026)
      n_name := CASE WHEN neu OR d ? 'name' THEN nullif(btrim(coalesce(d->>'name', '')), '') ELSE t.name END;
      n_kname := CASE WHEN neu OR d ? 'kuenstlername' THEN nullif(btrim(coalesce(d->>'kuenstlername', '')), '') ELSE t.kuenstlername END;
      n_email := CASE WHEN neu OR d ? 'email' THEN nullif(lower(btrim(coalesce(d->>'email', ''))), '') ELSE t.email END;
      n_notiz := CASE WHEN neu OR d ? 'notiz' THEN nullif(btrim(coalesce(d->>'notiz', '')), '') ELSE t.notiz END;
      n_tage := CASE WHEN neu THEN NULL ELSE t.verfolgung_tage END;
      IF d ? 'verfolgung_tage' THEN
        x := lower(btrim(coalesce(d->>'verfolgung_tage', '')));
        tage_gesetzt := true;
        IF x = '' THEN n_tage := NULL;
        ELSIF x IN ('unbegrenzt', '0') THEN n_tage := 0;
        ELSIF x ~ '^[0-9]{1,4}$' AND x::integer BETWEEN 1 AND 3650 THEN n_tage := x::integer;
        ELSE fehler := 'Bitte die Verfolgungsdauer in Tagen (1 bis 3650) angeben, „unbegrenzt“ wählen oder leer lassen (Standard der Agentur).';
        END IF;
      END IF;
      IF (neu OR d ? 'personen') AND verw THEN
        n_personen := talents_liste(d->'personen');
        IF neu AND cardinality(n_personen) = 0 THEN
          n_personen := ARRAY[u];
        END IF;
      ELSIF neu THEN
        -- Management: neue Talents gehören automatisch der anlegenden Person (Stefan 20.10.2026)
        n_personen := ARRAY[u];
      END IF;
      IF neu OR d ? 'kanaele' THEN
        n_kanaele := talents_liste(d->'kanaele');
      END IF;
      -- Ohne Namen, aber schon ein Account bekannt: dessen Name wird der Name (wie beim Verbinden) (Stefan 18.10.2026)
      IF NOT neu AND n_name IS NULL THEN
        SELECT nullif(btrim(left(ltrim(regexp_replace(btrim(kx.extern_name), '[[:cntrl:]]', '', 'g'), '@'), 120)), '') INTO n_name FROM talent_kanaele kx
        WHERE kx.talent_id = t.id AND nullif(btrim(ltrim(btrim(coalesce(kx.extern_name, '')), '@')), '') IS NOT NULL
        ORDER BY kx.status IN ('verbunden', 'abgelaufen') DESC, array_position(talents_plattformen(), kx.plattform) LIMIT 1;
      END IF;
      IF fehler IS NOT NULL THEN
        NULL;
      ELSIF n_name IS NOT NULL AND (length(n_name) > 120 OR n_name ~ '[[:cntrl:]]') THEN
        fehler := 'Der Name darf höchstens 120 Zeichen haben.';
      ELSIF n_kname IS NOT NULL AND (length(n_kname) > 120 OR n_kname ~ '[[:cntrl:]]') THEN
        fehler := 'Der Künstlername darf höchstens 120 Zeichen haben.';
      ELSIF n_email IS NOT NULL AND (length(n_email) > 200 OR n_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$') THEN
        fehler := 'Bitte eine gültige E-Mail-Adresse angeben oder das Feld leer lassen.';
      ELSIF n_notiz IS NOT NULL AND length(n_notiz) > 4000 THEN
        fehler := 'Die Notiz darf höchstens 4000 Zeichen haben.';
      ELSIF n_personen IS NOT NULL AND cardinality(n_personen) = 0 THEN
        fehler := 'Bitte mindestens einen Manager oder eine Managerin wählen.';
      ELSIF n_personen IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(n_personen) p
            WHERE NOT EXISTS (SELECT 1 FROM ally_personen ap WHERE ap.matrix_user_id = p AND ap.aktiv AND NOT ally_rolle_ist_talent(ap.rolle))) THEN  -- Migration 158 (Bauplan B3a): Talent-Personen sind nie Manager/in.
        fehler := 'In der Auswahl ist eine unbekannte Person. Bitte die Seite neu laden.';
      ELSIF n_kanaele IS NOT NULL AND cardinality(n_kanaele) = 0 THEN
        fehler := 'Bitte mindestens einen Kanal wählen.';
      ELSIF n_kanaele IS NOT NULL AND NOT (n_kanaele <@ talents_plattformen()) THEN
        fehler := 'In der Auswahl ist ein unbekannter Kanal. Bitte die Seite neu laden.';
      ELSIF neu AND n_name IS NOT NULL AND EXISTS (SELECT 1 FROM talents x2 WHERE lower(x2.name) = lower(n_name)
            AND coalesce(lower(x2.kuenstlername), '') = coalesce(lower(n_kname), '')) THEN
        fehler := 'Ein Talent mit diesem Namen gibt es schon.';
      -- Migration 165 (Bauplan B5c): vorgemerkte Rolle (Stefan G10): nur aktive Rollen der Art talent; ohne Angabe gilt Talent.
      ELSIF neu AND nullif(btrim(coalesce(d->>'rolle', '')), '') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ally_rollen r WHERE r.schluessel = btrim(d->>'rolle') AND r.art = 'talent' AND r.archiviert_am IS NULL) THEN
        fehler := 'Diese Rolle gibt es nicht oder sie ist archiviert. Bitte eine andere wählen.';
      ELSIF neu AND NOT ally_verschluesselung_bereit() THEN
        fehler := 'Verschlüsselung ist nicht eingerichtet.';
      ELSIF neu THEN
        INSERT INTO talents (name, kuenstlername, email, notiz, verfolgung_tage, erstellt_von, geaendert_von, rolle)
        VALUES (n_name, n_kname, n_email, n_notiz, n_tage, u, u, nullif(btrim(coalesce(d->>'rolle', '')), '')) RETURNING id INTO tid;
        INSERT INTO talent_personen (talent_id, matrix_user_id) SELECT tid, p FROM unnest(n_personen) p;
        INSERT INTO talent_kanaele (talent_id, plattform) SELECT tid, kk FROM unnest(n_kanaele) kk;
        erg := talent_einladung_anlegen(tid, u);
        m := 'Einladung erstellt.';
      ELSE
        tid := t.id;
        UPDATE talents SET name = n_name, kuenstlername = n_kname, email = n_email, notiz = n_notiz, verfolgung_tage = n_tage,
          geaendert_am = now(), geaendert_von = u WHERE id = tid;
        IF n_personen IS NOT NULL THEN
          DELETE FROM talent_personen WHERE talent_id = tid AND NOT (matrix_user_id = ANY (n_personen));
          INSERT INTO talent_personen (talent_id, matrix_user_id) SELECT tid, p FROM unnest(n_personen) p ON CONFLICT DO NOTHING;
        END IF;
        m := 'Talent gespeichert.';
        IF n_kanaele IS NOT NULL THEN
          -- Neue Plattform = Platzhalter; Plattformen mit vorhandenen Zeilen (Accounts) bleiben unverändert (Stefan 18.10.2026)
          INSERT INTO talent_kanaele (talent_id, plattform) SELECT tid, kk FROM unnest(n_kanaele) kk
          WHERE NOT EXISTS (SELECT 1 FROM talent_kanaele kx WHERE kx.talent_id = tid AND kx.plattform = kk) ON CONFLICT DO NOTHING;
          -- Abgewählte Kanäle nur entfernen, wenn sie nie verbunden waren und keine Daten haben
          DELETE FROM talent_kanaele kx WHERE kx.talent_id = tid AND NOT (kx.plattform = ANY (n_kanaele)) AND kx.status = 'offen'
            AND kx.schluessel IS NULL AND kx.verbunden_am IS NULL
            AND NOT EXISTS (SELECT 1 FROM talent_kanal_tage y WHERE y.kanal_id = kx.id)
            AND NOT EXISTS (SELECT 1 FROM talent_beitraege y WHERE y.kanal_id = kx.id)
            AND NOT EXISTS (SELECT 1 FROM talent_zielgruppen y WHERE y.kanal_id = kx.id);
          SELECT count(*) INTO anz FROM talent_kanaele kx WHERE kx.talent_id = tid AND NOT (kx.plattform = ANY (n_kanaele));
          IF anz > 0 THEN
            m := m || ' Kanäle, die schon verbunden waren, bleiben in der Liste. Zum Trennen bitte „Kanal trennen“ nutzen.';
          END IF;
        END IF;
      END IF;

    ELSIF p_aktion = 'einladung_neu' THEN
      IF t.status <> 'aktiv' THEN
        fehler := 'Das Talent liegt im Papierkorb. Bitte zuerst wiederherstellen.';
      ELSIF NOT ally_verschluesselung_bereit() THEN
        fehler := 'Verschlüsselung ist nicht eingerichtet.';
      ELSE
        anz := (SELECT count(*) FROM talent_einladungen e WHERE e.talent_id = t.id AND e.widerrufen_am IS NULL AND e.gueltig_bis > now());
        erg := talent_einladung_anlegen(t.id, u);
        m := 'Neuer Einladungslink' || coalesce(' für ' || talent_anzeigename(t.id), '') || ' erstellt.' || CASE WHEN anz > 0 THEN ' Der bisherige Link gilt nicht mehr.' ELSE '' END;
      END IF;

    ELSIF p_aktion = 'kanal_trennen' THEN
      -- Je Account: kanal_id (Stefan 18.10.2026). Rückfall plattform nur, wenn genau ein Account dieser Plattform verbunden ist.
      x := btrim(coalesce(d->>'kanal_id', ''));
      IF x ~ '^[0-9]{1,9}$' THEN
        SELECT * INTO k FROM talent_kanaele kx WHERE kx.id = x::integer AND kx.talent_id = t.id;
      ELSIF x = '' THEN
        x := lower(btrim(coalesce(d->>'plattform', '')));
        SELECT count(*) INTO anz FROM talent_kanaele kx WHERE kx.talent_id = t.id AND kx.plattform = x AND kx.status IN ('verbunden', 'abgelaufen');
        IF anz > 1 THEN
          fehler := 'Dieses Talent hat mehrere ' || talents_plattform_name(x) || '-Accounts. Bitte die Seite neu laden und den Account wählen.';
        ELSE
          SELECT * INTO k FROM talent_kanaele kx WHERE kx.talent_id = t.id AND kx.plattform = x
          ORDER BY kx.status IN ('verbunden', 'abgelaufen') DESC, kx.id LIMIT 1;
        END IF;
      END IF;
      IF fehler IS NOT NULL THEN
        NULL;
      ELSIF k.id IS NULL THEN
        fehler := 'Diesen Kanal hat das Talent nicht. Bitte die Seite neu laden.';
      ELSIF k.status NOT IN ('verbunden', 'abgelaufen') THEN
        fehler := 'Dieser Kanal ist nicht verbunden.';
      ELSE
        -- YouTube/TikTok: Zugang zuerst bei der Plattform widerrufen (TALENTS YT/TT über talents_widerruf_liste); der Schlüssel liegt bis dahin nur in talent_widerrufe (Stefan 18.10.2026)
        wid := talents_widerruf_vormerken(k.id, 'trennen', u);
        UPDATE talent_kanaele SET status = 'getrennt', schluessel = NULL, schluessel_zusatz = NULL, gueltig_bis = NULL, geaendert_am = now()
        WHERE id = k.id;
        m := talents_plattform_name(k.plattform) || CASE WHEN nullif(ltrim(btrim(coalesce(k.extern_name, '')), '@'), '') IS NOT NULL THEN ' ' || talents_konto_text(k.plattform, k.extern_name) ELSE '' END
          || coalesce(' von ' || talent_anzeigename(t.id), '') || ' getrennt.'
          || CASE WHEN wid THEN ' Ally widerruft den Zugang auch bei ' || talents_plattform_name(k.plattform) || '.' ELSE '' END
          || CASE WHEN k.plattform = 'youtube' AND k.extern_id IS NOT NULL
                  THEN ' Die bisher gespeicherten Zahlen bleiben bis zum ' || to_char(talents_tag(coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am)) + 30, 'DD.MM.YYYY')
                    || ' erhalten; danach löscht Ally sie nach den YouTube-Richtlinien, wenn der Kanal nicht neu verbunden ist.'
                  ELSE ' Die bisher gespeicherten Zahlen bleiben erhalten.' END;
      END IF;

    ELSIF p_aktion = 'talent_archivieren' THEN
      IF t.status = 'archiviert' THEN
        fehler := 'Das Talent liegt schon im Papierkorb.';
      ELSE
        UPDATE talents SET status = 'archiviert', archiviert_am = now(), geaendert_am = now(), geaendert_von = u WHERE id = t.id;
        UPDATE talent_einladungen SET widerrufen_am = now() WHERE talent_id = t.id AND widerrufen_am IS NULL;
        -- Migration 130: Papierkorb = bisher Archiv (Markierung status 'archiviert')
        m := coalesce(talent_anzeigename(t.id), 'Das Talent') || ' liegt jetzt im Papierkorb. Offene Einladungslinks gelten nicht mehr, Abrufe ruhen. Im Papierkorb kannst du es wiederherstellen.';
      END IF;

    ELSIF p_aktion = 'talent_reaktivieren' THEN
      IF t.status = 'aktiv' THEN
        fehler := 'Das Talent ist schon aktiv.';
      ELSE
        UPDATE talents SET status = 'aktiv', archiviert_am = NULL, geaendert_am = now(), geaendert_von = u WHERE id = t.id;
        m := coalesce(talent_anzeigename(t.id), 'Das Talent') || ' ist wiederhergestellt und wieder aktiv. Für neue Verbindungen bitte einen neuen Einladungslink erstellen.';
      END IF;

    ELSIF p_aktion = 'talent_loeschen' THEN
      -- Bestätigung: der gespeicherte Name; ohne Namen das Wort "löschen" (Stefan 18.10.2026)
      -- Endgültig löschen nur archivierte Talents (Stefan 18.10.2026)
      IF t.status <> 'archiviert' THEN
        fehler := 'Endgültig löschen lässt sich nur ein Talent im Papierkorb. Bitte das Talent zuerst in den Papierkorb legen.';
      ELSIF t.name IS NOT NULL AND btrim(coalesce(d->>'bestaetigung', '')) IS DISTINCT FROM t.name THEN
        fehler := 'Zum endgültigen Löschen bitte den Namen genau so eingeben, wie er gespeichert ist: ' || t.name;
      ELSIF t.name IS NULL AND lower(btrim(coalesce(d->>'bestaetigung', ''))) <> 'löschen' THEN
        fehler := 'Zum endgültigen Löschen bitte das Wort „löschen“ eingeben.';
      ELSE
        -- Berichte, KI-Bezüge, Widerrufe; Dateien im Speicherort werden vorgemerkt (talent_loesch_dateien) (Stefan 18.10.2026)
        lg := talents_talent_loeschen(t.id, 'manuell', u);
        m := coalesce(t.name, nullif(btrim(t.kuenstlername), ''), 'Das Talent') || ' wurde endgültig gelöscht, mit allen gespeicherten Daten.'
          || CASE WHEN (lg->>'dateien_vorgemerkt')::integer > 0 THEN ' Die Dateien im Speicherort (Berichte, Mediakits, Zahlen) löscht Ally in den nächsten Stunden.' ELSE '' END;
      END IF;

    ELSIF p_aktion = 'papierkorb_leeren' THEN
      -- Migration 130: genau die angezeigten Talents im Papierkorb (höchstens 1000), jedes wie „Endgültig löschen“ (talents_talent_loeschen)
      IF coalesce(d->>'ids', '') !~ '^[0-9]{1,9}(,[0-9]{1,9})*$' OR cardinality(string_to_array(d->>'ids', ',')) > 1000 THEN
        fehler := 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.';
      ELSIF lower(btrim(coalesce(d->>'bestaetigung', ''))) <> 'löschen' THEN
        fehler := 'Zum Leeren des Papierkorbs bitte das Wort „löschen“ eingeben.';
      ELSE
        anz := 0; tid := 0;
        FOR sammel IN SELECT tt.id FROM talents tt WHERE tt.id = ANY (string_to_array(d->>'ids', ',')::integer[]) AND tt.status = 'archiviert' ORDER BY tt.id FOR UPDATE LOOP
          lg := talents_talent_loeschen(sammel.id, 'manuell', u);
          anz := anz + 1; tid := tid + coalesce((lg->>'dateien_vorgemerkt')::integer, 0);
        END LOOP;
        m := CASE WHEN anz = 0 THEN 'Diese Talents liegen nicht mehr im Papierkorb.'
                  WHEN anz = 1 THEN '1 Talent wurde endgültig gelöscht, mit allen gespeicherten Daten.'
                  ELSE anz || ' Talents wurden endgültig gelöscht, mit allen gespeicherten Daten.' END
          || CASE WHEN tid > 0 THEN ' Die Dateien im Speicherort (Berichte, Mediakits, Zahlen) löscht Ally in den nächsten Stunden.' ELSE '' END;
        tid := NULL;
      END IF;

    ELSIF p_aktion = 'einstellungen' THEN
      v_alt := NULL; e_alt := NULL;
      IF d ? 'verfolgung_tage' THEN
        x := lower(btrim(coalesce(d->>'verfolgung_tage', '')));
        IF x IN ('unbegrenzt', '0') THEN v_alt := '0';
        ELSIF x ~ '^[0-9]{1,4}$' AND x::integer BETWEEN 1 AND 3650 THEN v_alt := x::integer::text;
        ELSE fehler := 'Bitte die Verfolgungsdauer in Tagen (1 bis 3650) angeben oder „unbegrenzt“ wählen.';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'einladung_tage' THEN
        x := btrim(coalesce(d->>'einladung_tage', ''));
        IF x ~ '^[0-9]{1,2}$' AND x::integer BETWEEN 1 AND 60 THEN e_alt := x::integer::text;
        ELSE fehler := 'Bitte die Gültigkeit der Einladungslinks in Tagen (1 bis 60) angeben.';
        END IF;
      END IF;
      -- Einladungstext (Vorlage), Löschfrist, Warnfristen (Stefan 18.10.2026)
      IF fehler IS NULL AND d ? 'einladung_betreff' THEN
        b_neu := btrim(regexp_replace(coalesce(d->>'einladung_betreff', ''), '[[:cntrl:]]', ' ', 'g'));
        IF length(b_neu) > 200 THEN fehler := 'Der Betreff darf höchstens 200 Zeichen haben.'; END IF;
      END IF;
      IF fehler IS NULL AND d ? 'einladung_vorlage' THEN
        vl_neu := btrim(regexp_replace(replace(replace(coalesce(d->>'einladung_vorlage', ''), E'\r\n', E'\n'), E'\r', E'\n'), '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f]', '', 'g'));
        IF length(vl_neu) > 4000 THEN fehler := 'Der Einladungstext darf höchstens 4000 Zeichen haben.';
        ELSIF vl_neu <> '' AND vl_neu !~* '\[link\]' THEN fehler := 'Der Einladungstext braucht den Platzhalter [Link], sonst fehlt dem Talent der Link.';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'loeschfrist_tage' THEN
        lf_neu := lower(btrim(coalesce(d->>'loeschfrist_tage', '')));
        IF lf_neu IN ('', 'nie') THEN lf_neu := '';
        ELSIF lf_neu ~ '^[0-9]{1,4}$' AND lf_neu::integer BETWEEN 1 AND 3650 THEN lf_neu := lf_neu::integer::text;
        ELSE fehler := 'Bitte die Löschfrist in Tagen nach der Archivierung (1 bis 3650) angeben oder leer lassen (nie automatisch löschen).';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'loeschwarnung_tage' THEN
        lw_neu := btrim(coalesce(d->>'loeschwarnung_tage', ''));
        IF lw_neu ~ '^[0-9]{1,2}$' AND lw_neu::integer BETWEEN 1 AND 90 THEN lw_neu := lw_neu::integer::text;
        ELSE fehler := 'Bitte angeben, wie viele Tage vor dem Löschen die Admins gewarnt werden (1 bis 90).';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'kampagne_warnung_tage' THEN
        kw_neu := btrim(coalesce(d->>'kampagne_warnung_tage', ''));
        IF kw_neu ~ '^[0-9]{1,2}$' AND kw_neu::integer BETWEEN 0 AND 60 THEN kw_neu := kw_neu::integer::text;
        ELSE fehler := 'Bitte angeben, wie viele Tage vor Kampagnenende ein fehlender Beitrag gemeldet wird (0 bis 60; 0 = am letzten Tag).';
        END IF;
      END IF;
      -- Migration 195 (Stefan 01.11.2026, Abrufzeiten): Zeiten des automatischen Abrufs für alle Talents
      -- (Kachel „Automatischer Abruf“; talents_abrufzeit_werte liest sie, ungültig = Standard). Uhrzeiten in Viertelstunden wie die übrigen (ally_web_uhrzeit).
      IF fehler IS NULL AND d ? 'abruf_uhrzeit' THEN
        az_neu := ally_web_uhrzeit(d->>'abruf_uhrzeit');
        IF az_neu IS NULL THEN fehler := 'Bitte die Uhrzeit für Beiträge und Kennzahlen angeben (z. B. 02:15).'; END IF;
      END IF;
      IF fehler IS NULL AND d ? 'abruf_storys_stunden' THEN
        as_neu := btrim(coalesce(d->>'abruf_storys_stunden', ''));
        IF as_neu ~ '^[0-9]{1,2}$' AND as_neu::integer BETWEEN 1 AND 24 THEN as_neu := as_neu::integer::text;
        ELSE as_neu := NULL; fehler := 'Bitte den Abstand für Storys in Stunden angeben (1 bis 24). Instagram zeigt Storys nur 24 Stunden lang.';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'abruf_zielgruppe_tag' THEN
        zt_neu := btrim(coalesce(d->>'abruf_zielgruppe_tag', ''));
        IF zt_neu !~ '^[0-7]$' THEN zt_neu := NULL; fehler := 'Bitte den Wochentag für die Zielgruppe wählen.'; END IF;
      END IF;
      IF fehler IS NULL AND d ? 'abruf_zielgruppe_uhrzeit' THEN
        zz_neu := ally_web_uhrzeit(d->>'abruf_zielgruppe_uhrzeit');
        IF zz_neu IS NULL THEN fehler := 'Bitte die Uhrzeit für die Zielgruppe angeben (z. B. 03:15).'; END IF;
      END IF;
      IF fehler IS NULL AND v_alt IS NULL AND e_alt IS NULL AND b_neu IS NULL AND vl_neu IS NULL AND lf_neu IS NULL AND lw_neu IS NULL AND kw_neu IS NULL
         AND az_neu IS NULL AND as_neu IS NULL AND zt_neu IS NULL AND zz_neu IS NULL THEN
        fehler := 'Es wurden keine Einstellungen übermittelt. Bitte die Seite neu laden.';
      END IF;
      IF fehler IS NULL THEN
        IF v_alt IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_verfolgung_tage', v_alt, u); END IF;
        IF e_alt IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_einladung_tage', e_alt, u); END IF;
        IF b_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_einladung_betreff', b_neu, u); END IF;
        IF vl_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_einladung_vorlage', vl_neu, u); END IF;
        IF lf_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_loeschfrist_tage', lf_neu, u); END IF;
        IF lw_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_loeschwarnung_tage', lw_neu, u); END IF;
        IF kw_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_kampagne_warnung_tage', kw_neu, u); END IF;
        IF az_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_abruf_uhrzeit', az_neu, u); END IF;
        IF as_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_abruf_storys_stunden', as_neu, u); END IF;
        IF zt_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_abruf_zielgruppe_tag', zt_neu, u); END IF;
        IF zz_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_abruf_zielgruppe_uhrzeit', zz_neu, u); END IF;
        -- Ankündigung auch ohne Chat (Stefan 19.10.2026, Migration 54)
        m := 'Einstellungen für Talents gespeichert.' || CASE WHEN coalesce(lf_neu, '') <> '' THEN ' Gelöscht wird frühestens '
          || talents_einstellung_zahl('talents_loeschwarnung_tage', 1, 90, 14) || ' Tage nach der Ankündigung (Chat an die Admins; kommt sie nicht an, gilt der Termin in der Talents-Liste).' ELSE '' END;
      END IF;

    -- Sammel-Aktion: neuer Link für alle aktiven Talents mit abgelaufener Verbindung oder abgelaufener Einladung, Tabelle (CSV) zum Herunterladen (Stefan 18.10.2026)
    ELSIF p_aktion = 'links_erneuern' THEN
      IF NOT ally_verschluesselung_bereit() THEN
        fehler := 'Verschlüsselung ist nicht eingerichtet.';
      ELSE
        zeilen := '[]'::jsonb;
        FOR sammel IN SELECT t2.id FROM talents t2 WHERE t2.status = 'aktiv' AND (talents_talent_stand(t2.id)->>'link_noetig')::boolean
                        AND (verw OR coalesce(talent_verwaltbar(u, t2.id), false))
                      ORDER BY lower(talent_listenname(t2.id)) COLLATE "C", t2.id LIMIT 500 LOOP
          erg := talent_einladung_anlegen(sammel.id, u);
          zeilen := zeilen || jsonb_build_array(jsonb_build_array(coalesce(talent_anzeigename(sammel.id), ''), erg->>'email', erg->>'link', erg->>'gueltig_bis'));
        END LOOP;
        anz := jsonb_array_length(zeilen);
        IF anz = 0 THEN
          erg := NULL;
          fehler := 'Es gibt keine Talents mit abgelaufener Verbindung oder abgelaufener Einladung.';
        ELSE
          erg := jsonb_build_object('art', 'links', 'anzahl', anz, 'dateiname', 'einladungslinks-' || to_char(talents_heute(), 'YYYY-MM-DD') || '.csv',
            'zeilen', (SELECT jsonb_agg(jsonb_build_object('name', z->>0, 'email', z->>1, 'link', z->>2, 'gueltig_bis', z->>3)) FROM jsonb_array_elements(zeilen) z),
            'csv', talents_csv(ARRAY['Name', 'E-Mail', 'Link', 'gültig bis'], zeilen));
          m := CASE WHEN anz = 1 THEN '1 neuer Einladungslink erstellt.' ELSE anz || ' neue Einladungslinks erstellt.' END
            || ' Die Tabelle steht zum Herunterladen bereit. Bitte die Links selbst an die Talents schicken.';
        END IF;
      END IF;

    ELSE
      fehler := 'Unbekannte Aktion.';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Teiländerungen dieses Blocks sind zurückgenommen
    erg := NULL;
    -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung
    fehler := CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' OR SQLSTATE = 'AT002' THEN SQLERRM
                   ELSE 'Die Aktion konnte nicht ausgeführt werden. Bitte erneut versuchen. (' || left(SQLERRM, 200) || ')' END;
  END;

  UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END,
    ergebnis = CASE WHEN fehler IS NULL THEN erg END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'fehler', fehler,
    'talent_id', CASE WHEN fehler IS NULL THEN coalesce(tid, t.id) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_url_kodieren(p text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce(string_agg(CASE WHEN x.c ~ '^[A-Za-z0-9._~-]$' THEN x.c
                                  ELSE upper(regexp_replace(encode(convert_to(x.c, 'UTF8'), 'hex'), '(..)', '%\1', 'g')) END, '' ORDER BY x.o), '')
  FROM regexp_split_to_table(coalesce(p, ''), '') WITH ORDINALITY AS x(c, o)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_veraenderung(p_jetzt numeric, p_vorher numeric)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_jetzt IS NULL OR p_vorher IS NULL OR p_jetzt < 0 OR p_vorher < 0 THEN jsonb_build_object('prozent', NULL, 'text', '–', 'richtung', NULL)
    WHEN p_vorher = 0 AND p_jetzt = 0 THEN jsonb_build_object('prozent', 0, 'text', '±0 %', 'richtung', 'gleich')
    WHEN p_vorher = 0 THEN jsonb_build_object('prozent', NULL, 'text', 'vorher 0', 'richtung', 'hoch')
    ELSE (SELECT jsonb_build_object('prozent', x.p,
            'text', CASE WHEN x.p > 0 THEN '+' || talents_zahl_text(x.p) WHEN x.p < 0 THEN '−' || talents_zahl_text(abs(x.p)) ELSE '±' || '0' END || ' %',
            'richtung', CASE WHEN x.p > 0 THEN 'hoch' WHEN x.p < 0 THEN 'runter' ELSE 'gleich' END)
          FROM (SELECT round((p_jetzt / p_vorher - 1) * 100)::bigint AS p) x) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_verbindung_info(p_plattform text, p_weg text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Info je Verbindung für das i-Symbol (Stefan 20.10.2026, 09:23; Migration 65): welche Daten die Verbindung liefert und welche nicht.
  -- Texte und Quellen: scratchpad mp/k2/info_verbindung/texte.md (offizielle Developer-Dokumentation der Plattformen und die Felder, die Ally abruft).
  -- Schlüssel: instagram/instagram (Instagram-Anmeldung), instagram/facebook (über Facebook-Seite), facebook, threads, youtube (Weg google), pinterest, tiktok,
  -- linkedin, manuell (Zahlen per Screenshot), instagram_kanal. Genderneutral, ohne „du“.
  SELECT CASE
    WHEN p_plattform = 'instagram' AND p_weg = 'instagram' THEN jsonb_build_object('schluessel', 'info.verbindung.instagram.instagram', 'titel', 'Instagram über Instagram-Anmeldung',
      'kurz', 'Für professionelle Instagram-Konten (Business oder Creator) ohne Facebook-Seite. Liefert Follower, Reichweite, Aufrufe, Interaktionen, Beiträge und Reels mit Zahlen sowie die Zielgruppe. Nicht dabei: Beitragstexte und Storys.',
      'liefert', 'Follower und Anzahl Beiträge; je Tag Reichweite, Aufrufe, Interaktionen, Likes, Kommentare, Speicherungen, Geteilt, Follows/Unfollows; Beiträge und Reels mit Link, Datum, Vorschaubild und Zahlen; Zielgruppe nach Alter, Geschlecht, Land und Stadt (wöchentlich).',
      'nicht', 'Beitragstexte (Captions) und die Art des Beitrags – liefert Instagram nur über die Anmeldung mit Facebook-Seite. Storys ruft Ally nur über die Anmeldung mit Facebook-Seite ab.',
      'gut', 'Manche Zahlen, z. B. die Zielgruppe, zeigt Instagram erst ab 100 Followern. Zahlen können bis zu 48 Stunden verspätet sein. Die Verbindung gilt 60 Tage; Ally verlängert sie automatisch.')
    WHEN p_plattform = 'instagram' AND p_weg = 'facebook' THEN jsonb_build_object('schluessel', 'info.verbindung.instagram.facebook', 'titel', 'Instagram über Facebook-Seite',
      'kurz', 'Für professionelle Instagram-Konten, die mit einer Facebook-Seite verknüpft sind. Liefert alles wie die Instagram-Anmeldung, dazu Beitragstexte und Storys mit Zahlen.',
      'liefert', 'Wie die Instagram-Anmeldung, zusätzlich Beitragstext und Art (Feed, Reel, Story); Storys der letzten 24 Stunden mit Aufrufen, Reichweite, Geteilt, Interaktionen, Follows, Profilbesuchen und Antworten (stündlich abgerufen).',
      'nicht', 'Zahlen von Storys, die älter als 24 Stunden sind – Instagram stellt Story-Zahlen nur 24 Stunden bereit. Storys mit weniger als 5 Betrachtenden liefern keine Zahlen.',
      'gut', 'Das Konto muss mit einer Facebook-Seite verknüpft sein. Die Verbindung über Facebook muss etwa alle 60 Tage erneuert werden; Ally erinnert vorher.')
    WHEN p_plattform = 'facebook' THEN jsonb_build_object('schluessel', 'info.verbindung.facebook', 'titel', 'Facebook-Seite',
      'kurz', 'Für Facebook-Seiten mit Zugriff auf die Statistiken. Liefert Follower, Aufrufe, Reichweite, Interaktionen und Beiträge mit Zahlen. Keine Zielgruppe. Statistiken gibt es erst ab 100 Likes der Seite.',
      'liefert', 'Follower der Seite; je Tag Aufrufe, Reichweite, Interaktionen, Video-Aufrufe und neue Follows; Beiträge mit Text, Link und Bild sowie Aufrufen, Reichweite, Reaktionen und Klicks.',
      'nicht', 'Zielgruppe (Alter, Geschlecht, Ort) – ruft Ally für Facebook-Seiten nicht ab.',
      'gut', 'Seiten-Statistiken gibt es erst ab 100 Likes der Seite. Nötig ist auf der Seite die Aufgabe ANALYZE. Meta speichert die Zahlen öffentlicher Seiten 2 Jahre.')
    WHEN p_plattform = 'threads' THEN jsonb_build_object('schluessel', 'info.verbindung.threads', 'titel', 'Threads',
      'kurz', 'Für das Threads-Profil. Liefert Follower, Profilaufrufe, Likes, Antworten, Reposts, Zitate, Link-Klicks, Beiträge mit Zahlen und ab 100 Followern die Zielgruppe.',
      'liefert', 'Follower; je Tag Profilaufrufe, Likes, Antworten, Reposts, Zitate und Link-Klicks; Beiträge mit Text und Link sowie Aufrufen, Likes, Antworten, Reposts, Zitaten und Geteilt; Zielgruppe nach Land, Stadt, Alter und Geschlecht (wöchentlich).',
      'nicht', 'Aufrufe aller Beiträge je Tag – Threads liefert für das Profil die Profilaufrufe. Antworten zählen nur auf oberster Ebene. Keine Zahlen vor dem 13.04.2024.',
      'gut', 'Zielgruppe erst ab 100 Followern. Aufrufe und Geteilt je Beitrag sind bei Threads noch in Entwicklung. Die Verbindung gilt 60 Tage; Ally verlängert sie automatisch.')
    WHEN p_plattform = 'youtube' THEN jsonb_build_object('schluessel', 'info.verbindung.youtube', 'titel', 'YouTube',
      'kurz', 'Für den YouTube-Kanal (Anmeldung mit dem Google-Konto, dem der Kanal gehört). Liefert Abos, Aufrufe, Wiedergabezeit, Likes, Kommentare, Videos mit Zahlen und die Zuschauenden nach Alter, Geschlecht und Land.',
      'liefert', 'Abos, Anzahl öffentlicher Videos, Aufrufe gesamt; je Tag Aufrufe, Engaged Views, Wiedergabezeit, durchschnittliche Wiedergabedauer, Likes, Kommentare, Geteilt, gewonnene und verlorene Abos; Videos mit Titel, Link und Zahlen; Zuschauende der letzten 28 Tage nach Alter und Geschlecht (in Prozent) und Land (wöchentlich).',
      'nicht', 'Umsätze. Impressionen und Klickrate der Vorschaubilder. Die jüngsten Tage fehlen zunächst.',
      'gut', 'Die Abozahl rundet YouTube auf drei Stellen ab; ist sie ausgeblendet, fehlt sie. Die Videoanzahl zählt nur öffentliche Videos. Summen und Veränderungen berechnet Ally; sie stammen nicht von YouTube.')
    WHEN p_plattform = 'pinterest' THEN jsonb_build_object('schluessel', 'info.verbindung.pinterest', 'titel', 'Pinterest',
      'kurz', 'Für das Pinterest-Konto. Liefert Follower, Impressionen, Interaktionen, Klicks, Speicherungen und Pins mit Zahlen. Keine Zielgruppe. Zahlen nur 90 Tage rückwirkend.',
      'liefert', 'Follower, Gefolgt, Anzahl Pins, monatliche Aufrufe; je Tag Impressionen, Interaktionen, Pin-Klicks, ausgehende Klicks und Speicherungen (nur fertig berechnete Tage); Pins mit Titel, Link, Bild und Gesamtzahlen.',
      'nicht', 'Zielgruppe (ruft Ally nicht ab). Tage, die bei der Verbindung älter als 90 Tage sind.',
      'gut', 'Pinterest liefert Zahlen nur 90 Tage rückwirkend; ältere Tage hat Ally nur, wenn es sie vorher selbst gespeichert hat. Manche Zahlen gibt es nur für Unternehmenskonten.')
    WHEN p_plattform = 'tiktok' THEN jsonb_build_object('schluessel', 'info.verbindung.tiktok', 'titel', 'TikTok',
      'kurz', 'Für das TikTok-Konto. Liefert nur Gesamtzahlen: Follower, Likes, Anzahl öffentlicher Videos und öffentliche Videos mit Aufrufen, Likes, Kommentaren und Geteilt.',
      'liefert', 'Follower, Gefolgt, Likes gesamt, Anzahl öffentlicher Videos; öffentliche Videos mit Titel, Link, Aufrufen, Likes, Kommentaren und Geteilt.',
      'nicht', 'Reichweite, Wiedergabezeit, Zielgruppe und Tageswerte (Ally erhält nur Gesamtzahlen). Private Videos. Zahlen aus der Zeit vor der Verbindung.',
      'gut', 'Tageswerte entstehen aus den täglichen Ständen, die Ally speichert.')
    WHEN p_plattform = 'linkedin' THEN jsonb_build_object('schluessel', 'info.verbindung.linkedin', 'titel', 'LinkedIn',
      'kurz', 'In Talents nicht eingebunden. LinkedIn ist in Ally nur zum Veröffentlichen eigener Beiträge verbunden (Marketing).')
    WHEN p_plattform = 'manuell' THEN jsonb_build_object('schluessel', 'info.verbindung.manuell', 'titel', 'Manuelle Daten',
      'kurz', 'Manuelle Daten sind Zahlen aus einem manuellen Import von Insights. Sie zählen, sobald der Manager oder die Managerin sie geprüft und bestätigt hat.',
      'liefert', 'Konto: Follower, Reichweite, Aufrufe, Interaktionen, Profilaufrufe, Anzahl Beiträge; Beitrag: Aufrufe, Reichweite, Interaktionen, Likes, Kommentare, Speicherungen, Geteilt; Zielgruppe: Follower nach Alter, Geschlecht, Land, Stadt.',
      'nicht', 'Tageswerte – es zählt der Zeitraum der importierten Insights. Ein Wert zählt nur, wenn sein Zeitraum ganz im gewählten Zeitraum liegt.',
      'gut', 'Manuelle Daten fließen in alle Summen ein. Ist „Manuelle Daten einbeziehen“ deaktiviert, werden sie nicht berücksichtigt. Gibt es für denselben Account, dieselbe Kennzahl und denselben Zeitraum auch automatische Zahlen, zählt bis zur Entscheidung der automatische Wert („Doppelte Daten prüfen“).')
    WHEN p_plattform = 'instagram_kanal' THEN jsonb_build_object('schluessel', 'info.verbindung.instagram_kanal', 'titel', 'Instagram-Kanal',
      'kurz', 'Instagram-Kanal nur über manuellen Import: Mitglieder, Gesamtinteraktionen, Teilen, Umfrage-Stimmen. Kanäle werden nicht automatisch abgerufen.',
      'gut', 'Die Zahlen des Kanals stehen getrennt vom Konto und werden nicht zu den Konto-Zahlen addiert.')
    END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_verbindung_info_liste(p_plattform text, p_weg text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Info je Verbindung als Liste für das i-Popup (Migration 65): kurz, dann „Liefert“, „Nicht dabei“, „Gut zu wissen“
  SELECT CASE WHEN i IS NULL THEN '[]'::jsonb ELSE to_jsonb(array_remove(ARRAY[i->>'kurz',
      CASE WHEN i ? 'liefert' THEN 'Liefert: ' || (i->>'liefert') END, CASE WHEN i ? 'nicht' THEN 'Nicht dabei: ' || (i->>'nicht') END,
      CASE WHEN i ? 'gut' THEN 'Gut zu wissen: ' || (i->>'gut') END], NULL)) END
  FROM (SELECT talents_verbindung_info(p_plattform, p_weg) AS i) x
$function$
;

CREATE OR REPLACE FUNCTION public.talents_verfolgung_stand(p_beitrag_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object('stand', x.stand,
    'text', CASE x.stand WHEN 'laeuft' THEN 'wird verfolgt bis ' || CASE WHEN d.story THEN talents_zeit(d.erst + interval '24 hours') ELSE to_char(d.ende, 'DD.MM.YYYY') END
                         || CASE WHEN d.kamp THEN ' (Kampagnenende)' ELSE '' END
                         WHEN 'unbegrenzt' THEN 'wird unbegrenzt verfolgt' ELSE 'abgeschlossen' END,
    'bis', CASE WHEN d.story THEN talents_zeit(d.erst + interval '24 hours') ELSE to_char(d.ende, 'DD.MM.YYYY') END,
    'bis_iso', CASE WHEN d.story THEN to_char((d.erst + interval '24 hours') AT TIME ZONE 'Europe/Berlin', 'YYYY-MM-DD"T"HH24:MI') ELSE to_char(d.ende, 'YYYY-MM-DD') END,
    'dauer_tage', CASE WHEN d.story THEN 1 ELSE d.dauer END,
    'quelle', CASE WHEN d.story THEN 'story' WHEN d.kamp THEN 'kampagne' WHEN b.verfolgung_tage IS NOT NULL THEN 'beitrag' WHEN t.verfolgung_tage IS NOT NULL THEN 'talent' ELSE 'agentur' END,
    'einstellung', CASE WHEN b.verfolgung_tage IS NULL THEN 'standard' WHEN b.verfolgung_tage = 0 THEN 'unbegrenzt' ELSE b.verfolgung_tage::text END,
    'standard_tage', d.std,
    'standard_text', 'Standard (' || CASE WHEN d.std = 0 THEN 'unbegrenzt' WHEN d.std = 1 THEN '1 Tag' ELSE d.std || ' Tage' END || ')',
    'story', d.story, 'kampagne_bis', to_char(d.kbis, 'DD.MM.YYYY'))
  FROM talent_beitraege b
  JOIN talent_kanaele k ON k.id = b.kanal_id
  JOIN talents t ON t.id = k.talent_id
  CROSS JOIN LATERAL (SELECT coalesce(b.verfolgung_tage, t.verfolgung_tage, talents_verfolgung_standard()) AS dauer,
                             coalesce(t.verfolgung_tage, talents_verfolgung_standard()) AS std,
                             talents_beitrag_art(b.art, b.produkt_art) = 'story' AS story,
                             coalesce(b.erstellt, b.erfasst_am) AS erst OFFSET 0) d0
  -- Beiträge einer Kampagne mindestens bis Kampagnenende (Stefan 18.10.2026)
  CROSS JOIN LATERAL (SELECT talents_kampagne_bis(b.id) AS kbis OFFSET 0) kb
  CROSS JOIN LATERAL (SELECT d0.*, kb.kbis, CASE WHEN d0.dauer > 0 THEN greatest(talents_tag(d0.erst) + d0.dauer, kb.kbis) END AS ende,
                             d0.dauer > 0 AND NOT d0.story AND coalesce(kb.kbis > talents_tag(d0.erst) + d0.dauer, false) AS kamp OFFSET 0) d
  CROSS JOIN LATERAL (SELECT CASE WHEN d.story THEN CASE WHEN b.abgeschlossen OR d.erst <= now() - interval '24 hours' THEN 'abgeschlossen' ELSE 'laeuft' END
                                  WHEN b.abgeschlossen THEN 'abgeschlossen'
                                  WHEN d.dauer = 0 THEN 'unbegrenzt'
                                  WHEN d.ende >= talents_heute() THEN 'laeuft'
                                  ELSE 'abgeschlossen' END AS stand OFFSET 0) x
  WHERE b.id = p_beitrag_id
$function$
;

CREATE OR REPLACE FUNCTION public.talents_verfolgung_standard()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN btrim(ally_einstellung('talents_verfolgung_tage')) ~ '^[0-9]{1,4}$'
    THEN least(btrim(ally_einstellung('talents_verfolgung_tage'))::integer, 3650) ELSE 30 END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_verlaengern_faellig(p_kanal_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM talent_kanaele k JOIN talents t ON t.id = k.talent_id AND NOT t.testdaten /* Testdaten (Migration 79) */
    WHERE k.id = p_kanal_id AND k.plattform = 'instagram' AND k.anmeldeweg = 'instagram' AND k.status = 'verbunden' AND t.status = 'aktiv'
      AND k.schluessel IS NOT NULL AND coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am) <= now() - interval '24 hours'
      AND (k.gueltig_bis IS NULL OR (k.gueltig_bis > now() AND k.gueltig_bis <= now() + interval '14 days')))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_verlaengern_liste()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  liste jsonb;
BEGIN
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', true, 'anzahl', 0, 'kanaele', '[]'::jsonb, 'hinweis', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Verschlüsselung ist nicht eingerichtet.', 'kanaele', '[]'::jsonb);
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('kanal_id', k.id, 'talent_id', k.talent_id, 'anzeigename', talent_anzeigename(k.talent_id),
      'ig_id', k.extern_id, 'ig_name', k.extern_name, 'adresse', 'https://graph.instagram.com/refresh_access_token',
      'schluessel', s.s, 'schluessel_fehler', s.s IS NULL, 'gueltig_bis', k.gueltig_bis, 'schluessel_seit', coalesce(k.geprueft_am, k.verbunden_am))
      ORDER BY k.gueltig_bis NULLS FIRST, k.id), '[]'::jsonb)
    INTO liste
  FROM talent_kanaele k
  CROSS JOIN LATERAL (SELECT talents_entschluesseln_still(k.schluessel) AS s) s
  WHERE talents_verlaengern_faellig(k.id);
  RETURN jsonb_build_object('ok', true, 'anzahl', jsonb_array_length(liste), 'kanaele', liste);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_verlaengern_speichern(p_kanal_id integer, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- p_daten: schluessel (neuer langlebiger Schlüssel), gueltig_bis (expires_in in Sekunden, Unix-Zeit oder ISO), berechtigungen (optional)
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  k talent_kanaele%ROWTYPE;
  sch text := d->>'schluessel';
  gb timestamptz;
BEGIN
  SELECT * INTO k FROM talent_kanaele WHERE id = p_kanal_id FOR UPDATE;
  IF k.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Kanal.');
  END IF;
  IF k.anmeldeweg IS DISTINCT FROM 'instagram' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Verlängern lassen sich nur Kanäle mit Instagram-Anmeldung.');
  END IF;
  IF k.status <> 'verbunden' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Dieser Kanal ist nicht verbunden.');
  END IF;
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  IF btrim(coalesce(sch, '')) = '' OR length(sch) > 4000 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Kein gültiger Zugangsschlüssel.');
  END IF;
  BEGIN
    gb := talents_gueltig_bis(d->>'gueltig_bis');
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Ungültiges Ablaufdatum.');
  END;
  UPDATE talent_kanaele SET schluessel = ally_verschluesseln(sch), gueltig_bis = gb, geprueft_am = now(),
    berechtigungen = CASE WHEN d ? 'berechtigungen' THEN talents_liste(d->'berechtigungen') ELSE berechtigungen END,
    geaendert_am = now()
  WHERE id = k.id;
  RETURN jsonb_build_object('ok', true, 'kanal_id', k.id, 'gueltig_bis', gb, 'gueltig_bis_text', talents_datum(gb));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false,
    'fehler', CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' THEN SQLERRM ELSE 'Technischer Fehler: ' || left(SQLERRM, 200) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_verwalten_liste(p_token text, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  c jsonb; u text; verw boolean; adm boolean;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  st text := lower(btrim(coalesce(f->>'status', '')));
  pe text := btrim(coalesce(f->>'person', ''));
  su text := lower(left(btrim(coalesce(f->>'suche', '')), 100));
  basis jsonb; anz integer; seite integer; je integer := 10; zeilen jsonb; n_sammel integer;
  frist integer := CASE WHEN btrim(coalesce(ally_einstellung('talents_loeschfrist_tage'), '')) ~ '^[0-9]{1,4}$' THEN btrim(ally_einstellung('talents_loeschfrist_tage'))::integer END;
BEGIN
  c := talents_ansicht_start(p_token);
  IF NOT (c->>'ok')::boolean THEN RETURN c; END IF;
  u := c->>'u'; verw := (c->>'verw')::boolean; adm := ally_hat_recht(u, 'admin');
  IF st NOT IN ('', 'verbunden', 'einladung_offen', 'einladung_abgelaufen', 'bald_ab', 'getrennt', 'archiviert') THEN st := ''; END IF;
  IF NOT verw OR NOT EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.matrix_user_id = pe) THEN pe := ''; END IF;
  -- sichtbare Talents mit Person und Suche, je Talent der Stand
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'status', t.status, 's', talents_talent_stand(t.id), 'n', lower(talent_listenname(t.id)))), '[]'::jsonb) INTO basis
  FROM talents t
  WHERE (verw OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u))
    AND (pe = '' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = pe))
    AND (su = '' OR position(su IN lower(concat_ws(' ', t.name, t.kuenstlername, t.email))) > 0
         OR EXISTS (SELECT 1 FROM talent_kanaele k WHERE k.talent_id = t.id AND position(ltrim(su, '@') IN lower(coalesce(k.extern_name, ''))) > 0));
  SELECT count(*)::integer INTO anz FROM jsonb_array_elements(basis) b
  WHERE CASE st WHEN '' THEN b->>'status' = 'aktiv' WHEN 'archiviert' THEN b->>'status' = 'archiviert' ELSE b->>'status' = 'aktiv' AND (b->'s'->>st)::boolean END;
  seite := talents_seite_nr(f->>'seite', anz, je);
  SELECT coalesce(jsonb_agg(jsonb_build_object('talent_id', t.id, 'anzeigename', talent_listenname(t.id), 'name_offen', talent_anzeigename(t.id) IS NULL,
      'email', t.email, 'status', t.status, 'archiviert', t.status = 'archiviert', 'stand', x.b->'s'->>'text', 'warnung', (x.b->'s'->>'warnung')::boolean,
      'kanaele', (SELECT coalesce(jsonb_agg(jsonb_build_object('kanal_id', k.id, 'plattform', k.plattform,
            'text', talents_plattform_name(k.plattform) || coalesce(' @' || nullif(ltrim(btrim(coalesce(k.extern_name, '')), '@'), ''), ''),
            'status', k.status, 'zeichen', CASE WHEN k.status = 'verbunden' AND k.gueltig_bis < now() + interval '7 days' THEN 'bald_ab' ELSE k.status END,
            'status_text', CASE WHEN k.status = 'verbunden' AND k.gueltig_bis < now() + interval '7 days' THEN 'läuft am ' || talents_datum(k.gueltig_bis) || ' ab'
                                WHEN k.status = 'verbunden' THEN 'verbunden' WHEN k.status = 'offen' THEN 'noch nicht verbunden'
                                WHEN k.status = 'abgelaufen' THEN 'Verbindung abgelaufen' ELSE 'getrennt' END)
          ORDER BY array_position(talents_plattformen(), k.plattform), k.extern_id IS NULL, lower(coalesce(k.extern_name, '')) COLLATE "C", k.id), '[]'::jsonb)
          FROM talent_kanaele k WHERE k.talent_id = t.id),
      'zustaendig', (SELECT string_agg(p.name, ', ' ORDER BY lower(p.name) COLLATE "C") FROM talent_personen tp JOIN ally_personen p ON p.matrix_user_id = tp.matrix_user_id WHERE tp.talent_id = t.id),
      'datenstand', (SELECT talents_zeit(max(k.letzter_abruf)) FROM talent_kanaele k WHERE k.talent_id = t.id),
      'einladung', CASE WHEN verw THEN (SELECT jsonb_build_object('link', talent_einladung_link(e.id), 'gueltig_bis', talents_datum(e.gueltig_bis))
                     FROM talent_einladungen e WHERE e.talent_id = t.id AND e.widerrufen_am IS NULL AND e.gueltig_bis > now() ORDER BY e.id DESC LIMIT 1) END,
      -- frühester Löschtermin (Stefan 19.10.2026, Migration 54): gilt auch ohne Chat als Ankündigung
      'loeschen_am', talents_datum(talents_loesch_frueheste(t.id))) ORDER BY x.o), '[]'::jsonb) INTO zeilen
  FROM (SELECT b, row_number() OVER (ORDER BY b->>'n' COLLATE "C", (b->>'id')::integer) AS o FROM jsonb_array_elements(basis) b
        WHERE CASE st WHEN '' THEN b->>'status' = 'aktiv' WHEN 'archiviert' THEN b->>'status' = 'archiviert' ELSE b->>'status' = 'aktiv' AND (b->'s'->>st)::boolean END) x
  JOIN talents t ON t.id = (x.b->>'id')::integer
  WHERE x.o > (seite - 1) * je AND x.o <= seite * je;
  SELECT count(*)::integer INTO n_sammel FROM talents t WHERE t.status = 'aktiv' AND (talents_talent_stand(t.id)->>'link_noetig')::boolean;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'zugriff', c->>'zugriff', 'darf_verwalten', verw, 'darf_loeschen', adm,
    'filter', jsonb_build_object('status', st, 'person', pe, 'suche', left(btrim(coalesce(f->>'suche', '')), 100), 'seite', seite),
    'zeilen', zeilen, 'anzahl', anz, 'seite', seite, 'seiten', greatest(1, ceil(anz / je::numeric)::integer), 'je_seite', je,
    'status_auswahl', (SELECT jsonb_agg(jsonb_build_object('schluessel', a.k, 'name', a.n,
        'anzahl', (SELECT count(*) FROM jsonb_array_elements(basis) b WHERE CASE a.k WHEN '' THEN b->>'status' = 'aktiv' WHEN 'archiviert' THEN b->>'status' = 'archiviert'
                                                                           ELSE b->>'status' = 'aktiv' AND (b->'s'->>a.k)::boolean END)) ORDER BY a.o)
      FROM (VALUES ('', 'Alle aktiven', 1), ('verbunden', 'Verbunden', 2), ('einladung_offen', 'Einladung offen', 3), ('einladung_abgelaufen', 'Einladung abgelaufen', 4),
                   ('bald_ab', 'Verbindung läuft bald ab', 5), ('getrennt', 'Verbindung abgelaufen oder getrennt', 6), ('archiviert', 'Archiviert', 7)) AS a(k, n, o)),
    'personen', CASE WHEN verw THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.matrix_user_id, 'name', p.name || CASE WHEN p.testdaten THEN ' (Testdaten)' ELSE '' END, 'ich', p.matrix_user_id = u) ORDER BY lower(p.name) COLLATE "C"), '[]'::jsonb)
        FROM ally_personen p WHERE p.aktiv AND EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.matrix_user_id = p.matrix_user_id)) ELSE '[]'::jsonb END,
    'auswahl', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'anzeigename', talent_listenname(t.id), 'archiviert', t.status = 'archiviert')
        ORDER BY t.status = 'archiviert', lower(talent_listenname(t.id)) COLLATE "C", t.id), '[]'::jsonb)
        FROM talents t WHERE verw OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u)),
    'sammel', CASE WHEN verw THEN jsonb_build_object('anzahl', n_sammel, 'knopf', 'Neue Links für abgelaufene Verbindungen und Einladungen',
        'text', CASE WHEN n_sammel = 0 THEN 'Keine Talents mit abgelaufener Verbindung oder abgelaufener Einladung.'
                     WHEN n_sammel = 1 THEN '1 Talent mit abgelaufener Verbindung oder Einladung. Ally erstellt einen neuen Link und stellt ihn als Tabelle bereit.'
                     ELSE n_sammel || ' Talents mit abgelaufener Verbindung oder Einladung. Ally erstellt je Talent einen neuen Link und stellt alle als Tabelle bereit.' END) END,
    'loeschfrist', jsonb_build_object('tage', frist, 'text', CASE WHEN frist IS NULL THEN 'Archivierte Talents werden nicht automatisch gelöscht.'
        ELSE 'Archivierte Talents werden frühestens ' || frist || ' Tage nach der Archivierung gelöscht und mindestens '
          || talents_einstellung_zahl('talents_loeschwarnung_tage', 1, 90, 14) || ' Tage vorher angekündigt: im Chat an die Admins und hier mit dem Löschtermin. '
          || 'Kommt die Chat-Nachricht nicht an, gilt der Termin hier als Ankündigung.' END),
    'leer_text', CASE WHEN anz > 0 THEN NULL WHEN jsonb_array_length(basis) = 0 AND st = '' AND pe = '' AND su = '' THEN
        CASE WHEN verw THEN 'Noch keine Talents. Lade das erste mit „Talent einladen“ ein.' ELSE 'Dir sind noch keine Talents zugeordnet.' END
      ELSE 'Keine Talents für diesen Filter.' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_fuellen(p_text text, p_name text, p_link text, p_bis text, p_agentur text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT regexp_replace(regexp_replace(regexp_replace(regexp_replace(
           CASE WHEN p_name IS NULL THEN regexp_replace(coalesce(p_text, ''), ' ?\[name\]', '', 'gi') ELSE coalesce(p_text, '') END,
           '\[name\]', replace(coalesce(p_name, ''), '\', '\\'), 'gi'),
           '\[link\]', replace(coalesce(p_link, ''), '\', '\\'), 'gi'),
           '\[gültig bis\]', replace(coalesce(p_bis, ''), '\', '\\'), 'gi'),
           '\[agentur\]', replace(coalesce(p_agentur, ''), '\', '\\'), 'gi')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_gelaufen(p_id integer, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
BEGIN
  UPDATE talent_bericht_vorlagen SET letzter_lauf = now(),
    letzter_bericht_id = CASE WHEN coalesce(d->>'bericht_id', '') ~ '^[0-9]{1,12}$' THEN (d->>'bericht_id')::bigint ELSE letzter_bericht_id END,
    letzter_fehler = CASE WHEN talents_bericht_ja(d->'ok', false) THEN NULL ELSE left(coalesce(nullif(btrim(d->>'fehler'), ''), 'Unbekannter Fehler.'), 500) END
  WHERE id = p_id;
  RETURN jsonb_build_object('ok', FOUND);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_intervall(p_plan text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_plan WHEN 'monatlich' THEN 'monat' WHEN 'woechentlich' THEN 'woche' ELSE 'aus' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_loeschen(p_user text, p_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb := talents_person_zugriff(p_user);
  n text;
BEGIN
  IF NOT (c->>'ok')::boolean THEN
    RETURN c;
  END IF;
  -- Migration 132: in den Papierkorb (Wiederherstellen und endgültig löschen: talents_vorlage_papierkorb)
  UPDATE talent_bericht_vorlagen v SET geloescht_am = now(), geloescht_von = p_user, geaendert_am = now()
  WHERE v.id = p_id AND v.geloescht_am IS NULL AND (v.erstellt_von = p_user OR (c->>'verw')::boolean) RETURNING v.name INTO n;
  IF n IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Vorlage gibt es nicht oder sie gehört einer anderen Person.');
  END IF;
  RETURN jsonb_build_object('ok', true, 'meldung', 'Vorlage „' || n || '“ liegt jetzt im Papierkorb. Ally erstellt damit keine Reports mehr. Bereits erstellte Reports bleiben erhalten. Im Papierkorb kannst du sie wiederherstellen oder endgültig löschen.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_naechster(p_plan text, p_heute date)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_plan WHEN 'monatlich' THEN (date_trunc('month', p_heute) + interval '1 month')::date
                     WHEN 'woechentlich' THEN p_heute + (8 - extract(isodow FROM p_heute)::integer) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_papierkorb(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  c jsonb := talents_ansicht_start(p_token);
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  u text; verw boolean; v talent_bericht_vorlagen%ROWTYPE;
  m text := NULL; fehler text := NULL; n integer := 0; heute date := talents_heute();
BEGIN
  -- Migration 132: Papierkorb der Vorlagen (Talent-Reports). Wer löschen darf, darf auch wiederherstellen und endgültig löschen.
  IF NOT coalesce((c->>'angemeldet')::boolean, (c->>'ok')::boolean, false) THEN RETURN jsonb_build_object('ok', false, 'angemeldet', false); END IF;
  IF NOT (c->>'ok')::boolean THEN
    PERFORM ally_web_meldung(p_token, coalesce(c->>'fehler', 'Das geht gerade nicht.'), 'fehler', NULL);
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := c->>'u'; verw := coalesce((c->>'verw')::boolean, false);
  IF p_aktion IN ('tr_vorlage_wiederherstellen', 'tr_vorlage_endgueltig') THEN
    IF coalesce(d->>'id', '') ~ '^[0-9]{1,9}$' THEN
      SELECT * INTO v FROM talent_bericht_vorlagen x WHERE x.id = (d->>'id')::integer AND (x.erstellt_von = u OR verw) FOR UPDATE;
    END IF;
    IF v.id IS NULL OR v.geloescht_am IS NULL THEN
      fehler := 'Diese Vorlage liegt nicht mehr im Papierkorb. Bitte die Seite neu laden.';
    ELSIF p_aktion = 'tr_vorlage_wiederherstellen' AND EXISTS (SELECT 1 FROM talent_bericht_vorlagen x WHERE x.erstellt_von = v.erstellt_von
        AND lower(x.name) = lower(v.name) AND x.id <> v.id AND x.geloescht_am IS NULL) THEN
      fehler := 'Eine Vorlage mit dem Namen „' || v.name || '“ gibt es inzwischen schon. Bitte die andere zuerst umbenennen.';
    ELSIF p_aktion = 'tr_vorlage_wiederherstellen' AND (SELECT count(*) FROM talent_bericht_vorlagen x WHERE x.erstellt_von = v.erstellt_von AND x.geloescht_am IS NULL) >= 50 THEN
      fehler := 'Es gibt schon 50 Vorlagen. Bitte zuerst eine nicht mehr benötigte in den Papierkorb legen.';
    ELSIF p_aktion = 'tr_vorlage_wiederherstellen' THEN
      UPDATE talent_bericht_vorlagen SET geloescht_am = NULL, geloescht_von = NULL, geaendert_am = now(),
        naechster_lauf = CASE WHEN intervall <> 'aus' AND (naechster_lauf IS NULL OR naechster_lauf < heute) THEN talents_vorlage_termin(intervall, intervall_tag, heute) ELSE naechster_lauf END
      WHERE id = v.id RETURNING * INTO v;
      m := 'Vorlage „' || v.name || '“ wiederhergestellt.' || CASE WHEN v.intervall <> 'aus' THEN ' Der nächste Report nach Plan entsteht am ' || to_char(v.naechster_lauf, 'FMDD.FMMM.YYYY') || '.' ELSE '' END;
    ELSE
      DELETE FROM talent_bericht_vorlagen WHERE id = v.id;
      m := 'Vorlage „' || v.name || '“ endgültig gelöscht. Bereits erstellte Reports bleiben erhalten.';
    END IF;
  ELSIF p_aktion = 'tr_vorlage_papierkorb_leeren' THEN
    IF coalesce(d->>'ids', '') !~ '^[0-9]{1,9}(,[0-9]{1,9})*$' OR cardinality(string_to_array(d->>'ids', ',')) > 1000 THEN
      fehler := 'Der Papierkorb hat sich geändert. Bitte die Seite neu laden.';
    ELSE
      DELETE FROM talent_bericht_vorlagen x WHERE x.id = ANY (string_to_array(d->>'ids', ',')::integer[]) AND x.geloescht_am IS NOT NULL AND x.erstellt_von = u;   -- nur die eigenen, wie angezeigt
      GET DIAGNOSTICS n = ROW_COUNT;
      m := CASE WHEN n = 0 THEN 'Diese Vorlagen liegen nicht mehr im Papierkorb.' WHEN n = 1 THEN '1 Vorlage endgültig gelöscht.' ELSE n || ' Vorlagen endgültig gelöscht.' END
        || CASE WHEN n > 0 THEN ' Bereits erstellte Reports bleiben erhalten.' ELSE '' END;
    END IF;
  ELSE
    fehler := 'Diese Aktion gibt es nicht.';
  END IF;
  PERFORM ally_web_meldung(p_token, coalesce(fehler, m), CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END, NULL);
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_plan(p_intervall text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_intervall WHEN 'monat' THEN 'monatlich' WHEN 'woche' THEN 'woechentlich' ELSE 'aus' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_plan_text(p_plan text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_plan WHEN 'monatlich' THEN 'jeden Monatsersten (über den Vormonat)' WHEN 'woechentlich' THEN 'jeden Montag (über die letzten 7 Tage)'
                     ELSE 'nur auf Klick' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_speichern(p_user text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  c jsonb := talents_person_zugriff(p_user);
  n text := left(btrim(regexp_replace(coalesce(d->>'name', ''), '[[:cntrl:]]', ' ', 'g')), 81);
  pl text := coalesce(nullif(lower(btrim(coalesce(d->>'plan', ''))), ''), 'aus');
  r jsonb;
  a jsonb;
  v_id integer;
BEGIN
  IF NOT (c->>'ok')::boolean THEN
    RETURN c;
  END IF;
  IF n = '' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Bitte einen Namen für die Vorlage angeben.');
  ELSIF length(n) > 80 THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Der Name der Vorlage darf höchstens 80 Zeichen haben.');
  END IF;
  IF pl NOT IN ('aus', 'monatlich', 'woechentlich') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannte Wiederholung. Bitte die Seite neu laden.');
  END IF;
  a := CASE WHEN jsonb_typeof(d->'auftrag') = 'object' THEN d->'auftrag' ELSE '{}'::jsonb END;
  IF pl <> 'aus' THEN
    IF a->>'art' = 'kampagne' THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Kampagnenberichte lassen sich nicht regelmäßig erstellen (die Kampagne hat einen festen Zeitraum).');
    END IF;
    a := (a - 'monat' - 'von' - 'bis') || jsonb_build_object('zeitraum', CASE pl WHEN 'monatlich' THEN 'vormonat' ELSE '7tage' END);
  END IF;
  r := talents_bericht_auftrag(p_user, a);
  IF NOT (r->>'ok')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'fehler', r->>'fehler');
  END IF;
  IF coalesce(d->>'id', '') ~ '^[0-9]{1,9}$' THEN
    UPDATE talent_bericht_vorlagen SET name = n, art = r->'auftrag'->>'art', auftrag = r->'auftrag',
      -- Migration 176 (B11c, Zeitplan der Reports): Zeitplan als intervall und intervall_tag (Tag 1: Montag bzw. Monatserster)
      intervall = talents_vorlage_intervall(pl), intervall_tag = CASE WHEN pl = 'aus' THEN NULL ELSE 1 END,
      naechster_lauf = CASE WHEN pl = 'aus' THEN NULL WHEN intervall = talents_vorlage_intervall(pl) AND naechster_lauf IS NOT NULL THEN naechster_lauf ELSE talents_vorlage_termin(talents_vorlage_intervall(pl), 1::smallint, talents_heute()) END,
      letzter_fehler = NULL, geaendert_am = now()
    WHERE id = (d->>'id')::integer AND erstellt_von = p_user AND geloescht_am IS NULL
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Diese Vorlage gibt es nicht oder sie gehört einer anderen Person.');
    END IF;
  ELSE
    IF (SELECT count(*) FROM talent_bericht_vorlagen WHERE erstellt_von = p_user AND geloescht_am IS NULL) >= 50 THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Du hast schon 50 Vorlagen. Bitte zuerst nicht mehr benötigte in den Papierkorb legen.');
    END IF;
    INSERT INTO talent_bericht_vorlagen (name, art, auftrag, intervall, intervall_tag, naechster_lauf, erstellt_von)
    VALUES (n, r->'auftrag'->>'art', r->'auftrag', talents_vorlage_intervall(pl), CASE WHEN pl = 'aus' THEN NULL ELSE 1 END,
      CASE WHEN pl <> 'aus' THEN talents_vorlage_termin(talents_vorlage_intervall(pl), 1::smallint, talents_heute()) END, p_user)
    RETURNING id INTO v_id;
  END IF;
  RETURN jsonb_build_object('ok', true, 'id', v_id,
    'meldung', 'Vorlage „' || n || '“ gespeichert.' || CASE WHEN pl <> 'aus' THEN ' Ally erstellt den Bericht ' || talents_vorlage_plan_text(pl) || ', zuerst am '
      || to_char((SELECT naechster_lauf FROM talent_bericht_vorlagen WHERE id = v_id), 'DD.MM.YYYY') || '. Er liegt dann im Speicherort und unter Reports; verschickt wird nichts.' ELSE '' END);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('ok', false, 'fehler', 'Eine Vorlage mit diesem Namen gibt es schon.');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlage_termin(p_intervall text, p_tag smallint, p_heute date)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE i integer; m date; t date;
BEGIN
  IF p_intervall = 'woche' AND p_tag BETWEEN 1 AND 7 THEN
    RETURN p_heute + (((p_tag - extract(isodow FROM p_heute)::integer + 6) % 7) + 1);
  ELSIF p_intervall = 'monat' AND p_tag BETWEEN 0 AND 28 THEN
    FOR i IN 0..2 LOOP
      m := (date_trunc('month', p_heute) + make_interval(months => i))::date;
      t := CASE WHEN p_tag = 0 THEN (m + interval '1 month' - interval '1 day')::date ELSE m + (p_tag - 1) END;
      IF t > p_heute THEN RETURN t; END IF;
    END LOOP;
  END IF;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlagen_faellig()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  heute date := talents_heute();
  r jsonb;
BEGIN
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', true, 'anzahl', 0, 'vorlagen', '[]'::jsonb, 'hinweis', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  WITH f AS (
    SELECT v.id FROM talent_bericht_vorlagen v WHERE v.intervall <> 'aus' AND v.naechster_lauf <= heute AND v.geloescht_am IS NULL AND NOT ally_person_ist_testdaten(v.erstellt_von) ORDER BY v.naechster_lauf, v.id LIMIT 20 FOR UPDATE SKIP LOCKED),
  u AS (
    UPDATE talent_bericht_vorlagen v SET naechster_lauf = talents_vorlage_termin(v.intervall, v.intervall_tag, heute), letzter_lauf = now()
    FROM f WHERE v.id = f.id
    RETURNING v.id, v.name, v.erstellt_von, talents_vorlage_plan(v.intervall) AS plan, v.auftrag)
  SELECT coalesce(jsonb_agg(jsonb_build_object('vorlage_id', u.id, 'name', u.name, 'nutzer', u.erstellt_von,
      'auftrag', (u.auftrag - 'zeitraum') || jsonb_build_object('zeitraum', CASE u.plan WHEN 'monatlich' THEN 'vormonat' ELSE '7tage' END)) ORDER BY u.id), '[]'::jsonb)
    INTO r FROM u;
  RETURN jsonb_build_object('ok', true, 'anzahl', jsonb_array_length(r), 'vorlagen', r);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorlagen_liste(p_user text, p_seite integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  je constant integer := 10;
  anzahl integer;
  seiten integer;
  s integer;
BEGIN
  SELECT count(*) INTO anzahl FROM talent_bericht_vorlagen WHERE erstellt_von = p_user AND geloescht_am IS NULL;
  seiten := greatest(1, ceil(anzahl / je::numeric)::integer);
  s := least(greatest(coalesce(p_seite, 1), 1), seiten);
  RETURN jsonb_build_object('anzahl', anzahl, 'seite', s, 'seiten', seiten, 'je_seite', je,
    'leer_text', CASE WHEN anzahl = 0 THEN 'Noch keine Vorlagen. Eine Zusammenstellung speicherst du beim Erstellen mit „Als Vorlage speichern“.' END,
    'zeilen', coalesce((SELECT jsonb_agg(jsonb_build_object('id', v.id, 'name', v.name, 'art', v.art,
        'art_name', (SELECT e->>'name' FROM jsonb_array_elements(talents_bericht_arten()) e WHERE e->>'schluessel' = v.art),
        'plan', talents_vorlage_plan(v.intervall), 'plan_text', talents_vorlage_plan_text(talents_vorlage_plan(v.intervall)),
        'naechster_text', CASE WHEN v.intervall <> 'aus' THEN 'nächster Bericht am ' || to_char(v.naechster_lauf, 'DD.MM.YYYY') END,
        'letzter_text', CASE WHEN v.letzter_lauf IS NOT NULL THEN 'zuletzt ' || talents_zeit(v.letzter_lauf) END,
        'letzter_fehler', v.letzter_fehler,
        'talents_text', (SELECT string_agg(talent_listenname(i::integer), ', ' ORDER BY o) FROM jsonb_array_elements_text(v.auftrag->'talents') WITH ORDINALITY x(i, o)),
        'bausteine_text', (SELECT string_agg(e->>'name', ', ' ORDER BY o) FROM jsonb_array_elements(talents_bericht_bausteine()) WITH ORDINALITY y(e, o)
                           WHERE v.auftrag->'bausteine' ? (e->>'schluessel') AND e->>'schluessel' NOT IN ('profil', 'beispiele')),
        'zeitraum', v.auftrag->'zeitraum'->>'zeitraum',
        'auftrag', v.auftrag) ORDER BY lower(v.name), v.id)
      FROM (SELECT * FROM talent_bericht_vorlagen WHERE erstellt_von = p_user AND geloescht_am IS NULL ORDER BY lower(name), id OFFSET (s - 1) * je LIMIT je) v), '[]'::jsonb));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorrat_staende()
 RETURNS TABLE(talent_id integer, kids integer[], stand text)
 LANGUAGE sql
 STABLE
AS $function$
  WITH f AS (SELECT count(*) || ':' || coalesce(sum(p.xmin::text::bigint), 0) AS s FROM pg_proc p
             WHERE p.pronamespace = 'public'::regnamespace AND p.proname = ANY (ARRAY['talents_zahlen', 'talents_zahl', 'talents_aufrufe', 'talents_interaktionen', 'talents_doppelt_status', 'talents_manuell_kanaele', 'talents_manuell_signatur', 'talents_manuell_ueberschneidung', 'talents_manuell_zeitraum_text', 'talents_plattform_name', 'talents_konto_text', 'talents_tageswert'])),
  kt AS (SELECT kt.kanal_id, count(*) AS n, sum(kt.xmin::text::bigint) AS x, sum(((kt.ctid::text::point)[0] * 65536 + (kt.ctid::text::point)[1])::bigint) AS c
         FROM talent_kanal_tage kt GROUP BY kt.kanal_id),
  k AS (SELECT k.talent_id, array_agg(k.id ORDER BY k.id) AS kids, count(*) AS n, sum(k.xmin::text::bigint) AS x,
               sum(((k.ctid::text::point)[0] * 65536 + (k.ctid::text::point)[1])::bigint) AS c,
               sum(coalesce(kt.n, 0)) AS tn, sum(coalesce(kt.x, 0)) AS tx, sum(coalesce(kt.c, 0)) AS tc
        FROM talent_kanaele k LEFT JOIN kt ON kt.kanal_id = k.id GROUP BY k.talent_id),
  m AS (SELECT m.talent_id, count(*) AS n, sum(m.xmin::text::bigint) AS x, sum(((m.ctid::text::point)[0] * 65536 + (m.ctid::text::point)[1])::bigint) AS c
        FROM talent_manuell_werte m GROUP BY m.talent_id),
  d AS (SELECT m.talent_id, count(*) AS n, sum(d.xmin::text::bigint) AS x, sum(((d.ctid::text::point)[0] * 65536 + (d.ctid::text::point)[1])::bigint) AS c
        FROM talent_doppelt_entscheidungen d JOIN talent_manuell_werte m ON m.id = d.manuell_id GROUP BY m.talent_id)
  SELECT t.id, coalesce(k.kids, '{}'::integer[]),
         md5(concat_ws('|', coalesce(k.kids, '{}'::integer[])::text, coalesce(k.n, 0), coalesce(k.x, 0), coalesce(k.c, 0),
                       coalesce(k.tn, 0), coalesce(k.tx, 0), coalesce(k.tc, 0), coalesce(m.n, 0), coalesce(m.x, 0), coalesce(m.c, 0),
                       coalesce(d.n, 0), coalesce(d.x, 0), coalesce(d.c, 0), f.s))
  FROM talents t CROSS JOIN f
  LEFT JOIN k ON k.talent_id = t.id LEFT JOIN m ON m.talent_id = t.id LEFT JOIN d ON d.talent_id = t.id
  WHERE t.status = 'aktiv'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorschau(p_url text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Testdaten (Migration 79): Platzhalter-Bilder der Testdaten als SVG-data-Adresse
  -- Migration 151 (Punkt 2j): keine Video- oder Stream-Adressen (z. B. .mp4); abgelaufene Meta-CDN-Adressen (oe) wie bisher NULL
  SELECT CASE WHEN p_url ~ '^data:image/svg[+]xml;base64,[A-Za-z0-9+/]+={0,2}$' AND length(p_url) <= 8000 THEN p_url
              WHEN p_url IS NULL OR p_url !~ '^https://[^[:space:]]+$' THEN NULL
              WHEN talents_vorschau_kein_bild(p_url) THEN NULL
              WHEN talents_vorschau_ablauf(p_url) <= now() THEN NULL
              ELSE p_url END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorschau_ablauf(p_url text)
 RETURNS timestamp with time zone
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 151 (Punkt 2j): Ablaufzeit einer Meta-CDN-Adresse (Parameter oe, Unix-Zeit hexadezimal); ohne oe NULL
  SELECT CASE WHEN p_url ~ '[?&]oe=[0-9A-Fa-f]{8}([&#]|$)'
    THEN to_timestamp(('x' || lpad(substring(p_url FROM '[?&]oe=([0-9A-Fa-f]{8})'), 16, '0'))::bit(64)::bigint) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorschau_auffrischen(p_kanal_id integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 151 (Stefan/Koordinator 25.10.2026, Punkt 2j): Bildadressen eines Kanals neu holen (vollständige Beitragsliste), wenn ein
  -- vorhandener Beitrag (ohne Storys, nicht als nicht mehr vorhanden vermerkt) eine Meta-CDN-Adresse hat, die abgelaufen ist oder in den
  -- nächsten 48 Stunden abläuft. Gespeichert werden nur Adressen, keine Bilder.
  SELECT EXISTS (SELECT 1 FROM talent_beitraege b
    WHERE b.kanal_id = p_kanal_id AND b.nicht_mehr_vorhanden_seit IS NULL
      AND coalesce(b.art, '') <> 'STORY' AND coalesce(b.produkt_art, '') <> 'STORY'
      AND talents_vorschau_ablauf(b.vorschau_url) <= now() + interval '48 hours')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorschau_bild_offen(p_kanal_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 193 (Stefan 01.11.2026, „Bild speichern“): Storys eines Instagram-Kanals ohne gespeichertes Vorschaubild, deren Meta-CDN-Adresse noch gilt
  -- (Parameter oe in der Zukunft; ohne oe nicht, damit nichts endlos neu versucht wird). TALENTS 2 lädt sie im selben Lauf wie den Abruf und speichert sie
  -- einmal (talents_vorschau_bild_speichern). Nur Bildadressen von Meta (cdninstagram.com, fbcdn.net), keine Video-Adressen; höchstens 30, neueste zuerst.
  SELECT coalesce(jsonb_agg(jsonb_build_object('beitrag_id', x.id, 'url', x.vorschau_url) ORDER BY x.o), '[]'::jsonb)
  FROM (SELECT b.id, b.vorschau_url, row_number() OVER (ORDER BY coalesce(b.erstellt, b.erfasst_am) DESC, b.id DESC) AS o
        FROM talent_beitraege b JOIN talent_kanaele k ON k.id = b.kanal_id
        WHERE b.kanal_id = p_kanal_id AND k.plattform = 'instagram'
          AND (coalesce(b.art, '') = 'STORY' OR coalesce(b.produkt_art, '') = 'STORY')
          AND NOT EXISTS (SELECT 1 FROM talent_beitrag_bilder bb WHERE bb.beitrag_id = b.id)
          AND length(b.vorschau_url) <= 2000
          AND b.vorschau_url ~ '^https://([A-Za-z0-9-]+[.])*(cdninstagram[.]com|fbcdn[.]net)/[^[:space:]]*$'
          AND NOT talents_vorschau_kein_bild(b.vorschau_url)
          AND talents_vorschau_ablauf(b.vorschau_url) > now()
        ORDER BY coalesce(b.erstellt, b.erfasst_am) DESC, b.id DESC LIMIT 30) x
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorschau_bild_speichern(p_beitrag_id bigint, p_kanal_id integer, p_b64 text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  roh bytea; w_mime text; n integer;
BEGIN
  -- Migration 193 (Stefan 01.11.2026, „Bild speichern“): Vorschaubild einer Instagram-Story einmal und dauerhaft speichern (TALENTS 2, gleicher Lauf wie der
  -- Abruf). Wie ally_cd_dateien: base64; TALENTS 2 verkleinert vorher (480 px, JPEG), hier höchstens 150 KB; nur JPEG oder PNG (Dateikopf geprüft).
  -- Ein vorhandenes Bild bleibt (das erste gilt).
  -- Wirft nie einen Fehler: ohne gespeichertes Bild bleibt es bei der Adresse wie bisher, der Lauf geht weiter.
  IF p_b64 IS NULL OR p_b64 = '' OR length(p_b64) > 204808 OR length(p_b64) % 4 <> 0 OR p_b64 !~ '^[A-Za-z0-9+/]+={0,2}$' THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'daten');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM talent_beitraege b JOIN talent_kanaele k ON k.id = b.kanal_id
                 WHERE b.id = p_beitrag_id AND b.kanal_id = p_kanal_id AND k.plattform = 'instagram'
                   AND (coalesce(b.art, '') = 'STORY' OR coalesce(b.produkt_art, '') = 'STORY')) THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'beitrag');
  END IF;
  roh := decode(p_b64, 'base64');
  IF length(roh) < 1 OR length(roh) > 153600 THEN
    RETURN jsonb_build_object('ok', false, 'grund', 'groesse');
  ELSIF substring(roh FROM 1 FOR 3) = '\xffd8ff'::bytea THEN
    w_mime := 'image/jpeg';
  ELSIF substring(roh FROM 1 FOR 8) = '\x89504e470d0a1a0a'::bytea THEN
    w_mime := 'image/png';
  ELSE
    RETURN jsonb_build_object('ok', false, 'grund', 'art');
  END IF;
  INSERT INTO talent_beitrag_bilder (beitrag_id, mime, daten, groesse) VALUES (p_beitrag_id, w_mime, p_b64, length(roh))
  ON CONFLICT (beitrag_id) DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'neu', n = 1, 'groesse', length(roh));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'grund', 'fehler');
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_vorschau_kein_bild(p_url text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Migration 151 (Punkt 2j): Adressen von Videos und Streams (Dateiendung im Pfad, ohne Parameter) sind kein Vorschaubild
  SELECT coalesce(substring(p_url FROM '^[^?#]*') ~* '[.](mp4|m4v|mov|webm|mkv|avi|wmv|flv|3gp|m3u8|mpd|ts)$', false)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_vorzeichen_text(p numeric)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN p IS NULL THEN '–' WHEN round(p) > 0 THEN '+' || talents_zahl_text(p)
              WHEN round(p) < 0 THEN '−' || talents_zahl_text(abs(p)) ELSE '0' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_warnung_empfaenger(p_talent_id integer, p_schalter text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH z AS (SELECT n.matrix_user_id, n.room_id, n.anzeigename FROM talent_personen tp JOIN ally_nutzer n ON n.matrix_user_id = tp.matrix_user_id
             WHERE tp.talent_id = p_talent_id AND n.room_id IS NOT NULL AND talents_zugriff(n.matrix_user_id) IS NOT NULL
               AND ally_funktion_an(n.matrix_user_id, p_schalter)),
  a AS (SELECT n.matrix_user_id, n.room_id, n.anzeigename FROM ally_nutzer n
        WHERE n.room_id IS NOT NULL AND EXISTS (SELECT 1 FROM ally_nutzer_rechte r WHERE r.matrix_user_id = n.matrix_user_id AND r.recht = 'admin')
          AND ally_hat_recht(n.matrix_user_id, 'admin') AND ally_funktion_an(n.matrix_user_id, p_schalter)),
  s AS (SELECT n.matrix_user_id, n.room_id, n.anzeigename FROM ally_nutzer n
        WHERE n.room_id IS NOT NULL AND ally_hat_recht(n.matrix_user_id, 'admin') AND ally_funktion_an(n.matrix_user_id, p_schalter)),
  e AS (SELECT * FROM z
        UNION SELECT * FROM a WHERE NOT EXISTS (SELECT 1 FROM z)
        UNION SELECT * FROM s WHERE NOT EXISTS (SELECT 1 FROM z) AND NOT EXISTS (SELECT 1 FROM a))
  SELECT coalesce(jsonb_agg(jsonb_build_object('user_id', e.matrix_user_id, 'room_id', e.room_id, 'name', e.anzeigename) ORDER BY e.anzeigename, e.matrix_user_id), '[]'::jsonb)
  FROM e WHERE NOT talents_ist_testdaten(p_talent_id)  -- Testdaten (Migration 79): keine Empfänger für Test-Talents
$function$
;

CREATE OR REPLACE FUNCTION public.talents_warnung_gemeldet(p_kanal_id integer, p_ereignis text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n integer;
  tid text;
BEGIN
  IF coalesce(p_ereignis, '') !~ '^[a-z_]{1,30}:[0-9A-Za-z]{1,40}$' THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Ungültiges Ereignis.');
  END IF;
  -- Warnungen je Talent (kanal_id leer): das Talent steht im Ereignis (kampagne_fehlt:k<id>t<talent>, loeschfrist:t<talent>a<zeit>) (Stefan 18.10.2026)
  IF p_kanal_id IS NULL THEN
    tid := substring(p_ereignis FROM '^(?:kampagne_fehlt:k[0-9]+t|loeschfrist:t)([0-9]{1,9})');
    IF tid IS NULL OR NOT EXISTS (SELECT 1 FROM talents WHERE id = tid::integer) THEN
      RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekanntes Talent.');
    END IF;
    INSERT INTO talent_meldungen_talent (talent_id, ereignis) VALUES (tid::integer, p_ereignis) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS n = ROW_COUNT;
    RETURN jsonb_build_object('ok', true, 'neu', n > 0);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM talent_kanaele WHERE id = p_kanal_id) THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Kanal.');
  END IF;
  INSERT INTO talent_meldungen (kanal_id, ereignis) VALUES (p_kanal_id, p_ereignis) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'neu', n > 0);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_warnungen()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH k AS (
    SELECT k.*, t.status AS t_status, coalesce(talent_anzeigename(k.talent_id), '@' || nullif(ltrim(btrim(k.extern_name), '@'), ''), 'Talent Nr. ' || k.talent_id) AS anz, talents_kanal_text(k.plattform, k.extern_name) AS kt
    FROM talent_kanaele k JOIN talents t ON t.id = k.talent_id
    WHERE t.status = 'aktiv' AND plattform_modul_an('talents')),
  w AS (
    SELECT k.id AS kanal_id, k.talent_id, 'ablauf_bald' AS art, 'talents_verbindung' AS schalter,
      'ablauf_bald:' || to_char(k.gueltig_bis AT TIME ZONE 'Europe/Berlin', 'YYYYMMDD') AS ereignis,
      'Talents: Verbindung läuft bald ab' AS titel,
      'Die Verbindung von ' || k.anz || ' zu ' || k.kt || ' läuft am ' || talents_datum(k.gueltig_bis) || ' ab. Danach kann ' || produkt_name()
        || ' für diesen Kanal keine neuen Zahlen mehr abrufen. Im Talent-Profil kannst du über das Zahnrad unter „Accounts und Verbindungen“ in ' || produkt_name()
        || ' einen neuen Einladungslink erzeugen und an ' || k.anz || ' schicken; mit der neuen Anmeldung gilt die Verbindung wieder für '
        || CASE WHEN k.plattform = 'tiktok' THEN 'etwa ein Jahr' ELSE 'etwa 60 Tage' END || '.' AS text,
      1 AS rang, NULL::integer AS kampagne_id
    FROM k WHERE k.status = 'verbunden' AND k.gueltig_bis > now() AND k.gueltig_bis <= now() + interval '7 days'
    UNION ALL
    SELECT k.id, k.talent_id, 'abgelaufen', 'talents_verbindung',
      'abgelaufen:' || to_char(coalesce(k.verbunden_am, k.erstellt_am) AT TIME ZONE 'UTC', 'YYYYMMDDHH24MISS'),
      'Talents: Verbindung abgelaufen',
      'Die Verbindung von ' || k.anz || ' zu ' || k.kt || ' ist abgelaufen oder wurde aufgehoben'
        || CASE WHEN k.gueltig_bis IS NOT NULL AND k.gueltig_bis <= now() THEN ' (gültig bis ' || talents_datum(k.gueltig_bis) || ')' ELSE '' END
        || '. ' || produkt_name() || ' ruft für diesen Kanal keine neuen Zahlen mehr ab; die bisher gespeicherten Zahlen bleiben erhalten. '
        || 'Im Talent-Profil kannst du über das Zahnrad unter „Accounts und Verbindungen“ in ' || produkt_name() || ' einen neuen Einladungslink erzeugen und an ' || k.anz || ' schicken.',
      0, NULL
    FROM k WHERE k.status = 'abgelaufen'
    UNION ALL
    SELECT k.id, k.talent_id, 'einbruch', 'talents_einbruch',
      'einbruch:' || to_char(talents_heute(), 'IYYY') || 'w' || to_char(talents_heute(), 'IW'),
      'Talents: starker Einbruch',
      'Starker Einbruch bei ' || k.anz || ' auf ' || k.kt || ' (' || to_char((e.x->>'von')::date, 'DD.MM.YYYY') || ' bis ' || to_char((e.x->>'bis')::date, 'DD.MM.YYYY') || '): '
        || concat_ws(' ',
             CASE WHEN (e.x->'reichweite'->>'einbruch')::boolean THEN 'Die Reichweite lag im Schnitt bei ' || talents_zahl_text((e.x->'reichweite'->>'schnitt_7')::numeric)
               || ' pro Tag, ' || (e.x->'reichweite'->>'minus_prozent') || ' % unter dem Schnitt der 4 Wochen davor (' || talents_zahl_text((e.x->'reichweite'->>'schnitt_28')::numeric) || ' pro Tag).' END,
             CASE WHEN (e.x->'interaktionen'->>'einbruch')::boolean THEN 'Die Interaktionen lagen im Schnitt bei ' || talents_zahl_text((e.x->'interaktionen'->>'schnitt_7')::numeric)
               || ' pro Tag, ' || (e.x->'interaktionen'->>'minus_prozent') || ' % unter dem Schnitt der 4 Wochen davor (' || talents_zahl_text((e.x->'interaktionen'->>'schnitt_28')::numeric) || ' pro Tag).' END)
        || ' Abschalten lässt sich diese Warnung in ' || produkt_name() || ' unter Einstellungen › Mein Konto › Benachrichtigungen.',
      2, NULL
    FROM k CROSS JOIN LATERAL (SELECT talents_einbruch(k.id) AS x) e
    WHERE k.status = 'verbunden' AND (e.x->>'einbruch')::boolean
    UNION ALL
    -- Kampagnenbeitrag fehlt: Kampagne läuft und endet in höchstens N Tagen, Talent ohne zugeordneten oder vorgeschlagenen Beitrag (Stefan 18.10.2026)
    SELECT NULL::integer, kt.talent_id, 'kampagne_fehlt', 'talents_kampagne', 'kampagne_fehlt:k' || ka.id || 't' || kt.talent_id,
      'Talents: Kampagnenbeitrag fehlt',
      'Für die Kampagne „' || ka.name || '“ (' || ka.marke || ', ' || to_char(ka.von, 'DD.MM.YYYY') || ' bis ' || to_char(ka.bis, 'DD.MM.YYYY') || ') ist bei '
        || coalesce(talent_anzeigename(kt.talent_id), 'Talent Nr. ' || kt.talent_id) || ' noch kein Beitrag zugeordnet. Unter Talents › Kampagnen kannst du in '
        || produkt_name() || ' Vorschläge bestätigen oder den Beitrag selbst zuordnen. Abschalten lässt sich diese Warnung in ' || produkt_name()
        || ' unter Einstellungen › Mein Konto › Benachrichtigungen.',
      3, ka.id
    FROM talent_kampagnen ka JOIN talent_kampagne_talents kt ON kt.kampagne_id = ka.id JOIN talents tt ON tt.id = kt.talent_id
    WHERE tt.status = 'aktiv' AND plattform_modul_an('talents') AND ka.von <= talents_heute() AND ka.bis >= talents_heute()
      AND talents_heute() >= ka.bis - talents_einstellung_zahl('talents_kampagne_warnung_tage', 0, 60, 3)
      AND NOT EXISTS (SELECT 1 FROM talent_kampagne_beitraege kb JOIN talent_beitraege b ON b.id = kb.beitrag_id JOIN talent_kanaele c ON c.id = b.kanal_id
                      WHERE kb.kampagne_id = ka.id AND kb.status IN ('bestaetigt', 'vorschlag') AND c.talent_id = kt.talent_id)
      -- Talents mit Deliverables in dieser Kampagne: dafür gelten die Erinnerungsregeln (Migration 61), keine zweite Meldung
      AND NOT EXISTS (SELECT 1 FROM talent_deliverables dl WHERE dl.kampagne_id = ka.id AND dl.talent_id = kt.talent_id)
    UNION ALL
    -- Löschfrist: Ankündigung an die Admins (ohne Schalter) vor dem endgültigen Löschen archivierter Talents (Stefan 18.10.2026)
    SELECT NULL::integer, tt.id, 'loeschfrist', NULL, talents_loesch_ereignis(tt.id), 'Talents: Daten werden bald gelöscht',
      'Die Daten von ' || coalesce(talent_anzeigename(tt.id), 'Talent Nr. ' || tt.id) || ' (in den Papierkorb gelegt am ' || talents_datum(tt.archiviert_am)
        || ') werden nach der Löschfrist der Agentur am ' || talents_datum(talents_loesch_termin(tt.id)) || ' endgültig gelöscht, mit allen gespeicherten Zahlen, '
        || 'Beiträgen, Notizen und Kampagnen-Zuordnungen. Wer sie aufbewahren muss, exportiert sie vorher: '
        || coalesce(talent_ui_adresse() || '?seite=talent&id=' || tt.id, talents_seite_adresse('ansicht=einstellungen&bereich=talents&talent=' || tt.id)) || ' (Aktionen › Export (ZIP)). Soll das Talent bleiben, dort unter Aktionen › Wiederherstellen wählen.',
      4, NULL
    FROM talents tt WHERE tt.status = 'archiviert' AND plattform_modul_an('talents') AND talents_loesch_termin(tt.id) IS NOT NULL
      AND now() >= talents_loesch_termin(tt.id) - make_interval(days => talents_einstellung_zahl('talents_loeschwarnung_tage', 1, 90, 14))
    UNION ALL
    -- YouTube ohne bestätigte Berechtigung: sofort Ankündigung an die Admins (ohne Schalter), Löschung der YouTube-Daten am Tag 30 (Stefan 18.10.2026)
    SELECT y.kanal_id, y.talent_id, 'youtube_berechtigung', NULL, 'youtube_berechtigung:k' || y.kanal_id || 'd' || to_char(talents_tag(y.basis), 'YYYYMMDD'),
      'Talents: YouTube-Daten werden gelöscht',
      'Der YouTube-Kanal ' || coalesce(nullif(btrim(ky.extern_name), ''), 'Nr. ' || y.kanal_id) || ' von ' || coalesce(talent_anzeigename(y.talent_id), 'Talent Nr. ' || y.talent_id)
        || ' hat keine bestätigte Berechtigung mehr (' || CASE y.status WHEN 'getrennt' THEN 'Verbindung getrennt' WHEN 'abgelaufen' THEN 'Verbindung abgelaufen'
             ELSE 'zuletzt bestätigt am ' || talents_datum(y.basis) END || '). Nach den YouTube-Richtlinien löscht ' || produkt_name() || ' am '
        || to_char(y.loeschen_am, 'DD.MM.YYYY') || ' die gespeicherten YouTube-Zahlen, Videos und Zuschauer-Angaben dieses Kanals, wenn der Kanal bis dahin nicht neu verbunden ist. '
        || 'Neu verbinden: im Talent-Profil über das Zahnrad unter „Accounts und Verbindungen“ einen neuen Einladungslink erzeugen und an das Talent schicken. Diese Löschung ist eine Pflicht und lässt sich nicht abschalten.',
      5, NULL
    FROM talents_youtube_unbestaetigt() y JOIN talent_kanaele ky ON ky.id = y.kanal_id WHERE y.loeschen_am > talents_heute()),
  f AS (
    SELECT w.*, CASE WHEN w.art IN ('loeschfrist', 'youtube_berechtigung') THEN talents_admin_empfaenger() ELSE talents_warnung_empfaenger(w.talent_id, w.schalter) END AS empfaenger FROM w
    WHERE NOT talents_ist_testdaten(w.talent_id)  -- Testdaten (Migration 79)
      AND NOT EXISTS (SELECT 1 FROM talent_meldungen m WHERE m.kanal_id = w.kanal_id AND m.ereignis = w.ereignis)
      AND NOT EXISTS (SELECT 1 FROM talent_meldungen_talent mt WHERE w.kanal_id IS NULL AND mt.talent_id = w.talent_id AND mt.ereignis = w.ereignis))
  SELECT jsonb_build_object('ok', true, 'anzahl', count(*) FILTER (WHERE jsonb_array_length(f.empfaenger) > 0),
    'warnungen', coalesce(jsonb_agg(jsonb_build_object('kanal_id', f.kanal_id, 'talent_id', f.talent_id, 'art', f.art, 'ereignis', f.ereignis,
        'titel', f.titel, 'text', f.text, 'empfaenger', f.empfaenger, 'kampagne_id', f.kampagne_id) ORDER BY f.rang, f.kanal_id, f.talent_id, f.kampagne_id) FILTER (WHERE jsonb_array_length(f.empfaenger) > 0), '[]'::jsonb))
  FROM f
$function$
;

CREATE OR REPLACE FUNCTION public.talents_warnzeichen(p_talent_id integer, p_plattform text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- p_plattform: NULL/'' = alle Kanäle, Plattform-Schlüssel oder 'k<kanal_id>' (ein Account). Hat das Talent mehrere Accounts
  -- der Plattform, beginnt der Text mit dem Account ("@name: …") (Stefan 18.10.2026)
  SELECT coalesce(jsonb_agg(w.o ORDER BY w.rang, w.reihe, w.sort COLLATE "C", w.kid), '[]'::jsonb)
  FROM (
    SELECT x.rang, array_position(talents_plattformen(), k.plattform) AS reihe, lower(coalesce(k.extern_name, '')) AS sort, k.id AS kid,
      jsonb_build_object('art', x.art, 'stufe', x.stufe, 'plattform', k.plattform, 'kanal_id', k.id, 'konto', n.konto,
        'text', CASE WHEN n.mehrere AND n.konto IS NOT NULL THEN n.konto || ': ' ELSE '' END || x.txt) AS o
    FROM talent_kanaele k
    CROSS JOIN LATERAL (SELECT talents_plattform_name(k.plattform) AS pn, '@' || nullif(ltrim(btrim(coalesce(k.extern_name, '')), '@'), '') AS konto,
        (SELECT count(*) FROM talent_kanaele y WHERE y.talent_id = k.talent_id AND y.plattform = k.plattform AND y.extern_id IS NOT NULL
           AND y.status <> 'getrennt') > 1 AS mehrere) n
    CROSS JOIN LATERAL (
      SELECT 1 AS rang, 'abgelaufen' AS art, 'warnung' AS stufe, n.pn || '-Verbindung abgelaufen' AS txt WHERE k.status = 'abgelaufen'
      UNION ALL
      SELECT 2, 'laeuft_ab', 'warnung',
        CASE WHEN k.gueltig_bis <= now() THEN n.pn || '-Verbindung läuft ab' ELSE n.pn || '-Verbindung läuft am ' || talents_datum(k.gueltig_bis) || ' ab' END
      WHERE k.status = 'verbunden' AND k.gueltig_bis IS NOT NULL AND k.gueltig_bis < now() + interval '7 days'
      UNION ALL
      SELECT 3, 'einbruch', 'warnung',
        'Starker Einbruch auf ' || n.pn || ': ' || CASE WHEN coalesce((e.e->'reichweite'->>'einbruch')::boolean, false)
          THEN 'Reichweite −' || (e.e->'reichweite'->>'minus_prozent') || ' %' ELSE 'Interaktionen −' || (e.e->'interaktionen'->>'minus_prozent') || ' %' END
          || ' (letzte 7 Tage gegen die 4 Wochen davor)'
      FROM (SELECT talents_einbruch(k.id) AS e) e WHERE k.status = 'verbunden' AND coalesce((e.e->>'einbruch')::boolean, false)
      UNION ALL
      SELECT 4, 'abruf_fehler', 'hinweis', 'Letzter Abruf von ' || n.pn || ' fehlgeschlagen'
      WHERE k.status = 'verbunden' AND k.letzter_fehler IS NOT NULL
      UNION ALL
      SELECT 5, 'veraltet', 'hinweis', 'Keine neuen Zahlen von ' || n.pn || ' seit ' || coalesce(talents_datum(k.letzter_abruf), talents_datum(k.verbunden_am))
      WHERE k.status = 'verbunden' AND k.letzter_fehler IS NULL AND coalesce(k.letzter_abruf, k.verbunden_am) < now() - interval '2 days'
      UNION ALL
      SELECT 6, 'nicht_verbunden', 'hinweis', n.pn || ' noch nicht verbunden' WHERE k.status = 'offen'
    ) x
    WHERE k.talent_id = p_talent_id AND talents_kanal_passt(coalesce(p_plattform, ''), k.plattform, k.id)
  ) w
$function$
;

CREATE OR REPLACE FUNCTION public.talents_web_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
DECLARE
  s record;
  d jsonb := coalesce(p_daten, '{}'::jsonb);
  u text;
  m text := NULL;
  fehler text := NULL;
  erg jsonb := NULL;
  t talents%ROWTYPE;
  verw boolean;
  adm boolean;
  neu boolean;
  x text;
  n_name text; n_kname text; n_email text; n_notiz text; n_tage integer; n_personen text[]; n_kanaele text[];
  tage_gesetzt boolean := false;
  tid integer;
  anz integer;
  k talent_kanaele%ROWTYPE;
  v_alt text; e_alt text;
  b_neu text; vl_neu text; lf_neu text; lw_neu text; kw_neu text; sammel record; zeilen jsonb;
  wid boolean; lg jsonb;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := s.matrix_user_id;
  verw := ally_hat_recht(u, 'talents_verwalten');
  adm := ally_hat_recht(u, 'admin');
  x := btrim(coalesce(d->>'id', ''));
  IF x ~ '^[0-9]{1,9}$' THEN
    SELECT * INTO t FROM talents WHERE id = x::integer;
  END IF;

  BEGIN
    IF NOT plattform_modul_an('talents') THEN
      fehler := 'Das Paket Talents ist nicht gebucht.';
    ELSIF p_aktion = 'einstellungen' AND NOT adm THEN
      fehler := 'Die Einstellungen für Talents ändern Admins.';
    ELSIF p_aktion = 'talent_loeschen' AND NOT adm THEN
      fehler := 'Talents endgültig löschen können nur Admins.';
    ELSIF NOT verw THEN
      fehler := 'Dafür fehlt dir das Recht „Talents und Kampagnen verwalten“ für alle Talents. Rechte vergibt eine Person mit der Rolle Admin.';
    ELSIF p_aktion IN ('talent_bearbeiten', 'einladung_neu', 'kanal_trennen', 'talent_archivieren', 'talent_reaktivieren', 'talent_loeschen') AND t.id IS NULL THEN
      fehler := 'Unbekanntes Talent. Bitte die Seite neu laden.';

    ELSIF p_aktion IN ('talent_neu', 'talent_bearbeiten') THEN
      neu := p_aktion = 'talent_neu';
      -- Name optional; leer = NULL (Stefan 18.10.2026)
      n_name := CASE WHEN neu OR d ? 'name' THEN nullif(btrim(coalesce(d->>'name', '')), '') ELSE t.name END;
      n_kname := CASE WHEN neu OR d ? 'kuenstlername' THEN nullif(btrim(coalesce(d->>'kuenstlername', '')), '') ELSE t.kuenstlername END;
      n_email := CASE WHEN neu OR d ? 'email' THEN nullif(lower(btrim(coalesce(d->>'email', ''))), '') ELSE t.email END;
      n_notiz := CASE WHEN neu OR d ? 'notiz' THEN nullif(btrim(coalesce(d->>'notiz', '')), '') ELSE t.notiz END;
      n_tage := CASE WHEN neu THEN NULL ELSE t.verfolgung_tage END;
      IF d ? 'verfolgung_tage' THEN
        x := lower(btrim(coalesce(d->>'verfolgung_tage', '')));
        tage_gesetzt := true;
        IF x = '' THEN n_tage := NULL;
        ELSIF x IN ('unbegrenzt', '0') THEN n_tage := 0;
        ELSIF x ~ '^[0-9]{1,4}$' AND x::integer BETWEEN 1 AND 3650 THEN n_tage := x::integer;
        ELSE fehler := 'Bitte die Verfolgungsdauer in Tagen (1 bis 3650) angeben, „unbegrenzt“ wählen oder leer lassen (Standard der Agentur).';
        END IF;
      END IF;
      IF neu OR d ? 'personen' THEN
        n_personen := talents_liste(d->'personen');
        IF neu AND cardinality(n_personen) = 0 THEN
          n_personen := ARRAY[u];
        END IF;
      END IF;
      IF neu OR d ? 'kanaele' THEN
        n_kanaele := talents_liste(d->'kanaele');
      END IF;
      -- Ohne Namen, aber schon ein Account bekannt: dessen Name wird der Name (wie beim Verbinden) (Stefan 18.10.2026)
      IF NOT neu AND n_name IS NULL THEN
        SELECT nullif(btrim(left(ltrim(regexp_replace(btrim(kx.extern_name), '[[:cntrl:]]', '', 'g'), '@'), 120)), '') INTO n_name FROM talent_kanaele kx
        WHERE kx.talent_id = t.id AND nullif(btrim(ltrim(btrim(coalesce(kx.extern_name, '')), '@')), '') IS NOT NULL
        ORDER BY kx.status IN ('verbunden', 'abgelaufen') DESC, array_position(talents_plattformen(), kx.plattform) LIMIT 1;
      END IF;
      IF fehler IS NOT NULL THEN
        NULL;
      ELSIF n_name IS NOT NULL AND (length(n_name) > 120 OR n_name ~ '[[:cntrl:]]') THEN
        fehler := 'Der Name darf höchstens 120 Zeichen haben.';
      ELSIF n_kname IS NOT NULL AND (length(n_kname) > 120 OR n_kname ~ '[[:cntrl:]]') THEN
        fehler := 'Der Künstlername darf höchstens 120 Zeichen haben.';
      ELSIF n_email IS NOT NULL AND (length(n_email) > 200 OR n_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$') THEN
        fehler := 'Bitte eine gültige E-Mail-Adresse angeben oder das Feld leer lassen.';
      ELSIF n_notiz IS NOT NULL AND length(n_notiz) > 4000 THEN
        fehler := 'Die Notiz darf höchstens 4000 Zeichen haben.';
      ELSIF n_personen IS NOT NULL AND cardinality(n_personen) = 0 THEN
        fehler := 'Bitte mindestens einen Manager oder eine Managerin wählen.';
      ELSIF n_personen IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(n_personen) p
            WHERE NOT EXISTS (SELECT 1 FROM ally_personen ap WHERE ap.matrix_user_id = p AND ap.aktiv AND NOT ally_rolle_ist_talent(ap.rolle))) THEN  -- Migration 158 (Bauplan B3a): Talent-Personen sind nie Manager/in.
        fehler := 'In der Auswahl ist eine unbekannte Person. Bitte die Seite neu laden.';
      ELSIF n_kanaele IS NOT NULL AND cardinality(n_kanaele) = 0 THEN
        fehler := 'Bitte mindestens einen Kanal wählen.';
      ELSIF n_kanaele IS NOT NULL AND NOT (n_kanaele <@ talents_plattformen()) THEN
        fehler := 'In der Auswahl ist ein unbekannter Kanal. Bitte die Seite neu laden.';
      ELSIF neu AND n_name IS NOT NULL AND EXISTS (SELECT 1 FROM talents x2 WHERE lower(x2.name) = lower(n_name)
            AND coalesce(lower(x2.kuenstlername), '') = coalesce(lower(n_kname), '')) THEN
        fehler := 'Ein Talent mit diesem Namen gibt es schon.';
      ELSIF neu AND NOT ally_verschluesselung_bereit() THEN
        fehler := 'Verschlüsselung ist nicht eingerichtet.';
      ELSIF neu THEN
        INSERT INTO talents (name, kuenstlername, email, notiz, verfolgung_tage, erstellt_von, geaendert_von)
        VALUES (n_name, n_kname, n_email, n_notiz, n_tage, u, u) RETURNING id INTO tid;
        INSERT INTO talent_personen (talent_id, matrix_user_id) SELECT tid, p FROM unnest(n_personen) p;
        INSERT INTO talent_kanaele (talent_id, plattform) SELECT tid, kk FROM unnest(n_kanaele) kk;
        erg := talent_einladung_anlegen(tid, u);
        m := 'Einladung erstellt.';
      ELSE
        tid := t.id;
        UPDATE talents SET name = n_name, kuenstlername = n_kname, email = n_email, notiz = n_notiz, verfolgung_tage = n_tage,
          geaendert_am = now(), geaendert_von = u WHERE id = tid;
        IF n_personen IS NOT NULL THEN
          DELETE FROM talent_personen WHERE talent_id = tid AND NOT (matrix_user_id = ANY (n_personen));
          INSERT INTO talent_personen (talent_id, matrix_user_id) SELECT tid, p FROM unnest(n_personen) p ON CONFLICT DO NOTHING;
        END IF;
        m := 'Talent gespeichert.';
        IF n_kanaele IS NOT NULL THEN
          -- Neue Plattform = Platzhalter; Plattformen mit vorhandenen Zeilen (Accounts) bleiben unverändert (Stefan 18.10.2026)
          INSERT INTO talent_kanaele (talent_id, plattform) SELECT tid, kk FROM unnest(n_kanaele) kk
          WHERE NOT EXISTS (SELECT 1 FROM talent_kanaele kx WHERE kx.talent_id = tid AND kx.plattform = kk) ON CONFLICT DO NOTHING;
          -- Abgewählte Kanäle nur entfernen, wenn sie nie verbunden waren und keine Daten haben
          DELETE FROM talent_kanaele kx WHERE kx.talent_id = tid AND NOT (kx.plattform = ANY (n_kanaele)) AND kx.status = 'offen'
            AND kx.schluessel IS NULL AND kx.verbunden_am IS NULL
            AND NOT EXISTS (SELECT 1 FROM talent_kanal_tage y WHERE y.kanal_id = kx.id)
            AND NOT EXISTS (SELECT 1 FROM talent_beitraege y WHERE y.kanal_id = kx.id)
            AND NOT EXISTS (SELECT 1 FROM talent_zielgruppen y WHERE y.kanal_id = kx.id);
          SELECT count(*) INTO anz FROM talent_kanaele kx WHERE kx.talent_id = tid AND NOT (kx.plattform = ANY (n_kanaele));
          IF anz > 0 THEN
            m := m || ' Kanäle, die schon verbunden waren, bleiben in der Liste. Zum Trennen bitte „Kanal trennen“ nutzen.';
          END IF;
        END IF;
      END IF;

    ELSIF p_aktion = 'einladung_neu' THEN
      IF t.status <> 'aktiv' THEN
        fehler := 'Das Talent ist archiviert. Bitte zuerst reaktivieren.';
      ELSIF NOT ally_verschluesselung_bereit() THEN
        fehler := 'Verschlüsselung ist nicht eingerichtet.';
      ELSE
        anz := (SELECT count(*) FROM talent_einladungen e WHERE e.talent_id = t.id AND e.widerrufen_am IS NULL AND e.gueltig_bis > now());
        erg := talent_einladung_anlegen(t.id, u);
        m := 'Neuer Einladungslink' || coalesce(' für ' || talent_anzeigename(t.id), '') || ' erstellt.' || CASE WHEN anz > 0 THEN ' Der bisherige Link gilt nicht mehr.' ELSE '' END;
      END IF;

    ELSIF p_aktion = 'kanal_trennen' THEN
      -- Je Account: kanal_id (Stefan 18.10.2026). Rückfall plattform nur, wenn genau ein Account dieser Plattform verbunden ist.
      x := btrim(coalesce(d->>'kanal_id', ''));
      IF x ~ '^[0-9]{1,9}$' THEN
        SELECT * INTO k FROM talent_kanaele kx WHERE kx.id = x::integer AND kx.talent_id = t.id;
      ELSIF x = '' THEN
        x := lower(btrim(coalesce(d->>'plattform', '')));
        SELECT count(*) INTO anz FROM talent_kanaele kx WHERE kx.talent_id = t.id AND kx.plattform = x AND kx.status IN ('verbunden', 'abgelaufen');
        IF anz > 1 THEN
          fehler := 'Dieses Talent hat mehrere ' || talents_plattform_name(x) || '-Accounts. Bitte die Seite neu laden und den Account wählen.';
        ELSE
          SELECT * INTO k FROM talent_kanaele kx WHERE kx.talent_id = t.id AND kx.plattform = x
          ORDER BY kx.status IN ('verbunden', 'abgelaufen') DESC, kx.id LIMIT 1;
        END IF;
      END IF;
      IF fehler IS NOT NULL THEN
        NULL;
      ELSIF k.id IS NULL THEN
        fehler := 'Diesen Kanal hat das Talent nicht. Bitte die Seite neu laden.';
      ELSIF k.status NOT IN ('verbunden', 'abgelaufen') THEN
        fehler := 'Dieser Kanal ist nicht verbunden.';
      ELSE
        -- YouTube/TikTok: Zugang zuerst bei der Plattform widerrufen (TALENTS YT/TT über talents_widerruf_liste); der Schlüssel liegt bis dahin nur in talent_widerrufe (Stefan 18.10.2026)
        wid := talents_widerruf_vormerken(k.id, 'trennen', u);
        UPDATE talent_kanaele SET status = 'getrennt', schluessel = NULL, schluessel_zusatz = NULL, gueltig_bis = NULL, geaendert_am = now()
        WHERE id = k.id;
        m := talents_plattform_name(k.plattform) || CASE WHEN nullif(ltrim(btrim(coalesce(k.extern_name, '')), '@'), '') IS NOT NULL THEN ' ' || talents_konto_text(k.plattform, k.extern_name) ELSE '' END
          || coalesce(' von ' || talent_anzeigename(t.id), '') || ' getrennt.'
          || CASE WHEN wid THEN ' Ally widerruft den Zugang auch bei ' || talents_plattform_name(k.plattform) || '.' ELSE '' END
          || CASE WHEN k.plattform = 'youtube' AND k.extern_id IS NOT NULL
                  THEN ' Die bisher gespeicherten Zahlen bleiben bis zum ' || to_char(talents_tag(coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am)) + 30, 'DD.MM.YYYY')
                    || ' erhalten; danach löscht Ally sie nach den YouTube-Richtlinien, wenn der Kanal nicht neu verbunden ist.'
                  ELSE ' Die bisher gespeicherten Zahlen bleiben erhalten.' END;
      END IF;

    ELSIF p_aktion = 'talent_archivieren' THEN
      IF t.status = 'archiviert' THEN
        fehler := 'Das Talent ist schon archiviert.';
      ELSE
        UPDATE talents SET status = 'archiviert', archiviert_am = now(), geaendert_am = now(), geaendert_von = u WHERE id = t.id;
        UPDATE talent_einladungen SET widerrufen_am = now() WHERE talent_id = t.id AND widerrufen_am IS NULL;
        m := coalesce(talent_anzeigename(t.id), 'Talent') || ' archiviert. Offene Einladungslinks gelten nicht mehr, Abrufe ruhen.';
      END IF;

    ELSIF p_aktion = 'talent_reaktivieren' THEN
      IF t.status = 'aktiv' THEN
        fehler := 'Das Talent ist schon aktiv.';
      ELSE
        UPDATE talents SET status = 'aktiv', archiviert_am = NULL, geaendert_am = now(), geaendert_von = u WHERE id = t.id;
        m := coalesce(talent_anzeigename(t.id), 'Das Talent') || ' ist wieder aktiv. Für neue Verbindungen bitte einen neuen Einladungslink erstellen.';
      END IF;

    ELSIF p_aktion = 'talent_loeschen' THEN
      -- Bestätigung: der gespeicherte Name; ohne Namen das Wort "löschen" (Stefan 18.10.2026)
      -- Endgültig löschen nur archivierte Talents (Stefan 18.10.2026)
      IF t.status <> 'archiviert' THEN
        fehler := 'Endgültig löschen lässt sich nur ein archiviertes Talent. Bitte das Talent zuerst archivieren.';
      ELSIF t.name IS NOT NULL AND btrim(coalesce(d->>'bestaetigung', '')) IS DISTINCT FROM t.name THEN
        fehler := 'Zum endgültigen Löschen bitte den Namen genau so eingeben, wie er gespeichert ist: ' || t.name;
      ELSIF t.name IS NULL AND lower(btrim(coalesce(d->>'bestaetigung', ''))) <> 'löschen' THEN
        fehler := 'Zum endgültigen Löschen bitte das Wort „löschen“ eingeben.';
      ELSE
        -- Berichte, KI-Bezüge, Widerrufe; Dateien im Speicherort werden vorgemerkt (talent_loesch_dateien) (Stefan 18.10.2026)
        lg := talents_talent_loeschen(t.id, 'manuell', u);
        m := coalesce(t.name, nullif(btrim(t.kuenstlername), ''), 'Das Talent') || ' wurde endgültig gelöscht, mit allen gespeicherten Daten.'
          || CASE WHEN (lg->>'dateien_vorgemerkt')::integer > 0 THEN ' Die Dateien im Speicherort (Berichte, Mediakits, Zahlen) löscht Ally in den nächsten Stunden.' ELSE '' END;
      END IF;

    ELSIF p_aktion = 'einstellungen' THEN
      v_alt := NULL; e_alt := NULL;
      IF d ? 'verfolgung_tage' THEN
        x := lower(btrim(coalesce(d->>'verfolgung_tage', '')));
        IF x IN ('unbegrenzt', '0') THEN v_alt := '0';
        ELSIF x ~ '^[0-9]{1,4}$' AND x::integer BETWEEN 1 AND 3650 THEN v_alt := x::integer::text;
        ELSE fehler := 'Bitte die Verfolgungsdauer in Tagen (1 bis 3650) angeben oder „unbegrenzt“ wählen.';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'einladung_tage' THEN
        x := btrim(coalesce(d->>'einladung_tage', ''));
        IF x ~ '^[0-9]{1,2}$' AND x::integer BETWEEN 1 AND 60 THEN e_alt := x::integer::text;
        ELSE fehler := 'Bitte die Gültigkeit der Einladungslinks in Tagen (1 bis 60) angeben.';
        END IF;
      END IF;
      -- Einladungstext (Vorlage), Löschfrist, Warnfristen (Stefan 18.10.2026)
      IF fehler IS NULL AND d ? 'einladung_betreff' THEN
        b_neu := btrim(regexp_replace(coalesce(d->>'einladung_betreff', ''), '[[:cntrl:]]', ' ', 'g'));
        IF length(b_neu) > 200 THEN fehler := 'Der Betreff darf höchstens 200 Zeichen haben.'; END IF;
      END IF;
      IF fehler IS NULL AND d ? 'einladung_vorlage' THEN
        vl_neu := btrim(regexp_replace(replace(replace(coalesce(d->>'einladung_vorlage', ''), E'\r\n', E'\n'), E'\r', E'\n'), '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f]', '', 'g'));
        IF length(vl_neu) > 4000 THEN fehler := 'Der Einladungstext darf höchstens 4000 Zeichen haben.';
        ELSIF vl_neu <> '' AND vl_neu !~* '\[link\]' THEN fehler := 'Der Einladungstext braucht den Platzhalter [Link], sonst fehlt dem Talent der Link.';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'loeschfrist_tage' THEN
        lf_neu := lower(btrim(coalesce(d->>'loeschfrist_tage', '')));
        IF lf_neu IN ('', 'nie') THEN lf_neu := '';
        ELSIF lf_neu ~ '^[0-9]{1,4}$' AND lf_neu::integer BETWEEN 1 AND 3650 THEN lf_neu := lf_neu::integer::text;
        ELSE fehler := 'Bitte die Löschfrist in Tagen nach der Archivierung (1 bis 3650) angeben oder leer lassen (nie automatisch löschen).';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'loeschwarnung_tage' THEN
        lw_neu := btrim(coalesce(d->>'loeschwarnung_tage', ''));
        IF lw_neu ~ '^[0-9]{1,2}$' AND lw_neu::integer BETWEEN 1 AND 90 THEN lw_neu := lw_neu::integer::text;
        ELSE fehler := 'Bitte angeben, wie viele Tage vor dem Löschen die Admins gewarnt werden (1 bis 90).';
        END IF;
      END IF;
      IF fehler IS NULL AND d ? 'kampagne_warnung_tage' THEN
        kw_neu := btrim(coalesce(d->>'kampagne_warnung_tage', ''));
        IF kw_neu ~ '^[0-9]{1,2}$' AND kw_neu::integer BETWEEN 0 AND 60 THEN kw_neu := kw_neu::integer::text;
        ELSE fehler := 'Bitte angeben, wie viele Tage vor Kampagnenende ein fehlender Beitrag gemeldet wird (0 bis 60; 0 = am letzten Tag).';
        END IF;
      END IF;
      IF fehler IS NULL AND v_alt IS NULL AND e_alt IS NULL AND b_neu IS NULL AND vl_neu IS NULL AND lf_neu IS NULL AND lw_neu IS NULL AND kw_neu IS NULL THEN
        fehler := 'Es wurden keine Einstellungen übermittelt. Bitte die Seite neu laden.';
      END IF;
      IF fehler IS NULL THEN
        IF v_alt IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_verfolgung_tage', v_alt, u); END IF;
        IF e_alt IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_einladung_tage', e_alt, u); END IF;
        IF b_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_einladung_betreff', b_neu, u); END IF;
        IF vl_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_einladung_vorlage', vl_neu, u); END IF;
        IF lf_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_loeschfrist_tage', lf_neu, u); END IF;
        IF lw_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_loeschwarnung_tage', lw_neu, u); END IF;
        IF kw_neu IS NOT NULL THEN PERFORM ally_einstellung_setzen('talents_kampagne_warnung_tage', kw_neu, u); END IF;
        -- Ankündigung auch ohne Chat (Stefan 19.10.2026, Migration 54)
        m := 'Einstellungen für Talents gespeichert.' || CASE WHEN coalesce(lf_neu, '') <> '' THEN ' Gelöscht wird frühestens '
          || talents_einstellung_zahl('talents_loeschwarnung_tage', 1, 90, 14) || ' Tage nach der Ankündigung (Chat an die Admins; kommt sie nicht an, gilt der Termin in der Talents-Liste).' ELSE '' END;
      END IF;

    -- Sammel-Aktion: neuer Link für alle aktiven Talents mit abgelaufener Verbindung oder abgelaufener Einladung, Tabelle (CSV) zum Herunterladen (Stefan 18.10.2026)
    ELSIF p_aktion = 'links_erneuern' THEN
      IF NOT ally_verschluesselung_bereit() THEN
        fehler := 'Verschlüsselung ist nicht eingerichtet.';
      ELSE
        zeilen := '[]'::jsonb;
        FOR sammel IN SELECT t2.id FROM talents t2 WHERE t2.status = 'aktiv' AND (talents_talent_stand(t2.id)->>'link_noetig')::boolean
                      ORDER BY lower(talent_listenname(t2.id)) COLLATE "C", t2.id LIMIT 500 LOOP
          erg := talent_einladung_anlegen(sammel.id, u);
          zeilen := zeilen || jsonb_build_array(jsonb_build_array(coalesce(talent_anzeigename(sammel.id), ''), erg->>'email', erg->>'link', erg->>'gueltig_bis'));
        END LOOP;
        anz := jsonb_array_length(zeilen);
        IF anz = 0 THEN
          erg := NULL;
          fehler := 'Es gibt keine Talents mit abgelaufener Verbindung oder abgelaufener Einladung.';
        ELSE
          erg := jsonb_build_object('art', 'links', 'anzahl', anz, 'dateiname', 'einladungslinks-' || to_char(talents_heute(), 'YYYY-MM-DD') || '.csv',
            'zeilen', (SELECT jsonb_agg(jsonb_build_object('name', z->>0, 'email', z->>1, 'link', z->>2, 'gueltig_bis', z->>3)) FROM jsonb_array_elements(zeilen) z),
            'csv', talents_csv(ARRAY['Name', 'E-Mail', 'Link', 'gültig bis'], zeilen));
          m := CASE WHEN anz = 1 THEN '1 neuer Einladungslink erstellt.' ELSE anz || ' neue Einladungslinks erstellt.' END
            || ' Die Tabelle steht zum Herunterladen bereit. Bitte die Links selbst an die Talents schicken.';
        END IF;
      END IF;

    ELSE
      fehler := 'Unbekannte Aktion.';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Teiländerungen dieses Blocks sind zurückgenommen
    erg := NULL;
    -- Migration 172 (B8b, Fixieren): ein fixierter Wert (SQLSTATE AT002) wird zur Meldung
    fehler := CASE WHEN SQLERRM = 'Verschlüsselung ist nicht eingerichtet.' OR SQLSTATE = 'AT002' THEN SQLERRM
                   ELSE 'Die Aktion konnte nicht ausgeführt werden. Bitte erneut versuchen. (' || left(SQLERRM, 200) || ')' END;
  END;

  UPDATE ally_web_sitzungen SET flash = coalesce(fehler, m), flash_art = CASE WHEN fehler IS NULL THEN 'ok' ELSE 'fehler' END,
    ergebnis = CASE WHEN fehler IS NULL THEN erg END
  WHERE token_hash = s.token_hash;
  RETURN jsonb_build_object('ok', fehler IS NULL, 'angemeldet', true, 'fehler', fehler,
    'talent_id', CASE WHEN fehler IS NULL THEN coalesce(tid, t.id) END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_web_daten(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
-- Migration 165 (Bauplan B5c): Rolle der Art talent (ally_rolle_ist_talent) statt des festen Schlüssels 'talent'.
DECLARE
  s record;
  u text;
  z text;
  verw boolean;
  adm boolean;
BEGIN
  SELECT * INTO s FROM ally_web_sitzung_pruefen(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', false);
  END IF;
  IF s.muss_pw_setzen THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true);
  END IF;
  u := s.matrix_user_id;
  IF NOT plattform_modul_an('talents') THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Das Paket Talents ist nicht gebucht.');
  END IF;
  z := talents_zugriff(u);
  IF z IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Für Talents fehlt dir das Recht „Talents ansehen“. Rechte vergibt eine Person mit der Rolle Admin.');
  END IF;
  -- Migration 66: verw = „Talents und Kampagnen verwalten“ für alle Talents; sehen nach „Talents ansehen“ (z)
  verw := ally_hat_recht(u, 'talents_verwalten');
  adm := ally_hat_recht(u, 'admin');
  RETURN jsonb_build_object('ok', true, 'angemeldet', true,
    'zugriff', z, 'darf_verwalten', verw, 'darf_loeschen', adm, 'darf_einstellungen', adm,
    -- Reihenfolge: aktive zuerst; mit Namen alphabetisch, ohne Namen (Einladung offen) danach, neueste zuerst (Stefan 18.10.2026)
    'talents', coalesce((SELECT jsonb_agg(talent_json(t.id, verw) ORDER BY t.status = 'archiviert', talent_anzeigename(t.id) IS NULL, lower(talent_anzeigename(t.id)), t.id DESC)
        FROM talents t WHERE z = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u)), '[]'::jsonb),
    'anzahl_talents', (SELECT count(*) FROM talents t WHERE z = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u)),
    'anzahl_aktiv', (SELECT count(*) FROM talents t WHERE t.status = 'aktiv' AND (z = 'alle' OR EXISTS (SELECT 1 FROM talent_personen tp WHERE tp.talent_id = t.id AND tp.matrix_user_id = u))),
    -- Angemeldete Person; Vorauswahl "zuständig" beim Einladen (Stefan 18.10.2026)
    'ich', u,
    'standard_zustaendig', CASE WHEN EXISTS (SELECT 1 FROM ally_personen p WHERE p.matrix_user_id = u AND p.aktiv) THEN jsonb_build_array(u) ELSE '[]'::jsonb END,
    'personen', coalesce((SELECT jsonb_agg(jsonb_build_object('id', p.matrix_user_id, 'name', p.name || CASE WHEN p.testdaten THEN ' (Testdaten)' ELSE '' END, 'hat_recht', talents_zugriff(p.matrix_user_id) IS NOT NULL) ORDER BY p.name)
        FROM ally_personen p WHERE p.aktiv AND NOT ally_rolle_ist_talent(p.rolle)), '[]'::jsonb),
    -- Migration 165 (Bauplan B5c): Rollen für Talents zur Auswahl beim Einladen (aktive Rollen der Art talent, Stefan G10)
    'talent_rollen', (SELECT coalesce(jsonb_agg(jsonb_build_object('wert', r.schluessel, 'text', r.name) ORDER BY r.sortierung, lower(r.name), r.schluessel), '[]'::jsonb)
        FROM ally_rollen r WHERE r.art = 'talent' AND r.archiviert_am IS NULL),
    -- je Plattform zusätzlich die Anmeldewege mit Bereitschaft (Stefan 18.10.2026)
    'plattformen', (SELECT jsonb_agg(jsonb_build_object('schluessel', x.k, 'name', talents_plattform_name(x.k), 'bereit', talent_plattform_bereit(x.k),
          'wege', (SELECT coalesce(jsonb_agg(jsonb_build_object('weg', w.w, 'name', talents_weg_name(x.k, w.w), 'bereit', (talent_weg(x.k, w.w)->>'bereit')::boolean) ORDER BY w.n), '[]'::jsonb)
                   FROM unnest(talent_wege(x.k)) WITH ORDINALITY AS w(w, n))) ORDER BY x.n)
        FROM unnest(talents_plattformen()) WITH ORDINALITY AS x(k, n)),
    'einstellungen', jsonb_build_object('verfolgung_tage', talents_verfolgung_standard(), 'verfolgung_unbegrenzt', talents_verfolgung_standard() = 0,
        'einladung_tage', talents_einladung_tage(),
        -- Einladungstext als Vorlage, Löschfrist, Warnfristen (Stefan 18.10.2026)
        'einladung_betreff', btrim(ally_einstellung('talents_einladung_betreff')), 'einladung_vorlage', btrim(ally_einstellung('talents_einladung_vorlage')),
        'einladung_standard', talents_einladung_standard(),
        'platzhalter', '[{"name":"[Name]","beschreibung":"Künstlername, sonst Name des Talents"},{"name":"[Link]","beschreibung":"persönlicher Einladungslink (Pflicht)"},{"name":"[Gültig bis]","beschreibung":"Datum, bis zu dem der Link gilt"},{"name":"[Agentur]","beschreibung":"Name der Agentur"}]'::jsonb,
        'loeschfrist_tage', CASE WHEN btrim(ally_einstellung('talents_loeschfrist_tage')) ~ '^[0-9]{1,4}$' THEN btrim(ally_einstellung('talents_loeschfrist_tage'))::integer END,
        'loeschwarnung_tage', talents_einstellung_zahl('talents_loeschwarnung_tage', 1, 90, 14),
        'kampagne_warnung_tage', talents_einstellung_zahl('talents_kampagne_warnung_tage', 0, 60, 3),
        -- Migration 195 (Stefan 01.11.2026, Abrufzeiten): Zeiten des automatischen Abrufs (Kachel „Automatischer Abruf“)
        'abruf', talents_abrufzeit_json()),
    'basis', talents_basis(),
    'anbieter', anbieter_name(), 'produkt', produkt_name(), 'firma', coalesce(eigenes_unternehmen()->>'name', ''),
    'verschluesselung', ally_verschluesselung_bereit());
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_weg_hinweis(p_plattform text, p_weg text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Kurzer Hinweis je Verbindung (Einladungsseite ALLY 16, Talent-Bereich ALLY 38). Migration 65: Text aus talents_verbindung_info (welche Daten die Verbindung
  -- liefert und welche nicht; Quellen in mp/k2/info_verbindung/texte.md)
  SELECT talents_verbindung_info(p_plattform, CASE WHEN p_plattform = 'instagram' THEN p_weg END)->>'kurz'
$function$
;

CREATE OR REPLACE FUNCTION public.talents_weg_knopf(p_plattform text, p_weg text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_plattform = 'instagram' AND p_weg = 'facebook' THEN 'Mit Instagram über Facebook verbinden'
    WHEN p_plattform = 'instagram' AND p_weg = 'instagram' THEN 'Mit Instagram direkt verbinden'
    WHEN p_plattform = 'facebook' THEN 'Facebook-Seite verbinden'
    WHEN p_plattform = 'threads' THEN 'Mit Threads verbinden'
    WHEN p_plattform = 'youtube' THEN 'YouTube-Kanal mit Google verbinden'
    WHEN p_plattform = 'pinterest' THEN 'Mit Pinterest verbinden'
    WHEN p_plattform = 'tiktok' THEN 'Mit TikTok verbinden' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_weg_name(p_plattform text, p_weg text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_plattform = 'instagram' AND p_weg = 'facebook' THEN 'Mit Facebook anmelden (Instagram-Konto ist mit einer Facebook-Seite verknüpft)'
    WHEN p_plattform = 'instagram' AND p_weg = 'instagram' THEN 'Mit Instagram anmelden (ohne Facebook-Seite, ohne Beitragstexte)'
    WHEN p_weg = 'facebook' THEN 'Mit Facebook anmelden'
    WHEN p_weg = 'google' THEN 'Mit Google anmelden'
    WHEN p_weg = 'threads' THEN 'Mit Threads anmelden'
    WHEN p_weg = 'tiktok' THEN 'Mit TikTok anmelden'
    WHEN p_weg = 'pinterest' THEN 'Mit Pinterest anmelden' END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_weitere_plattformen()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT ARRAY['facebook', 'threads', 'youtube', 'pinterest', 'tiktok'] $function$
;

CREATE OR REPLACE FUNCTION public.talents_wert(p numeric)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT jsonb_build_object('wert', p, 'text', CASE WHEN p IS NULL THEN '–' ELSE talents_zahl_text(p) END)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_werte(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF p IS NULL OR jsonb_typeof(p) = 'null' THEN
    RETURN '{}'::jsonb;
  END IF;
  IF jsonb_typeof(p) <> 'object' THEN
    RAISE EXCEPTION 'Die Kennzahlen (werte) müssen ein JSON-Objekt sein.';
  END IF;
  IF length(p::text) > 20000 THEN
    RAISE EXCEPTION 'Die Kennzahlen (werte) sind zu groß (höchstens 20000 Zeichen).';
  END IF;
  RETURN p;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_wf_aktion(p_token text, p_aktion text, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  tid integer := CASE WHEN d->>'talent_id' ~ '^[0-9]{1,9}$' THEN (d->>'talent_id')::integer END;
  s jsonb := talents_ki_sitzung(p_token, tid);
  z jsonb;
  kanal text;
  i integer;
  f text;
BEGIN
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  IF p_aktion <> 'erstellen' OR tid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Unbekannte Aktion.');
  END IF;
  f := talents_ki_start_fehler(tid);
  IF f IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', f);
  END IF;
  IF EXISTS (SELECT 1 FROM talent_ki_auswertungen w WHERE w.talent_id = tid AND w.status = 'wird_erstellt') THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', 'Eine Auswertung wird gerade erstellt. ' || talents_ki_laeuft_text());
  END IF;
  z := talents_wf_zeitraum(d);
  IF z->>'fehler' IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'angemeldet', true, 'fehler', z->>'fehler');
  END IF;
  kanal := talents_kanal_filter(coalesce(d->>'kanal', ''), talents_ki_kanaele(tid));
  INSERT INTO talent_ki_auswertungen (talent_id, kanal, von, bis, erstellt_von) VALUES (tid, kanal, (z->>'von')::date, (z->>'bis')::date, s->>'u') RETURNING id INTO i;
  UPDATE talent_ki_auswertungen SET ki_auftrag_id = talents_ki_auftrag_anlegen('was_funktioniert', tid, i, s->>'u') WHERE id = i;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true, 'auswertung_id', i, 'auftrag_id', (SELECT ki_auftrag_id FROM talent_ki_auswertungen WHERE id = i),
    'meldung', talents_ki_laeuft_text());
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_wf_daten(p_token text, p_talent_id integer, p_filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  s jsonb := talents_ki_sitzung(p_token, p_talent_id);
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  z jsonb;
  ids integer[];
  kanal text;
  w talent_ki_auswertungen;
BEGIN
  IF NOT coalesce((s->>'ok')::boolean, false) THEN
    RETURN s;
  END IF;
  ids := talents_ki_kanaele(p_talent_id);
  kanal := talents_kanal_filter(coalesce(f->>'kanal', ''), ids);
  z := talents_wf_zeitraum(f);
  SELECT * INTO w FROM talent_ki_auswertungen x WHERE x.talent_id = p_talent_id ORDER BY x.id DESC LIMIT 1;
  RETURN jsonb_build_object('ok', true, 'angemeldet', true,
    'talent', jsonb_build_object('talent_id', p_talent_id, 'name', talent_anzeigename(p_talent_id)),
    'filter', jsonb_build_object('kanal', kanal, 'zeitraum', z->>'schluessel', 'von', z->>'frei_von', 'bis', z->>'frei_bis'),
    'zeitraum', z,
    'zeitraeume', '[{"schluessel": "90tage", "name": "Letzte 90 Tage"}]'::jsonb || talents_zeitraeume(false),
    'kanal_auswahl', talents_kanal_auswahl(ids),
    'zahlen', talents_wf_zahlen(p_talent_id, kanal, (z->>'von')::date, (z->>'bis')::date),
    'vorschlaege', CASE WHEN w.id IS NULL THEN NULL ELSE jsonb_build_object('auswertung_id', w.id, 'status', w.status, 'laeuft', w.status = 'wird_erstellt',
        'status_text', CASE w.status WHEN 'wird_erstellt' THEN talents_ki_laeuft_text() WHEN 'fehler' THEN coalesce(w.fehler, 'Konnte nicht erstellt werden.') ELSE NULL END,
        'zeitraum_text', to_char(w.von, 'DD.MM.YYYY') || ' bis ' || to_char(w.bis, 'DD.MM.YYYY'),
        'kanal', w.kanal, 'erstellt', talents_datum(w.erstellt_am), 'eintraege', w.vorschlaege, 'hinweis', w.hinweis,
        'passt_zum_filter', w.kanal = kanal AND w.von = (z->>'von')::date AND w.bis = (z->>'bis')::date) END,
    'darf_erstellen', EXISTS (SELECT 1 FROM talents t WHERE t.id = p_talent_id AND t.status = 'aktiv'),
    'ki_hinweis', talents_ki_start_fehler(p_talent_id));
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_wf_gruppe(p_schluessel text, p_name text, p_n integer, p_r numeric, p_a numeric, p_i numeric, p_sr numeric, p_si numeric, p_basis text, p_schnitt numeric, p_instagram boolean)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT jsonb_build_object('schluessel', p_schluessel, 'name', p_name, 'anzahl', p_n,
    'reichweite', talents_wert(round(p_r)), 'aufrufe', talents_wert(round(p_a)), 'interaktionen', talents_wert(round(p_i)),
    'interaktionsrate', CASE WHEN p_instagram AND p_sr > 0 AND p_si IS NOT NULL THEN talents_dezimal_text(p_si / p_sr * 100, 1) || ' %' END,
    'faktor', CASE WHEN p_schnitt > 0 AND (CASE WHEN p_basis = 'reichweite' THEN p_r ELSE p_a END) IS NOT NULL
                   THEN round((CASE WHEN p_basis = 'reichweite' THEN p_r ELSE p_a END) / p_schnitt, 1) END,
    'faktor_text', CASE WHEN p_schnitt > 0 AND (CASE WHEN p_basis = 'reichweite' THEN p_r ELSE p_a END) IS NOT NULL
                   THEN talents_dezimal_text((CASE WHEN p_basis = 'reichweite' THEN p_r ELSE p_a END) / p_schnitt, 1) || '-mal '
                        || CASE WHEN p_basis = 'reichweite' THEN 'Reichweite' ELSE 'Aufrufe' END || ' des Schnitts' END,
    'aussage', p_n >= 3,
    'hinweis', CASE WHEN p_n < 3 THEN 'Zu wenige Beiträge für eine Aussage.' END)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_wf_zahlen(p_talent_id integer, p_kanal text, p_von date, p_bis date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  WITH ids AS (SELECT talents_ki_kanaele(p_talent_id, p_kanal) AS ids),
  w AS MATERIALIZED (
    SELECT b.id, talents_beitrag_art(b.art, b.produkt_art) AS art,
           extract(hour FROM coalesce(b.erstellt, b.erfasst_am) AT TIME ZONE 'Europe/Berlin')::integer AS stunde,
           extract(isodow FROM coalesce(b.erstellt, b.erfasst_am) AT TIME ZONE 'Europe/Berlin')::integer AS tag, th.thema,
           coalesce(btrim(b.text_inhalt), '') <> '' AS hat_text, talents_zahl(b.werte->'reach') AS r, talents_aufrufe(b.werte) AS a,
           talents_interaktionen(b.werte) AS i, coalesce(b.erstellt, b.erfasst_am) AS datum, CASE WHEN b.link ~ '^https://[^[:space:]]+$' THEN b.link END AS link
    FROM talent_beitraege b CROSS JOIN ids LEFT JOIN talent_ki_themen th ON th.beitrag_id = b.id
    WHERE b.kanal_id = ANY (ids.ids)
      AND (coalesce(b.erstellt, b.erfasst_am) AT TIME ZONE 'Europe/Berlin')::date BETWEEN p_von AND p_bis),
  k AS (SELECT CASE WHEN count(*) FILTER (WHERE r IS NOT NULL) >= count(*) FILTER (WHERE a IS NOT NULL) THEN 'reichweite' ELSE 'aufrufe' END AS basis
        FROM w WHERE art <> 'story'),
  s AS (SELECT k.basis, (SELECT avg(CASE WHEN k.basis = 'reichweite' THEN w.r ELSE w.a END) FROM w WHERE w.art <> 'story') AS schnitt,
               EXISTS (SELECT 1 FROM talent_kanaele x, ids WHERE x.id = ANY (ids.ids) AND x.plattform = 'instagram') AS ig FROM k),
  ws AS (SELECT w.*, s.basis, s.schnitt, s.ig, CASE WHEN s.basis = 'reichweite' THEN w.r ELSE w.a END AS bw,
                CASE WHEN w.stunde BETWEEN 6 AND 9 THEN 1 WHEN w.stunde BETWEEN 10 AND 13 THEN 2 WHEN w.stunde BETWEEN 14 AND 17 THEN 3
                     WHEN w.stunde BETWEEN 18 AND 21 THEN 4 ELSE 5 END AS block
         FROM w, s)
  SELECT jsonb_build_object(
    'von', to_char(p_von, 'YYYY-MM-DD'), 'bis', to_char(p_bis, 'YYYY-MM-DD'),
    'zeitraum_text', to_char(p_von, 'DD.MM.YYYY') || ' bis ' || to_char(p_bis, 'DD.MM.YYYY'),
    'anzahl_beitraege', (SELECT count(*) FROM w),
    'anzahl_mit_zahlen', (SELECT count(*) FROM w WHERE r IS NOT NULL OR a IS NOT NULL),
    'anzahl_mit_text', (SELECT count(*) FROM w WHERE hat_text),
    'anzahl_mit_thema', (SELECT count(*) FROM w WHERE thema IS NOT NULL),
    'basis', s.basis, 'basis_name', CASE s.basis WHEN 'reichweite' THEN 'Reichweite' ELSE 'Aufrufe' END,
    'schnitt', jsonb_build_object('reichweite', talents_wert(round((SELECT avg(r) FROM w WHERE art <> 'story'))),
                                  'aufrufe', talents_wert(round((SELECT avg(a) FROM w WHERE art <> 'story'))),
                                  'interaktionen', talents_wert(round((SELECT avg(i) FROM w WHERE art <> 'story')))),
    'formate', (SELECT coalesce(jsonb_agg(talents_wf_gruppe(g.art, talents_beitrag_art_name(g.art), g.n, g.r, g.a, g.i, g.sr, g.si, s.basis, s.schnitt, s.ig)
                  ORDER BY g.n DESC, g.art COLLATE "C"), '[]'::jsonb)
                FROM (SELECT art, count(*)::integer n, avg(r) r, avg(a) a, avg(i) i, sum(r) FILTER (WHERE i IS NOT NULL) sr, sum(i) FILTER (WHERE r IS NOT NULL) si
                      FROM w GROUP BY art) g),
    'tageszeiten', (SELECT coalesce(jsonb_agg(talents_wf_gruppe((ARRAY['morgens','mittags','nachmittags','abends','nachts'])[g.block],
                      (ARRAY['6 bis 10 Uhr','10 bis 14 Uhr','14 bis 18 Uhr','18 bis 22 Uhr','22 bis 6 Uhr'])[g.block],
                      g.n, g.r, g.a, g.i, g.sr, g.si, s.basis, s.schnitt, s.ig) ORDER BY g.block), '[]'::jsonb)
                FROM (SELECT block, count(*)::integer n, avg(r) r, avg(a) a, avg(i) i, sum(r) FILTER (WHERE i IS NOT NULL) sr, sum(i) FILTER (WHERE r IS NOT NULL) si
                      FROM ws WHERE art <> 'story' GROUP BY block) g),
    'wochentage', (SELECT coalesce(jsonb_agg(talents_wf_gruppe(g.tag::text, (ARRAY['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'])[g.tag],
                    g.n, g.r, g.a, g.i, g.sr, g.si, s.basis, s.schnitt, s.ig) ORDER BY g.tag), '[]'::jsonb)
                FROM (SELECT tag, count(*)::integer n, avg(r) r, avg(a) a, avg(i) i, sum(r) FILTER (WHERE i IS NOT NULL) sr, sum(i) FILTER (WHERE r IS NOT NULL) si
                      FROM w WHERE art <> 'story' GROUP BY tag) g),
    'themen', (SELECT coalesce(jsonb_agg(talents_wf_gruppe(g.thema, g.thema, g.n, g.r, g.a, g.i, g.sr, g.si, s.basis, s.schnitt, s.ig) ORDER BY g.n DESC, g.thema COLLATE "C"), '[]'::jsonb)
                FROM (SELECT thema, count(*)::integer n, avg(r) r, avg(a) a, avg(i) i, sum(r) FILTER (WHERE i IS NOT NULL) sr, sum(i) FILTER (WHERE r IS NOT NULL) si
                      FROM w WHERE art <> 'story' AND thema IS NOT NULL GROUP BY thema ORDER BY count(*) DESC, thema COLLATE "C" LIMIT 12) g),
    'beste', (SELECT coalesce(jsonb_agg(jsonb_build_object('beitrag_id', x.id, 'datum', talents_datum(x.datum), 'art', x.art, 'art_name', talents_beitrag_art_name(x.art),
                    'thema', x.thema, 'reichweite', talents_wert(x.r), 'aufrufe', talents_wert(x.a), 'interaktionen', talents_wert(x.i), 'link', x.link)
                    ORDER BY x.bw DESC, x.id), '[]'::jsonb)
              FROM (SELECT * FROM ws WHERE art <> 'story' AND bw IS NOT NULL ORDER BY bw DESC, id LIMIT 3) x),
    'hinweis', CASE WHEN (SELECT count(*) FROM w) = 0 THEN 'Im Zeitraum gibt es keine Beiträge.'
                    WHEN (SELECT count(*) FROM w WHERE hat_text) = 0
                      THEN 'Ohne Beitragstexte gibt es keine Themen: Die Auswertung zeigt nur Format, Uhrzeit und Zahlen. Beitragstexte liefert Instagram nur bei der Anmeldung über Facebook.'
                    WHEN (SELECT count(*) FROM w WHERE hat_text AND thema IS NULL) > 0
                      THEN 'Für ' || (SELECT count(*) FROM w WHERE hat_text AND thema IS NULL) || ' Beiträge mit Text sind die Themen noch nicht erkannt.' END)
  FROM s
$function$
;

CREATE OR REPLACE FUNCTION public.talents_wf_zeitraum(p_filter jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE WHEN coalesce(p_filter->>'zeitraum', '') IN ('', '90tage')
    THEN jsonb_build_object('schluessel', '90tage', 'name', 'Letzte 90 Tage', 'von', to_char(talents_heute() - 90, 'YYYY-MM-DD'), 'bis', to_char(talents_heute() - 1, 'YYYY-MM-DD'),
                            'text', to_char(talents_heute() - 90, 'DD.MM.YYYY') || ' bis ' || to_char(talents_heute() - 1, 'DD.MM.YYYY'))
    ELSE talents_zeitraum(p_filter, '28tage', false) END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_widerruf_ergebnis(p_id bigint, p_daten jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  d jsonb := CASE WHEN jsonb_typeof(p_daten) = 'object' THEN p_daten ELSE '{}'::jsonb END;
  w talent_widerrufe%ROWTYPE;
  e text;
BEGIN
  SELECT * INTO w FROM talent_widerrufe WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'fehler', 'Unbekannter Widerruf.'); END IF;
  IF w.erledigt_am IS NOT NULL THEN RETURN jsonb_build_object('ok', true, 'widerruf_id', w.id, 'erledigt', true, 'ergebnis', w.ergebnis); END IF;
  e := CASE WHEN talents_bericht_ja(d->'ok', false) THEN 'widerrufen' WHEN talents_bericht_ja(d->'ungueltig', false) THEN 'ungueltig'
            WHEN w.versuche + 1 >= 5 THEN 'aufgegeben' END;
  UPDATE talent_widerrufe SET versuche = versuche + 1, letzter_versuch = now(),
    fehler = CASE WHEN e IN ('widerrufen', 'ungueltig') THEN NULL ELSE left(coalesce(nullif(btrim(regexp_replace(coalesce(d->>'fehler', ''), '[[:cntrl:]]', ' ', 'g')), ''), 'Unbekannter Fehler.'), 300) END,
    schluessel = CASE WHEN e IS NULL THEN schluessel END, erledigt_am = CASE WHEN e IS NOT NULL THEN now() END, ergebnis = e
  WHERE id = p_id;
  RETURN jsonb_build_object('ok', true, 'widerruf_id', w.id, 'erledigt', e IS NOT NULL, 'ergebnis', e);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_widerruf_liste(p_plattform text, p_anzahl integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  pl text := lower(btrim(coalesce(p_plattform, '')));
  n integer := least(greatest(coalesce(p_anzahl, 10), 1), 50);
  wd jsonb; sec text; app jsonb; liste jsonb; alt integer; weitere integer;
BEGIN
  IF pl NOT IN ('youtube', 'tiktok') THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Widerruf gibt es nur für YouTube und TikTok.');
  END IF;
  -- nach 7 Tagen aufgeben: Schlüssel löschen (nie länger aufbewahren); erledigte Einträge nach 90 Tagen entfernen
  UPDATE talent_widerrufe SET schluessel = NULL, erledigt_am = now(), ergebnis = 'aufgegeben',
    fehler = coalesce(fehler, 'Nicht innerhalb von 7 Tagen widerrufen.')
  WHERE erledigt_am IS NULL AND erstellt_am < now() - interval '7 days';
  GET DIAGNOSTICS alt = ROW_COUNT;
  DELETE FROM talent_widerrufe WHERE erledigt_am < now() - interval '90 days';
  IF NOT ally_verschluesselung_bereit() THEN
    RETURN jsonb_build_object('ok', false, 'fehler', 'Verschlüsselung ist nicht eingerichtet.');
  END IF;
  wd := talent_weg_weitere(pl, (talent_wege(pl))[1]);
  sec := ally_geheim(wd->>'geheim');
  app := jsonb_build_object('token_adresse', wd->>'token_adresse', 'client_param', wd->>'client_param', 'client_id', wd->>'app_id', 'client_secret', sec,
    'widerruf_adresse', CASE pl WHEN 'youtube' THEN 'https://oauth2.googleapis.com/revoke' ELSE 'https://open.tiktokapis.com/v2/oauth/revoke/' END,
    'widerruf_felder', CASE pl WHEN 'youtube' THEN '["token"]'::jsonb ELSE '["client_key", "client_secret", "token"]'::jsonb END,
    'fehler', CASE WHEN coalesce(wd->>'app_id', '') = '' OR sec = '' THEN 'Die App-Zugangsdaten für ' || talents_plattform_name(pl) || ' fehlen (Einstellungen › Plattform-Apps).' END);
  SELECT coalesce(jsonb_agg(jsonb_build_object('widerruf_id', w.id, 'kanal_id', w.kanal_id, 'plattform', w.plattform, 'versuche', w.versuche,
      'schluessel', ally_entschluesseln(w.schluessel)) ORDER BY w.id), '[]'::jsonb) INTO liste
  FROM (SELECT * FROM talent_widerrufe x WHERE x.plattform = pl AND x.erledigt_am IS NULL
          AND (x.letzter_versuch IS NULL OR x.letzter_versuch < now() - interval '1 hour') ORDER BY x.id LIMIT n) w;
  SELECT count(*)::integer - jsonb_array_length(liste) INTO weitere FROM talent_widerrufe x WHERE x.plattform = pl AND x.erledigt_am IS NULL;
  RETURN jsonb_build_object('ok', true, 'plattform', pl, 'anzahl', jsonb_array_length(liste), 'weitere', greatest(weitere, 0), 'aufgegeben', alt,
    'app', app, 'widerrufe', CASE WHEN app->>'fehler' IS NULL THEN liste ELSE '[]'::jsonb END);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_widerruf_vormerken(p_kanal_id integer, p_anlass text, p_user text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE n integer;
BEGIN
  INSERT INTO talent_widerrufe (kanal_id, talent_id, plattform, schluessel, anlass, erstellt_von)
  SELECT k.id, k.talent_id, k.plattform, k.schluessel, p_anlass, p_user FROM talent_kanaele k
  WHERE k.id = p_kanal_id AND k.plattform IN ('youtube', 'tiktok') AND k.schluessel IS NOT NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n > 0;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_youtube_daten_loeschen()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  y record; liste jsonb := '[]'::jsonb; meldungen jsonb := '[]'::jsonb; nm text;
BEGIN
  FOR y IN SELECT u.* FROM talents_youtube_unbestaetigt() u WHERE u.loeschen_am <= talents_heute() ORDER BY u.kanal_id LOOP
    nm := coalesce(talent_anzeigename(y.talent_id), 'Talent Nr. ' || y.talent_id);
    DELETE FROM talent_beitraege WHERE kanal_id = y.kanal_id;
    DELETE FROM talent_kanal_tage WHERE kanal_id = y.kanal_id;
    DELETE FROM talent_zielgruppen WHERE kanal_id = y.kanal_id;
    -- Migration 138 (Prüfung H2): abgeleitete Zahlen dieses Talents und die Summe aller Talents sofort mit löschen (YouTube-Richtlinien)
    DELETE FROM talents_zahlen_vorrat WHERE talent_id = y.talent_id OR talent_id IS NULL;
    UPDATE talent_kanaele SET extern_name = NULL, geaendert_am = now(),
      letzter_fehler = 'YouTube-Daten am ' || to_char(talents_heute(), 'DD.MM.YYYY') || ' gelöscht: Berechtigung seit über 30 Tagen nicht bestätigt (YouTube-Richtlinien).'
    WHERE id = y.kanal_id;
    liste := liste || jsonb_build_array(jsonb_build_object('kanal_id', y.kanal_id, 'talent_id', y.talent_id, 'anzeigename', nm));
    meldungen := meldungen || jsonb_build_array(jsonb_build_object('talent_id', y.talent_id, 'kanal_id', y.kanal_id, 'titel', 'Talents: YouTube-Daten gelöscht',
      'text', 'Die gespeicherten YouTube-Daten von ' || nm || ' (Zahlen, Videos, Zuschauer) wurden am ' || to_char(talents_heute(), 'DD.MM.YYYY')
        || ' gelöscht, weil die Berechtigung seit dem ' || talents_datum(y.basis) || ' nicht mehr bestätigt war. Das verlangen die YouTube-Richtlinien. '
        || 'Verbindet das Talent den Kanal neu, holt ' || produkt_name() || ' die Zahlen wieder ab.', 'empfaenger', talents_admin_empfaenger()));
  END LOOP;
  RETURN jsonb_build_object('anzahl', jsonb_array_length(liste), 'kanaele', liste, 'meldungen', meldungen);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_youtube_pflichten()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n_titel integer;
  n_namen integer;
  liste jsonb;
BEGIN
  UPDATE talent_beitraege b SET text_inhalt = NULL
  FROM talent_kanaele k
  WHERE k.id = b.kanal_id AND k.plattform = 'youtube' AND b.text_inhalt IS NOT NULL
    AND coalesce(b.aktualisiert_am, b.erfasst_am) < now() - interval '30 days';
  GET DIAGNOSTICS n_titel = ROW_COUNT;
  UPDATE talent_kanaele k SET extern_name = NULL, geaendert_am = now()
  WHERE k.plattform = 'youtube' AND k.extern_name IS NOT NULL
    AND coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am) < now() - interval '30 days';
  GET DIAGNOSTICS n_namen = ROW_COUNT;
  SELECT coalesce(jsonb_agg(jsonb_build_object('kanal_id', k.id, 'talent_id', k.talent_id, 'anzeigename', talent_anzeigename(k.talent_id),
      'status', k.status, 'bestaetigt_am', talents_datum(coalesce(k.geprueft_am, k.verbunden_am)),
      'tage', (talents_heute() - talents_tag(coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am))),
      'text', 'YouTube-Kanal von ' || coalesce(talent_anzeigename(k.talent_id), 'einem Talent') || ': Die Berechtigung ist seit über 30 Tagen nicht bestätigt. '
        || 'Nach den YouTube-Regeln löscht Ally die gespeicherten YouTube-Daten beim nächsten täglichen Lauf (TALENTS 4), wenn die Berechtigung nicht mehr besteht. Bitte neu verbinden lassen.')
      ORDER BY k.id), '[]'::jsonb) INTO liste
  FROM talent_kanaele k
  WHERE k.plattform = 'youtube' AND k.extern_id IS NOT NULL
    AND coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am) < now() - interval '30 days'
    AND (EXISTS (SELECT 1 FROM talent_kanal_tage x WHERE x.kanal_id = k.id) OR EXISTS (SELECT 1 FROM talent_beitraege x WHERE x.kanal_id = k.id)
         OR EXISTS (SELECT 1 FROM talent_zielgruppen x WHERE x.kanal_id = k.id));
  RETURN jsonb_build_object('ok', true, 'titel_entfernt', n_titel, 'namen_entfernt', n_namen, 'anzahl', jsonb_array_length(liste), 'ueberfaellig', liste);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_youtube_unbestaetigt()
 RETURNS TABLE(kanal_id integer, talent_id integer, status text, basis timestamp with time zone, loeschen_am date)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT k.id, k.talent_id, k.status, coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am),
    talents_tag(coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am)) + 30
  FROM talent_kanaele k
  WHERE k.plattform = 'youtube' AND k.extern_id IS NOT NULL AND NOT talents_ist_testdaten(k.talent_id)  -- Testdaten (Migration 79)
    AND (k.status IN ('abgelaufen', 'getrennt') OR coalesce(k.geprueft_am, k.verbunden_am, k.erstellt_am) < now() - interval '2 days')
    AND (EXISTS (SELECT 1 FROM talent_kanal_tage x WHERE x.kanal_id = k.id) OR EXISTS (SELECT 1 FROM talent_beitraege x WHERE x.kanal_id = k.id)
         OR EXISTS (SELECT 1 FROM talent_zielgruppen x WHERE x.kanal_id = k.id))
$function$
;

CREATE OR REPLACE FUNCTION public.talents_zahl(p jsonb)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE jsonb_typeof(p)
    WHEN 'number' THEN (p #>> '{}')::numeric
    WHEN 'string' THEN CASE WHEN btrim(p #>> '{}') ~ '^-?[0-9]{1,15}([.][0-9]{1,6})?$' THEN btrim(p #>> '{}')::numeric END
  END
$function$
;

CREATE OR REPLACE FUNCTION public.talents_zahl_text(p numeric)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT replace(to_char(round(p), 'FM999,999,999,999,990'), ',', '.')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_zahlen(p_kanaele integer[], p_von date, p_bis date, p_talents integer[], p_kanal text, p_manuell boolean)
 RETURNS TABLE(reichweite numeric, aufrufe numeric, interaktionen numeric, tage integer, follower numeric, follower_zuwachs numeric, manuell_anzahl integer, manuell_text text, doppelt_offen integer)
 LANGUAGE plpgsql
 STABLE ROWS 1
AS $function$
DECLARE
  ks integer[] := coalesce(p_kanaele, '{}'::integer[]);
  kf text := lower(btrim(coalesce(p_kanal, '')));
  r record;
  st jsonb;
  e text;
  gew jsonb := '[]'::jsonb;
  n_offen integer := 0;
BEGIN
  -- Summen wie talents_kanal_zahlen, mit manuellen Daten (Stefan 20.10.2026, 09:23/09:26; Migration 65). p_manuell = false: genau talents_kanal_zahlen.
  -- Manuelle Konto-Werte der Talents p_talents zählen, wenn sie zu einem der Accounts p_kanaele gehören oder (ohne Account-Zuordnung) zum Filter p_kanal passen
  -- ('' = alle, Plattform-Schlüssel, 'k<id>' = nur zugeordnete). Zeitraum-Kennzahlen nur, wenn ihr Zeitraum ganz in p_von..p_bis liegt; überlappen sich
  -- manuelle Werte derselben Kennzahl und desselben Accounts, zählt der längste. Doppelte Daten (talents_doppelt_status): offen oder „automatisch behalten“ =
  -- manueller Wert zählt nicht; „manuell verwenden“ = automatische Tageswerte der Accounts zählen für Kennzahl und Zeitraum nicht. Follower: je Account der
  -- letzte Stand bis p_bis (automatisch oder manuell; am selben Tag gewinnt ein entschiedener manueller Wert). Follower ohne eindeutigen Account zählen nicht.
  IF coalesce(p_manuell, false) AND coalesce(cardinality(p_talents), 0) > 0 AND p_bis IS NOT NULL AND p_von IS NOT NULL THEN
    FOR r IN
      SELECT m.id, m.talent_id, m.plattform, m.konto, m.kennzahl, coalesce(m.von, m.bis) AS von, m.bis, m.wert,
             talents_manuell_kanaele(m.talent_id, m.plattform, m.konto) AS mk
      FROM talent_manuell_werte m
      WHERE m.talent_id = ANY (p_talents) AND m.bereich = 'konto' AND m.wert IS NOT NULL
        AND m.kennzahl IN ('follower', 'reichweite', 'aufrufe', 'interaktionen') AND m.bis <= p_bis
        AND (m.kennzahl = 'follower' OR coalesce(m.von, m.bis) >= p_von)
      ORDER BY m.talent_id, m.plattform, m.kennzahl, m.bis - coalesce(m.von, m.bis) DESC, m.bis DESC, m.bestaetigt_am DESC, m.id DESC
    LOOP
      IF cardinality(r.mk) > 0 THEN
        CONTINUE WHEN NOT (r.mk && ks);
      ELSE
        -- Migration 152 (7d): kf darf eine Liste sein (talents_kanal_filter)
        CONTINUE WHEN NOT (kf = '' OR kf = r.plattform OR r.plattform = ANY (string_to_array(kf, ',')));
      END IF;
      st := talents_doppelt_status(r.id);
      IF NOT coalesce((st->>'zaehlt')::boolean, false) THEN
        IF st->>'status' = 'offen' THEN n_offen := n_offen + 1; END IF;
        CONTINUE;
      END IF;
      CONTINUE WHEN r.kennzahl = 'follower' AND cardinality(r.mk) > 1;
      e := CASE WHEN cardinality(r.mk) = 1 THEN 'k' || r.mk[1] ELSE 'p' || r.talent_id || ':' || r.plattform || ':' || lower(ltrim(btrim(coalesce(r.konto, '')), '@')) END;
      IF r.kennzahl <> 'follower' THEN
        CONTINUE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(gew) g WHERE g->>'e' = e AND g->>'k' = r.kennzahl
                              AND daterange((g->>'von')::date, (g->>'bis')::date, '[]') && daterange(r.von, r.bis, '[]'));
      END IF;
      gew := gew || jsonb_build_array(jsonb_build_object('id', r.id, 'e', e, 'k', r.kennzahl, 'von', r.von, 'bis', r.bis, 'w', r.wert,
        'aus', coalesce(st->'ausschluss', '[]'::jsonb), 'q', talents_plattform_name(r.plattform) || ' ' || talents_manuell_zeitraum_text(r.von, r.bis)));
    END LOOP;
  END IF;

  RETURN QUERY
  WITH g AS (
    SELECT x->>'k' AS k, x->>'e' AS e, (x->>'von')::date AS von, (x->>'bis')::date AS bis, (x->>'w')::numeric AS w, x->>'q' AS q,
           ARRAY(SELECT (y #>> '{}')::integer FROM jsonb_array_elements(x->'aus') y) AS aus
    FROM jsonb_array_elements(gew) x),
  a AS (
    SELECT kt.kanal_id, kt.tag,
      CASE WHEN kt.tag < p_von OR EXISTS (SELECT 1 FROM g WHERE g.k = 'reichweite' AND kt.kanal_id = ANY (g.aus) AND kt.tag BETWEEN g.von AND g.bis) THEN NULL
           ELSE talents_zahl(kt.werte->'reach') END AS r,
      CASE WHEN kt.tag < p_von OR EXISTS (SELECT 1 FROM g WHERE g.k = 'aufrufe' AND kt.kanal_id = ANY (g.aus) AND kt.tag BETWEEN g.von AND g.bis) THEN NULL
           ELSE talents_aufrufe(kt.werte) END AS a,
      CASE WHEN kt.tag < p_von OR EXISTS (SELECT 1 FROM g WHERE g.k = 'interaktionen' AND kt.kanal_id = ANY (g.aus) AND kt.tag BETWEEN g.von AND g.bis) THEN NULL
           ELSE talents_interaktionen(kt.werte) END AS i,
      talents_zahl(kt.werte->'followers_count') AS f
    FROM talent_kanal_tage kt WHERE kt.kanal_id = ANY (ks) AND kt.tag <= p_bis),
  fl AS (SELECT * FROM g WHERE g.k <> 'follower'),
  d AS (SELECT a.tag FROM a WHERE a.r IS NOT NULL OR a.a IS NOT NULL OR a.i IS NOT NULL
        UNION SELECT s::date FROM fl, generate_series(fl.von, fl.bis, interval '1 day') s),
  sf AS (SELECT 'k' || a.kanal_id AS e, a.tag, a.f AS w, 1 AS rang, NULL::text AS q FROM a WHERE a.f IS NOT NULL
         UNION ALL SELECT g.e, g.bis, g.w, 0, g.q FROM g WHERE g.k = 'follower'),
  ende AS (SELECT DISTINCT ON (sf.e) sf.* FROM sf ORDER BY sf.e, sf.tag DESC, sf.rang),
  anf AS (SELECT DISTINCT ON (sf.e) sf.* FROM sf WHERE sf.tag < p_von ORDER BY sf.e, sf.tag DESC, sf.rang),
  su AS (SELECT (SELECT sum(a.r) FROM a) AS ar, (SELECT sum(a.a) FROM a) AS aa, (SELECT sum(a.i) FROM a) AS ai,
                (SELECT sum(fl.w) FROM fl WHERE fl.k = 'reichweite') AS mr, (SELECT sum(fl.w) FROM fl WHERE fl.k = 'aufrufe') AS ma,
                (SELECT sum(fl.w) FROM fl WHERE fl.k = 'interaktionen') AS mi)
  SELECT
    CASE WHEN su.ar IS NULL AND su.mr IS NULL THEN NULL ELSE coalesce(su.ar, 0) + coalesce(su.mr, 0) END,
    CASE WHEN su.aa IS NULL AND su.ma IS NULL THEN NULL ELSE coalesce(su.aa, 0) + coalesce(su.ma, 0) END,
    CASE WHEN su.ai IS NULL AND su.mi IS NULL THEN NULL ELSE coalesce(su.ai, 0) + coalesce(su.mi, 0) END,
    (SELECT count(DISTINCT d.tag) FROM d)::integer,
    (SELECT sum(ende.w) FROM ende),
    (SELECT sum(ende.w - anf.w) FROM ende JOIN anf ON anf.e = ende.e),
    ((SELECT count(*) FROM fl) + (SELECT count(*) FROM ende WHERE ende.rang = 0))::integer,
    (SELECT 'manuell: ' || string_agg(x.q, '; ' ORDER BY x.q) FROM (SELECT fl.q FROM fl UNION ALL SELECT ende.q FROM ende WHERE ende.rang = 0) x),
    n_offen
  FROM su;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_zahlen_vorrat_fuellen()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  heute date := talents_heute();
  zr jsonb := talents_zeitraum('{}'::jsonb, '28tage', false);
  d_von date := (zr->>'von')::date;
  d_bis date := (zr->>'bis')::date;
  d_vv date := (zr->>'vor_von')::date;
  d_vb date := (zr->>'vor_bis')::date;
  n_u integer := 0; n_k integer := 0; n_s integer := 0; n_weg integer := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('talents_zahlen_vorrat')) THEN
    RETURN jsonb_build_object('ok', true, 'uebersprungen', true);
  END IF;
  BEGIN
    PERFORM set_config('lock_timeout', '5s', true);
    DELETE FROM talents_zahlen_vorrat r
    WHERE r.talent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM talents t WHERE t.id = r.talent_id AND t.status = 'aktiv');
    GET DIAGNOSTICS n_weg = ROW_COUNT;

    -- Übersicht je Talent (wie talents_uebersicht ohne Filter: alle Kanäle, manuelle Daten an)
    WITH s AS (SELECT * FROM talents_vorrat_staende()),
    neu AS MATERIALIZED (SELECT s.* FROM s WHERE NOT EXISTS (SELECT 1 FROM talents_zahlen_vorrat r WHERE r.art = 'uebersicht' AND r.talent_id = s.talent_id
              AND r.von = d_von AND r.bis = d_bis AND r.vor_von = d_vv AND r.vor_bis = d_vb AND r.stand = s.stand AND r.kids = s.kids))
    INSERT INTO talents_zahlen_vorrat AS r (art, talent_id, von, bis, vor_von, vor_bis, kids, talents, stand, j, v, berechnet_am)
    SELECT 'uebersicht', neu.talent_id, d_von, d_bis, d_vv, d_vb, neu.kids, ARRAY[neu.talent_id], neu.stand, to_jsonb(j), to_jsonb(v), now()
    FROM neu
    CROSS JOIN LATERAL talents_zahlen(neu.kids, d_von, d_bis, ARRAY[neu.talent_id], '', true) j
    CROSS JOIN LATERAL talents_zahlen(neu.kids, d_vv, d_vb, ARRAY[neu.talent_id], '', true) v
    ON CONFLICT (art, (coalesce(talent_id, 0))) DO UPDATE SET von = EXCLUDED.von, bis = EXCLUDED.bis, vor_von = EXCLUDED.vor_von, vor_bis = EXCLUDED.vor_bis,
      kids = EXCLUDED.kids, talents = EXCLUDED.talents, stand = EXCLUDED.stand, j = EXCLUDED.j, v = EXCLUDED.v, berechnet_am = EXCLUDED.berechnet_am;
    GET DIAGNOSTICS n_u = ROW_COUNT;

    -- Kachel je Talent (wie talents_kachel: 7 Tage bis gestern gegen die 7 Tage davor)
    WITH s AS (SELECT * FROM talents_vorrat_staende()),
    neu AS MATERIALIZED (SELECT s.* FROM s WHERE NOT EXISTS (SELECT 1 FROM talents_zahlen_vorrat r WHERE r.art = 'kachel' AND r.talent_id = s.talent_id
              AND r.von = heute - 7 AND r.bis = heute - 1 AND r.vor_von = heute - 14 AND r.vor_bis = heute - 8 AND r.stand = s.stand AND r.kids = s.kids))
    INSERT INTO talents_zahlen_vorrat AS r (art, talent_id, von, bis, vor_von, vor_bis, kids, talents, stand, j, v, berechnet_am)
    SELECT 'kachel', neu.talent_id, heute - 7, heute - 1, heute - 14, heute - 8, neu.kids, ARRAY[neu.talent_id], neu.stand, to_jsonb(j), to_jsonb(v), now()
    FROM neu
    CROSS JOIN LATERAL talents_zahlen(neu.kids, heute - 7, heute - 1, ARRAY[neu.talent_id], '', true) j
    CROSS JOIN LATERAL talents_zahlen(neu.kids, heute - 14, heute - 8, ARRAY[neu.talent_id], '', true) v
    ON CONFLICT (art, (coalesce(talent_id, 0))) DO UPDATE SET von = EXCLUDED.von, bis = EXCLUDED.bis, vor_von = EXCLUDED.vor_von, vor_bis = EXCLUDED.vor_bis,
      kids = EXCLUDED.kids, talents = EXCLUDED.talents, stand = EXCLUDED.stand, j = EXCLUDED.j, v = EXCLUDED.v, berechnet_am = EXCLUDED.berechnet_am;
    GET DIAGNOSTICS n_k = ROW_COUNT;

    -- Summe aller aktiven Talents (Übersicht)
    WITH s AS MATERIALIZED (SELECT * FROM talents_vorrat_staende()),
    a AS (SELECT coalesce(array_agg(s.talent_id ORDER BY s.talent_id), '{}'::integer[]) AS tids,
                 md5(coalesce(string_agg(s.talent_id || ':' || s.stand, ',' ORDER BY s.talent_id), '')) AS stand FROM s),
    ak AS (SELECT coalesce(array_agg(x ORDER BY x), '{}'::integer[]) AS kids FROM s CROSS JOIN LATERAL unnest(s.kids) x),
    neu AS MATERIALIZED (SELECT a.tids, a.stand, ak.kids FROM a CROSS JOIN ak
            WHERE NOT EXISTS (SELECT 1 FROM talents_zahlen_vorrat r WHERE r.art = 'uebersicht' AND r.talent_id IS NULL
                                AND r.von = d_von AND r.bis = d_bis AND r.vor_von = d_vv AND r.vor_bis = d_vb AND r.stand = a.stand AND r.talents = a.tids))
    INSERT INTO talents_zahlen_vorrat AS r (art, talent_id, von, bis, vor_von, vor_bis, kids, talents, stand, j, v, berechnet_am)
    SELECT 'uebersicht', NULL, d_von, d_bis, d_vv, d_vb, neu.kids, neu.tids, neu.stand, to_jsonb(j), to_jsonb(v), now()
    FROM neu
    CROSS JOIN LATERAL talents_zahlen(neu.kids, d_von, d_bis, neu.tids, '', true) j
    CROSS JOIN LATERAL talents_zahlen(neu.kids, d_vv, d_vb, neu.tids, '', true) v
    ON CONFLICT (art, (coalesce(talent_id, 0))) DO UPDATE SET von = EXCLUDED.von, bis = EXCLUDED.bis, vor_von = EXCLUDED.vor_von, vor_bis = EXCLUDED.vor_bis,
      kids = EXCLUDED.kids, talents = EXCLUDED.talents, stand = EXCLUDED.stand, j = EXCLUDED.j, v = EXCLUDED.v, berechnet_am = EXCLUDED.berechnet_am;
    GET DIAGNOSTICS n_s = ROW_COUNT;

    RETURN jsonb_build_object('ok', true, 'uebersicht', n_u, 'kachel', n_k, 'summe', n_s, 'entfernt', n_weg);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'fehler', left(SQLERRM, 200));
  END;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_zahlen_vorrat_lesen(p_art text, p_von date, p_bis date, p_vor_von date, p_vor_bis date)
 RETURNS TABLE(talent_id integer, j jsonb, v jsonb)
 LANGUAGE sql
 STABLE ROWS 50
AS $function$
  WITH s AS MATERIALIZED (SELECT * FROM talents_vorrat_staende()),
  a AS (SELECT coalesce(array_agg(s.talent_id ORDER BY s.talent_id), '{}'::integer[]) AS tids,
               md5(coalesce(string_agg(s.talent_id || ':' || s.stand, ',' ORDER BY s.talent_id), '')) AS stand FROM s)
  SELECT r.talent_id, r.j, r.v FROM talents_zahlen_vorrat r JOIN s ON s.talent_id = r.talent_id
  WHERE r.art = p_art AND r.von = p_von AND r.bis = p_bis AND r.vor_von = p_vor_von AND r.vor_bis = p_vor_bis
    AND r.stand = s.stand AND r.kids = s.kids AND r.talents = ARRAY[s.talent_id]
  UNION ALL
  SELECT NULL::integer, r.j, r.v FROM talents_zahlen_vorrat r CROSS JOIN a
  WHERE r.art = p_art AND r.talent_id IS NULL AND r.von = p_von AND r.bis = p_bis AND r.vor_von = p_vor_von AND r.vor_bis = p_vor_bis
    AND r.stand = a.stand AND r.talents = a.tids
$function$
;

CREATE OR REPLACE FUNCTION public.talents_zahlen_vorrat_summe_weg()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  DELETE FROM talents_zahlen_vorrat WHERE talent_id IS NULL;
  RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_zeit(p timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT to_char(p AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI')
$function$
;

CREATE OR REPLACE FUNCTION public.talents_zeitraeume(p_alle boolean)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN p_alle THEN '[{"schluessel": "alle", "name": "Gesamter Zeitraum"}]'::jsonb ELSE '[]'::jsonb END
    || '[{"schluessel": "7tage", "name": "Letzte 7 Tage"}, {"schluessel": "28tage", "name": "Letzte 28 Tage"}, {"schluessel": "monat", "name": "Dieser Monat"},
         {"schluessel": "vormonat", "name": "Vormonat"}, {"schluessel": "frei", "name": "Eigener Zeitraum"}]'::jsonb
$function$
;

CREATE OR REPLACE FUNCTION public.talents_zeitraum(p_filter jsonb, p_standard text, p_alle_erlaubt boolean, p_heute date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  heute date := coalesce(p_heute, talents_heute());
  gestern date := coalesce(p_heute, talents_heute()) - 1;
  f jsonb := CASE WHEN jsonb_typeof(p_filter) = 'object' THEN p_filter ELSE '{}'::jsonb END;
  art text := lower(btrim(coalesce(f->>'zeitraum', '')));
  sv text := left(btrim(coalesce(f->>'von', '')), 20);
  sb text := left(btrim(coalesce(f->>'bis', '')), 20);
  von date; bis date; vv date; vb date;
  name text; fehler text; hinweis text;
  namen jsonb := '{"7tage": "Letzte 7 Tage", "28tage": "Letzte 28 Tage", "monat": "Dieser Monat", "vormonat": "Vormonat", "frei": "Eigener Zeitraum", "alle": "Gesamter Zeitraum"}';
BEGIN
  IF art = '' THEN
    art := p_standard;
  END IF;
  IF art NOT IN ('7tage', '28tage', 'monat', 'vormonat', 'frei') AND NOT (p_alle_erlaubt AND art = 'alle') THEN
    fehler := 'Unbekannter Zeitraum. Angezeigt wird „' || (namen->>p_standard) || '“.';
    art := p_standard;
  END IF;
  IF art = 'frei' THEN
    von := talents_datum_lesen(sv);
    bis := talents_datum_lesen(sb);
    IF von IS NULL OR bis IS NULL THEN
      fehler := 'Bitte Beginn und Ende des Zeitraums als Datum angeben.';
    ELSIF von > bis THEN
      fehler := 'Der Beginn des Zeitraums liegt nach dem Ende.';
    ELSE
      IF bis > gestern THEN
        bis := gestern;
        hinweis := 'Heute ist noch nicht abgeschlossen. Der Zeitraum endet deshalb gestern.';
      END IF;
      IF von > bis THEN
        fehler := 'Der Zeitraum muss vor heute beginnen.';
        hinweis := NULL;
      ELSIF bis - von + 1 > 366 THEN
        fehler := 'Der Zeitraum darf höchstens 366 Tage lang sein.';
        hinweis := NULL;
      END IF;
    END IF;
    IF fehler IS NOT NULL THEN
      fehler := fehler || ' Angezeigt wird „' || (namen->>p_standard) || '“.';
      art := p_standard;
    END IF;
  END IF;
  IF art = 'monat' AND extract(day FROM heute) = 1 THEN
    art := 'vormonat';
    hinweis := 'Der Monat hat heute begonnen. Angezeigt wird der Vormonat.';
  END IF;
  IF art = '7tage' THEN
    von := heute - 7; bis := gestern;
  ELSIF art = '28tage' THEN
    von := heute - 28; bis := gestern;
  ELSIF art = 'monat' THEN
    von := date_trunc('month', heute)::date; bis := gestern;
  ELSIF art = 'vormonat' THEN
    von := (date_trunc('month', heute) - interval '1 month')::date; bis := date_trunc('month', heute)::date - 1;
  ELSIF art = 'alle' THEN
    von := NULL; bis := NULL;
  END IF;
  IF von IS NOT NULL THEN
    vb := von - 1;
    vv := von - (bis - von + 1);
  END IF;
  name := namen->>art;
  RETURN jsonb_build_object('schluessel', art, 'name', name,
    'von', to_char(von, 'YYYY-MM-DD'), 'bis', to_char(bis, 'YYYY-MM-DD'),
    'von_text', to_char(von, 'DD.MM.YYYY'), 'bis_text', to_char(bis, 'DD.MM.YYYY'),
    'tage', CASE WHEN von IS NOT NULL THEN bis - von + 1 END,
    'text', CASE WHEN art = 'vormonat' THEN talents_monat_text(von)
                 WHEN art = 'monat' THEN talents_monat_text(von) || ' bis ' || to_char(bis, 'DD.MM.YYYY')
                 WHEN von IS NOT NULL THEN to_char(von, 'DD.MM.YYYY') || ' bis ' || to_char(bis, 'DD.MM.YYYY')
                 ELSE 'Alle Beiträge' END,
    'vor_von', to_char(vv, 'YYYY-MM-DD'), 'vor_bis', to_char(vb, 'YYYY-MM-DD'),
    'vor_text', CASE WHEN vv IS NOT NULL THEN 'Vergleich mit ' || to_char(vv, 'DD.MM.YYYY') || ' bis ' || to_char(vb, 'DD.MM.YYYY') END,
    -- Eingaben für das Formular "frei" (zurück in die Felder)
    'frei_von', CASE WHEN art = 'frei' THEN to_char(von, 'YYYY-MM-DD') ELSE nullif(sv, '') END,
    'frei_bis', CASE WHEN art = 'frei' THEN to_char(bis, 'YYYY-MM-DD') ELSE nullif(sb, '') END,
    'fehler', fehler, 'hinweis', hinweis);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_ziel_stand(p_ziel_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  z talent_konzept_ziele;
  ids integer[];
  stand date;
  tage_gesamt integer;
  tage_um integer;
  anteil numeric;
  ist numeric; anfang numeric; soll_heute numeric; abw numeric;
  st text;
  schwelle numeric := coalesce(nullif(ally_einstellung('talents_konzept_abweichung_prozent'), '')::numeric, 25);
  zr record;
  namen jsonb := '{"follower": "Follower", "follower_zuwachs": "Follower-Zuwachs", "reichweite": "Reichweite", "aufrufe": "Aufrufe",
                  "interaktionen": "Interaktionen", "interaktionsrate": "Interaktionsrate", "beitraege": "Beiträge"}';
BEGIN
  SELECT * INTO z FROM talent_konzept_ziele WHERE id = p_ziel_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT coalesce(array_agg(k.id), '{}') INTO ids FROM talent_kanaele k
  WHERE k.talent_id = z.talent_id AND k.extern_id IS NOT NULL AND (z.plattform IS NULL OR k.plattform = z.plattform);
  stand := least(z.bis, talents_heute() - 1);
  tage_gesamt := z.bis - z.von + 1;
  tage_um := greatest(0, least(tage_gesamt, stand - z.von + 1));
  anteil := tage_um::numeric / tage_gesamt;
  IF tage_um = 0 THEN
    st := 'offen';
  ELSE
    -- Migration 65: manuelle Daten zählen mit (ohne Doppelzählung)
    SELECT * INTO zr FROM talents_zahlen(ids, z.von, stand, ARRAY[z.talent_id], coalesce(z.plattform, ''), true);
    IF z.kennzahl = 'follower' THEN
      ist := zr.follower;
      anfang := zr.follower - zr.follower_zuwachs;
      soll_heute := CASE WHEN anfang IS NOT NULL THEN anfang + (z.zielwert - anfang) * anteil ELSE z.zielwert END;
    ELSIF z.kennzahl = 'follower_zuwachs' THEN
      ist := zr.follower_zuwachs; soll_heute := z.zielwert * anteil;
    ELSIF z.kennzahl = 'reichweite' THEN
      ist := zr.reichweite; soll_heute := z.zielwert * anteil;
    ELSIF z.kennzahl = 'aufrufe' THEN
      ist := zr.aufrufe; soll_heute := z.zielwert * anteil;
    ELSIF z.kennzahl = 'interaktionen' THEN
      ist := zr.interaktionen; soll_heute := z.zielwert * anteil;
    ELSIF z.kennzahl = 'interaktionsrate' THEN
      ist := CASE WHEN zr.reichweite > 0 AND zr.interaktionen IS NOT NULL THEN round(zr.interaktionen / zr.reichweite * 100, 1) END;
      soll_heute := z.zielwert;
    ELSE
      SELECT count(*) INTO ist FROM talent_beitraege b WHERE b.kanal_id = ANY (ids) AND talents_beitrag_art(b.art, b.produkt_art) <> 'story'
        AND (coalesce(b.erstellt, b.erfasst_am) AT TIME ZONE 'Europe/Berlin')::date BETWEEN z.von AND stand;
      soll_heute := z.zielwert * anteil;
    END IF;
    IF ist IS NULL THEN
      st := 'keine_daten';
    ELSE
      abw := CASE WHEN soll_heute > 0 THEN round((ist - soll_heute) / soll_heute * 100) END;
      IF stand >= z.bis THEN
        st := CASE WHEN ist >= z.zielwert THEN 'erreicht' ELSE 'verfehlt' END;
      ELSIF abw IS NULL OR abs(abw) < schwelle THEN
        st := 'im_plan';
      ELSE
        st := CASE WHEN abw < 0 THEN 'darunter' ELSE 'darueber' END;
      END IF;
    END IF;
  END IF;
  RETURN jsonb_build_object('ziel_id', z.id, 'kennzahl', z.kennzahl, 'kennzahl_name', namen->>z.kennzahl,
    'plattform', z.plattform, 'plattform_name', CASE WHEN z.plattform IS NULL THEN 'alle Kanäle' ELSE talents_plattform_name(z.plattform) END,
    'von', to_char(z.von, 'YYYY-MM-DD'), 'bis', to_char(z.bis, 'YYYY-MM-DD'),
    'zeitraum_text', to_char(z.von, 'DD.MM.YYYY') || ' bis ' || to_char(z.bis, 'DD.MM.YYYY'),
    'soll', z.zielwert, 'soll_text', CASE WHEN z.kennzahl = 'interaktionsrate' THEN talents_dezimal_text(z.zielwert, 1) || ' %' ELSE talents_zahl_text(z.zielwert) END,
    'soll_bis_heute', round(soll_heute, 1),
    'soll_bis_heute_text', CASE WHEN soll_heute IS NULL THEN NULL WHEN z.kennzahl = 'interaktionsrate' THEN talents_dezimal_text(soll_heute, 1) || ' %' ELSE talents_zahl_text(soll_heute) END,
    'ist', ist, 'ist_text', CASE WHEN ist IS NULL THEN 'nicht verfügbar' WHEN z.kennzahl = 'interaktionsrate' THEN talents_dezimal_text(ist, 1) || ' %' ELSE talents_zahl_text(ist) END,
    'stand_text', CASE WHEN tage_um > 0 THEN 'Stand ' || to_char(stand, 'DD.MM.YYYY') END,
    'abweichung_prozent', abw,
    'abweichung_text', CASE WHEN abw IS NULL THEN NULL WHEN abw > 0 THEN '+' || abw || ' % zum Plan' WHEN abw < 0 THEN '−' || abs(abw) || ' % zum Plan' ELSE 'genau im Plan' END,
    'status', st,
    'status_text', CASE st WHEN 'offen' THEN 'beginnt am ' || to_char(z.von, 'DD.MM.YYYY') WHEN 'im_plan' THEN 'im Plan' WHEN 'darunter' THEN 'deutlich unter Plan'
                           WHEN 'darueber' THEN 'deutlich über Plan' WHEN 'erreicht' THEN 'erreicht' WHEN 'verfehlt' THEN 'nicht erreicht' ELSE 'keine Zahlen' END,
    'deutlich', st IN ('darunter', 'darueber'), 'von_ki', z.von_ki);
END $function$
;

CREATE OR REPLACE FUNCTION public.talents_zielgruppe(p_kanaele integer[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 77: Zielgruppe mit höchstens 10 Einträgen je Gruppe (wie bisher), Berechnung in talents_zielgruppe_max
  SELECT talents_zielgruppe_max(p_kanaele, 10)
$function$
;

CREATE OR REPLACE FUNCTION public.talents_zielgruppe_max(p_kanaele integer[], p_max integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  -- Migration 77 (Stefan 21.10.2026): wie talents_zielgruppe, aber mit wählbarer Höchstzahl je Gruppe (p_max NULL = alle Einträge, für die eigene Seite „Alle anzeigen“)
  WITH l AS (
    SELECT DISTINCT ON (z.kanal_id, z.art) z.kanal_id, z.art, z.stand, z.werte FROM talent_zielgruppen z
    WHERE z.kanal_id = ANY (p_kanaele) ORDER BY z.kanal_id, z.art, z.stand DESC),
  e AS (
    SELECT l.*, split_part(l.art, ':', 1) AS gruppe, split_part(l.art, ':', 2) AS aufteilung FROM l)
  SELECT coalesce(jsonb_agg(jsonb_build_object('kanal_id', e.kanal_id, 'plattform', k.plattform, 'art', e.art,
      'gruppe', e.gruppe, 'aufteilung', e.aufteilung,
      -- YouTube: viewer_demographics = Zuschauer (Alter/Geschlecht in Prozent), Land = Aufrufe (Stefan 18.10.2026)
      'name', CASE WHEN e.art = 'viewer_demographics:country' THEN 'Aufrufe'
                   ELSE CASE e.gruppe WHEN 'follower_demographics' THEN 'Follower' WHEN 'engaged_audience_demographics' THEN 'Interagierende Konten'
                                      WHEN 'viewer_demographics' THEN 'Zuschauer' ELSE e.gruppe END END
              || ' nach ' || CASE e.aufteilung WHEN 'age' THEN 'Alter' WHEN 'gender' THEN 'Geschlecht' WHEN 'country' THEN 'Land' WHEN 'city' THEN 'Stadt'
                                               ELSE coalesce(nullif(e.aufteilung, ''), 'Merkmal') END,
      'plattform_name', talents_plattform_name(k.plattform),
      'stand', to_char(e.stand, 'DD.MM.YYYY'), 'summe', s.summe, 'eintraege', s.eintraege, 'weitere', greatest(s.anzahl - coalesce(p_max, s.anzahl), 0))
      ORDER BY array_position(talents_plattformen(), k.plattform), e.kanal_id,
        CASE e.gruppe WHEN 'follower_demographics' THEN 1 WHEN 'engaged_audience_demographics' THEN 2 ELSE 3 END,
        CASE e.aufteilung WHEN 'age' THEN 1 WHEN 'gender' THEN 2 WHEN 'country' THEN 3 WHEN 'city' THEN 4 ELSE 5 END, e.art), '[]'::jsonb)
  FROM e
  JOIN talent_kanaele k ON k.id = e.kanal_id
  CROSS JOIN LATERAL (
    SELECT (SELECT sum(talents_zahl(x.value)) FROM jsonb_each(e.werte) x WHERE talents_zahl(x.value) IS NOT NULL) AS summe,
           (SELECT count(*)::integer FROM jsonb_each(e.werte) x WHERE talents_zahl(x.value) IS NOT NULL) AS anzahl,
           (SELECT coalesce(jsonb_agg(jsonb_build_object('schluessel', y.key,
                'name', CASE WHEN e.aufteilung = 'gender' THEN CASE upper(y.key) WHEN 'F' THEN 'weiblich' WHEN 'M' THEN 'männlich' WHEN 'U' THEN 'unbekannt' ELSE y.key END ELSE y.key END,
                'wert', y.w, 'text', CASE WHEN e.art IN ('viewer_demographics:age', 'viewer_demographics:gender') THEN talents_dezimal_text(y.w, 1) || ' %' ELSE talents_zahl_text(y.w) END,
                'anteil', CASE WHEN e.art IN ('viewer_demographics:age', 'viewer_demographics:gender') THEN round(y.w, 1) WHEN y.su > 0 THEN round(y.w / y.su * 100, 1) END,
                'anteil_text', CASE WHEN e.art IN ('viewer_demographics:age', 'viewer_demographics:gender') THEN talents_dezimal_text(y.w, 1) || ' %'
                                    WHEN y.su > 0 THEN talents_dezimal_text(y.w / y.su * 100, 1) || ' %' END) ORDER BY y.o), '[]'::jsonb)
            FROM (SELECT x.key, talents_zahl(x.value) AS w, sum(talents_zahl(x.value)) OVER () AS su,
                         row_number() OVER (ORDER BY CASE WHEN e.aufteilung = 'age' THEN x.key END, talents_zahl(x.value) DESC, x.key) AS o
                  FROM jsonb_each(e.werte) x WHERE talents_zahl(x.value) IS NOT NULL) y WHERE p_max IS NULL OR y.o <= p_max) AS eintraege) s
$function$
;

CREATE OR REPLACE FUNCTION public.talents_zugriff(p_user text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- Zugriff auf Talents (Migration 64): 'alle' oder 'eigene' (= zugeordnete) nach der Reichweite von „Talents ansehen“
  SELECT CASE ally_recht_reichweite(p_user, 'talents_ansehen') WHEN 'alle' THEN 'alle' WHEN 'zugeordnet' THEN 'eigene' END
$function$
;

CREATE OR REPLACE FUNCTION public.webapp_einstellungen_web(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; adm boolean; sa boolean; pfr boolean; pfe boolean; igr boolean; mk boolean;
  w jsonb; li jsonb; ki jsonb; sy jsonb; sp jsonb; ab jsonb; ka jsonb; pf jsonb; eig jsonb; sh jsonb;
BEGIN
  SELECT * INTO s FROM ally_ui_sitzung(p_token) y WHERE NOT y.muss_pw_setzen;
  IF NOT FOUND OR s.person IS NULL THEN RETURN jsonb_build_object('ok', false); END IF;
  adm := coalesce(ally_hat_recht(s.person, 'admin'), false);
  sa  := coalesce(ally_hat_recht(s.person, 'superadmin'), false);
  pfr := coalesce(ally_hat_recht(s.person, 'postfaecher'), false);
  pfe := coalesce(ally_hat_recht(s.person, 'postfaecher_eigene'), false);
  igr := coalesce(ally_hat_recht(s.person, 'instagram'), false);
  mk  := coalesce(ally_ui_funktion_erlaubt(s.person, s.rolle, 'marketing'), false);
  w := coalesce(ally_web_daten(s.person), '{}'::jsonb);

  -- Postfächer: gemeinsame (Verbindungen) nur mit Admin oder Recht „Gemeinsame Postfächer verwalten“; eigene (Mein Konto) für die Person selbst
  IF adm OR pfr THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('platz', p->'platz', 'adresse', p->>'adresse', 'name', p->>'name', 'aktiv', p->'aktiv',
        'zugang', jsonb_build_object('host', p->'zugang'->'host', 'port', p->'zugang'->'port', 'benutzer', p->'zugang'->'benutzer', 'ssl', p->'zugang'->'ssl',
          'ergebnis', p->'zugang'->'ergebnis', 'geprueft', p->'zugang'->'geprueft', 'ordner_stand', p->'zugang'->'ordner_stand'))
        ORDER BY lower(coalesce(p->>'adresse', ''))), '[]'::jsonb)
      INTO pf FROM jsonb_array_elements(coalesce(w->'postfaecher', '[]'::jsonb)) p WHERE p->>'art' = 'gemeinsam';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('platz', p->'platz', 'adresse', p->>'adresse', 'ergebnis', p->'zugang'->'ergebnis') ORDER BY lower(coalesce(p->>'adresse', ''))), '[]'::jsonb)
    INTO eig FROM jsonb_array_elements(coalesce(w->'postfaecher', '[]'::jsonb)) p WHERE p->>'art' = 'persoenlich' AND coalesce((p->>'eigen')::boolean, false);

  IF mk THEN
    li := linkedin_web_stand(p_token);
    IF li IS NOT NULL THEN
      li := li || jsonb_build_object('rueck', CASE WHEN coalesce(ally_oberflaeche_webhook(), '') <> '' THEN ally_oberflaeche_webhook() || '/' || ally_webhook_praefix_aussen() || '/linkedin' END);
      IF NOT adm THEN li := li - 'client_id' - 'seite_client_id'; END IF;
    END IF;
  END IF;

  IF adm THEN
    ki := (SELECT jsonb_build_object('ki_schluessel', k->'ki_schluessel', 'anbieter_name', k->'anbieter_name', 'zugang_geprueft', k->'zugang_geprueft',
            'darf_schluessel_aendern', k->'darf_schluessel_aendern', 'eigener_schluessel_erlaubt', k->'eigener_schluessel_erlaubt')
           FROM ki_web_daten(p_token) k WHERE (k->>'ok') = 'true');
    sy := (SELECT jsonb_build_object('stand', x->'stand', 'zahlen', x->'zahlen') FROM ally_systemnachricht_absender_web(p_token) x WHERE (x->>'ok') = 'true');
    sp := (SELECT x->'eigen' FROM ally_speicherorte_ui(p_token) x WHERE (x->>'ok') = 'true');
    ab := (SELECT jsonb_build_object('art', a->'art', 'name', a->'name', 'aktiv', a->'aktiv', 'verbunden', a->'verbunden', 'geprueft_am', a->'geprueft_am')
           FROM ablage_web_seite(p_token) a);
    IF plattform_modul_an('shopify') AND NOT ally_person_ist_testdaten(s.person) THEN
      sh := (SELECT jsonb_build_object('anzahl', count(*), 'verbunden', count(*) FILTER (WHERE o.access_token IS NOT NULL),
               'fehler', count(*) FILTER (WHERE o.pruef_ok = false))
             FROM shopify_shops o WHERE o.aktiv);
    END IF;
  END IF;
  ka := (SELECT jsonb_build_object('google', x->'google', 'abo', x->'abo') FROM ally_kalender_abo_ui(p_token) x WHERE (x->>'ok') = 'true');

  RETURN jsonb_build_object('ok', true,
    'rechte', jsonb_build_object('admin', adm, 'superadmin', sa, 'postfaecher', pfr, 'postfaecher_eigene', pfe, 'instagram', igr, 'marketing', mk),
    'postfaecher', pf, 'plaetze_frei', CASE WHEN adm OR pfr THEN w->'plaetze_frei' END, 'plaetze_live', CASE WHEN adm OR pfr THEN w->'plaetze_live' END,
    -- Migration 170 (Schritt P): Kennzeichen Höchstzahl erreicht (Hinweis statt „Alle 10 Plätze sind belegt.“)
    'hoechstzahl_erreicht', CASE WHEN adm OR pfr THEN w->'postfaecher_hoechstzahl_erreicht' END,
    'eigene_postfaecher', eig,
    'systemnachricht', sy,
    'speicherort', CASE WHEN adm THEN jsonb_build_object('eigen', sp, 'ablage', ab) END,
    'linkedin', li,
    'instagram', CASE WHEN igr THEN coalesce(w->'instagram', '{}'::jsonb) END,
    'shopify', sh,
    'kalender', coalesce(ka, '{}'::jsonb) || jsonb_build_object('kalender_id', coalesce(w->'einstellungen'->>'kalender_id', '')),
    'papierkram', CASE WHEN adm THEN coalesce(w->'papierkram', '{}'::jsonb) END,
    'ki', ki,
    -- Funktionen mit eigenen Einstellungen (wie ALLY 23 „Daten laden“ funktionen): nur, was die Person nutzen darf
    'funktionen', (SELECT coalesce(jsonb_agg(jsonb_build_object('schluessel', f.schluessel,
      -- Migration 181 (Teil C): der Eintrag der Reports unter Funktionen enthält nur die persönlichen Schalter des Pakets
      'name', CASE WHEN f.schluessel = 'talent-reports' COLLATE "C" THEN 'Meine Hinweise zu Talents' ELSE ally_ui_name(f.name) END, 'ziel', f.einstellungen_ziel) ORDER BY f.sortierung, f.schluessel), '[]'::jsonb)
      FROM ally_ui_funktionen f WHERE f.art = 'funktion' AND f.einstellungen_ziel IS NOT NULL AND ally_ui_funktion_erlaubt(s.person, s.rolle, f.schluessel)));
END $function$
;

CREATE OR REPLACE FUNCTION public.webapp_kosten_alle_web(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
BEGIN
  -- Migration 127: Kosten aller Funktionen (Startseite, eine Zeile je Kachel); Sichtbarkeit wie webapp_kosten_web
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false); END IF;
  IF NOT coalesce(ally_ui_funktion_erlaubt(s.person, s.rolle, 'ki-verbrauch'), false) THEN
    RETURN jsonb_build_object('ok', true, 'sichtbar', false);
  END IF;
  RETURN jsonb_build_object('ok', true, 'sichtbar', true,
    'je', (SELECT coalesce(jsonb_object_agg(f.funktion, webapp_kosten_rechnen(f.funktion)), '{}'::jsonb) FROM webapp_funktion_kosten f));
END $function$
;

CREATE OR REPLACE FUNCTION public.webapp_kosten_rechnen(p_funktion text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  k record; kurs numeric; monat numeric := 0; lauf numeric; n int := 0;
  n_ohne int := 0; n_lauf int := 0; ohne_text text;   -- Migration 189
BEGIN
  SELECT * INTO k FROM webapp_funktion_kosten f WHERE f.funktion = p_funktion;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', true, 'sichtbar', true, 'bekannt', false); END IF;
  IF coalesce(array_length(k.ki_schluessel, 1), 0) = 0 THEN
    RETURN jsonb_build_object('ok', true, 'sichtbar', true, 'bekannt', true, 'ki', false, 'monat_eur', 0, 'je_lauf_eur', 0,
      'text', '0,00 € (keine KI)', 'hinweis', k.hinweis);
  END IF;
  SELECT v.usd_eur INTO kurs FROM plattform_vertrag v WHERE v.id = 1;
  SELECT coalesce(sum(x.kosten_usd * x.preis_faktor), 0) * coalesce(kurs, 1), count(*), count(*) FILTER (WHERE x.kosten_usd IS NULL) INTO monat, n, n_ohne
    FROM ki_verbrauch x
   WHERE x.funktion = ANY (k.ki_schluessel)
     AND (cardinality(k.nur_workflows) = 0 OR coalesce(x.workflow, '') LIKE ANY (k.nur_workflows))
     AND NOT (coalesce(x.workflow, '') LIKE ANY (k.ohne_workflows))
     AND x.zeit >= date_trunc('month', now() AT TIME ZONE 'Europe/Berlin') AT TIME ZONE 'Europe/Berlin';
  SELECT avg(y.kosten_usd * y.preis_faktor) * coalesce(kurs, 1), count(*) INTO lauf, n_lauf
    FROM (SELECT x.kosten_usd, x.preis_faktor FROM ki_verbrauch x
           WHERE x.funktion = ANY (k.ki_schluessel)
             AND (cardinality(k.nur_workflows) = 0 OR coalesce(x.workflow, '') LIKE ANY (k.nur_workflows))
             AND NOT (coalesce(x.workflow, '') LIKE ANY (k.ohne_workflows))
           ORDER BY x.zeit DESC LIMIT 20) y;
  -- Migration 189 (Plan 51): Buchungen ohne Preis – nur solche: „unbekannt“ statt 0,00 € (vor dem Text steht in der Oberfläche schon „Kosten“);
  -- mit bekannten zusammen: bekannter Betrag und „dazu N Aufrufe ohne Preis (Kosten unbekannt)“. „je Lauf“ aus den letzten 20 mit Preis; alle 20 ohne: unbekannt.
  ohne_text := n_ohne::text || CASE WHEN n_ohne = 1 THEN ' Aufruf' ELSE ' Aufrufe' END || ' ohne Preis';
  RETURN jsonb_build_object('ok', true, 'sichtbar', true, 'bekannt', true, 'ki', true,
    'monat_eur', round(monat, 2), 'je_lauf_eur', CASE WHEN lauf IS NULL THEN NULL ELSE round(lauf, 2) END, 'buchungen_monat', n,
    'ohne_preis_monat', n_ohne, 'monat_unbekannt', n > 0 AND n_ohne = n,
    'text', 'diesen Monat: ' || CASE WHEN n > 0 AND n_ohne = n THEN 'unbekannt (' || ohne_text || ')'
        ELSE replace(to_char(round(monat, 2), 'FM999990D00'), '.', ',') || ' €' || CASE WHEN n_ohne > 0 THEN ' · dazu ' || ohne_text || ' (Kosten unbekannt)' ELSE '' END END
      || CASE WHEN lauf IS NULL THEN CASE WHEN n_lauf > 0 THEN ' · je Lauf: unbekannt' ELSE '' END ELSE ' · je Lauf ca. ' || replace(to_char(round(lauf, 2), 'FM999990D00'), '.', ',') || ' €' END,
    'hinweis', k.hinweis);
END $function$
;

CREATE OR REPLACE FUNCTION public.webapp_kosten_web(p_token text, p_funktion text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
BEGIN
  -- Migration 127: gleiche Ausgabe wie Migration 121; Rechnung in webapp_kosten_rechnen (mit Workflow-Mustern)
  SELECT * INTO s FROM ally_ui_sitzung(p_token);
  IF NOT FOUND OR s.muss_pw_setzen THEN RETURN jsonb_build_object('ok', false); END IF;
  IF NOT coalesce(ally_ui_funktion_erlaubt(s.person, s.rolle, 'ki-verbrauch'), false) THEN
    RETURN jsonb_build_object('ok', true, 'sichtbar', false);
  END IF;
  RETURN webapp_kosten_rechnen(p_funktion);
END $function$
;

CREATE OR REPLACE FUNCTION public.webapp_meine_postfaecher_web(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; w jsonb; pfe boolean; pv jsonb; li jsonb;
BEGIN
  SELECT * INTO s FROM ally_ui_sitzung(p_token) y WHERE NOT y.muss_pw_setzen;
  IF NOT FOUND OR s.person IS NULL THEN RETURN jsonb_build_object('ok', false); END IF;
  pfe := coalesce(ally_hat_recht(s.person, 'postfaecher_eigene'), false);
  w := coalesce(ally_web_daten(s.person), '{}'::jsonb);
  pv := coalesce(postfach_versand_web(p_token)->'plaetze', '[]'::jsonb);
  SELECT coalesce(jsonb_agg(jsonb_build_object('platz', p->'platz', 'adresse', p->'adresse', 'name', p->'name', 'aktiv', p->'aktiv',
      'lesen', p->'zugang'->'ergebnis', 'geprueft', p->'zugang'->'geprueft',
      'versand', (SELECT jsonb_build_object('bereit', v->'bereit', 'eingerichtet', v->'eingerichtet', 'erlaubt', v->'erlaubt', 'host', v->'host')
                  FROM jsonb_array_elements(pv) v WHERE lower(v->>'adresse') = lower(p->>'adresse') LIMIT 1))
      ORDER BY lower(p->>'adresse')), '[]'::jsonb)
    INTO li FROM jsonb_array_elements(coalesce(w->'postfaecher', '[]'::jsonb)) p
   WHERE p->>'art' = 'persoenlich' AND coalesce((p->>'eigen')::boolean, false) AND (p->>'platz') ~ '^[0-9]{1,9}$';  -- Migration 173 (Schritt P, P3): Nummer ohne Grenze
  RETURN jsonb_build_object('ok', true, 'recht', pfe, 'live', coalesce((w->>'plaetze_live')::boolean, false),
    'frei', CASE WHEN pfe THEN coalesce(w->'plaetze_frei', '[]'::jsonb) END, 'liste', li,
    -- Migration 170 (Schritt P): Kennzeichen Höchstzahl erreicht
    'hoechstzahl_erreicht', CASE WHEN pfe THEN w->'postfaecher_hoechstzahl_erreicht' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.webapp_postfach_web(p_token text, p_adresse text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record; w jsonb; p jsonb; v jsonb; adm boolean; pfr boolean; rs jsonb; pl int;
BEGIN
  SELECT * INTO s FROM ally_ui_sitzung(p_token) y WHERE NOT y.muss_pw_setzen;
  IF NOT FOUND OR s.person IS NULL OR coalesce(p_adresse, '') = '' THEN RETURN jsonb_build_object('ok', false); END IF;
  adm := coalesce(ally_hat_recht(s.person, 'admin'), false);
  pfr := coalesce(ally_hat_recht(s.person, 'postfaecher'), false);
  w := coalesce(ally_web_daten(s.person), '{}'::jsonb);
  SELECT x INTO p FROM jsonb_array_elements(coalesce(w->'postfaecher', '[]'::jsonb)) x
   WHERE lower(x->>'adresse') = lower(p_adresse) AND (x->>'platz') ~ '^[0-9]{1,9}$'
     AND ((x->>'art' = 'gemeinsam' AND coalesce((x->>'verwalten')::boolean, false)) OR (x->>'art' = 'persoenlich' AND coalesce((x->>'eigen')::boolean, false)))
   LIMIT 1;
  IF p IS NULL THEN RETURN jsonb_build_object('ok', false, 'fehlt', true); END IF;
  pl := (p->>'platz')::int;
  SELECT x INTO v FROM jsonb_array_elements(coalesce(postfach_versand_web(p_token)->'plaetze', '[]'::jsonb)) x WHERE lower(x->>'adresse') = lower(p->>'adresse') LIMIT 1;
  IF p->>'art' = 'gemeinsam' AND pfr THEN
    SELECT coalesce(jsonb_agg(ro.name ORDER BY lower(ro.name)), '[]'::jsonb) INTO rs
      FROM ally_rollen_rechte rr JOIN ally_rollen ro ON ro.schluessel = rr.rolle AND ro.art = 'eigen' AND ro.archiviert_am IS NULL
     WHERE rr.recht = ally_postfach_recht(pl);
  END IF;
  RETURN jsonb_build_object('ok', true, 'admin', adm, 'live', coalesce((w->>'plaetze_live')::boolean, false),
    'postfach', jsonb_build_object('platz', pl, 'art', p->'art', 'adresse', p->'adresse', 'name', p->'name', 'aktiv', p->'aktiv', 'belege_erfassen', p->'belege_erfassen',
      'unternehmen_id', p->'unternehmen_id', 'schrift', p->'schrift', 'schrift_groesse', p->'schrift_groesse', 'signatur_html', p->'signatur_html',
      'entwurf_ordner', p->'entwurf_ordner', 'angebot_bei', p->'angebot_bei', 'eigene_einordnung', p->'eigene_einordnung', 'einordnung', p->'einordnung',
      'personen', jsonb_array_length(coalesce(p->'personen', '[]'::jsonb)),
      'zugang', jsonb_build_object('host', p->'zugang'->'host', 'port', p->'zugang'->'port', 'benutzer', p->'zugang'->'benutzer', 'ssl', p->'zugang'->'ssl',
        'ordner', p->'zugang'->'ordner', 'ergebnis', p->'zugang'->'ergebnis', 'geprueft', p->'zugang'->'geprueft')),
    'versand', CASE WHEN v IS NULL THEN NULL ELSE jsonb_build_object('bereit', v->'bereit', 'eingerichtet', v->'eingerichtet', 'erlaubt', v->'erlaubt', 'host', v->'host', 'port', v->'port',
      'benutzer', v->'benutzer', 'imap_benutzer', v->'imap_benutzer', 'anders', v->'anders', 'abgeleitet_host', v->'abgeleitet_host', 'ergebnis', v->'ergebnis',
      'geprueft', v->'geprueft', 'berichte', v->'berichte') END,
    'unternehmen', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', u->'id', 'name', u->'name')), '[]'::jsonb) FROM jsonb_array_elements(coalesce(w->'unternehmen', '[]'::jsonb)) u),
    'schriften', coalesce(w->'mail_schriften', '[]'::jsonb),
    'kategorien', coalesce(w->'mail_kategorien', '{}'::jsonb),
    'rollen', rs);
END $function$
;

CREATE OR REPLACE FUNCTION public.zahlwort(p_n bigint)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE
  -- Migration 173: Zahl als deutsches Zahlwort in Kleinbuchstaben, ohne Leer- und Sonderzeichen (ä/ö/ü/ß als ae/oe/ue/ss), für Schlüssel ohne Ziffern
  -- (Rechte postfach_<zahlwort>, wie postfach_eins … postfach_zehn). Für jede Zahl ab 1, ohne Obergrenze (bigint).
  e text[] := ARRAY['eins', 'zwei', 'drei', 'vier', 'fuenf', 'sechs', 'sieben', 'acht', 'neun', 'zehn', 'elf', 'zwoelf', 'dreizehn', 'vierzehn', 'fuenfzehn',
                    'sechzehn', 'siebzehn', 'achtzehn', 'neunzehn'];
  z text[] := ARRAY['', 'zwanzig', 'dreissig', 'vierzig', 'fuenfzig', 'sechzig', 'siebzig', 'achtzig', 'neunzig'];
  gross text[] := ARRAY['million', 'milliarde', 'billion', 'billiarde', 'trillion'];
  grossmz text[] := ARRAY['millionen', 'milliarden', 'billionen', 'billiarden', 'trillionen'];
  r text := ''; teil bigint; rest bigint := p_n; stufe integer := 0; w text; g bigint;
BEGIN
  IF p_n < 1 THEN RAISE EXCEPTION 'zahlwort: nur Zahlen ab 1'; END IF;
  -- von unten nach oben in Dreiergruppen
  WHILE rest > 0 LOOP
    teil := rest % 1000; rest := rest / 1000;
    IF teil > 0 THEN
      -- unter 1000
      g := teil / 100; w := '';
      IF g > 0 THEN w := CASE WHEN g = 1 THEN 'ein' ELSE e[g] END || 'hundert'; END IF;
      g := teil % 100;
      IF g > 0 AND g < 20 THEN w := w || e[g];
      ELSIF g >= 20 THEN w := w || CASE WHEN g % 10 = 0 THEN '' ELSE CASE WHEN g % 10 = 1 THEN 'ein' ELSE e[(g % 10)::int] END || 'und' END || z[(g / 10)::int];
      END IF;
      IF stufe = 1 THEN
        w := regexp_replace(w, 'eins$', 'ein') || 'tausend';
      ELSIF stufe >= 2 THEN
        w := CASE WHEN teil = 1 THEN 'eine' || gross[stufe - 1] ELSE regexp_replace(w, 'eins$', 'ein') || grossmz[stufe - 1] END;
      END IF;
      r := w || r;
    END IF;
    stufe := stufe + 1;
  END LOOP;
  RETURN r;
END $function$
;

