ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_art_check CHECK ((art = 'manager'::text));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_empfaenger_check CHECK ((empfaenger = ANY (ARRAY['zustaendige'::text, 'personen'::text])));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_intervall_check CHECK ((intervall = ANY (ARRAY['aus'::text, 'tag'::text, 'woche'::text, 'monat'::text])));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_mail_betreff_check CHECK (((mail_betreff IS NULL) OR (length(mail_betreff) <= 200)));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_mail_html_check CHECK (((mail_html IS NULL) OR (length(mail_html) <= 20000)));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_name_check CHECK (((btrim(name) <> ''::text) AND (length(name) <= 80)));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_personen_check CHECK ((cardinality(personen) <= 20));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_signatur_html_check CHECK (((signatur_html IS NULL) OR (length(signatur_html) <= 20000)));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_tag_check CHECK (tag BETWEEN 1 AND 28 AND (intervall <> 'woche' OR tag <= 7));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_talents_check CHECK ((cardinality(talents) <= 50));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_uhrzeit_check CHECK ((uhrzeit ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'::text));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_versand_check CHECK ((versand = ANY (ARRAY['ally'::text, 'chat'::text, 'mail'::text])));

ALTER TABLE ONLY public.talents_briefings ADD CONSTRAINT talents_briefings_zeitraum_check CHECK ((zeitraum = ANY (ARRAY['letzte_7_tage'::text, 'letzte_30_tage'::text, 'vormonat'::text])));

