CREATE VIEW public.ally_berechtigungen AS
 SELECT id,
    matrix_user_id,
    name AS anzeigename,
    aktiv,
    erstellt_am
   FROM ally_personen p
  WHERE (NOT ally_rolle_ist_talent(rolle));

CREATE VIEW public.ally_nutzer AS
 SELECT p.matrix_user_id,
    p.name AS anzeigename,
    r.room_id
   FROM (ally_personen p
     LEFT JOIN matrix_direct_rooms r ON ((r.matrix_user_id = p.matrix_user_id)))
  WHERE (p.aktiv AND (NOT ally_rolle_ist_talent(p.rolle)));

CREATE VIEW public.ally_nutzer_postfaecher AS
 SELECT x.matrix_user_id,
    p.adresse AS postfach
   FROM (ally_personen x
     CROSS JOIN ally_postfaecher p)
  WHERE (x.aktiv AND ally_postfach_zustaendig(x.matrix_user_id, p.adresse));
